'use client';

import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { supabase } from '@/lib/supabaseClient';
import { getErrorMessage } from '@/lib/errorUtils';
import { trackEvent } from '@/lib/analytics';
import {
  BACKUP_TABLE_CONFIG,
  exportBackup,
  restoreBackup,
  isValidBackupFile,
  type BackupData,
  type BackupTableKey,
  type RestoreMode,
} from '@/lib/services/backupService';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** All table keys checked/selected by default — a "full backup" out of the box. */
const ALL_KEYS: BackupTableKey[] = BACKUP_TABLE_CONFIG.map((cfg) => cfg.key);

function allChecked(keys: BackupTableKey[] = ALL_KEYS): Record<BackupTableKey, boolean> {
  return Object.fromEntries(ALL_KEYS.map((key) => [key, keys.includes(key)])) as Record<BackupTableKey, boolean>;
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function BackupPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();

  // Export checkboxes — every table selected by default (a "full backup").
  const [exportSelected, setExportSelected] = useState<Record<BackupTableKey, boolean>>(() => allChecked());
  const [isExporting, setIsExporting] = useState(false);

  // Import state
  const [backupFile,     setBackupFile]     = useState<BackupData | null>(null);
  const [backupFileName, setBackupFileName] = useState('');
  const [restoreMode,    setRestoreMode]    = useState<RestoreMode>('merge');
  const [restoreConfirm, setRestoreConfirm] = useState(false);
  const [isRestoring,    setIsRestoring]    = useState(false);

  // Per-table restore toggles — set from the uploaded backup file's contents.
  const [restoreSelected, setRestoreSelected] = useState<Record<BackupTableKey, boolean>>(() => allChecked([]));

  const [error,     setError]     = useState<string | null>(null);
  const [success,   setSuccess]   = useState<string | null>(null);
  const [statusLog, setStatusLog] = useState<string[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isUserLoading) return;
    if (!user)    { router.push('/login'); return; }
    if (!isAdmin) { router.push('/admin'); return; }
  }, [isUserLoading, user, isAdmin, router]);

  const addLog = (msg: string) => setStatusLog(prev => [...prev, msg]);

  // ── Export ─────────────────────────────────────────────────────────────────

  const selectedExportKeys = ALL_KEYS.filter((key) => exportSelected[key]);

  const handleExport = async () => {
    if (selectedExportKeys.length === 0) {
      setError('Please select at least one table to include in the backup.');
      return;
    }

    setIsExporting(true);
    setError(null);
    setSuccess(null);
    setStatusLog([]);

    try {
      const backup = await exportBackup(supabase, selectedExportKeys, addLog);

      // Trigger browser download
      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement('a');
      a.href     = url;
      a.download = `campaign-backup-${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      addLog('✅ Backup downloaded successfully.');
      setSuccess('Backup downloaded.');
      trackEvent('backup_export', { tables: selectedExportKeys });
    } catch (err) {
      setError(getErrorMessage(err, 'Export failed'));
    } finally {
      setIsExporting(false);
    }
  };

  // ── Import ─────────────────────────────────────────────────────────────────

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    setError(null);
    setSuccess(null);
    setStatusLog([]);
    setBackupFile(null);
    setRestoreConfirm(false);

    const file = e.target.files?.[0];
    if (!file) return;
    setBackupFileName(file.name);

    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const parsed = JSON.parse(ev.target?.result as string) as unknown;
        if (!isValidBackupFile(parsed)) {
          throw new Error('Not a valid backup file — missing exported_at or version.');
        }
        setBackupFile(parsed);
        // Default: restore only tables present in the file
        setRestoreSelected(allChecked(ALL_KEYS.filter((key) => !!parsed[key])));
      } catch (err) {
        setError(getErrorMessage(err, 'Failed to parse backup file'));
      }
    };
    reader.readAsText(file);
  };

  const selectedRestoreKeys = ALL_KEYS.filter((key) => restoreSelected[key] && !!backupFile?.[key]);

  const handleRestore = async () => {
    if (!backupFile) return;

    setIsRestoring(true);
    setError(null);
    setSuccess(null);
    setStatusLog([]);
    setRestoreConfirm(false);

    try {
      await restoreBackup(supabase, backupFile, selectedRestoreKeys, restoreMode, addLog);

      addLog('✅ Restore completed successfully.');
      setSuccess('Restore completed successfully.');
      trackEvent('backup_restore', { mode: restoreMode, tables: selectedRestoreKeys });
    } catch (err) {
      setError(getErrorMessage(err, 'Restore failed'));
    } finally {
      setIsRestoring(false);
    }
  };

  // ── Render ─────────────────────────────────────────────────────────────────

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="mx-auto max-w-2xl p-4">

        <div className="mb-6">
          <Link
            href="/admin"
            className="text-sm text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
          >
            ← Back to Admin Panel
          </Link>
        </div>

        <h1 className="mb-2 text-2xl font-bold text-gray-900 dark:text-gray-100">
          Backup &amp; Restore
        </h1>

        <div className="mb-6 rounded-md border border-gray-200 bg-gray-50 px-4 py-3 text-sm text-gray-600 dark:border-gray-600 dark:bg-gray-700/50 dark:text-gray-400">
          <p className="font-medium text-gray-800 dark:text-gray-200">
            This isn&apos;t the only backup — there&apos;s also an automatic one.
          </p>
          <p className="mt-1">
            A full database backup (every table, not just the ones below) runs automatically every{' '}
            <strong>Saturday at 23:00 UTC</strong> — timed to land before Sunday&apos;s Weekly Refresh
            job, so it captures a pre-refresh snapshot. It&apos;s pushed to a private GitHub repo, not
            this app. See <code className="rounded bg-gray-200 px-1 py-0.5 text-xs dark:bg-gray-600">scripts/BACKUP_RESTORE.md</code> for
            restore instructions.
          </p>
          <p className="mt-1">
            Use the tools below for on-demand, per-table snapshots or restores — the automatic backup
            is for full disaster recovery.
          </p>
        </div>

        {error && (
          <div className="mb-4 rounded-md bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-200">
            {error}
          </div>
        )}
        {success && (
          <div className="mb-4 rounded-md bg-green-50 border border-green-200 px-4 py-3 text-sm text-green-800 dark:bg-green-900/20 dark:border-green-800 dark:text-green-200">
            {success}
          </div>
        )}

        {/* ── Export ── */}
        <div className="mb-6 rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white p-5 shadow-sm dark:bg-gray-800">
          <h2 className="mb-1 text-lg font-semibold text-gray-900 dark:text-gray-100">
            Export Backup
          </h2>
          <p className="mb-4 text-sm text-gray-600 dark:text-gray-400">
            Download a JSON snapshot of the selected tables. Keep the file somewhere safe so you
            can restore from it if needed. Every table is included by default for a full backup.
          </p>

          <fieldset className="mb-4 space-y-2">
            <legend className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
              Tables to include
            </legend>
            {BACKUP_TABLE_CONFIG.map(({ key, label }) => (
              <label key={key} className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={exportSelected[key]}
                  onChange={(e) => setExportSelected((prev) => ({ ...prev, [key]: e.target.checked }))}
                  className="h-4 w-4 rounded border-gray-300"
                />
                <span className="text-sm text-gray-700 dark:text-gray-300">{label}</span>
              </label>
            ))}
          </fieldset>

          <button
            onClick={handleExport}
            disabled={isExporting}
            className="rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 border-2 border-gray-800 dark:border-gray-600"
          >
            {isExporting ? 'Exporting…' : '⬇ Download Backup'}
          </button>
        </div>

        {/* ── Import ── */}
        <div className="rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white p-5 shadow-sm dark:bg-gray-800">
          <h2 className="mb-1 text-lg font-semibold text-gray-900 dark:text-gray-100">
            Restore from Backup
          </h2>
          <p className="mb-4 text-sm text-gray-600 dark:text-gray-400">
            Upload a previously downloaded backup file to restore records.
          </p>

          <div className="mb-4">
            <label className="mb-1 block text-sm font-medium text-gray-700 dark:text-gray-300">
              Select backup file (.json)
            </label>
            <input
              ref={fileInputRef}
              type="file"
              accept=".json,application/json"
              onChange={handleFileSelect}
              className="block w-full text-sm text-gray-700 dark:text-gray-300
                file:mr-3 file:rounded-md file:border-2 file:border-gray-800
                file:bg-gray-100 file:px-3 file:py-1.5 file:text-sm file:font-bold
                file:text-gray-700 hover:file:bg-gray-200
                dark:file:border-gray-600 dark:file:bg-gray-700 dark:file:text-gray-300"
            />
          </div>

          {backupFile && (
            <>
              {/* Backup summary card */}
              <div className="mb-5 rounded-md bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 p-3 text-sm">
                <p className="font-semibold text-blue-800 dark:text-blue-300 mb-1">
                  📦 {backupFileName}
                </p>
                <p className="text-xs text-blue-600 dark:text-blue-400 mb-2">
                  Exported: {new Date(backupFile.exported_at).toLocaleString('en-AU')}
                </p>
                <ul className="space-y-0.5 text-blue-700 dark:text-blue-400">
                  {BACKUP_TABLE_CONFIG.map(({ key, label }) => {
                    const rows = backupFile[key];
                    if (!rows) return null;
                    return <li key={key}>• {rows.length.toLocaleString()} {label.toLowerCase()}</li>;
                  })}
                </ul>
              </div>

              {/* Tables to restore */}
              <fieldset className="mb-5 space-y-2">
                <legend className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Tables to restore
                </legend>
                {BACKUP_TABLE_CONFIG.map(({ key, label }) => {
                  const available = !!backupFile[key];
                  return (
                    <label
                      key={key}
                      className={`flex items-center gap-2 ${available ? 'cursor-pointer' : 'cursor-not-allowed opacity-40'}`}
                    >
                      <input
                        type="checkbox"
                        checked={restoreSelected[key] && available}
                        disabled={!available}
                        onChange={(e) => setRestoreSelected((prev) => ({ ...prev, [key]: e.target.checked }))}
                        className="h-4 w-4 rounded border-gray-300"
                      />
                      <span className="text-sm text-gray-700 dark:text-gray-300">
                        {label}
                        {!available && (
                          <span className="ml-1 text-xs text-gray-400">(not in this backup)</span>
                        )}
                      </span>
                    </label>
                  );
                })}
              </fieldset>

              {/* Restore mode */}
              <fieldset className="mb-5">
                <legend className="mb-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                  Restore mode
                </legend>
                <div className="space-y-3">
                  <label className="flex items-start gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="restoreMode"
                      value="merge"
                      checked={restoreMode === 'merge'}
                      onChange={() => setRestoreMode('merge')}
                      className="mt-0.5 h-4 w-4 border-gray-300"
                    />
                    <span className="text-sm text-gray-700 dark:text-gray-300">
                      <span className="font-semibold">Merge</span>
                      <span className="text-gray-500 dark:text-gray-400">
                        {' '}— adds and updates records from the backup; records that exist now
                        but are not in the backup are left untouched
                      </span>
                    </span>
                  </label>
                  <label className="flex items-start gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="restoreMode"
                      value="replace"
                      checked={restoreMode === 'replace'}
                      onChange={() => { setRestoreMode('replace'); setRestoreConfirm(false); }}
                      className="mt-0.5 h-4 w-4 border-gray-300"
                    />
                    <span className="text-sm text-gray-700 dark:text-gray-300">
                      <span className="font-semibold">Replace</span>
                      <span className="text-gray-500 dark:text-gray-400">
                        {' '}— deletes all current records in the selected tables, then restores
                        from backup exactly; use this to fully undo corruption. Replacing
                        Campaigns without also replacing Results (or vice versa) can fail, since
                        each result row references a campaign — select both together, or use
                        Merge instead.
                      </span>
                    </span>
                  </label>
                </div>
              </fieldset>

              {/* Replace confirmation */}
              {restoreMode === 'replace' && (
                <div className="mb-5 rounded-md bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 p-3">
                  <label className="flex items-start gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={restoreConfirm}
                      onChange={(e) => setRestoreConfirm(e.target.checked)}
                      className="mt-0.5 h-4 w-4 rounded border-gray-300"
                    />
                    <span className="text-sm font-medium text-red-800 dark:text-red-300">
                      I understand this will permanently delete all current records in the selected
                      tables and replace them with the backup data. This cannot be undone.
                    </span>
                  </label>
                </div>
              )}

              <button
                onClick={handleRestore}
                disabled={isRestoring || selectedRestoreKeys.length === 0 || (restoreMode === 'replace' && !restoreConfirm)}
                className="rounded-md bg-green-600 px-4 py-2 text-base font-bold text-white hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 border-2 border-gray-800 dark:border-gray-600"
              >
                {isRestoring ? 'Restoring…' : '⬆ Restore Backup'}
              </button>
            </>
          )}
        </div>

        {/* Status log */}
        {statusLog.length > 0 && (
          <div className="mt-4 rounded-md bg-gray-900 p-4 font-mono text-sm text-green-400">
            {statusLog.map((line, i) => (
              <div key={i}>{line}</div>
            ))}
          </div>
        )}

      </div>
    </MobileLayout>
  );
}

app/admin/campaign-categories/page.tsx:
'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { supabase } from '@/lib/supabaseClient';
import { getErrorMessage } from '@/lib/errorUtils';

interface CampaignCategory {
  id: string;
  code: string;
  name: string;
  created_at: string;
}

export default function CampaignCategoriesPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const [hasAccess, setHasAccess] = useState(false);
  const [categories, setCategories] = useState<CampaignCategory[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Form state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formState, setFormState] = useState({ code: '', name: '' });

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      setError('You do not have permission to access this page');
      return;
    }
    setHasAccess(true);
  }, [isUserLoading, user, isAdmin, router]);

  const fetchCategories = useCallback(async () => {
    try {
      const { data, error: fetchError } = await supabase
        .from('campaign_categories')
        .select('*')
        .order('code', { ascending: true });

      if (fetchError) throw fetchError;
      setCategories(data || []);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to fetch campaign categories'));
    }
  }, []);

  useEffect(() => {
    if (hasAccess) fetchCategories();
  }, [hasAccess, fetchCategories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    setIsSubmitting(true);

    const code = formState.code.trim().toUpperCase();
    const name = formState.name.trim();

    try {
      if (editingId) {
        const { error: updateError } = await supabase
          .from('campaign_categories')
          .update({ code, name })
          .eq('id', editingId);

        if (updateError) throw updateError;
        setSuccess('Category updated successfully');
      } else {
        const { error: insertError } = await supabase
          .from('campaign_categories')
          .insert([{ code, name }]);

        if (insertError) {
          if (insertError.code === '23505') {
            throw new Error(`Category code '${code}' already exists`);
          }
          throw insertError;
        }
        setSuccess('Category created successfully');
      }

      setFormState({ code: '', name: '' });
      setEditingId(null);
      await fetchCategories();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to save category'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEdit = (item: CampaignCategory) => {
    setEditingId(item.id);
    setFormState({ code: item.code, name: item.name });
    setError(null);
    setSuccess(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string, code: string) => {
    if (!confirm(`Are you sure you want to delete the '${code}' category? This will fail if any campaigns are using it.`)) {
      return;
    }

    try {
      const { error: deleteError } = await supabase
        .from('campaign_categories')
        .delete()
        .eq('id', id);

      if (deleteError) throw deleteError;
      setSuccess('Category deleted successfully');
      await fetchCategories();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to delete category'));
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setFormState({ code: '', name: '' });
    setError(null);
    setSuccess(null);
  };

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">
              Access Denied
            </h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {error || 'You do not have permission to access this page.'}
            </p>
            <button
              onClick={() => router.push('/admin')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="mb-6">
          <button
            onClick={() => router.push('/admin')}
            className="mb-4 text-sm text-blue-600 hover:text-blue-700 dark:text-blue-400"
          >
            ← Back to Admin Panel
          </button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
            Campaign Categories
          </h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Manage the campaign category list. Categories are used in forms and slide generation.
          </p>
        </div>

        {/* Success/Error Messages */}
        {success && (
          <div className="mb-4 rounded-md border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-800 dark:border-green-800 dark:bg-green-900/20 dark:text-green-200">
            {success}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-md border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {error}
          </div>
        )}

        {/* Add/Edit Form */}
        <div className="mb-6 rounded-lg border border-gray-200 bg-blue-50 p-4 shadow-sm dark:border-gray-700 dark:bg-blue-900/20">
          <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-gray-100">
            {editingId ? 'Edit Category' : 'Add New Category'}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="code" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Code
              </label>
              <input
                id="code"
                type="text"
                required
                value={formState.code}
                onChange={(e) => setFormState({ ...formState, code: e.target.value.toUpperCase() })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="e.g. TWOL"
                maxLength={10}
              />
              <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                Short uppercase code used in campaign data (e.g. TWOL, BOTJ, TLT)
              </p>
            </div>
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Name
              </label>
              <input
                id="name"
                type="text"
                required
                value={formState.name}
                onChange={(e) => setFormState({ ...formState, name: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="e.g. Two Weekly"
              />
              <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                Full descriptive name shown in dropdowns
              </p>
            </div>
            <div className="flex gap-2">
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex-1 rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
              >
                {isSubmitting ? 'Saving...' : editingId ? 'Update' : 'Add'}
              </button>
              {editingId && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-md bg-gray-200 px-4 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
                >
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>

        {/* Category List */}
        <div className="rounded-lg border-2 border-gray-800 bg-white shadow-sm dark:border-gray-600 dark:bg-gray-800">
          <div className="p-4">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              Categories ({categories.length})
            </h2>
          </div>
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {categories.length === 0 ? (
              <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
                No categories found
              </div>
            ) : (
              categories.map((item) => (
                <div key={item.id} className="p-4">
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="font-bold text-gray-900 dark:text-gray-100">
                        {item.code}
                      </div>
                      <div className="text-sm text-gray-600 dark:text-gray-400">
                        {item.name}
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleEdit(item)}
                        className="rounded-md bg-blue-100 px-3 py-1 text-sm font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:hover:bg-blue-900/50"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleDelete(item.id, item.code)}
                        className="rounded-md bg-red-100 px-3 py-1 text-base font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-300 dark:hover:bg-red-900/50 border-2 border-gray-800 dark:border-gray-600"
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </MobileLayout>
  );
}

app/admin/campaign-logs/page.tsx:
'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { supabase } from '@/lib/supabaseClient';
import { getErrorMessage } from '@/lib/errorUtils';
import type { Campaign } from '@/lib/types';

interface CampaignLog {
  id: string;
  campaign_id: string | null;
  user_id: string | null;
  change_type: 'INSERT' | 'UPDATE' | 'DELETE';
  old_data: Partial<Campaign> | null;
  new_data: Partial<Campaign> | null;
  changed_fields: string[] | null;
  user_email: string | null;
  user_name: string | null;
  created_at: string;
}

const PAGE_SIZE = 50;

export default function CampaignLogsPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const [hasAccess, setHasAccess] = useState(false);
  const [logs, setLogs] = useState<CampaignLog[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [error, setError] = useState<string | null>(null);
  const [expandedLogs, setExpandedLogs] = useState<Set<string>>(new Set());

  // Search and filter state
  const [searchUser, setSearchUser] = useState('');
  const [filterChangeType, setFilterChangeType] = useState<string>('');
  const [filterDateFrom, setFilterDateFrom] = useState('');
  const [filterDateTo, setFilterDateTo] = useState('');
  const [searchCampaignId, setSearchCampaignId] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  const fetchLogs = useCallback(async (page = 1) => {
    setIsSearching(true);
    setError(null);

    const from = (page - 1) * PAGE_SIZE;
    const to = from + PAGE_SIZE - 1;

    try {
      let query = supabase
        .from('campaign_changes_log')
        .select('*', { count: 'exact' })
        .order('created_at', { ascending: false })
        .range(from, to);

      if (filterChangeType) {
        query = query.eq('change_type', filterChangeType);
      }
      if (filterDateFrom) {
        query = query.gte('created_at', filterDateFrom + 'T00:00:00');
      }
      if (filterDateTo) {
        query = query.lte('created_at', filterDateTo + 'T23:59:59');
      }
      if (searchCampaignId.trim()) {
        query = query.eq('campaign_id', searchCampaignId.trim());
      }

      const { data, count, error: fetchError } = await query;
      if (fetchError) throw fetchError;

      // User search is applied in-memory (name/email not indexed for full-text)
      let filteredData = data ?? [];
      if (searchUser.trim()) {
        const term = searchUser.trim().toLowerCase();
        filteredData = filteredData.filter(
          (log) =>
            log.user_name?.toLowerCase().includes(term) ||
            log.user_email?.toLowerCase().includes(term)
        );
      }

      setLogs(filteredData);
      setTotalCount(count ?? 0);
      setCurrentPage(page);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to fetch logs'));
    } finally {
      setIsSearching(false);
    }
  }, [filterChangeType, filterDateFrom, filterDateTo, searchCampaignId, searchUser]);

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      setError('You do not have permission to access this page');
      return;
    }
    setHasAccess(true);
    fetchLogs(1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isUserLoading, user, isAdmin, router]);

  const handleSearch = () => {
    fetchLogs(1);
  };

  const handleClearFilters = async () => {
    setSearchUser('');
    setFilterChangeType('');
    setFilterDateFrom('');
    setFilterDateTo('');
    setSearchCampaignId('');
    setIsSearching(true);
    setError(null);
    try {
      const { data, count, error: fetchError } = await supabase
        .from('campaign_changes_log')
        .select('*', { count: 'exact' })
        .order('created_at', { ascending: false })
        .range(0, PAGE_SIZE - 1);
      if (fetchError) throw fetchError;
      setLogs(data ?? []);
      setTotalCount(count ?? 0);
      setCurrentPage(1);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to fetch logs'));
    } finally {
      setIsSearching(false);
    }
  };

  const toggleExpand = (logId: string) => {
    setExpandedLogs((prev) => {
      const next = new Set(prev);
      if (next.has(logId)) next.delete(logId);
      else next.add(logId);
      return next;
    });
  };

  const formatDateTime = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleString('en-AU', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  const getChangeTypeColor = (changeType: string) => {
    switch (changeType) {
      case 'INSERT':
        return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300';
      case 'UPDATE':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300';
      case 'DELETE':
        return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
    }
  };

  const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));
  const firstItem = totalCount === 0 ? 0 : (currentPage - 1) * PAGE_SIZE + 1;
  const lastItem = Math.min(currentPage * PAGE_SIZE, totalCount);

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">
              Access Denied
            </h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {error || 'You do not have permission to access this page.'}
            </p>
            <button
              onClick={() => router.push('/admin')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                Campaign Change Logs
              </h1>
              <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                View and search all campaign change records
              </p>
            </div>
            <button
              onClick={() => router.push('/admin')}
              className="rounded-md bg-gray-200 px-3 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
            >
              Back
            </button>
          </div>
        </div>

        {error && (
          <div className="mb-4 rounded-md bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-200">
            {error}
          </div>
        )}

        {/* Search and Filter Section */}
        <div className="mb-6 rounded-lg border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
            Search & Filters
          </h2>

          <div className="space-y-4">
            {/* User Search */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                User (Name or Email)
              </label>
              <input
                type="text"
                value={searchUser}
                onChange={(e) => setSearchUser(e.target.value)}
                placeholder="Search by user name or email..."
                className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
              />
            </div>

            {/* Filters Row */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Change Type
                </label>
                <select
                  value={filterChangeType}
                  onChange={(e) => setFilterChangeType(e.target.value)}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
                >
                  <option value="">All Types</option>
                  <option value="INSERT">Insert</option>
                  <option value="UPDATE">Update</option>
                  <option value="DELETE">Delete</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Campaign ID
                </label>
                <input
                  type="text"
                  value={searchCampaignId}
                  onChange={(e) => setSearchCampaignId(e.target.value)}
                  placeholder="Enter campaign ID..."
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
                />
              </div>
            </div>

            {/* Date Range */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Date From
                </label>
                <input
                  type="date"
                  value={filterDateFrom}
                  onChange={(e) => setFilterDateFrom(e.target.value)}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Date To
                </label>
                <input
                  type="date"
                  value={filterDateTo}
                  onChange={(e) => setFilterDateTo(e.target.value)}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
                />
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-2">
              <button
                onClick={handleSearch}
                disabled={isSearching}
                className="rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:bg-gray-400 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
              >
                {isSearching ? 'Searching...' : 'Search'}
              </button>
              <button
                onClick={handleClearFilters}
                className="rounded-md bg-gray-200 px-4 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
              >
                Clear Filters
              </button>
            </div>
          </div>
        </div>

        {/* Results count + pagination (top) */}
        <div className="mb-4 flex items-center justify-between">
          <p className="text-sm text-gray-600 dark:text-gray-400">
            {totalCount === 0
              ? 'No records found'
              : `Showing ${firstItem}–${lastItem} of ${totalCount} record${totalCount !== 1 ? 's' : ''}`}
          </p>
          {totalPages > 1 && (
            <div className="flex items-center gap-2">
              <button
                onClick={() => fetchLogs(currentPage - 1)}
                disabled={currentPage <= 1 || isSearching}
                className="rounded-md border border-gray-300 bg-white px-3 py-1 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600"
              >
                ← Prev
              </button>
              <span className="text-sm text-gray-700 dark:text-gray-300">
                {currentPage} / {totalPages}
              </span>
              <button
                onClick={() => fetchLogs(currentPage + 1)}
                disabled={currentPage >= totalPages || isSearching}
                className="rounded-md border border-gray-300 bg-white px-3 py-1 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600"
              >
                Next →
              </button>
            </div>
          )}
        </div>

        {/* Logs */}
        {logs.length === 0 ? (
          <div className="rounded-lg border border-gray-200 bg-white p-8 text-center dark:border-gray-700 dark:bg-gray-800">
            <p className="text-gray-500 dark:text-gray-400">
              {isSearching ? 'Searching...' : 'No log records found'}
            </p>
          </div>
        ) : (
          <>
            <div className="space-y-3">
              {logs.map((log) => (
                <div
                  key={log.id}
                  className="rounded-lg border border-gray-200 bg-white shadow-sm dark:border-gray-700 dark:bg-gray-800"
                >
                  <div
                    className="p-4 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700/50"
                    onClick={() => toggleExpand(log.id)}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${getChangeTypeColor(log.change_type)}`}>
                            {log.change_type}
                          </span>
                          <span className="text-sm text-gray-500 dark:text-gray-400">
                            {formatDateTime(log.created_at)}
                          </span>
                        </div>
                        <div className="text-sm text-gray-900 dark:text-gray-100">
                          <div>
                            <span className="font-medium">User:</span>{' '}
                            {log.user_name || log.user_email || 'Unknown'}
                            {log.user_email && log.user_name && ` (${log.user_email})`}
                          </div>
                          {log.campaign_id && (
                            <div className="mt-1">
                              <span className="font-medium">Campaign ID:</span>{' '}
                              <span className="font-mono text-xs">{log.campaign_id}</span>
                            </div>
                          )}
                          {log.change_type === 'UPDATE' && log.changed_fields && log.changed_fields.length > 0 && (
                            <div className="mt-1">
                              <span className="font-medium">Changed Fields:</span>{' '}
                              {log.changed_fields.join(', ')}
                            </div>
                          )}
                        </div>
                      </div>
                      <div className="ml-4">
                        <svg
                          className={`h-5 w-5 text-gray-400 transition-transform ${expandedLogs.has(log.id) ? 'rotate-180' : ''}`}
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                        </svg>
                      </div>
                    </div>
                  </div>

                  {expandedLogs.has(log.id) && (
                    <div className="border-t border-gray-200 bg-gray-50 p-4 dark:border-gray-700 dark:bg-gray-900/50">
                      <div className="space-y-4">
                        {(log.change_type === 'UPDATE' || log.change_type === 'DELETE') && log.old_data && (
                          <div>
                            <h4 className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-2">
                              Previous Values:
                            </h4>
                            <pre className="overflow-x-auto rounded-md bg-white p-3 text-xs text-gray-800 dark:bg-gray-800 dark:text-gray-200 border border-gray-200 dark:border-gray-700">
                              {JSON.stringify(log.old_data, null, 2)}
                            </pre>
                          </div>
                        )}
                        {(log.change_type === 'INSERT' || log.change_type === 'UPDATE') && log.new_data && (
                          <div>
                            <h4 className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-2">
                              {log.change_type === 'INSERT' ? 'New Values:' : 'Updated Values:'}
                            </h4>
                            <pre className="overflow-x-auto rounded-md bg-white p-3 text-xs text-gray-800 dark:bg-gray-800 dark:text-gray-200 border border-gray-200 dark:border-gray-700">
                              {JSON.stringify(log.new_data, null, 2)}
                            </pre>
                          </div>
                        )}
                        <div className="text-xs text-gray-500 dark:text-gray-400">
                          <div>Log ID: <span className="font-mono">{log.id}</span></div>
                          {log.user_id && (
                            <div>User ID: <span className="font-mono">{log.user_id}</span></div>
                          )}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>

            {/* Bottom pagination */}
            {totalPages > 1 && (
              <div className="mt-6 flex items-center justify-between">
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  Showing {firstItem}–{lastItem} of {totalCount} records
                </p>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => fetchLogs(currentPage - 1)}
                    disabled={currentPage <= 1 || isSearching}
                    className="rounded-md border border-gray-300 bg-white px-3 py-1 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600"
                  >
                    ← Prev
                  </button>
                  <span className="text-sm text-gray-700 dark:text-gray-300">
                    {currentPage} / {totalPages}
                  </span>
                  <button
                    onClick={() => fetchLogs(currentPage + 1)}
                    disabled={currentPage >= totalPages || isSearching}
                    className="rounded-md border border-gray-300 bg-white px-3 py-1 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600"
                  >
                    Next →
                  </button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </MobileLayout>
  );
}

app/admin/campaign-messages/page.tsx:
'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { supabase } from '@/lib/supabaseClient';
import { getErrorMessage } from '@/lib/errorUtils';

interface CampaignMessage {
  date: string;
  message: string;
  created_at: string;
  updated_at: string;
}

export default function CampaignMessagesPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const [hasAccess, setHasAccess] = useState(false);
  const [messages, setMessages] = useState<CampaignMessage[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Form state
  const [editingDate, setEditingDate] = useState<string | null>(null);
  const [formState, setFormState] = useState({ date: '', message: '' });

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      setError('You do not have permission to access this page');
      return;
    }
    setHasAccess(true);
    fetchMessages();
  }, [isUserLoading, user, isAdmin, router]);

  const fetchMessages = async () => {
    try {
      const { data, error } = await supabase
        .from('campaign_messages')
        .select('*')
        .order('date', { ascending: false });

      if (error) throw error;
      setMessages(data || []);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to fetch campaign messages'));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    setIsSubmitting(true);

    try {
      if (editingDate) {
        // Update existing record
        const { error } = await supabase
          .from('campaign_messages')
          .update({ 
            message: formState.message,
            updated_at: new Date().toISOString()
          })
          .eq('date', editingDate);

        if (error) throw error;
        setSuccess('Campaign message updated successfully');
      } else {
        // Create new record
        const { error } = await supabase
          .from('campaign_messages')
          .insert([{ 
            date: formState.date, 
            message: formState.message
          }]);

        if (error) {
          if (error.code === '23505') {
            throw new Error('A message already exists for this date');
          }
          throw error;
        }
        setSuccess('Campaign message created successfully');
      }

      // Reset form
      setFormState({ date: '', message: '' });
      setEditingDate(null);
      await fetchMessages();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to save campaign message'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEdit = (item: CampaignMessage) => {
    setEditingDate(item.date);
    setFormState({ 
      date: item.date, 
      message: item.message
    });
    setError(null);
    setSuccess(null);
    // Scroll to form
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (date: string) => {
    if (!confirm('Are you sure you want to delete this campaign message?')) {
      return;
    }

    try {
      const { error } = await supabase
        .from('campaign_messages')
        .delete()
        .eq('date', date);

      if (error) throw error;
      setSuccess('Campaign message deleted successfully');
      await fetchMessages();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to delete campaign message'));
    }
  };

  const handleCancel = () => {
    setEditingDate(null);
    setFormState({ date: '', message: '' });
    setError(null);
    setSuccess(null);
  };

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">
              Access Denied
            </h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {error || 'You do not have permission to access this page.'}
            </p>
            <button
              onClick={() => router.push('/admin')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="p-4 max-w-full overflow-x-hidden">
        <div className="mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-xl sm:text-2xl font-bold text-gray-900 dark:text-gray-100 break-words">
                Campaign Messages
              </h1>
              <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                Add special messages to display on campaign slides for specific dates
              </p>
            </div>
            <button
              onClick={() => router.push('/admin')}
              className="rounded-md bg-gray-200 px-3 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 whitespace-nowrap border-2 border-gray-800 dark:border-gray-600"
            >
              Back
            </button>
          </div>
        </div>

        {/* Success/Error Messages */}
        {success && (
          <div className="mb-4 rounded-md bg-green-50 border border-green-200 px-4 py-3 text-sm text-green-800 dark:bg-green-900/20 dark:border-green-800 dark:text-green-200 break-words">
            {success}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-md bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-200 break-words">
            {error}
          </div>
        )}

        {/* Add/Edit Form */}
        <div className="mb-6 rounded-lg border border-gray-200 bg-blue-50 p-4 shadow-sm dark:border-gray-700 dark:bg-blue-900/20 w-full overflow-hidden">
          <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-gray-100">
            {editingDate ? 'Edit Campaign Message' : 'Add New Campaign Message'}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="date" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Date
              </label>
              <input
                id="date"
                type="date"
                required
                value={formState.date}
                onChange={(e) => setFormState({ ...formState, date: e.target.value })}
                disabled={!!editingDate}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white disabled:opacity-50 disabled:cursor-not-allowed"
              />
            </div>
            <div>
              <label htmlFor="message" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Message
              </label>
              <textarea
                id="message"
                required
                rows={3}
                value={formState.message}
                onChange={(e) => setFormState({ ...formState, message: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="Enter message to display on slides"
              />
              <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                This message will appear as a banner after the campaigns for the selected date.
              </p>
            </div>
            <div className="flex gap-2">
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex-1 rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
              >
                {isSubmitting ? 'Saving...' : editingDate ? 'Update' : 'Add'}
              </button>
              {editingDate && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-md bg-gray-200 px-4 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
                >
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>

        {/* List of Campaign Messages */}
        <div className="rounded-lg border border-gray-200 bg-white shadow-sm dark:border-gray-700 dark:bg-gray-800 w-full overflow-hidden">
          <div className="p-4">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              Campaign Messages ({messages.length})
            </h2>
          </div>
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {messages.length === 0 ? (
              <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
                No campaign messages found
              </div>
            ) : (
              messages.map((item) => (
                <div key={item.date} className="p-4 hover:bg-gray-50 dark:hover:bg-gray-700/50">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="font-medium text-gray-900 dark:text-gray-100">
                        {new Date(item.date).toLocaleDateString('en-AU', { 
                          weekday: 'long', 
                          day: 'numeric', 
                          month: 'long', 
                          year: 'numeric' 
                        })}
                      </div>
                      <div className="mt-1 text-sm text-gray-600 dark:text-gray-400 break-words">
                        {item.message}
                      </div>
                    </div>
                    <div className="flex flex-col sm:flex-row gap-2 flex-shrink-0">
                      <button
                        onClick={() => handleEdit(item)}
                        className="rounded-md bg-blue-100 px-3 py-1 text-base font-bold text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:hover:bg-blue-900/50 whitespace-nowrap border-2 border-gray-800 dark:border-gray-600"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleDelete(item.date)}
                        className="rounded-md bg-red-100 px-3 py-1 text-base font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-300 dark:hover:bg-red-900/50 whitespace-nowrap border-2 border-gray-800 dark:border-gray-600"
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </MobileLayout>
  );
}

app/admin/campaign-report-locations/page:
'use client';

import { useEffect, useMemo, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { fetchUnresolvedLocations, saveLocationMapping } from '@/lib/services/campaignReportLocationsClient';
import type { UnresolvedLocation } from '@/lib/services/campaignReportLocationsService';
import type { StateLocation } from '@/lib/services/stateLocations';
import { sortLocations, type LocationSortColumn, type SortDirection } from '@/lib/campaignReportLocationSort';
import { getErrorMessage } from '@/lib/errorUtils';
import { AUSTRALIAN_STATES } from '@/lib/constants';

const ADD_NEW = '__add_new__';

interface Draft {
  state: string;
  location: string; // a State Places location, '' for state only, or ADD_NEW
  newLocation: string;
}

type SaveState = 'idle' | 'saving' | 'error';

export default function CampaignReportLocationsPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();

  const [hasAccess, setHasAccess] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [spellings, setSpellings] = useState<UnresolvedLocation[]>([]);
  const [stateLocations, setStateLocations] = useState<StateLocation[]>([]);
  const [drafts, setDrafts] = useState<Record<string, Draft>>({});
  const [saveStates, setSaveStates] = useState<Record<string, SaveState>>({});
  const [saveErrors, setSaveErrors] = useState<Record<string, string>>({});
  const [notice, setNotice] = useState<string | null>(null);
  const [sortColumn, setSortColumn] = useState<LocationSortColumn>('records');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      setLoadError('You do not have permission to access this page');
      return;
    }
    setHasAccess(true);
  }, [isUserLoading, user, isAdmin, router]);

  const load = useCallback(async () => {
    setIsLoading(true);
    setLoadError(null);
    try {
      const data = await fetchUnresolvedLocations();
      setSpellings(data.spellings);
      setStateLocations(data.locations);
      const next: Record<string, Draft> = {};
      for (const l of data.spellings) {
        const s = l.suggestions.length === 1 ? l.suggestions[0] : null;
        next[l.key] = { state: s?.state ?? l.knownState ?? '', location: s?.location ?? '', newLocation: '' };
      }
      setDrafts(next);
      setSaveStates({});
    } catch (err: unknown) {
      setLoadError(getErrorMessage(err, 'Error loading locations'));
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (hasAccess) load();
  }, [hasAccess, load]);

  const sortedLocations = useMemo(() => sortLocations(spellings, sortColumn, sortDirection), [spellings, sortColumn, sortDirection]);

  const update = (key: string, patch: Partial<Draft>) => {
    setDrafts((prev) => ({ ...prev, [key]: { ...prev[key], ...patch } }));
    setSaveStates((prev) => ({ ...prev, [key]: 'idle' }));
  };

  const save = async (loc: UnresolvedLocation) => {
    const d = drafts[loc.key];
    if (!d?.state) return;
    setSaveStates((prev) => ({ ...prev, [loc.key]: 'saving' }));
    try {
      const rowsUpdated = await saveLocationMapping({
        locationKey: loc.key,
        state: d.state,
        location: d.location && d.location !== ADD_NEW ? d.location : null,
        newLocation: d.location === ADD_NEW ? d.newLocation : null,
      });
      setNotice(`Saved "${loc.example}" — ${rowsUpdated} record${rowsUpdated === 1 ? '' : 's'} updated.`);
      if (d.location === ADD_NEW && d.newLocation.trim()) {
        setStateLocations((prev) => [...prev, { state: d.state, location: d.newLocation.trim() }]);
      }
      // A location-level mapping completes this spelling; a state-only one stays listed so it isn't forgotten.
      if (d.location) setSpellings((prev) => prev.filter((l) => l.key !== loc.key));
      else setSaveStates((prev) => ({ ...prev, [loc.key]: 'idle' }));
    } catch (err: unknown) {
      setSaveStates((prev) => ({ ...prev, [loc.key]: 'error' }));
      setSaveErrors((prev) => ({ ...prev, [loc.key]: getErrorMessage(err, 'Failed to save') }));
    }
  };

  if (isUserLoading || (isLoading && hasAccess)) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner text="Loading locations…" />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">Access Denied</h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {loadError || 'You do not have permission to access this page.'}
            </p>
            <a href="/admin" className="mt-4 inline-block rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600">
              Go Back
            </a>
          </div>
        </div>
      </MobileLayout>
    );
  }

  const totalRows = spellings.reduce((n, l) => n + l.rows, 0);

  return (
    <MobileLayout>
      <div className="p-4 pb-28">
        <div className="mb-6">
          <a href="/admin" className="mb-4 inline-block text-sm text-blue-600 hover:text-blue-700 dark:text-blue-400">
            ← Back to Admin Panel
          </a>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">Campaign Report Locations</h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Locations typed in the Campaign Report sheet that aren&apos;t mapped to a State Places location yet.
            Pick the state and location for each — it is applied to every record with that spelling, and to new
            ones as they arrive. Choose &ldquo;Add as new location&rdquo; for a location that is no longer (or never
            was) in State Places; it will also appear in State Places and campaign dropdowns.
          </p>
        </div>

        {loadError && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <p className="text-sm text-red-600 dark:text-red-300">{loadError}</p>
          </div>
        )}
        {notice && (
          <div className="mb-4 rounded-lg border border-green-300 bg-green-50 p-3 text-sm text-green-800 dark:border-green-700 dark:bg-green-900/20 dark:text-green-200">
            {notice}
          </div>
        )}

        <div className="mb-4 flex items-center justify-between">
          <p className="text-sm font-medium text-gray-700 dark:text-gray-300">
            {spellings.length} typed location{spellings.length === 1 ? '' : 's'} ({totalRows} records) remaining
          </p>
          <div className="flex flex-wrap items-center gap-2">
            <label className="text-xs font-medium text-gray-700 dark:text-gray-300" htmlFor="location-sort">Sort by</label>
            <select
              id="location-sort"
              value={sortColumn}
              onChange={(e) => {
                const column = e.target.value as LocationSortColumn;
                setSortColumn(column);
                setSortDirection(column === 'records' ? 'desc' : 'asc');
              }}
              className="rounded-md border border-gray-300 bg-white px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
            >
              <option value="records">Number of records</option>
              <option value="location">Location</option>
              <option value="state">State</option>
            </select>
            <button
              type="button"
              onClick={() => setSortDirection((d) => (d === 'asc' ? 'desc' : 'asc'))}
              aria-label={`Sort direction: ${sortDirection === 'asc' ? 'ascending' : 'descending'}`}
              className="rounded-md border-2 border-gray-400 bg-white px-3 py-1.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 dark:border-gray-500 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600"
            >
              {sortDirection === 'asc' ? '▲ A–Z' : '▼ Z–A'}
            </button>
          <button
            type="button"
            onClick={load}
            className="rounded-md border-2 border-gray-400 bg-white px-3 py-1.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 dark:border-gray-500 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600"
          >
            Refresh
          </button>
          </div>
        </div>

        {spellings.length === 0 && !isLoading && (
          <div className="rounded-lg border-2 border-green-300 bg-green-50 p-6 text-center dark:border-green-700 dark:bg-green-900/20">
            <p className="text-base font-semibold text-green-800 dark:text-green-200">Every typed location is mapped 🎉</p>
          </div>
        )}

        <div className="space-y-4">
          {sortedLocations.map((loc) => {
            const d = drafts[loc.key] ?? { state: '', location: '', newLocation: '' };
            const saveState = saveStates[loc.key] ?? 'idle';
            const stateOptions = stateLocations.filter((p) => p.state === d.state);
            return (
              <div key={loc.key} className="rounded-lg border-2 border-gray-300 bg-white p-4 shadow-sm dark:border-gray-600 dark:bg-gray-800">
                <div className="mb-3 flex flex-wrap items-baseline justify-between gap-x-4 border-b border-gray-200 pb-2 dark:border-gray-700">
                  <p className="text-base font-semibold text-gray-900 dark:text-gray-100">{loc.example}</p>
                  <p className="text-xs text-gray-500 dark:text-gray-400">
                    {loc.rows} record{loc.rows === 1 ? '' : 's'}
                    {loc.knownState ? ` · state ${loc.knownState}` : ''}
                  </p>
                </div>

                {loc.suggestions.length > 0 && (
                  <div className="mb-3 flex flex-wrap items-center gap-2">
                    <span className="text-xs font-medium text-gray-500 dark:text-gray-400">Suggestions:</span>
                    {loc.suggestions.map((s) => (
                      <button
                        key={`${s.state}-${s.location}`}
                        type="button"
                        onClick={() => update(loc.key, { state: s.state, location: s.location })}
                        className="rounded-full border border-blue-400 bg-blue-50 px-3 py-0.5 text-xs font-semibold text-blue-800 hover:bg-blue-100 dark:border-blue-500 dark:bg-blue-900/30 dark:text-blue-200"
                      >
                        {s.location} ({s.state})
                      </button>
                    ))}
                  </div>
                )}

                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                  <div>
                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">State</label>
                    <select
                      value={d.state}
                      onChange={(e) => update(loc.key, { state: e.target.value, location: '', newLocation: '' })}
                      className="mt-1 block w-full rounded-md border border-gray-300 bg-white px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
                    >
                      <option value="">— Select —</option>
                      {AUSTRALIAN_STATES.map((s) => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">Location</label>
                    <select
                      value={d.location}
                      onChange={(e) => update(loc.key, { location: e.target.value })}
                      disabled={!d.state}
                      className="mt-1 block w-full rounded-md border border-gray-300 bg-white px-2 py-1.5 text-sm disabled:bg-gray-100 dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100 dark:disabled:bg-gray-800"
                    >
                      <option value="">{d.state ? '— State only —' : 'Select a state first'}</option>
                      {stateOptions.map((p) => <option key={p.location} value={p.location}>{p.location}</option>)}
                      {d.state && <option value={ADD_NEW}>+ Add as new location…</option>}
                    </select>
                  </div>
                </div>

                {d.location === ADD_NEW && (
                  <div className="mt-3">
                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">New location name (added to State Places for {d.state})</label>
                    <input
                      value={d.newLocation}
                      onChange={(e) => update(loc.key, { newLocation: e.target.value })}
                      placeholder="e.g. Port Macquarie"
                      className="mt-1 block w-full rounded-md border border-gray-300 bg-white px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
                    />
                  </div>
                )}

                <div className="mt-3 flex items-center gap-3">
                  <button
                    type="button"
                    onClick={() => save(loc)}
                    disabled={saveState === 'saving' || !d.state || (d.location === ADD_NEW && !d.newLocation.trim())}
                    className="rounded-md bg-blue-600 px-4 py-1.5 text-sm font-bold text-white hover:bg-blue-700 disabled:bg-gray-400 border-2 border-gray-800 dark:border-gray-600"
                  >
                    {saveState === 'saving' ? 'Saving…' : 'Save'}
                  </button>
                  {saveState === 'error' && (
                    <span className="text-sm font-medium text-red-700 dark:text-red-400">{saveErrors[loc.key] || 'Failed to save'}</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </MobileLayout>
  );
}

