                        <div className={`text-xs ${stateColor.text} opacity-60 mt-1`}>
                          {frequencyLabel}{dayLabel ? ` on ${dayLabel}` : ''}
                        </div>
                        {(rule.start_date || rule.end_date) && (
                          <div className={`text-xs mt-0.5 ${expiringSoon ? 'font-medium text-amber-600 dark:text-amber-400' : `${stateColor.text} opacity-60`}`}>
                            {rule.start_date ? `Active from ${rule.start_date}` : ''}
                            {rule.start_date && rule.end_date ? ' · ' : ''}
                            {rule.end_date ? `Until ${rule.end_date}` : ''}
                            {expiringSoon ? ' ⚠ Expiring soon' : ''}
                          </div>
                        )}
                        {rule.notes && (
                          <div className={`text-xs ${stateColor.text} opacity-60 mt-1 italic`}>
                            {rule.notes}
                          </div>
                        )}
                        {(rule.rule_config?.exceptions?.length ?? 0) > 0 && (
                          <div className="mt-2 rounded bg-white/50 p-2 dark:bg-gray-900/50">
                            <div className="text-xs font-medium text-gray-700 dark:text-gray-300">
                              Excluded dates (manually deleted — won&apos;t be regenerated):
                            </div>
                            <div className="mt-1 flex flex-wrap gap-1.5">
                              {[...(rule.rule_config?.exceptions ?? [])].sort().map((dateStr) => (
                                <span
                                  key={dateStr}
                                  className="inline-flex items-center gap-1 rounded bg-amber-100 px-2 py-0.5 text-xs font-medium text-amber-800 dark:bg-amber-900/30 dark:text-amber-300"
                                >
                                  {formatDateReadable(new Date(dateStr + 'T00:00:00'))}
                                  <button
                                    type="button"
                                    onClick={() => handleRemoveException(rule, dateStr)}
                                    title="Allow this date to be regenerated again"
                                    className="ml-0.5 font-bold text-amber-600 hover:text-amber-900 dark:text-amber-400 dark:hover:text-amber-100"
                                  >
                                    ×
                                  </button>
                                </span>
                              ))}
                            </div>
                          </div>
                        )}
                        {previewRuleId === rule.id && (
                          <div className="mt-2 rounded bg-white/50 p-2 dark:bg-gray-900/50">
                            <div className="text-xs font-medium text-gray-700 dark:text-gray-300">
                              Upcoming campaign dates:
                            </div>
                            {previewDates.length > 0 ? (
                              <div className="text-xs text-gray-600 dark:text-gray-400">
                                {previewDates.map((d, i) => (
                                  <span key={i} className="mr-2">
                                    {formatDateReadable(d)}
                                  </span>
                                ))}
                              </div>
                            ) : (
                              <div className="text-xs text-gray-500 dark:text-gray-400">
                                No dates match in preview period
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                      <div className="flex flex-col gap-2 ml-4">
                        <button
                          onClick={() => handlePreview(rule)}
                          className="rounded-md bg-green-100 px-3 py-1 text-sm font-medium text-green-700 hover:bg-green-200 dark:bg-green-900/30 dark:text-green-300 dark:hover:bg-green-900/50"
                        >
                          {previewRuleId === rule.id ? 'Hide Preview' : 'Preview'}
                        </button>
                        <button
                          onClick={() => handleEdit(rule)}
                          className="rounded-md bg-blue-100 px-3 py-1 text-sm font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:hover:bg-blue-900/50"
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => handleToggleActive(rule)}
                          className={`rounded-md px-3 py-1 text-sm font-medium ${
                            rule.is_active
                              ? 'bg-yellow-100 text-yellow-700 hover:bg-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-300'
                              : 'bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-300'
                          }`}
                        >
                          {rule.is_active ? 'Deactivate' : 'Activate'}
                        </button>
                        <button
                          onClick={() => handleDelete(rule.id, rule)}
                          className="rounded-md bg-red-100 px-3 py-1 text-base font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-300 dark:hover:bg-red-900/50 border-2 border-gray-800 dark:border-gray-600"
                        >
                          Delete
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>

      {/* ── Create-confirmation modal ──────────────────────────────────────── */}
      {showConfirmModal && pendingRuleData && (
        <Modal position="bottom" onClose={handleCancelConfirm}>
          <div className="w-full max-w-lg rounded-t-2xl bg-white p-6 shadow-xl dark:bg-gray-900 sm:rounded-2xl">

            {/* Header */}
            <h2 className="mb-1 text-xl font-bold text-gray-900 dark:text-gray-100">
              Confirm New Campaign Rule
            </h2>
            <p className="mb-5 text-sm text-gray-500 dark:text-gray-400">
              Please review what this rule will do before confirming.
            </p>

            {/* Rule summary card */}
            <div className="mb-5 rounded-lg border-2 border-blue-200 bg-blue-50 p-4 dark:border-blue-800 dark:bg-blue-900/20">
              <div className="mb-3 text-sm font-semibold text-blue-900 dark:text-blue-200">
                {pendingRuleData.name}
              </div>
              <div className="space-y-1 text-sm text-blue-800 dark:text-blue-300">
                <div>
                  <span className="font-medium">Who: </span>
                  {pendingRuleData.leader}
                </div>
                <div>
                  <span className="font-medium">Where: </span>
                  {combinePlaceAndSite(pendingRuleData.place, pendingRuleData.site)}, {pendingRuleData.state}
                </div>
                <div>
                  <span className="font-medium">Time: </span>
                  {TIME_OPTIONS.find(t => t.value === pendingRuleData.time)?.label ?? pendingRuleData.time}
                </div>
                <div>
                  <span className="font-medium">Schedule: </span>
                  {buildScheduleSummary(
                    pendingRuleData.frequency_type as 'weekly' | 'biweekly' | 'monthly',
                    pendingRuleData.day_of_week ?? 0,
                    pendingRuleData.month_week_number,
                    pendingRuleData.month_day_of_week,
                    pendingRuleData.frequency_value ?? 2,
                  )}
                </div>
                {pendingRuleData.start_date && (
                  <div>
                    <span className="font-medium">Starting: </span>
                    {new Date(pendingRuleData.start_date + 'T00:00:00').toLocaleDateString('en-AU', {
                      day: 'numeric', month: 'long', year: 'numeric',
                    })}
                  </div>
                )}
                {pendingRuleData.end_date && (
                  <div>
                    <span className="font-medium">Until: </span>
                    {new Date(pendingRuleData.end_date + 'T00:00:00').toLocaleDateString('en-AU', {
                      day: 'numeric', month: 'long', year: 'numeric',
                    })}
                  </div>
                )}
              </div>
            </div>

            {/* Upcoming dates */}
            <div className="mb-5">
              <p className="mb-2 text-sm font-semibold text-gray-700 dark:text-gray-300">
                📅 Next upcoming campaign dates:
              </p>
              {confirmDates.length > 0 ? (
                <ul className="space-y-1">
                  {confirmDates.map(dateStr => (
                    <li key={dateStr} className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-300">
                      <span className="text-green-500">✓</span>
                      {new Date(dateStr + 'T00:00:00').toLocaleDateString('en-AU', {
                        weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
                      })}
                    </li>
                  ))}
                </ul>
              ) : (
                <div className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-800 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-300">
                  ⚠ No campaigns will be generated in the next 6 months with these settings.
                  You can still create the rule and activate it later, or go back and adjust the settings.
                </div>
              )}
            </div>

            {/* Footer note */}
            <p className="mb-5 text-xs text-gray-500 dark:text-gray-400">
              Campaigns are created automatically during the weekly system refresh.
              You can edit, deactivate, or delete this rule at any time.
            </p>

            {/* Actions */}
            <div className="flex gap-3">
              <button
                type="button"
                onClick={handleCancelConfirm}
                className="flex-1 rounded-md border-2 border-gray-400 bg-white px-4 py-2.5 text-base font-bold text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
              >
                ← Go Back
              </button>
              <button
                type="button"
                onClick={handleConfirmCreate}
                disabled={isSubmitting}
                className="flex-1 rounded-md border-2 border-gray-800 bg-blue-600 px-4 py-2.5 text-base font-bold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600"
              >
                {isSubmitting ? 'Creating…' : 'Confirm & Create'}
              </button>
            </div>
          </div>
        </Modal>
      )}
    </MobileLayout>
  );
}

export default function CampaignRulesPage() {
  return (
    <Suspense fallback={
      <MobileLayout>
        <div className="p-4">
          <div className="text-center">Loading...</div>
        </div>
      </MobileLayout>
    }>
      <CampaignRulesPageContent />
    </Suspense>
  );
}

app/admin/campaigns-near-me/page.tsx:
'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import dynamic from 'next/dynamic';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { useCampaignDates } from '@/contexts/CampaignDatesContext';
import { formatDateForDb, formatWeekRangeLabel } from '@/lib/campaignDates';
import { getUserLocation } from '@/lib/location';
import { supabase } from '@/lib/supabaseClient';
import { getNearbyCampaigns, type NearbyMapMarker } from '@/lib/services/nearbyCampaignsService';
import { getErrorMessage } from '@/lib/errorUtils';

const NearbyCampaignsMap = dynamic(() => import('@/components/NearbyCampaignsMap'), {
  ssr: false,
  loading: () => (
    <div className="flex h-full items-center justify-center text-sm text-gray-500 dark:text-gray-400">
      Loading map…
    </div>
  ),
});

const RADIUS_KM = 60;

export default function CampaignsNearMePage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const { dates: campaignDates } = useCampaignDates();
  const [hasAccess, setHasAccess] = useState(false);
  const [accessError, setAccessError] = useState<string | null>(null);

  // Week 1 is the upcoming campaign week; Week 2 is the one after it. The
  // toggle below picks which week's campaigns are queried — Week 1 by default.
  const [selectedWeek, setSelectedWeek] = useState<1 | 2>(1);

  const weeks = useMemo(() => {
    if (!campaignDates) return null;
    const week1Start = campaignDates.upcomingCampaignStart;
    const week2Start = campaignDates.secondWeekStart;
    return {
      1: { startDate: formatDateForDb(week1Start), label: formatWeekRangeLabel(week1Start) },
      2: { startDate: formatDateForDb(week2Start), label: formatWeekRangeLabel(week2Start) },
    };
  }, [campaignDates]);

  const { startDate, endDate } = useMemo(() => {
    if (!weeks) return { startDate: '', endDate: '' };
    const start = weeks[selectedWeek].startDate;
    const [y, m, d] = start.split('-').map(Number);
    const end = new Date(y, m - 1, d + 6);
    return { startDate: start, endDate: formatDateForDb(end) };
  }, [weeks, selectedWeek]);

  // Centre point: either browser geolocation or a geocoded address.
  const [center, setCenter] = useState<[number, number] | null>(null);
  const [centerLabel, setCenterLabel] = useState<string>('Your current location');
  const [isLocating, setIsLocating] = useState(false);
  const [locationError, setLocationError] = useState<string | null>(null);

  // Address entry — separate state from the active centre so the user can type
  // freely without re-triggering geocoding on every keystroke.
  const [addressInput, setAddressInput] = useState('');
  const [isGeocoding, setIsGeocoding] = useState(false);

  const [markers, setMarkers] = useState<NearbyMapMarker[]>([]);
  const [unresolvedCount, setUnresolvedCount] = useState(0);
  const [isLoadingMap, setIsLoadingMap] = useState(false);
  const [mapError, setMapError] = useState<string | null>(null);

  // Auth + access gate.
  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    Promise.resolve().then(() => {
      if (!isAdmin) {
        setAccessError('You do not have permission to access this page');
        return;
      }
      setHasAccess(true);
    });
  }, [isUserLoading, user, isAdmin, router]);

  // Initial geolocation attempt — only after access is granted to avoid prompting
  // users who'll see the access-denied screen anyway.
  const requestCurrentLocation = useCallback(async () => {
    setIsLocating(true);
    setLocationError(null);
    try {
      const { coords, deniedByUser } = await getUserLocation();
      if (coords) {
        setCenter([coords.latitude, coords.longitude]);
        setCenterLabel('Your current location');
      } else if (deniedByUser) {
        setLocationError('Location permission denied. Type an address below to choose a different centre.');
      } else {
        setLocationError('Could not get your location. Type an address below to choose a different centre.');
      }
    } finally {
      setIsLocating(false);
    }
  }, []);

  useEffect(() => {
    if (!hasAccess) return;
    if (center) return;
    requestCurrentLocation();
  }, [hasAccess, center, requestCurrentLocation]);

  // Refetch markers whenever the centre or date range changes.
  useEffect(() => {
    if (!hasAccess || !center) return;
    if (!startDate || !endDate) return;

    let cancelled = false;

    Promise.resolve()
      .then(() => {
        setIsLoadingMap(true);
        setMapError(null);
        return getNearbyCampaigns({
          startDate,
          endDate,
          centerLat: center[0],
          centerLng: center[1],
          radiusKm: RADIUS_KM,
        });
      })
      .then(result => {
        if (cancelled) return;
        setMarkers(result.markers);
        setUnresolvedCount(result.unresolvedPlaces.length);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setMapError(getErrorMessage(err, 'Failed to load nearby campaigns'));
      })
      .finally(() => {
        if (!cancelled) setIsLoadingMap(false);
      });

    return () => { cancelled = true; };
  }, [hasAccess, center, startDate, endDate]);

  const handleAddressSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const address = addressInput.trim();
    if (!address) return;

    setIsGeocoding(true);
    setLocationError(null);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        setLocationError('Your session has expired. Please sign in again.');
        return;
      }
      const response = await fetch('/api/admin/geocode-address', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({ address }),
      });

      if (response.status === 404) {
        setLocationError(`No location found for "${address}". Try a more specific address.`);
        return;
      }
      if (!response.ok) {
        setLocationError('Could not look up that address. Please try again.');
        return;
      }

      const data = await response.json() as { latitude: number; longitude: number; displayName: string };
      setCenter([data.latitude, data.longitude]);
      setCenterLabel(data.displayName);
    } catch (err: unknown) {
      setLocationError(getErrorMessage(err, 'Could not look up that address'));
    } finally {
      setIsGeocoding(false);
    }
  };

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">Access Denied</h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {accessError || 'You do not have permission to access this page.'}
            </p>
            <button
              onClick={() => router.push('/app')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      {/* 100dvh (not vh) so mobile browser chrome that shows/hides on scroll doesn't
          throw the height off. Subtracts the header (4rem), the fixed bottom nav
          (5rem, matching MobileLayout's own pb-20 reservation for it) */}
      <div className="flex h-[calc(100dvh-4rem-5rem)] flex-col p-4">
        <div className="mb-3 flex items-start justify-between gap-3">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">Campaigns Near Me</h1>
            <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
              Campaigns within {RADIUS_KM} km of your location
            </p>
          </div>
          <button
            onClick={() => router.push('/admin')}
            className="shrink-0 rounded-md bg-gray-200 px-3 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
          >
            Back
          </button>
        </div>

        {weeks && (
          <div className="mb-3 flex gap-2">
            {([1, 2] as const).map(week => (
              <button
                key={week}
                type="button"
                onClick={() => setSelectedWeek(week)}
                className={`rounded-md px-3 py-2 text-sm font-semibold border-2 transition-colors ${
                  selectedWeek === week
                    ? 'bg-blue-600 text-white border-blue-700'
                    : 'bg-white text-gray-700 border-gray-400 hover:bg-gray-50 dark:bg-gray-800 dark:text-gray-200 dark:border-gray-600 dark:hover:bg-gray-700'
                }`}
              >
                {week === 1 ? 'This Week' : 'Next Week'} ({weeks[week].label})
              </button>
            ))}
          </div>
        )}

        <form onSubmit={handleAddressSubmit} className="mb-3">
          <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">
            Centre on address
          </label>
          <div className="mt-1 flex gap-2">
            <input
              type="text"
              value={addressInput}
              onChange={e => setAddressInput(e.target.value)}
              placeholder="e.g. 100 Collins St, Melbourne"
              className="flex-1 rounded-md border border-gray-300 px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
            />
            <button
              type="submit"
              disabled={isGeocoding || !addressInput.trim()}
              className="rounded-md bg-blue-600 px-3 py-1.5 text-sm font-bold text-white hover:bg-blue-700 disabled:bg-gray-400 border-2 border-gray-800 dark:border-gray-600"
            >
              {isGeocoding ? 'Locating…' : 'Use address'}
            </button>
            <button
              type="button"
              onClick={() => { setAddressInput(''); requestCurrentLocation(); }}
              disabled={isLocating}
              className="rounded-md bg-gray-200 px-3 py-1.5 text-sm font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 disabled:opacity-50 border-2 border-gray-800 dark:border-gray-600"
              title="Use my current location"
            >
              {isLocating ? '…' : 'My location'}
            </button>
          </div>
        </form>

        {locationError && (
          <div className="mb-3 rounded-lg border border-yellow-200 bg-yellow-50 p-3 text-sm text-yellow-800 dark:border-yellow-800 dark:bg-yellow-900/20 dark:text-yellow-200">
            {locationError}
          </div>
        )}

        {mapError && (
          <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {mapError}
          </div>
        )}

        {!mapError && unresolvedCount > 0 && (
          <div className="mb-3 rounded-lg border border-yellow-200 bg-yellow-50 p-3 text-sm text-yellow-800 dark:border-yellow-800 dark:bg-yellow-900/20 dark:text-yellow-200">
            {unresolvedCount} place{unresolvedCount === 1 ? '' : 's'} could not be located on the map.
          </div>
        )}

        {center && (
          <div className="mb-2 text-xs text-gray-600 dark:text-gray-400">
            Centred on: <span className="font-medium">{centerLabel}</span>
            {' · '}
            {markers.length} campaign{markers.length === 1 ? '' : 's'} within {RADIUS_KM} km
          </div>
        )}

        <div className="relative flex-1 overflow-hidden rounded-lg border-2 border-gray-800 dark:border-gray-600">
          {(isLoadingMap || isLocating) && (
            // z-[1100] keeps the overlay above Leaflet's stacked panes (tile=200,
            // overlay=400, marker=600, popup=700, controls=~1000) — otherwise the
            // loading message disappears the moment Leaflet paints its first tile.
            <div className="absolute inset-0 z-[1100] flex flex-col items-center justify-center gap-3 bg-white/80 px-6 text-center dark:bg-gray-900/80">
              <LoadingSpinner text={isLocating ? 'Locating you…' : 'Please wait — locating campaigns on the map'} />
              {isLoadingMap && (
                <p className="max-w-sm text-xs text-gray-600 dark:text-gray-400">
                  This can take up to 15 seconds the first time, while new place locations are looked up. Subsequent loads are instant.
                </p>
              )}
            </div>
          )}
          {center ? (
            <NearbyCampaignsMap center={center} radiusKm={RADIUS_KM} markers={markers} />
          ) : (
            <div className="flex h-full items-center justify-center p-4 text-center text-sm text-gray-500 dark:text-gray-400">
              {isLocating
                ? 'Getting your location…'
                : 'Enter an address above or allow location access to see nearby campaigns.'}
            </div>
          )}
        </div>
      </div>
    </MobileLayout>
  );
}

app/admin/check-registration/__tests__/p:
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, cleanup, fireEvent, waitFor } from '@testing-library/react';

const mockPush = vi.fn();
const mockRouter = { push: mockPush };
vi.mock('next/navigation', () => ({
  useRouter: () => mockRouter,
}));

vi.mock('@/components/MobileLayout', () => ({
  default: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}));

const mockUseUser = vi.fn();
vi.mock('@/contexts/UserContext', () => ({
  useUser: () => mockUseUser(),
}));

// The real module imports lib/supabaseClient.ts, which needs env vars at import time.
const mockLookup = vi.fn();
vi.mock('@/lib/services/registrationCheckClient', () => ({
  requestAdminRegistrationLookup: (...args: unknown[]) => mockLookup(...args),
}));

import AdminCheckRegistrationPage from '../page';

const ALICE = {
  id: 'r-alice', firstName: 'Alice', lastName: 'Nguyen', email: 'alice@example.com', phone: '+61412345678',
  state: 'VIC', postcode: '3000', registeredAt: '2026-09-12T03:00:00Z',
  webinarSessionAt: null, webinarAttended: null, codeOfConductAgreed: 'Yes', codeOfConductAgreedAt: null,
  unsubscribed: null, nfc: null, matchedOn: ['email'],
};

function fill(label: string, value: string) {
  fireEvent.change(screen.getByLabelText(label), { target: { value } });
}

const submit = () => fireEvent.click(screen.getByRole('button', { name: 'Check Registry' }));

beforeEach(() => {
  vi.clearAllMocks();
  mockUseUser.mockReturnValue({ user: { id: 'user-1' }, isAdmin: true, isLoading: false });
});

afterEach(cleanup);

describe('AdminCheckRegistrationPage', () => {
  it('redirects to /login when there is no signed-in user', async () => {
    mockUseUser.mockReturnValue({ user: null, isAdmin: false, isLoading: false });
    render(<AdminCheckRegistrationPage />);
    await waitFor(() => expect(mockPush).toHaveBeenCalledWith('/login'));
  });

  it('shows Access Denied, and no form, to a non-admin', () => {
    mockUseUser.mockReturnValue({ user: { id: 'user-1' }, isAdmin: false, isLoading: false });
    render(<AdminCheckRegistrationPage />);
    expect(screen.getByText('Access Denied')).toBeTruthy();
    expect(screen.queryByLabelText('Mobile')).toBeNull();
  });

  it('asks only for mobile and email', () => {
    render(<AdminCheckRegistrationPage />);
    expect(screen.getAllByRole('textbox').map((input) => input.id)).toEqual(['lookup-mobile', 'lookup-email']);
  });

  it('sends the cleaned details and says which one is registered', async () => {
    mockLookup.mockResolvedValue({ registered: true, matchedOn: ['email'], registrants: [ALICE] });
    render(<AdminCheckRegistrationPage />);
    fill('Mobile', ' 0412 345 678 ');
    fill('Email', 'alice@example.com');
    submit();

    expect(await screen.findByText('✅ Registered')).toBeTruthy();
    expect(mockLookup).toHaveBeenCalledWith({ email: 'alice@example.com', mobile: '0412 345 678' });
    expect(screen.getByText('There is a registration with the email address alice@example.com.')).toBeTruthy();
    expect(screen.getByText('No registration has the mobile number 0412 345 678.')).toBeTruthy();
  });

  it('shows the registration details of the person found', async () => {
    mockLookup.mockResolvedValue({ registered: true, matchedOn: ['email'], registrants: [ALICE] });
    render(<AdminCheckRegistrationPage />);
    fill('Email', 'alice@example.com');
    submit();

    expect(await screen.findByRole('heading', { name: 'Alice Nguyen' })).toBeTruthy();
    const details = screen.getByRole('status').textContent ?? '';
    for (const expected of ['Matched on email address', '+61412345678', 'VIC', '3000', 'Code agreedYes']) {
      expect(details).toContain(expected);
    }
    // Month abbreviation ("Sep"/"Sept") varies with the runtime's locale data.
    expect(details).toMatch(/Registered12 Sept? 2026/);
    expect(details).not.toMatch(/Unsubscribed|No Further Contact/);
  });

  it('flags an unsubscribed / No Further Contact registrant', async () => {
    mockLookup.mockResolvedValue({
      registered: true, matchedOn: ['email'], registrants: [{ ...ALICE, unsubscribed: 'Yes', nfc: 'Yes' }],
    });
    render(<AdminCheckRegistrationPage />);
    fill('Email', 'alice@example.com');
    submit();
    expect(await screen.findByText('Unsubscribed · No Further Contact')).toBeTruthy();
  });

  it('lists every matching registration when there is more than one', async () => {
    mockLookup.mockResolvedValue({
      registered: true,
      matchedOn: ['email', 'mobile'],
      registrants: [ALICE, { ...ALICE, id: 'r-bao', firstName: 'Bao', email: 'bao@example.com', matchedOn: ['mobile'] }],
    });
    render(<AdminCheckRegistrationPage />);
    fill('Mobile', '0412 345 678');
    fill('Email', 'alice@example.com');
    submit();

    expect(await screen.findByText(/2 different registrations match/)).toBeTruthy();
    expect(screen.getByRole('heading', { name: 'Alice Nguyen' })).toBeTruthy();
    expect(screen.getByRole('heading', { name: 'Bao Nguyen' })).toBeTruthy();
  });

  it('works with a mobile on its own, and shows "Not Registered"', async () => {
    mockLookup.mockResolvedValue({ registered: false, matchedOn: [], registrants: [] });
    render(<AdminCheckRegistrationPage />);
    fill('Mobile', '0412 345 678');
    submit();

    expect(await screen.findByText('❌ Not Registered')).toBeTruthy();
    expect(mockLookup).toHaveBeenCalledWith({ email: null, mobile: '0412 345 678' });
    expect(screen.getByText('No registration was found for 0412 345 678.')).toBeTruthy();
  });

  it('does not call the API when both fields are empty', () => {
    render(<AdminCheckRegistrationPage />);
    submit();
    expect(screen.getByRole('alert').textContent).toMatch(/email address or a mobile number/);
    expect(mockLookup).not.toHaveBeenCalled();
  });

  it('clears the previous answer as soon as a field is edited', async () => {
    mockLookup.mockResolvedValue({ registered: true, matchedOn: ['email'], registrants: [ALICE] });
    render(<AdminCheckRegistrationPage />);
    fill('Email', 'alice@example.com');
    submit();
    await screen.findByText('✅ Registered');

    fill('Email', 'someone.else@example.com');
    expect(screen.queryByText('✅ Registered')).toBeNull();
  });

  it("shows the server's refusal (e.g. no 2FA) as an error, never as an answer", async () => {
    mockLookup.mockRejectedValue(new Error('Two-factor sign-in is required for this action'));
    render(<AdminCheckRegistrationPage />);
    fill('Email', 'alice@example.com');
    submit();

    expect((await screen.findByRole('alert')).textContent).toBe('Two-factor sign-in is required for this action');
    expect(screen.queryByRole('status')).toBeNull();
  });
});

