            <button
              onClick={() => router.push('/app')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="relative mb-3">
          <button
            onClick={() => router.push('/admin')}
            className="absolute right-0 top-0 rounded bg-gray-200 px-1.5 py-0.5 text-xs font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border border-gray-800 dark:border-gray-600"
          >
            Back
          </button>
          <h1 className="pr-14 text-2xl font-bold text-gray-900 dark:text-gray-100">Campaign Interest ({entries.length})</h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Members who have registered interest in joining a campaign via the Register Interest screen. Tick Contacted once you&apos;ve followed up with them.
          </p>
        </div>

        {loadError && (
          <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {loadError}
          </div>
        )}
        {updateError && (
          <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {updateError}
          </div>
        )}

        <div className="rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white shadow-sm dark:bg-gray-800">
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {isLoading ? (
              <div className="p-8 flex justify-center">
                <LoadingSpinner text="Loading registered interest…" />
              </div>
            ) : (
              <CampaignInterestEntryList entries={entries} updatingIds={updatingIds} onToggleContacted={handleToggleContacted} />
            )}
          </div>
        </div>
      </div>
    </MobileLayout>
  );
}

app/admin/results-metrics/page.tsx:
'use client';

import { useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { supabase } from '@/lib/supabaseClient';
import { useCampaignDates } from '@/contexts/CampaignDatesContext';
import { formatDateForDb } from '@/lib/campaignDates';
import { getErrorMessage } from '@/lib/errorUtils';
import { getStateColor } from '@/lib/stateColors';
import {
  fetchResultsMetrics,
  aggregateByCategory,
  aggregateByState,
  aggregateByPlace,
  RESULT_CATEGORIES,
  RESULT_CATEGORY_LABELS,
  type CampaignResultsRow,
  type ResultCategory,
} from '@/lib/resultsMetrics';

type ViewMode = 'total' | 'category' | 'state' | 'place' | 'campaign';

/** Categories counted in the "by campaign" per-card total — team members are excluded. */
const NON_TEAM_CATEGORIES: ResultCategory[] = RESULT_CATEGORIES.filter((c) => c !== 'TM');

function nonTeamCount(r: CampaignResultsRow): number {
  return NON_TEAM_CATEGORIES.reduce((sum, cat) => sum + r.names[cat].length, 0);
}

const CATEGORY_BAR_COLOR: Record<string, string> = {
  TM: 'bg-blue-500',
  P: 'bg-amber-500',
  F: 'bg-emerald-500',
  SP: 'bg-purple-500',
};

export default function ResultsMetricsPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const { dates: campaignDates } = useCampaignDates();

  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [view, setView] = useState<ViewMode>('total');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasData, setHasData] = useState(false);
  const [rows, setRows] = useState<CampaignResultsRow[]>([]);

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) { router.push('/admin'); return; }
  }, [isUserLoading, user, isAdmin, router]);

  useEffect(() => {
    if (campaignDates && !startDate && !endDate) {
      const monday = campaignDates.pastCampaignStart;
      const sunday = new Date(monday);
      sunday.setDate(sunday.getDate() + 6);
      setStartDate(formatDateForDb(monday));
      setEndDate(formatDateForDb(sunday));
    }
  }, [campaignDates, startDate, endDate]);

  const fetchData = async () => {
    if (!startDate || !endDate) {
      setError('Please select both start and end dates');
      return;
    }
    setIsLoading(true);
    setError(null);
    setHasData(false);

    try {
      const fetched = await fetchResultsMetrics(supabase, startDate, endDate);
      if (fetched.length === 0) {
        setError('No campaigns found in the selected date range');
        setRows([]);
        return;
      }
      setRows(fetched);
      setHasData(true);
    } catch (err) {
      setError(getErrorMessage(err, 'Error loading results metrics'));
    } finally {
      setIsLoading(false);
    }
  };

  const categoryTotals = useMemo(() => aggregateByCategory(rows), [rows]);
  const stateTotals = useMemo(() => aggregateByState(rows), [rows]);
  const placeTotals = useMemo(() => aggregateByPlace(rows), [rows]);
  const grandTotal = useMemo(() => categoryTotals.reduce((sum, c) => sum + c.count, 0), [categoryTotals]);
  const nonTeamGrandTotal = useMemo(() => rows.reduce((sum, r) => sum + nonTeamCount(r), 0), [rows]);

  const formatDate = (dateStr: string) => {
    const d = new Date(dateStr + 'T00:00:00');
    return d.toLocaleDateString('en-AU', { weekday: 'short', day: 'numeric', month: 'short' });
  };

  const tabs: { key: ViewMode; label: string }[] = [
    { key: 'total', label: 'Total' },
    { key: 'category', label: 'By Category' },
    { key: 'state', label: 'By State' },
    { key: 'place', label: 'By Place' },
    { key: 'campaign', label: 'By Campaign' },
  ];

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="p-4 pb-28">
        <div className="mb-6">
          <a
            href="/admin"
            className="mb-4 inline-block text-sm text-blue-600 hover:text-blue-700 dark:text-blue-400"
          >
            ← Back to Admin Panel
          </a>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
            Results Metrics
          </h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Names recorded against past campaigns, by category, state, and place
          </p>
        </div>

        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <p className="text-sm text-red-600 dark:text-red-300">{error}</p>
          </div>
        )}

        {/* Date range + fetch */}
        <div className="mb-6 rounded-lg border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-700 dark:bg-gray-800">
          <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-gray-100">Date Range</h2>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Start Date</label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="mt-1 block w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">End Date</label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="mt-1 block w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
              />
            </div>
            <button
              type="button"
              onClick={fetchData}
              disabled={isLoading}
              className="w-full rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:bg-gray-400 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
            >
              {isLoading ? 'Loading…' : 'Load Data'}
            </button>
          </div>
        </div>

        {hasData && (
          <>
            {/* View tabs */}
            <div className="mb-4 flex gap-2 flex-wrap">
              {tabs.map((t) => (
                <button
                  key={t.key}
                  type="button"
                  onClick={() => setView(t.key)}
                  className={`rounded-md px-4 py-2 text-sm font-semibold border-2 transition-colors ${
                    view === t.key
                      ? 'bg-blue-600 text-white border-blue-700'
                      : 'bg-white text-gray-700 border-gray-400 hover:bg-gray-50 dark:bg-gray-800 dark:text-gray-200 dark:border-gray-600 dark:hover:bg-gray-700'
                  }`}
                >
                  {t.label}
                </button>
              ))}
            </div>

            {/* Total view */}
            {view === 'total' && (
              <div className="space-y-4">
                <div className="rounded-lg border-2 border-blue-300 bg-blue-50 p-6 text-center dark:border-blue-700 dark:bg-blue-900/30">
                  <p className="text-5xl font-bold text-blue-700 dark:text-blue-300">{grandTotal}</p>
                  <p className="mt-2 text-base font-semibold text-blue-900 dark:text-blue-100">Total Names Recorded</p>
                  <p className="mt-1 text-sm text-blue-700 dark:text-blue-300">across {rows.length} campaign{rows.length !== 1 ? 's' : ''}</p>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  {categoryTotals.map((c) => (
                    <div
                      key={c.category}
                      className="rounded-lg border border-gray-200 bg-white p-4 text-center dark:border-gray-700 dark:bg-gray-800"
                    >
                      <p className="text-3xl font-bold text-gray-900 dark:text-gray-100">{c.count}</p>
                      <p className="mt-1 text-xs font-medium text-gray-600 dark:text-gray-400">
                        {RESULT_CATEGORY_LABELS[c.category]}
                      </p>
                    </div>
                  ))}
                </div>
                <div className="rounded-lg border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-800">
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    <span className="font-semibold">Average per campaign:</span>{' '}
                    {rows.length > 0 ? (grandTotal / rows.length).toFixed(1) : '—'}
                  </p>
                </div>
              </div>
            )}

            {/* By Category view */}
            {view === 'category' && (
              <div className="space-y-3">
                {categoryTotals.map((c) => {
                  const pct = grandTotal > 0 ? Math.round((c.count / grandTotal) * 100) : 0;
                  return (
                    <div
                      key={c.category}
                      className="rounded-lg border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-800"
                    >
                      <div className="flex items-center justify-between text-sm">
                        <span className="font-semibold text-gray-900 dark:text-gray-100">
                          {RESULT_CATEGORY_LABELS[c.category]}
                        </span>
                        <span className="text-gray-600 dark:text-gray-400">{c.count} ({pct}%)</span>
                      </div>
                      <div className="mt-2 h-3 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-gray-700">
                        <div
                          className={`h-full rounded-full ${CATEGORY_BAR_COLOR[c.category]}`}
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {/* By State view */}
            {view === 'state' && (
              <div className="overflow-x-auto rounded-lg border border-gray-200 dark:border-gray-700">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-700">
                    <tr>
                      <th className="px-4 py-3 text-left font-semibold text-gray-700 dark:text-gray-200">State</th>
                      <th className="px-4 py-3 text-right font-semibold text-gray-700 dark:text-gray-200">Campaigns</th>
                      {RESULT_CATEGORIES.map((cat) => (
                        <th key={cat} className="px-4 py-3 text-right font-semibold text-gray-700 dark:text-gray-200">{cat}</th>
                      ))}
                      <th className="px-4 py-3 text-right font-semibold text-gray-700 dark:text-gray-200">Total</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                    {stateTotals.map((s) => {
                      const stateColor = getStateColor(s.state);
                      return (
                        <tr key={s.state} className={stateColor.bg}>
                          <td className="px-4 py-3 font-semibold text-gray-900 dark:text-gray-100">{s.state}</td>
                          <td className="px-4 py-3 text-right text-gray-700 dark:text-gray-300">{s.campaigns}</td>
                          {RESULT_CATEGORIES.map((cat) => (
                            <td key={cat} className="px-4 py-3 text-right text-gray-700 dark:text-gray-300">{s.totals[cat]}</td>
                          ))}
                          <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">{s.total}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot className="bg-gray-100 dark:bg-gray-600">
                    <tr>
                      <td className="px-4 py-3 font-bold text-gray-900 dark:text-gray-100">Total</td>
                      <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">{rows.length}</td>
                      {RESULT_CATEGORIES.map((cat) => (
                        <td key={cat} className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">
                          {categoryTotals.find((c) => c.category === cat)?.count ?? 0}
                        </td>
                      ))}
                      <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">{grandTotal}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}

            {/* By Place view */}
            {view === 'place' && (
              <div className="overflow-x-auto rounded-lg border border-gray-200 dark:border-gray-700">
                <table className="w-full text-sm">
                  <thead className="bg-gray-50 dark:bg-gray-700">
                    <tr>
                      <th className="px-4 py-3 text-left font-semibold text-gray-700 dark:text-gray-200">Place</th>
                      <th className="px-4 py-3 text-left font-semibold text-gray-700 dark:text-gray-200">State</th>
                      <th className="px-4 py-3 text-right font-semibold text-gray-700 dark:text-gray-200">Campaigns</th>
                      {RESULT_CATEGORIES.map((cat) => (
                        <th key={cat} className="px-4 py-3 text-right font-semibold text-gray-700 dark:text-gray-200">{cat}</th>
                      ))}
                      <th className="px-4 py-3 text-right font-semibold text-gray-700 dark:text-gray-200">Total</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                    {placeTotals.map((p) => {
                      const stateColor = getStateColor(p.state);
                      return (
                        <tr key={`${p.state}-${p.place}`} className={stateColor.bg}>
                          <td className="px-4 py-3 font-medium text-gray-900 dark:text-gray-100">{p.place}</td>
                          <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{p.state}</td>
                          <td className="px-4 py-3 text-right text-gray-700 dark:text-gray-300">{p.campaigns}</td>
                          {RESULT_CATEGORIES.map((cat) => (
                            <td key={cat} className="px-4 py-3 text-right text-gray-700 dark:text-gray-300">{p.totals[cat]}</td>
                          ))}
                          <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">{p.total}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot className="bg-gray-100 dark:bg-gray-600">
                    <tr>
                      <td colSpan={2} className="px-4 py-3 font-bold text-gray-900 dark:text-gray-100">Total</td>
                      <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">{rows.length}</td>
                      {RESULT_CATEGORIES.map((cat) => (
                        <td key={cat} className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">
                          {categoryTotals.find((c) => c.category === cat)?.count ?? 0}
                        </td>
                      ))}
                      <td className="px-4 py-3 text-right font-bold text-gray-900 dark:text-gray-100">{grandTotal}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}

            {/* By Campaign view */}
            {view === 'campaign' && (
              <div className="space-y-3">
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  The total on the right counts Partial/Full Presentations and Sinner&rsquo;s Prayer results only — Team Members are excluded.
                </p>
                {rows.map((r) => {
                  const stateColor = getStateColor(r.state);
                  const total = nonTeamCount(r);
                  const displayLeader = r.actualLeader || r.leader;
                  return (
                    <div
                      key={r.campaignId}
                      className={`rounded-lg border border-gray-200 dark:border-gray-700 p-4 ${stateColor.bg}`}
                    >
                      <div className="flex items-start justify-between gap-3">
                        <div className="flex-1 min-w-0">
                          <p className="font-semibold text-gray-900 dark:text-gray-100">
                            {r.place}, {r.state}
                          </p>
                          <p className="text-sm text-gray-600 dark:text-gray-400">{formatDate(r.date)}</p>
                          <p className="text-sm text-gray-700 dark:text-gray-300 mt-1">
                            Leader: <span className="font-medium">{displayLeader}</span>
                          </p>
                          {RESULT_CATEGORIES.map((cat) => (
                            <p key={cat} className="text-sm text-gray-700 dark:text-gray-300 mt-0.5">
                              {RESULT_CATEGORY_LABELS[cat]}: <span className="font-medium">{r.names[cat].length}</span>
                            </p>
                          ))}
                        </div>
                        <div className="flex-shrink-0 text-right">
                          <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">{total}</p>
                          <p className="text-xs text-gray-500 dark:text-gray-400">result{total !== 1 ? 's' : ''}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
                <div className="rounded-lg border-2 border-gray-400 bg-gray-100 dark:border-gray-600 dark:bg-gray-700 px-4 py-3 flex justify-between items-center">
                  <span className="font-bold text-gray-900 dark:text-gray-100">Total</span>
                  <span className="text-xl font-bold text-gray-900 dark:text-gray-100">{nonTeamGrandTotal} results</span>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </MobileLayout>
  );
}

app/admin/state-leaders/page.tsx:
'use client';

import { useEffect, useState, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { getStateColor } from '@/lib/stateColors';
import { AUSTRALIAN_STATES } from '@/lib/constants';
import { getErrorMessage } from '@/lib/errorUtils';
import { isValidEmail } from '@/lib/validation';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';
import {
  type StateLeaderRoleFilter,
  STATE_LEADER_ROLE_FILTER_OPTIONS,
  matchesStateLeaderRoleFilter,
} from '@/lib/stateLeaderRoleFilter';
import { requestMfaReset } from '@/lib/services/mfaResetClient';
import {
  type StateLeader,
  getStateLeaders,
  createStateLeader,
  updateStateLeader,
  deleteStateLeader,
} from '@/lib/services/stateLeadersService';

import { supabase } from '@/lib/supabaseClient';

async function revokeSessionsForLeader(state: string, leader: string): Promise<void> {
  const { data: { session } } = await supabase.auth.getSession();
  const token = session?.access_token;
  if (!token) return;
  await fetch('/api/admin/invalidate-user-session', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
    body: JSON.stringify({ state, leader }),
  });
}

export default function StateLeadersPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const [hasAccess, setHasAccess] = useState(false);
  const [stateLeaders, setStateLeaders] = useState<StateLeader[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Form state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formState, setFormState] = useState({ state: '', leader: '', mobile: '', admin: '', email: '' });
  const [filterState, setFilterState] = useState<string>('');
  const [filterName, setFilterName]   = useState<string>('');
  const [filterMobile, setFilterMobile] = useState<string>('');
  const [filterRole, setFilterRole] = useState<StateLeaderRoleFilter>('');

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      setError('You do not have permission to access this page');
      return;
    }
    setHasAccess(true);
    fetchStateLeaders();
  }, [isUserLoading, user, isAdmin, router]);

  const fetchStateLeaders = async () => {
    try {
      const data = await getStateLeaders(filterState || undefined);
      setStateLeaders(data);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to fetch state leaders'));
    }
  };

  useEffect(() => {
    if (hasAccess) {
      fetchStateLeaders();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterState, hasAccess]);

  // Dropdown options derived from already-fetched data, scoped to the selected state and role.
  // Must be declared before any early returns to satisfy Rules of Hooks.
  const filterOptionSource = useMemo(
    () => stateLeaders.filter(sl =>
      (!filterState || sl.state === filterState) && matchesStateLeaderRoleFilter(sl.admin, filterRole)),
    [stateLeaders, filterState, filterRole],
  );

  const filterNameOptions = useMemo(
    () => [...new Set(filterOptionSource.map(sl => sl.leader))].sort(),
    [filterOptionSource],
  );

  const filterMobileOptions = useMemo(
    () => [...new Set(filterOptionSource.map(sl => sl.mobile).filter((m): m is string => !!m))].sort(),
    [filterOptionSource],
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    setIsSubmitting(true);

    try {
      const leaderValue = formState.leader.trim();
      const mobileValue = formState.mobile.trim() || null;
      const adminValue = formState.admin.trim() || null;
      const emailValue = formState.email.trim() || null;

      if (emailValue && !isValidEmail(emailValue)) {
        setError('Please enter a valid email address');
        return;
      }

      if (editingId) {
        const originalItem = stateLeaders.find(sl => sl.id === editingId);
        await updateStateLeader(editingId, {
          state: formState.state,
          leader: leaderValue,
          mobile: mobileValue,
          admin: adminValue,
          email: emailValue,
        });
        setSuccess('State leader updated successfully');

        // If admin status changed (granted or revoked), force-sign-out the
        // affected user immediately so the change takes effect without waiting
        // for their next JWT refresh cycle (~1 hour).
        const adminChanged = originalItem && (originalItem.admin ?? null) !== adminValue;
        if (adminChanged) {
          void revokeSessionsForLeader(formState.state, leaderValue);
        }
      } else {
        await createStateLeader({
          state: formState.state,
          leader: leaderValue,
          mobile: mobileValue,
          admin: adminValue,
          email: emailValue,
        });
        setSuccess('State leader created successfully');
      }

      // Reset form
      setFormState({ state: '', leader: '', mobile: '', admin: '', email: '' });
      setEditingId(null);
      await fetchStateLeaders();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to save state leader'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEdit = (item: StateLeader) => {
    setEditingId(item.id);
    setFormState({
      state: item.state,
      leader: item.leader,
      mobile: item.mobile || '',
      admin: item.admin || '',
      email: item.email || '',
    });
    setError(null);
    setSuccess(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this state-leader combination?')) {
      return;
    }

    try {
      await deleteStateLeader(id);
      setSuccess('State leader deleted successfully');
      await fetchStateLeaders();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to delete state leader'));
    }
  };

  const handleResetMfa = async (item: StateLeader) => {
    const asAdmin = isRecognizedAdminStatus(item.admin) ? ' as an admin' : '';
    if (!confirm(`Reset two-factor authentication for ${item.leader} (${item.state})?\n\nThey will be signed out and must set up 2FA again before they can sign in${asAdmin}.`)) {
      return;
    }

    try {
      setError(null);
      await requestMfaReset(item.id);
      setSuccess(`Two-factor authentication reset for ${item.leader} (${item.state}). They will need to set it up again.`);
      await fetchStateLeaders();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to reset two-factor authentication'));
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setFormState({ state: '', leader: '', mobile: '', admin: '', email: '' });
    setError(null);
    setSuccess(null);
  };

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">
              Access Denied
            </h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {error || 'You do not have permission to access this page.'}
            </p>
            <button
              onClick={() => router.push('/admin')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  const filteredLeaders = stateLeaders.filter((sl) => {
    if (filterState  && sl.state !== filterState) return false;
    if (!matchesStateLeaderRoleFilter(sl.admin, filterRole)) return false;
    if (filterName   && !sl.leader.toLowerCase().includes(filterName.toLowerCase())) return false;
    if (filterMobile && !(sl.mobile ?? '').toLowerCase().includes(filterMobile.toLowerCase())) return false;
    return true;
  });

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                Manage State Leaders
              </h1>
              <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                Add, edit, or remove state-leader combinations
              </p>
            </div>
            <button
              onClick={() => router.push('/admin')}
              className="rounded-md bg-gray-200 px-3 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
            >
              Back
            </button>
          </div>
        </div>

        {/* Success/Error Messages */}
        {success && (
          <div className="mb-4 rounded-md bg-green-50 border border-green-200 px-4 py-3 text-sm text-green-800 dark:bg-green-900/20 dark:border-green-800 dark:text-green-200">
            {success}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-md bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-200">
            {error}
          </div>
        )}

        {/* Add/Edit Form */}
        <div className="mb-6 rounded-lg border border-gray-200 bg-blue-50 p-4 shadow-sm dark:border-gray-700 dark:bg-blue-900/20">
          <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-gray-100">
            {editingId ? 'Edit State Leader' : 'Add New State Leader'}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="state" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                State
              </label>
              <select
                id="state"
                required
                value={formState.state}
                onChange={(e) => setFormState({ ...formState, state: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
              >
                <option value="">Select a state</option>
                {AUSTRALIAN_STATES.map((state) => (
                  <option key={state} value={state}>
                    {state}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label htmlFor="leader" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Leader
              </label>
              <input
                id="leader"
                type="text"
                required
                value={formState.leader}
                onChange={(e) => setFormState({ ...formState, leader: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="Enter leader name"
              />
            </div>
            <div>
              <label htmlFor="mobile" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Mobile (Optional)
              </label>
              <input
                id="mobile"
                type="tel"
                value={formState.mobile}
                onChange={(e) => setFormState({ ...formState, mobile: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="Enter mobile number"
              />
            </div>
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Email (Optional)
              </label>
              <input
                id="email"
                type="email"
                value={formState.email}
                onChange={(e) => setFormState({ ...formState, email: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="Enter email address"
              />
              {editingId && (
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  Changing or removing the email resets this leader&apos;s email confirmation and two-factor setup — they will need to set them up again.
                </p>
              )}
            </div>
            <div>
              <label htmlFor="admin" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                Admin Role (Optional)
              </label>
              {/* Constrained to the only three values this column may ever hold — a free-text
                  field here is exactly what caused the #78 stray-admin-value bug (a recruiter's
                  name typed in instead of a real role code). */}
              <select
                id="admin"
                value={formState.admin}
                onChange={(e) => setFormState({ ...formState, admin: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
              >
                <option value="">None (regular leader)</option>
                <option value="AD">AD — Full Admin</option>
                <option value="SR">SR — State Reporter</option>
              </select>
            </div>
            <div className="flex gap-2">
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex-1 rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
              >
                {isSubmitting ? 'Saving...' : editingId ? 'Update' : 'Add'}
              </button>
              {editingId && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-md bg-gray-200 px-4 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
                >
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>

        {/* Filters */}
        <div className="mb-4 grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <div>
            <label htmlFor="filter-state" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
              Filter by State
            </label>
            <select
              id="filter-state"
              value={filterState}
              onChange={(e) => { setFilterState(e.target.value); setFilterName(''); setFilterMobile(''); }}
              className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
            >
              <option value="">All States</option>
              {AUSTRALIAN_STATES.map((state) => (
                <option key={state} value={state}>
                  {state}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="filter-role" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
              Filter by Role
            </label>
            <select
              id="filter-role"
              value={filterRole}
              onChange={(e) => { setFilterRole(e.target.value as StateLeaderRoleFilter); setFilterName(''); setFilterMobile(''); }}
              className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
            >
              {STATE_LEADER_ROLE_FILTER_OPTIONS.map(({ value, label }) => (
                <option key={value} value={value}>{label}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="filter-name" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
              Filter by Name
            </label>
            <select
              id="filter-name"
              value={filterName}
              onChange={(e) => setFilterName(e.target.value)}
              className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
            >
              <option value="">All Names</option>
              {filterNameOptions.map((name) => (
                <option key={name} value={name}>{name}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="filter-mobile" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
              Filter by Mobile
            </label>
            <select
              id="filter-mobile"
              value={filterMobile}
              onChange={(e) => setFilterMobile(e.target.value)}
              className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
            >
              <option value="">All Mobiles</option>
              {filterMobileOptions.map((mobile) => (
                <option key={mobile} value={mobile}>{mobile}</option>
              ))}
            </select>
          </div>
        </div>

        {/* List of State Leaders */}
        <div className="rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white shadow-sm dark:bg-gray-800">
          <div className="p-4">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              State Leaders ({filteredLeaders.length})
            </h2>
          </div>
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {filteredLeaders.length === 0 ? (
              <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
                No state leaders found
              </div>
            ) : (
              filteredLeaders.map((item) => {
                const stateColor = getStateColor(item.state);
                return (
                  <div key={item.id} className={`p-4 ${stateColor.bg}`}>
                    <div className="flex items-center justify-between">
                      <div>
                        <div className={`font-medium ${stateColor.text}`}>
                          {item.leader}
                        </div>
                        <div className={`text-sm ${stateColor.text} opacity-75`}>
                          {item.state}
                        </div>
                        {item.mobile && (
                          <div className={`text-xs ${stateColor.text} opacity-60 mt-1`}>
                            {item.mobile}
                          </div>
                        )}
                        {item.email && (
                          <div className={`text-xs ${stateColor.text} opacity-60 mt-1`}>
                            {item.email}{item.mfa_enrolled_at && ' · MFA ✓'}
                          </div>
                        )}
                        {item.admin && (
                          <div className={`text-xs ${stateColor.text} opacity-60 mt-1`}>
                            Admin: {item.admin}
                            {isRecognizedAdminStatus(item.admin) && !item.mfa_enrolled_at && ' · 2FA not set up — cannot sign in yet'}
                          </div>
                        )}
                      </div>
                      <div className="flex gap-2">
                        {item.mfa_enrolled_at && (
                          <button
                            onClick={() => handleResetMfa(item)}
                            className="rounded-md bg-amber-100 px-3 py-1 text-sm font-medium text-amber-800 hover:bg-amber-200 dark:bg-amber-900/30 dark:text-amber-300 dark:hover:bg-amber-900/50"
                          >
                            Reset 2FA
                          </button>
                        )}
                        <button
                          onClick={() => handleEdit(item)}
                          className="rounded-md bg-blue-100 px-3 py-1 text-sm font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:hover:bg-blue-900/50"
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => handleDelete(item.id)}
                          className="rounded-md bg-red-100 px-3 py-1 text-base font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-300 dark:hover:bg-red-900/50 border-2 border-gray-800 dark:border-gray-600"
                        >
                          Delete
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </MobileLayout>
  );
}

