'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { getStateColor } from '@/lib/stateColors';
import { AUSTRALIAN_STATES } from '@/lib/constants';
import { getErrorMessage } from '@/lib/errorUtils';
import {
  type StatePlace,
  getStatePlaces,
  createStatePlace,
  updateStatePlace,
  deleteStatePlace,
} from '@/lib/services/statePlacesService';
import { fetchPlaceCoordinates } from '@/lib/services/campaignMapService';

export default function StatePlacesPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const [hasAccess, setHasAccess] = useState(false);
  const [statePlaces, setStatePlaces] = useState<StatePlace[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Form state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formState, setFormState] = useState({ state: '', place: '', location: '' });
  const [filterState, setFilterState] = useState<string>('');

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      setError('You do not have permission to access this page');
      return;
    }
    setHasAccess(true);
    fetchStatePlaces();
  }, [isUserLoading, user, isAdmin, router]);

  const fetchStatePlaces = async () => {
    try {
      const data = await getStatePlaces(filterState || undefined);
      setStatePlaces(data);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to fetch state places'));
    }
  };

  useEffect(() => {
    if (hasAccess) {
      fetchStatePlaces();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterState, hasAccess]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    setIsSubmitting(true);

    try {
      const action = editingId ? 'updated' : 'created';
      if (editingId) {
        await updateStatePlace(editingId, { state: formState.state, place: formState.place, location: formState.location });
      } else {
        await createStatePlace({ state: formState.state, place: formState.place, location: formState.location });
      }

      // Geocode immediately so the campaign map has coordinates ready right away, rather
      // than waiting for this place to first appear on a map view. On edit, force a fresh
      // geocode — the location text may have changed, so any cached coordinates are stale.
      const coords = await fetchPlaceCoordinates(formState.state, formState.place, !!editingId);
      setSuccess(
        coords
          ? `State place ${action} successfully. Map coordinates found and saved.`
          : `State place ${action} successfully. Could not find map coordinates for this location yet — it will be retried the next time the campaign map loads.`,
      );

      // Reset form
      setFormState({ state: '', place: '', location: '' });
      setEditingId(null);
      await fetchStatePlaces();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to save state place'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEdit = (item: StatePlace) => {
    setEditingId(item.id);
    setFormState({ state: item.state, place: item.place, location: item.location || '' });
    setError(null);
    setSuccess(null);
    // Scroll to form
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this state-place combination?')) {
      return;
    }

    try {
      await deleteStatePlace(id);
      setSuccess('State place deleted successfully');
      await fetchStatePlaces();
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to delete state place'));
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setFormState({ state: '', place: '', location: '' });
    setError(null);
    setSuccess(null);
  };

  if (isUserLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (!hasAccess) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">
              Access Denied
            </h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {error || 'You do not have permission to access this page.'}
            </p>
            <button
              onClick={() => router.push('/admin')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-sm font-medium text-white hover:bg-red-700"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  const filteredPlaces = filterState
    ? statePlaces.filter(sp => sp.state === filterState)
    : statePlaces;

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                Manage State Places
              </h1>
              <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                Add, edit, or remove state-place combinations
              </p>
            </div>
            <button
              onClick={() => router.push('/admin')}
              className="rounded-md bg-gray-200 px-3 py-2 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
            >
              Back
            </button>
          </div>
        </div>

        {/* Success/Error Messages */}
        {success && (
          <div className="mb-4 rounded-md bg-green-50 border border-green-200 px-4 py-3 text-sm text-green-800 dark:bg-green-900/20 dark:border-green-800 dark:text-green-200">
            {success}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-md bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-200">
            {error}
          </div>
        )}

        {/* Add/Edit Form */}
        <div className="mb-6 rounded-lg border border-gray-200 bg-blue-50 p-4 shadow-sm dark:border-gray-700 dark:bg-blue-900/20">
          <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-gray-100">
            {editingId ? 'Edit State Place' : 'Add New State Place'}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="state" className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                State
              </label>
              <select
                id="state"
                required
                value={formState.state}
                onChange={(e) => setFormState({ ...formState, state: e.target.value })}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
              >
                <option value="">Select a state</option>
                {AUSTRALIAN_STATES.map((state) => (
