'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { getErrorMessage } from '@/lib/errorUtils';
import { fetchStuckLeaders } from '@/lib/services/stuckLeadersClient';
import type { StuckLeader } from '@/lib/services/stuckLeadersService';
import { toSupportNumber } from '@/lib/supportContact';

function timeAgo(iso: string | null, now: number = Date.now()): string {
  if (!iso) return 'no activity recorded';
  const minutes = Math.max(0, Math.round((now - new Date(iso).getTime()) / 60000));
  if (minutes < 60) return `${Math.max(1, minutes)} min ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 48) return `${hours} hour${hours === 1 ? '' : 's'} ago`;
  return `${Math.round(hours / 24)} days ago`;
}

function nudgeMessage(leader: StuckLeader): string {
  const firstName = leader.name.replace(/_(AD|SR)$/i, '');
  return `Hi ${firstName}, I can see you started setting up your secure AFJ sign-in but haven't finished. Can I help? Step-by-step guide: ${window.location.origin}/help/2fa`;
}

export default function StuckLeadersPage() {
  const router = useRouter();
  const { user, isAdmin, isLoading: isUserLoading } = useUser();
  const [leaders, setLeaders] = useState<StuckLeader[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }
    if (!isAdmin) {
      Promise.resolve().then(() => setError('You do not have permission to access this page'));
      return;
    }
    let cancelled = false;
    fetchStuckLeaders()
      .then((result) => {
        if (cancelled) return;
        setError(null);
        setLeaders(result);
      })
      .catch((err: unknown) => {
        if (!cancelled) setError(getErrorMessage(err, 'Failed to load the list'));
      });
    return () => { cancelled = true; };
  }, [isUserLoading, user, isAdmin, router, reloadKey]);

  if (isUserLoading || (leaders === null && !error)) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center"><LoadingSpinner /></div>
      </MobileLayout>
    );
  }

  const admins = (leaders ?? []).filter((l) => l.isAdmin);
  const others = (leaders ?? []).filter((l) => !l.isAdmin);

  const renderCard = (l: StuckLeader) => {
    const number = toSupportNumber(l.mobile);
    return (
      <li key={l.key} className="rounded-lg border-2 border-gray-800 bg-white p-4 shadow-sm dark:border-gray-600 dark:bg-gray-800">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <span className="text-lg font-semibold text-gray-900 dark:text-gray-100">{l.name}</span>
          <span className="rounded-full bg-gray-200 px-3 py-0.5 text-sm font-semibold text-gray-800 dark:bg-gray-700 dark:text-gray-200">
            {l.role} · {l.states.join(', ')}
          </span>
        </div>
        <p className="mt-1 font-semibold text-red-700 dark:text-red-300">{l.label}</p>
        <p className="mt-1 text-sm text-gray-700 dark:text-gray-300">{l.action}</p>
        <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
          Last activity: {timeAgo(l.lastActivityAt)}{l.email ? ` · ${l.email}` : ''}{l.mobile ? ` · ${l.mobile}` : ''}
        </p>
        {number && (
          <div className="mt-3 flex gap-2">
            <a href={`tel:${number}`} className="rounded-md border-2 border-gray-800 bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700 dark:border-gray-600">Call</a>
            <a
              href={`sms:${number}?&body=${encodeURIComponent(nudgeMessage(l))}`}
              className="rounded-md border-2 border-gray-800 bg-white px-4 py-2 text-sm font-bold text-gray-900 hover:bg-gray-100 dark:border-gray-600 dark:bg-gray-900 dark:text-gray-100"
            >
              Text a reminder
            </a>
          </div>
        )}
      </li>
    );
  };

  return (
    <MobileLayout>
      <div className="mx-auto max-w-3xl space-y-6 px-4 py-6">
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-bold text-gray-900 dark:text-gray-100">Leaders who are stuck</h1>
          <button onClick={() => { setLeaders(null); setReloadKey((k) => k + 1); }} className="rounded-md border-2 border-gray-800 bg-white px-3 py-1 text-sm font-bold text-gray-900 hover:bg-gray-100 dark:border-gray-600 dark:bg-gray-900 dark:text-gray-100">
            Refresh
          </button>
        </div>
        <p className="text-sm text-gray-600 dark:text-gray-400">
          People who haven&apos;t finished setting up email sign-in and two-factor authentication, and the step they&apos;re at. Admins
          (and state reporters) are listed until they finish, because they can&apos;t sign in as an admin without it. Other leaders only
          appear if they started and didn&apos;t finish.
        </p>

        {error && <div role="alert" className="rounded-md bg-red-50 p-3 text-sm text-red-800 dark:bg-red-900/20 dark:text-red-200">{error}</div>}

        {leaders && leaders.length === 0 && (
          <p className="rounded-md bg-green-50 p-4 text-green-900 dark:bg-green-900/20 dark:text-green-200">Nobody is stuck right now.</p>
        )}

        {admins.length > 0 && (
          <section className="space-y-3">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Admins who can&apos;t sign in as admin yet ({admins.length})</h2>
            <ul className="space-y-3">{admins.map(renderCard)}</ul>
          </section>
        )}

        {others.length > 0 && (
          <section className="space-y-3">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Other leaders part-way through ({others.length})</h2>
            <ul className="space-y-3">{others.map(renderCard)}</ul>
          </section>
        )}
      </div>
    </MobileLayout>
  );
}

app/api/admin/__tests__/adminRoutesRequi:
/**
 * Every admin-only API route must refuse a caller who isn't a full admin
 * signed in with 2FA — via the shared verifyAdminCaller — *before* touching
 * anything else. These routes use the service role, which bypasses RLS, so
 * this check is the only thing protecting what they write. They used to each
 * copy-paste their own version (with an ILIKE that treated `_` in names as a
 * wildcard and no 2FA requirement); this pins that they all go through the
 * one shared check and stop when it says no.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { NextRequest } from 'next/server';

const mockVerify = vi.fn();
vi.mock('@/lib/services/adminCallerService', () => ({
  verifyAdminCaller: (...args: unknown[]) => mockVerify(...args),
}));
vi.mock('@/lib/corsUtils', () => ({ enforceOrigin: () => null }));
// Any use of the service-role client past the admin check is a failure.
vi.mock('@/lib/supabaseAdmin', () => ({
  supabaseAdmin: new Proxy({}, { get() { throw new Error('supabaseAdmin was used for a denied caller'); } }),
}));
vi.mock('@/lib/geocoding', () => ({ geocodeAddress: vi.fn(), geocodePlace: vi.fn() }));
vi.mock('@/lib/supabaseClient', () => ({ supabase: { auth: {}, from: vi.fn() } }));

type Handler = (r: NextRequest) => Promise<Response>;
type Method = 'POST' | 'GET' | 'PATCH';
const ROUTES: Array<[string, () => Promise<{ POST?: Handler; GET?: Handler; PATCH?: Handler }>, Method]> = [
  ['settings', () => import('../settings/route'), 'POST'],
  ['geocode-address', () => import('../geocode-address/route'), 'POST'],
  ['geocode-place', () => import('../geocode-place/route'), 'POST'],
  ['invalidate-user-session', () => import('../invalidate-user-session/route'), 'POST'],
  ['campaign-reports/locations', () => import('../campaign-reports/locations/route'), 'GET'],
  ['campaign-reports/locations', () => import('../campaign-reports/locations/route'), 'POST'],
  ['campaign-reports/manage', () => import('../campaign-reports/manage/route'), 'GET'],
  ['campaign-reports/manage', () => import('../campaign-reports/manage/route'), 'PATCH'],
  ['campaign-reports/edit-log', () => import('../campaign-reports/edit-log/route'), 'GET'],
  ['stuck-leaders', () => import('../stuck-leaders/route'), 'GET'],
  ['reset-mfa', () => import('../reset-mfa/route'), 'POST'],
  ['check-registration', () => import('../check-registration/route'), 'POST'],
  ['user-guide/upload-url', () => import('../user-guide/upload-url/route'), 'POST'],
  ['tech-insights', () => import('../tech-insights/route'), 'GET'],
];

function makeRequest(name: string, token?: string, method: Method = 'POST') {
  const headers = { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) };
  if (method === 'GET') return new NextRequest(`http://localhost/api/admin/${name}`, { method, headers });
  return new NextRequest(`http://localhost/api/admin/${name}`, {
    method,
    headers,
    body: JSON.stringify({ key: 'campaign_logging_enabled', value: 'true', address: 'x', state: 'VIC', place: 'x', leader: 'x', id: 'x', leaderId: 'x', email: 'a@example.com' }),
  });
}

describe.each(ROUTES)('/api/admin/%s', (name, load, method) => {
  beforeEach(() => {
    mockVerify.mockReset();
    process.env.SUPABASE_SERVICE_ROLE_KEY = 'test-service-key';
  });

  it('returns 401 without a Bearer token, without checking anything', async () => {
    const handler = (await load())[method] as Handler;
    const res = await handler(makeRequest(name, undefined, method));
    expect(res.status).toBe(401);
    expect(mockVerify).not.toHaveBeenCalled();
  });

  it('refuses a caller verifyAdminCaller rejects (403) and does nothing else', async () => {
    mockVerify.mockResolvedValue({ ok: false, status: 403, error: 'Forbidden' });
    const handler = (await load())[method] as Handler;
    const res = await handler(makeRequest(name, 'tok-123', method));

    expect(res.status).toBe(403);
    expect(mockVerify).toHaveBeenCalledWith(expect.anything(), 'tok-123');
  });

  it('passes through a 401 for an invalid session', async () => {
    mockVerify.mockResolvedValue({ ok: false, status: 401, error: 'Unauthorized' });
    const handler = (await load())[method] as Handler;
    expect((await handler(makeRequest(name, 'bad', method))).status).toBe(401);
  });

  it('refuses an admin whose session is not at 2FA level', async () => {
    mockVerify.mockResolvedValue({ ok: false, status: 403, error: 'Two-factor sign-in is required for this action' });
    const handler = (await load())[method] as Handler;
    const res = await handler(makeRequest(name, 'tok-aal1', method));
    expect(res.status).toBe(403);
    expect(await res.json()).toEqual({ error: 'Two-factor sign-in is required for this action' });
  });
});

