import { NextRequest } from 'next/server';

vi.mock('@/lib/services/adminCallerService', () => ({
  verifyAdminCaller: vi.fn().mockResolvedValue({ ok: true, userId: 'u1', label: 'Admin (VIC)' }),
}));
