/**
 * Campaign Report locations (see lib/services/campaignReportLocationsService.ts
 * and the /admin/campaign-report-locations screen).
 *
 * GET  -> { spellings, locations }  typed sheet locations with no mapped location yet, and the locations they can map to
 * POST -> { locationKey, state, location?, newLocation? }  record a mapping and apply it
 * Authorization: Bearer <supabase_access_token>  (caller must be a full admin with 2FA)
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { authorizeAdminRequest } from '@/lib/adminRouteGuard';
import { getUnresolvedLocations, saveLocationAlias } from '@/lib/services/campaignReportLocationsService';
import { getErrorMessage } from '@/lib/errorUtils';

const LOG_TAG = 'admin/campaign-reports/locations';

export async function GET(request: NextRequest) {
  const auth = await authorizeAdminRequest(request, LOG_TAG);
  if (!auth.ok) return auth.response;
  try {
    return NextResponse.json(await getUnresolvedLocations(supabaseAdmin));
  } catch (err) {
    console.error('[admin/campaign-reports/locations] GET failed:', err);
    return NextResponse.json({ error: getErrorMessage(err, 'Failed to load locations') }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  const auth = await authorizeAdminRequest(request, LOG_TAG);
  if (!auth.ok) return auth.response;

  let body: { locationKey?: unknown; state?: unknown; location?: unknown; newLocation?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }
  const str = (v: unknown) => (typeof v === 'string' ? v : null);
  if (!str(body.locationKey) || !str(body.state)) {
    return NextResponse.json({ error: 'Missing location or state' }, { status: 400 });
  }

  try {
    const result = await saveLocationAlias(supabaseAdmin, {
      locationKey: str(body.locationKey)!, state: str(body.state)!, location: str(body.location), newLocation: str(body.newLocation),
    });
    if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
    return NextResponse.json({ ok: true, rowsUpdated: result.rowsUpdated });
  } catch (err) {
    console.error('[admin/campaign-reports/locations] POST failed:', err);
    return NextResponse.json({ error: getErrorMessage(err, 'Failed to save') }, { status: 500 });
  }
}

app/api/admin/campaign-reports/manage/ro:
/**
 * Campaign Reports management screen (/admin/campaign-reports).
 *
 * GET   -> { reports, locations, leaders }  every report plus the State Places locations / leaders pick-lists
 * PATCH -> { id, field: 'state'|'location'|'leader', value, addLocation? }  one audited hand edit
 * Authorization: Bearer <supabase_access_token>  (caller must be a full admin with 2FA)
 * See lib/services/campaignReportManageService.ts.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { authorizeAdminRequest } from '@/lib/adminRouteGuard';
import { applyReportEdit, getManageData } from '@/lib/services/campaignReportManageService';
import { EDITABLE_REPORT_FIELDS, type EditableReportField } from '@/lib/campaignReportManageTypes';
import { getErrorMessage } from '@/lib/errorUtils';

const LOG_TAG = 'admin/campaign-reports/manage';

export async function GET(request: NextRequest) {
  const auth = await authorizeAdminRequest(request, LOG_TAG);
  if (!auth.ok) return auth.response;
  try {
    return NextResponse.json(await getManageData(supabaseAdmin));
  } catch (err) {
    console.error(`[${LOG_TAG}] GET failed:`, err);
    return NextResponse.json({ error: getErrorMessage(err, 'Failed to load reports') }, { status: 500 });
  }
}

export async function PATCH(request: NextRequest) {
  const auth = await authorizeAdminRequest(request, LOG_TAG);
  if (!auth.ok) return auth.response;

  let body: { id?: unknown; field?: unknown; value?: unknown; addLocation?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }
  if (typeof body.id !== 'string' || !body.id) return NextResponse.json({ error: 'id is required' }, { status: 400 });
  if (typeof body.field !== 'string' || !EDITABLE_REPORT_FIELDS.includes(body.field as EditableReportField)) {
    return NextResponse.json({ error: 'field must be state, location or leader' }, { status: 400 });
  }
  if (body.value !== null && typeof body.value !== 'string') {
    return NextResponse.json({ error: 'value must be a string or null' }, { status: 400 });
  }

  try {
    const result = await applyReportEdit(supabaseAdmin, {
      id: body.id,
      field: body.field as EditableReportField,
      value: body.value as string | null,
      addLocation: body.addLocation === true,
      actor: { userId: auth.userId, label: auth.label },
    });
    if (!result.ok) return NextResponse.json({ error: result.error, code: result.code }, { status: result.status });
    return NextResponse.json(result.report);
  } catch (err) {
    console.error(`[${LOG_TAG}] PATCH failed:`, err);
    return NextResponse.json({ error: getErrorMessage(err, 'Failed to save the edit') }, { status: 500 });
  }
}

app/api/admin/check-registration/route.t:
/**
 * Admin-only: who, if anyone, is already registered under this email or
 * mobile? A contact-only version of the leader check (no name asked for or
 * compared) that — unlike it — returns the matching registry records; see
 * lib/services/registrationCheckService.ts. That is personal data, so the
 * caller must be a full admin (AD) who signed in with 2FA
 * (lib/services/adminCallerService.ts) — do not loosen this gate.
 *
 * POST body: { email?, mobile? }  (at least one)
 * Authorization: Bearer <supabase_access_token>
 * Response: { registered: boolean, matchedOn: ('email' | 'mobile')[], registrants: RegistrantDetails[] }
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { verifyAdminCaller } from '@/lib/services/adminCallerService';
import { lookupRegistrationByContact, parseContactLookupInput } from '@/lib/services/registrationCheckService';

// Generous next to the leader check's 30 — this is a trusted admin working
// through a list — but still bounded.
const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 200 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  if (rateLimiter.isLimited(getClientIp(request))) {
    return NextResponse.json({ error: 'Too many checks. Please wait a few minutes and try again.' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('[admin/check-registration] SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const authHeader = request.headers.get('authorization');
    const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const caller = await verifyAdminCaller(supabaseAdmin, token);
    if (!caller.ok) return NextResponse.json({ error: caller.error }, { status: caller.status });

    const parsed = parseContactLookupInput(await request.json().catch(() => null));
    if (!parsed.ok) return NextResponse.json({ error: parsed.error }, { status: 400 });

    return NextResponse.json(await lookupRegistrationByContact(supabaseAdmin, parsed.input), {
      headers: { 'Cache-Control': 'no-store' },
    });
  } catch (err) {
    console.error('[admin/check-registration] exception:', err);
    return NextResponse.json({ error: 'The check could not be completed. Please try again.' }, { status: 500 });
  }
}

app/api/admin/geocode-address/route.ts:
/**
 * Server-side address geocoding for the "Campaigns Near Me" map.
 * POST body: { address: string }
 * Authorization: Bearer <supabase_access_token>
 *
 * Resolves a free-form Australian address to coordinates via Nominatim
 * (server-side, so a proper User-Agent can be set per Nominatim's usage policy).
 * Unlike /api/admin/geocode-place, results are NOT cached — addresses are
 * one-off lookups for the centre of the map and don't correspond to a row in
 * state_places.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyAdminCaller } from '@/lib/services/adminCallerService';
import { geocodeAddress } from '@/lib/geocoding';

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error('[admin/geocode-address] SUPABASE_SERVICE_ROLE_KEY is not set');
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  // Full admin (AD) signed in with 2FA — shared check, see lib/services/adminCallerService.ts.
  const caller = await verifyAdminCaller(supabaseAdmin, token);
  if (!caller.ok) {
    return NextResponse.json({ error: caller.error }, { status: caller.status });
  }

  let body: { address?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  const address = typeof body.address === 'string' ? body.address.trim() : null;
  if (!address) {
    return NextResponse.json({ error: 'Missing address' }, { status: 400 });
  }

  const result = await geocodeAddress(address);
  if (!result) {
    return NextResponse.json({ error: 'No coordinates found for this address' }, { status: 404 });
  }

  return NextResponse.json({
    latitude: result.latitude,
    longitude: result.longitude,
    displayName: result.displayName,
  });
}

app/api/admin/geocode-place/route.ts:
/**
 * Server-side geocoding for the admin campaign map.
 * POST body: { state: string, place: string, force?: boolean }
 * Authorization: Bearer <supabase_access_token>
 *
 * Looks up cached coordinates on state_places first; if missing, geocodes via
 * Nominatim (server-side, so a proper User-Agent can be set per their usage policy)
 * using the matching state_places row's `location` field — the sole source for
 * coordinates, since `place` is often a venue/event name rather than a real
 * suburb/town — and persists the result so future lookups for the same place are free.
 *
 * `force: true` skips the cache and re-geocodes + overwrites even when coordinates
 * already exist — used when an admin edits a place's `location`, since the old
 * coordinates were computed from the previous location text and are now stale.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyAdminCaller } from '@/lib/services/adminCallerService';
import { geocodePlace } from '@/lib/geocoding';

// A few rows are administratively grouped under one state (`state_places.state`, which
// drives who manages them / which campaign group they belong to) but are physically
// located in another — geocoding with the row's own state then finds no match. Override
// the state used in the *geocode query only* for these; the stored `state` column and
// campaign grouping are untouched. Keep in sync with the same map in
// scripts/backfill_state_places_coords.js.
const GEOCODE_STATE_OVERRIDES: Record<string, string> = {
  'f9811c68-0c9a-45e2-890a-e94fdcf0331c': 'NSW', // ACT :: Jervis Bay — physically on the NSW south coast
  '4dd81bed-5b01-433b-91b6-629cbece75f9': 'NSW', // ACT :: Sanctuary Point — physically on the NSW south coast
};

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error('[admin/geocode-place] SUPABASE_SERVICE_ROLE_KEY is not set');
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  // Full admin (AD) signed in with 2FA — shared check, see lib/services/adminCallerService.ts.
  const caller = await verifyAdminCaller(supabaseAdmin, token);
  if (!caller.ok) {
    return NextResponse.json({ error: caller.error }, { status: caller.status });
  }

  let body: { state?: unknown; place?: unknown; force?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  const state = typeof body.state === 'string' ? body.state.trim().toUpperCase() : null;
  const place = typeof body.place === 'string' ? body.place.trim() : null;
  const force = body.force === true;
  if (!state || !place) {
    return NextResponse.json({ error: 'Missing state or place' }, { status: 400 });
  }

  // `place` is matched loosely (trim + collapsed whitespace + case-insensitive) because
  // campaigns.place and state_places.place are independently free-typed and can differ by
  // incidental whitespace (e.g. "Preston" vs "Preston "), which would otherwise silently
  // break the coordinate cache.
  const { data: statePlaces } = await supabaseAdmin
    .from('state_places')
    .select('id, place, location, latitude, longitude')
    .eq('state', state);

  const normalize = (s: string) => s.trim().replace(/\s+/g, ' ').toLowerCase();
  const existing = statePlaces?.find(p => normalize(p.place) === normalize(place)) ?? null;

  if (!force && existing?.latitude != null && existing?.longitude != null) {
    return NextResponse.json({ latitude: existing.latitude, longitude: existing.longitude, cached: true });
  }

  if (!existing?.location) {
    return NextResponse.json({ error: 'No location set for this place' }, { status: 404 });
  }

  const geocodeState = (existing.id && GEOCODE_STATE_OVERRIDES[existing.id]) || state;
  const geocoded = await geocodePlace(existing.location, geocodeState);
  if (!geocoded) {
    return NextResponse.json({ error: 'No coordinates found for this location' }, { status: 404 });
  }

  if (existing?.id) {
    await supabaseAdmin
      .from('state_places')
      .update({ latitude: geocoded.latitude, longitude: geocoded.longitude })
      .eq('id', existing.id);
  }

  return NextResponse.json({ latitude: geocoded.latitude, longitude: geocoded.longitude, cached: false });
}

app/api/admin/invalidate-user-session/ro:
/**
 * Immediately revoke all active sessions for a given leader+state.
 *
 * Called by the state-leaders admin page when the `admin` field changes
 * (e.g. demoting an 'AD' admin or promoting someone new). Without this, the
 * affected user's admin-level access persists until their next JWT refresh
 * (~1 hour). This route forces an immediate sign-out via the Supabase auth
 * admin API so the role change takes effect right away.
 *
 * POST body: { state: string, leader: string }
 * Authorization: Bearer <supabase_access_token>  (caller must be an admin)
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { normalizeName } from '@/lib/auth';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyAdminCaller } from '@/lib/services/adminCallerService';

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error('[invalidate-user-session] SUPABASE_SERVICE_ROLE_KEY is not set');
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }

  // Verify caller is an authenticated admin
  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  // Full admin (AD) signed in with 2FA — shared check, see lib/services/adminCallerService.ts.
  const caller = await verifyAdminCaller(supabaseAdmin, token);
  if (!caller.ok) {
    return NextResponse.json({ error: caller.error }, { status: caller.status });
  }

  // Parse target
  let body: { state?: unknown; leader?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  const targetState  = typeof body.state  === 'string' ? body.state.toUpperCase().trim() : null;
  const targetLeader = typeof body.leader === 'string' ? body.leader.trim()              : null;

  if (!targetState || !targetLeader) {
    return NextResponse.json({ error: 'state and leader are required' }, { status: 400 });
  }

  // Find all user_profiles that match this leader+state. Matched exactly
  // after normalizing — not ILIKE, where `_` (in names like "Lorraine_AD")
  // is a wildcard and could revoke someone else's sessions.
  const { data: stateProfiles, error: profilesErr } = await supabaseAdmin
    .from('user_profiles')
    .select('user_id, name')
    .eq('state', targetState);

  if (profilesErr) {
    console.error('[invalidate-user-session] profile lookup failed:', profilesErr);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }

  const wantedName = normalizeName(targetLeader);
  const profiles = (stateProfiles ?? []).filter((p) => normalizeName(p.name ?? '') === wantedName);

  if (!profiles?.length) {
    return NextResponse.json({ ok: true, revoked: 0 });
  }

  // Revoke sessions via the Supabase auth admin REST endpoint.
  // The JS SDK's auth.admin.signOut() takes a JWT; for user-ID–based logout
  // we call the underlying REST API directly.
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
  const serviceKey  = process.env.SUPABASE_SERVICE_ROLE_KEY!;

  let revoked = 0;
  for (const { user_id } of profiles) {
    try {
      const res = await fetch(`${supabaseUrl}/auth/v1/admin/users/${user_id}/logout`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${serviceKey}`,
          'apikey': serviceKey,
        },
      });
      if (res.ok) revoked++;
    } catch (err) {
      console.error(`[invalidate-user-session] logout failed for ${user_id}:`, err);
    }
  }

  return NextResponse.json({ ok: true, revoked });
}

