app/api/auth/complete-mfa-setup/route.ts:
/**
 * MFA enrollment completion — called by app/setup-mfa/page.tsx right after
 * challengeAndVerify() succeeds (TOTP or phone), before it signs the
 * isolated client back out. Bearer token only; supabaseAdmin.auth.getUser
 * is the ONLY trusted source of identity.
 *
 * The caller must have at least one verified factor on their own session
 * (checked via supabaseAdmin.auth.getUser(token)'s returned user.factors,
 * never trusting the client's word for it) — a valid Bearer token alone
 * isn't proof that challengeAndVerify() actually succeeded; without this
 * check, anyone with a live session for this user_id (e.g. one abandoned
 * before completing enrollment) could mark mfa_enrolled_at without ever
 * having a real factor enrolled.
 *
 * Before stamping mfa_enrolled_at, completeMfaEnrollment() also binds user_id
 * on any still-unbound row whose email is this session's own address (see
 * lib/services/mfaEnrollmentService.ts for why — admin-entered emails never
 * got a user_id otherwise).
 *
 * UPDATE ... WHERE user_id = $user.id (no leaderId): MFA enrollment is a
 * property of the person/account, not any one state_leaders row. Safe to
 * scope by user_id alone here — unlike propose/confirm-email, which had
 * to scope by leaderId because identity wasn't yet established at
 * proposal time. By the time this route runs, user_id is already bound
 * to exactly one person via that earlier, leaderId-scoped confirm-email
 * flow — this route only ever touches rows that already carry this exact
 * user_id, so it can't cross into another leader's row. It only reaches
 * rows this person has individually confirmed email on, not necessarily
 * every row findVerifiedStateLeaders would surface as theirs — the same
 * per-row granularity email confirmation already has.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { completeMfaEnrollment } from '@/lib/services/mfaEnrollmentService';

const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 20 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const authHeader = request.headers.get('authorization');
    const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) {
      return NextResponse.json({ error: 'Invalid or expired session' }, { status: 401 });
    }

    const hasVerifiedFactor = (user.factors ?? []).some((f) => f.status === 'verified');
    if (!hasVerifiedFactor) {
      return NextResponse.json({ error: 'No verified MFA factor found for this session' }, { status: 403 });
    }

    const result = await completeMfaEnrollment(supabaseAdmin, { userId: user.id, email: user.email });
    if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });

    return NextResponse.json({ ok: true });
  } catch (err) {
    console.error('complete-mfa-setup API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/auth/confirm-email/route.ts:
/**
 * Leader self-serve email capture — step 2 of 2 (see propose-email/route.ts
 * for step 1). Called by app/confirm-email/page.tsx once the leader has
 * clicked their magic-link and that page's isolated Supabase client
 * (lib/emailConfirmSupabaseClient.ts) has completed the client-side session
 * exchange — this route never sees the magic-link itself.
 *
 * Authorization: Bearer <access_token> — the ONLY trusted source of the
 * confirmed email is supabaseAdmin.auth.getUser(token) below. A
 * client-supplied email string is never used to decide what gets written.
 *
 * Body: { leaderId }. The commit is scoped to this ONE row (id + matching
 * pending_email) rather than every row that happens to share the same
 * pending_email string — propose-email/route.ts only ever verified that
 * THIS leaderId belongs to the caller's mobile+name; two different leaders
 * who happened to propose the same address (a shared household email, or a
 * typo) must each independently prove control of it and each only commits
 * their own row, never each other's.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';

const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 20 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const body = await request.json().catch(() => ({}));
    const leaderId = typeof body.leaderId === 'string' ? body.leaderId : '';
    if (!leaderId) {
      return NextResponse.json({ error: 'Invalid or expired confirmation link' }, { status: 400 });
    }

    const authHeader = request.headers.get('authorization');
    const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user?.email) {
      return NextResponse.json({ error: 'Invalid or expired confirmation link' }, { status: 401 });
    }
    const email = user.email.toLowerCase();

    const { data: existingRow, error: fetchError } = await supabaseAdmin
      .from('state_leaders')
      .select('id, email')
      .eq('id', leaderId)
      .eq('pending_email', email)
      .maybeSingle();
    if (fetchError) {
      console.error('confirm-email: failed to look up pending_email:', fetchError);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }
    if (!existingRow) {
      return NextResponse.json({ error: 'This confirmation link is no longer valid.' }, { status: 404 });
    }

    const { error: updateError } = await supabaseAdmin
      .from('state_leaders')
      .update({
        email,
        user_id: user.id,
        email_confirmed_at: new Date().toISOString(),
        pending_email: null,
      })
      .eq('id', leaderId)
      .eq('pending_email', email);

    if (updateError) {
      // state_leaders.email has no uniqueness constraint (deliberately — see
      // scripts/drop_state_leaders_email_unique_index.sql: several leaders
      // legitimately hold more than one row in the SAME state — an AD row,
      // an SR row, and/or a plain leader row — and may have only one real
      // email to give all of them). This branch is a generic fallback for
      // any future constraint on these columns, not a currently-reachable
      // path.
      if (updateError.code === '23505') {
        return NextResponse.json(
          { error: 'This email could not be confirmed due to a conflicting record. Contact an admin.' },
          { status: 409 },
        );
      }
      console.error('confirm-email: failed to commit email:', updateError);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    // Best-effort audit trail — never blocks the confirmation that already succeeded above.
    try {
      await supabaseAdmin.from('state_leader_email_changes').insert([
        { state_leader_id: existingRow.id, old_email: existingRow.email, new_email: email, source: 'self-serve' },
      ]);
    } catch (auditErr) {
      console.error('confirm-email: failed to record audit row(s):', auditErr);
    }

    return NextResponse.json({ ok: true, email });
  } catch (err) {
    console.error('confirm-email API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * Server-side grant of a session's user_profiles / user_roles rows — see
 * lib/services/sessionAccessService.ts for what is verified and why this
 * moved off the browser. Bearer token only; supabaseAdmin.auth.getUser is
 * the ONLY trusted source of who is asking.
 *
 * POST body: { method: 'mobile-name', leaderId, mobile, firstName }
 *          | { method: 'real-auth', leaderId }
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { getAalFromJwt, grantSessionAccess, type GrantRequest } from '@/lib/services/sessionAccessService';

// Per IP, 20 attempts per 15 minutes — a normal sign-in makes exactly one
// call here (after validate-leader's own 10/15min), so this only bites repeated guessing.
const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 20 });

function parseRequest(body: unknown): GrantRequest | null {
  if (!body || typeof body !== 'object') return null;
  const b = body as Record<string, unknown>;
  const leaderId = typeof b.leaderId === 'string' ? b.leaderId : '';
  if (!leaderId || leaderId.length > 100) return null;

  if (b.method === 'real-auth') return { method: 'real-auth', leaderId };
  if (b.method === 'mobile-name') {
    const mobile = typeof b.mobile === 'string' ? b.mobile : '';
    const firstName = typeof b.firstName === 'string' ? b.firstName : '';
    if (!mobile || !firstName || mobile.length > 20 || firstName.length > 100) return null;
    return { method: 'mobile-name', leaderId, mobile, firstName };
  }
  return null;
}

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const authHeader = request.headers.get('authorization');
    const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) {
      return NextResponse.json({ error: 'Invalid or expired session' }, { status: 401 });
    }

    const grantRequest = parseRequest(await request.json().catch(() => null));
    if (!grantRequest) return NextResponse.json({ error: 'Invalid request' }, { status: 400 });

    const result = await grantSessionAccess(supabaseAdmin, {
      userId: user.id,
      aal: getAalFromJwt(token),
      request: grantRequest,
    });
    if (!result.ok) return NextResponse.json({ error: result.error, code: result.code }, { status: result.status });

    return NextResponse.json({ ok: true });
  } catch (err) {
    console.error('grant-session-access API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/auth/propose-email/route.ts:
/**
 * Leader self-serve email capture — step 1 of 2 (see confirm-email/route.ts
 * for step 2). POST body: { leaderId, mobile, firstName, email }
 *
 * A bare leaderId is never trusted on its own: the caller must also supply
 * the same mobile+name pair validate-leader already confirmed, re-verified
 * here via findVerifiedStateLeaders — otherwise anyone who observed a
 * leaderId (e.g. in network traffic) could propose an email for a leader
 * they don't actually know the mobile+name for, sending an unwanted
 * magic-link email to whatever address they typed.
 *
 * Writes state_leaders.pending_email and sends a real Supabase magic link
 * to it. Nothing is committed to state_leaders.email until the leader
 * clicks that link and confirm-email/route.ts verifies it — see that
 * file's comment for why signInWithOtp is safe to call server-side here
 * (this project's magic-link flow is implicit/#hash, not PKCE, so there's
 * no browser-bound code verifier tying the send to this request).
 *
 * The redirect URL is built from request.nextUrl.origin — the origin this
 * request actually arrived on — NOT lib/siteUrl.ts's getSiteUrl(). That
 * helper is designed for <head> metadata (OG tags, canonical URLs), where
 * always resolving to the production domain regardless of environment is
 * the point; here it's wrong, since a magic link needs to return the
 * leader to whichever deployment actually sent it (a Vercel preview during
 * testing, or production once merged) — getSiteUrl() would send every
 * preview-deployment test back to production instead, 404ing on a route
 * that isn't merged/deployed there yet (confirmed live during this
 * feature's own rollout testing).
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { isValidEmail } from '@/lib/validation';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { findVerifiedStateLeaders } from '@/lib/services/leaderVerificationService';

// Lower than validate-leader's 10/15min — each successful call sends a real email.
const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 5 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const body = await request.json();
    const leaderId  = typeof body.leaderId  === 'string' ? body.leaderId  : '';
    const mobile    = typeof body.mobile    === 'string' ? body.mobile    : '';
    const firstName = typeof body.firstName === 'string' ? body.firstName : '';
    const email     = typeof body.email     === 'string' ? body.email     : '';

    if (!leaderId || mobile.length > 20 || firstName.length > 100 || email.length > 254) {
      return NextResponse.json({ error: 'Invalid request' }, { status: 400 });
    }

    if (!isValidEmail(email)) {
      return NextResponse.json({ error: 'Please enter a valid email address' }, { status: 400 });
    }

    const verified = await findVerifiedStateLeaders(mobile, firstName);
    const match = verified.find((v) => v.id === leaderId);
    if (!match) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 });
    }

    const normalizedEmail = email.trim().toLowerCase();

    const { error: updateError } = await supabaseAdmin
      .from('state_leaders')
      .update({ pending_email: normalizedEmail })
      .eq('id', leaderId);
    if (updateError) {
      console.error('propose-email: failed to write pending_email:', updateError);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    // leaderId travels with the redirect so confirm-email can scope its commit to
    // THIS specific row rather than any row that happens to share pending_email —
    // otherwise two different leaders proposing the same address (e.g. a shared
    // household email, or one mistyping another's) would let whichever one
    // confirms first silently attach their auth identity to the other's row too.
    const redirectUrl = new URL('/confirm-email', request.nextUrl.origin);
    redirectUrl.searchParams.set('leaderId', leaderId);

    const { error: otpError } = await supabaseAdmin.auth.signInWithOtp({
      email: normalizedEmail,
      options: {
        shouldCreateUser: true,
        emailRedirectTo: redirectUrl.toString(),
      },
    });
    if (otpError) {
      console.error('propose-email: failed to send magic link:', otpError);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    return NextResponse.json({ ok: true });
  } catch (err) {
    console.error('propose-email API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/auth/request-mfa-setup/route.ts:
/**
 * "Send me a link to set up MFA" — step 1 of 2 (see complete-mfa-setup/
 * route.ts for step 2). POST body: { leaderId, mobile, firstName }.
 *
 * leaderId identifies the SPECIFIC row the leader is currently signed in
 * as, mirroring propose-email/route.ts's own scoping — findVerifiedStateLeaders
 * may return several of a multi-row person's rows (a multi-state leader,
 * or an AD/SR/plain-leader trio), and those rows can carry DIFFERENT
 * confirmed emails if the person signed in and confirmed under different
 * mobile+name pairs. Picking an arbitrary matching row (rather than the
 * one the leader actually clicked "Set up now" from) risks emailing the
 * magic link to an inbox they don't have on hand right now. Re-verify
 * mobile+name via findVerifiedStateLeaders (never trust a bare
 * identifier from the client), confirm leaderId is among the verified
 * matches AND has a confirmed email, then send a real Supabase magic
 * link to that address; completion is handled by app/setup-mfa/page.tsx
 * + complete-mfa-setup/route.ts, not here.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { findVerifiedStateLeaders } from '@/lib/services/leaderVerificationService';

const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 5 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const body = await request.json();
    const leaderId  = typeof body.leaderId  === 'string' ? body.leaderId  : '';
    const mobile    = typeof body.mobile    === 'string' ? body.mobile    : '';
    const firstName = typeof body.firstName === 'string' ? body.firstName : '';

    if (!leaderId || mobile.length > 20 || firstName.length > 100) {
      return NextResponse.json({ error: 'Invalid request' }, { status: 400 });
    }

    const verified = await findVerifiedStateLeaders(mobile, firstName);
    const match = verified.find((v) => v.id === leaderId);
    if (!match) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 403 });
    }
    if (!match.email) {
      // Shouldn't be reachable from the UI (the leader only sees this step
      // once match.email is set on the login page) — but must not
      // silently no-op if it is.
      return NextResponse.json({ error: 'No confirmed email on file yet' }, { status: 400 });
    }

    const redirectUrl = new URL('/setup-mfa', request.nextUrl.origin);
    // Always carries a query so the email template can append &token_hash=... (lib/magicLinkToken.ts)
    redirectUrl.searchParams.set('via', 'email');

    const { error: otpError } = await supabaseAdmin.auth.signInWithOtp({
      email: match.email,
      options: {
        // Not false: a row whose email was entered by an admin (which counts
        // as confirmed) may have no auth account yet — verified mobile+name
        // plus that row's own email is enough authority to create it.
        shouldCreateUser: true,
        emailRedirectTo: redirectUrl.toString(),
      },
    });
    if (otpError) {
      console.error('request-mfa-setup: failed to send magic link:', otpError);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    return NextResponse.json({ ok: true });
  } catch (err) {
    console.error('request-mfa-setup API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

