    return NextResponse.json({ error: message }, { status: 500 });
  }
}

app/api/cron/weekly-refresh/route.ts:
/**
 * Vercel Cron — Weekly Campaign Refresh
 *
 * Scheduled to run every Sunday at 01:00 UTC (see vercel.json).
 * Vercel automatically attaches an Authorization: Bearer <CRON_SECRET> header
 * so the endpoint is not callable by anyone without that secret.
 *
 * Can also be triggered manually for testing:
 *   curl -X GET https://<domain>/api/cron/weekly-refresh \
 *        -H "Authorization: Bearer <CRON_SECRET>"
 */

import { NextRequest, NextResponse } from 'next/server';
import type { SupabaseClient } from '@supabase/supabase-js';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { runWeeklyRefresh } from '@/lib/services/weeklyRefreshService';
import { getErrorMessage } from '@/lib/errorUtils';

// ---------------------------------------------------------------------------
// Anonymous user cleanup
// Every login creates a fresh anonymous Supabase auth user. This function
// removes any that haven't been active for > 90 days, keeping the auth table
// from growing unboundedly.
// ---------------------------------------------------------------------------
async function pruneStaleAnonymousUsers(client: SupabaseClient): Promise<number> {
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - 90);

  let pruned = 0;
  let page = 1;

  for (;;) {
    const { data: { users }, error } = await client.auth.admin.listUsers({ page, perPage: 100 });
    if (error) throw error;
    if (!users.length) break;

    for (const u of users) {
      if (!u.is_anonymous) continue;
      const lastActive = u.last_sign_in_at
        ? new Date(u.last_sign_in_at)
        : new Date(u.created_at ?? 0);
      if (lastActive < cutoff) {
        const { error: delErr } = await client.auth.admin.deleteUser(u.id);
        if (!delErr) pruned++;
      }
    }

    if (users.length < 100) break;
    page++;
  }

  return pruned;
}

export async function GET(request: NextRequest) {
  // ------------------------------------------------------------------
  // Auth: only accept calls with the Vercel-injected CRON_SECRET
  // ------------------------------------------------------------------
  const authHeader = request.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error('[cron/weekly-refresh] SUPABASE_SERVICE_ROLE_KEY is not set');
    return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
  }

  // ------------------------------------------------------------------
  // Run the refresh (userId = null → auto)
  // ------------------------------------------------------------------
  try {
    const result = await runWeeklyRefresh(supabaseAdmin, null);
    console.log(
      `[cron/weekly-refresh] OK — created=${result.created} skipped=${result.skipped} deleted=${result.deleted} logsPruned=${result.logsPruned}`
    );

    // Best-effort: prune anonymous auth users inactive for > 90 days.
    let usersPruned = 0;
    try {
      usersPruned = await pruneStaleAnonymousUsers(supabaseAdmin);
      if (usersPruned > 0) console.log(`[cron/weekly-refresh] pruned ${usersPruned} stale anonymous users`);
    } catch (pruneErr) {
      console.error('[cron/weekly-refresh] anonymous user prune failed:', pruneErr);
    }

    return NextResponse.json({ success: true, ...result, usersPruned });
  } catch (err) {
    const message = getErrorMessage(err, 'Weekly refresh failed');
    console.error('[cron/weekly-refresh] FAILED —', message);
    // runWeeklyRefresh already writes the error to weekly_refresh_log
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

/**
 * Leader-facing "is this person registered?" check against
 * registry.registrants — see lib/services/registrationCheckService.ts for
 * the matching rules and what is deliberately never returned.
 *
 * Goes through the service role because no main-app session can read the
 * registry schema; the caller must therefore be proven here to be a real
 * state_leaders row (any role), not merely signed in.
 *
 * POST body: { firstName, lastName, email?, mobile? }  (email or mobile required)
 * Authorization: Bearer <supabase_access_token>
 * Response: { status: 'registered' | 'name_mismatch' | 'not_registered', matchedOn: ('email' | 'mobile')[] }
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import {
  checkRegistration,
  isSessionForStateLeader,
  parseRegistrationCheckInput,
} from '@/lib/services/registrationCheckService';

// A leader checking the people in front of them needs a handful of lookups;
// these only bite someone working through a list of emails/numbers to see
// who is in the registry. Per IP before auth (looser, since several leaders
// can share one venue's Wi-Fi), then per signed-in user (so one account
// can't dodge the limit by changing network).
const ipRateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 60 });
const userRateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 30 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  if (ipRateLimiter.isLimited(getClientIp(request))) {
    return NextResponse.json({ error: 'Too many checks. Please wait a few minutes and try again.' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('[leader/check-registration] SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const authHeader = request.headers.get('authorization');
    const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) {
      return NextResponse.json({ error: 'Invalid or expired session' }, { status: 401 });
    }

    if (userRateLimiter.isLimited(user.id)) {
      return NextResponse.json({ error: 'Too many checks. Please wait a few minutes and try again.' }, { status: 429 });
    }

    if (!(await isSessionForStateLeader(supabaseAdmin, user.id))) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const parsed = parseRegistrationCheckInput(await request.json().catch(() => null));
    if (!parsed.ok) return NextResponse.json({ error: parsed.error }, { status: 400 });

    const result = await checkRegistration(supabaseAdmin, parsed.input);
    return NextResponse.json(result);
  } catch (err) {
    console.error('[leader/check-registration] exception:', err);
    return NextResponse.json({ error: 'The check could not be completed. Please try again.' }, { status: 500 });
  }
}

