  getVisibleInterestCounts: (...a: unknown[]) => mockCounts(...a),
}));

import { POST } from '../route';

function req(body: unknown, token?: string) {
  return new NextRequest('http://localhost/api/leader/interest-counts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: JSON.stringify(body),
  });
}

beforeEach(() => {
  process.env.SUPABASE_SERVICE_ROLE_KEY = 'svc';
  process.env.NEXT_PUBLIC_SUPABASE_URL = 'http://sb.test';
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY = 'anon';
  mockGetUser.mockReset().mockResolvedValue({ data: { user: { id: 'u1' } }, error: null });
  mockCounts.mockReset().mockResolvedValue({ campaignInterest: { c1: 2 }, trainingInterest: {} });
  mockCreateClient.mockClear();
});

describe('POST /api/leader/interest-counts', () => {
  it('401 without a token, touching nothing', async () => {
    expect((await POST(req({ campaignIds: ['c1'] }))).status).toBe(401);
    expect(mockGetUser).not.toHaveBeenCalled();
    expect(mockCounts).not.toHaveBeenCalled();
  });

  it('401 for an invalid session', async () => {
    mockGetUser.mockResolvedValue({ data: { user: null }, error: { message: 'bad' } });
    expect((await POST(req({ campaignIds: ['c1'] }, 'bad'))).status).toBe(401);
    expect(mockCounts).not.toHaveBeenCalled();
  });

  it('400 for a malformed or oversized id list', async () => {
    expect((await POST(req({ campaignIds: 'c1' }, 't'))).status).toBe(400);
    expect((await POST(req({ campaignIds: [1] }, 't'))).status).toBe(400);
    expect((await POST(req({ campaignIds: Array(501).fill('x') }, 't'))).status).toBe(400);
    expect(mockCounts).not.toHaveBeenCalled();
  });

  it('returns counts, computed with a client that carries the CALLER\'s own token (so RLS decides what they can see)', async () => {
    const res = await POST(req({ campaignIds: ['c1'] }, 'tok-1'));
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({ campaignInterest: { c1: 2 }, trainingInterest: {} });
    const options = (mockCreateClient.mock.calls[0] as unknown[])[2] as { global: { headers: { Authorization: string } } };
    expect(options.global.headers.Authorization).toBe('Bearer tok-1');
    expect(mockCounts).toHaveBeenCalledWith({ marker: 'user-client' }, expect.anything(), ['c1']);
  });

  it('500 (no details leaked) if the lookup throws', async () => {
    mockCounts.mockRejectedValue(new Error('db down'));
    const res = await POST(req({ campaignIds: ['c1'] }, 't'));
    expect(res.status).toBe(500);
    expect(JSON.stringify(await res.json())).not.toContain('db down');
  });
});

app/api/leader/interest-counts/route.ts:
/**
 * Per-campaign counts of members who registered interest — numbers only (no
 * personal details), for any signed-in leader, for the campaigns that leader
 * can see. See lib/services/interestCountsService.ts for why this exists
 * (members' details need a 2FA-level session; the count does not).
 * POST body: { campaignIds: string[] }. Authorization: Bearer <access token>.
 */
import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { getVisibleInterestCounts, MAX_CAMPAIGN_IDS } from '@/lib/services/interestCountsService';

const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 120 });

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const authHeader = request.headers.get('authorization');
    const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
    if (!token) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) return NextResponse.json({ error: 'Invalid or expired session' }, { status: 401 });

    const body = await request.json().catch(() => null);
    const ids: unknown = body?.campaignIds;
    if (!Array.isArray(ids) || ids.length > MAX_CAMPAIGN_IDS || !ids.every((i) => typeof i === 'string' && i.length <= 100)) {
      return NextResponse.json({ error: 'Invalid request' }, { status: 400 });
    }

    // A client carrying the caller's own JWT, so RLS decides which campaigns they can see.
    const userClient = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
      global: { headers: { Authorization: `Bearer ${token}` } },
      auth: { persistSession: false, autoRefreshToken: false },
    });

    return NextResponse.json(await getVisibleInterestCounts(userClient, supabaseAdmin, ids as string[]));
  } catch (err) {
    console.error('interest-counts API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/campaign-results/route.ts:
/**
 * Public, unauthenticated data source for the "Campaign Results" page
 * (/public/campaign-results). Mirrors the "All States" path of
 * fetchReportRows (lib/reportGenerator.ts) — the same pipeline behind
 * AdminQuickActions' "Campaign Results" button — but:
 *  - runs server-side with the service role, since anonymous visitors have
 *    no RLS access to `campaigns`/`results`
 *  - covers the week the last Weekly Refresh kept, all states, and keeps
 *    showing it until the next refresh — see
 *    lib/services/publicCampaignResultsService.ts. No SR/admin state
 *    filtering, since there's no logged-in user to derive one from
 *  - caches the result briefly, since every caller gets the same data
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { formatDateForDb } from '@/lib/campaignDates';
import { getDisplayedResultsWeekStart, getLastSuccessfulWeeklyRefreshAt } from '@/lib/services/publicCampaignResultsService';
import { fetchReportRows, type ReportRow } from '@/lib/reportGenerator';

// Generous limit — this is a read-only, public-safe endpoint; the rate limit
// exists to blunt scripted hammering, not to gate legitimate sharing.
const rateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });

export interface CampaignResultsResponse {
  rows: ReportRow[];
  /** Monday (YYYY-MM-DD) of the campaign week `rows` covers. */
  weekStart: string;
}

// ---------------------------------------------------------------------------
// Short-lived in-memory cache — one entry, since the response is identical
// for every caller (all states, same week). Purely time-based: which week is
// shown depends on the refresh log, so there's no cheap key to compare first.
// ---------------------------------------------------------------------------
const CACHE_TTL_MS = 60 * 1000;
let cache: { expiresAt: number; response: CampaignResultsResponse } | null = null;

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    if (cache && cache.expiresAt > Date.now()) {
      return NextResponse.json(cache.response);
    }

    const weekStart = getDisplayedResultsWeekStart(await getLastSuccessfulWeeklyRefreshAt(supabaseAdmin));
    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekEnd.getDate() + 6);
    const startDate = formatDateForDb(weekStart);
    const endDate = formatDateForDb(weekEnd);

    let rows: ReportRow[] = [];
    try {
      rows = await fetchReportRows({ supabase: supabaseAdmin, startDate, endDate });
    } catch (err) {
      // fetchReportRows throws a plain Error when there are no campaigns/no
      // recorded results in range — that's a normal "nothing to show yet"
      // state for a public link, not a server error. Anything else (a real
      // Postgrest error) is rethrown to the outer catch below.
      const msg = err instanceof Error ? err.message : '';
      if (!msg.includes('No campaigns found') && !msg.includes('No results recorded')) {
        throw err;
      }
    }

    const response: CampaignResultsResponse = { rows, weekStart: startDate };
    cache = { expiresAt: Date.now() + CACHE_TTL_MS, response };

    return NextResponse.json(response);
  } catch (err) {
    console.error('public campaign-results API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/campaigns-near-me/route.t:
/**
 * Public, unauthenticated "Campaigns Near Me" screen for a registry
 * registrant reached via a personalized link in their WhatsApp-invite
 * email (lib/registryPipeline/whatsappInvite.ts) — see
 * app/public/campaigns-near-me/page.tsx.
 *
 * GET  — map data for one registrant, identified by `?r=<registry.registrants.id>`
 *        (never their raw name/email/mobile/postcode in the URL — those
 *        stay server-side, looked up by this opaque id, the same pattern
 *        /public/training/[campaignId] uses for a campaign id). Centres
 *        the map on their postcode (falling back to a state-level centre
 *        if no postcode is on file — postcode is only populated for
 *        registrations from ~2026-08-26 onward), for the 7 days starting
 *        today, within RADIUS_KM. Coordinates are cached state_places
 *        values only — no on-demand geocoding of a place, which needs the
 *        admin-only /api/admin/geocode-place route an anonymous visitor
 *        can't call; an unresolved place is simply omitted, same as the
 *        admin map's own established behaviour for one it can't place.
 * POST — records interest in one campaign for that same registrant,
 *        without asking them to re-type their name/mobile/email (unlike
 *        the general-public /api/public/register-interest, which has no
 *        identity to look those up from) — re-derived server-side from
 *        the registrant id every time, so the write can't be tampered
 *        with via the request body.
 *
 * Not in-memory cached like the other /api/public/* GETs — each request
 * is personalized to one registrant, not identical for every caller, same
 * reasoning as /public/training/[campaignId]'s GET.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { formatDateForDb } from '@/lib/campaignDates';
import { isCampaignPast } from '@/lib/campaignUtils';
import { normalizeMobile } from '@/lib/auth';
import { geocodeAddress } from '@/lib/geocoding';
import { notifyLeadersOfCampaignInterest, type CampaignInterestType } from '@/lib/services/campaignInterestSmsService';
import {
  buildNearbyMarkers,
  type CampaignsNearMeResponse,
  type PublicNearbyCampaignRow,
  type PublicPlaceCoords,
} from '@/lib/services/publicCampaignsNearMeService';

const RADIUS_KM = 60; // Same default as the admin "Campaigns Near Me" map.
const WINDOW_DAYS = 7; // Today + the next 6 days, per Peter's request.

const getRateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });
const postRateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 10 });

interface RegistrantLocation {
  first_name: string | null;
  email: string | null;
  phone: string | null;
  state: string | null;
  postcode: string | null;
}

async function getRegistrant(id: string): Promise<RegistrantLocation | null> {
  const { data, error } = await supabaseAdmin
    .schema('registry')
    .from('registrants')
    .select('first_name, email, phone, state, postcode')
    .eq('id', id)
    .maybeSingle();
  if (error) throw error;
  return (data as RegistrantLocation | null) ?? null;
}

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (getRateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  const registrantId = request.nextUrl.searchParams.get('r');
  if (!registrantId) {
    return NextResponse.json({ error: 'Missing registrant id' }, { status: 400 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('[public/campaigns-near-me] SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const registrant = await getRegistrant(registrantId);
    if (!registrant) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    const today = new Date();
    const endDate = new Date(today);
    endDate.setDate(endDate.getDate() + WINDOW_DAYS - 1);
    const startDateStr = formatDateForDb(today);
    const endDateStr = formatDateForDb(endDate);

    // No postcode on file (common for anyone registered before ~2026-08-26)
    // falls back to a state-level centre — coarser, but still useful;
    // neither postcode nor state means there's nothing to centre a map on.
    const noLocationResponse = () => {
      const body: CampaignsNearMeResponse = {
        firstName: registrant.first_name,
        startDate: startDateStr,
        endDate: endDateStr,
        radiusKm: RADIUS_KM,
        center: null,
        markers: [],
        unresolvedCount: 0,
      };
      return NextResponse.json(body);
    };

    const geocodeQuery = registrant.postcode
      ? `${registrant.postcode} ${registrant.state ?? ''}, Australia`
      : registrant.state
        ? `${registrant.state}, Australia`
        : null;
    if (!geocodeQuery) {
      return noLocationResponse();
    }

    const geocoded = await geocodeAddress(geocodeQuery);
    if (!geocoded) {
      return noLocationResponse();
    }

    const [{ data: campaignRows, error: campaignError }, { data: placeRows, error: placeError }] = await Promise.all([
      supabaseAdmin
        .from('campaigns')
        .select('id, date, state, place, time, leader, category')
        .gte('date', startDateStr)
        .lte('date', endDateStr)
        .order('date', { ascending: true })
        .order('time', { ascending: true }),
      supabaseAdmin
        .from('state_places')
        .select('state, place, latitude, longitude')
        .not('latitude', 'is', null)
        .not('longitude', 'is', null),
    ]);
    if (campaignError) throw campaignError;
    if (placeError) throw placeError;

    const upcoming = ((campaignRows ?? []) as PublicNearbyCampaignRow[]).filter((c) => !isCampaignPast(c.date, c.time));
    const placeCoords = (placeRows ?? []) as PublicPlaceCoords[];

    const { markers, unresolvedCount } = buildNearbyMarkers(
      upcoming,
      placeCoords,
      { latitude: geocoded.latitude, longitude: geocoded.longitude },
      RADIUS_KM,
    );

    const body: CampaignsNearMeResponse = {
      firstName: registrant.first_name,
      startDate: startDateStr,
      endDate: endDateStr,
      radiusKm: RADIUS_KM,
      center: { latitude: geocoded.latitude, longitude: geocoded.longitude, label: geocoded.displayName },
      markers,
      unresolvedCount,
    };
    return NextResponse.json(body);
  } catch (err) {
    console.error('[public/campaigns-near-me] GET error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (postRateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('[public/campaigns-near-me] SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const body: unknown = await request.json();
    const bodyObj = (body && typeof body === 'object' ? body : {}) as Record<string, unknown>;
    const registrantId = typeof bodyObj.registrantId === 'string' ? bodyObj.registrantId : '';
    const campaignId = typeof bodyObj.campaignId === 'string' ? bodyObj.campaignId : '';
    const interestType = bodyObj.interestType;

    if (!registrantId || !campaignId) {
      return NextResponse.json({ error: 'Missing registrant or campaign id' }, { status: 400 });
    }
    if (interestType !== 'in' && interestType !== 'more') {
      return NextResponse.json({ error: 'Invalid interest type' }, { status: 400 });
    }

    const registrant = await getRegistrant(registrantId);
    if (!registrant) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    // Same requirement campaign_interest's own CHECK constraint enforces
    // (campaign_interest_contact_required) — checked here too so this
    // returns a clear error instead of a raw DB constraint failure.
    if (!registrant.email && !registrant.phone) {
      return NextResponse.json({ error: 'No contact details on file for this registration' }, { status: 400 });
    }

    const { error } = await supabaseAdmin.from('campaign_interest').insert({
      campaign_id: campaignId,
      // Falls back to a placeholder rather than failing outright — first_name
      // is NOT NULL on campaign_interest, and while every registrant should
      // have one (mapAcFields always attempts to capture it), a national
      // admin could have cleared it via /registry/manage's Edit mode.
      first_name: registrant.first_name?.trim() || 'AFJ Registrant',
      // registry.registrants.phone is E.164 ('+61...'); campaign_interest's
      // other rows are in the local '0XXXXXXXXX' format the rest of the app
      // uses (whatever a visitor typed into the public form) — normalized
      // here so this table doesn't end up with two different formats.
      mobile: registrant.phone ? normalizeMobile(registrant.phone) : null,
      email: registrant.email,
      interest_type: interestType,
    });
    if (error) {
      console.error('[public/campaigns-near-me] POST insert error:', error);
      return NextResponse.json({ error: 'Failed to register your interest' }, { status: 500 });
    }

    // Best-effort — a leader-notification failure must never turn into a
    // 500 for someone who has already successfully registered interest.
    try {
      await notifyLeadersOfCampaignInterest(supabaseAdmin, {
        campaignIds: [campaignId],
        registrantFirstName: registrant.first_name?.trim() || 'AFJ Registrant',
        interestType: interestType as CampaignInterestType,
      });
    } catch (notifyErr) {
      console.error('[public/campaigns-near-me] leader SMS notification error:', notifyErr);
    }

    return NextResponse.json({ success: true });
  } catch (err) {
    console.error('[public/campaigns-near-me] POST error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/final-campaign-lists/rout:
/**
 * Public, unauthenticated data source for the "Final AFJ Campaign Lists"
 * page (/public/final-campaign-lists). Same fortnight, same all-states data
 * as /api/public/temporary-upcoming-campaigns — the query itself lives in
 * lib/services/publicCampaignListService.ts and is shared between the two
 * routes. This page is the "final" read-only list (Download only, no Edit),
 * shown once leaders have finished making changes on the temporary list.
 */
import { NextRequest, NextResponse } from 'next/server';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { fetchFortnightCampaignDays, getUpcomingFortnightDateStrings } from '@/lib/services/publicCampaignListService';
import type { PublicSlideDay } from '@/lib/slideGenerator';

const rateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });

export interface FinalCampaignListsResponse {
  days: PublicSlideDay[];
}

// Short-lived in-memory cache — one entry, since the response is identical
// for every caller (all states, current fortnight).
const CACHE_TTL_MS = 60 * 1000;
let cache: { key: string; expiresAt: number; response: FinalCampaignListsResponse } | null = null;

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const dateStrings = getUpcomingFortnightDateStrings();
    const cacheKey = dateStrings[0];

    if (cache && cache.key === cacheKey && cache.expiresAt > Date.now()) {
      return NextResponse.json(cache.response);
    }

    const days = await fetchFortnightCampaignDays(dateStrings);
    const response: FinalCampaignListsResponse = { days };
    cache = { key: cacheKey, expiresAt: Date.now() + CACHE_TTL_MS, response };

    return NextResponse.json(response);
  } catch (err) {
    console.error('public final-campaign-lists API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/geocode-postcode/route.ts:
/**
 * Public, unauthenticated postcode lookup for the "Upcoming Campaigns" map's
 * "Show me Campaigns Near Me" field (/public/upcoming-campaigns). Unlike
 * the admin campaign map's browser-geolocation "Near Me" button, a public
 * visitor types their own postcode instead — this just geocodes it and
 * hands back coordinates for the page to recentre its existing marker set
 * on (no radius re-filtering, same as the admin map's own "Near Me" —
 * see app/public/upcoming-campaigns/UpcomingCampaignsClient.tsx).
 */
import { NextRequest, NextResponse } from 'next/server';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { geocodeAddress } from '@/lib/geocoding';

const rateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 20 });

const POSTCODE_PATTERN = /^\d{4}$/;

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    const body: unknown = await request.json();
    const bodyObj = (body && typeof body === 'object' ? body : {}) as Record<string, unknown>;
    const postcode = typeof bodyObj.postcode === 'string' ? bodyObj.postcode.trim() : '';

    if (!POSTCODE_PATTERN.test(postcode)) {
      return NextResponse.json({ error: 'Please enter a valid 4-digit postcode' }, { status: 400 });
    }

    const geocoded = await geocodeAddress(`${postcode}, Australia`);
    if (!geocoded) {
      return NextResponse.json({ error: `No location found for postcode ${postcode}` }, { status: 404 });
    }

    return NextResponse.json({
      latitude: geocoded.latitude,
      longitude: geocoded.longitude,
      displayName: geocoded.displayName,
    });
  } catch (err) {
    console.error('[public/geocode-postcode] POST error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/register-interest/route.t:
/**
 * Public, unauthenticated data source + submission endpoint for the
 * Register Interest screen (app/public/register-interest, and the
 * admin-only next-fortnight preview at app/admin/register-interest).
 *
 * GET  — public-safe campaigns for a fortnight (all states; the client
 *        filters by state itself, same as the other /public/* GET routes —
 *        one cached response per window serves every caller). Defaults to
 *        the current fortnight; `?period=next` shifts the window to the
 *        fortnight starting right after the current one ends, for the
 *        admin preview screen. This data is already fully public regardless
 *        of who's asking (no PII, same shape as the other public campaign
 *        lists), so the extra window isn't gated — only the admin *button*
 *        that links to it is.
 * POST — records interest against one or more campaigns. This is the
 *        first *write* on a /public/* route: anonymous visitors have no
 *        RLS access to campaign_interest (its policy is admin/owning-leader
 *        only, see supabase/rls-policies.sql), so this uses the service
 *        role and does its own input validation in place of the RLS check.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { calculateCampaignDates, formatDateForDb, getFortnightDateRange } from '@/lib/campaignDates';
import { isCampaignPast } from '@/lib/campaignUtils';
import { isValidMobile, isValidEmail } from '@/lib/validation';
import type { AriseCampaign } from '@/lib/ariseLayout';
import { notifyLeadersOfCampaignInterest, type CampaignInterestType } from '@/lib/services/campaignInterestSmsService';

const getRateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });
// Writes get a tighter, longer-window limit than the read-only public GETs —
// matches /api/auth/validate-leader's 10-per-15-minutes for a similar
// legitimate-visitor-submits-a-form-a-few-times shape.
const postRateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 10 });

const MAX_FIRST_NAME_LENGTH = 100;
const MAX_MOBILE_LENGTH = 20;
const MAX_EMAIL_LENGTH = 200;
const MAX_CAMPAIGN_IDS = 50;

export interface RegisterInterestGetResponse {
  campaigns: AriseCampaign[];
}

// Short-lived in-memory cache — the GET response is identical for every
// caller asking for the same window (all states), but there are now two
// possible windows (current / next), so this is keyed per-window rather
// than a single slot to avoid the two constantly evicting each other.
const CACHE_TTL_MS = 60 * 1000;
const cache = new Map<string, { expiresAt: number; response: RegisterInterestGetResponse }>();

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (getRateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const isNextPeriod = request.nextUrl.searchParams.get('period') === 'next';
    const { upcomingCampaignStart } = calculateCampaignDates();
    let periodStart = upcomingCampaignStart;
    if (isNextPeriod) {
      periodStart = new Date(upcomingCampaignStart);
      periodStart.setDate(periodStart.getDate() + 14);
    }
    const dates = getFortnightDateRange(periodStart);
    const dateStrings = dates.map(formatDateForDb);
    const cacheKey = `${isNextPeriod ? 'next' : 'current'}:${dateStrings[0]}`;

    const cached = cache.get(cacheKey);
    if (cached && cached.expiresAt > Date.now()) {
      return NextResponse.json(cached.response);
    }

    const { data, error } = await supabaseAdmin
      .from('campaigns')
      .select('id, date, state, place, site, time, leader, category')
      .gte('date', dateStrings[0])
      .lte('date', dateStrings[dateStrings.length - 1])
      .order('date', { ascending: true })
      .order('state', { ascending: true })
      .order('place', { ascending: true })
      .order('time', { ascending: true });

    if (error) {
      console.error('public register-interest GET error:', error);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    // Campaigns that have already started or finished are excluded — this
    // page is for finding upcoming campaigns to register interest in.
    const campaigns = ((data ?? []) as AriseCampaign[]).filter(c => !isCampaignPast(c.date, c.time));

    const response: RegisterInterestGetResponse = { campaigns };
    cache.set(cacheKey, { expiresAt: Date.now() + CACHE_TTL_MS, response });

    return NextResponse.json(response);
  } catch (err) {
    console.error('public register-interest GET exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (postRateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const body: unknown = await request.json();
    const bodyObj = (body && typeof body === 'object' ? body : {}) as Record<string, unknown>;
    const firstName = typeof bodyObj.firstName === 'string' ? bodyObj.firstName.trim() : '';
    const mobile = typeof bodyObj.mobile === 'string' ? bodyObj.mobile.trim() : '';
    const email = typeof bodyObj.email === 'string' ? bodyObj.email.trim() : '';
    const interestType = bodyObj.interestType;
    const rawCampaignIds: unknown[] = Array.isArray(bodyObj.campaignIds) ? bodyObj.campaignIds : [];

    if (!firstName || firstName.length > MAX_FIRST_NAME_LENGTH) {
      return NextResponse.json({ error: 'Please enter your first name' }, { status: 400 });
    }
    if (mobile.length > MAX_MOBILE_LENGTH || email.length > MAX_EMAIL_LENGTH) {
      return NextResponse.json({ error: 'Please check your mobile number or email address' }, { status: 400 });
    }
    // A visitor is asked for a *valid* mobile or email (not merely a
    // non-empty one) — stricter than training_interest's presence-only check,
    // since this is the field the leader will actually follow up on.
    if (!isValidMobile(mobile) && !isValidEmail(email)) {
      return NextResponse.json({ error: 'Please enter a valid mobile number or email address' }, { status: 400 });
    }
    if (interestType !== 'in' && interestType !== 'more') {
      return NextResponse.json({ error: 'Invalid interest type' }, { status: 400 });
    }
    const isValidCampaignId = (id: unknown): id is string => typeof id === 'string' && id.length > 0;
    if (
      rawCampaignIds.length === 0 ||
      rawCampaignIds.length > MAX_CAMPAIGN_IDS ||
      !rawCampaignIds.every(isValidCampaignId)
    ) {
      return NextResponse.json({ error: 'Please tick at least one campaign' }, { status: 400 });
    }
    const campaignIds = rawCampaignIds as string[];

    const rows = campaignIds.map(campaignId => ({
      campaign_id: campaignId,
      first_name: firstName,
      mobile: mobile || null,
      email: email || null,
      interest_type: interestType,
    }));

    const { error } = await supabaseAdmin.from('campaign_interest').insert(rows);
    if (error) {
      console.error('public register-interest POST error:', error);
      return NextResponse.json({ error: 'Failed to register your interest' }, { status: 500 });
    }

    // Best-effort — a leader-notification failure must never turn into a
    // 500 for someone who has already successfully registered interest.
    try {
      await notifyLeadersOfCampaignInterest(supabaseAdmin, {
        campaignIds,
        registrantFirstName: firstName,
        interestType: interestType as CampaignInterestType,
      });
    } catch (notifyErr) {
      console.error('public register-interest: leader SMS notification error:', notifyErr);
    }

    return NextResponse.json({ success: true });
  } catch (err) {
    console.error('public register-interest POST exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/temporary-upcoming-campai:
/**
 * Public, unauthenticated data source for the "Temporary Upcoming Campaigns"
 * page (/public/temporary-upcoming-campaigns). Same shape of route as
 * /api/public/week1-campaigns, but:
 *  - covers the full fortnight (14 days), matching the authenticated
 *    Register Interest screen and the "Leader Campaign Lists" download
 *  - also returns each day's campaign_messages banner text, since the
 *    response doubles as the input to generateAndDownloadSlidesFromData
 *    (lib/slideGenerator.ts) for the page's Download button — one fetch
 *    powers both the on-screen list and the ZIP
 *
 * The actual query lives in lib/services/publicCampaignListService.ts,
 * shared with /api/public/final-campaign-lists (same fortnight, same data —
 * the two pages differ only in copy/actions).
 */
import { NextRequest, NextResponse } from 'next/server';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { fetchFortnightCampaignDays, getUpcomingFortnightDateStrings } from '@/lib/services/publicCampaignListService';
import type { PublicSlideDay } from '@/lib/slideGenerator';

const rateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });

export interface TemporaryUpcomingCampaignsResponse {
  days: PublicSlideDay[];
}

// Short-lived in-memory cache — one entry, since the response is identical
// for every caller (all states, current fortnight).
const CACHE_TTL_MS = 60 * 1000;
let cache: { key: string; expiresAt: number; response: TemporaryUpcomingCampaignsResponse } | null = null;

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const dateStrings = getUpcomingFortnightDateStrings();
    const cacheKey = dateStrings[0];

    if (cache && cache.key === cacheKey && cache.expiresAt > Date.now()) {
      return NextResponse.json(cache.response);
    }

    const days = await fetchFortnightCampaignDays(dateStrings);
    const response: TemporaryUpcomingCampaignsResponse = { days };
    cache = { key: cacheKey, expiresAt: Date.now() + CACHE_TTL_MS, response };

    return NextResponse.json(response);
  } catch (err) {
    console.error('public temporary-upcoming-campaigns API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/public/training-interest/[campai:
/**
 * Public, unauthenticated data source + submission endpoint for one training
 * session's interest page (/public/training/[campaignId]). Unlike the other
 * /public/* GETs, this is scoped to a single campaign id rather than a
 * shared list — no in-memory cache, since each lookup is a single indexed
 * row rather than a table scan.
 *
 * GET  — the training campaign's public-safe details (only ever returns a
 *        campaign whose category is BOTJ or TLT — anything else 404s, same
 *        as a non-existent id, so this can't be used to peek at arbitrary
 *        non-training campaigns).
 * POST — records interest against this campaign. Anonymous visitors have no
 *        RLS access to training_interest (its policy is admin/owning-leader
 *        only, see supabase/rls-policies.sql), so this uses the service role
 *        and does its own input validation in place of the RLS check.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { isTrainingCategory } from '@/lib/services/trainingInterestService';

const getRateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });
// Writes get a tighter, longer-window limit than the read-only public GET —
// matches /api/public/register-interest's POST limit.
const postRateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 10 });

const MAX_NAME_LENGTH = 100;
const MAX_MOBILE_LENGTH = 20;
const MAX_EMAIL_LENGTH = 200;
// Deliberately loose — just enough to catch obviously-wrong input, not a
// strict RFC 5322 validator (real deliverability is confirmed by the leader
// following up, not by this check).
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export interface TrainingInterestCampaignInfo {
  id: string;
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
  category: string;
}

export interface TrainingInterestGetResponse {
  campaign: TrainingInterestCampaignInfo;
  categoryName: string;
}

/**
 * Loads one training campaign's public-safe details, or null if it doesn't
 * exist, its id isn't well-formed, or its category isn't BOTJ/TLT — all
 * treated identically (404) so this can't be used to distinguish "no such
 * campaign" from "not a training campaign". Exported so
 * app/public/training/[campaignId]/page.tsx's generateMetadata can reuse it
 * directly (server-to-server, no HTTP round trip) instead of duplicating
 * this query.
 */
export async function loadTrainingCampaign(campaignId: string): Promise<TrainingInterestCampaignInfo | null> {
  // A malformed id would otherwise reach Postgres as "invalid input syntax
  // for type uuid" and bubble up as a 500 — checked here so a garbled link
  // 404s cleanly instead.
  if (!UUID_PATTERN.test(campaignId)) return null;

  const { data, error } = await supabaseAdmin
    .from('campaigns')
    .select('id, date, state, place, site, time, leader, category')
    .eq('id', campaignId)
    .maybeSingle();

  if (error) throw error;
  if (!data || !isTrainingCategory(data.category)) return null;
  return data as TrainingInterestCampaignInfo;
}

// campaign_categories rarely changes — a short-lived cache avoids a second
// live query on every public page view just to resolve a display name.
const CATEGORY_NAME_CACHE_TTL_MS = 5 * 60 * 1000;
let categoryNameCache: { expiresAt: number; names: Map<string, string> } | null = null;

async function getCategoryName(code: string): Promise<string> {
  if (!categoryNameCache || categoryNameCache.expiresAt <= Date.now()) {
    const { data, error } = await supabaseAdmin.from('campaign_categories').select('code, name');
    if (error) {
      console.error('public training-interest: failed to load campaign_categories:', error);
      // Fall through to the code itself below rather than caching a failed lookup.
      return code;
    }
    const names = new Map((data ?? []).map((row) => [row.code as string, row.name as string]));
    categoryNameCache = { expiresAt: Date.now() + CATEGORY_NAME_CACHE_TTL_MS, names };
  }
  return categoryNameCache.names.get(code) || code;
}

export async function GET(request: NextRequest, { params }: { params: Promise<{ campaignId: string }> }) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (getRateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const { campaignId } = await params;
    const campaign = await loadTrainingCampaign(campaignId);
    if (!campaign) {
      return NextResponse.json({ error: 'Training session not found' }, { status: 404 });
    }

    const response: TrainingInterestGetResponse = {
      campaign,
      categoryName: await getCategoryName(campaign.category),
    };
    return NextResponse.json(response);
  } catch (err) {
    console.error('public training-interest GET exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

export async function POST(request: NextRequest, { params }: { params: Promise<{ campaignId: string }> }) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (postRateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const { campaignId } = await params;
    // Re-verify the campaign still exists and is a training session server-side
    // — never trust the client's word for it.
    const campaign = await loadTrainingCampaign(campaignId);
    if (!campaign) {
      return NextResponse.json({ error: 'Training session not found' }, { status: 404 });
    }

    const body: unknown = await request.json();
    const bodyObj = (body && typeof body === 'object' ? body : {}) as Record<string, unknown>;
    const name = typeof bodyObj.name === 'string' ? bodyObj.name.trim() : '';
    const mobile = typeof bodyObj.mobile === 'string' ? bodyObj.mobile.trim() : '';
    const email = typeof bodyObj.email === 'string' ? bodyObj.email.trim() : '';

    if (!name || name.length > MAX_NAME_LENGTH) {
      return NextResponse.json({ error: 'Please enter your name' }, { status: 400 });
    }
    if (!mobile && !email) {
      return NextResponse.json({ error: 'Please enter a mobile number or email address' }, { status: 400 });
    }
    if (mobile && mobile.length > MAX_MOBILE_LENGTH) {
      return NextResponse.json({ error: 'Mobile number is too long' }, { status: 400 });
    }
    if (email && (email.length > MAX_EMAIL_LENGTH || !EMAIL_PATTERN.test(email))) {
      return NextResponse.json({ error: 'Please enter a valid email address' }, { status: 400 });
    }

    const { error } = await supabaseAdmin.from('training_interest').insert({
      campaign_id: campaignId,
      name,
      mobile: mobile || null,
      email: email || null,
    });
    if (error) {
      console.error('public training-interest POST error:', error);
      return NextResponse.json({ error: 'Failed to register your interest' }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (err) {
    console.error('public training-interest POST exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

