/**
 * A short-lived link to the current CAS User Guide PDF, for the OPEN GUIDE
 * buttons — see lib/services/userGuideService.ts. Public (no sign-in) because
 * the guide is also offered on the sign-in screen for new leaders: Peter's
 * call (2026-10-15) that anyone may read it.
 *
 * Not in-memory cached like other /api/public GETs: right after an admin
 * uploads a new guide, a cached link would keep showing the old one.
 *
 * GET. Response: { url: string, uploadedAt: string } | { url: null } (none uploaded yet)
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { getUserGuideView } from '@/lib/services/userGuideService';

const rateLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 60 });

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  if (rateLimiter.isLimited(getClientIp(request))) {
    return NextResponse.json({ error: 'Too many requests. Please wait a few minutes and try again.' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('[public/user-guide] SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const view = await getUserGuideView(supabaseAdmin);
    return NextResponse.json(view ?? { url: null });
  } catch (err) {
    console.error('[public/user-guide] exception:', err);
    return NextResponse.json({ error: 'The guide could not be loaded. Please try again.' }, { status: 500 });
  }
}

app/api/public/week1-campaigns/route.ts:
/**
 * Public, unauthenticated data source for the Week 1 Campaigns list
 * (/public/week1-campaigns). Mirrors the "All States" path of
 * generateAndDownloadAriseList (lib/ariseGenerator.ts) but:
 *  - runs server-side with the service role, since anonymous visitors have
 *    no RLS access to `campaigns`
 *  - selects the same public-safe columns the authenticated generator
 *    already used (no mobile numbers, no admin-only fields)
 *  - fetches the whole 8-day window in one ranged query instead of 8
 *    sequential per-day queries, since this route is open to anyone with
 *    the link rather than gated behind an admin click
 *  - caches the result briefly, since every caller gets the same "all
 *    states, current window" data
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';
import { calculateCampaignDates, formatDateForDb } from '@/lib/campaignDates';
import { getAriseDateRange, type AriseCampaign } from '@/lib/ariseLayout';

// Generous limit — this is a read-only, public-safe endpoint; the rate limit
// exists to blunt scripted hammering, not to gate legitimate sharing.
const rateLimiter = createRateLimiter({ windowMs: 60 * 1000, maxAttempts: 30 });

export interface Week1CampaignsDay {
  date: string; // YYYY-MM-DD
  campaigns: AriseCampaign[];
}

export interface Week1CampaignsResponse {
  days: Week1CampaignsDay[];
}

// ---------------------------------------------------------------------------
// Short-lived in-memory cache — one entry, since the response is identical
// for every caller (all states, current window). Avoids hitting Postgres on
// every open of a link that may get shared and opened many times in a burst.
// ---------------------------------------------------------------------------
const CACHE_TTL_MS = 60 * 1000;
let cache: { key: string; expiresAt: number; response: Week1CampaignsResponse } | null = null;

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const ip = getClientIp(request);
  if (rateLimiter.isLimited(ip)) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 });
  }

  try {
    if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
      console.error('SUPABASE_SERVICE_ROLE_KEY is not set');
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const { upcomingCampaignStart } = calculateCampaignDates();
    const dates = getAriseDateRange(upcomingCampaignStart);
    const dateStrings = dates.map(formatDateForDb);
    const cacheKey = dateStrings[0];

    if (cache && cache.key === cacheKey && cache.expiresAt > Date.now()) {
      return NextResponse.json(cache.response);
    }

    const { data, error } = await supabaseAdmin
      .from('campaigns')
      .select('id, date, state, place, site, time, leader, category')
      .gte('date', dateStrings[0])
      .lte('date', dateStrings[dateStrings.length - 1])
      .order('state', { ascending: true })
      .order('place', { ascending: true })
      .order('time', { ascending: true });

    if (error) {
      console.error('public week1-campaigns API error:', error);
      return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }

    const campaigns = (data ?? []) as AriseCampaign[];
    const days: Week1CampaignsDay[] = dateStrings.map((date) => ({
      date,
      campaigns: campaigns.filter((c) => c.date === date),
    }));

    const response: Week1CampaignsResponse = { days };
    cache = { key: cacheKey, expiresAt: Date.now() + CACHE_TTL_MS, response };

    return NextResponse.json(response);
  } catch (err) {
    console.error('public week1-campaigns API exception:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

app/api/registry/manage-edit-log/route.t:
/**
 * Registry portal — paginated read of registry.registrant_edits (the audit
 * trail of manual corrections made from /registry/manage's Edit mode — see
 * scripts/create_registry_registrant_edits_table.sql), joined with the
 * registrant each row was about. Powers /registry/manage/edit-log.
 *
 * Admin-only, same gate as manage-summary/manage-record.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyRegistryAdminRequest } from '@/lib/registryServerAuth';
import { isNationalRegistryAdmin } from '@/lib/registryPipeline/mfaGate';
import type { RegistrantEditLogEntry, RegistrantEditLogResponse } from '@/lib/registryPipeline/manageSummaryTypes';

const PAGE_SIZE = 50;

interface EmbeddedRegistrant {
  first_name: string | null;
  last_name: string | null;
  email: string | null;
  state: string | null;
}

interface RegistrantEditRow {
  id: number;
  field: string;
  old_value: string | null;
  new_value: string | null;
  edited_by_email: string | null;
  edited_at: string;
  // supabase-js's embed shape for a to-one relation is usually a single
  // object, but isn't guaranteed by this client's (ungenerated) types —
  // handled as either below rather than trusted blindly.
  registrants: EmbeddedRegistrant | EmbeddedRegistrant[] | null;
}

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const verified = await verifyRegistryAdminRequest(supabaseAdmin, token);
  if (!verified || !isNationalRegistryAdmin(verified.leaderRole.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const pageParam = Number(request.nextUrl.searchParams.get('page') ?? '1');
  const page = Number.isFinite(pageParam) && pageParam >= 1 ? Math.floor(pageParam) : 1;
  const from = (page - 1) * PAGE_SIZE;
  const to = from + PAGE_SIZE - 1;

  try {
    const { data, count, error } = await supabaseAdmin
      .schema('registry')
      .from('registrant_edits')
      .select('id, field, old_value, new_value, edited_by_email, edited_at, registrants(first_name, last_name, email, state)', { count: 'exact' })
      .order('edited_at', { ascending: false })
      .range(from, to);
    if (error) throw error;

    const rows = (data ?? []) as unknown as RegistrantEditRow[];
    const entries: RegistrantEditLogEntry[] = rows.map((row) => {
      const embedded = Array.isArray(row.registrants) ? row.registrants[0] ?? null : row.registrants;
      return {
        id: row.id,
        field: row.field,
        oldValue: row.old_value,
        newValue: row.new_value,
        editedByEmail: row.edited_by_email,
        editedAt: row.edited_at,
        registrant: embedded
          ? { firstName: embedded.first_name, lastName: embedded.last_name, email: embedded.email, state: embedded.state }
          : null,
      };
    });

    const body: RegistrantEditLogResponse = { entries, totalCount: count ?? 0 };
    return NextResponse.json(body);
  } catch (err) {
    console.error('[registry/manage-edit-log] failed:', err);
    return NextResponse.json({ error: 'Failed to load the edit log' }, { status: 500 });
  }
}

app/api/registry/manage-record/route.ts:
/**
 * Registry portal — applies one hand-edit to a registry.registrants row
 * from the /registry/manage console's View/Edit toggle, and records it in
 * registry.registrant_edits (scripts/create_registry_registrant_edits_table.sql)
 * so every correction is attributable and reviewable later.
 *
 * Only the fields in EDITABLE_REGISTRANT_FIELDS
 * (lib/registryPipeline/registrantValidation.ts) can ever be written here —
 * whitelisted and re-validated server-side, not just hidden in the UI,
 * since email/phone are the pipeline's own identity/dedup keys and must
 * never be hand-edited from this screen (see that module's header comment).
 *
 * Admin-only, same gate as /api/registry/manage-summary — see that route's
 * header comment for the reasoning.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyRegistryAdminRequest } from '@/lib/registryServerAuth';
import { isNationalRegistryAdmin } from '@/lib/registryPipeline/mfaGate';
import {
  EDITABLE_FIELD_COLUMNS,
  isEditableRegistrantField,
  isValidRegistrantFieldValue,
} from '@/lib/registryPipeline/registrantValidation';
import type { ManageRecordEditResponse } from '@/lib/registryPipeline/manageSummaryTypes';

export async function PATCH(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const verified = await verifyRegistryAdminRequest(supabaseAdmin, token);
  if (!verified || !isNationalRegistryAdmin(verified.leaderRole.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  let body: { id?: unknown; field?: unknown; value?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const { id, field, value } = body;
  if (typeof id !== 'string' || !id) {
    return NextResponse.json({ error: 'id is required' }, { status: 400 });
  }
  if (typeof field !== 'string' || !isEditableRegistrantField(field)) {
    return NextResponse.json({ error: 'field must be one of firstName, lastName, state, postcode, nfc' }, { status: 400 });
  }
  if (value !== null && typeof value !== 'string') {
    return NextResponse.json({ error: 'value must be a string or null' }, { status: 400 });
  }

  // A blank string clears the field — normalized to null so the DB stores
  // NULL, not '', matching every other writer of this table.
  const normalized = value === null || value.trim() === '' ? null : value.trim();
  if (!isValidRegistrantFieldValue(field, normalized)) {
    return NextResponse.json({ error: `Invalid value for ${field}` }, { status: 400 });
  }

  const column = EDITABLE_FIELD_COLUMNS[field];

  try {
    // Selecting the full set of editable columns (rather than building a
    // select() string from `column` dynamically) keeps this statically
    // typed — supabase-js can't type-check a runtime-computed column list.
    const { data: existing, error: fetchError } = await supabaseAdmin
      .schema('registry')
      .from('registrants')
      .select('first_name, last_name, state, postcode, nfc')
      .eq('id', id)
      .maybeSingle();
    if (fetchError) throw fetchError;
    if (!existing) {
      return NextResponse.json({ error: 'Registrant not found' }, { status: 404 });
    }
    const oldValue = (existing as Record<string, string | null>)[column];

    const { error: updateError } = await supabaseAdmin
      .schema('registry')
      .from('registrants')
      .update({ [column]: normalized, last_updated_at: new Date().toISOString() })
      .eq('id', id);
    if (updateError) throw updateError;

    const { error: auditError } = await supabaseAdmin
      .schema('registry')
      .from('registrant_edits')
      .insert({
        registrant_id: id,
        field: column,
        old_value: oldValue,
        new_value: normalized,
        edited_by: verified.userId,
        edited_by_email: verified.email,
      });
    // The edit itself already succeeded and passed validation — don't roll
    // it back over a failed audit-log write, but never let that failure be
    // silent, since attributability is the entire point of that table.
    if (auditError) {
      console.error('[registry/manage-record] audit log insert failed:', auditError);
    }

    const responseBody: ManageRecordEditResponse = { id, field, value: normalized };
    return NextResponse.json(responseBody);
  } catch (err) {
    console.error('[registry/manage-record] failed:', err);
    return NextResponse.json({ error: 'Failed to save the edit' }, { status: 500 });
  }
}

app/api/registry/manage-registration-log:
/**
 * Registry portal — paginated trace of what ac-sync did with each form
 * submission it received from ActiveCampaign, newest first (the outcome rules
 * live in lib/registryPipeline/registrationLog.ts). Powers
 * /registry/manage/registration-log, so an admin can see for any recent
 * registration whether it created a new registrant, updated an existing one,
 * landed in the separate Way of Life responders table, or was skipped.
 *
 * Reads staging.ac_events (the raw landing zone) and joins what it produced
 * in registry.registration_events / registrants / twol_respondents. Query
 * params: page, view (registrations | responders | skipped | all), q (name or
 * email contains).
 *
 * Admin-only, same gate as manage-summary/manage-edit-log/manage-whatsapp-invite-log.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyRegistryAdminRequest } from '@/lib/registryServerAuth';
import { isNationalRegistryAdmin } from '@/lib/registryPipeline/mfaGate';
import { deriveRegistrationOutcome, parseRegistrationLogView, sanitizeSearchTerm } from '@/lib/registryPipeline/registrationLog';
import type { RegistrationLogEntry, RegistrationLogResponse } from '@/lib/registryPipeline/manageSummaryTypes';

const PAGE_SIZE = 50;

interface StagingRow {
  id: number;
  source_list_id: string;
  received_at: string;
  processed_at: string | null;
  processing_error: string | null;
  email: string | null;
  first_name: string | null;
  last_name: string | null;
  contact_created: string | null;
}

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const verified = await verifyRegistryAdminRequest(supabaseAdmin, token);
  if (!verified || !isNationalRegistryAdmin(verified.leaderRole.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const params = request.nextUrl.searchParams;
  const pageParam = Number(params.get('page') ?? '1');
  const page = Number.isFinite(pageParam) && pageParam >= 1 ? Math.floor(pageParam) : 1;
  const from = (page - 1) * PAGE_SIZE;
  const to = from + PAGE_SIZE - 1;
  const view = parseRegistrationLogView(params.get('view'));
  const search = sanitizeSearchTerm(params.get('q'));

  try {
    let query = supabaseAdmin
      .schema('staging')
      .from('ac_events')
      .select(
        'id, source_list_id, received_at, processed_at, processing_error, email:raw_payload->contact->>email, first_name:raw_payload->contact->>firstName, last_name:raw_payload->contact->>lastName, contact_created:raw_payload->contact->>cdate',
        { count: 'exact' },
      );

    if (view === 'registrations') query = query.eq('source_list_id', '1').is('processing_error', null);
    else if (view === 'responders') query = query.eq('source_list_id', '2').is('processing_error', null);
    else if (view === 'skipped') query = query.not('processing_error', 'is', null);

    if (search) {
      query = query.or(
        `raw_payload->contact->>email.ilike.%${search}%,raw_payload->contact->>lastName.ilike.%${search}%,raw_payload->contact->>firstName.ilike.%${search}%`,
      );
    }

    const { data, count, error } = await query.order('id', { ascending: false }).range(from, to);
    if (error) throw error;

    const rows = (data ?? []) as unknown as StagingRow[];
    const ids = rows.map((r) => r.id);

    const registrantByEvent = new Map<number, string>();
    const responderEvents = new Set<number>();
    const registrantById = new Map<string, { firstSeenAt: string; state: string | null; registeredAt: string | null }>();

    if (ids.length > 0) {
      const [eventsRes, respondersRes] = await Promise.all([
        supabaseAdmin.schema('registry').from('registration_events').select('raw_staging_id, registrant_id').in('raw_staging_id', ids),
        supabaseAdmin.schema('registry').from('twol_respondents').select('raw_staging_id').in('raw_staging_id', ids),
      ]);
      if (eventsRes.error) throw eventsRes.error;
      if (respondersRes.error) throw respondersRes.error;

      for (const e of eventsRes.data ?? []) registrantByEvent.set(e.raw_staging_id as number, e.registrant_id as string);
      for (const r of respondersRes.data ?? []) responderEvents.add(r.raw_staging_id as number);

      const registrantIds = [...new Set(registrantByEvent.values())];
      if (registrantIds.length > 0) {
        const { data: regs, error: regError } = await supabaseAdmin
          .schema('registry')
          .from('registrants')
          .select('id, first_seen_at, state, registered_at')
          .in('id', registrantIds);
        if (regError) throw regError;
        for (const r of regs ?? []) {
          registrantById.set(r.id as string, { firstSeenAt: r.first_seen_at as string, state: r.state as string | null, registeredAt: r.registered_at as string | null });
        }
      }
    }

    const entries: RegistrationLogEntry[] = rows.map((row) => {
      const registrantId = registrantByEvent.get(row.id);
      const registrant = registrantId ? registrantById.get(registrantId) ?? null : null;
      return {
        id: row.id,
        receivedAt: row.received_at,
        listId: row.source_list_id,
        outcome: deriveRegistrationOutcome({
          processedAt: row.processed_at,
          processingError: row.processing_error,
          hasResponderRow: responderEvents.has(row.id),
          registrant: registrant ? { firstSeenAt: registrant.firstSeenAt } : null,
        }),
        firstName: row.first_name,
        lastName: row.last_name,
        email: row.email,
        contactCreatedAt: row.contact_created,
        registrant: registrant ? { state: registrant.state, registeredAt: registrant.registeredAt } : null,
      };
    });

    const body: RegistrationLogResponse = { entries, totalCount: count ?? 0 };
    return NextResponse.json(body);
  } catch (err) {
    console.error('[registry/manage-registration-log] failed:', err);
    return NextResponse.json({ error: 'Failed to load the registration log' }, { status: 500 });
  }
}

app/api/registry/manage-summary/route.ts:
/**
 * Registry portal — data for the Manage console (app/registry/manage/page.tsx).
 *
 * Returns the most recent registry.sync_log row (whatever a national admin
 * needs to answer "when did the cron job last run, and did it succeed") and
 * every registry.registrants row — first/last name, email, phone, state,
 * postcode, registered_at, unsubscribed/nfc status, the four webinar/Code-of-Conduct
 * fields (see lib/registryPipeline/tagDerivedFields.ts), plus whether it matches a public.state_leaders
 * row by normalized phone (lib/registryPipeline/leaderMatch.ts — every
 * AFJ leader is expected to also be a registrant, so Peter wanted this
 * visible in the record list, just as a yes/no next to their name — not
 * which state they lead; computed live on every request, not a
 * synced/stored column, since state_leaders is small and this is the
 * first place the registry pipeline reads the main app's public schema —
 * both live in the same Postgres database, just different schemas, so
 * it's one more query, not a cross-database join). The console tallies
 * these into its grid (lib/registryPipeline/registrantCounts.ts) and,
 * when a national admin clicks a non-zero cell, lists the actual matching
 * records underneath it — both done client-side against this one fetch,
 * so the filter dropdowns and record drill-down are instant with no extra
 * round trip.
 *
 * This is PII, which is why this route is gated as strictly as it is —
 * see the admin-only note below.
 *
 * ~9,100 registrants as of the 2026-09 reload (see
 * scripts/backup_registrants_before_reload.ts), growing by a handful a day
 * via ac-sync — small enough to page through and return whole. Revisit with
 * server-side aggregation/pagination if that ever stops being true (the
 * response grew by four short fields per registrant 2026-09-15, still
 * small enough not to force the issue).
 *
 * Admin-only: verifyRegistryAdminRequest() proves the caller cleared the
 * MFA gate, and isNationalRegistryAdmin() further restricts this to
 * national_admin/whatsapp_admin — a state_leader has no need for national
 * totals across every state and isn't shown the Manage button that links
 * here (app/registry/page.tsx), so this is defense in depth for that same
 * rule, not a separate decision.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyRegistryAdminRequest } from '@/lib/registryServerAuth';
import { isNationalRegistryAdmin } from '@/lib/registryPipeline/mfaGate';
import { matchRegistrantsToLeaders, type LeaderForMatch } from '@/lib/registryPipeline/leaderMatch';
import type { ManageRegistrant, ManageSummaryResponse, SyncLogSummary } from '@/lib/registryPipeline/manageSummaryTypes';

const PAGE_SIZE = 1000;

export async function GET(request: NextRequest) {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return corsBlock;

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const verified = await verifyRegistryAdminRequest(supabaseAdmin, token);
  if (!verified || !isNationalRegistryAdmin(verified.leaderRole.role)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { data: syncRow, error: syncError } = await supabaseAdmin
      .schema('registry')
      .from('sync_log')
      .select('started_at, completed_at, status, records_in, records_upserted, errors, notes')
      .eq('run_type', 'sync')
      .order('started_at', { ascending: false })
      .limit(1)
      .maybeSingle();
    if (syncError) throw syncError;

    const lastSync: SyncLogSummary | null = syncRow
      ? {
          startedAt: syncRow.started_at,
          completedAt: syncRow.completed_at,
          status: syncRow.status,
          recordsIn: syncRow.records_in,
          recordsUpserted: syncRow.records_upserted,
          errors: syncRow.errors,
          notes: syncRow.notes,
        }
      : null;

    const { data: leaderRows, error: leaderError } = await supabaseAdmin
      .from('state_leaders')
      .select('leader, mobile');
    if (leaderError) throw leaderError;
    const leaders: LeaderForMatch[] = (leaderRows ?? []) as LeaderForMatch[];

    const bareRegistrants: Omit<ManageRegistrant, 'isLeader' | 'leaderName'>[] = [];
    for (let offset = 0; ; offset += PAGE_SIZE) {
      const { data, error } = await supabaseAdmin
        .schema('registry')
        .from('registrants')
        .select('id, first_name, last_name, email, phone, state, postcode, registered_at, webinar_session_at, webinar_attended, code_of_conduct_agreed, code_of_conduct_agreed_at, unsubscribed, nfc, church_name')
        .range(offset, offset + PAGE_SIZE - 1);
      if (error) throw error;
      if (!data || data.length === 0) break;
      bareRegistrants.push(...data.map((r) => ({
        id: r.id,
        firstName: r.first_name,
        lastName: r.last_name,
        email: r.email,
        phone: r.phone,
        state: r.state,
        postcode: r.postcode,
        registeredAt: r.registered_at,
        webinarSessionAt: r.webinar_session_at,
        webinarAttended: r.webinar_attended,
        codeOfConductAgreed: r.code_of_conduct_agreed,
        codeOfConductAgreedAt: r.code_of_conduct_agreed_at,
        unsubscribed: r.unsubscribed,
        nfc: r.nfc,
        churchName: r.church_name,
      })));
      if (data.length < PAGE_SIZE) break;
    }
    const registrants: ManageRegistrant[] = matchRegistrantsToLeaders(bareRegistrants, leaders);

    const body: ManageSummaryResponse = { lastSync, registrants };
    return NextResponse.json(body);
  } catch (err) {
    console.error('[registry/manage-summary] failed:', err);
    return NextResponse.json({ error: 'Failed to load registry management summary' }, { status: 500 });
  }
}

