import { useRouter } from 'next/navigation';
import { PUBLIC_LINKS } from '@/lib/publicLinks';
import { withBackToApp } from '@/components/BackToAppBar';

/** Public links offered as shortcuts, by their `lib/publicLinks.ts` slug. */
