'use client';
import type { Campaign } from '@/lib/types';
import type { LeaderShareOwner } from '@/lib/types';
import { getStateColor } from '@/lib/stateColors';
import { formatCampaignTimeDisplay, isCampaignPast } from '@/lib/campaignUtils';
import { normalizeName, normalizeMobile } from '@/lib/auth';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';
import { combinePlaceAndSite } from '@/lib/placeSite';
import { isTrainingCategory } from '@/lib/services/trainingInterestService';

const SOURCE_LABEL: Record<string, string> = {
  MAN: 'Manual',
  CFP: 'Copied from past week',
  RUL: 'Created by rule',
};

function canRecordResults(
  campaign: Campaign,
  adminStatus: string | null,
  userState: string | null,
  userMobileAndLeader: { mobile: string | null; leader: string | null } | null,
  sharedWithMeOwners: LeaderShareOwner[],
): boolean {
  if (!isCampaignPast(campaign.date, campaign.time)) return false;
  if (adminStatus === 'AD') return true;
  if (adminStatus === 'SR') {
    return (campaign.state || '').toUpperCase().trim() === (userState || '').toUpperCase().trim();
  }
  const isOwn =
    !!userMobileAndLeader?.leader &&
    !!userState &&
    normalizeName(campaign.leader || '') === normalizeName(userMobileAndLeader.leader) &&
    (campaign.state || '').toUpperCase().trim() === userState.toUpperCase().trim() &&
    !!userMobileAndLeader.mobile &&
    normalizeMobile(campaign.mobile || '') === normalizeMobile(userMobileAndLeader.mobile);
  const isShared = sharedWithMeOwners.some(
    (o) =>
      (o.owner_state || '').toUpperCase().trim() === (campaign.state || '').toUpperCase().trim() &&
      normalizeName(o.owner_leader) === normalizeName(campaign.leader || ''),
  );
  return isOwn || isShared;
}

interface Props {
  campaign: Campaign;
  dateFilter: 'past' | 'future';
  isAdmin: boolean;
  adminStatus: string | null;
  userState: string | null;
  userMobileAndLeader: { mobile: string | null; leader: string | null } | null;
  sharedWithMeOwners: LeaderShareOwner[];
  savedCheckboxId: string | null;
  /** Number of campaign_interest registrations for this campaign — 0/undefined hides the callout entirely. */
  campaignInterestCount?: number;
  onEdit: () => void;
  onDelete: () => void;
  onToggleCheckbox: (field: 'tl_ok' | 'sr_ok', currentValue: boolean) => void;
  onRecordResults: () => void;
  onViewTrainingInterest: () => void;
  onViewCampaignInterest: () => void;
}

export default function CampaignCard({
  campaign, dateFilter, isAdmin, adminStatus, userState, userMobileAndLeader,
  sharedWithMeOwners, savedCheckboxId, campaignInterestCount, onEdit, onDelete, onToggleCheckbox, onRecordResults,
  onViewTrainingInterest, onViewCampaignInterest,
}: Props) {
  const stateColor = getStateColor(campaign.state);
  const displayTime = formatCampaignTimeDisplay(campaign.time);
  const campaignCat = campaign.category ?? 'TWOL';
  const showCategoryBadge = campaignCat !== 'TWOL';
  const showRecordResults = canRecordResults(campaign, adminStatus, userState, userMobileAndLeader, sharedWithMeOwners);
  const showTrainingInterest = isTrainingCategory(campaignCat);

  return (
    <div data-ti="app/app/components/CampaignCard.tsx" className={`p-4 sm:p-5 ${stateColor.bg} border-b-2 border-gray-800 dark:border-gray-600`}>
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div className="flex-1 min-w-0">
          <div className={`flex items-center justify-between gap-2 text-lg sm:text-xl font-bold ${stateColor.text} mb-2 break-words`}>
            <span>{combinePlaceAndSite(campaign.place, campaign.site)} {campaign.state} • {displayTime}</span>
            {showCategoryBadge && <span className="shrink-0 ml-2">{campaignCat}</span>}
          </div>
          <div className={`text-base sm:text-lg ${stateColor.text} opacity-90 mb-1 break-words`}>
            <span className="font-semibold">Leader: </span>
            <span className="font-bold">{campaign.leader}</span>
            {isRecognizedAdminStatus(adminStatus) && campaign.mobile && (
              <> <span className="font-normal">{campaign.mobile}</span></>
            )}
            {isAdmin && campaign.source && (
              <span
                className="ml-2 text-xs font-normal opacity-75"
                title={SOURCE_LABEL[campaign.source] ?? campaign.source}
              >
                ({campaign.source})
              </span>
            )}
          </div>
          {!!campaignInterestCount && (
            <button
              type="button"
              onClick={onViewCampaignInterest}
              className="mb-1 inline-flex items-center gap-1.5 rounded-full border-2 border-amber-600 bg-amber-400 px-3 py-1 text-sm font-extrabold text-amber-950 shadow-sm hover:bg-amber-300 dark:border-amber-500 dark:bg-amber-500 dark:text-amber-950 dark:hover:bg-amber-400"
            >
              🔔 {campaignInterestCount} {campaignInterestCount === 1 ? 'person' : 'people'} interested — Manage →
            </button>
          )}
          {dateFilter === 'future' && (
            <div className="flex items-center gap-3 justify-center text-sm sm:text-base mt-2 mb-2">
              <div
                className={`flex items-center ${stateColor.text} font-semibold cursor-pointer`}
                onClick={() => onToggleCheckbox('tl_ok', campaign.tl_ok)}
              >
                <input
                  type="checkbox"
                  checked={campaign.tl_ok}
                  onChange={() => {}}
                  className="h-5 w-5 rounded border-gray-300 mr-2 cursor-pointer"
                />
                <span>This Campaign is Correct</span>
              </div>
              {savedCheckboxId === campaign.id && (
                <span className="text-sm font-semibold text-green-600 dark:text-green-400 animate-pulse">
                  Saved ✓
                </span>
              )}
            </div>
          )}
        </div>
        {/* flex-wrap: a training campaign that also qualifies for Record
            Results can stack up to 4 flex-1 buttons here — wrap onto a
            second line on narrow screens instead of squeezing/truncating. */}
        <div className="flex flex-row flex-wrap gap-2 sm:ml-4 w-full sm:w-auto">
          {showTrainingInterest && (
            <button
              onClick={onViewTrainingInterest}
              className="flex-1 rounded-md bg-purple-100 px-2 sm:px-4 py-2 text-base font-bold text-purple-700 hover:bg-purple-200 dark:bg-purple-900/30 dark:text-purple-300 dark:hover:bg-purple-900/50 border-2 border-gray-800 dark:border-gray-600"
            >
              Training Interest
            </button>
          )}
          {showRecordResults && (
            <button
              onClick={onRecordResults}
              className="flex-1 rounded-md bg-green-100 px-2 sm:px-4 py-2 text-base font-bold text-green-700 hover:bg-green-200 dark:bg-green-900/30 dark:text-green-300 dark:hover:bg-green-900/50 border-2 border-gray-800 dark:border-gray-600"
            >
              Record Results
            </button>
          )}
          <button
            onClick={onEdit}
            className="flex-1 rounded-md bg-blue-100 px-2 sm:px-4 py-2 text-base font-bold text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:hover:bg-blue-900/50 border-2 border-gray-800 dark:border-gray-600"
          >
            Edit
          </button>
          <button
            onClick={onDelete}
            className="flex-1 rounded-md bg-red-100 px-2 sm:px-4 py-2 text-base font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-300 dark:hover:bg-red-900/50 border-2 border-gray-800 dark:border-gray-600"
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}

app/app/components/CampaignCreateForm.ts:
'use client';
import { createCampaign } from '@/lib/services/campaignService';
import { trackEvent } from '@/lib/analytics';
import { getTodayDateString } from '@/lib/campaignDates';
import { AUSTRALIAN_STATES } from '@/lib/constants';
import { combinePlaceAndSite } from '@/lib/placeSite';
import { useCampaignForm } from './useCampaignForm';
import { TIME_OPTIONS } from './timeOptions';

interface Props {
  isAdmin: boolean;
  userState: string | null;
  userMobileAndLeader: { mobile: string | null; leader: string | null } | null;
  userId: string;
  categories: { code: string; name: string }[];
  onSuccess: () => void;
  onClose: () => void;
}

const fieldClass =
  'mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white';

export default function CampaignCreateForm({
  isAdmin, userState, userMobileAndLeader, userId, categories, onSuccess, onClose,
}: Props) {
  const {
    values, setValue,
    isOtherPlace, customPlace, setCustomPlace,
    places, leaders, loadingPlaces, loadingLeaders,
    isSubmitting, error,
    handleSubmit, handleStateChange, handleLeaderChange, handlePlaceChange,
  } = useCampaignForm({
    initialValues: {
      date: getTodayDateString(),
      state: userState ? userState.toUpperCase().trim() : '',
      place: '', site: '', time: '', leader: '', mobile: '',
      category: 'TWOL', tl_ok: false, sr_ok: false,
    },
    onSubmit: async (v) => {
      await createCampaign({
        date: v.date, state: v.state, place: v.place, site: v.site, time: v.time,
        leader: v.leader, mobile: v.mobile.trim() || null,
        category: v.category ?? 'TWOL', tl_ok: v.tl_ok, sr_ok: v.sr_ok,
        user_id: userId, source: 'MAN',
      });
      trackEvent('campaign_create', { state: v.state, category: v.category ?? 'TWOL' });
      onSuccess();
      onClose();
    },
    autoFill: { isAdmin, userMobileAndLeader, userState },
  });

  return (
    <div data-ti="app/app/components/CampaignCreateForm.tsx" className="rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white shadow-sm dark:bg-gray-800 w-full overflow-hidden">
      <div className="flex items-center justify-between p-4">
        <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Add Campaign</h2>
        <button type="button" onClick={onClose}
          className="rounded-md bg-red-600 px-3 py-1 text-base font-bold text-white hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600">
          Close
        </button>
      </div>
      <div className="p-4 pt-0 bg-blue-50 dark:bg-blue-900/20 rounded-b-lg">
        {error && (
          <div className="mb-4 rounded-md bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-800 dark:bg-red-900/20 dark:border-red-800 dark:text-red-200">
            {error}
          </div>
        )}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label htmlFor="create-date" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Date</label>
            <input type="date" id="create-date" required value={values.date}
              onChange={(e) => setValue('date', e.target.value)} className={fieldClass} />
          </div>
          <div>
            <label htmlFor="create-state" className="block text-sm font-medium text-gray-700 dark:text-gray-300">State</label>
            <select id="create-state" required value={values.state}
              onChange={(e) => handleStateChange(e.target.value)}
              disabled={!isAdmin}
              className={`${fieldClass} disabled:opacity-50 disabled:cursor-not-allowed`}>
              <option value="">Select a state</option>
              {AUSTRALIAN_STATES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="create-place" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Place</label>
            <select id="create-place" required={!isOtherPlace}
              value={isOtherPlace ? 'OTHER_PLACE' : combinePlaceAndSite(values.place, values.site)}
              onChange={(e) => handlePlaceChange(e.target.value)}
              disabled={!values.state || loadingPlaces}
              className={`${fieldClass} disabled:opacity-50`}>
              <option value="">{loadingPlaces ? 'Loading...' : 'Select a place'}</option>
              {places.map((p) => <option key={p.label} value={p.label}>{p.label}</option>)}
              <option value="OTHER_PLACE">Other Place</option>
            </select>
            {isOtherPlace && (
              <>
                <input type="text" id="create-customPlace" required value={customPlace}
                  onChange={(e) => setCustomPlace(e.target.value)}
                  placeholder="e.g. Sunshine West"
                  className="mt-2 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white" />
                <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                  Enter the suburb or location name. It will be saved for future use.
                </p>
              </>
            )}
          </div>
          <div>
            <label htmlFor="create-time" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Time</label>
            <select id="create-time" required value={values.time}
              onChange={(e) => setValue('time', e.target.value)} className={fieldClass}>
              <option value="">Select a time</option>
              {TIME_OPTIONS.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="create-leader" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Leader</label>
            <select id="create-leader" required value={values.leader}
              onChange={(e) => handleLeaderChange(e.target.value)}
              disabled={!values.state || loadingLeaders}
              className={`${fieldClass} disabled:opacity-50`}>
              <option value="">{loadingLeaders ? 'Loading...' : 'Select a leader'}</option>
              {leaders.map((l) => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="create-category" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Category</label>
            <select id="create-category" required value={values.category}
              onChange={(e) => setValue('category', e.target.value)} className={fieldClass}>
              {categories.map((c) => <option key={c.code} value={c.code}>{c.name}</option>)}
            </select>
          </div>
          <button type="submit" disabled={isSubmitting}
            className="w-full rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600">
            {isSubmitting ? 'Adding...' : 'Add Campaign'}
          </button>
        </form>
      </div>
    </div>
  );
}

