app/app/components/CampaignList.tsx:
'use client';
import type { Campaign } from '@/lib/types';
import type { LeaderShareOwner } from '@/lib/types';
import type { EditUpdates } from './types';
import CampaignCard from './CampaignCard';
import InlineEditForm from './InlineEditForm';
import { combinePlaceAndSite } from '@/lib/placeSite';

interface Props {
  campaigns: Campaign[];
  editingId: string | null;
  dateFilter: 'past' | 'future';
  isAdmin: boolean;
  adminStatus: string | null;
  userState: string | null;
  userMobileAndLeader: { mobile: string | null; leader: string | null } | null;
  sharedWithMeOwners: LeaderShareOwner[];
  savedCheckboxId: string | null;
  categories: { code: string; name: string }[];
  /** Campaign id -> number of campaign_interest registrations, for the "N people interested" callout. */
  campaignInterestCounts: Map<string, number>;
  onEditStart: (id: string) => void;
  onCancelEdit: () => void;
  onSaveEdit: (id: string, updates: EditUpdates) => Promise<void>;
  onDelete: (campaign: Campaign) => void;
  onToggleCheckbox: (id: string, field: 'tl_ok' | 'sr_ok', currentValue: boolean) => void;
  onRecordResults: (campaign: Campaign) => void;
  onViewTrainingInterest: (campaign: Campaign) => void;
  onViewCampaignInterest: (campaign: Campaign) => void;
}

export default function CampaignList({
  campaigns, editingId, dateFilter, isAdmin, adminStatus, userState, userMobileAndLeader,
  sharedWithMeOwners, savedCheckboxId, categories, campaignInterestCounts,
  onEditStart, onCancelEdit, onSaveEdit, onDelete, onToggleCheckbox, onRecordResults, onViewTrainingInterest,
  onViewCampaignInterest,
}: Props) {
  if (campaigns.length === 0) {
    return (
      <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
        No campaigns found
      </div>
    );
  }

  // Group by date → state → place
  const grouped = campaigns.reduce(
    (acc, campaign) => {
      const d = campaign.date;
      const placeKey = combinePlaceAndSite(campaign.place, campaign.site);
      if (!acc[d]) acc[d] = {};
      if (!acc[d][campaign.state]) acc[d][campaign.state] = {};
      if (!acc[d][campaign.state][placeKey]) acc[d][campaign.state][placeKey] = [];
      acc[d][campaign.state][placeKey].push(campaign);
      return acc;
    },
    {} as Record<string, Record<string, Record<string, Campaign[]>>>,
  );

  const result: React.ReactElement[] = [];
  const sortedDates = Object.keys(grouped).sort();
  let lastDate = '';

  for (const date of sortedDates) {
    if (date !== lastDate) {
      result.push(
        <div
          key={`date-${date}`}
          className="bg-yellow-100 dark:bg-yellow-900/30 px-4 py-4 border-2 border-gray-800 dark:border-gray-600 border-b-2 border-yellow-300 dark:border-yellow-700"
        >
          <div className="font-bold text-xl sm:text-2xl text-yellow-900 dark:text-yellow-200 break-words">
            {new Date(date).toLocaleDateString('en-AU', {
              weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
            })}
          </div>
        </div>,
      );
      lastDate = date;
    }

    for (const state of Object.keys(grouped[date]).sort()) {
      for (const place of Object.keys(grouped[date][state]).sort()) {
        for (const campaign of grouped[date][state][place]) {
          if (editingId === campaign.id) {
            result.push(
              <InlineEditForm
                key={campaign.id}
                campaign={campaign}
                isAdmin={isAdmin}
                categories={categories}
                onSave={onSaveEdit}
                onCancel={onCancelEdit}
              />,
            );
          } else {
            result.push(
              <CampaignCard
                key={campaign.id}
                campaign={campaign}
                dateFilter={dateFilter}
                isAdmin={isAdmin}
                adminStatus={adminStatus}
                userState={userState}
                userMobileAndLeader={userMobileAndLeader}
                sharedWithMeOwners={sharedWithMeOwners}
                savedCheckboxId={savedCheckboxId}
                campaignInterestCount={campaignInterestCounts.get(campaign.id)}
                onEdit={() => onEditStart(campaign.id)}
                onDelete={() => onDelete(campaign)}
                onToggleCheckbox={(field, val) => onToggleCheckbox(campaign.id, field, val)}
                onRecordResults={() => onRecordResults(campaign)}
                onViewTrainingInterest={() => onViewTrainingInterest(campaign)}
                onViewCampaignInterest={() => onViewCampaignInterest(campaign)}
              />,
            );
          }
        }
      }
    }
  }

  return <div data-ti="app/app/components/CampaignList.tsx" className="divide-y divide-gray-200 dark:divide-gray-700">{result}</div>;
}

app/app/components/CampaignSlideView.tsx:
'use client';

import type { Campaign } from '@/lib/types';
import { getSlideStateColor, STATE_CODES, formatSlideDateText } from '@/lib/slideLayout';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';
import { combinePlaceAndSite } from '@/lib/placeSite';

const PLACE_COLS  = 18;
const LEADER_COLS = 12;

interface Props {
  campaigns: Campaign[];
  adminStatus: string | null;
}

export default function CampaignSlideView({ campaigns, adminStatus }: Props) {
  if (campaigns.length === 0) {
    return (
      <div className="p-4 text-center text-sm text-gray-500">
        No campaigns found
      </div>
    );
  }

  // Mobile numbers are sensitive — only show them to full admins/state reporters,
  // matching the main feed's CampaignCard and the mobile-free "Leader Campaign
  // Lists" JPEG export (#118).
  const showMobile = isRecognizedAdminStatus(adminStatus);

  // Group by date (campaigns arrive pre-sorted by date/state/place/time)
  const grouped: Record<string, Campaign[]> = {};
  const sortedDates: string[] = [];
  for (const c of campaigns) {
    if (!grouped[c.date]) {
      grouped[c.date] = [];
      sortedDates.push(c.date);
    }
    grouped[c.date].push(c);
  }

  return (
    // Force white background so slide state colours (incl. black for NSW) remain legible
    <div data-ti="app/app/components/CampaignSlideView.tsx" style={{ backgroundColor: '#ffffff' }}>

      {/* Colour key — admin only */}
      {adminStatus === 'AD' && (
        <div className="flex flex-wrap gap-x-3 gap-y-0.5 px-3 py-1.5 font-mono text-xs font-bold border-b border-gray-100">
          <span style={{ color: 'rgb(130, 0, 0)' }}>Colour Key:</span>
          {STATE_CODES.map(s => (
            <span key={s} style={{ color: getSlideStateColor(s) }}>{s}</span>
          ))}
        </div>
      )}

      {/* Campaign rows grouped by date */}
      <div className="pb-2">
        {sortedDates.map(date => {
          const [y, m, d] = date.split('-').map(Number);
          const dateText = formatSlideDateText(new Date(y, m - 1, d));

          return (
            <div key={date} className="mt-1">
              {/* Yellow date header with dark-red italic text */}
              <div
                className="mx-3 px-2 py-0.5 inline-block text-sm font-bold italic"
                style={{ backgroundColor: '#ffff00', color: 'rgb(130, 0, 0)' }}
              >
                {dateText}
              </div>

              {/* One flex row per campaign — stretches to fill container width */}
              {grouped[date].map(c => {
                let place = combinePlaceAndSite(c.place, c.site);
                const cat = c.category ?? 'TWOL';
                if (cat !== 'TWOL') place = `${place} ${cat}`;
                if (place.length > PLACE_COLS) place = place.substring(0, PLACE_COLS);

                const time   = formatCampaignTimeDisplay(c.time);
                const leader = c.leader.length > LEADER_COLS
                  ? c.leader.substring(0, LEADER_COLS)
                  : c.leader;
                const mobile = (c.mobile ?? '').replace(/\s/g, '');
                const color  = getSlideStateColor(c.state);

                return (
                  <div
                    key={c.id}
                    className="flex items-baseline px-3 py-px font-mono font-bold text-sm leading-snug"
                    style={{ color, ...(cat !== 'TWOL' ? { backgroundColor: '#fcd34d' } : {}) }}
                  >
                    {/* Place — left-aligned, grows to fill spare space */}
                    <span style={{ flex: 18, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {place}
                    </span>
                    {/* Time — right-aligned within its column */}
                    <span style={{ flex: 9, textAlign: 'right', whiteSpace: 'nowrap' }}>
                      {time}
                    </span>
                    {/* Leader */}
                    <span style={{ flex: 13, paddingLeft: '0.75ch', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {leader}
                    </span>
                    {/* Mobile — admin/state-reporter only */}
                    {showMobile && (
                      <span style={{ flex: 10, paddingLeft: '0.75ch', whiteSpace: 'nowrap' }}>
                        {mobile}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

