'use client';

import { useEffect, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { supabase } from '@/lib/supabaseClient';
import { rememberEmailLogin } from '@/lib/emailLoginPreference';
import { completeLeaderAuthSignIn, signOutClearingAccess, type AuthedLeaderRow } from '@/lib/auth';
import { useUser } from '@/contexts/UserContext';
import { getLeaderRoleLabel } from '@/lib/leaderRoleLabel';
import { CodeEntryScreen, cardClass, bodyTextClass, primaryButtonClass, secondaryButtonClass, errorBannerClass, headingClass } from '@/components/auth/CodeEntryScreen';
import { BusyChoiceButtons } from '@/components/auth/BusyChoiceButtons';
import { getErrorMessage } from '@/lib/errorUtils';
import { describeMfaVerifyError } from '@/lib/mfaErrors';
import { EmailAndCodeFallback } from '@/components/auth/EmailAndCodeFallback';
import { TapToContinue } from '@/components/auth/TapToContinue';
import { GetHelp } from '@/components/auth/GetHelp';
import { clearPendingLoginStep } from '@/lib/pendingLoginStep';
import { readTokenHashFromUrl, stripTokenHashFromUrl } from '@/lib/magicLinkToken';
import { SigningInStuck, useStuckWatchdog } from '@/components/auth/SigningInStuck';

const GIVE_UP_AFTER_MS = 8000;

const NOT_ENROLLED_MESSAGE =
  "Two-factor authentication isn't set up for this account yet — please sign in with your mobile number and name instead.";

type Screen = 'waiting' | 'tap' | 'expired' | 'stuck' | 'not-enrolled' | 'challenge' | 'role-picker';

/**
 * Magic-link callback for the real-auth + MFA leader login path
 * (app/login/mfa/page.tsx) — mirrors app/registry/auth/callback/page.tsx +
 * app/registry/mfa/challenge/page.tsx's combined mechanics, applied to
 * state_leaders.user_id instead of registry.leader_roles.
 *
 * Deliberately does NOT parse the URL or call exchangeCodeForSession()
 * itself — lib/supabaseClient.ts has detectSessionInUrl: true, so the SDK
 * already does that automatically on page load (see the identical comment
 * on app/registry/auth/callback/page.tsx for the implicit-vs-PKCE history
 * behind this). This page just waits for the resulting SIGNED_IN event and
 * runs the MFA-gate + role-resolution logic.
 *
 * Uses the MAIN supabase client, not an isolated one — this session is
 * meant to become the leader's persistent app identity (see
 * app/login/mfa/page.tsx's header comment for the full rationale).
 */
export default function LoginMfaCallbackPage() {
  const router = useRouter();
  const { refresh: refreshUser } = useUser();
  const handledRef = useRef(false);
  // True while a scanner-proof link's token is waiting for the tap. Until then
  // a session already saved on this device must not claim the sign-in:
  // it used to, which left the tapped sign-in ignored and the page frozen on
  // "Signing you in…" (Peter_AD, 2026-10-14).
  const awaitingTapRef = useRef(false);

  const [screen, setScreen] = useState<Screen>('waiting');
  const [error, setError] = useState<string | null>(null);
  const [isBusy, setIsBusy] = useState(false);
  const [selectedRowId, setSelectedRowId] = useState<string | null>(null);
  // Scanner-proof link: the token is only used when the person taps the button (lib/magicLinkToken.ts).
  const [tokenHash, setTokenHash] = useState<string | null>(null);

  const [rows, setRows] = useState<AuthedLeaderRow[]>([]);
  const [factorId, setFactorId] = useState<string | null>(null);
  const [code, setCode] = useState('');

  useStuckWatchdog(screen === 'waiting', () => setScreen('stuck'));

  // Resolves sign-in once the account is known to be at aal2 (either
  // already, or right after a successful challenge): a single matching row
  // signs straight in, more than one shows a role picker.
  async function resolveRole(candidateRows: AuthedLeaderRow[]) {
    if (candidateRows.length === 1) {
      await finishSignIn(candidateRows[0]);
      return;
    }
    setIsBusy(false);
    setRows(candidateRows);
    setScreen('role-picker');
  }

  async function finishSignIn(row: AuthedLeaderRow) {
    setSelectedRowId(row.id);
    setIsBusy(true);
    setError(null);
    try {
      await completeLeaderAuthSignIn(row);
    } catch (err) {
      // The server refused (or the request failed) — stay on this screen with
      // a message rather than navigating on as if signed in.
      setIsBusy(false);
      setError(getErrorMessage(err, 'Failed to complete sign-in. Please try again.'));
      return;
    }
    // A signed-in leader must not later be shown someone else's remembered /login step.
    clearPendingLoginStep();
    // Remember on this device that someone signs in via email + MFA, so
    // app/login/page.tsx can skip straight to /login/mfa where that makes
    // sense (always for an admin; only from "extra security needed" for a plain
    // leader — see lib/emailLoginPreference.ts).
    rememberEmailLogin(row.admin);
    // Reload UserContext so it reads the profile just written, before
    // navigating — avoids a race where onAuthStateChange's own reload fires
    // before the server's write is visible (same pattern app/login/page.tsx uses).
    await refreshUser();
    router.replace('/app');
  }

  useEffect(() => {
    async function handleSignedIn(session: { user: { id: string } }) {
      if (handledRef.current || awaitingTapRef.current) return;
      handledRef.current = true;
      try {
        await resolveSignedIn(session);
      } catch (err) {
        console.error('leader email sign-in failed:', err);
        setScreen('stuck');
      }
    }

    async function resolveSignedIn(session: { user: { id: string } }) {
      const { data, error: rowsError } = await supabase
        .from('state_leaders')
        .select('id, state, leader, admin, mfa_enrolled_at')
        .eq('user_id', session.user.id);

      const candidateRows = (data ?? []) as (AuthedLeaderRow & { mfa_enrolled_at: string | null })[];
      if (rowsError || candidateRows.length === 0 || !candidateRows.some((r) => r.mfa_enrolled_at)) {
        setScreen('not-enrolled');
        return;
      }

      const { data: aalData } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
      if (aalData?.currentLevel === 'aal2') {
        await resolveRole(candidateRows);
        return;
      }

      const { data: factorsData } = await supabase.auth.mfa.listFactors();
      const verified = factorsData?.totp.find((f) => f.status === 'verified');
      if (!verified) {
        // mfa_enrolled_at is set but no verified factor exists — data drift
        // (e.g. the factor was removed after enrollment). Same fallback as
        // "not enrolled at all", since the practical guidance is identical.
        setScreen('not-enrolled');
        return;
      }
      setFactorId(verified.id);
      setRows(candidateRows);
      setScreen('challenge');
    }

    // A token in the URL means "wait for the person to tap"; the give-up
    // clock only starts once they do (handleTap).
    const urlTokenHash = readTokenHashFromUrl();
    awaitingTapRef.current = Boolean(urlTokenHash);

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN' && session) handleSignedIn(session);
    });

    // Race guard: detection may already have completed before this listener
    // attached (onAuthStateChange only fires on the *next* change).
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) handleSignedIn(session);
    });

    if (urlTokenHash) {
      Promise.resolve().then(() => {
        setTokenHash(urlTokenHash);
        setScreen('tap');
      });
    }
    const giveUp = urlTokenHash
      ? null
      : setTimeout(() => {
          if (!handledRef.current) setScreen('expired');
        }, GIVE_UP_AFTER_MS);

    return () => {
      subscription.unsubscribe();
      if (giveUp) clearTimeout(giveUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function handleTap() {
    if (!tokenHash) return;
    const token = tokenHash;
    setTokenHash(null);
    setScreen('waiting');
    stripTokenHashFromUrl();
    awaitingTapRef.current = false;
    const { error: verifyError } = await supabase.auth.verifyOtp({ token_hash: token, type: 'email' });
    if (verifyError) {
      setScreen('expired');
      return;
    }
    // SIGNED_IN reaches the listener above; if it somehow never does, don't hang.
    setTimeout(() => {
      if (!handledRef.current) setScreen('expired');
    }, GIVE_UP_AFTER_MS);
  }

  async function handleVerify() {
    if (!factorId) return;
    setIsBusy(true);
    setError(null);
    const { error: verifyError } = await supabase.auth.mfa.challengeAndVerify({ factorId, code });
    if (verifyError) {
      setIsBusy(false);
      setError(describeMfaVerifyError(verifyError));
      return;
    }
    await resolveRole(rows);
  }

  // Recovery path when the link itself already failed (e.g. Apple Mail
  // Privacy Protection silently consumed it before the leader ever tapped
  // it — confirmed live, 2026-10-05). Just needs to call verifyOtp() and
  // throw on failure; the onAuthStateChange listener registered in the
  // effect above is still subscribed (the failed first attempt never ran
  // handleSignedIn, so nothing blocks it firing again) and runs the exact
  // same MFA-gate/role-resolution flow a working link would have.
  async function handleRecoveryVerify(email: string, code: string) {
    const { error } = await supabase.auth.verifyOtp({ email, token: code, type: 'email' });
    if (error) throw error;
  }

  async function handleCancel() {
    await signOutClearingAccess();
    router.replace('/login/mfa');
  }

  if (screen === 'waiting') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>Signing you in…</h2>
          {error && (
            <>
              <p role="alert" className={errorBannerClass}>{error}</p>
              <a href="/login/mfa" className={`${secondaryButtonClass} block text-center`}>Back to sign in</a>
            </>
          )}
        </div>
      </div>
    );
  }

  if (screen === 'stuck') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <SigningInStuck restartHref="/login/mfa" />
        </div>
      </div>
    );
  }

  if (screen === 'tap') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <TapToContinue
            title="One last step"
            description="Tap the button below to finish signing in."
            buttonLabel="Finish signing in"
            isBusy={false}
            onTap={handleTap}
          />
        </div>
      </div>
    );
  }

  if (screen === 'expired') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>That link has already been used</h2>
          <p className={bodyTextClass}>The link has expired, or it was already used — some email programs open links automatically, which uses them up.</p>
          <EmailAndCodeFallback onVerify={handleRecoveryVerify} />
          <a href="/login/mfa" className={`${secondaryButtonClass} block text-center`}>Back to sign in</a>
          <GetHelp />
        </div>
      </div>
    );
  }

  if (screen === 'not-enrolled') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>Not set up yet</h2>
          <p className={bodyTextClass}>{NOT_ENROLLED_MESSAGE}</p>
          {/* ?mode=mobile: the message above says to use mobile + name, and without it a device that
              remembers email sign-in (lib/emailLoginPreference.ts) would bounce straight back here. */}
          <a href="/login?mode=mobile" className={`${primaryButtonClass} block text-center`}>Back to sign in</a>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
      <div className={cardClass}>
        {screen === 'challenge' && (
          <CodeEntryScreen
            title="Enter your authenticator code"
            description="Enter the 6-digit code from your authenticator app to finish signing in."
            code={code}
            onCodeChange={setCode}
            onVerify={handleVerify}
            onBack={handleCancel}
            backLabel="Cancel"
            error={error}
            isBusy={isBusy}
            disabled={!factorId}
            help={<GetHelp />}
          />
        )}

        {screen === 'role-picker' && (
          <div className="space-y-4">
            <h2 className={headingClass}>Which role are you signing in as?</h2>
            <p className={bodyTextClass}>You have more than one role on file.</p>
            {error && <p role="alert" className={errorBannerClass}>{error}</p>}
            <BusyChoiceButtons
              choices={rows.map(row => ({ id: row.id, label: getLeaderRoleLabel(row.admin, row.state) }))}
              selectedId={selectedRowId}
              busy={isBusy}
              onSelect={id => { const row = rows.find(r => r.id === id); if (row) void finishSignIn(row); }}
              baseClass={primaryButtonClass}
              idleClass=""
              selectedClass="opacity-75"
              otherClass="!bg-gray-400 !opacity-100"
            />
            <button onClick={handleCancel} disabled={isBusy} className={secondaryButtonClass}>Cancel</button>
          </div>
        )}
      </div>
    </div>
  );
}

app/login/mfa/page.tsx:
'use client';

import { useEffect, useState, FormEvent } from 'react';
import { useRouter } from 'next/navigation';
import { supabase } from '@/lib/supabaseClient';
import { cardClass, bodyTextClass, primaryButtonClass, secondaryButtonClass, inputClass, labelClass, headingClass } from '@/components/auth/CodeEntryScreen';
import { InlineCodeFallback } from '@/components/auth/InlineCodeFallback';
import { GetHelp } from '@/components/auth/GetHelp';

/**
 * Email + magic-link entry point for leaders who've confirmed their email
 * and set up an authenticator app (see app/setup-mfa/page.tsx) — mirrors
 * app/registry/login/page.tsx's mechanics closely, applied to state_leaders
 * instead of registry.leader_roles. Mobile+name (app/login/page.tsx) stays
 * the only option for everyone else; this is purely additive.
 *
 * Uses the MAIN supabase client (lib/supabaseClient.ts), not an isolated
 * one like app/confirm-email or app/setup-mfa use — those flows prove
 * identity and then immediately discard the session (signOut()) so it can
 * never collide with a leader's live anonymous app session. Here the
 * opposite is true: this magic-link session is meant to *become* the
 * leader's new real, persistent identity, replacing whatever anonymous
 * session existed. lib/supabaseClient.ts already has detectSessionInUrl:
 * true, so app/login/mfa/callback/page.tsx picks the session up automatically.
 */
export default function LoginMfaPage() {
  const router = useRouter();
  const [checkingSession, setCheckingSession] = useState(true);
  const [email, setEmail] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sent, setSent] = useState(false);

  // A real (non-anonymous) session already signed in via this flow before —
  // let app/login/mfa/callback/page.tsx re-resolve it (role picker / straight
  // through to /app) instead of asking for an email again. An anonymous
  // session (today's mobile+name flow) is not "already signed in" for this
  // flow's purposes, so it's ignored here and the form still shows.
  useEffect(() => {
    let cancelled = false;
    async function checkExistingSession() {
      const { data: { session } } = await supabase.auth.getSession();
      if (session && !session.user.is_anonymous) {
        if (!cancelled) router.replace('/login/mfa/callback');
        return;
      }
      if (!cancelled) setCheckingSession(false);
    }
    checkExistingSession();
    return () => { cancelled = true; };
  }, [router]);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const origin = window.location.origin;
      // shouldCreateUser: false — by the time a leader can reach this state
      // (confirmed email + enrolled MFA), their auth.users row already
      // exists from the original email-capture magic link. Always shows
      // "check your email" below regardless of outcome, so this form never
      // reveals whether an address is a recognized, enrolled leader.
      await supabase.auth.signInWithOtp({
        email,
        options: {
          shouldCreateUser: false,
          // ?via=email: the email template appends &token_hash=... (lib/magicLinkToken.ts)
          emailRedirectTo: `${origin}/login/mfa/callback?via=email`,
        },
      });
    } catch (err) {
      console.error('leader email sign-in request failed:', err);
    } finally {
      setIsSubmitting(false);
      setSent(true);
    }
  }

  // Same Apple-Mail-prefetch fallback as app/login/page.tsx's two code
  // handlers — establishing the session via the same main client
  // /login/mfa/callback/page.tsx already expects is enough; that page's own
  // getSession() race cover picks it up and runs its normal AAL2-challenge/
  // role-resolution flow unmodified.
  async function handleCodeVerify(code: string) {
    const { data, error } = await supabase.auth.verifyOtp({ email, token: code, type: 'email' });
    if (error || !data.session) throw error ?? new Error('Invalid or expired code');
    router.push('/login/mfa/callback');
  }

  if (checkingSession) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>Checking sign-in status…</h2>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
      <div className={cardClass}>
        <h2 className={headingClass}>Sign in with email</h2>
        {sent ? (
          <div className="space-y-4">
            <p className={bodyTextClass}>
              If that address has two-factor authentication set up, we have sent it an email. Open that email and click the <strong>CONFIRM NOW</strong> link in it to sign in. If you can&apos;t see it, check your Junk or Spam folder.
            </p>
            <InlineCodeFallback onVerify={handleCodeVerify} />
            <GetHelp />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="leader-email" className={labelClass}>Email address</label>
              <input
                id="leader-email"
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                autoComplete="email"
                className={inputClass}
              />
            </div>
            <button type="submit" disabled={isSubmitting || !email} className={primaryButtonClass}>
              {isSubmitting ? 'Sending…' : 'Send sign-in link'}
            </button>
          </form>
        )}
        {/* ?mode=mobile bypasses /login's own "prefers email+MFA" redirect
            just this once, without clearing that remembered preference —
            see app/login/page.tsx's checkExistingSession. */}
        <a href="/login?mode=mobile" className={`${secondaryButtonClass} block text-center`}>
          ← Back to mobile + name sign in
        </a>
      </div>
    </div>
  );
}

app/login/page.tsx:
'use client';

import { BusyChoiceButtons } from '@/components/auth/BusyChoiceButtons';
import { useState, FormEvent, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import { shouldSkipToEmailLogin } from '@/lib/emailLoginPreference';
import { getVerifiedSession, validateStateLeader, completeSignIn, type StateLeaderMatch } from '@/lib/auth';
import { emailConfirmSupabase } from '@/lib/emailConfirmSupabaseClient';
import { getErrorMessage } from '@/lib/errorUtils';
import { isValidEmail } from '@/lib/validation';
import { trackEvent } from '@/lib/analytics';
import { useUser } from '@/contexts/UserContext';
import { getRecentTWOLCampaignsForLeader } from '@/lib/services/campaignService';
import { getTrainingCampaigns } from '@/lib/services/trainingInterestService';
import { hasCampaignInterestForLeader } from '@/lib/services/campaignInterestService';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';
import { AUSTRALIAN_STATE_NAMES } from '@/lib/constants';
import { InlineCodeFallback } from '@/components/auth/InlineCodeFallback';
import { cardClass as setupCardClass, bodyTextClass, headingClass, errorBannerClass, primaryButtonClass, secondaryButtonClass, inputClass } from '@/components/auth/CodeEntryScreen';
import { GetHelp } from '@/components/auth/GetHelp';
import GuideScreen, { OpenGuideButton, SignInGuideLink } from '@/components/GuideScreen';
import { SetupStep } from '@/components/auth/SetupStep';
import { getAdminLoginGate, type AdminLoginGate } from '@/lib/adminLoginGate';
import { clearPendingLoginStep, readPendingLoginStep, savePendingLoginStep } from '@/lib/pendingLoginStep';
import type { Campaign } from '@/lib/types';

type ActionChoice = 'record-past' | 'review-upcoming' | 'create-new' | 'campaign-rules' | 'training-interest' | 'campaign-interest';

const STORAGE_KEYS = { mobile: 'login_mobile', firstName: 'login_firstName' };

export default function LoginPage() {
  const router = useRouter();
  const { refresh: refreshUser } = useUser();
  const [mobile, setMobile]           = useState('');
  const [firstName, setFirstName]     = useState('');
  const [error, setError]             = useState<string | null>(null);
  const [isLoading, setIsLoading]     = useState(false);
  const [checkingSession, setCheckingSession] = useState(true);
  // Set when credentials validate but the leader has records in multiple states
  const [pendingMatches, setPendingMatches] = useState<StateLeaderMatch[] | null>(null);
  // Tracks which state button was clicked while sign-in is in progress
  const [selectedStateId, setSelectedStateId] = useState<string | null>(null);
  // Recent TWOL campaigns that the leader may want to record results for
  const [recentCampaigns, setRecentCampaigns] = useState<Pick<Campaign, 'id' | 'date' | 'state' | 'place' | 'time' | 'leader'>[] | null>(null);
  // Whether to show the post-sign-in action chooser (regular leaders only)
  const [showActionChooser, setShowActionChooser] = useState(false);
  // Whether the signed-in leader has any BOTJ/TLT training campaigns — gates
  // the "Manage my Training Interest" button on the action chooser
  const [hasTrainingCampaigns, setHasTrainingCampaigns] = useState(false);
  // Whether any of the signed-in leader's campaigns have registrations via
  // the public Register Interest link — gates the "Manage my Campaign
  // Interest" button on the action chooser
  const [hasCampaignInterest, setHasCampaignInterest] = useState(false);
  // Ahead of a later phase moving login onto real Supabase Auth accounts,
  // every leader without a confirmed email is asked (skippably) to add/
  // confirm one, pre-filled from state_leaders.pending_email or a
  // registry.registrants phone-match suggestion. Shown every login until
  // confirmed, then never again — see the leader-email-capture plan.
  const [emailStep, setEmailStep] = useState<{ match: StateLeaderMatch; value: string; phase: 'edit' | 'sent' } | null>(null);
  const [emailStepError, setEmailStepError] = useState<string | null>(null);
  const [emailStepSubmitting, setEmailStepSubmitting] = useState(false);
  // Once a leader has a confirmed email, offer (skippably) to set up MFA
  // ahead of a later phase that starts requiring it — same "every login
  // until done, then never again" shape as the email step above.
  const [mfaStep, setMfaStep] = useState<{ match: StateLeaderMatch; phase: 'offer' | 'sent' } | null>(null);
  const [mfaStepError, setMfaStepError] = useState<string | null>(null);
  const [mfaStepSubmitting, setMfaStepSubmitting] = useState(false);
  // Admins (AD/SR) may not sign in with mobile+name at all — they must use
  // email + an authenticator code. Set when an *already enrolled* admin
  // matched here and needs pointing at /login/mfa; an unenrolled admin is
  // instead walked through the same email/MFA-setup steps as everyone else,
  // minus the "skip" (emailStep/mfaStep below, `mandatory`). No app session
  // is ever created on this path.
  const [adminSignInMatch, setAdminSignInMatch] = useState<StateLeaderMatch | null>(null);
  // A plain leader who came here (/login?require2fa=1) because they need
  // two-factor authentication to see other people's personal details: they get
  // the same no-skip email/2FA steps an admin does, instead of a plain sign-in.
  // Everyone else is no longer prompted to set up email or 2FA at sign-in.
  const [requireTwoFactor, setRequireTwoFactor] = useState(false);
  // OPEN GUIDE on the sign-in form and the "What do you want to do today?"
  // screen shows the guide in place rather than navigating away, so Close
  // returns to exactly where the leader was (anything typed, the chooser) —
  // coming back to /login with a session would otherwise jump to /app.
  const [showGuide, setShowGuide] = useState(false);

  // Set once the on-load restore check below has finished, so the persist
  // effect doesn't clear a remembered step before it has been read.
  const restoreSettledRef = useRef(false);

  // Check if user is already signed in
  useEffect(() => {
    async function checkExistingSession() {
      try {
        // Read before anything else: a "Check your inbox" screen that was open
        // when the page reloaded (see lib/pendingLoginStep.ts).
        const pending = readPendingLoginStep();
        const session = await getVerifiedSession();
        // Put the leader back on that screen rather than bouncing a signed-in
        // leader to /app — they had left to fetch the emailed code. A plain
        // leader (who has no app session on this path, same as an admin) is
        // put back too; a stale step is only dropped if a session exists and
        // they aren't an admin.
        if (pending && (!session || getAdminLoginGate(pending.match))) {
          setRequireTwoFactor(true);
          if (pending.kind === 'email') {
            setEmailStep({ match: pending.match, value: pending.value, phase: 'sent' });
          } else {
            setMfaStep({ match: pending.match, phase: 'sent' });
          }
          return;
        }
        if (pending) clearPendingLoginStep();
        const requires2fa = new URLSearchParams(window.location.search).get('require2fa') === '1';
        if (requires2fa) setRequireTwoFactor(true);
        if (session) {
          router.push('/app');
          return;
        }
        // No active session, but this device has signed in via email + MFA
        // before — for an admin (who can't use mobile+name), or a plain
        // leader sent here by "extra security needed", skip the mobile+name
        // form and go straight there (lib/emailLoginPreference.ts). ?mode=mobile (set
        // by /login/mfa's own "back to mobile+name" link) bypasses this
        // just once, without touching the remembered preference — without
        // it, that link would otherwise bounce straight back here forever.
        const skipToMobileForm = new URLSearchParams(window.location.search).get('mode') === 'mobile';
        if (!skipToMobileForm && shouldSkipToEmailLogin({ requireTwoFactor: requires2fa })) {
          router.push('/login/mfa');
          return;
        }
      } catch {
        // No session — continue to login form
      } finally {
        restoreSettledRef.current = true;
        setCheckingSession(false);
      }
    }
    checkExistingSession();
  }, [router]);

  // Remember the "Check your inbox" screen while it is showing, and forget it
  // as soon as the leader moves past it (skip, confirmed, signed in, ...).
  useEffect(() => {
    if (emailStep?.phase === 'sent') {
      savePendingLoginStep({ kind: 'email', match: emailStep.match, value: emailStep.value });
    } else if (mfaStep?.phase === 'sent') {
      savePendingLoginStep({ kind: 'mfa', match: mfaStep.match });
    } else if (restoreSettledRef.current) {
      clearPendingLoginStep();
    }
  }, [emailStep, mfaStep]);

  // Load remembered credentials from localStorage
  useEffect(() => {
    if (checkingSession) return;
    try {
      const savedMobile    = localStorage.getItem(STORAGE_KEYS.mobile);
      const savedFirstName = localStorage.getItem(STORAGE_KEYS.firstName);
      if (savedMobile)    setMobile(savedMobile);
      if (savedFirstName) setFirstName(savedFirstName);
    } catch {
      // Ignore localStorage errors (e.g. private browsing)
    }
  }, [checkingSession]);

  // ── Step 1: validate credentials ──────────────────────────────────────────
  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);
    // A fresh sign-in attempt supersedes any step remembered from before.
    clearPendingLoginStep();

    try {
      if (!mobile.trim() || !firstName.trim()) {
        setError('Please enter both mobile number and first name');
        return;
      }

      const matches = await validateStateLeader(mobile.trim(), firstName.trim());

      if (matches.length === 0) {
        setError('No matching record found. Please check your mobile number and first name.');
        return;
      }

      // Save credentials now that they are confirmed valid
      try {
        localStorage.setItem(STORAGE_KEYS.mobile,    mobile.trim());
        localStorage.setItem(STORAGE_KEYS.firstName, firstName.trim());
      } catch { /* ignore */ }

      const singleMatchGate = matches.length === 1 ? getAdminLoginGate(matches[0], { requireTwoFactor }) : null;
      if (singleMatchGate) {
        startAdminGate(matches[0], singleMatchGate);
      } else if (matches.length === 1) {
        // Single state — sign in immediately, no extra step
        await completeSignIn(matches[0], { mobile, firstName });
        // Reload the UserContext so it reads the profile that was just written
        // (avoids a race where onAuthStateChange fires before the profile upsert completes)
        await refreshUser();
        trackEvent('sign_in', { state: matches[0].state });
        await checkRecentCampaign(matches[0]);
      } else {
        // Multiple states — show state picker
        setPendingMatches(matches);
      }
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to authenticate. Please check your mobile number and first name.'));
    } finally {
      setIsLoading(false);
    }
  };

  // ── Admin (AD/SR) match: never sign in here — send to email sign-in, or make them set up 2FA first ─
  const startAdminGate = (match: StateLeaderMatch, gate: AdminLoginGate) => {
    setError(null);
    if (gate === 'sign-in-with-email') {
      setAdminSignInMatch(match);
      return;
    }
    if (match.email) {
      setMfaStep({ match, phase: 'offer' });
    } else {
      setEmailStep({ match, value: match.pendingEmail ?? match.suggestedEmail ?? '', phase: 'edit' });
    }
  };

  // The original tab can't see that a leader confirmed their email (or even
  // finished 2FA) in the other tab/page, so for admins — who have no "skip"
  // — re-check where they are and move them to the right next screen.
  const handleAdminProgressCheck = async () => {
    const currentMatch = emailStep?.match ?? mfaStep?.match;
    if (!currentMatch) return;
    setEmailStepError(null);
    setMfaStepError(null);
    setEmailStepSubmitting(true);
    setMfaStepSubmitting(true);
    try {
      const matches = await validateStateLeader(mobile.trim(), firstName.trim());
      const fresh = matches.find((m) => m.id === currentMatch.id);
      const gate = fresh ? getAdminLoginGate(fresh, { requireTwoFactor }) : null;
      if (!fresh || !gate) throw new Error('Could not check your progress. Please try again.');
      if (gate === 'set-up-2fa' && !fresh.email) {
        throw new Error("We can't see that your email has been confirmed yet. Please click the CONFIRM NOW link in the email, then try again.");
      }
      setEmailStep(null);
      setMfaStep(null);
      startAdminGate(fresh, gate);
    } catch (err: unknown) {
      const message = getErrorMessage(err, 'Could not check your progress. Please try again.');
      setEmailStepError(message);
      setMfaStepError(message);
    } finally {
      setEmailStepSubmitting(false);
      setMfaStepSubmitting(false);
    }
  };

  const handleEmailContinue = async () => {
    if (!emailStep) return;
    const trimmed = emailStep.value.trim();
    if (!isValidEmail(trimmed)) {
      setEmailStepError('Please enter a valid email address');
      return;
    }
    setEmailStepError(null);
    setEmailStepSubmitting(true);
    try {
      const res = await fetch('/api/auth/propose-email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ leaderId: emailStep.match.id, mobile: mobile.trim(), firstName: firstName.trim(), email: trimmed }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to send confirmation email');
      setEmailStep({ ...emailStep, value: trimmed, phase: 'sent' });
    } catch (err: unknown) {
      setEmailStepError(getErrorMessage(err, 'Failed to send confirmation email. Please try again.'));
    } finally {
      setEmailStepSubmitting(false);
    }
  };

  // Fallback for a leader whose magic-link click never arrives server-side
  // (seen live for Apple Mail users — Mail Privacy Protection silently
  // pre-fetches, and thereby consumes, the one-time link before they ever
  // tap it). Mirrors app/confirm-email/page.tsx's own request shape exactly,
  // just driven by a typed code instead of a clicked link.
  const handleEmailCodeVerify = async (code: string) => {
    if (!emailStep) return;
    const { data, error } = await emailConfirmSupabase.auth.verifyOtp({ email: emailStep.value, token: code, type: 'email' });
    if (error || !data.session) throw error ?? new Error('Invalid or expired code');
    try {
      const res = await fetch('/api/auth/confirm-email', {
        method: 'POST',
        headers: { Authorization: `Bearer ${data.session.access_token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ leaderId: emailStep.match.id }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to confirm email');
    } finally {
      await emailConfirmSupabase.auth.signOut();
    }
    // Unlike the across-tab link flow (where this page has no way to know
    // confirmation happened elsewhere, so match.email stays stale until the
    // next login), this path knows synchronously that it just succeeded —
    // so it can proceed straight into the 2FA setup step this same sitting.
    const confirmedMatch = { ...emailStep.match, email: emailStep.value };
    setEmailStep(null);
    setMfaStep({ match: confirmedMatch, phase: 'offer' });
  };

  const handleMfaContinue = async () => {
    if (!mfaStep) return;
    setMfaStepError(null);
    setMfaStepSubmitting(true);
    try {
      const res = await fetch('/api/auth/request-mfa-setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ leaderId: mfaStep.match.id, mobile: mobile.trim(), firstName: firstName.trim() }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to send sign-in link');
      setMfaStep({ ...mfaStep, phase: 'sent' });
    } catch (err: unknown) {
      setMfaStepError(getErrorMessage(err, 'Failed to send sign-in link. Please try again.'));
    } finally {
      setMfaStepSubmitting(false);
    }
  };

  // Same Apple-Mail-prefetch fallback as handleEmailCodeVerify, for the MFA
  // magic link. Establishing the session here via the same isolated client
  // /setup-mfa itself uses is enough — that page's own getSession() race
  // cover (built for "session already exists by the time the listener
  // subscribes") picks it up and runs its normal TOTP/AAL2 flow unmodified.
  const handleMfaCodeVerify = async (code: string) => {
    if (!mfaStep?.match.email) return;
    const { data, error } = await emailConfirmSupabase.auth.verifyOtp({ email: mfaStep.match.email, token: code, type: 'email' });
    if (error || !data.session) throw error ?? new Error('Invalid or expired code');
    // Leaving this screen for good — don't let /login restore it later (lib/pendingLoginStep.ts).
    clearPendingLoginStep();
    router.push('/setup-mfa');
  };

  // ── Post-sign-in: show action chooser for regular leaders, or check recent TWOL for admins ─
  const checkRecentCampaign = async (match: StateLeaderMatch) => {
    // Any other value (including stray legacy data like a recruiter's name) is
    // treated as a regular leader and shown the action chooser.
    if (!isRecognizedAdminStatus(match.admin)) {
      // Regular leader — show the action chooser instead of navigating.
      // Also check for BOTJ/TLT training campaigns and campaign-interest
      // registrations, to decide whether to show the "Manage my Training
      // Interest" / "Manage my Campaign Interest" buttons. userId is unused
      // by either call here (their fallback branches only apply when
      // userLeader/userState are missing, and match always has both), so a
      // placeholder is fine. Run in parallel — independent checks.
      const params = {
        adminStatus: match.admin,
        userState: match.state,
        userLeader: match.leader,
        userMobile: match.mobile,
        userId: '',
      };
      const [trainingResult, campaignInterestResult] = await Promise.allSettled([
        getTrainingCampaigns(params),
        hasCampaignInterestForLeader(params),
      ]);
      // Non-fatal — a button just won't show if its check fails.
      if (trainingResult.status === 'fulfilled') setHasTrainingCampaigns(trainingResult.value.length > 0);
      if (campaignInterestResult.status === 'fulfilled') setHasCampaignInterest(campaignInterestResult.value);
      setShowActionChooser(true);
      return;
    }
    try {
      const recent = await getRecentTWOLCampaignsForLeader(match.leader);
      if (recent.length > 0) {
        setRecentCampaigns(recent);
        return;
      }
    } catch {
      // Non-fatal — fall through to normal navigation
    }
    router.push('/app');
  };

  const handleActionChoice = (choice: ActionChoice) => {
    switch (choice) {
      case 'record-past':
        router.push('/app?filter=past');
        break;
      case 'review-upcoming':
        router.push('/app');
        break;
      case 'create-new':
        router.push('/app?openForm=true');
        break;
      case 'campaign-rules':
        router.push('/admin/campaign-rules');
        break;
      case 'training-interest':
        router.push('/training-interest');
        break;
      case 'campaign-interest':
        router.push('/campaign-interest');
        break;
    }
  };

  // ── Step 2 (multi-state only): complete sign-in with chosen state ─────────
  const handleStateSelect = async (match: StateLeaderMatch) => {
    setError(null);
    setIsLoading(true);
    setSelectedStateId(match.id);
    try {
      const gate = getAdminLoginGate(match, { requireTwoFactor });
      if (gate) {
        setPendingMatches(null);
        setSelectedStateId(null);
        startAdminGate(match, gate);
        return;
      }
      await completeSignIn(match, { mobile, firstName });
      await refreshUser();
      trackEvent('sign_in', { state: match.state });
      await checkRecentCampaign(match);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'Failed to sign in. Please try again.'));
      setPendingMatches(null);
      setSelectedStateId(null);
    } finally {
      setIsLoading(false);
    }
  };

  // ── Loading / session-check spinner ──────────────────────────────────────
  if (showGuide) return <GuideScreen onClose={() => setShowGuide(false)} />;

  if (checkingSession) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 dark:bg-gray-900">
        <div className="text-gray-600 dark:text-gray-400">Checking sign-in status…</div>
      </div>
    );
  }

  const cardClass =
    'w-full max-w-md space-y-6 rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-blue-50 p-6 shadow-lg dark:bg-blue-900/20 sm:p-8';

  // ── Recent-campaigns modal ────────────────────────────────────────────────
  function formatCampaignLabel(date: string, time: string, place: string): string {
    const d = new Date(`${date}T00:00:00`);
    const day = d.getDate();
    const suffix = day >= 11 && day <= 13 ? 'th' : ['th','st','nd','rd'][day % 10] ?? 'th';
    const month = ['January','February','March','April','May','June','July','August','September','October','November','December'][d.getMonth()];
    const [hStr, mStr] = time.split(':');
    const h = parseInt(hStr, 10);
    const ampm = h >= 12 ? 'pm' : 'am';
    const h12 = h % 12 || 12;
    const formattedTime = `${h12}:${mStr} ${ampm}`;
    return `${place} ${day}${suffix} ${month} ${formattedTime} ... Yes?`;
  }

  if (adminSignInMatch) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={setupCardClass}>
          <div className="space-y-6">
            <SetupStep n={3} label="Sign in" />
            <h2 className={headingClass}>
              Sign in with your email
            </h2>
            <p className={bodyTextClass}>
              {isRecognizedAdminStatus(adminSignInMatch.admin)
                ? 'Admin accounts sign in with your email address and a code from your authenticator app — not your mobile number.'
                : "To see other people's personal details, sign in with your email address and a code from your authenticator app."}
            </p>
            <button
              onClick={() => router.push('/login/mfa')}
              className={primaryButtonClass}
            >
              Sign in with email
            </button>
            <button
              onClick={() => setAdminSignInMatch(null)}
              className={secondaryButtonClass}
            >
              Back
            </button>
            <GetHelp />
          </div>
        </div>
      </div>
    );
  }

  if (emailStep) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={setupCardClass}>
          <SetupStep n={1} label="Confirm your email" />
          {emailStep.phase === 'edit' ? (
            <div className="space-y-6">
              <h2 className={headingClass}>
                Add your email
              </h2>
              <p className={bodyTextClass}>
                {isRecognizedAdminStatus(emailStep.match.admin)
                  ? 'Admin accounts must use two-factor authentication, which starts with confirming your email address.'
                  : "To see other people's personal details you need two-factor authentication, which starts with confirming your email address."}
              </p>
              {emailStepError && (
                <div className={errorBannerClass}>
                  {emailStepError}
                </div>
              )}
              <input
                type="email"
                autoComplete="email"
                value={emailStep.value}
                onChange={(e) => setEmailStep({ ...emailStep, value: e.target.value })}
                className={inputClass}
                placeholder="you@example.com"
              />
              <button
                onClick={handleEmailContinue}
                disabled={emailStepSubmitting}
                className={primaryButtonClass}
              >
                {emailStepSubmitting ? 'Sending…' : 'Continue'}
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <h2 className={headingClass}>
                Check your inbox
              </h2>
              <p className={bodyTextClass}>
                We have sent an email to <strong>{emailStep.value}</strong>. Open that email and click the <strong>CONFIRM NOW</strong> link in it to confirm your email address. If you can&apos;t see it, check your Junk or Spam folder.
              </p>
              <InlineCodeFallback onVerify={handleEmailCodeVerify} />
              {emailStepError && (
                <div className={errorBannerClass}>
                  {emailStepError}
                </div>
              )}
              <button
                onClick={handleAdminProgressCheck}
                disabled={emailStepSubmitting}
                className={primaryButtonClass}
              >
                {emailStepSubmitting ? 'Checking…' : "I've confirmed my email — continue"}
              </button>
            </div>
          )}
          <GetHelp />
        </div>
      </div>
    );
  }

  if (mfaStep) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={setupCardClass}>
          <SetupStep n={2} label="Set up two-factor authentication" />
          {mfaStep.phase === 'offer' ? (
            <div className="space-y-6">
              <h2 className={headingClass}>
                Two-factor authentication is required
              </h2>
              <p className={bodyTextClass}>
                {isRecognizedAdminStatus(mfaStep.match.admin)
                  ? 'Admin accounts must use two-factor authentication. '
                  : "To see other people's personal details you need two-factor authentication. "}
                You will need a free authenticator app on your phone, such as Google Authenticator or Microsoft Authenticator.
              </p>
              {mfaStepError && (
                <div className={errorBannerClass}>
                  {mfaStepError}
                </div>
              )}
              <button
                onClick={handleMfaContinue}
                disabled={mfaStepSubmitting}
                className={primaryButtonClass}
              >
                {mfaStepSubmitting ? 'Sending…' : 'Set up now'}
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <h2 className={headingClass}>
                Check your inbox
              </h2>
              <p className={bodyTextClass}>
                We have sent an email to your email address. Open that email and click the <strong>CONFIRM NOW</strong> link in it to continue setting up your authenticator app. If you can&apos;t see it, check your Junk or Spam folder.
              </p>
              <InlineCodeFallback onVerify={handleMfaCodeVerify} />
              <p className={bodyTextClass}>
                When you have finished setting up two-factor authentication, come back here and sign in with your email.
              </p>
              <button
                onClick={() => router.push('/login/mfa')}
                className={primaryButtonClass}
              >
                Sign in with email
              </button>
            </div>
          )}
          <GetHelp />
        </div>
      </div>
    );
  }

  if (showActionChooser) {
    return (
      <div className="large-text flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <div className="space-y-6">
            <h2 className="text-center text-xl font-bold text-gray-900 dark:text-gray-100">
              What do you want to do today?
            </h2>
            <p className="text-center text-base text-gray-600 dark:text-gray-400">
              Please select an option.
            </p>
            <div className="flex flex-col gap-3">
              <button
                onClick={() => handleActionChoice('record-past')}
                className="w-full rounded-md bg-orange-600 px-4 py-3 text-base font-bold text-white hover:bg-orange-700 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
              >
                Record Results for Past Campaigns
              </button>
              <button
                onClick={() => handleActionChoice('review-upcoming')}
                className="w-full rounded-md bg-blue-600 px-4 py-3 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
              >
                Review or Update Upcoming Campaigns
              </button>
              <button
                onClick={() => handleActionChoice('create-new')}
                className="w-full rounded-md bg-green-600 px-4 py-3 text-base font-bold text-white hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
              >
                Create a New Campaign
              </button>
              <button
                onClick={() => handleActionChoice('campaign-rules')}
                className="w-full rounded-md bg-purple-600 px-4 py-3 text-base font-bold text-white hover:bg-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
              >
                Create or Update a Campaign Rule
              </button>
              {hasTrainingCampaigns && (
                <button
                  onClick={() => handleActionChoice('training-interest')}
                  className="w-full rounded-md bg-pink-600 px-4 py-3 text-base font-bold text-white hover:bg-pink-700 focus:outline-none focus:ring-2 focus:ring-pink-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
                >
                  Manage my Training Interest
                </button>
              )}
              {hasCampaignInterest && (
                <button
                  onClick={() => handleActionChoice('campaign-interest')}
                  className="w-full rounded-md bg-teal-600 px-4 py-3 text-base font-bold text-white hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
                >
                  Manage my Campaign Interest
                </button>
              )}
            </div>
            <OpenGuideButton onClick={() => setShowGuide(true)} />
          </div>
        </div>
      </div>
    );
  }

  if (recentCampaigns) {
    return (
      <div className="large-text flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <div className="space-y-6">
            <h2 className="text-center text-xl font-bold text-gray-900 dark:text-gray-100">
              Do you want to Record Results for
            </h2>
            <div className="flex flex-col gap-3">
              {recentCampaigns.map(campaign => {
                const detailParams = new URLSearchParams({
                  id:     campaign.id,
                  date:   campaign.date,
                  state:  campaign.state,
                  place:  campaign.place,
                  time:   campaign.time,
                  leader: campaign.leader,
                });
                return (
                  <button
                    key={campaign.id}
                    onClick={() => router.push(`/record-results/detail?${detailParams.toString()}`)}
                    className="w-full rounded-md bg-green-600 px-4 py-3 text-base font-bold text-white hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
                  >
                    {formatCampaignLabel(campaign.date, campaign.time, campaign.place)}
                  </button>
                );
              })}
              <button
                autoFocus
                onClick={() => router.push('/app')}
                className="w-full rounded-md bg-red-600 px-4 py-3 text-base font-bold text-white hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
              >
                No
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="large-text flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
      <div className={cardClass}>

        {/* Logo + title (always shown) */}
        <div className="flex flex-col items-center">
          <div className="mb-4 flex justify-center">
            <Image
              src="/afj_graphic.png"
              alt="AFJ Graphic"
              width={200}
              height={200}
              className="h-auto w-auto max-w-full"
              priority
            />
          </div>
          <h2 className="text-center text-2xl font-bold text-gray-900 dark:text-gray-100">
            AFJ Campaign Activity System
          </h2>
        </div>

        {/* Error banner */}
        {error && (
          <div className="rounded-md bg-red-50 p-3 text-sm text-red-800 dark:bg-red-900/20 dark:text-red-200">
            {error}
          </div>
        )}

        {/* ── State picker (step 2) ── */}
        {pendingMatches ? (
          <div className="space-y-4">
            <div>
              <p className="text-center text-sm font-semibold text-gray-700 dark:text-gray-300">
                You lead campaigns in multiple states.
              </p>
              <p className="mt-1 text-center text-sm text-gray-600 dark:text-gray-400">
                Which state are you working in today?
              </p>
            </div>

            <BusyChoiceButtons
              choices={pendingMatches.map(match => ({
                id: match.id,
                label: (
                  <>
                    {match.state}
                    {AUSTRALIAN_STATE_NAMES[match.state] && (
                      <span className="ml-2 text-sm font-normal opacity-90">
                        — {AUSTRALIAN_STATE_NAMES[match.state]}
                      </span>
                    )}
                  </>
                ),
              }))}
              selectedId={selectedStateId}
              busy={isLoading}
              onSelect={id => { const match = pendingMatches.find(m => m.id === id); if (match) handleStateSelect(match); }}
              baseClass="w-full rounded-md px-4 py-3 text-base font-bold text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600 disabled:cursor-not-allowed"
              idleClass="bg-blue-600 hover:bg-blue-700"
              selectedClass="bg-blue-600 opacity-75"
              otherClass="bg-gray-400"
            />

            <button
              onClick={() => { setPendingMatches(null); setError(null); }}
              disabled={isLoading}
              className="w-full text-sm text-blue-600 hover:text-blue-700 dark:text-blue-400 disabled:opacity-50"
            >
              ← Back
            </button>
          </div>
        ) : (

        /* ── Credentials form (step 1) ── */
          <form onSubmit={handleSubmit} className="mt-2 space-y-6">
            <p className="text-center text-sm text-gray-600 dark:text-gray-400">
              Enter your mobile number and first name<br />to sign in
            </p>
            {requireTwoFactor && (
              <p className="rounded-md bg-blue-50 p-4 text-center text-lg font-medium text-blue-900 dark:bg-blue-900/20 dark:text-blue-200">
                You will then be taken through two-factor authentication — needed to see other people&apos;s personal details.
              </p>
            )}

            <div>
              <label
                htmlFor="mobile"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                Mobile Number
              </label>
              <input
                id="mobile"
                name="mobile"
                type="tel"
                autoComplete="tel"
                required
                value={mobile}
                onChange={e => setMobile(e.target.value)}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="e.g., 0429 028 464"
                inputMode="tel"
              />
            </div>

            <div>
              <label
                htmlFor="firstName"
                className="block text-sm font-medium text-gray-700 dark:text-gray-300"
              >
                First Name
              </label>
              <input
                id="firstName"
                name="firstName"
                type="text"
                autoComplete="given-name"
                required
                value={firstName}
                onChange={e => setFirstName(e.target.value)}
                className="mt-1 block w-full rounded-md border-2 border-gray-400 bg-white px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-500 dark:bg-gray-900 dark:text-white"
                placeholder="Enter your first name"
              />
            </div>

            <div>
              <button
                type="submit"
                disabled={isLoading}
                className="w-full rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
              >
                {isLoading ? 'Signing in...' : 'Sign In'}
              </button>
            </div>

            {/* New leaders: the guide covers installing the app and signing in. */}
            <SignInGuideLink onClick={() => setShowGuide(true)} />
          </form>
        )}
      </div>
    </div>
  );
}

