'use client';

/**
 * Public, unauthenticated "Temporary Upcoming Campaigns" list — a read-only
 * view of the same fortnight shown on the (authenticated) Register Interest
 * screen, minus selection/registration. Not listed in middleware's
 * PROTECTED_PREFIXES, so it's open by default (see middleware.ts).
 *
 * Deliberately does NOT use MobileLayout — that component resolves the
 * signed-in user's admin status and assumes a logged-in session.
 *
 * Split out of page.tsx (a Server Component, for its `metadata` export —
 * a 'use client' page can't export metadata) — see page.tsx.
 */
import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import LoadingSpinner from '@/components/LoadingSpinner';
import PublicCampaignList from '@/components/PublicCampaignList';
import { getErrorMessage } from '@/lib/errorUtils';
import { generateAndDownloadSlidesFromData, type PublicSlideDay } from '@/lib/slideGenerator';
import type { AriseCampaign } from '@/lib/ariseLayout';
import type { TemporaryUpcomingCampaignsResponse } from '@/app/api/public/temporary-upcoming-campaigns/route';

const TITLE = 'Temporary AFJ Campaign Lists';
const INTRO_TEXT = 'Here is the temporary upcoming campaign list for this fortnight.';

/** Each step as [text, bold?] segments so the key words can be styled inline. */
const LEADER_BULLETS: [string, boolean][][] = [
  [['Check', true], [' that your campaign details are correct', false]],
  [['If', true], [' anything is wrong, click on the ', false], ['Edit', true], [' button to fix it', false]],
  [['If', true], [' you want to keep a copy, click on the ', false], ['Download', true], [' button to save it', false]],
];

export default function TemporaryUpcomingCampaignsClient() {
  const router = useRouter();
  const [days, setDays] = useState<PublicSlideDay[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState('');
  const [downloadError, setDownloadError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const res = await fetch('/api/public/temporary-upcoming-campaigns');
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load campaign data');
        if (cancelled) return;
        setDays((json as TemporaryUpcomingCampaignsResponse).days);
      } catch (err) {
        if (!cancelled) setLoadError(getErrorMessage(err, 'Failed to load campaign data'));
      }
    })();

    return () => { cancelled = true; };
  }, []);

  const campaigns: AriseCampaign[] = (days ?? []).flatMap((d) => d.campaigns);

  const handleEdit = () => {
    router.push('/login');
  };

  const handleDownload = async () => {
    if (!days) return;
    setIsDownloading(true);
    setDownloadError(null);
    setDownloadProgress('');
    try {
      await generateAndDownloadSlidesFromData(days, setDownloadProgress);
    } catch (err) {
      setDownloadError(getErrorMessage(err, 'Failed to generate the campaign list download'));
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div data-ti="app/public/temporary-upcoming-campaigns/TemporaryUpcomingCampaignsClient.tsx" className="flex h-dvh flex-col p-4">
      <div className="mb-3">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">{TITLE}</h1>
        <p className="mt-1 text-base text-gray-600 dark:text-gray-400">{INTRO_TEXT}</p>
        <p className="mt-2 text-base font-bold text-gray-900 dark:text-gray-100">ALL LEADERS please:</p>
        <ol className="mt-1 space-y-1 rounded-lg border border-blue-200 bg-blue-50 p-3 text-base font-medium text-blue-900 dark:border-blue-800 dark:bg-blue-900/30 dark:text-blue-100">
          {LEADER_BULLETS.map((segments, index) => (
            <li key={index}>
              <span className="font-bold">{index + 1}.</span>{' '}
              {segments.map(([text, bold], i) =>
                bold ? <span key={i} className="font-bold">{text}</span> : text,
              )}
            </li>
          ))}
        </ol>
      </div>

      {loadError && (
        <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
          {loadError}
        </div>
      )}
      {downloadError && (
        <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
          {downloadError}
        </div>
      )}

      {/* Campaign lines box — the list scrolls inside here so the two
          buttons below always stay visible on screen. */}
      <div className="relative flex-1 overflow-hidden rounded-lg border-2 border-gray-800 dark:border-gray-600">
        {days === null && !loadError && (
          <div className="absolute inset-0 z-20 flex items-center justify-center bg-white/80 dark:bg-gray-900/80">
            <LoadingSpinner text="Loading campaigns…" />
          </div>
        )}
        <div className="h-full overflow-y-auto">
          <PublicCampaignList campaigns={campaigns} />
        </div>
      </div>

      {/* Bottom action buttons — outside the campaign lines box, stretching
          the full width of the screen. */}
      <div className="mt-3 flex shrink-0 flex-col gap-2">
        {isDownloading && downloadProgress && (
          <p className="text-center text-xs text-gray-600 dark:text-gray-400">{downloadProgress}</p>
        )}
        <div className="flex gap-2">
          <button
            type="button"
            onClick={handleEdit}
            className="flex-1 rounded-md bg-green-600 px-4 py-3 text-base font-bold text-white hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
          >
            Edit
          </button>
          <button
            type="button"
            onClick={handleDownload}
            disabled={!days || isDownloading}
            className="flex-1 rounded-md bg-blue-600 px-4 py-3 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
          >
            {isDownloading ? 'Preparing…' : 'Download'}
          </button>
        </div>
      </div>
    </div>
  );
}

import type { Metadata } from 'next';
import TemporaryUpcomingCampaignsClient from './TemporaryUpcomingCampaignsClient';
import { PUBLIC_LINKS, PUBLIC_LINK_OG_IMAGE, publicLinkTitleSettingKey, publicLinkDescriptionSettingKey } from '@/lib/publicLinks';
import { getSettingServer } from '@/lib/appSettings';

const LINK = PUBLIC_LINKS.find((l) => l.slug === 'temporary-upcoming-campaigns')!;

// Without this, Next.js prerenders the page (and runs generateMetadata) once
// at build time and bakes the result into static HTML — an admin's title/
// description edit on /admin/public-links would then only take effect on
// the next deploy, not immediately. Forces per-request rendering instead.
export const dynamic = 'force-dynamic';

// A Server Component (no 'use client') so it can export `metadata` — link
// previews (WhatsApp, iMessage, etc.) read these Open Graph/Twitter tags to
// build a rich preview card. Without them, some clients show a bare
// "Copy link / Open link" prompt instead of navigating straight through.
//
// Dynamic (generateMetadata, not a static `export const metadata`) so an
// admin's title/description override from /admin/public-links — saved to
// app_settings — takes effect without a redeploy. Falls back to the code
// default in lib/publicLinks.ts when no override is set.
export async function generateMetadata(): Promise<Metadata> {
  const [titleOverride, descriptionOverride] = await Promise.all([
    getSettingServer(publicLinkTitleSettingKey(LINK.slug)),
    getSettingServer(publicLinkDescriptionSettingKey(LINK.slug)),
  ]);
  const title = titleOverride || LINK.title;
  const description = descriptionOverride || LINK.description;

  return {
    title,
    description,
    openGraph: {
      title,
      description,
      url: LINK.path,
      type: 'website',
      // Some clients (Slack, iMessage) show this friendlier label instead of
      // the bare domain under the preview card. WhatsApp shows the domain
      // regardless, as its own transparency feature — not controllable here.
      siteName: 'AFJ Campaign App',
      // Branded app icon. Without an explicit image, some clients (iMessage
      // link previews on macOS) fall back to a generic placeholder — in this
      // case a default Vercel image — rather than no image at all, which
      // reads worse than just showing our own icon. Deliberately the small
      // 192x192 icon (see PUBLIC_LINK_OG_IMAGE) — a large, undeclared image
      // makes WhatsApp render a big banner-style card instead of a compact
      // thumbnail beside the text.
      images: [PUBLIC_LINK_OG_IMAGE],
    },
    twitter: {
      card: 'summary',
      title,
      description,
      images: [PUBLIC_LINK_OG_IMAGE.url],
    },
  };
}

export default function TemporaryUpcomingCampaignsPage() {
  return <TemporaryUpcomingCampaignsClient />;
}

