'use client';

import { useCallback, useEffect, useMemo, useRef, useState, type ChangeEvent, type CSSProperties, type ReactNode } from 'react';
import Link from 'next/link';
import { registrySupabase } from '@/lib/registrySupabaseClient';
import { useRegistryGate } from '@/app/registry/useRegistryGate';
import { isNationalRegistryAdmin, type MfaGateResult } from '@/lib/registryPipeline/mfaGate';
import type {
  ManageRecordEditResponse,
  ManageRegistrant,
  ManageSummaryResponse,
  SyncLogSummary,
} from '@/lib/registryPipeline/manageSummaryTypes';
import {
  FILTER_PERIOD_OPTIONS,
  OTHER_FILTER_OPTIONS,
  MANAGE_CONSOLE_STATES,
  countAllRegistrants,
  countRegistrantsForPeriod,
  countRegistrantsByCategory,
  filterRegistrantsForCell,
  filterRegistrantsByCategoryForCell,
  type ConsoleColumn,
  type FilterPeriod,
  type OtherFilterCategory,
  type PeriodCounts,
} from '@/lib/registryPipeline/registrantCounts';
import type { EditableRegistrantField } from '@/lib/registryPipeline/registrantValidation';
import {
  LOOKUP_FIELDS,
  LOOKUP_FIELD_LABELS,
  getLookupOptions,
  filterByLookups,
  type LookupField,
  type LookupFilters,
  type LookupOption,
} from '@/lib/registryPipeline/registrantLookupFilters';
import {
  PAGE_SIZE_OPTIONS,
  DEFAULT_PAGE_SIZE,
  getPageCount,
  getPageSlice,
  sortRegistrants,
  type PageSize,
  type RecordSortColumn,
  type SortDirection,
} from '@/lib/registryPipeline/registrantSort';
import { getSlideStateShade } from '@/lib/slideLayout';
import { AUSTRALIAN_STATES } from '@/lib/constants';

const ALLOW: MfaGateResult[] = ['ok'];

// Cells (Total/Unknown) that aren't tied to a specific state color still
// need a "selected" look — a neutral accent rather than no color at all.
const NEUTRAL_HIGHLIGHT = 'rgba(37, 99, 235, 0.18)';

type RowKey = 'all' | 'primary' | 'other';

interface SelectedCell {
  row: RowKey;
  rowLabel: string;
  column: ConsoleColumn;
  columnLabel: string;
}

type PaneMode = 'view' | 'edit';

const DEFAULT_SELECTED_CELL: SelectedCell = { row: 'all', rowLabel: 'All AFJ Registrations', column: 'total', columnLabel: 'Total' };

type SaveEditResult = { ok: true } | { ok: false; error: string };

/** Persists one field edit (PATCH /api/registry/manage-record) and reports success/failure — the editable cells below revert their own display on failure, they don't need to know how saving actually works. */
type SaveEditFn = (recordId: string, field: EditableRegistrantField, value: string) => Promise<SaveEditResult>;

const cellStyle: CSSProperties = { border: '1px solid #ccc', padding: '0.6rem 0.75rem', textAlign: 'center' };
const headerCellStyle: CSSProperties = { ...cellStyle, fontWeight: 600, background: '#f3f4f6' };
const sortableHeaderCellStyle: CSSProperties = { ...headerCellStyle, cursor: 'pointer', userSelect: 'none' };
const labelCellStyle: CSSProperties = { ...cellStyle, textAlign: 'left', fontWeight: 600, background: '#f3f4f6' };
const numberButtonStyle: CSSProperties = {
  font: 'inherit',
  fontWeight: 600,
  cursor: 'pointer',
  background: 'transparent',
  border: 'none',
  padding: '0.15rem 0.4rem',
  borderRadius: 4,
  width: '100%',
};

function formatDateTime(iso: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? iso : d.toLocaleString('en-AU', { dateStyle: 'medium', timeStyle: 'short' });
}

/** Date only, no time — for the record pane's "Registered" column specifically (formatDateTime above still carries the time where it's actually useful, e.g. the last cron run). */
function formatDateOnly(iso: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? iso : d.toLocaleDateString('en-AU', { day: 'numeric', month: 'short', year: 'numeric' });
}

function statusLabel(sync: SyncLogSummary): string {
  switch (sync.status) {
    case 'success': return 'Completed successfully';
    case 'failed': return 'Failed';
    case 'partial': return 'Stopped partway (time budget) — resumes next run';
    case 'crashed': return 'Crashed before completion';
    default: return sync.completedAt ? 'Completed (pre-status rows)' : 'Still running, or crashed without recording an outcome';
  }
}

function statusColor(sync: SyncLogSummary): string {
  switch (sync.status) {
    case 'success': return '#15803d';
    case 'failed':
    case 'crashed': return '#b91c1c';
    case 'partial': return '#b45309';
    default: return '#6b7280';
  }
}

/** Background for one grid cell: the column's state tint (or a neutral accent for Total/Unknown), boosted in intensity when this is the cell currently shown in the record pane below. */
function cellShade(column: ConsoleColumn, isSelected: boolean): string {
  const isState = (MANAGE_CONSOLE_STATES as readonly string[]).includes(column);
  if (isState) return getSlideStateShade(column, isSelected ? 0.45 : 0.14);
  return isSelected ? NEUTRAL_HIGHLIGHT : 'transparent';
}

/** One number cell in the grid — a click target when it has records, otherwise plain text. */
function CountCell({
  count,
  column,
  isSelected,
  onSelect,
}: {
  count: number | null;
  column: ConsoleColumn;
  isSelected: boolean;
  onSelect: (column: ConsoleColumn) => void;
}) {
  return (
    <td style={{ ...cellStyle, padding: '0.35rem', background: cellShade(column, isSelected) }}>
      {count === null ? (
        '—'
      ) : count > 0 ? (
        <button type="button" onClick={() => onSelect(column)} style={numberButtonStyle} aria-pressed={isSelected}>
          {count.toLocaleString('en-AU')}
        </button>
      ) : (
        <span style={{ color: '#9ca3af' }}>0</span>
      )}
    </td>
  );
}

/** One row of the console grid: a label, an optional control (a dropdown of some kind — the caller decides which, or none for the unfiltered "All" row), and the resulting counts. */
function ConsoleRow({
  rowKey,
  label,
  control,
  counts,
  selectedCell,
  onSelectCell,
}: {
  rowKey: RowKey;
  label: string;
  control?: ReactNode;
  counts: PeriodCounts | null;
  selectedCell: SelectedCell | null;
  onSelectCell: (column: ConsoleColumn, columnLabel: string) => void;
}) {
  const isSelected = (column: ConsoleColumn) => selectedCell?.row === rowKey && selectedCell.column === column;

  return (
    <tr>
      <td style={labelCellStyle}>{label}</td>
      <td style={{ ...cellStyle, background: '#f9fafb' }}>{control}</td>
      <CountCell count={counts?.total ?? null} column="total" isSelected={isSelected('total')} onSelect={() => onSelectCell('total', 'Total')} />
      {MANAGE_CONSOLE_STATES.map((state) => (
        <CountCell
          key={state}
          count={counts?.byState[state] ?? null}
          column={state}
          isSelected={isSelected(state)}
          onSelect={() => onSelectCell(state, state)}
        />
      ))}
      <CountCell count={counts?.unknown ?? null} column="unknown" isSelected={isSelected('unknown')} onSelect={() => onSelectCell('unknown', 'Unknown')} />
    </tr>
  );
}

/** The period-dropdown control for a date-based row (currently just Primary Filter) — factored out so ConsoleRow itself doesn't need to know about FilterPeriod specifically. */
function PeriodControl({ label, value, onChange }: { label: string; value: FilterPeriod; onChange: (period: FilterPeriod) => void }) {
  return (
    <select
      aria-label={`${label} period`}
      value={value}
      onChange={(e) => onChange(e.target.value as FilterPeriod)}
      style={{ padding: '0.3rem', width: '100%' }}
    >
      {FILTER_PERIOD_OPTIONS.map((opt) => (
        <option key={opt.value} value={opt.value}>{opt.label}</option>
      ))}
    </select>
  );
}

/** The category-dropdown control for the "Other Filters" row — Unsubscribed or No Further Contact, in place of a date period. */
function CategoryControl({ label, value, onChange }: { label: string; value: OtherFilterCategory; onChange: (category: OtherFilterCategory) => void }) {
  return (
    <select
      aria-label={`${label} category`}
      value={value}
      onChange={(e) => onChange(e.target.value as OtherFilterCategory)}
      style={{ padding: '0.3rem', width: '100%' }}
    >
      {OTHER_FILTER_OPTIONS.map((opt) => (
        <option key={opt.value} value={opt.value}>{opt.label}</option>
      ))}
    </select>
  );
}

const editInputStyle: CSSProperties = { width: '100%', padding: '0.3rem', border: '1px solid #ccc', borderRadius: 4, font: 'inherit' };

/**
 * Per-field sizing for EditableTextCell's <input> — a plain flex-fill (the
 * default) left every text field stretching to however wide its column
 * happened to be once the page container itself was widened, which looked
 * absurd for a short, length-bounded value like a postcode or a name.
 * Fields not listed here keep the original flex-fill behaviour.
 */
const TEXT_FIELD_SIZE: Partial<Record<EditableRegistrantField, { maxLength: number; width: string }>> = {
  postcode: { maxLength: 4, width: '4.5rem' },
  firstName: { maxLength: 20, width: '12rem' },
  lastName: { maxLength: 20, width: '12rem' },
};
const editErrorStyle: CSSProperties = { color: 'crimson', fontSize: '0.75rem', marginTop: '0.15rem' };

/** A free-text editable cell (First name / Last name / Postcode) — saves on blur or Enter, only if the value actually changed; reverts to the last-known-good value and shows an error inline if the save is rejected. */
function EditableTextCell({
  recordId,
  field,
  value,
  onSave,
  suffix,
}: {
  recordId: string;
  field: EditableRegistrantField;
  value: string | null;
  onSave: SaveEditFn;
  /** Extra content shown beside the input — e.g. the leader icon next to Last name. */
  suffix?: ReactNode;
}) {
  const [draft, setDraft] = useState(value ?? '');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Resets the draft when the underlying value changes (e.g. this record
  // scrolled out and a different one now occupies this row — React reuses
  // the component instance since key={r.id} isn't set per-column). Adjusting
  // state during render, not in an effect, per the react-hooks/set-state-in-effect
  // rule — see app/app/components/useStateDropdowns.ts for the same rule
  // satisfied a different way (Promise chains) for an async case; this is
  // the simpler synchronous "reset on prop change" case React's own docs
  // recommend handling this way.
  const [lastValue, setLastValue] = useState(value);
  if (value !== lastValue) {
    setLastValue(value);
    setDraft(value ?? '');
  }

  async function commit() {
    if (draft === (value ?? '')) return;
    setIsSaving(true);
    setError(null);
    const result = await onSave(recordId, field, draft);
    setIsSaving(false);
    if (!result.ok) {
      setError(result.error);
      setDraft(value ?? ''); // revert — the edit was rejected, don't leave an unsaved value showing as if it stuck.
    }
  }

  const sizing = TEXT_FIELD_SIZE[field];

  return (
    <td style={{ padding: '0.35rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
        <input
          type="text"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => {
            if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
          }}
          disabled={isSaving}
          maxLength={sizing?.maxLength}
          style={sizing ? { ...editInputStyle, width: sizing.width, flex: '0 0 auto' } : { ...editInputStyle, width: 'auto', flex: '1 1 auto' }}
          aria-label={field}
        />
        {suffix}
      </div>
      {error && <div style={editErrorStyle}>{error}</div>}
    </td>
  );
}

/** The State cell in edit mode — a constrained dropdown (never free text), so a correction can't introduce a new typo. Saves immediately on change; the parent's own value flows back in as the `value` prop, so a rejected save reverts the visible selection with no local draft state needed. */
function EditableStateCell({ recordId, value, onSave }: { recordId: string; value: string | null; onSave: SaveEditFn }) {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleChange(e: ChangeEvent<HTMLSelectElement>) {
    setIsSaving(true);
    setError(null);
    const result = await onSave(recordId, 'state', e.target.value);
    setIsSaving(false);
    if (!result.ok) setError(result.error);
  }

  return (
    <td style={{ padding: '0.35rem' }}>
      {/* minWidth beyond the plain 100% fill — a bare 3-letter state code left too little room next to the browser's own dropdown arrow, obscuring the value. */}
      <select value={value ?? ''} onChange={handleChange} disabled={isSaving} style={{ ...editInputStyle, minWidth: '5rem' }} aria-label="state">
        <option value="">—</option>
        {AUSTRALIAN_STATES.map((s) => (
          <option key={s} value={s}>{s}</option>
        ))}
      </select>
      {error && <div style={editErrorStyle}>{error}</div>}
    </td>
  );
}

/** The NFC cell in edit mode — a fixed Yes/blank control (never a recorded 'No', matching this column's convention elsewhere), same "saves immediately, no local draft" shape as EditableStateCell. */
function EditableNfcCell({ recordId, value, onSave }: { recordId: string; value: string | null; onSave: SaveEditFn }) {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleChange(e: ChangeEvent<HTMLSelectElement>) {
    setIsSaving(true);
    setError(null);
    const result = await onSave(recordId, 'nfc', e.target.value);
    setIsSaving(false);
    if (!result.ok) setError(result.error);
  }

  return (
    <td style={{ padding: '0.35rem' }}>
      {/* Same reasoning as EditableStateCell's minWidth above — "Yes" was cramped against the dropdown arrow. */}
      <select value={value ?? ''} onChange={handleChange} disabled={isSaving} style={{ ...editInputStyle, minWidth: '4.5rem' }} aria-label="nfc">
        <option value="">—</option>
        <option value="Yes">Yes</option>
      </select>
      {error && <div style={editErrorStyle}>{error}</div>}
    </td>
  );
}

const lookupInputStyle: CSSProperties = { padding: '0.3rem', minWidth: 130, border: '1px solid #ccc', borderRadius: 4, font: 'inherit' };
const lookupOptionStyle: CSSProperties = {
  display: 'block', width: '100%', textAlign: 'left', padding: '0.3rem 0.6rem', background: 'none', border: 'none',
  cursor: 'pointer', font: 'inherit', fontSize: '0.85rem', color: '#111827',
};

/**
 * One "type to filter, then pick" lookup dropdown — a text input that
 * narrows a floating options list to whatever's typed, rather than a plain
 * <select> the admin has to scroll through. Typing filters by substring
 * (case-insensitive) against each option's label; Enter picks the top match,
 * Escape or a click outside closes without changing the selection.
 */
function LookupSelect({
  field,
  label,
  options,
  value,
  onChange,
}: {
  field: LookupField;
  label: string;
  options: LookupOption[];
  value: string;
  onChange: (value: string) => void;
}) {
  const selectedLabel = value === '' ? '' : (options.find((opt) => opt.value === value)?.label ?? value);
  const [query, setQuery] = useState(selectedLabel);
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Re-sync the displayed text when the selection changes from outside this
  // component (e.g. "Reset lookups", or a different grid cell resetting all
  // filters) — same reset-during-render pattern as EditableTextCell's
  // `lastValue` above, not a useEffect, per the react-hooks/set-state-in-effect rule.
  const [lastValue, setLastValue] = useState(value);
  if (value !== lastValue) {
    setLastValue(value);
    setQuery(selectedLabel);
  }

  useEffect(() => {
    if (!open) return;
    function handlePointerDown(e: MouseEvent) {
      if (!containerRef.current?.contains(e.target as Node)) {
        setOpen(false);
        setQuery(selectedLabel);
      }
    }
    document.addEventListener('mousedown', handlePointerDown);
    return () => document.removeEventListener('mousedown', handlePointerDown);
  }, [open, selectedLabel]);

  const filtered = query.trim() === ''
    ? options
    : options.filter((opt) => opt.label.toLowerCase().includes(query.trim().toLowerCase()));

  function select(optValue: string, optLabel: string) {
    onChange(optValue);
    setQuery(optLabel);
    setOpen(false);
  }

  return (
    <div ref={containerRef} style={{ position: 'relative', display: 'flex', flexDirection: 'column', gap: '0.2rem' }}>
      <label htmlFor={`lookup-${field}`} style={{ fontSize: '0.8rem', color: '#374151' }}>{label}</label>
      <input
        id={`lookup-${field}`}
        type="text"
        value={query}
        onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
        onFocus={(e) => { setOpen(true); e.target.select(); }}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            setOpen(false);
            setQuery(selectedLabel);
            (e.target as HTMLInputElement).blur();
          } else if (e.key === 'Enter') {
            e.preventDefault();
            if (filtered.length > 0) select(filtered[0].value, filtered[0].label);
            else select('', '');
          }
        }}
        placeholder="All"
        autoComplete="off"
        style={lookupInputStyle}
        aria-label={`Look up by ${label}`}
      />
      {open && (
        <ul
          role="listbox"
          aria-label={`${label} options`}
          style={{
            position: 'absolute', top: '100%', left: 0, right: 0, marginTop: 2, maxHeight: 220, overflowY: 'auto',
            background: '#fff', border: '1px solid #ccc', borderRadius: 4, listStyle: 'none', padding: '0.25rem 0',
            zIndex: 20, boxShadow: '0 2px 6px rgba(0,0,0,0.12)',
          }}
        >
          <li>
            <button type="button" role="option" aria-selected={value === ''} onClick={() => select('', '')} style={lookupOptionStyle}>All</button>
          </li>
          {filtered.length === 0 ? (
            <li style={{ padding: '0.3rem 0.6rem', color: '#9ca3af', fontSize: '0.85rem' }}>No matches</li>
          ) : (
            filtered.map((opt) => (
              <li key={opt.value}>
                <button type="button" role="option" aria-selected={value === opt.value} onClick={() => select(opt.value, opt.label)} style={lookupOptionStyle}>
                  {opt.label}
                </button>
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  );
}

/** The "find a record by a specific value" dropdowns above the pane's table — one per field, each already populated from the values actually present among the selected cell's records. */
function LookupFiltersRow({
  options,
  filters,
  onChange,
  onReset,
}: {
  options: Record<LookupField, LookupOption[]>;
  filters: LookupFilters;
  onChange: (field: LookupField, value: string) => void;
  onReset: () => void;
}) {
  const anyActive = LOOKUP_FIELDS.some((field) => !!filters[field]);

  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'flex-end', gap: '0.75rem', margin: '0.75rem 0' }}>
      {LOOKUP_FIELDS.map((field) => (
        <LookupSelect
          key={field}
          field={field}
          label={LOOKUP_FIELD_LABELS[field]}
          options={options[field]}
          value={filters[field] ?? ''}
          onChange={(value) => onChange(field, value)}
        />
      ))}
      {anyActive && (
        <button type="button" onClick={onReset} style={{ background: 'none', border: 'none', color: '#2563eb', cursor: 'pointer', padding: '0.3rem 0' }}>
          Reset lookups
        </button>
      )}
    </div>
  );
}

/** The record pane under the grid — every registrant behind the currently-selected cell, shaded per row the same way as Recent Registrations. The View/Edit toggle controls whether First name/Last name/State/Postcode/NFC render as plain text or as inline-editable cells (NFC added 2026-09-25 — a manual flag alongside the unsubscribed/nfc filter checkboxes above, for cases the sheet cross-reference/CSV backfill couldn't resolve on their own); Email/Mobile/Date registered and the four webinar/Code-of-Conduct columns (synced/derived from AC — see lib/registryPipeline/tagDerivedFields.ts) are never editable here (see lib/registryPipeline/registrantValidation.ts). The lookup dropdowns above the table further narrow which of those records are shown, by an exact value on any field except State/Date registered. */
function RecordsPane({
  selectedCell,
  records,
  totalForCell,
  onClear,
  mode,
  onModeChange,
  onSaveEdit,
  lookupOptions,
  lookupFilters,
  onLookupFilterChange,
  onResetLookups,
  listKey,
}: {
  selectedCell: SelectedCell;
  records: ManageRegistrant[];
  /** The cell's full unfiltered-by-lookups count, for the "N of M" header when a lookup narrows the list. */
  totalForCell: number;
  onClear: () => void;
  mode: PaneMode;
  onModeChange: (mode: PaneMode) => void;
  onSaveEdit: SaveEditFn;
  lookupOptions: Record<LookupField, LookupOption[]>;
  lookupFilters: LookupFilters;
  onLookupFilterChange: (field: LookupField, value: string) => void;
  onResetLookups: () => void;
  /** Changes whenever the listed set changes (selected cell or lookups) — the pane returns to page 1. */
  listKey: string;
}) {
  // Sort is a view preference, not tied to which cell is selected — unlike
  // paneMode/lookupFilters (reset on cell change since they concern that
  // specific record set), a "sort by Last name" choice stays meaningful no
  // matter which cell you look at next, so it's just local state here with
  // no reset wiring from the parent.
  const [sortColumn, setSortColumn] = useState<RecordSortColumn>('registeredAt');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  function toggleSort(column: RecordSortColumn) {
    setPage(1);
    if (column === sortColumn) {
      setSortDirection((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortColumn(column);
      setSortDirection('asc');
    }
  }

  function sortIndicator(column: RecordSortColumn): string {
    if (column !== sortColumn) return '';
    return sortDirection === 'asc' ? ' ▲' : ' ▼';
  }

  // The list is paged rather than capped: every record is reachable, however
  // it's sorted. Page 1 again whenever what's listed (cell, lookups) changes.
  const [pageSize, setPageSize] = useState<PageSize>(DEFAULT_PAGE_SIZE);
  const [page, setPage] = useState(1);
  const [seenListKey, setSeenListKey] = useState(listKey);
  if (seenListKey !== listKey) {
    setSeenListKey(listKey);
    setPage(1);
  }

  const sorted = useMemo(() => sortRegistrants(records, sortColumn, sortDirection), [records, sortColumn, sortDirection]);
  const pageCount = getPageCount(sorted.length, pageSize);
  const currentPage = Math.min(page, pageCount);
  const shown = getPageSlice(sorted, currentPage, pageSize);
  const firstShown = sorted.length === 0 ? 0 : pageSize === 'all' ? 1 : (currentPage - 1) * pageSize + 1;
  const lastShown = firstShown === 0 ? 0 : firstShown + shown.length - 1;

  function sortableHeader(column: RecordSortColumn, label: string) {
    const active = column === sortColumn;
    return (
      <th
        style={sortableHeaderCellStyle}
        onClick={() => toggleSort(column)}
        aria-sort={active ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
      >
        {label}{sortIndicator(column)}
      </th>
    );
  }

  const pager = (
    <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: '0.75rem', margin: '0.5rem 0' }}>
      <span>
        Showing {firstShown.toLocaleString('en-AU')}–{lastShown.toLocaleString('en-AU')} of {sorted.length.toLocaleString('en-AU')}
      </span>
      <button type="button" onClick={() => setPage(Math.max(1, currentPage - 1))} disabled={currentPage <= 1}>← Previous</button>
      <span>Page {currentPage.toLocaleString('en-AU')} of {pageCount.toLocaleString('en-AU')}</span>
      <button type="button" onClick={() => setPage(Math.min(pageCount, currentPage + 1))} disabled={currentPage >= pageCount}>Next →</button>
      <label>
        Rows per page{' '}
        <select
          value={String(pageSize)}
          onChange={(e) => {
            setPageSize(e.target.value === 'all' ? 'all' : (Number(e.target.value) as PageSize));
            setPage(1);
          }}
        >
          {PAGE_SIZE_OPTIONS.map((o) => (
            <option key={o} value={String(o)}>{o === 'all' ? 'All' : o}</option>
          ))}
        </select>
      </label>
    </div>
  );

  return (
    <div style={{ marginTop: '1.5rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', flexWrap: 'wrap', gap: '1rem' }}>
        <h2 style={{ margin: 0, fontSize: '1.1rem' }}>
          {selectedCell.rowLabel} — {selectedCell.columnLabel} (
          {records.length === totalForCell
            ? records.length.toLocaleString('en-AU')
            : `${records.length.toLocaleString('en-AU')} of ${totalForCell.toLocaleString('en-AU')}`}
          )
        </h2>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <span role="radiogroup" aria-label="Pane mode" style={{ display: 'flex', gap: '0.75rem' }}>
            <label style={{ cursor: 'pointer' }}>
              <input type="radio" name="pane-mode" checked={mode === 'view'} onChange={() => onModeChange('view')} /> View
            </label>
            <label style={{ cursor: 'pointer' }}>
              <input type="radio" name="pane-mode" checked={mode === 'edit'} onChange={() => onModeChange('edit')} /> Edit
            </label>
          </span>
          <button type="button" onClick={onClear} style={{ background: 'none', border: 'none', color: '#2563eb', cursor: 'pointer', padding: 0 }}>
            Clear selection
          </button>
        </div>
      </div>

      <LookupFiltersRow options={lookupOptions} filters={lookupFilters} onChange={onLookupFilterChange} onReset={onResetLookups} />

      {mode === 'edit' && (
        <p style={{ color: '#6b7280', fontSize: '0.85rem', marginTop: '0.35rem' }}>
          Editing First name, Last name, State, Postcode, and NFC — each field saves on its own as soon as you leave it (or change the selection, for State/NFC). Email, Mobile, Date registered, and the webinar/Code of Conduct fields can&apos;t be changed here.
        </p>
      )}

      {pager}

      <div style={{ overflowX: 'auto', marginTop: '0.5rem' }}>
        <table aria-label="Matching records" style={{ width: '100%', borderCollapse: 'collapse', minWidth: 1300 }}>
          <thead>
            <tr>
              {sortableHeader('firstName', 'First name')}
              {sortableHeader('lastName', 'Last name')}
              {sortableHeader('email', 'Email')}
              {sortableHeader('phone', 'Mobile')}
              {sortableHeader('state', 'State')}
              {sortableHeader('postcode', 'Postcode')}
              {sortableHeader('nfc', 'NFC')}
              {sortableHeader('churchName', 'Church')}
              {sortableHeader('registeredAt', 'Registered')}
              {sortableHeader('webinarSessionAt', 'Webinar session')}
              {sortableHeader('webinarAttended', 'Webinar attended')}
              {sortableHeader('codeOfConductAgreed', 'Code agreed')}
              {sortableHeader('codeOfConductAgreedAt', 'Date agreed')}
            </tr>
          </thead>
          <tbody>
            {shown.map((r) => {
              const leaderIcon = r.isLeader ? (
                <span
                  role="img"
                  aria-label="Registered as a state leader"
                  title={r.leaderName ? `Leader: ${r.leaderName}` : 'Registered as a state leader'}
                  style={{ color: '#d97706', fontSize: '0.95rem', lineHeight: 1 }}
                >
                  ★
                </span>
              ) : null;

              return (
                <tr key={r.id} style={{ borderBottom: '1px solid #eee', background: getSlideStateShade(r.state) }}>
                  {mode === 'edit' ? (
                    <EditableTextCell recordId={r.id} field="firstName" value={r.firstName} onSave={onSaveEdit} />
                  ) : (
                    <td style={{ padding: '0.5rem' }}>{r.firstName ?? '—'}</td>
                  )}
                  {mode === 'edit' ? (
                    <EditableTextCell recordId={r.id} field="lastName" value={r.lastName} onSave={onSaveEdit} suffix={leaderIcon} />
                  ) : (
                    <td style={{ padding: '0.5rem' }}>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
                        {r.lastName ?? '—'}
                        {leaderIcon}
                      </span>
                    </td>
                  )}
                  <td style={{ padding: '0.5rem' }}>{r.email ?? '—'}</td>
                  <td style={{ padding: '0.5rem' }}>{r.phone ?? '—'}</td>
                  {mode === 'edit' ? (
                    <EditableStateCell recordId={r.id} value={r.state} onSave={onSaveEdit} />
                  ) : (
                    <td style={{ padding: '0.5rem' }}>{r.state ?? '—'}</td>
                  )}
                  {mode === 'edit' ? (
                    <EditableTextCell recordId={r.id} field="postcode" value={r.postcode} onSave={onSaveEdit} />
                  ) : (
                    <td style={{ padding: '0.5rem' }}>{r.postcode ?? '—'}</td>
                  )}
                  {mode === 'edit' ? (
                    <EditableNfcCell recordId={r.id} value={r.nfc} onSave={onSaveEdit} />
                  ) : (
                    <td style={{ padding: '0.5rem' }}>{r.nfc ?? '—'}</td>
                  )}
                  <td style={{ padding: '0.5rem' }}>{r.churchName ?? '—'}</td>
                  <td style={{ padding: '0.5rem' }}>{formatDateOnly(r.registeredAt)}</td>
                  <td style={{ padding: '0.5rem' }}>{formatDateTime(r.webinarSessionAt)}</td>
                  <td style={{ padding: '0.5rem' }}>{r.webinarAttended ?? '—'}</td>
                  <td style={{ padding: '0.5rem' }}>{r.codeOfConductAgreed ?? '—'}</td>
                  <td style={{ padding: '0.5rem' }}>{formatDateOnly(r.codeOfConductAgreedAt)}</td>
                </tr>
              );
            })}
            {shown.length === 0 && (
              <tr><td colSpan={13} style={{ padding: '1rem', textAlign: 'center' }}>No matching records.</td></tr>
            )}
          </tbody>
        </table>
      </div>
      {shown.length > 10 && pager}
    </div>
  );
}

export default function RegistryManagePage() {
  const gate = useRegistryGate(ALLOW);
  const [summary, setSummary] = useState<ManageSummaryResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [primaryPeriod, setPrimaryPeriod] = useState<FilterPeriod>('last_7_days');
  const [otherFilterCategory, setOtherFilterCategory] = useState<OtherFilterCategory>('unsubscribed');
  // Opens on the whole database (All AFJ Registrations × Total) so the full
  // list is there to sort and page through without clicking anything first.
  const [selectedCell, setSelectedCell] = useState<SelectedCell | null>(DEFAULT_SELECTED_CELL);
  const [paneMode, setPaneMode] = useState<PaneMode>('view');
  const [lookupFilters, setLookupFilters] = useState<LookupFilters>({});
  const [excludeUnsubscribed, setExcludeUnsubscribed] = useState(false);
  const [excludeNfc, setExcludeNfc] = useState(false);

  const isAdmin = gate.status === 'ready' && isNationalRegistryAdmin(gate.leaderRole?.role);

  const load = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const { data: { session } } = await registrySupabase.auth.getSession();
      if (!session) {
        setError('Session expired — please sign in again.');
        return;
      }
      const res = await fetch('/api/registry/manage-summary', {
        headers: { Authorization: `Bearer ${session.access_token}` },
      });
      const json = await res.json();
      if (!res.ok) {
        setError(json.error ?? 'Failed to load the management summary.');
        return;
      }
      setSummary(json);
    } catch (err) {
      // Worth logging (a fetch/JSON failure, nothing sensitive) precisely
      // because a 200 response can still fail client-side, which a generic
      // message alone wouldn't distinguish from a real network failure.
      console.error('[registry/manage] load failed:', err);
      setError('Failed to load the management summary — check the browser console for detail, or try again.');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (isAdmin) load();
  }, [isAdmin, load]);

  // The single point every grid count and the record pane both derive from
  // (via the useMemos below) — filtering here, once, means the "Exclude
  // unsubscribed"/"Exclude NFC" toggles affect the whole console
  // consistently rather than each consumer having to remember to apply
  // them separately.
  const rows = useMemo(() => {
    if (!summary) return null;
    if (!excludeUnsubscribed && !excludeNfc) return summary.registrants;
    return summary.registrants.filter(
      (r) => (!excludeUnsubscribed || r.unsubscribed !== 'Yes') && (!excludeNfc || r.nfc !== 'Yes'),
    );
  }, [summary, excludeUnsubscribed, excludeNfc]);

  const allCounts = useMemo(() => (rows ? countAllRegistrants(rows) : null), [rows]);
  const primaryCounts = useMemo(() => (rows ? countRegistrantsForPeriod(rows, primaryPeriod) : null), [rows, primaryPeriod]);
  const otherFilterCounts = useMemo(
    () => (rows ? countRegistrantsByCategory(rows, otherFilterCategory) : null),
    [rows, otherFilterCategory],
  );

  // Selection is pinned by cell identity (row + column), not by a snapshot
  // of the period/category at click time — so if the admin leaves a cell
  // selected and then changes that row's own dropdown, the pane's records
  // recompute against the new value automatically, the same way the grid's
  // own count for that cell does.
  const selectedPeriod: FilterPeriod | null = selectedCell?.row === 'primary' ? primaryPeriod : null;

  const selectedRecords = useMemo(() => {
    if (!selectedCell || !rows) return [];
    if (selectedCell.row === 'other') {
      return filterRegistrantsByCategoryForCell(rows, selectedCell.column, otherFilterCategory);
    }
    return filterRegistrantsForCell(rows, selectedCell.column, selectedPeriod);
  }, [rows, selectedCell, selectedPeriod, otherFilterCategory]);

  // Each lookup dropdown's own option list is built from the cell's full
  // record set (not from what other lookups have already narrowed it to) —
  // so picking a value in one field never makes another field's options
  // disappear out from under the admin.
  const lookupOptions = useMemo(() => {
    const options = {} as Record<LookupField, LookupOption[]>;
    for (const field of LOOKUP_FIELDS) {
      options[field] = getLookupOptions(selectedRecords, field);
    }
    return options;
  }, [selectedRecords]);

  const displayedRecords = useMemo(
    () => filterByLookups(selectedRecords, lookupFilters),
    [selectedRecords, lookupFilters],
  );

  function updateLookupFilter(field: LookupField, value: string) {
    setLookupFilters((prev) => {
      if (!value) {
        const { [field]: _removed, ...rest } = prev;
        return rest;
      }
      return { ...prev, [field]: value };
    });
  }

  function resetLookupFilters() {
    setLookupFilters({});
  }

  function selectCell(row: RowKey, rowLabel: string) {
    return (column: ConsoleColumn, columnLabel: string) => {
      setSelectedCell({ row, rowLabel, column, columnLabel });
      setPaneMode('view'); // land back on View for a freshly-selected cell, rather than carrying Edit over from whatever was selected before.
      setLookupFilters({}); // a different cell means a different universe of records — last cell's lookups wouldn't even make sense here.
    };
  }

  function clearSelection() {
    setSelectedCell(null);
    setPaneMode('view');
    setLookupFilters({});
  }

  // Applies one field edit and, on success, patches the in-memory registrant
  // list in place — the grid's counts and the pane's own record list both
  // recompute from that same array (via useMemo above), so an edit that
  // moves someone between columns (e.g. a corrected Unknown -> VIC) shows up
  // immediately without a refetch.
  const saveEdit: SaveEditFn = useCallback(async (recordId, field, rawValue) => {
    const value = rawValue.trim() === '' ? null : rawValue.trim();
    try {
      const { data: { session } } = await registrySupabase.auth.getSession();
      if (!session) return { ok: false, error: 'Session expired — please sign in again.' };

      const res = await fetch('/api/registry/manage-record', {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${session.access_token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: recordId, field, value }),
      });
      const json = await res.json();
      if (!res.ok) {
        return { ok: false, error: json.error ?? 'Failed to save.' };
      }

      const saved = json as ManageRecordEditResponse;
      setSummary((prev) =>
        prev
          ? { ...prev, registrants: prev.registrants.map((r) => (r.id === recordId ? { ...r, [saved.field]: saved.value } : r)) }
          : prev,
      );
      return { ok: true };
    } catch (err) {
      console.error('[registry/manage] edit failed:', err);
      return { ok: false, error: 'Failed to save — check the browser console for detail, or try again.' };
    }
  }, []);

  if (gate.status === 'loading') return null;

  // A state_leader can technically navigate here directly (middleware only
  // enforces the MFA-gate cookies, not role) — this page's own national
  // totals aren't theirs to see, so show a plain refusal rather than the
  // console. The API independently enforces the same rule server-side.
  if (!isAdmin) {
    return (
      <div style={{ maxWidth: 700, margin: '2rem auto', padding: '0 1rem' }}>
        <h1>Registrations Management</h1>
        <p>This screen is only available to national registry admins.</p>
        <Link href="/registry">← Back to Registry</Link>
      </div>
    );
  }

  return (
    <div style={{ width: '95%', maxWidth: 1800, margin: '2rem auto', padding: '0 1rem' }}>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr auto 1fr', alignItems: 'center', gap: '1rem' }}>
        <Link href="/registry" style={{ justifySelf: 'start' }}>← Back to Registry</Link>
        <h1 style={{ margin: 0, fontSize: '2rem', fontWeight: 800, textAlign: 'center' }}>Registrations Management</h1>
        <div style={{ justifySelf: 'end', display: 'flex', gap: '1rem' }}>
          <Link href="/registry/manage/registration-log">View Registration Log →</Link>
          <Link href="/registry/manage/whatsapp-invite-log">View WhatsApp Invite Log →</Link>
          <Link href="/registry/manage/edit-log">View Edit Log →</Link>
        </div>
      </div>

      <div style={{ margin: '1rem 0', padding: '0.75rem 1rem', border: '1px solid #ddd', borderRadius: 6, background: '#fafafa' }}>
        {isLoading && !summary && <span>Loading…</span>}
        {summary?.lastSync ? (
          <>
            <strong>Last cron run:</strong> {formatDateTime(summary.lastSync.startedAt)}
            {' — '}
            <span style={{ color: statusColor(summary.lastSync) }}>{statusLabel(summary.lastSync)}</span>
            {summary.lastSync.recordsUpserted != null && (
              <span>, {summary.lastSync.recordsUpserted.toLocaleString('en-AU')} upserted</span>
            )}
            {!!summary.lastSync.errors && <span>, {summary.lastSync.errors} error(s)</span>}
          </>
        ) : (
          summary && <span>No cron runs recorded yet.</span>
        )}
      </div>

      {error && <p role="alert" style={{ color: 'crimson' }}>{error}</p>}

      {summary && (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '1.25rem', margin: '0 0 0.75rem' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', cursor: 'pointer', fontSize: '0.9rem' }}>
              <input
                type="checkbox"
                checked={excludeUnsubscribed}
                onChange={(e) => setExcludeUnsubscribed(e.target.checked)}
              />
              Exclude unsubscribed registrants
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', cursor: 'pointer', fontSize: '0.9rem' }}>
              <input
                type="checkbox"
                checked={excludeNfc}
                onChange={(e) => setExcludeNfc(e.target.checked)}
              />
              Exclude No Further Contact (NFC) registrants
            </label>
          </div>

          <div style={{ overflowX: 'auto' }}>
            <table aria-label="Registration counts" style={{ width: '100%', borderCollapse: 'collapse', minWidth: 900 }}>
              <thead>
                <tr>
                  <th style={headerCellStyle}></th>
                  <th style={headerCellStyle}></th>
                  <th style={headerCellStyle}>Total</th>
                  {MANAGE_CONSOLE_STATES.map((state) => (
                    <th key={state} style={{ ...headerCellStyle, background: getSlideStateShade(state) }}>{state}</th>
                  ))}
                  <th style={headerCellStyle}>Unknown</th>
                </tr>
              </thead>
              <tbody>
                <ConsoleRow
                  rowKey="all"
                  label="All AFJ Registrations"
                  counts={allCounts}
                  selectedCell={selectedCell}
                  onSelectCell={selectCell('all', 'All AFJ Registrations')}
                />
                <ConsoleRow
                  rowKey="primary"
                  label="Primary Filter"
                  control={<PeriodControl label="Primary Filter" value={primaryPeriod} onChange={setPrimaryPeriod} />}
                  counts={primaryCounts}
                  selectedCell={selectedCell}
                  onSelectCell={selectCell('primary', 'Primary Filter')}
                />
                <ConsoleRow
                  rowKey="other"
                  label="Other Filters"
                  control={<CategoryControl label="Other Filters" value={otherFilterCategory} onChange={setOtherFilterCategory} />}
                  counts={otherFilterCounts}
                  selectedCell={selectedCell}
                  onSelectCell={selectCell('other', 'Other Filters')}
                />
              </tbody>
            </table>
          </div>
          <p style={{ color: '#6b7280', fontSize: '0.85rem', marginTop: '0.75rem' }}>
            Counts are based on {(rows?.length ?? 0).toLocaleString('en-AU')} registrants currently in the registry
            {(excludeUnsubscribed || excludeNfc) && (
              <> ({(summary.registrants.length - (rows?.length ?? 0)).toLocaleString('en-AU')} excluded as unsubscribed/NFC)</>
            )}
            . &quot;Unknown&quot; covers registrants with no state on file, or a state outside VIC/NSW/ACT/QLD/NT/WA/SA/TAS.
            A registrant with no recorded registration date can never match Primary Filter, but is still counted in All AFJ Registrations and Other Filters (which isn&apos;t date-based). Click any non-zero number to list its records below.
          </p>

          {selectedCell ? (
            <RecordsPane
              selectedCell={selectedCell}
              records={displayedRecords}
              totalForCell={selectedRecords.length}
              onClear={clearSelection}
              mode={paneMode}
              onModeChange={setPaneMode}
              onSaveEdit={saveEdit}
              lookupOptions={lookupOptions}
              lookupFilters={lookupFilters}
              onLookupFilterChange={updateLookupFilter}
              onResetLookups={resetLookupFilters}
              listKey={`${selectedCell.row}|${selectedCell.column}|${JSON.stringify(lookupFilters)}`}
            />
          ) : (
            <p style={{ color: '#6b7280', marginTop: '1.5rem' }}>Click a number above to list the matching records here.</p>
          )}
        </>
      )}
    </div>
  );
}

