  it('keeps waiting for the tap well past the old 8-second give-up', async () => {
    vi.useFakeTimers();
    render(<SetupMfaPage />);
    await act(async () => {}); // let the page reach the tap screen first, as it does at once in a browser
    await act(async () => { await vi.advanceTimersByTimeAsync(30000); });
    expect(screen.getByRole('button', { name: /continue setting up/i })).toBeInTheDocument();
    expect(screen.queryByText(/already been used/i)).not.toBeInTheDocument();
  });

  it('uses the token only on tap, and removes it from the address bar', async () => {
    render(<SetupMfaPage />);
    fireEvent.click(await screen.findByRole('button', { name: /continue setting up/i }));

    await waitFor(() => expect(mockVerifyOtp).toHaveBeenCalledWith({ token_hash: 'hash-1', type: 'email' }));
    expect(window.location.search).not.toContain('token_hash');
  });

  it('carries on to the QR code once the tap signs the person in', async () => {
    render(<SetupMfaPage />);
    fireEvent.click(await screen.findByRole('button', { name: /continue setting up/i }));
    await waitFor(() => expect(mockVerifyOtp).toHaveBeenCalled());

    await act(async () => { authChangeCallback!('SIGNED_IN', { access_token: 'tok', user: { id: 'u1' } }); });
    expect(await screen.findByTestId('qrcode')).toBeInTheDocument();
  });

  it('is not taken over by an older session already saved on the device (it used to freeze on "Signing you in…")', async () => {
    mockGetSession.mockResolvedValue({ data: { session: { access_token: 'old-tok', user: { id: 'u0' } } } });
    render(<SetupMfaPage />);
    fireEvent.click(await screen.findByRole('button', { name: /continue setting up/i }));
    await waitFor(() => expect(mockVerifyOtp).toHaveBeenCalled());

    await act(async () => { authChangeCallback!('SIGNED_IN', { access_token: 'tok', user: { id: 'u1' } }); });
    expect(await screen.findByTestId('qrcode')).toBeInTheDocument();
  });

  it('offers a way out instead of freezing on "Signing you in…" if the sign-in never arrives', async () => {
    vi.useFakeTimers();
    mockVerifyOtp.mockReturnValue(new Promise(() => {}));
    render(<SetupMfaPage />);
    await act(async () => {});
    fireEvent.click(screen.getByRole('button', { name: /continue setting up/i }));
    await act(async () => {});
    expect(screen.getByText(/signing you in/i)).toBeInTheDocument();

    await act(async () => { await vi.advanceTimersByTimeAsync(20000); });
    expect(screen.getByText(/taking too long/i)).toBeInTheDocument();
    expect(screen.getByRole('link', { name: /start again/i })).toHaveAttribute('href', '/login');
  });

  it('falls back to the email + code form if the token was already used', async () => {
    mockVerifyOtp.mockResolvedValue({ error: { message: 'Token has expired or is invalid' } });
    render(<SetupMfaPage />);
    fireEvent.click(await screen.findByRole('button', { name: /continue setting up/i }));

    expect(await screen.findByText(/that link has already been used/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/code from the email/i)).toBeInTheDocument();
  });
});

app/setup-mfa/page.tsx:
'use client';

import { useEffect, useRef, useState } from 'react';
import { emailConfirmSupabase } from '@/lib/emailConfirmSupabaseClient';
import { primaryButtonClass, secondaryButtonClass, bodyTextClass, cardClass, headingClass } from '@/components/auth/CodeEntryScreen';
import { EmailAndCodeFallback } from '@/components/auth/EmailAndCodeFallback';
import { MfaEnrollmentFlow, type MfaEnrollmentOutcome } from '@/components/auth/MfaEnrollmentFlow';
import { TapToContinue } from '@/components/auth/TapToContinue';
import { GetHelp } from '@/components/auth/GetHelp';
import { SetupStep } from '@/components/auth/SetupStep';
import { readTokenHashFromUrl, stripTokenHashFromUrl } from '@/lib/magicLinkToken';
import { SigningInStuck, useStuckWatchdog } from '@/components/auth/SigningInStuck';

const GIVE_UP_AFTER_MS = 8000;

type Screen = 'waiting' | 'tap' | 'expired' | 'stuck' | 'cancelled' | 'enrolling' | 'success';

/**
 * MFA enrollment landing page for the leader self-serve flow (see
 * app/api/auth/request-mfa-setup/route.ts and
 * app/api/auth/complete-mfa-setup/route.ts). Reuses
 * lib/emailConfirmSupabaseClient.ts (shared with app/confirm-email/page.tsx)
 * for the same reason that page does: an isolated session to prove identity
 * via magic link. Unlike /confirm-email's old behavior, this session has to
 * stay alive through a multi-step enrollment UI rather than being signed out
 * immediately — the enrollment steps themselves (and the abandonment timer
 * that bounds that window) live in components/auth/MfaEnrollmentFlow.tsx,
 * shared with /confirm-email.
 */
export default function SetupMfaPage() {
  const [screen, setScreen] = useState<Screen>('waiting');
  const [accessToken, setAccessToken] = useState<string | null>(null);
  // Scanner-proof link: the email carries ?token_hash=… and the token is only
  // used when the person taps the button (lib/magicLinkToken.ts).
  const [tokenHash, setTokenHash] = useState<string | null>(null);
  const handledRef = useRef(false);
  // While a link's token waits for the tap, a session already saved on this
  // device must not claim the sign-in (the tapped one would then be ignored —
  // see app/login/mfa/callback/page.tsx, 2026-10-14).
  const awaitingTapRef = useRef(false);

  useStuckWatchdog(screen === 'waiting', () => setScreen('stuck'));

  // Sign-in wait — identical pattern to app/confirm-email/page.tsx.
  useEffect(() => {
    function handleSignedIn(session: { access_token: string }) {
      if (handledRef.current || awaitingTapRef.current) return;
      handledRef.current = true;
      setAccessToken(session.access_token);
      setScreen('enrolling');
    }

    // A token in the URL means "wait for the person to tap"; the give-up
    // clock only starts once they do (handleTap).
    const urlTokenHash = readTokenHashFromUrl();
    awaitingTapRef.current = Boolean(urlTokenHash);

    const { data: { subscription } } = emailConfirmSupabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN' && session) handleSignedIn(session);
    });

    emailConfirmSupabase.auth.getSession().then(({ data: { session } }) => {
      if (session) handleSignedIn(session);
    });

    if (urlTokenHash) {
      Promise.resolve().then(() => {
        setTokenHash(urlTokenHash);
        setScreen('tap');
      });
    }
    const giveUp = urlTokenHash
      ? null
      : setTimeout(() => {
          if (!handledRef.current) setScreen('expired');
        }, GIVE_UP_AFTER_MS);

    return () => {
      subscription.unsubscribe();
      if (giveUp) clearTimeout(giveUp);
    };
  }, []);

  async function handleTap() {
    if (!tokenHash) return;
    const token = tokenHash;
    setTokenHash(null);
    setScreen('waiting');
    stripTokenHashFromUrl();
    awaitingTapRef.current = false;
    const { error } = await emailConfirmSupabase.auth.verifyOtp({ token_hash: token, type: 'email' });
    if (error) {
      setScreen('expired');
      return;
    }
    // SIGNED_IN reaches the listener above; if it somehow never does, don't hang.
    setTimeout(() => {
      if (!handledRef.current) setScreen('expired');
    }, GIVE_UP_AFTER_MS);
  }

  function handleEnrollmentDone(outcome: MfaEnrollmentOutcome) {
    setScreen(outcome);
  }

  // Recovery path when the link itself already failed (e.g. Apple Mail
  // Privacy Protection silently consumed it before the leader ever tapped
  // it — confirmed live, 2026-10-05). Just needs to call verifyOtp() and
  // throw on failure; the onAuthStateChange listener registered in the
  // sign-in-wait effect above is still subscribed (the failed first attempt
  // never ran handleSignedIn, so nothing blocks it firing again) and runs
  // the exact same enrollment flow a working link would have.
  async function handleRecoveryVerify(email: string, code: string) {
    const { error } = await emailConfirmSupabase.auth.verifyOtp({ email, token: code, type: 'email' });
    if (error) throw error;
  }

  if (screen === 'waiting') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>Signing you in…</h2>
        </div>
      </div>
    );
  }

  if (screen === 'stuck') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <SigningInStuck restartHref="/login" />
        </div>
      </div>
    );
  }

  if (screen === 'tap') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <SetupStep n={2} label="Set up your authenticator app" />
          <TapToContinue
            title="One last step"
            description="Tap the button below to finish and carry on setting up your authenticator app."
            buttonLabel="Continue setting up"
            isBusy={false}
            onTap={handleTap}
          />
          <GetHelp />
        </div>
      </div>
    );
  }

  if (screen === 'expired') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>That link has already been used</h2>
          <p className={bodyTextClass}>The link has expired, or it was already used — some email programs open links automatically, which uses them up.</p>
          <EmailAndCodeFallback onVerify={handleRecoveryVerify} />
          <a href="/login" className={`${secondaryButtonClass} block text-center`}>Back to sign in</a>
          <GetHelp />
        </div>
      </div>
    );
  }

  if (screen === 'cancelled') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>Two-factor authentication was not set up</h2>
          <p className={bodyTextClass}>Nothing has been changed. You can try again any time — just sign in and choose &quot;Set up now&quot; when asked.</p>
          <a href="/login" className={`${primaryButtonClass} block text-center`}>Back to sign in</a>
        </div>
      </div>
    );
  }

  if (screen === 'success') {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
        <div className={cardClass}>
          <h2 className={headingClass}>Two-factor authentication is set up</h2>
          <p className={bodyTextClass}>You&apos;re all set — no further action needed today.</p>
          <a href="/app" className={`${primaryButtonClass} block text-center`}>Continue</a>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-8 dark:bg-gray-900">
      <div className={cardClass}>
        {accessToken && <MfaEnrollmentFlow accessToken={accessToken} onDone={handleEnrollmentDone} />}
      </div>
    </div>
  );
}

'use client';

/**
 * Full list of people who registered interest in one training campaign
 * (category BOTJ/TLT) via its public link. Access control relies on
 * getCampaignById's RLS-gated query: it returns null both when the campaign
 * doesn't exist and when the signed-in user isn't its owning/shared leader
 * or an admin (see supabase/rls-policies.sql's campaigns SELECT policy) — so
 * this page can't distinguish "not found" from "not yours", which is the
 * safer failure mode for PII.
 */
import { useEffect, useState, use as usePromise } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import RequireTwoFactorForMemberDetails from '@/components/auth/RequireTwoFactorForMemberDetails';
import { useUser } from '@/contexts/UserContext';
import { getCampaignById } from '@/lib/services/campaignService';
import {
  getTrainingInterestForCampaign,
  setTrainingInterestContacted,
  isTrainingCategory,
  type TrainingInterest,
} from '@/lib/services/trainingInterestService';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { combinePlaceAndSite } from '@/lib/placeSite';
import { getErrorMessage } from '@/lib/errorUtils';
import type { Campaign } from '@/lib/types';

function formatDateTime(dateString: string): string {
  return new Date(dateString).toLocaleString('en-AU', {
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
  });
}

export default function TrainingInterestDetailPage({ params }: { params: Promise<{ campaignId: string }> }) {
  return (
    <RequireTwoFactorForMemberDetails>
      <TrainingInterestDetailContent params={params} />
    </RequireTwoFactorForMemberDetails>
  );
}

function TrainingInterestDetailContent({ params }: { params: Promise<{ campaignId: string }> }) {
  const { campaignId } = usePromise(params);
  const router = useRouter();
  const { user, isLoading: isUserLoading } = useUser();

  // isLoading starts true (rather than a third "not yet loaded" state on
  // `campaign`) so the very first render — before the effect below has run —
  // shows the loading spinner rather than flashing the "not found" screen.
  const [campaign, setCampaign] = useState<Campaign | null>(null);
  const [entries, setEntries] = useState<TrainingInterest[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [updatingIds, setUpdatingIds] = useState<Set<string>>(new Set());
  const [updateError, setUpdateError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }

    let cancelled = false;
    Promise.resolve()
      .then(() => {
        setIsLoading(true);
        setLoadError(null);
        // Fetched in parallel — training_interest's own RLS policy (see
        // supabase/rls-policies.sql) independently re-derives "is this user
        // the owning/shared leader or admin" via its own join through
        // campaigns, so this doesn't need to wait on getCampaignById first
        // to be safe; it just costs one wasted query on an invalid/
        // inaccessible campaignId, which is fine on this authenticated page.
        return Promise.all([getCampaignById(campaignId), getTrainingInterestForCampaign(campaignId)]);
      })
      .then(([c, result]) => {
        if (cancelled) return;
        setCampaign(c);
        setEntries(c && isTrainingCategory(c.category) ? result : []);
      })
      .catch((err: unknown) => {
        if (!cancelled) setLoadError(getErrorMessage(err, 'Failed to load training interest'));
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => { cancelled = true; };
  }, [isUserLoading, user, campaignId, router]);

  const handleToggleContacted = async (id: string, nextContacted: boolean) => {
    setUpdateError(null);
    setUpdatingIds((prev) => new Set(prev).add(id));
    try {
      const { contacted_at } = await setTrainingInterestContacted(id, nextContacted);
      setEntries((prev) => prev.map((e) => (e.id === id ? { ...e, contacted: nextContacted, contacted_at } : e)));
    } catch (err: unknown) {
      setUpdateError(getErrorMessage(err, 'Failed to update contacted status'));
    } finally {
      setUpdatingIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
    }
  };

  const handleCopyLink = async () => {
    const url = `${window.location.origin}/public/training/${campaignId}`;
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setUpdateError('Could not copy the link — your browser may not support clipboard access.');
    }
  };

  if (isUserLoading || isLoading) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner />
        </div>
      </MobileLayout>
    );
  }

  if (loadError || campaign === null || (campaign && !isTrainingCategory(campaign.category))) {
    return (
      <MobileLayout>
        <div className="p-4">
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
            <h2 className="text-lg font-semibold text-red-800 dark:text-red-200">
              {loadError ? 'Error' : 'Not Available'}
            </h2>
            <p className="mt-1 text-sm text-red-600 dark:text-red-300">
              {loadError
                || (campaign && !isTrainingCategory(campaign.category)
                  ? 'This campaign is not a BOTJ or TLT training session.'
                  : "This training campaign couldn't be found, or you don't have permission to view it.")}
            </p>
            <button
              onClick={() => router.push('/training-interest')}
              className="mt-4 rounded-md bg-red-600 px-4 py-2 text-base font-bold text-white hover:bg-red-700 border-2 border-gray-800 dark:border-gray-600"
            >
              Go Back
            </button>
          </div>
        </div>
      </MobileLayout>
    );
  }

  if (!campaign) return null; // unreachable, satisfies TS narrowing

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="relative mb-3">
          <button
            onClick={() => router.push('/training-interest')}
            className="absolute right-0 top-0 rounded bg-gray-200 px-1.5 py-0.5 text-xs font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border border-gray-800 dark:border-gray-600"
          >
            Back
          </button>
          <h1 className="pr-14 text-2xl font-bold text-gray-900 dark:text-gray-100">
            {combinePlaceAndSite(campaign.place, campaign.site)} — {campaign.state}
          </h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            {campaign.category} training, {new Date(campaign.date).toLocaleDateString('en-AU', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' })}
            {' at '}{formatCampaignTimeDisplay(campaign.time)} — Leader: {campaign.leader}
          </p>
          <button
            type="button"
            onClick={handleCopyLink}
            className="mt-2 rounded-md bg-gray-200 px-3 py-2 text-xs font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
          >
            {copied ? 'Copied!' : 'Copy Public Link'}
          </button>
        </div>

        {updateError && (
          <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {updateError}
          </div>
        )}

        <div className="rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white shadow-sm dark:bg-gray-800">
          <div className="p-4">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              Interested ({entries.length})
            </h2>
          </div>
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {/* No isLoading branch needed here — the page-level gate above
                already blocks rendering until campaign+entries have both
                resolved together (fetched in parallel). */}
            {entries.length === 0 ? (
              <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
                No one has registered interest yet.
              </div>
            ) : (
              entries.map((entry) => {
                const isUpdating = updatingIds.has(entry.id);
                return (
                  <div key={entry.id} className="p-4">
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0">
                        <div className="text-base font-bold text-gray-900 dark:text-gray-100">{entry.name}</div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">
                          {[entry.mobile, entry.email].filter(Boolean).join(' · ')}
                        </div>
                        <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                          Registered {formatDateTime(entry.created_at)}
                        </div>
                      </div>

                      <div className="shrink-0 text-right">
                        <label className="flex items-center justify-end gap-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                          <span>Contacted</span>
                          <input
                            type="checkbox"
                            checked={entry.contacted}
                            disabled={isUpdating}
                            onChange={(e) => handleToggleContacted(entry.id, e.target.checked)}
                            className="h-5 w-5 accent-blue-600 disabled:opacity-50"
                          />
                        </label>
                        {entry.contacted && entry.contacted_at && (
                          <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                            {formatDateTime(entry.contacted_at)}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </MobileLayout>
  );
}

app/training-interest/page.tsx:
'use client';

/**
 * Leader-facing dashboard of training campaigns (category BOTJ/TLT) the
 * signed-in user leads (own, shared, or — for admins — every training
 * campaign), each with its public-link interest count. Click through to
 * /training-interest/[campaignId] for the full list of who's interested.
 *
 * Visibility is enforced the same way as the main campaign feed: RLS on the
 * campaigns table (see supabase/rls-policies.sql) restricts what
 * getTrainingCampaigns can ever return, so a non-admin leader simply never
 * sees another leader's training campaigns here.
 */
import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import MobileLayout from '@/components/MobileLayout';
import LoadingSpinner from '@/components/LoadingSpinner';
import { useUser } from '@/contexts/UserContext';
import { getTrainingCampaigns, getTrainingInterestCounts } from '@/lib/services/trainingInterestService';
import { getSlideStateColor } from '@/lib/slideLayout';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { combinePlaceAndSite } from '@/lib/placeSite';
import { getErrorMessage } from '@/lib/errorUtils';
import type { Campaign } from '@/lib/types';

export default function TrainingInterestPage() {
  const router = useRouter();
  const { user, adminStatus, userState, userLeader, userMobile, isLoading: isUserLoading } = useUser();

  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [counts, setCounts] = useState<Map<string, number>>(new Map());
  const [isLoading, setIsLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  useEffect(() => {
    if (isUserLoading) return;
    if (!user) { router.push('/login'); return; }

    let cancelled = false;
    Promise.resolve()
      .then(() => {
        setIsLoading(true);
        setLoadError(null);
        return getTrainingCampaigns({ adminStatus, userState, userLeader, userMobile, userId: user.id });
      })
      .then(async (result) => {
        if (cancelled) return;
        setCampaigns(result);
        const countsResult = await getTrainingInterestCounts(result.map((c) => c.id));
        if (!cancelled) setCounts(countsResult);
      })
      .catch((err: unknown) => {
        if (!cancelled) setLoadError(getErrorMessage(err, 'Failed to load training campaigns'));
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => { cancelled = true; };
  }, [isUserLoading, user, adminStatus, userState, userLeader, userMobile, router]);

  // Sum of counts.values() — total registrations across all listed training
  // campaigns, shown after the title for consistency with the Campaign
  // Interest screens (e.g. "Campaign Interest (2)").
  const totalInterest = Array.from(counts.values()).reduce((sum, n) => sum + n, 0);

  const handleCopyLink = async (campaignId: string) => {
    const url = `${window.location.origin}/public/training/${campaignId}`;
    try {
      await navigator.clipboard.writeText(url);
      setCopiedId(campaignId);
      setTimeout(() => setCopiedId((prev) => (prev === campaignId ? null : prev)), 2000);
    } catch {
      setLoadError('Could not copy the link — your browser may not support clipboard access.');
    }
  };

  if (isUserLoading || (isLoading && campaigns.length === 0)) {
    return (
      <MobileLayout>
        <div className="flex min-h-screen items-center justify-center">
          <LoadingSpinner text="Loading training campaigns…" />
        </div>
      </MobileLayout>
    );
  }

  return (
    <MobileLayout>
      <div className="p-4">
        <div className="relative mb-3">
          <button
            onClick={() => router.push('/app')}
            className="absolute right-0 top-0 rounded bg-gray-200 px-1.5 py-0.5 text-xs font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border border-gray-800 dark:border-gray-600"
          >
            Back
          </button>
          <h1 className="pr-14 text-2xl font-bold text-gray-900 dark:text-gray-100">Training Interest ({totalInterest})</h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Your BOTJ and TLT training campaigns, each with a public link people can use to register interest in joining.
          </p>
        </div>

        {loadError && (
          <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {loadError}
          </div>
        )}

        <div className="rounded-lg border-2 border-gray-800 dark:border-gray-600 bg-white shadow-sm dark:bg-gray-800">
          <div className="divide-y divide-gray-200 dark:divide-gray-700">
            {campaigns.length === 0 ? (
              <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
                No BOTJ or TLT training campaigns found.
              </div>
            ) : (
              campaigns.map((campaign) => (
                <div key={campaign.id} className="p-4">
                  <div className="flex items-start justify-between gap-3">
                    <button
                      type="button"
                      onClick={() => router.push(`/training-interest/${campaign.id}`)}
                      className="min-w-0 flex-1 text-left"
                    >
                      <div className="font-bold" style={{ color: getSlideStateColor(campaign.state) }}>
                        {combinePlaceAndSite(campaign.place, campaign.site)} — {campaign.state}
                        <span className="ml-2 rounded-md bg-blue-600 px-1.5 py-0.5 text-xs font-bold text-white">
                          {campaign.category}
                        </span>
                      </div>
                      <div className="text-sm text-gray-600 dark:text-gray-400">
                        {new Date(campaign.date).toLocaleDateString('en-AU', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' })}
                        {' at '}{formatCampaignTimeDisplay(campaign.time)} — Leader: {campaign.leader}
                      </div>
                      <div className="mt-1 text-sm font-semibold text-blue-700 dark:text-blue-300">
                        {counts.get(campaign.id) ?? 0} interested — View details →
                      </div>
                    </button>
                    <button
                      type="button"
                      onClick={() => handleCopyLink(campaign.id)}
                      className="shrink-0 rounded-md bg-gray-200 px-3 py-2 text-xs font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
                    >
                      {copiedId === campaign.id ? 'Copied!' : 'Copy Link'}
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </MobileLayout>
  );
}

app/view-slides/page.tsx:
'use client';

import { useEffect, useState } from 'react';
import { getErrorMessage } from '@/lib/errorUtils';

export default function PublicSlideViewerPage() {
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [slides, setSlides] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [imageError, setImageError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    async function loadSlides() {
      try {
        // Load slides from public/slides folder
        // We'll try to load slides sequentially starting from slide_1.jpg
        const slidesList: string[] = [];
        let slideNum = 1;
        let foundSlides = true;

        // Fetch up to 100 slides (reasonable max)
        while (foundSlides && slideNum <= 100) {
          try {
            const slidePath = `/slides/slide_${slideNum}.jpg`;
            const response = await fetch(slidePath, { method: 'HEAD' });
            if (response.ok) {
              slidesList.push(slidePath);
              slideNum++;
            } else {
              foundSlides = false;
            }
          } catch {
            foundSlides = false;
          }
        }

        if (slidesList.length === 0) {
          setError('No slides found');
        } else {
          setSlides(slidesList);
        }
      } catch (err: unknown) {
        setError(getErrorMessage(err, 'Failed to load slides'));
      } finally {
        setIsLoading(false);
      }
    }
    loadSlides();
  }, []);

  const handleNext = () => {
    if (currentSlideIndex < slides.length - 1) {
      setCurrentSlideIndex(currentSlideIndex + 1);
      setImageError(false);
    } else {
      // Loop back to first slide
      setCurrentSlideIndex(0);
      setImageError(false);
    }
  };

  const handleDownload = async () => {
    try {
      const currentSlide = slides[currentSlideIndex];
      const response = await fetch(currentSlide);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = currentSlide.split('/').pop() || 'slide.jpg';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      console.error('Error downloading slide:', err);
      alert('Failed to download slide');
    }
  };

  if (isLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-black">
        <div className="text-white">Loading slides...</div>
      </div>
    );
  }

  if (error || slides.length === 0) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-black p-4">
        <div className="rounded-lg border border-gray-700 bg-gray-800 p-8 text-center">
          <p className="text-gray-300">
            {error || 'No slides available.'}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 py-3 px-4">
        <h1 className="text-lg font-semibold text-white text-center">
          Campaign Slides
        </h1>
      </header>

      {/* Slide display area */}
      <div className="flex-1 flex items-center justify-center overflow-hidden pt-4">
        {imageError ? (
          <div className="text-white text-center p-4">
            <p className="mb-2">Failed to load slide</p>
            <p className="text-sm text-gray-400">
              {slides[currentSlideIndex]}
            </p>
          </div>
        ) : (
          <img
            src={slides[currentSlideIndex]}
            alt={`Slide ${currentSlideIndex + 1}`}
            className="w-full h-full object-contain"
            onError={() => setImageError(true)}
          />
        )}
      </div>

      {/* Button controls */}
      <div className="flex gap-4 p-4 bg-gray-900">
        <button
          onClick={handleNext}
          className="flex-1 rounded-md bg-blue-600 px-6 py-3 text-base font-semibold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        >
          Next
        </button>
        <button
          onClick={handleDownload}
          className="flex-1 rounded-md bg-green-600 px-6 py-3 text-base font-semibold text-white hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2"
        >
          Download
        </button>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import LoadingSpinner from '@/components/LoadingSpinner';
import PublicCampaignList from '@/components/PublicCampaignList';
import { getErrorMessage } from '@/lib/errorUtils';
import { generateAndDownloadSlidesFromData, type PublicSlideDay } from '@/lib/slideGenerator';
import type { TemporaryUpcomingCampaignsResponse } from '@/app/api/public/temporary-upcoming-campaigns/route';

/**
 * Full-screen "Upcoming Campaigns for All Leaders" — the same fortnight list
 * as the public /public/temporary-upcoming-campaigns page (same API, same
 * PublicCampaignList), but with only a Download button and a link back to the
 * screen it was opened from. Shown in place (fixed overlay) so going back
 * returns the leader to exactly where they were on /app.
 */
export default function AllLeadersCampaignListScreen({ onClose }: { onClose: () => void }) {
  const [days, setDays] = useState<PublicSlideDay[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState('');
  const [downloadError, setDownloadError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch('/api/public/temporary-upcoming-campaigns');
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load campaign data');
        if (!cancelled) setDays((json as TemporaryUpcomingCampaignsResponse).days);
      } catch (err) {
        if (!cancelled) setLoadError(getErrorMessage(err, 'Failed to load campaign data'));
      }
    })();
    return () => { cancelled = true; };
  }, []);

  const campaigns = (days ?? []).flatMap((d) => d.campaigns);

  const handleDownload = async () => {
    if (!days) return;
    setIsDownloading(true);
    setDownloadError(null);
    setDownloadProgress('');
    try {
      await generateAndDownloadSlidesFromData(days, setDownloadProgress);
    } catch (err) {
      setDownloadError(getErrorMessage(err, 'Failed to generate the campaign list download'));
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div
      data-ti="components/AllLeadersCampaignListScreen.tsx"
      className="fixed inset-0 z-50 flex flex-col bg-white p-4 dark:bg-gray-900"
    >
      <h1 className="mb-3 text-2xl font-bold text-gray-900 dark:text-gray-100">
        Upcoming Campaigns for All Leaders
      </h1>

      {loadError && (
        <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
          {loadError}
        </div>
      )}
      {downloadError && (
        <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
          {downloadError}
        </div>
      )}

      <div className="relative flex-1 overflow-hidden rounded-lg border-2 border-gray-800 dark:border-gray-600">
        {days === null && !loadError && (
          <div className="absolute inset-0 z-20 flex items-center justify-center bg-white/80 dark:bg-gray-900/80">
            <LoadingSpinner text="Loading campaigns…" />
          </div>
        )}
        <div className="h-full overflow-y-auto">
          <PublicCampaignList campaigns={campaigns} />
        </div>
      </div>

      <div className="mt-3 flex shrink-0 flex-col gap-2">
        {isDownloading && downloadProgress && (
          <p className="text-center text-xs text-gray-600 dark:text-gray-400">{downloadProgress}</p>
        )}
        <button
          type="button"
          onClick={handleDownload}
          disabled={!days || isDownloading}
          className="w-full rounded-md border-2 border-gray-800 bg-blue-600 px-4 py-3 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 dark:border-gray-600"
        >
          {isDownloading ? 'Preparing…' : 'Download a Copy'}
        </button>
        <button
          type="button"
          onClick={onClose}
          className="py-1 text-center text-base font-bold text-blue-600 underline hover:text-blue-800 focus:outline-none dark:text-blue-400 dark:hover:text-blue-300"
        >
          ← Return to the previous page
        </button>
      </div>
    </div>
  );
}

components/BackToAppBar.tsx:
'use client';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';

/**
 * Query parameter marking a /public/* page as opened from inside the app
 * (e.g. the Admin Quick Actions buttons), rather than from a shared link.
 */
export const FROM_APP_PARAM = 'from';
const FROM_APP_VALUE = 'app';

/** `path` with the marker that makes `BackToAppBar` show a way back to `/app`. */
export function withBackToApp(path: string): string {
  return `${path}?${FROM_APP_PARAM}=${FROM_APP_VALUE}`;
}

/**
 * Public pages have no app header or bottom bar, so one opened from inside
 * the app left no way back (an installed app has no browser Back button).
 * Shown only when the page was opened via `withBackToApp()` — members who
 * open the same page from a shared link never see it.
 */
export default function BackToAppBar() {
  const searchParams = useSearchParams();
  if (searchParams.get(FROM_APP_PARAM) !== FROM_APP_VALUE) return null;

  return (
    <div data-ti="components/BackToAppBar.tsx" className="sticky top-0 z-10 border-b border-gray-300 bg-gray-100 px-4 py-2 dark:border-gray-800 dark:bg-gray-950">
      <Link
        href="/app"
        className="inline-block rounded-md border-2 border-gray-800 bg-purple-600 px-4 py-2 text-sm font-bold text-white hover:bg-purple-700 dark:border-gray-600"
      >
        ← Back to app
      </Link>
    </div>
  );
}

components/CampaignForm.tsx:
'use client';

import { useState, FormEvent, useEffect } from 'react';
import { getTodayDateString } from '@/lib/campaignDates';
import { getErrorMessage } from '@/lib/errorUtils';
import { getPlacesForState, getLeadersForState, getCampaignCategories, type PlaceOption } from '@/lib/services/dropdownService';
import { combinePlaceAndSite } from '@/lib/placeSite';

export interface CampaignData {
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
  mobile: string;
  category: string;
}

interface CampaignFormProps {
  onSubmit: (data: CampaignData) => Promise<void> | void;
  initialData?: Partial<CampaignData>;
  submitLabel?: string;
  /** When not admin/state reporter: default leader to signed-in user's leader when state matches */
  signedInLeader?: string;
  signedInMobile?: string;
  signedInState?: string;
  /** When true, do not apply leader/mobile defaults (admins and state reporters can select any leader) */
  isAdminOrStateReporter?: boolean;
}

export default function CampaignForm({
  onSubmit,
  initialData,
  submitLabel = 'Create Campaign',
  signedInLeader,
  signedInMobile: _signedInMobile,
  signedInState,
  isAdminOrStateReporter = false,
}: CampaignFormProps) {
  const todayDateString = getTodayDateString();

  const [formData, setFormData] = useState<CampaignData>({
    date: initialData?.date || todayDateString,
    state: initialData?.state || '',
    place: initialData?.place || '',
    site: initialData?.site || '',
    time: initialData?.time || '',
    leader: initialData?.leader || '',
    mobile: initialData?.mobile || '',
    category: initialData?.category ?? 'TWOL',
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [places, setPlaces] = useState<PlaceOption[]>([]);
  const [loadingPlaces, setLoadingPlaces] = useState(false);
  const [timeOptions, setTimeOptions] = useState<{ value: string; label: string }[]>([]);
  const [leaders, setLeaders] = useState<string[]>([]);
  const [loadingLeaders, setLoadingLeaders] = useState(false);
  const [categories, setCategories] = useState<{ code: string; name: string }[]>([
    { code: 'TWOL', name: 'Two Weekly' },
    { code: 'BOTJ', name: 'Book of the Judgement' },
    { code: 'TLT', name: 'TLT' },
  ]);

  // Generate time options (half-hour intervals from 8:00 AM to 9:00 PM)
  useEffect(() => {
    function generateTimeOptions() {
      const times: { value: string; label: string }[] = [];

      // Start at 8:00 AM (8 * 60 = 480 minutes)
      // End at 9:00 PM (21 * 60 = 1260 minutes)
      // Interval: 30 minutes
      for (let minutes = 480; minutes <= 1260; minutes += 30) {
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;

        // Format as HH:MM for value (24-hour format for database)
        const value = `${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}`;

        // Format for display (12-hour format with AM/PM)
        const displayHours = hours === 0 ? 12 : hours > 12 ? hours - 12 : hours;
        const ampm = hours >= 12 ? 'PM' : 'AM';
        const label = `${displayHours}:${String(mins).padStart(2, '0')} ${ampm}`;

        times.push({ value, label });
      }

      setTimeOptions(times);
    }

    generateTimeOptions();
  }, []);

  // Load campaign categories from DB (fallback to hardcoded defaults if table not ready)
  useEffect(() => {
    getCampaignCategories().then((cats) => {
      if (cats.length > 0) setCategories(cats);
    });
  }, []);

  // Fetch places when state changes
  useEffect(() => {
    if (!formData.state) {
      setPlaces([]);
      return;
    }
    setLoadingPlaces(true);
    getPlacesForState(formData.state)
      .then((uniquePlaces) => {
        setPlaces(uniquePlaces);
        const currentLabel = combinePlaceAndSite(formData.place, formData.site);
        if (formData.place && !uniquePlaces.some((p) => p.label === currentLabel)) {
          setFormData((prev) => ({ ...prev, place: '', site: '' }));
        }
      })
      .finally(() => setLoadingPlaces(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formData.state]);

  // Fetch leaders when state changes
  useEffect(() => {
    if (!formData.state) {
      setLeaders([]);
      return;
    }
    setLoadingLeaders(true);
    getLeadersForState(formData.state)
      .then((uniqueLeaders) => {
        setLeaders(uniqueLeaders);
        if (formData.leader && !uniqueLeaders.includes(formData.leader)) {
          setFormData((prev) => ({ ...prev, leader: '' }));
        } else if (
          !formData.leader &&
          !isAdminOrStateReporter &&
          signedInLeader &&
          signedInState &&
          formData.state.toUpperCase().trim() === signedInState.toUpperCase().trim() &&
          uniqueLeaders.includes(signedInLeader)
        ) {
          setFormData((prev) => ({ ...prev, leader: signedInLeader }));
        }
      })
      .finally(() => setLoadingLeaders(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formData.state, formData.leader, isAdminOrStateReporter, signedInLeader, signedInState]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
      // Clear place/site when state changes
      ...(name === 'state' ? { place: '', site: '' } : {}),
    }));
    setError(null);
  };

  /** Resolves the selected PlaceOption.label back into place+site via the loaded options. */
  const handlePlaceChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const label = e.target.value;
    const match = places.find((p) => p.label === label);
    setFormData((prev) => ({ ...prev, place: match?.place ?? label, site: '' }));
    setError(null);
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSubmitting(true);

    try {
      await onSubmit(formData);
    } catch (err: unknown) {
      setError(getErrorMessage(err, 'An error occurred'));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form data-ti="components/CampaignForm.tsx" onSubmit={handleSubmit} className="space-y-4 p-4">
      {error && (
        <div className="rounded-md bg-red-50 p-3 text-sm text-red-800 dark:bg-red-900/20 dark:text-red-200">
          {error}
        </div>
      )}

      <div>
        <label
          htmlFor="date"
          className="block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Date *
        </label>
        <input
          type="date"
          id="date"
          name="date"
          required
          value={formData.date}
          onChange={handleChange}
          className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
        />
      </div>

      <div>
        <label
          htmlFor="state"
          className="block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          State *
        </label>
        <select
          id="state"
          name="state"
          required
          value={formData.state}
          onChange={handleChange}
          className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
        >
          <option value="">Select a state</option>
          <option value="VIC">Victoria (VIC)</option>
          <option value="NSW">New South Wales (NSW)</option>
          <option value="QLD">Queensland (QLD)</option>
          <option value="SA">South Australia (SA)</option>
          <option value="WA">Western Australia (WA)</option>
          <option value="TAS">Tasmania (TAS)</option>
          <option value="NT">Northern Territory (NT)</option>
          <option value="ACT">Australian Capital Territory (ACT)</option>
        </select>
      </div>

      <div>
        <label
          htmlFor="place"
          className="block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Place *
        </label>
        <select
          id="place"
          name="place"
          required
          value={combinePlaceAndSite(formData.place, formData.site)}
          onChange={handlePlaceChange}
          disabled={!formData.state || loadingPlaces}
          className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 disabled:bg-gray-100 disabled:cursor-not-allowed dark:border-gray-600 dark:bg-gray-800 dark:text-white dark:disabled:bg-gray-700"
        >
          <option value="">
            {!formData.state
              ? 'Select a state first'
              : loadingPlaces
              ? 'Loading places...'
              : places.length === 0
              ? 'No places found for this state'
              : 'Select a place'}
          </option>
          {places.map((place) => (
            <option key={place.label} value={place.label}>
              {place.label}
            </option>
          ))}
        </select>
        {formData.state && places.length === 0 && !loadingPlaces && (
          <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
            No potential campaigns found for {formData.state}. You can still create a campaign manually.
          </p>
        )}
      </div>

      <div>
        <label
          htmlFor="time"
          className="block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Time *
        </label>
        <select
          id="time"
          name="time"
          required
          value={formData.time}
          onChange={handleChange}
          className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
        >
          <option value="">Select a time</option>
          {timeOptions.map((time) => (
            <option key={time.value} value={time.value}>
              {time.label}
            </option>
          ))}
        </select>
      </div>

      <div>
        <label
          htmlFor="leader"
          className="block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Leader *
        </label>
        <select
          id="leader"
          name="leader"
          required
          value={formData.leader}
          onChange={handleChange}
          disabled={!formData.state || loadingLeaders}
          className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 disabled:bg-gray-100 disabled:cursor-not-allowed dark:border-gray-600 dark:bg-gray-800 dark:text-white dark:disabled:bg-gray-700"
        >
          <option value="">
            {!formData.state
              ? 'Select a state first'
              : loadingLeaders
              ? 'Loading leaders...'
              : leaders.length === 0
              ? 'No leaders found'
              : 'Select a leader'}
          </option>
          {leaders.map((leader) => (
            <option key={leader} value={leader}>
              {leader}
            </option>
          ))}
        </select>
        {formData.state && leaders.length === 0 && !loadingLeaders && (
          <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
            No leaders found for {formData.place ? `${combinePlaceAndSite(formData.place, formData.site)}, ` : ''}
            {formData.state}.
          </p>
        )}
      </div>

      <div>
        <label
          htmlFor="category"
          className="block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Category
        </label>
        <select
          id="category"
          name="category"
          required
          value={formData.category}
          onChange={(e) => {
            setFormData((prev) => ({ ...prev, category: e.target.value }));
            setError(null);
          }}
          className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
        >
          {categories.map((cat) => (
            <option key={cat.code} value={cat.code}>
              {cat.name}
            </option>
          ))}
        </select>
      </div>

      <button
        type="submit"
        disabled={isSubmitting}
        className="w-full rounded-md bg-blue-600 px-4 py-2 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
      >
        {isSubmitting ? 'Submitting...' : submitLabel}
      </button>
    </form>
  );
}

components/CampaignInterestEntryList.tsx:
'use client';

import type { CampaignInterestWithCampaign } from '@/lib/services/campaignInterestService';
import { getSlideStateColor } from '@/lib/slideLayout';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { combinePlaceAndSite } from '@/lib/placeSite';

function formatDateTime(dateString: string): string {
  return new Date(dateString).toLocaleString('en-AU', {
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
  });
}

interface Props {
  entries: CampaignInterestWithCampaign[];
  updatingIds: Set<string>;
  onToggleContacted: (id: string, contacted: boolean) => void;
}

/**
 * Row rendering shared by /admin/registered-interest (every registration,
 * admin-only) and /campaign-interest (a leader's own campaigns only) — same
 * data shape, same Contacted-checkbox interaction, differing only in which
 * rows the caller fetched. Renders just the row list (not the surrounding
 * card/header), so callers control the "Registrations (N)" title and empty
 * vs loaded framing around it.
 */
export default function CampaignInterestEntryList({ entries, updatingIds, onToggleContacted }: Props) {
  if (entries.length === 0) {
    return (
      <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
        No one has registered interest yet.
      </div>
    );
  }

  return (
    <>
      {entries.map((entry) => {
        const campaign = entry.campaign;
        const isUpdating = updatingIds.has(entry.id);
        return (
          <div key={entry.id} data-ti="components/CampaignInterestEntryList.tsx" className="p-4">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                {campaign ? (
                  <div className="font-bold" style={{ color: getSlideStateColor(campaign.state) }}>
                    {combinePlaceAndSite(campaign.place, campaign.site)} — {campaign.state}
                  </div>
                ) : (
                  <div className="font-bold text-gray-400 italic">Campaign no longer exists</div>
                )}
                {campaign && (
                  <div className="text-sm text-gray-600 dark:text-gray-400">
                    {new Date(campaign.date).toLocaleDateString('en-AU', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' })}
                    {' at '}{formatCampaignTimeDisplay(campaign.time)} — Leader: {campaign.leader}
                  </div>
                )}
                <div className="mt-2 text-base text-gray-900 dark:text-gray-100">
                  {entry.first_name} — {[entry.mobile, entry.email].filter(Boolean).join(' · ')}
                </div>
                <div className="mt-1 flex flex-wrap items-center gap-2 text-xs">
                  <span
                    className={`rounded-md px-2 py-0.5 font-bold text-white ${
                      entry.interest_type === 'in' ? 'bg-green-600' : 'bg-orange-500'
                    }`}
                  >
                    {entry.interest_type === 'in' ? "Yes I'm In" : 'Tell Me More'}
                  </span>
                  <span className="text-gray-500 dark:text-gray-400">
                    Registered {formatDateTime(entry.created_at)}
                  </span>
                </div>
              </div>

              <div className="shrink-0 text-right">
                <label className="flex items-center justify-end gap-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                  <span>Contacted</span>
                  <input
                    type="checkbox"
                    checked={entry.contacted}
                    disabled={isUpdating}
                    onChange={(e) => onToggleContacted(entry.id, e.target.checked)}
                    className="h-5 w-5 accent-blue-600 disabled:opacity-50"
                  />
                </label>
                {entry.contacted && entry.contacted_at && (
                  <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                    {formatDateTime(entry.contacted_at)}
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
    </>
  );
}

components/CampaignMap.tsx:
'use client';

import 'leaflet/dist/leaflet.css';
import { useEffect, useState, type ReactNode } from 'react';
import L from 'leaflet';
import { MapContainer, TileLayer, Marker, Popup, useMap, useMapEvents } from 'react-leaflet';
import { getStateMarkerIcon, type StateMarkerIconOptions } from '@/lib/leafletMarkerIcon';
import { formatCampaignDateTimeDisplay, sortCampaignsChronologically } from '@/lib/campaignUtils';
import MapPopupActions from '@/components/MapPopupActions';
import TechInsightsMapTag from '@/components/techInsights/TechInsightsMapTag';

/**
 * Just enough of a campaign for this map's popup (id/date/time/leader) —
 * kept minimal and local rather than requiring the admin-only `Campaign`
 * type campaignMapService.ts's `MapMarker` carries, so the public
 * "Upcoming Campaigns" map (app/public/upcoming-campaigns) — whose
 * campaign rows carry far fewer fields — can use this same component
 * without an awkward cast. A full admin `Campaign` object already
 * structurally satisfies this. Mirrors NearbyCampaignsMap.tsx's identical
 * `NearbyMapPopupCampaign` pattern.
 */
export interface CampaignMapPopupCampaign {
  id: string;
  date: string;
  time: string;
  leader: string;
}

export interface CampaignMapPopupMarker {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
  campaigns?: CampaignMapPopupCampaign[];
}

interface FlyToProps {
  center: [number, number];
  zoom: number;
}

/**
 * Animates the map to a new center/zoom whenever the target changes (e.g.
 * state selection, a "Near Me" lookup). Leaflet doesn't measure a freshly
 * created map's container synchronously — `getSize()` reads 0x0 until the
 * browser has laid it out and Leaflet has picked that up (normally via its
 * own resize observer) — and `flyTo`'s animation does pixel-based math on
 * that size, so calling it too soon (right on mount, before that first
 * measurement) throws "Invalid LatLng (NaN, NaN)" instead of moving the
 * map. `setView` doesn't animate but doesn't need a measured size either,
 * so it's used as a safe fallback whenever the size isn't known yet —
 * `MapContainer`'s own `center`/`zoom` props already position the map
 * correctly on first mount, so this never visibly "jumps".
 */
function FlyTo({ center, zoom }: FlyToProps) {
  const map = useMap();
  useEffect(() => {
    const size = map.getSize();
    if (size.x === 0 || size.y === 0) {
      map.setView(center, zoom);
    } else {
      map.flyTo(center, zoom, { duration: 1 });
    }
  }, [map, center, zoom]);
  return null;
}

/**
 * Frames the map around all markers (capped at a city-level zoom so a single
 * marker doesn't zoom in absurdly far) whenever the marker set changes —
 * so the map opens on the campaigns instead of all of Australia. Declared
 * after FlyTo so it wins on first mount; callers turn it off while a
 * postcode/location target is being shown.
 */
function FitToMarkers({ markers }: { markers: CampaignMapPopupMarker[] }) {
  const map = useMap();
  useEffect(() => {
    if (markers.length === 0) return;
    const size = map.getSize();
    if (size.x === 0 || size.y === 0) return;
    map.fitBounds(L.latLngBounds(markers.map((m): [number, number] => [m.latitude, m.longitude])), { padding: [40, 40], maxZoom: 10 });
  }, [map, markers]);
  return null;
}

/**
 * Leaflet only notices window resizes, not its container changing size
 * (e.g. toggling full screen) — tell it to re-measure when `resizeKey` changes.
 */
function InvalidateSizeOnChange({ resizeKey }: { resizeKey: unknown }) {
  const map = useMap();
  useEffect(() => {
    // Wait a frame so the container has its new layout size.
    const id = requestAnimationFrame(() => map.invalidateSize());
    return () => cancelAnimationFrame(id);
  }, [map, resizeKey]);
  return null;
}

/** Surfaces tile load failures directly instead of leaving the admin staring at a blank grey map. */
function TileErrorBanner() {
  const [hasError, setHasError] = useState(false);
  useMapEvents({
    tileerror: () => setHasError(true),
    tileload: () => setHasError(false),
  });

  if (!hasError) return null;
  return (
    <div className="absolute top-2 left-1/2 z-[1000] -translate-x-1/2 rounded-md border border-red-300 bg-red-50 px-3 py-1.5 text-xs font-medium text-red-800 shadow">
      Map tiles failed to load — check your network connection.
    </div>
  );
}

interface CampaignMapProps {
  center: [number, number];
  zoom: number;
  markers: CampaignMapPopupMarker[];
  /**
   * What to render under the Leader line in a campaign marker's popup —
   * defaults to the admin `MapPopupActions` stub. The public "Upcoming
   * Campaigns" screen (app/public/upcoming-campaigns) passes its own
   * renderer here instead, wired to actually record interest rather than
   * console.log placeholders — same `renderActions` pattern
   * NearbyCampaignsMap.tsx already established.
   */
  /** Marker size/opacity — defaults to the small, faint style; the public map passes a larger one so markers read as tappable. */
  markerStyle?: StateMarkerIconOptions;
  /** Frame the map around the markers whenever they change (instead of staying on `center`/`zoom`). */
  fitToMarkers?: boolean;
  /** Changing this value makes the map re-measure its container (e.g. when the caller toggles full screen). */
  resizeKey?: unknown;
  /** Called when a marker is clicked/tapped (e.g. to hide a first-visit hint). */
  onMarkerOpen?: () => void;
  renderActions?: (props: { campaignId: string; place: string; state: string }) => ReactNode;
  /**
   * Place-level alternative to `renderActions`: when given, it is rendered
   * once under a marker's campaign list (instead of per-campaign actions),
   * receiving every campaign id at that place. The public Upcoming Campaigns
   * screen uses this for its single "Contact Me about This or Other
   * Campaigns at this Location" button.
   */
  renderPlaceActions?: (props: { campaignIds: string[]; place: string; state: string }) => ReactNode;
}

export default function CampaignMap({ center, zoom, markers, markerStyle, fitToMarkers = false, resizeKey, onMarkerOpen, renderPlaceActions, renderActions = (props) => <MapPopupActions {...props} /> }: CampaignMapProps) {
  return (
    <MapContainer
      center={center}
      zoom={zoom}
      scrollWheelZoom
      style={{ height: '100%', width: '100%' }}
    >
      <TileLayer
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        url="/api/tiles/{z}/{x}/{y}"
      />
      <TechInsightsMapTag data-ti="components/CampaignMap.tsx" />
      <TileErrorBanner />
      <InvalidateSizeOnChange resizeKey={resizeKey} />
      <FlyTo center={center} zoom={zoom} />
      {fitToMarkers && <FitToMarkers markers={markers} />}
      {markers.map(marker => {
        // Every campaign at this place is listed (earliest first) — showing
        // only the first hid any later day's campaign from a visitor, and
        // "Yes I'm In" could only ever register interest in that one.
        const campaigns = marker.campaigns ? sortCampaignsChronologically(marker.campaigns) : [];
        return (
          <Marker key={`${marker.state}::${marker.place}`} position={[marker.latitude, marker.longitude]} icon={getStateMarkerIcon(marker.state, marker.place, markerStyle)} eventHandlers={onMarkerOpen ? { click: onMarkerOpen } : undefined}>
            <Popup>
              {campaigns.length > 0 ? (
                <div className="text-sm">
                  <p className="font-semibold">{marker.place}, {marker.state}</p>
                  {campaigns.map(campaign => (
                    <div key={campaign.id} className="mt-2 border-t border-gray-200 pt-2" data-testid="map-popup-campaign">
                      <p>{formatCampaignDateTimeDisplay(campaign.date, campaign.time)}</p>
                      <p>Leader: {campaign.leader}</p>
                      {!renderPlaceActions && renderActions({ campaignId: campaign.id, place: marker.place, state: marker.state })}
                    </div>
                  ))}
                  {renderPlaceActions?.({ campaignIds: campaigns.map(c => c.id), place: marker.place, state: marker.state })}
                </div>
              ) : (
                <p className="text-sm font-semibold">{marker.place} {marker.state}</p>
              )}
            </Popup>
          </Marker>
        );
      })}
    </MapContainer>
  );
}

components/ErrorBoundary.tsx:
'use client';

import { Component, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  message: string;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, message: '' };
  }

  static getDerivedStateFromError(error: unknown): State {
    const message = error instanceof Error ? error.message : 'An unexpected error occurred.';
    return { hasError: true, message };
  }

  componentDidCatch(error: unknown, info: { componentStack: string }) {
    console.error('ErrorBoundary caught:', error, info.componentStack);
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) return this.props.fallback;

      return (
        <div className="min-h-screen flex items-center justify-center p-6 bg-gray-50">
          <div className="max-w-md w-full bg-white rounded-xl shadow-sm border border-gray-200 p-8 text-center">
            <div className="text-4xl mb-4">⚠️</div>
            <h1 className="text-xl font-semibold text-gray-900 mb-2">Something went wrong</h1>
            <p className="text-gray-500 text-sm mb-6">{this.state.message}</p>
            <button
              onClick={() => {
                this.setState({ hasError: false, message: '' });
                window.location.reload();
              }}
              className="bg-blue-600 text-white px-5 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors"
            >
              Reload page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

components/FullscreenImageViewer.tsx:
'use client';

/**
 * Full-viewport image overlay, always presented in landscape.
 *
 * - On a device that's already landscape (e.g. an iPad turned sideways), the
 *   image simply fills the screen.
 * - On a portrait device (most phones), the image is rotated 90° with CSS so
 *   it reads as landscape without needing the device physically turned.
 *   This is done with plain CSS (not the Screen Orientation API) because
 *   orientation *locking* has no iOS Safari support at all — the CSS rotate
 *   is the one approach that works everywhere.
 * - As a progressive enhancement, also requests real browser Fullscreen
 *   (hides the address bar / chrome) where the API is available; failures
 *   are swallowed since the CSS-rotated overlay already satisfies the
 *   "fullscreen landscape" requirement on its own.
 * - Easy to leave on a phone: a large labelled Close button, tapping anywhere
 *   closes, and the phone's Back gesture/button closes it too (the viewer
 *   pushes one history entry while open, so Back returns to the page instead
 *   of leaving it). Leaving real fullscreen (e.g. swipe down) also closes it.
 */
import { useCallback, useEffect, useRef, useState } from 'react';

interface Props {
  src: string;
  alt: string;
  onClose: () => void;
}

export default function FullscreenImageViewer({ src, alt, onClose }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  const pushedHistoryRef = useRef(false);
  const [isPortrait, setIsPortrait] = useState(
    () => typeof window !== 'undefined' && window.innerHeight > window.innerWidth,
  );

  useEffect(() => {
    const updateOrientation = () => setIsPortrait(window.innerHeight > window.innerWidth);
    updateOrientation();
    window.addEventListener('resize', updateOrientation);
    window.addEventListener('orientationchange', updateOrientation);
    return () => {
      window.removeEventListener('resize', updateOrientation);
      window.removeEventListener('orientationchange', updateOrientation);
    };
  }, []);

  useEffect(() => {
    onCloseRef.current = onClose;
  }, [onClose]);

  // Every close goes through here: if we pushed a history entry, popping it
  // (popstate below) is what actually closes, so Back and the Close button
  // behave identically and no stray entry is left behind.
  const close = useCallback(() => {
    if (pushedHistoryRef.current) {
      window.history.back();
    } else {
      onCloseRef.current();
    }
  }, []);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    const handlePopState = () => {
      pushedHistoryRef.current = false;
      onCloseRef.current();
    };
    let enteredFullscreen = false;
    const handleFullscreenChange = () => {
      if (enteredFullscreen && !document.fullscreenElement) close();
    };
    document.addEventListener('keydown', handleKey);
    window.addEventListener('popstate', handlePopState);
    document.addEventListener('fullscreenchange', handleFullscreenChange);

    // Guarded so React Strict Mode's dev-only mount/unmount/mount can't stack two entries.
    if (!window.history.state?.fullscreenImageViewer) {
      window.history.pushState({ fullscreenImageViewer: true }, '');
    }
    pushedHistoryRef.current = true;

    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    // Best-effort real fullscreen — silently no-ops where unsupported
    // (notably iOS Safari before 16.4) since the CSS rotate below already
    // makes the image read as landscape and fill the viewport regardless.
    containerRef.current
      ?.requestFullscreen?.()
      .then(() => { enteredFullscreen = true; })
      .catch(() => {});

    return () => {
      document.removeEventListener('keydown', handleKey);
      window.removeEventListener('popstate', handlePopState);
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      document.body.style.overflow = prevOverflow;
      enteredFullscreen = false;
      if (document.fullscreenElement) {
        document.exitFullscreen().catch(() => {});
      }
    };
  }, [close]);

  return (
    <div data-ti="components/FullscreenImageViewer.tsx"
      ref={containerRef}
      className="fixed inset-0 z-[2000] flex items-center justify-center overflow-hidden bg-black"
      onClick={close}
    >
      <button
        onClick={close}
        aria-label="Close full screen view"
        className="absolute right-3 top-3 z-10 flex items-center gap-2 rounded-full border-2 border-white bg-black/70 px-5 py-3 text-lg font-bold text-white hover:bg-black"
        style={{ marginTop: 'env(safe-area-inset-top)', marginRight: 'env(safe-area-inset-right)' }}
      >
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} className="h-6 w-6" aria-hidden="true">
          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
        </svg>
        Close
      </button>
      {/* eslint-disable-next-line @next/next/no-img-element -- object URL, not an optimizable static/remote asset */}
      <img
        src={src}
        alt={alt}
                style={
          isPortrait
            ? {
                width: '100vh',
                height: '100vw',
                maxWidth: 'none',
                maxHeight: 'none',
                transform: 'rotate(90deg)',
                objectFit: 'contain',
              }
            : {
                width: '100vw',
                height: '100vh',
                maxWidth: 'none',
                maxHeight: 'none',
                objectFit: 'contain',
              }
        }
      />
    </div>
  );
}

