'use client';

import { ReactNode, Suspense, useEffect, useState } from 'react';
import Link from 'next/link';
import { usePathname, useSearchParams } from 'next/navigation';
import { signOut } from '@/lib/auth';
import { supabase } from '@/lib/supabaseClient';
import Modal from '@/components/Modal';
import OpenGuideLabel from '@/components/OpenGuideLabel';
import { useUser } from '@/contexts/UserContext';

interface MobileLayoutProps {
  children: ReactNode;
}

type NavItem = {
  href: string;
  label: string;
  icon?: string;
  iconImage?: string;
  isSrAdmin?: boolean;
  isTlAdmin?: boolean;
  /** The USER GUIDE item: bold gold stacked label (OpenGuideLabel) instead of icon + label. */
  textOnly?: boolean;
};

function MobileLayoutNav({ pathname, navItems }: { pathname: string; navItems: NavItem[] }) {
  return (
    <div className={`flex items-center ${navItems.length === 1 ? 'justify-center' : 'justify-around'}`}>
      {navItems.map((item) => {
        const isActive = item.isSrAdmin
          ? pathname === '/app/sr-admin'
          : item.isTlAdmin
            ? pathname === '/app/tl-admin'
            : item.href === '/app'
              ? pathname === '/app'
              : pathname === item.href || (item.href !== '/app' && pathname?.startsWith(item.href));
        return (
          <Link
            key={item.href}
            href={item.href}
            className={`flex flex-col items-center justify-center gap-1 px-4 py-3 transition-colors ${
              isActive
                ? 'text-blue-600 dark:text-blue-400'
                : 'text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-gray-100'
            }`}
          >
            {item.textOnly ? (
              <OpenGuideLabel />
            ) : 'iconImage' in item && item.iconImage ? (
              <img src={item.iconImage} alt="" className="h-6 w-6 object-contain" />
            ) : (
              <span className="text-xl">{item.icon}</span>
            )}
            {!item.textOnly && <span className="text-xs font-medium">{item.label}</span>}
          </Link>
        );
      })}
    </div>
  );
}

/** Uses useSearchParams(); must be rendered inside Suspense for static prerender */
function MobileLayoutNavWithSearchParams({ pathname, navItems }: { pathname: string; navItems: NavItem[] }) {
  void useSearchParams(); // Required for static prerender - triggers client hydration
  return <MobileLayoutNav pathname={pathname} navItems={navItems} />;
}

export default function MobileLayout({ children }: MobileLayoutProps) {
  const pathname = usePathname();
  // Larger text everywhere except the admin screens (dense tables) — see `.large-text` in app/globals.css.
  const largeText = !(pathname ?? '').startsWith('/admin');
  // Role comes from UserContext, which resolves it once per app load. MobileLayout
  // remounts on every page, so querying here again cost a getUser() round trip plus
  // two table lookups on every navigation.
  const { adminStatus: userAdminStatus, isLoading: isUserLoading } = useUser();
  const isAdmin = isUserLoading ? null : userAdminStatus === 'AD';
  const adminStatus = userAdminStatus;
  const [showSignOutConfirm, setShowSignOutConfirm] = useState(false);
  // Only a leader signed in via the real-auth + MFA path (app/login/mfa)
  // has more than one selectable role tied to their session — the
  // mobile+name flow picks a state once, at login, via different
  // credentials per role. Gates the "Switch Role" button below.
  const [canSwitchRole, setCanSwitchRole] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setCanSwitchRole(!!session && session.user.is_anonymous === false);
    });
  }, []);

  const homeNavItem: NavItem    = { href: '/app',           label: 'Home',    icon: '🏠' };
  const metricsNavItem: NavItem = { href: '/admin/metrics', label: 'Metrics', icon: '📊' };
  const adminNavItem: NavItem   = { href: '/admin',         label: 'Admin',   icon: '⚙️' };
  const srAdminNavItem: NavItem = { href: '/app/sr-admin',  label: 'Admin',    icon: '⚙️', isSrAdmin: true };
  const tlAdminNavItem: NavItem = { href: '/app/tl-admin',  label: 'My Admin', icon: '⚙️', isTlAdmin: true };
  const guideNavItem: NavItem   = { href: '/app/guide',     label: 'USER GUIDE', textOnly: true };

  // Full admins (AD): Home | Metrics | Admin
  // State reporters (SR): Home | SR Admin
  // Team leaders: Home | Open Guide | TL Admin
  const navItems: NavItem[] = isAdmin === null
    ? []
    : isAdmin
      ? [homeNavItem, metricsNavItem, adminNavItem]
      : adminStatus === 'SR'
        ? [homeNavItem, srAdminNavItem]
        : [homeNavItem, guideNavItem, tlAdminNavItem];

  const handleSignOut = async () => {
    setShowSignOutConfirm(false);
    try {
      await signOut();
      window.location.href = '/login';
    } catch (error) {
      console.error('Error signing out:', error);
    }
  };

  return (
    <div data-ti="components/MobileLayout.tsx" className="flex min-h-screen flex-col bg-gray-50 dark:bg-gray-900 overflow-x-hidden">
      {/* Header */}
      <header className="sticky top-0 z-10 border-b-2 border-gray-800 dark:border-gray-600 bg-white dark:bg-gray-950">
        <div className="flex h-14 items-center justify-between px-4">
          <h1 className="text-base sm:text-lg font-semibold text-gray-900 dark:text-gray-100 truncate">
            AFJ Campaign Activity System
          </h1>
          <div className="flex items-center gap-2">
            {canSwitchRole && (
              <a
                href="/login/mfa/callback"
                className="rounded-md px-3 py-1.5 text-base font-bold text-gray-700 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-800 whitespace-nowrap border-2 border-gray-800 dark:border-gray-600"
              >
                Switch Role
              </a>
            )}
            <button
              onClick={() => setShowSignOutConfirm(true)}
              className="rounded-md px-3 py-1.5 text-base font-bold text-gray-700 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-800 whitespace-nowrap border-2 border-gray-800 dark:border-gray-600"
            >
              Sign Out
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className={`flex-1 overflow-y-auto overflow-x-hidden pb-20 ${largeText ? 'large-text' : ''}`}>
        {children}
      </main>

      {/* Sign-Out Confirmation Modal */}
      {showSignOutConfirm && (
        <Modal onClose={() => setShowSignOutConfirm(false)}>
          <div className="w-full max-w-sm rounded-xl border-2 border-gray-800 bg-white p-6 shadow-2xl dark:border-gray-600 dark:bg-gray-900">
            <h2 className="text-xl font-bold text-gray-900 dark:text-gray-100">Sign Out?</h2>
            <p className="mt-2 text-base text-gray-600 dark:text-gray-400">
              Are you sure you want to sign out?
            </p>
            <div className="mt-6 flex flex-col gap-3">
              <button
                onClick={handleSignOut}
                className="w-full rounded-md bg-red-600 px-4 py-3 text-base font-bold text-white hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
              >
                Yes, Sign Out
              </button>
              <button
                onClick={() => setShowSignOutConfirm(false)}
                className="w-full rounded-md bg-gray-200 px-4 py-3 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
              >
                Stay Signed In
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* Bottom Navigation (Suspense required for useSearchParams during prerender) */}
      <nav className="fixed bottom-0 left-0 right-0 border-t-2 border-gray-800 dark:border-gray-600 bg-white dark:bg-gray-950">
        <Suspense fallback={<MobileLayoutNav pathname={pathname ?? ''} navItems={navItems} />}>
          <MobileLayoutNavWithSearchParams pathname={pathname ?? ''} navItems={navItems} />
        </Suspense>
      </nav>
    </div>
  );
}

components/Modal.tsx:
'use client';
import { useEffect, type ReactNode } from 'react';
import { createPortal } from 'react-dom';

interface Props {
  onClose?: () => void;
  children: ReactNode;
  /** 'bottom' slides up from the bottom on mobile, centers on sm+. Default: 'center'. */
  position?: 'center' | 'bottom';
}

export default function Modal({ onClose, children, position = 'center' }: Props) {
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose?.();
    };
    document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, [onClose]);

  // Portaled straight to <body> rather than rendered in place: a `position:
  // fixed` element is only fixed to the *viewport* if none of its ancestors
  // have a `transform` set — but Leaflet applies `transform: translate3d(...)`
  // to its panes for panning performance, and this component is now also
  // triggered from inside a map popup (components/PublicCampaignInterestActions.tsx),
  // which react-leaflet renders as a real DOM descendant of that transformed
  // pane. Without the portal, the modal would end up positioned relative to
  // the map instead of the screen.
  //
  // No mount-effect delay guard needed here (the usual pattern for a
  // SSR-safe portal): every current/expected caller only ever adds this
  // component to the tree in response to a later client-side state change
  // (e.g. clicking a button), never present on the very first render — so
  // there's nothing for this to mismatch against during SSR, and `document`
  // is always real by the time this actually runs. The `typeof document`
  // check below is just a defensive guard against a future caller that
  // renders this unconditionally from the start.
  if (typeof document === 'undefined') return null;

  return createPortal(
    <div
      // z-[2000]: Leaflet's own panes/controls (used by the campaign map) set
      // z-index up to 1000, which would otherwise render on top of this modal.
      data-ti="components/Modal.tsx"
      className={`large-text fixed inset-0 z-[2000] flex justify-center bg-black/60 p-4 ${
        position === 'bottom' ? 'items-end sm:items-center' : 'items-center'
      }`}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose?.();
      }}
    >
      {children}
    </div>,
    document.body,
  );
}

components/NearbyCampaignsMap.tsx:
'use client';

import 'leaflet/dist/leaflet.css';
import { useEffect, useMemo, type ReactNode } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Circle, useMap } from 'react-leaflet';
import L from 'leaflet';
import { getStateMarkerIcon } from '@/lib/leafletMarkerIcon';
import { formatCampaignDateTimeDisplay, sortCampaignsChronologically } from '@/lib/campaignUtils';
import MapPopupActions from '@/components/MapPopupActions';
import TechInsightsMapTag from '@/components/techInsights/TechInsightsMapTag';

/**
 * Just enough of a campaign for this map's popup (id/date/time/leader) —
 * kept minimal and local rather than importing the admin-only
 * NearbyMapMarker/Campaign types, so the public "Campaigns Near Me" screen
 * (app/public/campaigns-near-me) — whose campaign rows carry far fewer
 * fields — can use this same component without an awkward cast. A full
 * admin `Campaign` object already structurally satisfies this.
 */
export interface NearbyMapPopupCampaign {
  id: string;
  date: string;
  time: string;
  leader: string;
}

export interface NearbyMapPopupMarker {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
  distanceKm: number;
  campaigns: NearbyMapPopupCampaign[];
}

// Distinct centre marker drawn as a CSS pin so it can't be confused with a campaign.
const centerIcon = L.divIcon({
  className: 'nearby-center-marker',
  html:
    '<div style="width:18px;height:18px;border-radius:50%;background:#dc2626;border:3px solid #fff;box-shadow:0 0 0 1px #000;"></div>',
  iconSize: [18, 18],
  iconAnchor: [9, 9],
});

/**
 * Bounds framing the user's centre and the full radius circle.
 * 1 degree of latitude is ~111 km; longitude scales with cos(lat).
 */
function radiusBounds(center: [number, number], radiusKm: number): L.LatLngBounds {
  const latDelta = radiusKm / 111;
  const lngDelta = radiusKm / (111 * Math.max(0.1, Math.cos((center[0] * Math.PI) / 180)));
  return L.latLngBounds(
    [center[0] - latDelta, center[1] - lngDelta],
    [center[0] + latDelta, center[1] + lngDelta],
  );
}

interface FitBoundsProps {
  center: [number, number];
  radiusKm: number;
}

/**
 * Frames the map so the user's centre, the 60 km radius circle, and all
 * campaign markers are visible. Re-runs whenever the centre changes (new
 * geolocation fix or address lookup) so the starting view stays in sync —
 * this is also the view `ResetViewControl` returns to.
 */
function FitBounds({ center, radiusKm }: FitBoundsProps) {
  const map = useMap();
  useEffect(() => {
    // Zero padding so the radius circle pushes right up to the edge of whichever
    // dimension is the constraining one — the circle stays fully visible but the
    // map area outside it is minimised.
    map.fitBounds(radiusBounds(center, radiusKm), { padding: [0, 0], animate: false });
  }, [map, center, radiusKm]);
  return null;
}

/**
 * Floating button that re-frames the map back to its starting view (the same
 * bounds `FitBounds` computes) — lets the user zoom/pan in to explore, then
 * return to the overview without hunting for their centre point again.
 */
function ResetViewControl({ center, radiusKm }: FitBoundsProps) {
  const map = useMap();
  return (
    <button
      type="button"
      onClick={() => map.fitBounds(radiusBounds(center, radiusKm), { padding: [0, 0] })}
      className="absolute top-2 right-2 z-[1000] rounded-md border-2 border-gray-800 bg-white px-2 py-1 text-xs font-bold text-gray-700 shadow hover:bg-gray-100 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-gray-700"
    >
      Reset view
    </button>
  );
}

interface NearbyCampaignsMapProps {
  center: [number, number];
  radiusKm: number;
  markers: NearbyMapPopupMarker[];
  /**
   * What to render under the Leader line in a campaign marker's popup —
   * defaults to the admin `MapPopupActions` stub. The public
   * "Campaigns Near Me" screen (app/public/campaigns-near-me) passes its
   * own renderer here instead, wired to actually record interest for a
   * known registrant rather than console.log placeholders.
   */
  renderActions?: (props: { campaignId: string; place: string; state: string }) => ReactNode;
}

/**
 * Map of campaigns near a centre point. Starts framed on the centre + radius
 * circle; the user can zoom and pan freely to explore, then use the "Reset
 * view" button to return to that starting frame.
 */
export default function NearbyCampaignsMap({
  center,
  radiusKm,
  markers,
  renderActions = (props) => <MapPopupActions {...props} />,
}: NearbyCampaignsMapProps) {
  const radiusMeters = useMemo(() => radiusKm * 1000, [radiusKm]);

  return (
    <MapContainer
      center={center}
      zoom={9}
      // Allow fractional zoom levels so fitBounds can land the 60 km circle
      // tight against the viewport edge instead of rounding down to the next
      // whole zoom level and leaving a wide margin around the circle.
      zoomSnap={0}
      zoomDelta={0.25}
      scrollWheelZoom
      style={{ height: '100%', width: '100%' }}
    >
      <TileLayer
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        url="/api/tiles/{z}/{x}/{y}"
      />
      <TechInsightsMapTag data-ti="components/NearbyCampaignsMap.tsx" />
      <FitBounds center={center} radiusKm={radiusKm} />
      <ResetViewControl center={center} radiusKm={radiusKm} />
      <Circle
        center={center}
        radius={radiusMeters}
        pathOptions={{ color: '#2563eb', weight: 2, fillColor: '#3b82f6', fillOpacity: 0.08 }}
      />
      <Marker position={center} icon={centerIcon}>
        <Popup>
          <div className="text-sm">
            <p className="font-semibold">You are here</p>
            <p className="mt-1">Showing campaigns within {radiusKm} km</p>
          </div>
        </Popup>
      </Marker>
      {markers.map(marker => {
        // Every campaign at this place is listed (earliest first) — showing
        // only the first hid later days' campaigns from the visitor.
        const campaigns = sortCampaignsChronologically(marker.campaigns);
        if (campaigns.length === 0) return null;
        return (
          <Marker
            key={`${marker.state}::${marker.place}`}
            position={[marker.latitude, marker.longitude]}
            // Larger and more opaque than CampaignMap's default (22px/0.35) —
            // this map is meant to be tapped on a phone, so markers need to
            // stand out and be easy to hit, per Peter's request (2026-09-17).
            icon={getStateMarkerIcon(marker.state, marker.place, { size: 30, fillOpacity: 0.5 })}
          >
            <Popup>
              <div className="text-sm">
                <p className="font-semibold">{marker.place}, {marker.state}</p>
                <p className="mt-1">{marker.distanceKm} km away</p>
                {campaigns.map(campaign => (
                  <div key={campaign.id} className="mt-2 border-t border-gray-200 pt-2" data-testid="map-popup-campaign">
                    <p>{formatCampaignDateTimeDisplay(campaign.date, campaign.time)}</p>
                    <p>Leader: {campaign.leader}</p>
                    {renderActions({ campaignId: campaign.id, place: marker.place, state: marker.state })}
                  </div>
                ))}
              </div>
            </Popup>
          </Marker>
        );
      })}
    </MapContainer>
  );
}

