components/PWAInstallPrompt.tsx:
'use client';
import { useEffect, useState } from 'react';
import { usePathname } from 'next/navigation';

type Platform = 'ios' | 'android' | 'desktop' | null;

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

// Bump this key to reset the dismissed state for all users (e.g. after a bug fix).
const DISMISSED_KEY = 'pwa-install-dismissed-v2';

function detectPlatform(): Platform {
  const ua = navigator.userAgent;
  if (/iphone|ipad|ipod/i.test(ua)) return 'ios';
  if (/android/i.test(ua)) return 'android';
  return 'desktop';
}

function isStandalone(): boolean {
  return (
    window.matchMedia('(display-mode: standalone)').matches ||
    ('standalone' in navigator && (navigator as { standalone?: boolean }).standalone === true)
  );
}

export default function PWAInstallPrompt() {
  // Public, unauthenticated pages (shared as one-off links, e.g. via WhatsApp)
  // should open straight into their content — no install pitch aimed at
  // logged-in leaders using the main app.
  const pathname = usePathname();
  const isPublicPage = pathname?.startsWith('/public/') ?? false;

  // null = hidden; non-null = visible with the detected platform. Starts null so the
  // first client render matches the server's (which can't see window/localStorage);
  // the real value is filled in after mount.
  const [platform, setPlatform] = useState<Platform>(null);

  // setState goes through a Promise callback (react-hooks/set-state-in-effect).
  useEffect(() => {
    let cancelled = false;
    Promise.resolve().then(() => {
      if (cancelled) return;
      if (isStandalone() || localStorage.getItem(DISMISSED_KEY)) return;
      setPlatform(detectPlatform());
    });
    return () => {
      cancelled = true;
    };
  }, []);

  // showInstructions: true once the user asks how to install (iOS always; Android fallback)
  const [showInstructions, setShowInstructions] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);

  // Effect is purely for the beforeinstallprompt event listener — no setState here.
  useEffect(() => {
    if (!platform) return;
    const handler = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e as BeforeInstallPromptEvent);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, [platform]);

  const dismiss = () => {
    localStorage.setItem(DISMISSED_KEY, '1');
    setPlatform(null);
    setShowInstructions(false);
  };

  // Rendered as a fixed overlay above the bottom nav, not in normal flow: it only
  // appears after hydration (it needs localStorage / the user agent), so an in-flow
  // banner pushed the whole page down once it mounted — a layout shift on every
  // first visit. An overlay moves nothing, so pages need no knowledge of its height.

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      // Android/desktop Chrome: trigger the native install dialog
      await deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') dismiss();
    } else {
      // Either iOS (Apple never fires beforeinstallprompt) or the Chrome event
      // hasn't fired yet — show manual instructions appropriate to the platform.
      setShowInstructions(true);
    }
  };

  if (isPublicPage || !platform) return null;

  const isIOS = platform === 'ios';
  const isAndroid = platform === 'android';

  return (
    <div data-ti="components/PWAInstallPrompt.tsx" className="fixed inset-x-0 bottom-20 z-20 max-h-[60dvh] overflow-y-auto bg-[#1e3a5f] text-white px-4 py-3 text-sm shadow-lg">
      <div className="flex items-start justify-between gap-3 max-w-lg mx-auto">
        <div className="flex-1 min-w-0">
          {!showInstructions ? (
            <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:gap-3">
              <p className="font-semibold leading-snug">
                Install this app on your{' '}
                {isIOS ? 'iPhone/iPad' : isAndroid ? 'Android' : 'device'} for
                the best experience — opens full-screen like a native app
              </p>
              <button
                onClick={handleInstallClick}
                className="shrink-0 self-start rounded-md bg-white px-3 py-1.5 text-sm font-bold text-[#1e3a5f] hover:bg-blue-50 focus:outline-none focus:ring-2 focus:ring-white"
              >
                {isIOS ? 'How to install' : 'Install'}
              </button>
            </div>
          ) : isIOS ? (
            /* ── iOS instructions ── */
            <div>
              <p className="font-semibold mb-2">Install on iPhone / iPad (Safari):</p>
              <ol className="space-y-1 list-none">
                <li className="flex items-start gap-2">
                  <span className="shrink-0">1.</span>
                  <span>
                    Tap the{' '}
                    <span className="inline-flex items-center gap-0.5 font-bold">
                      Share{' '}
                      <svg
                        className="inline-block w-4 h-4 mb-0.5"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden="true"
                      >
                        <path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8" />
                        <polyline points="16 6 12 2 8 6" />
                        <line x1="12" y1="2" x2="12" y2="15" />
                      </svg>
                    </span>{' '}
                    button at the bottom of Safari
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="shrink-0">2.</span>
                  <span>
                    Scroll down and tap{' '}
                    <span className="font-bold">Add to Home Screen</span>
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="shrink-0">3.</span>
                  <span>
                    Tap <span className="font-bold">Add</span> — done!
                  </span>
                </li>
              </ol>
            </div>
          ) : (
            /* ── Android / desktop fallback instructions ── */
            <div>
              <p className="font-semibold mb-2">
                Install on {isAndroid ? 'Android (Chrome)' : 'your browser'}:
              </p>
              <ol className="space-y-1 list-none">
                <li className="flex items-start gap-2">
                  <span className="shrink-0">1.</span>
                  <span>
                    Tap the <span className="font-bold">⋮</span> menu in the
                    top-right corner of Chrome
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="shrink-0">2.</span>
                  <span>
                    Tap{' '}
                    <span className="font-bold">Add to Home screen</span>
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="shrink-0">3.</span>
                  <span>
                    Tap <span className="font-bold">Add</span> — done!
                  </span>
                </li>
              </ol>
            </div>
          )}
        </div>
        <button
          onClick={dismiss}
          className="shrink-0 text-white/70 hover:text-white text-lg leading-none focus:outline-none mt-0.5"
          aria-label="Dismiss install prompt"
        >
          ✕
        </button>
      </div>
    </div>
  );
}

components/PdfGuideViewer.tsx:
'use client';

import { useEffect, useRef, useState } from 'react';
import type { PDFDocumentProxy } from 'pdfjs-dist';
import { computePdfRenderScale } from '@/lib/pdfRenderScale';

interface PdfGuideViewerProps {
  url: string;
  /** Called when the PDF can't be shown here, so the caller can offer the plain link instead. */
  onError: (err: unknown) => void;
}

/**
 * Renders every page of a PDF, top to bottom, at the width of the screen,
 * using pdf.js. Used instead of the browser's own PDF viewer so the guide can
 * sit inside the app with our own Close button — phones don't reliably show a
 * PDF embedded in a page (Android Chrome won't at all, iPhones often show only
 * page 1). Uses pdf.js's "legacy" build, which supports older phones.
 */
export default function PdfGuideViewer({ url, onError }: PdfGuideViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [doc, setDoc] = useState<PDFDocumentProxy | null>(null);
  const onErrorRef = useRef(onError);
  useEffect(() => { onErrorRef.current = onError; }, [onError]);

  // 1. Load the document (pdf.js is only downloaded when the guide is opened).
  useEffect(() => {
    let cancelled = false;
    let destroy: (() => void) | null = null;
    (async () => {
      const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
      pdfjs.GlobalWorkerOptions.workerSrc = new URL('pdfjs-dist/legacy/build/pdf.worker.min.mjs', import.meta.url).toString();
      const task = pdfjs.getDocument({ url });
      destroy = () => { void task.destroy(); };
      const loaded = await task.promise;
      if (!cancelled) setDoc(loaded);
    })().catch((err: unknown) => {
      if (!cancelled) onErrorRef.current(err);
    });
    return () => {
      cancelled = true;
      destroy?.();
    };
  }, [url]);

  // 2. Once a canvas exists for every page, draw them in order, so page 1
  //    appears as soon as it's ready.
  useEffect(() => {
    if (!doc) return;
    let cancelled = false;
    (async () => {
      for (let n = 1; n <= doc.numPages; n++) {
        const container = containerRef.current;
        const canvas = container?.querySelector<HTMLCanvasElement>(`canvas[data-page="${n}"]`);
        if (cancelled || !container || !canvas) return;

        const page = await doc.getPage(n);
        const base = page.getViewport({ scale: 1 });
        const { renderScale } = computePdfRenderScale(container.clientWidth, base.width, window.devicePixelRatio);
        const viewport = page.getViewport({ scale: renderScale });
        canvas.width = Math.floor(viewport.width);
        canvas.height = Math.floor(viewport.height);
        canvas.style.aspectRatio = `${base.width} / ${base.height}`;
        await page.render({ canvas, viewport }).promise;
        page.cleanup();
      }
    })().catch((err: unknown) => {
      if (!cancelled) onErrorRef.current(err);
    });
    return () => { cancelled = true; };
  }, [doc]);

  return (
    <div data-ti="components/PdfGuideViewer.tsx" ref={containerRef} className="mx-auto w-full max-w-3xl">
      {doc === null ? (
        <p className="p-8 text-center text-xl text-gray-700 dark:text-gray-300">Opening the guide…</p>
      ) : (
        Array.from({ length: doc.numPages }, (_, i) => (
          <canvas
            key={i + 1}
            data-page={i + 1}
            role="img"
            aria-label={`Guide page ${i + 1} of ${doc.numPages}`}
            // Placeholder A4 shape until the real page size is known.
            className="mb-3 block aspect-[1/1.414] h-auto w-full bg-white shadow-md"
          />
        ))
      )}
    </div>
  );
}

components/PublicCampaignInterestActions:
'use client';

/**
 * Real "Yes I'm In" / "Tell Me More" actions for the public "Campaigns Near
 * Me" screen (app/public/campaigns-near-me) — the registrant-facing
 * counterpart to components/MapPopupActions.tsx's admin stub. Submits
 * straight to /api/public/campaigns-near-me's POST handler with only the
 * registrant id it already has (from the page's own `?r=` param) — no
 * name/mobile/email re-entry, since the server looks those up from
 * registry.registrants itself.
 *
 * Same consent-confirmation step as the general public Register Interest
 * flow (components/registerInterest/InterestSummaryModal.tsx) before
 * either button actually submits — reusing the shared Modal component
 * that flow already established (its z-index is deliberately high enough
 * to sit above this screen's Leaflet map, see components/Modal.tsx).
 */
import { useState } from 'react';
import Modal from '@/components/Modal';

type Status = 'idle' | 'submitting' | 'done' | 'error';
type InterestType = 'in' | 'more';

interface PublicCampaignInterestActionsProps {
  registrantId: string;
  campaignId: string;
}

export default function PublicCampaignInterestActions({ registrantId, campaignId }: PublicCampaignInterestActionsProps) {
  const [pendingType, setPendingType] = useState<InterestType | null>(null);
  const [status, setStatus] = useState<Status>('idle');
  const [doneType, setDoneType] = useState<InterestType | null>(null);
  const [error, setError] = useState<string | null>(null);

  function requestConfirmation(interestType: InterestType) {
    setError(null);
    setPendingType(interestType);
  }

  async function confirm() {
    if (!pendingType) return;
    setStatus('submitting');
    setError(null);
    try {
      const res = await fetch('/api/public/campaigns-near-me', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ registrantId, campaignId, interestType: pendingType }),
      });
      const json = await res.json();
      if (!res.ok) {
        setStatus('error');
        setError(json.error ?? 'Something went wrong — please try again.');
        return;
      }
      setDoneType(pendingType);
      setStatus('done');
      setPendingType(null);
    } catch (err) {
      console.error('[PublicCampaignInterestActions] submit failed:', err);
      setStatus('error');
      setError('Something went wrong — please try again.');
    }
  }

  function cancel() {
    if (status === 'submitting') return;
    setPendingType(null);
    setStatus('idle');
    setError(null);
  }

  if (status === 'done') {
    return (
      <p className="mt-2 text-xs font-semibold text-green-700">
        {doneType === 'in' ? "✓ Thanks — you're registered! A leader will be in touch." : '✓ Thanks — someone will reach out with more details.'}
      </p>
    );
  }

  return (
    <div data-ti="components/PublicCampaignInterestActions.tsx" className="mt-2">
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => requestConfirmation('in')}
          className="rounded-md border border-gray-800 bg-green-600 px-2 py-1 text-xs font-bold text-white hover:bg-green-700"
        >
          Yes I&apos;m In
        </button>
        <button
          type="button"
          onClick={() => requestConfirmation('more')}
          className="rounded-md border border-gray-800 bg-orange-500 px-2 py-1 text-xs font-bold text-white hover:bg-orange-600"
        >
          Tell Me More
        </button>
      </div>

      {pendingType && (
        <Modal onClose={status === 'submitting' ? undefined : cancel}>
          <div className="w-full max-w-sm rounded-xl border-2 border-gray-800 bg-white p-6 text-left shadow-2xl dark:border-gray-600 dark:bg-gray-900">
            <p className="text-sm font-semibold text-gray-900 dark:text-gray-100">
              By proceeding you agree that your details will be made available to the team leader of this campaign, and you give your
              permission for them to contact you regarding their campaign.
            </p>

            {error && (
              <p className="mt-3 rounded-md border border-red-200 bg-red-50 p-2 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
                {error}
              </p>
            )}

            <div className="mt-5 flex gap-3">
              <button
                type="button"
                onClick={confirm}
                disabled={status === 'submitting'}
                className="flex-1 rounded-md bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 border-2 border-gray-800 dark:border-gray-600"
              >
                {status === 'submitting' ? 'Submitting…' : 'Proceed'}
              </button>
              <button
                type="button"
                onClick={cancel}
                disabled={status === 'submitting'}
                className="flex-1 rounded-md bg-gray-200 px-4 py-2 text-sm font-bold text-gray-700 hover:bg-gray-300 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
              >
                Cancel
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

