'use client';

/**
 * Confirmation modal for a general public visitor registering interest —
 * no known identity to look name/mobile/email up from (unlike
 * PublicCampaignInterestActions.tsx's registrant-specific flow), so this
 * collects them inline before submitting to POST
 * /api/public/register-interest. Shared by PublicMapRegisterInterestActions.tsx
 * (a single map-marker campaign) and the "List View" checklist on
 * /public/upcoming-campaigns (one or more ticked campaigns), so both
 * screens present an identical confirmation step with the same Proceed/
 * Cancel buttons and contact fields.
 */
import { useState } from 'react';
import Modal from '@/components/Modal';
import { isValidMobile, isValidEmail } from '@/lib/validation';

export type PublicInterestType = 'in' | 'more';

interface PublicRegisterInterestModalProps {
  campaignIds: string[];
  interestType: PublicInterestType;
  onCancel: () => void;
  onSuccess: () => void;
}

export default function PublicRegisterInterestModal({ campaignIds, interestType, onCancel, onSuccess }: PublicRegisterInterestModalProps) {
  const [firstName, setFirstName] = useState('');
  const [mobile, setMobile] = useState('');
  const [email, setEmail] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function confirm() {
    if (!firstName.trim()) {
      setError('Please enter your first name');
      return;
    }
    if (!isValidMobile(mobile) && !isValidEmail(email)) {
      setError('Please enter a valid mobile number or email address');
      return;
    }

    setIsSubmitting(true);
    setError(null);
    try {
      const res = await fetch('/api/public/register-interest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          firstName: firstName.trim(),
          mobile: mobile.trim(),
          email: email.trim(),
          interestType,
          campaignIds,
        }),
      });
      const json = await res.json();
      if (!res.ok) {
        setError(json.error ?? 'Something went wrong — please try again.');
        setIsSubmitting(false);
        return;
      }
      onSuccess();
    } catch (err) {
      console.error('[PublicRegisterInterestModal] submit failed:', err);
      setError('Something went wrong — please try again.');
      setIsSubmitting(false);
    }
  }

  return (
    <Modal onClose={isSubmitting ? undefined : onCancel}>
      <div data-ti="components/PublicRegisterInterestModal.tsx" className="w-full max-w-sm rounded-xl border-2 border-gray-800 bg-white p-6 text-left shadow-2xl dark:border-gray-600 dark:bg-gray-900">
        <p className="text-sm font-semibold text-gray-900 dark:text-gray-100">
          Enter your details below. By proceeding you agree that they will be made available to the team leader(s) of the
          selected campaign(s), and you give your permission for them to contact you regarding their campaign.
        </p>

        <div className="mt-4 space-y-3">
          <div>
            <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">First name</label>
            <input
              type="text"
              value={firstName}
              onChange={(e) => setFirstName(e.target.value)}
              className="mt-1 w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">Mobile number</label>
            <input
              type="tel"
              value={mobile}
              onChange={(e) => setMobile(e.target.value)}
              placeholder="04XX XXX XXX"
              className="mt-1 w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">Email (optional if mobile provided)</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="mt-1 w-full rounded-md border border-gray-300 px-2 py-1.5 text-sm dark:border-gray-600 dark:bg-gray-700 dark:text-gray-100"
            />
          </div>
        </div>

        {error && (
          <p className="mt-3 rounded-md border border-red-200 bg-red-50 p-2 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {error}
          </p>
        )}

        <div className="mt-5 flex gap-3">
          <button
            type="button"
            onClick={confirm}
            disabled={isSubmitting}
            className="flex-1 rounded-md bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 border-2 border-gray-800 dark:border-gray-600"
          >
            {isSubmitting ? 'Submitting…' : 'Proceed'}
          </button>
          <button
            type="button"
            onClick={onCancel}
            disabled={isSubmitting}
            className="flex-1 rounded-md bg-gray-200 px-4 py-2 text-sm font-bold text-gray-700 hover:bg-gray-300 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 border-2 border-gray-800 dark:border-gray-600"
          >
            Cancel
          </button>
        </div>
      </div>
    </Modal>
  );
}

components/SaveImageButton.tsx:
'use client';

/**
 * "Save to Photos" button — Web Share API Level 2 (file sharing).
 *
 * Browsers deliberately don't let a page write into the device's Photos
 * library on its own — that's a privacy boundary, not something we can code
 * around. The closest a web page can get is handing the image to the OS's
 * native share sheet via navigator.share({ files }), where "Save Image"
 * (which saves straight to Photos on iOS, or the gallery app on Android) is
 * one tap away. This is what iOS Safari and most mobile browsers support;
 * most desktop browsers don't support sharing files at all.
 *
 * Renders nothing when unsupported — callers should always also render a
 * plain download link/anchor alongside this as the universal fallback.
 */
import { useState } from 'react';

interface Props {
  blob: Blob;
  filename: string;
  label?: string;
  className?: string;
}

function toShareFile(blob: Blob, filename: string): File {
  return new File([blob], filename, { type: blob.type || 'image/jpeg' });
}

/** True if navigator.share can be handed this exact file — mainly iOS/Android
 * mobile browsers; false on most desktop browsers and in any non-secure
 * (non-HTTPS) context. */
function canShareFile(blob: Blob, filename: string): boolean {
  return (
    typeof navigator !== 'undefined' &&
    typeof navigator.canShare === 'function' &&
    navigator.canShare({ files: [toShareFile(blob, filename)] })
  );
}

export default function SaveImageButton({ blob, filename, label = 'Save to Photos', className }: Props) {
  // Lazy initializer — runs once on the client, no setState-in-effect needed.
  // Safe because both callers only mount this after their own client-side
  // fetch has resolved (never during SSR), and blob/filename don't change
  // again for a given button instance.
  const [isSupported] = useState(() => canShareFile(blob, filename));
  const [isSharing, setIsSharing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isSupported) return null;

  const handleClick = async () => {
    setError(null);
    setIsSharing(true);
    try {
      await navigator.share({ files: [toShareFile(blob, filename)] });
    } catch (err) {
      // AbortError just means the user closed the share sheet without
      // picking anything — not a real failure, nothing to report.
      if (err instanceof Error && err.name !== 'AbortError') {
        setError('Could not open Save to Photos — use Download instead.');
      }
    } finally {
      setIsSharing(false);
    }
  };

  return (
    <div data-ti="components/SaveImageButton.tsx" className="flex flex-col items-start gap-1">
      <button type="button" onClick={handleClick} disabled={isSharing} className={className}>
        {isSharing ? 'Opening…' : label}
      </button>
      {error ? (
        <p className="text-xs font-medium text-red-600 dark:text-red-400">{error}</p>
      ) : (
        <p className="text-xs text-gray-500 dark:text-gray-400">
          Opens the Share menu — choose &quot;Save Image&quot; to add it to Photos.
        </p>
      )}
    </div>
  );
}

components/ServiceWorkerRegistration.tsx:
'use client';
import { useEffect } from 'react';

export default function ServiceWorkerRegistration() {
  useEffect(() => {
    if (!('serviceWorker' in navigator)) return;

    // Reload once a new worker takes control, so an already-open tab/installed PWA
    // picks up the new deploy's assets instead of silently running stale ones.
    // Installed PWAs especially can sit on a backgrounded process for a long time
    // without a real network navigation, so this is the main way they self-heal.
    let hasReloaded = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (hasReloaded) return;
      hasReloaded = true;
      window.location.reload();
    });

    navigator.serviceWorker
      .register('/sw.js')
      .then((reg) => {
        console.log('SW registered:', reg.scope);

        // If a new worker is already waiting (e.g. install happened in a prior
        // visit), activate it now rather than waiting for the next deploy.
        if (reg.waiting) reg.waiting.postMessage('SKIP_WAITING');

        reg.addEventListener('updatefound', () => {
          const newWorker = reg.installing;
          newWorker?.addEventListener('statechange', () => {
            if (newWorker.state === 'installed' && reg.waiting) {
              reg.waiting.postMessage('SKIP_WAITING');
            }
          });
        });

        // Installed PWAs can resume from a backgrounded state without a network
        // request, so explicitly re-check for an update whenever the app regains
        // focus instead of waiting for the browser's own update schedule.
        document.addEventListener('visibilitychange', () => {
          if (document.visibilityState === 'visible') reg.update();
        });
      })
      .catch((err) => console.error('SW registration failed:', err));
  }, []);

  return null;
}

