'use client';

import Modal from '@/components/Modal';
import type { AriseCampaign } from '@/lib/ariseLayout';
import { formatShortDateWithOrdinal } from '@/lib/campaignDates';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { combinePlaceAndSite } from '@/lib/placeSite';

interface Props {
  campaigns: AriseCampaign[];
  onProceed: () => void;
  onCancel: () => void;
  isSubmitting?: boolean;
  error?: string | null;
}

/** e.g. "Frankston Wed 12th Aug 11:30am Linda" */
function formatCampaignLine(c: AriseCampaign): string {
  const place = combinePlaceAndSite(c.place, c.site);
  const [y, m, d] = c.date.split('-').map(Number);
  const dateText = formatShortDateWithOrdinal(new Date(y, m - 1, d));
  // formatCampaignTimeDisplay gives "11:30 AM" — lowercased and de-spaced to "11:30am"
  const time = formatCampaignTimeDisplay(c.time).toLowerCase().replace(' ', '');
  return `${place} ${dateText} ${time} ${c.leader}`;
}

/**
 * Confirmation shown when "Yes I'm In" or "Tell Me More" is pressed, listing
 * the ticked campaigns and asking the visitor to confirm before proceeding.
 * Proceeding records the interest against each ticked campaign via
 * POST /api/public/register-interest.
 */
export default function InterestSummaryModal({ campaigns, onProceed, onCancel, isSubmitting = false, error = null }: Props) {
  return (
    <Modal onClose={isSubmitting ? undefined : onCancel}>
      <div data-ti="components/registerInterest/InterestSummaryModal.tsx" className="w-full max-w-sm rounded-xl border-2 border-gray-800 bg-white p-6 shadow-2xl dark:border-gray-600 dark:bg-gray-900">
        <p className="text-base font-semibold text-gray-900 dark:text-gray-100">
          You have selected the following campaign(s)
        </p>

        <div className="mt-2 max-h-48 space-y-1 overflow-y-auto pl-4 text-sm text-gray-700 dark:text-gray-300">
          {campaigns.map(c => (
            <div key={c.id}>{formatCampaignLine(c)}</div>
          ))}
        </div>

        <p className="mt-4 text-base font-semibold text-gray-900 dark:text-gray-100">
          By selecting Proceed below you agree to being contacted by the leader(s) of the selected campaigns
        </p>

        {error && (
          <p className="mt-3 rounded-md border border-red-200 bg-red-50 p-2 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
            {error}
          </p>
        )}

        <div className="mt-6 flex gap-3">
          <button
            onClick={onProceed}
            disabled={isSubmitting}
            className="flex-1 rounded-md bg-blue-600 px-4 py-3 text-base font-bold text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
          >
            {isSubmitting ? 'Submitting…' : 'Proceed'}
          </button>
          <button
            onClick={onCancel}
            disabled={isSubmitting}
            className="flex-1 rounded-md bg-gray-200 px-4 py-3 text-base font-bold text-gray-700 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600 disabled:opacity-50 disabled:cursor-not-allowed border-2 border-gray-800 dark:border-gray-600"
          >
            Cancel
          </button>
        </div>
      </div>
    </Modal>
  );
}

components/registerInterest/RegisterInte:
'use client';

/**
 * Register Interest screen — tick campaigns for a fortnight and register
 * interest ("Yes I'm In" / "Tell Me More"). Two entry points render this
 * exact component:
 *  - app/public/register-interest/page.tsx — the public, unauthenticated
 *    page for the *current* fortnight. Not listed in middleware's
 *    PROTECTED_PREFIXES, so it's open by default (see middleware.ts).
 *  - app/admin/register-interest/page.tsx — an admin-only preview of the
 *    *next* fortnight (the two weeks starting right after the current
 *    period ends), passing `nextPeriod`. Everything else — copy, layout,
 *    validation, submission — is identical; only the fetched date window
 *    differs (see the `period=next` handling in the API route below).
 *
 * Data comes from GET /api/public/register-interest; submissions go
 * through POST on the same route (service role — see that route for why
 * campaign_interest can't be written via the browser client here, unlike
 * the admin-only /admin/registered-interest listing screen).
 *
 * Deliberately does NOT use MobileLayout — that component resolves the
 * signed-in user's admin status and assumes a logged-in session, which the
 * public entry point doesn't have. The admin entry point wraps this in its
 * own access-gated MobileLayout shell around this component instead of
 * baking that into this component, so both callers render identical content.
 */
import { useEffect, useState } from 'react';
import LoadingSpinner from '@/components/LoadingSpinner';
import { getErrorMessage } from '@/lib/errorUtils';
import { isValidMobile, isValidEmail } from '@/lib/validation';
import type { AriseCampaign } from '@/lib/ariseLayout';
import type { RegisterInterestGetResponse } from '@/app/api/public/register-interest/route';
import CampaignCheckboxList from './CampaignCheckboxList';
import InterestSummaryModal from './InterestSummaryModal';

type CampaignInterestType = 'in' | 'more';

interface Props {
  /** When true, fetches the fortnight starting right after the current one instead of the current fortnight. */
  nextPeriod?: boolean;
}

export default function RegisterInterestClient({ nextPeriod = false }: Props = {}) {
  const [firstName, setFirstName] = useState('');
  const [mobileNumber, setMobileNumber] = useState('');
  const [email, setEmail] = useState('');

  const [allCampaigns, setAllCampaigns] = useState<AriseCampaign[]>([]);
  const [isLoadingCampaigns, setIsLoadingCampaigns] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const url = nextPeriod ? '/api/public/register-interest?period=next' : '/api/public/register-interest';
        const res = await fetch(url);
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load campaign data');
        if (cancelled) return;
        setAllCampaigns((json as RegisterInterestGetResponse).campaigns);
      } catch (err) {
        if (!cancelled) setLoadError(getErrorMessage(err, 'Failed to load campaign data'));
      } finally {
        if (!cancelled) setIsLoadingCampaigns(false);
      }
    })();

    return () => { cancelled = true; };
  }, [nextPeriod]);

  const [checkedIds, setCheckedIds] = useState<Set<string>>(new Set());
  const toggleChecked = (id: string) => {
    setCheckedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };
  // Preserves the campaigns' existing date/state/place/time sort order for
  // the confirmation popup's list.
  const checkedCampaigns = allCampaigns.filter(c => checkedIds.has(c.id));

  const [popupAction, setPopupAction] = useState<CampaignInterestType | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [isSubmittingInterest, setIsSubmittingInterest] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const openPopup = (action: CampaignInterestType) => {
    setValidationError(null);
    if (checkedIds.size === 0) {
      setValidationError('Tick at least one campaign below first.');
      return;
    }
    if (!firstName.trim()) {
      setValidationError('Please enter your first name.');
      return;
    }
    const mobileTrimmed = mobileNumber.trim();
    const emailTrimmed = email.trim();
    if (!mobileTrimmed && !emailTrimmed) {
      setValidationError('Please enter your mobile number or email address.');
      return;
    }
    if (!isValidMobile(mobileTrimmed) && !isValidEmail(emailTrimmed)) {
      setValidationError('Please enter a valid mobile number or email address.');
      return;
    }
    setPopupAction(action);
  };

  const closePopup = () => {
    setPopupAction(null);
    setSubmitError(null);
  };

  const handleProceed = async () => {
    if (!popupAction) return;
    // checkedCampaigns can go stale between opening the popup and pressing
    // Proceed — re-check rather than silently "succeeding" with nothing sent.
    if (checkedCampaigns.length === 0) {
      setSubmitError('The selected campaign(s) are no longer available — please close this and tick again.');
      return;
    }
    setIsSubmittingInterest(true);
    setSubmitError(null);
    try {
      const res = await fetch('/api/public/register-interest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          firstName: firstName.trim(),
          mobile: mobileNumber.trim(),
          email: email.trim(),
          interestType: popupAction,
          campaignIds: checkedCampaigns.map(c => c.id),
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Failed to register your interest');
      setCheckedIds(new Set());
      setPopupAction(null);
    } catch (err: unknown) {
      setSubmitError(getErrorMessage(err, 'Failed to register your interest'));
    } finally {
      setIsSubmittingInterest(false);
    }
  };

  return (
    <div data-ti="components/registerInterest/RegisterInterestClient.tsx" className="flex h-dvh flex-col p-4">
      <div className="mb-3">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">Register my Campaign Interest</h1>
        <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
          All Upcoming AFJ Campaigns for this fortnight are listed below. To <strong className="font-bold">join a campaign</strong>, or to <strong className="font-bold">get more information</strong> please enter your first name and either a mobile number or email address below, click on the campaign that you are interested in and then click on the green or orange button at the bottom of the page.
        </p>
      </div>

      <div className="mb-3 flex flex-wrap items-center gap-2">
        <label className="flex-1 min-w-[8rem]">
          <span className="sr-only">First name</span>
          <input
            type="text"
            value={firstName}
            onChange={e => setFirstName(e.target.value)}
            placeholder="First name"
            className="w-full rounded-md border-2 border-gray-800 bg-white px-3 py-2 text-sm text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100 dark:placeholder:text-gray-500"
          />
        </label>
        <label className="flex-1 min-w-[8rem]">
          <span className="sr-only">Mobile number</span>
          <input
            type="tel"
            value={mobileNumber}
            onChange={e => setMobileNumber(e.target.value)}
            placeholder="Mobile number"
            className="w-full rounded-md border-2 border-gray-800 bg-white px-3 py-2 text-sm text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100 dark:placeholder:text-gray-500"
          />
        </label>
      </div>

      <div className="mb-3 flex flex-wrap items-center gap-2">
        <label className="flex-1 min-w-[8rem]">
          <span className="sr-only">Email address</span>
          <input
            type="email"
            value={email}
            onChange={e => setEmail(e.target.value)}
            placeholder="Email address"
            className="w-full rounded-md border-2 border-gray-800 bg-white px-3 py-2 text-sm text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100 dark:placeholder:text-gray-500"
          />
        </label>
      </div>

      {loadError && (
        <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
          {loadError}
        </div>
      )}
      {validationError && (
        <div className="mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-900/20 dark:text-red-200">
          {validationError}
        </div>
      )}

      {/* Campaign lines box — the list scrolls inside here so the two
          buttons below always stay visible on screen. */}
      <div className="relative flex-1 overflow-hidden rounded-lg border-2 border-gray-800 dark:border-gray-600">
        {isLoadingCampaigns && (
          <div className="absolute inset-0 z-20 flex items-center justify-center bg-white/80 dark:bg-gray-900/80">
            <LoadingSpinner text="Loading campaigns…" />
          </div>
        )}
        <div className="h-full overflow-y-auto">
          <CampaignCheckboxList campaigns={allCampaigns} checkedIds={checkedIds} onToggle={toggleChecked} />
        </div>
      </div>

      {/* Bottom action buttons — outside the campaign lines box, stretching
          the full width of the screen. */}
      <div className="mt-3 flex shrink-0 gap-2">
        <button
          type="button"
          onClick={() => openPopup('in')}
          className="flex-1 rounded-md bg-green-600 px-4 py-3 text-base font-bold text-white hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
        >
          Yes I&apos;m In
        </button>
        <button
          type="button"
          onClick={() => openPopup('more')}
          className="flex-1 rounded-md bg-orange-500 px-4 py-3 text-base font-bold text-white hover:bg-orange-600 focus:outline-none focus:ring-2 focus:ring-orange-500 focus:ring-offset-2 border-2 border-gray-800 dark:border-gray-600"
        >
          Tell Me More
        </button>
      </div>

      {popupAction && (
        <InterestSummaryModal
          campaigns={checkedCampaigns}
          onProceed={handleProceed}
          onCancel={closePopup}
          isSubmitting={isSubmittingInterest}
          error={submitError}
        />
      )}
    </div>
  );
}

