/**
 * Tests for Campaign Dates calculations
 * Run with: npm test or jest
 */

import { calculateCampaignDates, formatDateForDb, formatWeekRangeLabel, formatWeekDateRangeString, formatFortnightDateRangeString, formatShortWeekRange, formatShortDateWithOrdinal, formatLongDateWithOrdinal, getCampaignResultsNoticeDate, getFortnightDateRange, getDateRangeInclusive } from '../campaignDates';

describe('Campaign Dates Calculations', () => {
  // Helper to create a date
  const createDate = (year: number, month: number, day: number) => {
    return new Date(year, month - 1, day); // month is 0-indexed in JS
  };

  describe('Past Campaign Start Logic', () => {
    it('should return Monday of current week when today is Thursday', () => {
      // January 9, 2026 is a Friday
      const friday = createDate(2026, 1, 9);
      const dates = calculateCampaignDates(friday);
      const expected = createDate(2026, 1, 5); // Monday, Jan 5, 2026

      expect(formatDateForDb(dates.pastCampaignStart)).toBe(formatDateForDb(expected));
    });

    it('should return Monday of current week when today is Sunday', () => {
      // January 11, 2026 is a Sunday
      const sunday = createDate(2026, 1, 11);
      const dates = calculateCampaignDates(sunday);
      const expected = createDate(2026, 1, 5); // Monday, Jan 5, 2026

      expect(formatDateForDb(dates.pastCampaignStart)).toBe(formatDateForDb(expected));
    });

    it('should return Monday of previous week when today is Monday', () => {
      // January 12, 2026 is a Monday
      const monday = createDate(2026, 1, 12);
      const dates = calculateCampaignDates(monday);
      const expected = createDate(2026, 1, 5); // Previous Monday, Jan 5, 2026

      expect(formatDateForDb(dates.pastCampaignStart)).toBe(formatDateForDb(expected));
    });

    it('should return Monday of previous week when today is Wednesday', () => {
      // January 14, 2026 is a Wednesday
      const wednesday = createDate(2026, 1, 14);
      const dates = calculateCampaignDates(wednesday);
      const expected = createDate(2026, 1, 5); // Previous Monday, Jan 5, 2026

      expect(formatDateForDb(dates.pastCampaignStart)).toBe(formatDateForDb(expected));
    });
  });

  describe('Upcoming Campaign Start Logic', () => {
    it('should return Monday of current week when today is Monday', () => {
      // January 12, 2026 is a Monday
      const monday = createDate(2026, 1, 12);
      const dates = calculateCampaignDates(monday);
      const expected = createDate(2026, 1, 12); // Same Monday

      expect(formatDateForDb(dates.upcomingCampaignStart)).toBe(formatDateForDb(expected));
    });

    it('should return Monday of current week when today is Wednesday', () => {
      // January 14, 2026 is a Wednesday
      const wednesday = createDate(2026, 1, 14);
      const dates = calculateCampaignDates(wednesday);
      const expected = createDate(2026, 1, 12); // Monday of same week

      expect(formatDateForDb(dates.upcomingCampaignStart)).toBe(formatDateForDb(expected));
    });

    it('should return Monday of current week when today is Thursday', () => {
      // January 8, 2026 is a Thursday
      const thursday = createDate(2026, 1, 8);
      const dates = calculateCampaignDates(thursday);
      const expected = createDate(2026, 1, 5); // Monday of same week

      expect(formatDateForDb(dates.upcomingCampaignStart)).toBe(formatDateForDb(expected));
    });

    it('should return Monday of next week when today is Sunday', () => {
      // January 11, 2026 is a Sunday
      const sunday = createDate(2026, 1, 11);
      const dates = calculateCampaignDates(sunday);
      const expected = createDate(2026, 1, 12); // Next Monday

      expect(formatDateForDb(dates.upcomingCampaignStart)).toBe(formatDateForDb(expected));
    });
  });

  describe('Second Week Start Logic', () => {
    it('should be 7 days after Upcoming Campaign Start', () => {
      // January 12, 2026 is a Monday
      const monday = createDate(2026, 1, 12);
      const dates = calculateCampaignDates(monday);
      const expected = createDate(2026, 1, 19); // Monday, Jan 19, 2026

      expect(formatDateForDb(dates.secondWeekStart)).toBe(formatDateForDb(expected));
    });

    it('should maintain 7-day gap from Thursday', () => {
      // January 8, 2026 is a Thursday
      const thursday = createDate(2026, 1, 8);
      const dates = calculateCampaignDates(thursday);
      const expectedUpcoming = createDate(2026, 1, 5); // Monday of same week
      const expectedSecond = createDate(2026, 1, 12); // Monday after that

      expect(formatDateForDb(dates.upcomingCampaignStart)).toBe(formatDateForDb(expectedUpcoming));
      expect(formatDateForDb(dates.secondWeekStart)).toBe(formatDateForDb(expectedSecond));
    });
  });

  describe('formatWeekRangeLabel', () => {
    it('formats a week within a single month as "D Mon - D Mon", with no year', () => {
      // Monday, August 3, 2026 -> Sunday, August 9, 2026
      const monday = createDate(2026, 8, 3);
      expect(formatWeekRangeLabel(monday)).toBe('3 Aug - 9 Aug');
    });

    it('formats a week spanning two months as "D Mon - D Mon", with no year', () => {
      // Monday, June 29, 2026 -> Sunday, July 5, 2026
      const monday = createDate(2026, 6, 29);
      expect(formatWeekRangeLabel(monday)).toBe('29 Jun - 5 Jul');
    });

    it('formats a week spanning two years as "D Mon - D Mon", with no year', () => {
      // Monday, December 28, 2026 -> Sunday, January 3, 2027
      const monday = createDate(2026, 12, 28);
      expect(formatWeekRangeLabel(monday)).toBe('28 Dec - 3 Jan');
    });
  });

  describe('formatWeekDateRangeString', () => {
    it('formats a week within a single month as "Mon Dth Mon YY - Sun Dth Mon YY"', () => {
      // Monday, August 10, 2026 -> Sunday, August 16, 2026
      const monday = createDate(2026, 8, 10);
      expect(formatWeekDateRangeString(monday)).toBe('Mon 10th Aug 26 - Sun 16th Aug 26');
    });

    it('formats a week spanning two months, each with its own month and year', () => {
      // Monday, June 29, 2026 -> Sunday, July 5, 2026
      const monday = createDate(2026, 6, 29);
      expect(formatWeekDateRangeString(monday)).toBe('Mon 29th Jun 26 - Sun 5th Jul 26');
    });

    it('formats a week spanning two years, each with its own year', () => {
      // Monday, December 28, 2026 -> Sunday, January 3, 2027
      const monday = createDate(2026, 12, 28);
      expect(formatWeekDateRangeString(monday)).toBe('Mon 28th Dec 26 - Sun 3rd Jan 27');
    });

    it('uses the correct ordinal suffix for each day (1st, 2nd, 3rd, 11th-13th, 21st...)', () => {
      expect(formatWeekDateRangeString(createDate(2026, 3, 1))).toBe('Mon 1st Mar 26 - Sun 7th Mar 26');
      expect(formatWeekDateRangeString(createDate(2026, 6, 2))).toBe('Mon 2nd Jun 26 - Sun 8th Jun 26');
      expect(formatWeekDateRangeString(createDate(2026, 12, 21))).toBe('Mon 21st Dec 26 - Sun 27th Dec 26');
    });
  });

  describe('formatFortnightDateRangeString', () => {
    it('formats a fortnight within a single month as "Mon Dth Mon YY - Sun Dth Mon YY"', () => {
      // Monday, August 10, 2026 -> Sunday, August 23, 2026 (13 days later)
      const monday = createDate(2026, 8, 10);
      expect(formatFortnightDateRangeString(monday)).toBe('Mon 10th Aug 26 - Sun 23rd Aug 26');
    });

    it('formats a fortnight spanning two months, each with its own month and year', () => {
      // Monday, June 29, 2026 -> Sunday, July 12, 2026
      const monday = createDate(2026, 6, 29);
      expect(formatFortnightDateRangeString(monday)).toBe('Mon 29th Jun 26 - Sun 12th Jul 26');
    });

    it('formats a fortnight spanning two years, each with its own year', () => {
      // Monday, December 21, 2026 -> Sunday, January 3, 2027
      const monday = createDate(2026, 12, 21);
      expect(formatFortnightDateRangeString(monday)).toBe('Mon 21st Dec 26 - Sun 3rd Jan 27');
    });
  });

  describe('formatShortDateWithOrdinal', () => {
    it('formats a date as "Ddd Dth Mon" — short day name, ordinal day, short month, no year', () => {
      // Wednesday, August 12, 2026
      expect(formatShortDateWithOrdinal(createDate(2026, 8, 12))).toBe('Wed 12th Aug');
    });

    it('uses the correct ordinal suffix for each day (1st, 2nd, 3rd, 11th-13th, 21st...)', () => {
      expect(formatShortDateWithOrdinal(createDate(2026, 3, 1))).toBe('Sun 1st Mar');
      expect(formatShortDateWithOrdinal(createDate(2026, 6, 2))).toBe('Tue 2nd Jun');
      expect(formatShortDateWithOrdinal(createDate(2026, 12, 21))).toBe('Mon 21st Dec');
    });
  });

  describe('getCampaignResultsNoticeDate', () => {
    it('returns the Sunday a week after the displayed week is deleted', () => {
      // Displayed week Mon 28 Sep - Sun 4 Oct 2026: on screen until (and deleted on)
      // Sunday 11 Oct, so the notice names the end of the following week, Sunday 18 Oct.
      expect(formatDateForDb(getCampaignResultsNoticeDate(createDate(2026, 9, 28)))).toBe('2026-10-18');
    });

    it('crosses a year boundary', () => {
      // Displayed week 14-20 Dec 2026 -> Sunday 3 Jan 2027
      expect(formatDateForDb(getCampaignResultsNoticeDate(createDate(2026, 12, 14)))).toBe('2027-01-03');
    });

    it('does not mutate the date it is given', () => {
      const monday = createDate(2026, 9, 28);
      getCampaignResultsNoticeDate(monday);
      expect(formatDateForDb(monday)).toBe('2026-09-28');
    });
  });

  describe('formatLongDateWithOrdinal', () => {
    it('formats a date as "Dddd Dth Mon YYYY" — full day name, ordinal day, short month, full year', () => {
      expect(formatLongDateWithOrdinal(createDate(2026, 10, 11))).toBe('Sunday 11th Oct 2026');
    });

    it('uses the correct ordinal suffix for each day', () => {
      expect(formatLongDateWithOrdinal(createDate(2026, 3, 1))).toBe('Sunday 1st Mar 2026');
      expect(formatLongDateWithOrdinal(createDate(2026, 6, 2))).toBe('Tuesday 2nd Jun 2026');
      expect(formatLongDateWithOrdinal(createDate(2027, 1, 3))).toBe('Sunday 3rd Jan 2027');
    });
  });

  describe('getFortnightDateRange', () => {
    it('returns 14 consecutive days starting at startDate', () => {
      const start = createDate(2026, 8, 10); // Mon 10 Aug 2026
      const dates = getFortnightDateRange(start);
      expect(dates).toHaveLength(14);
      expect(dates.map((d) => formatDateForDb(d))).toEqual([
        '2026-08-10', '2026-08-11', '2026-08-12', '2026-08-13', '2026-08-14',
        '2026-08-15', '2026-08-16', '2026-08-17', '2026-08-18', '2026-08-19',
        '2026-08-20', '2026-08-21', '2026-08-22', '2026-08-23',
      ]);
    });

    it('rolls over a month boundary correctly', () => {
      const start = createDate(2026, 8, 27); // Thu 27 Aug 2026
      const dates = getFortnightDateRange(start);
      expect(formatDateForDb(dates[0])).toBe('2026-08-27');
      expect(formatDateForDb(dates[13])).toBe('2026-09-09');
    });

    it('does not mutate the startDate argument', () => {
      const start = createDate(2026, 8, 10);
      const startCopy = new Date(start);
      getFortnightDateRange(start);
      expect(start.getTime()).toBe(startCopy.getTime());
    });
  });

  describe('getDateRangeInclusive', () => {
    it('returns every date from startDate to endDate, inclusive', () => {
      const start = createDate(2026, 8, 10); // Mon 10 Aug 2026
      const end = createDate(2026, 8, 13);   // Thu 13 Aug 2026
      const dates = getDateRangeInclusive(start, end);
      expect(dates.map((d) => formatDateForDb(d))).toEqual([
        '2026-08-10', '2026-08-11', '2026-08-12', '2026-08-13',
      ]);
    });

    it('returns a single date when startDate equals endDate', () => {
      const day = createDate(2026, 8, 10);
      const dates = getDateRangeInclusive(day, day);
      expect(dates.map((d) => formatDateForDb(d))).toEqual(['2026-08-10']);
    });

    it('rolls over a month boundary correctly', () => {
      const start = createDate(2026, 8, 30);
      const end = createDate(2026, 9, 2);
      const dates = getDateRangeInclusive(start, end);
      expect(dates.map((d) => formatDateForDb(d))).toEqual([
        '2026-08-30', '2026-08-31', '2026-09-01', '2026-09-02',
      ]);
    });

    it('returns an empty array when endDate precedes startDate', () => {
      const start = createDate(2026, 8, 10);
      const end = createDate(2026, 8, 9);
      expect(getDateRangeInclusive(start, end)).toEqual([]);
    });

    it('does not mutate the startDate or endDate arguments', () => {
      const start = createDate(2026, 8, 10);
      const end = createDate(2026, 8, 13);
      const startCopy = new Date(start);
      const endCopy = new Date(end);
      getDateRangeInclusive(start, end);
      expect(start.getTime()).toBe(startCopy.getTime());
      expect(end.getTime()).toBe(endCopy.getTime());
    });
  });
});

describe('formatShortWeekRange', () => {
  it('collapses a week inside one month', () => {
    expect(formatShortWeekRange(new Date(2026, 9, 19))).toBe('19–25 Oct');
  });

  it('shows both months when the week spans two', () => {
    expect(formatShortWeekRange(new Date(2026, 9, 26))).toBe('26 Oct – 1 Nov');
  });
});

