import { describe, it, expect } from 'vitest';
import {
  normalizeLocationForMatch,
  normalizeLeaderForMatch,
  matchPlace,
  matchLeader,
  deriveCampaignReportFields,
  extractStateHint,
  locationKey,
  type LocationAliasRef,
  type PlaceRef,
  type LeaderRef,
} from '../campaignReportMatcher';

const PLACES: PlaceRef[] = [
  { state: 'NSW', place: 'Orange 1' },
  { state: 'NSW', place: 'Orange 2' },
  { state: 'NSW', place: 'Parramatta' },
  { state: 'NSW', place: 'Cronulla' },
  { state: 'VIC', place: 'Narre Warren' },
  { state: 'VIC', place: 'Dandenong' },
  { state: 'SA', place: 'Mt Gambier' },
  { state: 'QLD', place: 'Charters Twrs' },
  { state: 'WA', place: 'Perth CBD' },
  { state: 'WA', place: 'Armadale' },
  { state: 'VIC', place: 'Armadale' },
];

const LEADERS: LeaderRef[] = [
  { state: 'VIC', leader: 'Linda' },
  { state: 'NSW', leader: 'Steve G' },
  { state: 'SA', leader: 'Maria' },
  { state: 'VIC', leader: 'Michael' },
  { state: 'SA', leader: 'Michael' },
  { state: 'VIC', leader: 'Chris' },
  { state: 'NSW', leader: 'Chris' },
];

describe('normalizeLocationForMatch', () => {
  it('strips a trailing state abbreviation', () => {
    expect(normalizeLocationForMatch('Orange nsw')).toBe('Orange');
  });

  it('strips a trailing full state name', () => {
    expect(normalizeLocationForMatch('Pakenham Victoria')).toBe('Pakenham');
  });

  it('strips a parenthetical state annotation', () => {
    expect(normalizeLocationForMatch('Narre Warren (Vic)')).toBe('Narre Warren');
  });

  it('turns a stray period between letters into a space', () => {
    expect(normalizeLocationForMatch('Mt.Gambier')).toBe('Mt Gambier');
  });

  it('strips a trailing qualifier word', () => {
    expect(normalizeLocationForMatch('Werribee Station')).toBe('Werribee');
    expect(normalizeLocationForMatch('Frankston update')).toBe('Frankston');
  });

  it('strips a bracketed aside', () => {
    expect(normalizeLocationForMatch('Tewantin [main street]')).toBe('Tewantin');
  });

  it('returns an empty string for null/undefined/empty input', () => {
    expect(normalizeLocationForMatch(null)).toBe('');
    expect(normalizeLocationForMatch(undefined)).toBe('');
    expect(normalizeLocationForMatch('')).toBe('');
  });
});

describe('normalizeLeaderForMatch', () => {
  it('strips a trailing team-size annotation', () => {
    expect(normalizeLeaderForMatch('Bee Bee +2')).toBe('Bee Bee');
    expect(normalizeLeaderForMatch('Andrew C (+ 3)')).toBe('Andrew C');
    expect(normalizeLeaderForMatch('Alan , 3')).toBe('Alan');
  });

  it('strips a trailing co-leader mention', () => {
    expect(normalizeLeaderForMatch('Michael & Lanre')).toBe('Michael');
    expect(normalizeLeaderForMatch('Ron and Carolyn')).toBe('Ron');
  });

  it('returns an empty string for null/undefined/empty input', () => {
    expect(normalizeLeaderForMatch(null)).toBe('');
    expect(normalizeLeaderForMatch(undefined)).toBe('');
  });
});

describe('matchPlace', () => {
  it('matches exactly after normalization', () => {
    expect(matchPlace('Dandenong', PLACES)).toEqual([{ state: 'VIC', place: 'Dandenong' }]);
  });

  it('matches via a verified alias (typo/abbreviation correction)', () => {
    expect(matchPlace('Mount Gambier', PLACES)).toEqual([{ state: 'SA', place: 'Mt Gambier' }]);
    expect(matchPlace('Charters Towers', PLACES)).toEqual([{ state: 'QLD', place: 'Charters Twrs' }]);
  });

  it('forward-prefix matches a site-numbered place', () => {
    expect(matchPlace('Orange nsw', PLACES)).toEqual([
      { state: 'NSW', place: 'Orange 1' },
      { state: 'NSW', place: 'Orange 2' },
    ]);
  });

  it('reverse-prefix matches a place with an extra trailing descriptor', () => {
    expect(matchPlace('Perth CBD1', PLACES)).toEqual([{ state: 'WA', place: 'Perth CBD' }]);
  });

  it('returns every state a place name is ambiguous across', () => {
    const result = matchPlace('Armadale', PLACES);
    expect(result).toHaveLength(2);
    expect(result.map((r) => r.state).sort()).toEqual(['VIC', 'WA']);
  });

  it('returns an empty array when nothing matches (never guesses)', () => {
    expect(matchPlace('LifeSource Foodcare', PLACES)).toEqual([]);
  });
});

describe('matchLeader', () => {
  it('matches exactly after normalization', () => {
    expect(matchLeader('Steve G', LEADERS)).toEqual([{ state: 'NSW', leader: 'Steve G' }]);
  });

  it('falls back to a first-name-only match', () => {
    expect(matchLeader('Maria McCully', LEADERS)).toEqual([{ state: 'SA', leader: 'Maria' }]);
    expect(matchLeader('Linda H +2', LEADERS)).toEqual([{ state: 'VIC', leader: 'Linda' }]);
  });

  it('returns every state a first name is ambiguous across', () => {
    const result = matchLeader('Michael', LEADERS);
    expect(result).toHaveLength(2);
    expect(result.map((r) => r.state).sort()).toEqual(['SA', 'VIC']);
  });

  it('returns an empty array when nothing matches (never guesses)', () => {
    expect(matchLeader('Holy Spirit & David Bishop', LEADERS)).toEqual([]);
  });
});

describe('deriveCampaignReportFields', () => {
  it('resolves state, location, and leader when the place uniquely determines the state', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'Dandenong', leader_raw: 'Brent' },
      PLACES,
      LEADERS,
    );
    expect(result).toEqual({ state: 'VIC', location: 'Dandenong', leader: null }); // 'Brent' isn't in the fixture leader list
  });

  it('uses the leader to disambiguate a place name that exists in multiple states', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'Armadale', leader_raw: 'Chris' },
      PLACES,
      LEADERS,
    );
    // 'Armadale' is VIC or WA; 'Chris' is VIC or NSW — the only state in both is VIC.
    expect(result).toEqual({ state: 'VIC', location: 'Armadale', leader: 'Chris' });
  });

  it('resolves state from the leader alone when the place has no match', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'LifeSource Foodcare', leader_raw: 'Steve G' },
      PLACES,
      LEADERS,
    );
    expect(result).toEqual({ state: 'NSW', location: null, leader: 'Steve G' });
  });

  it('leaves location null when the state resolves but the candidates are different locations (Orange 1 / Orange 2 with no shared location)', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'Orange nsw', leader_raw: 'Steve G' },
      PLACES,
      LEADERS,
    );
    expect(result).toEqual({ state: 'NSW', location: null, leader: 'Steve G' });
  });

  it('returns all-null when neither place nor leader resolves a state (never guesses)', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'Train from Sydney to Melbourne', leader_raw: 'Cancelled' },
      PLACES,
      LEADERS,
    );
    expect(result).toEqual({ state: null, location: null, leader: null });
  });

  it('trusts a unique place match over a non-corroborating leader, leaving leader unresolved', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'Cronulla', leader_raw: 'Linda' }, // Cronulla is NSW-only; Linda only matches in VIC
      PLACES,
      LEADERS,
    );
    expect(result).toEqual({ state: 'NSW', location: 'Cronulla', leader: null });
  });

  it('returns all-null when an ambiguous place and an ambiguous leader share no common state', () => {
    const result = deriveCampaignReportFields(
      { location_raw: 'Armadale', leader_raw: 'Steve G' }, // Armadale is VIC/WA; Steve G is NSW-only
      PLACES,
      LEADERS,
    );
    expect(result).toEqual({ state: null, location: null, leader: null });
  });
});

describe('extractStateHint', () => {
  it.each([
    ['Brighton SA', 'SA'],
    ['Ayr  Nth Qld', 'QLD'],
    ['Hoppers Crossing Vic', 'VIC'],
    ['Queanbeyan, NSW', 'NSW'],
    ['Midwest WA', 'WA'],
    ['Foo (Tasmania)', 'TAS'],
  ])('reads the typed state from %s', (raw, state) => {
    expect(extractStateHint(raw)).toBe(state);
  });

  it('returns null when no state is typed, or the letters are only part of a word', () => {
    expect(extractStateHint('Dandenong')).toBeNull();
    expect(extractStateHint('Pisa')).toBeNull();
    expect(extractStateHint(null)).toBeNull();
  });
});

describe('deriveCampaignReportFields — a typed state is authoritative', () => {
  const places: PlaceRef[] = [...PLACES, { state: 'NSW', place: 'Brighton Le S' }, { state: 'ACT', place: 'Queanbeyan' }, { state: 'NSW', place: 'Queanbeyan' }];
  const leaders: LeaderRef[] = [...LEADERS, { state: 'NSW', leader: 'Anne Mills' }];

  it('does not match a same-named place in another state', () => {
    const r = deriveCampaignReportFields({ location_raw: 'Brighton SA', leader_raw: 'Anne Mills' }, places, leaders);
    expect(r.state).toBe('SA');
    expect(r.location).toBeNull();
  });

  it('is not overridden by the leader\'s usual state', () => {
    const r = deriveCampaignReportFields({ location_raw: 'Aberfoyle Park SA', leader_raw: 'Anne Mills' }, places, leaders);
    expect(r).toEqual({ state: 'SA', location: null, leader: null });
  });

  it('still finds the place within the typed state', () => {
    const r = deriveCampaignReportFields({ location_raw: 'Queanbeyan, NSW', leader_raw: null }, places, leaders);
    expect(r).toEqual({ state: 'NSW', location: 'Queanbeyan', leader: null });
  });
});

describe('deriveCampaignReportFields — confirmed aliases', () => {
  const aliases = new Map<string, LocationAliasRef>([
    [locationKey('Rundle Mall - Adelaide'), { location_key: locationKey('Rundle Mall - Adelaide'), state: 'SA', location: 'Adelaide CBD' }],
  ]);

  it('uses the alias over any heuristic, and still matches the leader within that state', () => {
    const r = deriveCampaignReportFields({ location_raw: 'Rundle Mall - Adelaide', leader_raw: 'Maria' }, PLACES, LEADERS, aliases);
    expect(r).toEqual({ state: 'SA', location: 'Adelaide CBD', leader: 'Maria' });
  });

  it('keeps a state-only alias as state-only', () => {
    const only = new Map([['herberton', { location_key: 'herberton', state: 'QLD', location: null }]]);
    expect(deriveCampaignReportFields({ location_raw: 'Herberton', leader_raw: null }, PLACES, LEADERS, only))
      .toEqual({ state: 'QLD', location: null, leader: null });
  });
});

describe('deriveCampaignReportFields — maps to the physical location, not the place label', () => {
  const places: PlaceRef[] = [
    { state: 'NSW', place: 'Orange 1', location: 'Orange' },
    { state: 'NSW', place: 'Orange 2', location: 'Orange' },
    { state: 'WA', place: 'Perth CBD 1', location: 'Perth CBD' },
    { state: 'WA', place: 'Perth CBD 2', location: 'Perth CBD' },
    { state: 'WA', place: 'Perth Metro', location: 'Perth CBD' },
    { state: 'NSW', place: 'Pt Macquarie', location: 'Port Macquarie' },
    { state: 'NSW', place: 'Campbelltown', location: 'Sydney' },
  ];

  it('two numbered sites at one location resolve to that location instead of being ambiguous', () => {
    expect(deriveCampaignReportFields({ location_raw: 'Orange', leader_raw: null }, places, []))
      .toEqual({ state: 'NSW', location: 'Orange', leader: null });
  });

  it('matches typed text against the location name or any place label, and answers with the location', () => {
    expect(deriveCampaignReportFields({ location_raw: 'Perth CBD1', leader_raw: null }, places, []).location).toBe('Perth CBD');
    expect(deriveCampaignReportFields({ location_raw: 'Port Macquarie', leader_raw: null }, places, []).location).toBe('Port Macquarie');
    expect(deriveCampaignReportFields({ location_raw: 'Pt Macquarie', leader_raw: null }, places, []).location).toBe('Port Macquarie');
  });

  it('a place whose location is elsewhere resolves to that location (place Campbelltown -> location Sydney)', () => {
    expect(deriveCampaignReportFields({ location_raw: 'Campbelltown', leader_raw: null }, places, []))
      .toEqual({ state: 'NSW', location: 'Sydney', leader: null });
  });

  it('falls back to the place name when a row has no location text', () => {
    expect(deriveCampaignReportFields({ location_raw: 'Lone', leader_raw: null }, [{ state: 'VIC', place: 'Lone', location: null }], []))
      .toEqual({ state: 'VIC', location: 'Lone', leader: null });
  });
});

import { describe, it, expect } from 'vitest';
import {
  parseTallyValue,
  parseCampaignDate,
  normalizeCampaignReportRow,
} from '../campaignReportParser';

describe('parseTallyValue', () => {
  it('passes a clean number straight through', () => {
    expect(parseTallyValue(6)).toEqual({ value: 6, raw: null });
    expect(parseTallyValue(0)).toEqual({ value: 0, raw: null });
  });

  it('treats null/undefined/empty as no data', () => {
    expect(parseTallyValue(null)).toEqual({ value: null, raw: null });
    expect(parseTallyValue(undefined)).toEqual({ value: null, raw: null });
    expect(parseTallyValue('  ')).toEqual({ value: null, raw: null });
  });

  it('maps known zero-words to 0, keeping the original text', () => {
    expect(parseTallyValue('Nil')).toEqual({ value: 0, raw: 'Nil' });
    expect(parseTallyValue('None')).toEqual({ value: 0, raw: 'None' });
    expect(parseTallyValue('—')).toEqual({ value: 0, raw: '—' });
    expect(parseTallyValue('O')).toEqual({ value: 0, raw: 'O' }); // letter-O typo for zero, seen in the real sheet
  });

  it('extracts a leading number from a note, keeping the full text', () => {
    expect(parseTallyValue('10(1 with 5 persons, 1 with 3 and 1 with 2)')).toEqual({
      value: 10,
      raw: '10(1 with 5 persons, 1 with 3 and 1 with 2)',
    });
    expect(parseTallyValue('3 (incl 1 affirmation) ')).toEqual({ value: 3, raw: '3 (incl 1 affirmation)' });
  });

  it('yields null value for pure narrative with no leading digit, but preserves it', () => {
    const note = 'Gave out 3 new testaments, 4 books of eternity.';
    expect(parseTallyValue(note)).toEqual({ value: null, raw: note });
  });
});

const submittedAt = (iso: string) => new Date(iso);

describe('parseCampaignDate', () => {
  it('accepts a clean native Date', () => {
    expect(parseCampaignDate(new Date(2021, 8, 2), submittedAt('2021-09-02T18:17:36Z'))).toEqual({
      date: '2021-09-02',
      raw: null,
      needsReview: false,
    });
  });

  it('parses dot-separated D.M.Y', () => {
    expect(parseCampaignDate('25.9.21', submittedAt('2021-09-25T12:00:00Z'))).toEqual({
      date: '2021-09-25',
      raw: '25.9.21',
      needsReview: false,
    });
  });

  it('parses dot-separated Y.M.D', () => {
    expect(parseCampaignDate('2024.04.06', submittedAt('2024-04-06T12:00:00Z'))).toEqual({
      date: '2024-04-06',
      raw: '2024.04.06',
      needsReview: false,
    });
  });

  it('parses "D Month YYYY"', () => {
    expect(parseCampaignDate('18th September 2021', submittedAt('2021-09-18T12:00:00Z'))).toEqual({
      date: '2021-09-18',
      raw: '18th September 2021',
      needsReview: false,
    });
  });

  it('parses "Month D" with the year inferred from the submission date', () => {
    expect(parseCampaignDate('August 7th', submittedAt('2026-08-08T12:00:00Z'))).toEqual({
      date: '2026-08-07',
      raw: 'August 7th',
      needsReview: false,
    });
  });

  it('strips a day-of-week prefix', () => {
    expect(parseCampaignDate('Saturday 23rd October 2021', submittedAt('2021-10-25T12:00:00Z'))).toEqual({
      date: '2021-10-23',
      raw: 'Saturday 23rd October 2021',
      needsReview: false,
    });
  });

  it('takes the first date out of a multi-date entry, preserving the full original text', () => {
    expect(parseCampaignDate('9/9/21 & 10/9/21', submittedAt('2021-09-10T12:00:00Z'))).toEqual({
      date: '2021-09-09',
      raw: '9/9/21 & 10/9/21',
      needsReview: false,
    });
  });

  it('rolls a yearless month back a year across a Dec/Jan reporting gap', () => {
    // Campaign run in December, report filed the following January.
    expect(parseCampaignDate('28th December', submittedAt('2022-01-03T12:00:00Z'))).toEqual({
      date: '2021-12-28',
      raw: '28th December',
      needsReview: false,
    });
  });

  it('parses an unambiguous 8-digit YYYYMMDD typed as a plain number', () => {
    expect(parseCampaignDate(20240914, submittedAt('2024-09-14T18:39:23Z'))).toEqual({
      date: '2024-09-14',
      raw: '20240914',
      needsReview: false,
    });
  });

  it('flags a short, ambiguous digit string instead of guessing', () => {
    // Real example: "50222" is ambiguous (could be several things); the sheet's
    // own submission date makes "5/2/22" plausible but that's a guess, not a fact.
    const result = parseCampaignDate(50222, submittedAt('2022-02-05T16:45:15Z'));
    expect(result.date).toBeNull();
    expect(result.needsReview).toBe(true);
    expect(result.raw).toBe('50222');
  });

  it('flags a corrupted Excel serial (year wildly out of range)', () => {
    const wild = new Date(6702324, 0, 1); // outside MIN_YEAR..MAX_YEAR
    const result = parseCampaignDate(wild, submittedAt('2024-01-01T12:00:00Z'));
    expect(result.date).toBeNull();
    expect(result.needsReview).toBe(true);
  });

  it('flags unrecognizable free text instead of guessing', () => {
    const result = parseCampaignDate('Harvey', submittedAt('2023-06-01T12:00:00Z'));
    expect(result.date).toBeNull();
    expect(result.needsReview).toBe(true);
    expect(result.raw).toBe('Harvey');
  });

  it('treats a missing cell as no data, not a review flag', () => {
    expect(parseCampaignDate(null, submittedAt('2023-06-01T12:00:00Z'))).toEqual({
      date: null,
      raw: null,
      needsReview: false,
    });
  });

  // Real production bug (found 2026-09-01, after the initial 6,203-row load):
  // a plausible-looking parse with an explicit — but wrong — year sailed
  // through untouched because the only submission-date sanity check applied
  // to the *year-missing* code path, not to dates that already carried an
  // explicit (if mistyped) year. Reproduced here from the exact rows Peter
  // flagged in production. See BRIEF.md for the full investigation.
  describe('implausible dates relative to the submission timestamp (regression)', () => {
    it('rejects a native Excel date a leader fat-fingered a year into the future', () => {
      // Real row: submitted 2026-08-07, campaign_date came out 2027-08-08.
      const result = parseCampaignDate(new Date(2027, 7, 8), submittedAt('2026-08-07T21:12:59Z'));
      expect(result.date).toBeNull();
      expect(result.needsReview).toBe(true);
      expect(result.raw).toBe('2027-08-08'); // no original text for a native Date cell — falls back to the parsed ISO value
    });

    it('rejects a dot-format date with a typo\'d year a decade off', () => {
      // Real row: "14.6.35" submitted 2025-06-13 — the leader meant "14.6.25".
      const result = parseCampaignDate('14.6.35', submittedAt('2025-06-13T22:21:39Z'));
      expect(result.date).toBeNull();
      expect(result.needsReview).toBe(true);
      expect(result.raw).toBe('14.6.35');
    });

    it('rejects a "D Month YYYY" date exactly a year ahead of submission', () => {
      // Real row: "27th Feb 2028" submitted 2025-02-26.
      const result = parseCampaignDate('27th Feb 2028', submittedAt('2025-02-26T20:13:02Z'));
      expect(result.date).toBeNull();
      expect(result.needsReview).toBe(true);
      expect(result.raw).toBe('27th Feb 2028');
    });

    it('rejects a native Excel date several years in the past', () => {
      // Real row: submitted 2026-06-27, campaign_date came out 2020-06-26.
      const result = parseCampaignDate(new Date(2020, 5, 26), submittedAt('2026-06-27T01:43:20Z'));
      expect(result.date).toBeNull();
      expect(result.needsReview).toBe(true);
    });

    it('still accepts a genuinely late backlog report (~1 year late, correct date)', () => {
      // Real pattern seen in production: several leaders (e.g. "Sunshine")
      // batch-submitted a full year of backlogged reports at once — the
      // campaign_date is correct, just very late. Must not be flagged.
      const result = parseCampaignDate('10th May 2024', submittedAt('2025-05-09T20:13:15Z'));
      expect(result).toEqual({ date: '2024-05-10', raw: '10th May 2024', needsReview: false });
    });

    it('rejects a past date multiple years further back than any genuine backlog pattern', () => {
      const result = parseCampaignDate(new Date(2020, 5, 23), submittedAt('2026-05-23T04:54:16Z'));
      expect(result.date).toBeNull();
      expect(result.needsReview).toBe(true);
    });
  });
});

describe('normalizeCampaignReportRow', () => {
  it('normalizes a clean row end to end', () => {
    const result = normalizeCampaignReportRow({
      submittedAt: new Date('2021-09-02T18:17:36Z'),
      location: 'Glenelg SA',
      leader: 'Anne Mills',
      campaignDate: new Date(2021, 8, 2),
