  });
});

describe('parseGvizRows', () => {
  it('strips the JSONP wrapper', () => {
    expect(parseGvizRows(gviz([{ c: [] }]))).toEqual([{ c: [] }]);
  });
  it('throws on a non-ok status', () => {
