import { isRecognizedAdminStatus } from '@/lib/campaignFilter';

/**
 * What the mobile+name login must do for a matched leader instead of
 * signing them in. Admins (AD and SR) may only sign in with email + an
 * authenticator code, so the legacy form never gives them an app session:
 * an enrolled admin is sent to email sign-in, an unenrolled one must set up
 * 2FA first (the same email-confirm + MFA-setup steps every leader is offered,
 * minus the "skip"). Plain leaders return null and sign in as before —
 * unless `requireTwoFactor` is set, which gates them identically.
 * The server enforces the same rule (sessionAccessService.ts) — this only
 * decides which screen to show.
 */
export type AdminLoginGate = 'sign-in-with-email' | 'set-up-2fa';

export function getAdminLoginGate(
  match: { admin: string | null; mfaEnrolledAt: string | null },
  options: { requireTwoFactor?: boolean } = {},
): AdminLoginGate | null {
  // A plain leader is gated the same way only when they have asked for it —
  // /login?require2fa=1, reached from a screen that needs 2FA to show other
  // people's personal details (components/auth/RequireTwoFactorForMemberDetails.tsx).
  if (!isRecognizedAdminStatus(match.admin) && !options.requireTwoFactor) return null;
  return match.mfaEnrolledAt ? 'sign-in-with-email' : 'set-up-2fa';
}

lib/adminRouteGuard.ts:
/**
 * Shared front door for admin-only API routes that need the standard checks:
 * same-origin, service role configured, Bearer token, and a full admin (AD)
 * signed in with 2FA (`verifyAdminCaller`). Returns the caller on success, or
 * the ready-made error response to send back.
 */
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { enforceOrigin } from '@/lib/corsUtils';
import { verifyAdminCaller } from '@/lib/services/adminCallerService';

export type AdminRequestResult =
  | { ok: true; userId: string; label: string }
  | { ok: false; response: NextResponse };

export async function authorizeAdminRequest(request: NextRequest, logTag: string): Promise<AdminRequestResult> {
  const corsBlock = enforceOrigin(request);
  if (corsBlock) return { ok: false, response: corsBlock };

  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error(`[${logTag}] SUPABASE_SERVICE_ROLE_KEY is not set`);
    return { ok: false, response: NextResponse.json({ error: 'Internal server error' }, { status: 500 }) };
  }

  const authHeader = request.headers.get('authorization');
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;
  if (!token) return { ok: false, response: NextResponse.json({ error: 'Unauthorized' }, { status: 401 }) };

  const caller = await verifyAdminCaller(supabaseAdmin, token);
  if (!caller.ok) return { ok: false, response: NextResponse.json({ error: caller.error }, { status: caller.status }) };
  return { ok: true, userId: caller.userId, label: caller.label };
}

lib/analytics.ts:
/**
 * Lightweight fire-and-forget event tracker.
 *
 * Inserts a row into the `app_events` table. All calls are non-blocking and
 * swallow every error so tracking failures can never break application logic.
 *
 * Usage:
 *   trackEvent('sign_in', { state: 'VIC' });
 *   trackEvent('campaign_create', { state: 'NSW', category: 'TWOL' });
 */

import { supabase } from './supabaseClient';

export type AppEventType =
  | 'sign_in'
  | 'campaign_create'
  | 'campaign_update'
  | 'campaign_delete'
  | 'record_results_save'
  | 'record_results_save_error'
  | 'generate_slides'
  | 'generate_leader_slides'
  | 'generate_report'
  | 'generate_week1'
  | 'weekly_refresh_manual'
  | 'backup_export'
  | 'backup_restore';

/**
 * Track an application event. Fire-and-forget — never throws, never awaited.
 *
 * @param type      The event type (see AppEventType).
 * @param eventData Optional structured payload stored in the jsonb event_data column.
 */
export function trackEvent(
  type: AppEventType,
  eventData?: Record<string, unknown>,
): void {
  // Run entirely in the background — callers must not await this.
  void (async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return; // Not signed in — nothing to track.

      // Resolve display name and state from user_profiles (best-effort).
      let userName: string | null = null;
      let userState: string | null = null;
      try {
        const { data: profile } = await supabase
          .from('user_profiles')
          .select('name, state')
          .eq('user_id', user.id)
          .single();
        userName  = profile?.name  ?? null;
        userState = profile?.state ?? null;
      } catch {
        // Profile lookup failure is non-fatal.
      }

      await supabase.from('app_events').insert({
        user_id:    user.id,
        user_name:  userName,
        user_state: userState,
        event_type: type,
        event_data: eventData ?? null,
      });
    } catch {
      // Silently swallow all errors — tracking must never break the app.
    }
  })();
}

lib/appSettings.ts:
import { supabase } from './supabaseClient';
import { supabaseAdmin } from './supabaseAdmin';
import { publicLinkTitleSettingKey, publicLinkDescriptionSettingKey } from './publicLinks';
import { TECH_INSIGHTS_ENABLED_KEY, TECH_INSIGHTS_HOTKEY_KEY } from './techInsights/settings';
import { DEFAULT_TECH_INSIGHTS_HOTKEY, normalizeHotkey } from './techInsights/hotkey';

// ---------------------------------------------------------------------------
// Server-only read (no user session available, e.g. generateMetadata on a
// public page) — bypasses RLS via the service-role client, since the
// anon-key client getSetting() below has no reliable read access without an
// authenticated session. Short in-memory cache so a burst of link-preview
// crawlers (WhatsApp, Slack, etc.) re-fetching the same page doesn't hit
// Postgres on every request.
// ---------------------------------------------------------------------------

const SERVER_SETTING_CACHE_TTL_MS = 60 * 1000;
const serverSettingCache = new Map<string, { value: string | null; expiresAt: number }>();

/** Server-only variant of getSetting() — for use in Server Components/API routes with no logged-in user. */
export async function getSettingServer(key: string): Promise<string | null> {
  const cached = serverSettingCache.get(key);
  if (cached && cached.expiresAt > Date.now()) return cached.value;

  let value: string | null = null;
  try {
    const { data, error } = await supabaseAdmin
      .from('app_settings')
      .select('setting_value')
      .eq('setting_key', key)
      .single();

    if (error) {
      // PGRST116 = no row found, which just means "no override" — anything
      // else is a real failure worth logging.
      if (error.code !== 'PGRST116') console.error('Error fetching setting (server):', error);
    } else {
      value = data?.setting_value || null;
    }
  } catch (error) {
    console.error('Exception fetching setting (server):', error);
  }

  serverSettingCache.set(key, { value, expiresAt: Date.now() + SERVER_SETTING_CACHE_TTL_MS });
  return value;
}

// ---------------------------------------------------------------------------
// Secure server-gated mutation (admin writes only)
// ---------------------------------------------------------------------------

/**
 * Calls the /api/admin/settings route, which verifies admin status server-side
 * before writing. The caller's Supabase access token is forwarded so the server
 * can authenticate the request without relying on the client's trust level.
 */
async function setSettingSecure(key: string, value: string, description?: string): Promise<void> {
  const { data: { session } } = await supabase.auth.getSession();
  const token = session?.access_token;
  if (!token) throw new Error('Not authenticated');

  const res = await fetch('/api/admin/settings', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
    },
    body: JSON.stringify({ key, value, description }),
  });

  if (!res.ok) {
    const json = await res.json().catch(() => ({}));
    throw new Error(json.error ?? `Failed to update setting (${res.status})`);
  }
}

/**
 * Get a setting value by key
 * Returns the setting value as a string, or null if not found
 */
export async function getSetting(key: string): Promise<string | null> {
  try {
    const { data, error } = await supabase
      .from('app_settings')
      .select('setting_value')
      .eq('setting_key', key)
      .single();

    if (error) {
      // If setting doesn't exist, return null
      if (error.code === 'PGRST116') {
        return null;
      }
      console.error('Error fetching setting:', error);
      return null;
    }

    return data?.setting_value || null;
  } catch (error) {
    console.error('Exception fetching setting:', error);
    return null;
  }
}

/**
 * Get a boolean setting value by key
 * Returns true if setting value is 'true', false otherwise (or if not found)
 */
export async function getBooleanSetting(key: string, defaultValue: boolean = false): Promise<boolean> {
  const value = await getSetting(key);
  if (value === null) {
    return defaultValue;
  }
  return value.toLowerCase() === 'true';
}

/**
 * Set a setting value by key
 * Creates the setting if it doesn't exist, updates it if it does
 */
export async function setSetting(key: string, value: string, description?: string): Promise<void> {
  try {
    const { error } = await supabase
      .from('app_settings')
      .upsert(
        {
          setting_key: key,
          setting_value: value,
          description: description || null,
        },
        {
          onConflict: 'setting_key',
        }
      );

    if (error) {
      console.error('Error setting setting:', error);
      throw error;
    }
  } catch (error) {
    console.error('Exception setting setting:', error);
    throw error;
  }
}

/**
 * Set a boolean setting value by key
 */
export async function setBooleanSetting(key: string, value: boolean, description?: string): Promise<void> {
  await setSetting(key, value ? 'true' : 'false', description);
}

/**
 * Check if campaign logging is enabled
 */
export async function isCampaignLoggingEnabled(): Promise<boolean> {
  return await getBooleanSetting('campaign_logging_enabled', true);
}

/**
 * Set campaign logging enabled/disabled.
 * Writes through the server-verified API route — admin status is confirmed server-side.
 */
export async function setCampaignLoggingEnabled(enabled: boolean): Promise<void> {
  await setSettingSecure(
    'campaign_logging_enabled',
    enabled ? 'true' : 'false',
    'Enable or disable logging of campaign changes'
  );
}

// ---------------------------------------------------------------------------
// Slide-view feature flags (one per leader role)
// ---------------------------------------------------------------------------

const SLIDE_VIEW_KEYS = {
  leaders: 'slide_view_leaders',
  sr:      'slide_view_sr',
  admin:   'slide_view_admin',
} as const;

export type SlideViewRole = keyof typeof SLIDE_VIEW_KEYS;

const SLIDE_VIEW_DESCRIPTIONS: Record<SlideViewRole, string> = {
  leaders: 'Enable slide-style View mode for basic team leaders on the main campaign list',
  sr:      'Enable slide-style View mode for state reporters on the main campaign list',
  admin:   'Enable slide-style View mode for administrators on the main campaign list',
};

/**
 * Returns whether the slide-style view mode toggle is enabled for the given role.
 * Defaults to false (off) if the setting has never been written.
 */
export async function getSlideViewEnabled(role: SlideViewRole): Promise<boolean> {
  return getBooleanSetting(SLIDE_VIEW_KEYS[role], false);
}

/**
 * Enable or disable the slide-style view mode toggle for the given role.
 * Writes through the server-verified API route — admin status is confirmed server-side.
 */
export async function setSlideViewEnabled(role: SlideViewRole, enabled: boolean): Promise<void> {
  await setSettingSecure(SLIDE_VIEW_KEYS[role], enabled ? 'true' : 'false', SLIDE_VIEW_DESCRIPTIONS[role]);
}

// ---------------------------------------------------------------------------
// Public link display text overrides (see lib/publicLinks.ts for the
// slug/setting-key scheme and the defaults these override). Empty string is
// treated as "no override" — getSetting/getSettingServer both fall through
// `|| null` for an empty value — so "reset to default" is just saving ''.
// ---------------------------------------------------------------------------

/**
 * Override a public link's display title (shown on /admin/public-links and
 * used as the page's <title>/Open Graph title). Pass '' to reset to the
 * code default in lib/publicLinks.ts.
 * Writes through the server-verified API route — admin status is confirmed server-side.
 */
export async function setPublicLinkTitle(slug: string, value: string): Promise<void> {
  await setSettingSecure(publicLinkTitleSettingKey(slug), value, `Display title override for public link "${slug}"`);
}

/**
 * Override a public link's display description. Pass '' to reset to the
 * code default in lib/publicLinks.ts.
 * Writes through the server-verified API route — admin status is confirmed server-side.
 */
export async function setPublicLinkDescription(slug: string, value: string): Promise<void> {
  await setSettingSecure(publicLinkDescriptionSettingKey(slug), value, `Display description override for public link "${slug}"`);
}

// ---------------------------------------------------------------------------
// Tech Insights (admin-only on-screen technical details — see lib/techInsights/)
// ---------------------------------------------------------------------------

export interface TechInsightsConfig { enabled: boolean; hotkey: string }

/** One query for both settings; an unset or invalid hotkey falls back to the default. Off unless explicitly enabled. */
export async function getTechInsightsConfig(): Promise<TechInsightsConfig> {
  const { data, error } = await supabase
    .from('app_settings')
    .select('setting_key, setting_value')
    .in('setting_key', [TECH_INSIGHTS_ENABLED_KEY, TECH_INSIGHTS_HOTKEY_KEY]);
  if (error) {
    console.error('Error fetching Tech Insights settings:', error);
    return { enabled: false, hotkey: DEFAULT_TECH_INSIGHTS_HOTKEY };
  }
  const byKey = new Map((data ?? []).map((r: { setting_key: string; setting_value: string | null }) => [r.setting_key, r.setting_value]));
  return {
    enabled: (byKey.get(TECH_INSIGHTS_ENABLED_KEY) ?? '').toLowerCase() === 'true',
    hotkey: normalizeHotkey(byKey.get(TECH_INSIGHTS_HOTKEY_KEY) ?? '') ?? DEFAULT_TECH_INSIGHTS_HOTKEY,
  };
}

/** Writes through the server-verified API route — admin status is confirmed server-side. */
export async function setTechInsightsEnabled(enabled: boolean): Promise<void> {
  await setSettingSecure(TECH_INSIGHTS_ENABLED_KEY, enabled ? 'true' : 'false', 'Enable the Tech Insights panel (desktop, full admins with 2FA only)');
}

export async function setTechInsightsHotkey(hotkey: string): Promise<void> {
  const normalized = normalizeHotkey(hotkey);
  if (!normalized) throw new Error('That is not a valid shortcut — use Ctrl, Alt or Meta plus a letter, digit or F-key');
  await setSettingSecure(TECH_INSIGHTS_HOTKEY_KEY, normalized, 'Keyboard shortcut that opens the Tech Insights panel');
}

lib/ariseCanvas.ts:
/**
 * Canvas drawing helpers and renderer for the Week 1 Campaigns JPEG.
 * Depends on ariseLayout.ts for constants and types.
 */

import {
  WIDTH, HEIGHT, FONT_TITLE, FONT_KEY, FONT_DATE, FONT_CAMP,
  PLACE_COLS, TIME_COLS, LEADER_COLS,
  CONTENT_TOP, CONTENT_BOTTOM,
  DATE_PAD, DATE_BLOCK_H, DATE_HDR_SPACE, DATE_TOP_MARGIN,
  LINE_SPACING, SEP_H,
  apx, simulateColumnCount, computeColLayout, computeTimeLeaderGap,
  type AriseCampaign,
} from '@/lib/ariseLayout';
import { getSlideStateColor, formatSlideDateText, STATE_CODES } from '@/lib/slideLayout';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { combinePlaceAndSite } from '@/lib/placeSite';

// Fraction of an average character width used for the gap between fields and
// the side margins of a campaign line. Kept below 1 char so more of the
// column's width goes to the actual letters instead of whitespace.
const FIELD_GAP_CHARS = 0.4;
const MARGIN_CHARS    = 0.5;

// ---------------------------------------------------------------------------
// Draw helpers
// ---------------------------------------------------------------------------

export function drawBannerAndKey(ctx: CanvasRenderingContext2D): void {
  const bannerH = apx(0.5);
  ctx.fillStyle = 'rgb(255, 0, 0)';
  ctx.fillRect(0, 0, WIDTH, bannerH);
  ctx.fillStyle = 'white';
  ctx.font = `bold ${FONT_TITLE}px Arial`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('A.F.J UPCOMING CAMPAIGNS', WIDTH / 2, bannerH / 2);

  ctx.font = `bold ${FONT_KEY}px Arial`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  const keyLabel = 'Colour Key:    ';
  let totalW = ctx.measureText(keyLabel).width;
  STATE_CODES.forEach((s, i) => {
    totalW += ctx.measureText(s).width;
    if (i < STATE_CODES.length - 1) totalW += ctx.measureText('   ').width;
  });

  let xPos = (WIDTH - totalW) / 2;
  const yKey = apx(0.6) + apx(0.1);
  ctx.fillStyle = 'rgb(130, 0, 0)';
  ctx.fillText(keyLabel, xPos, yKey);
  xPos += ctx.measureText(keyLabel).width;
  STATE_CODES.forEach((s, i) => {
    ctx.fillStyle = getSlideStateColor(s);
    ctx.fillText(s, xPos, yKey);
    xPos += ctx.measureText(s).width;
    if (i < STATE_CODES.length - 1) {
      ctx.fillStyle = 'rgb(0, 0, 0)';
      ctx.fillText('   ', xPos, yKey);
      xPos += ctx.measureText('   ').width;
    }
  });
}

export function drawDateHeader(
  ctx: CanvasRenderingContext2D,
  date: Date,
  colX: number,
  y: number,
  colWidth: number,
): void {
  ctx.font = `italic ${FONT_DATE}px Arial`;
  const text = formatSlideDateText(date);
  const tw   = ctx.measureText(text).width;
  const bw   = Math.min(tw + 2 * DATE_PAD, colWidth);
  ctx.fillStyle = 'rgb(255, 255, 0)';
  ctx.fillRect(colX, y, bw, DATE_BLOCK_H);
  ctx.fillStyle = 'rgb(130, 0, 0)';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText(text, colX + DATE_PAD, y + DATE_PAD);
}

export function drawCampaignLine(
  ctx: CanvasRenderingContext2D,
  campaign: AriseCampaign,
  colX: number,
  y: number,
  colWidth: number,
): void {
  let place = combinePlaceAndSite(campaign.place, campaign.site);
  const cat = campaign.category ?? 'TWOL';
  if (cat !== 'TWOL') place = `${place} ${cat}`;
  if (place.length > PLACE_COLS) place = place.substring(0, PLACE_COLS);

  const time   = formatCampaignTimeDisplay(campaign.time);
  const leader = campaign.leader.length > LEADER_COLS
    ? campaign.leader.substring(0, LEADER_COLS)
    : campaign.leader;

  ctx.font = `${FONT_CAMP}px Arial`;

  // Arial is proportional, so columns can't rely on character counts like a
  // monospace font would. Each field gets its own fixed-width slot so
  // place/time/leader still line up vertically across rows. Sizing the slots
  // off 'M' (one of the widest glyphs) over-compresses ordinary text, so use
  // the average glyph width across a representative character set instead.
  const AVG_SAMPLE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const avgCharW    = ctx.measureText(AVG_SAMPLE).width / AVG_SAMPLE.length;
  const placeColW   = avgCharW * PLACE_COLS;
  const timeColW    = avgCharW * TIME_COLS;
  const leaderColW  = avgCharW * LEADER_COLS;
  const placeTimeGapW = avgCharW * FIELD_GAP_CHARS;

  const oneCharW  = Math.round(avgCharW * MARGIN_CHARS);
  const availableW = colWidth - 2 * oneCharW;

  // Give the AM/PM → leader gap one or two full space-widths (wider than the
  // other inter-field gaps) so the leader name doesn't crowd the time.
  const spaceW = ctx.measureText(' ').width;
  const naturalWWithoutTimeLeaderGap = placeColW + placeTimeGapW + timeColW + leaderColW;
  const timeLeaderGapW = computeTimeLeaderGap(naturalWWithoutTimeLeaderGap, availableW, spaceW);
  const naturalW = naturalWWithoutTimeLeaderGap + timeLeaderGapW;

  const scaleX = availableW / naturalW;

  const color = getSlideStateColor(campaign.state);
  ctx.save();
  ctx.translate(colX + oneCharW, y);
  ctx.scale(scaleX, 1);
  ctx.textBaseline = 'top';
  ctx.strokeStyle = color;
  ctx.lineWidth = 3;
  ctx.lineJoin = 'round';
  ctx.fillStyle = color;

  let x = 0;
  ctx.textAlign = 'left';
  ctx.strokeText(place, x, 0);
  ctx.fillText(place, x, 0);
  x += placeColW + placeTimeGapW;

  const timeW = ctx.measureText(time).width;
  ctx.textAlign = 'left';
  ctx.strokeText(time, x + (timeColW - timeW), 0);
  ctx.fillText(time, x + (timeColW - timeW), 0);
  x += timeColW + timeLeaderGapW;

  ctx.strokeText(leader, x, 0);
  ctx.fillText(leader, x, 0);

  ctx.restore();
}

export function drawWeekSeparator(
  ctx: CanvasRenderingContext2D,
  colX: number,
  y: number,
  colWidth: number,
): void {
  ctx.font = `bold ${FONT_KEY}px Arial`;
  ctx.fillStyle = 'rgb(255, 0, 0)';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('*'.repeat(40), colX + colWidth / 2, y);
  ctx.textAlign = 'left';
}

// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------

export async function renderAriseCanvas(
  allCampaigns: AriseCampaign[][],
  dates: Date[],
  onProgress?: (msg: string) => void,
  /**
   * Draws the red "****" separator before day index 7 (the boundary between
   * week-1 and the week-2 Monday). Only meaningful for the fixed 8-day
   * "Week 1 Campaigns" window — callers rendering an arbitrary explicit date
   * range (e.g. a custom Single Week Campaigns window) should pass `false`
   * so an unrelated 8th day doesn't get a misleading week boundary drawn
   * across it.
   */
  showWeekSeparator: boolean = true,
): Promise<HTMLCanvasElement> {
  // Measure font to compute dynamic side margin, matching the margin used
  // inside drawCampaignLine so columns and content line up.
  const tmp    = document.createElement('canvas');
  const tmpCtx = tmp.getContext('2d')!;
  tmpCtx.font  = `${FONT_CAMP}px Arial`;
  const AVG_SAMPLE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const avgCharW   = tmpCtx.measureText(AVG_SAMPLE).width / AVG_SAMPLE.length;
  const sideMargin = Math.round(avgCharW * MARGIN_CHARS);

  const nCols = Math.max(2, simulateColumnCount(allCampaigns));
  const { colWidth, colXs } = computeColLayout(nCols, sideMargin);

  onProgress?.(`Rendering Week 1 Campaigns list (${nCols} columns)…`);

  const canvas    = document.createElement('canvas');
  canvas.width    = WIDTH;
  canvas.height   = HEIGHT;
  const ctx       = canvas.getContext('2d')!;
  if (!ctx) throw new Error('Failed to get canvas context');

  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, WIDTH, HEIGHT);
  drawBannerAndKey(ctx);

  let colIdx     = 0;
  let currentY   = CONTENT_TOP;
  let firstInCol = true;

  for (let dayIndex = 0; dayIndex < dates.length; dayIndex++) {
    const date = dates[dayIndex];

    if (showWeekSeparator && dayIndex === 7) {
      const topM   = firstInCol ? 0 : DATE_TOP_MARGIN;
      const needed = topM + SEP_H;
      if (currentY + needed > CONTENT_BOTTOM && colIdx < colXs.length - 1) {
        colIdx++;
        currentY   = CONTENT_TOP;
        firstInCol = true;
      }
      const sepY = currentY + (firstInCol ? 0 : DATE_TOP_MARGIN);
      drawWeekSeparator(ctx, colXs[colIdx], sepY, colWidth);
      currentY   = sepY + SEP_H;
      firstInCol = false;
    }

    const campaigns = allCampaigns[dayIndex];
    if (campaigns.length === 0) continue;

    let remaining = [...campaigns];
    while (remaining.length > 0) {
      const topM      = firstInCol ? 0 : DATE_TOP_MARGIN;
      const minNeeded = topM + DATE_BLOCK_H + DATE_HDR_SPACE + LINE_SPACING;

      if (currentY + minNeeded > CONTENT_BOTTOM) {
        if (colIdx >= colXs.length - 1) break;
        colIdx++;
        currentY   = CONTENT_TOP;
        firstInCol = true;
      }

      const topM2   = firstInCol ? 0 : DATE_TOP_MARGIN;
      const headerY = currentY + topM2;
      drawDateHeader(ctx, date, colXs[colIdx], headerY, colWidth);

      const lineY = headerY + DATE_BLOCK_H + DATE_HDR_SPACE;
      const avail = CONTENT_BOTTOM - lineY;
      const nFit  = Math.max(0, Math.floor(avail / LINE_SPACING));

      if (nFit === 0) {
        if (colIdx >= colXs.length - 1) break;
        colIdx++;
        currentY   = CONTENT_TOP;
        firstInCol = true;
        continue;
      }

      const batch = remaining.slice(0, nFit);
      batch.forEach((c, j) => {
        drawCampaignLine(ctx, c, colXs[colIdx], lineY + j * LINE_SPACING, colWidth);
      });

      currentY   = lineY + batch.length * LINE_SPACING;
      firstInCol = false;
      remaining  = remaining.slice(nFit);
    }
  }

  return canvas;
}

lib/ariseGenerator.ts:
/**
 * Week 1 Campaigns List Generator — public API and data fetching.
 * Layout constants live in ariseLayout.ts; canvas helpers in ariseCanvas.ts.
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import { formatDownloadDate } from '@/lib/slideLayout';
import { renderAriseCanvas } from '@/lib/ariseCanvas';
import { getAriseDateRange, type AriseCampaign } from '@/lib/ariseLayout';
import { getDateRangeInclusive } from '@/lib/campaignDates';

// ---------------------------------------------------------------------------
// Data fetching
// ---------------------------------------------------------------------------

async function fetchCampaignsForDate(
  client: SupabaseClient,
  date: Date,
  filterState: string | null,
): Promise<AriseCampaign[]> {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');

  let q = client
    .from('campaigns')
    .select('id, date, state, place, site, time, leader, category')
    .eq('date', `${y}-${m}-${d}`)
    .order('state', { ascending: true })
    .order('place', { ascending: true })
    .order('time',  { ascending: true });

  if (filterState) {
    q = q.eq('state', filterState);
  }

  const { data } = await q;
  return (data ?? []) as AriseCampaign[];
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export interface GenerateAriseOptions {
  supabase: SupabaseClient;
  /** First date of the window. */
  startDate: Date;
  /**
   * Last date of the window, inclusive. When omitted, falls back to the
   * fixed 8-day "week-1 + week-2 Monday" window used by the Week 1
   * Campaigns quick action.
   */
  endDate?: Date;
  adminStatus?: string | null;
  userState?: string | null;
  /** Explicit state to filter to, chosen by a full admin. Overrides the SR role-based filter. */
  stateFilter?: string | null;
  onProgress?: (msg: string) => void;
}

/**
 * Fetches campaign data, renders the Week 1 Campaigns list as a landscape
 * JPEG, and triggers a browser download.
 */
export async function generateAndDownloadAriseList(options: GenerateAriseOptions): Promise<void> {
  const { supabase: client, startDate, endDate, adminStatus, userState, stateFilter, onProgress } = options;

  const explicitState = stateFilter && stateFilter.trim() ? stateFilter.toUpperCase().trim() : null;
  const roleState = adminStatus === 'SR' && userState ? userState.toUpperCase().trim() : null;
  const filterState = explicitState || roleState;

  const dates = endDate ? getDateRangeInclusive(startDate, endDate) : getAriseDateRange(startDate);
  if (dates.length === 0) {
    throw new Error('End date must be on or after the start date.');
  }

  onProgress?.('Fetching campaign data…');
  const allCampaigns: AriseCampaign[][] = [];
  for (let i = 0; i < dates.length; i++) {
    onProgress?.(`Fetching day ${i + 1} of ${dates.length}…`);
    allCampaigns.push(await fetchCampaignsForDate(client, dates[i], filterState));
  }

  // The week-1/week-2 separator only makes sense for the fixed 8-day
  // "Week 1 Campaigns" window — an explicit endDate means an arbitrary range
  // (e.g. Single Week Campaigns), which has no such boundary to mark.
  const canvas = await renderAriseCanvas(allCampaigns, dates, onProgress, !endDate);

  onProgress?.('Creating JPEG…');
  const blob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob(
      b => (b ? resolve(b) : reject(new Error('Failed to create JPEG blob'))),
      'image/jpeg',
      0.95,
    );
  });

  const listLabel = endDate ? 'Week_Campaigns' : 'Week1_Campaigns';
  const url  = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href     = url;
  link.download = `${formatDownloadDate(new Date())}_${listLabel}${explicitState ? `_${explicitState}` : ''}.jpg`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);

  onProgress?.('Done — campaign list downloaded.');
}

lib/ariseLayout.ts:
/**
 * Layout constants and simulation logic for the Week 1 Campaigns canvas.
 * Consumed by ariseCanvas.ts (drawing) and ariseGenerator.ts (orchestration).
 */

// ---------------------------------------------------------------------------
// Canvas dimensions
// ---------------------------------------------------------------------------

const DPI    = 300;
export const WIDTH  = Math.floor(14 * DPI); // 4200 px  (14" landscape)
export const HEIGHT = Math.floor(10 * DPI); // 3000 px  (10" landscape)

// ---------------------------------------------------------------------------
// Font sizes
// ---------------------------------------------------------------------------

export const FONT_TITLE = 72;
export const FONT_KEY   = 54;
export const FONT_DATE  = 70;
export const FONT_CAMP  = 84;

// ---------------------------------------------------------------------------
// Column layout
// ---------------------------------------------------------------------------

export const PLACE_COLS  = 20;
export const TIME_COLS   = 9;
export const LEADER_COLS = 15;

export function apx(inches: number): number {
  return Math.floor(inches * DPI);
}

export const CONTENT_TOP    = apx(1.0);
export const BOTTOM_MARGIN  = apx(0.5);
export const CONTENT_BOTTOM = HEIGHT - BOTTOM_MARGIN;

export const DATE_PAD        = apx(0.08);
export const DATE_BLOCK_H    = FONT_DATE + 2 * DATE_PAD;
export const DATE_HDR_SPACE  = apx(0.05);
export const DATE_TOP_MARGIN = apx(0.1);
export const LINE_SPACING    = apx(0.3);
export const SEP_H           = FONT_KEY + apx(0.08);

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AriseCampaign {
  id: string;
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
  category: string | null;
}

// ---------------------------------------------------------------------------
// Date range
// ---------------------------------------------------------------------------

/** Number of days covered by the Week 1 Campaigns list: week-1 (0–6) + week-2 Monday (7). */
export const ARISE_DATE_RANGE_DAYS = 8;

/**
 * Builds the 8 date targets for the Week 1 Campaigns list: every day of
 * week-1, plus the Monday that starts week-2. Shared by the authenticated
 * generator (ariseGenerator.ts) and the public API route so both stay in
 * sync with a single definition of "the current window".
 */
export function getAriseDateRange(startDate: Date): Date[] {
  return Array.from({ length: ARISE_DATE_RANGE_DAYS }, (_, i) => {
    const d = new Date(startDate);
    d.setDate(d.getDate() + i);
    return d;
  });
}

// ---------------------------------------------------------------------------
// Time → leader gap
// ---------------------------------------------------------------------------

// Below this horizontal scale, a line is already compressed enough that
// widening the time→leader gap to two space-widths would visibly shrink the
// text further — fall back to one space instead.
export const MIN_COMFORTABLE_SCALE = 0.85;

/**
 * Picks the gap (in canvas units) to leave between the AM/PM time and the
 * leader name on a campaign line: two space-widths when the column has room
 * to spare, one otherwise. Pure (no canvas ops) so it's testable without
 * mocking Canvas — callers measure `spaceW` via `ctx.measureText(' ')`.
 */
export function computeTimeLeaderGap(
  naturalWWithoutGap: number,
  availableW: number,
  spaceW: number,
): number {
  const twoSpaceScale = availableW / (naturalWWithoutGap + 2 * spaceW);
  return twoSpaceScale >= MIN_COMFORTABLE_SCALE ? 2 * spaceW : spaceW;
}

// ---------------------------------------------------------------------------
// Layout simulation
// ---------------------------------------------------------------------------

/**
 * Simulates placing 8 days of campaigns into columns and returns how many
 * columns are required. Mirrors the drawing algorithm without canvas ops.
 */
export function simulateColumnCount(allCampaigns: AriseCampaign[][]): number {
  let colCount   = 1;
  let currentY   = CONTENT_TOP;
  let firstInCol = true;

  for (let dayIndex = 0; dayIndex < allCampaigns.length; dayIndex++) {
    if (dayIndex === 7) {
      const topM   = firstInCol ? 0 : DATE_TOP_MARGIN;
      const needed = topM + SEP_H;
      if (currentY + needed > CONTENT_BOTTOM) {
        colCount++;
        currentY   = CONTENT_TOP;
        firstInCol = true;
      }
      currentY  += (firstInCol ? 0 : DATE_TOP_MARGIN) + SEP_H;
      firstInCol = false;
    }

    const count = allCampaigns[dayIndex].length;
    if (count === 0) continue;

    let remaining = count;
    while (remaining > 0) {
      const topM      = firstInCol ? 0 : DATE_TOP_MARGIN;
      const minNeeded = topM + DATE_BLOCK_H + DATE_HDR_SPACE + LINE_SPACING;

      if (currentY + minNeeded > CONTENT_BOTTOM) {
        colCount++;
        currentY   = CONTENT_TOP;
        firstInCol = true;
        continue;
      }

      const lineY = currentY + (firstInCol ? 0 : DATE_TOP_MARGIN) + DATE_BLOCK_H + DATE_HDR_SPACE;
      const avail = CONTENT_BOTTOM - lineY;
      const nFit  = Math.max(0, Math.floor(avail / LINE_SPACING));

      if (nFit === 0) {
        colCount++;
        currentY   = CONTENT_TOP;
        firstInCol = true;
        continue;
      }

      currentY   = lineY + Math.min(remaining, nFit) * LINE_SPACING;
      firstInCol = false;
      remaining  = Math.max(0, remaining - nFit);
    }
  }

  return colCount;
}

/**
 * Returns the column width and left-edge X positions for `nCols` equal columns.
 */
export function computeColLayout(
  nCols: number,
  sideMargin: number,
): { colWidth: number; colXs: number[] } {
  const colWidth = Math.floor((WIDTH - 2 * sideMargin) / nCols);
  const colXs    = Array.from({ length: nCols }, (_, i) => sideMargin + i * colWidth);
  return { colWidth, colXs };
}

