import { isAuthApiError } from '@supabase/supabase-js';
import { supabase } from './supabaseClient';

export interface User {
  id: string;
  email?: string;
}

export interface StateLeaderMatch {
  id: string;
  state: string;
  leader: string;
  mobile: string | null;
  admin: string | null;
  email: string | null;
  pendingEmail: string | null;
  suggestedEmail: string | null;
  mfaEnrolledAt: string | null;
}

/** A state_leaders row belonging to a real-auth (email + MFA) session's
 * user_id — the shape app/login/mfa/callback/page.tsx resolves to and picks
 * a role from. Deliberately leaner than StateLeaderMatch (no pending/
 * suggested email, no mobile) since this flow never needs those. */
export interface AuthedLeaderRow {
  id: string;
  state: string;
  leader: string;
  admin: string | null;
}

/**
 * Normalize mobile number by removing spaces, dashes, parentheses, and other formatting
 * Handles country codes (e.g., +61) and Australian mobile numbers
 * For Australian numbers: 
 *   - +61 0429028464 -> 0429028464 (removes country code, keeps leading 0)
 *   - +61 429028464 -> 0429028464 (removes country code, adds leading 0)
 *   - +61429028464 -> 0429028464 (removes country code, adds leading 0)
 * Also handles: 0429028464, 0429 028 464, etc.
 */
export function normalizeMobile(mobile: string): string {
  if (!mobile) return '';

  let normalized = mobile.trim();

  // Handle country code +61 (Australia) - can have space or no space
  if (normalized.startsWith('+61')) {
    normalized = normalized.substring(3).trim(); // Remove '+61' and any following space
  }

  // Remove all non-digit characters (spaces, dashes, parentheses, + signs)
  normalized = normalized.replace(/[\s\-\(\)\+]/g, '');

  // For Australian numbers: if it doesn't start with 0 and has 9 digits, add leading 0
  // This handles cases like "+61 429028464" -> "429028464" -> "0429028464"
  if (normalized && !normalized.startsWith('0') && normalized.length === 9) {
    normalized = '0' + normalized;
  }

  return normalized;
}

/**
 * Normalize name by trimming whitespace and converting to lowercase for comparison
 * Returns the normalized version for comparison, but we'll use the original for display
 */
export function normalizeName(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * Validate mobile number and first name against state_leaders table.
 * Returns ALL matching records — callers must handle the multi-state case.
 * Uses server-side API route with service role to bypass RLS.
 */
export async function validateStateLeader(mobile: string, firstName: string): Promise<StateLeaderMatch[]> {
  try {
    const res = await fetch('/api/auth/validate-leader', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mobile, firstName }),
    });

    const json = await res.json();

    if (!res.ok) {
      console.error('Error validating state leader:', json.error);
      throw new Error(json.error || 'Validation failed');
    }

    return (json.matches ?? []).map((m: StateLeaderMatch) => ({
      id:             m.id,
      state:          m.state,
      leader:         m.leader,
      mobile:         null,
      admin:          m.admin,
      email:          m.email,
      pendingEmail:   m.pendingEmail,
      suggestedEmail: m.suggestedEmail,
      mfaEnrolledAt:  m.mfaEnrolledAt,
    }));
  } catch (err) {
    console.error('Error validating state leader:', err);
    throw err;
  }
}

/**
 * Sets the app_session cookie middleware.ts checks for every protected
 * route. Not cryptographically verified — RLS remains the true security
 * boundary. maxAgeSeconds is omitted for the mobile+name flow (a plain
 * session cookie, cleared on browser close, matching today's behaviour) and
 * set to a real duration for the real-auth+MFA flow (see
 * completeLeaderAuthSignIn) — that flow has more per-login friction (email +
 * TOTP code vs. one instant form), so a longer-lived cookie offsets it,
 * since the underlying Supabase session/refresh token already supports
 * staying signed in that long.
 */
function setAppSessionCookie(maxAgeSeconds?: number): void {
  if (typeof document === 'undefined') return;
  const secure = location.protocol === 'https:' ? '; Secure' : '';
  const maxAge = maxAgeSeconds ? `; Max-Age=${maxAgeSeconds}` : '';
  document.cookie = `app_session=1; path=/; SameSite=Lax${secure}${maxAge}`;
}

function clearAppSessionCookie(): void {
  if (typeof document === 'undefined') return;
  document.cookie = 'app_session=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT; SameSite=Lax';
}

/**
 * Signs the current session out *and* has the server delete its
 * user_profiles / user_roles rows (app/api/auth/revoke-session-access), so a
 * signed-out session leaves no app identity behind. The delete is
 * best-effort — it must never stop the sign-out itself. Returns the sign-out
 * error, if any.
 */
export async function signOutClearingAccess(): Promise<{ error: Error | null }> {
  try {
    const { data: { session } } = await supabase.auth.getSession();
    if (session) {
      await fetch('/api/auth/revoke-session-access', {
        method: 'POST',
        headers: { Authorization: `Bearer ${session.access_token}` },
      });
    }
  } catch (err) {
    console.warn('Failed to clear session access before sign-out:', err);
  }
  return supabase.auth.signOut();
}

/**
 * Asks the server to write this session's user_profiles / user_roles rows
 * (app/api/auth/grant-session-access). The browser used to write them itself,
 * but user_roles' RLS then had to let any signed-in session write its own
 * `admin` row — so the server now verifies entitlement first. Throws if the
 * server refuses, so a failed grant can't look like a successful sign-in.
 */
async function requestSessionAccess(
  body:
    | { method: 'mobile-name'; leaderId: string; mobile: string; firstName: string }
    | { method: 'real-auth'; leaderId: string },
): Promise<void> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error('No active session');

  const res = await fetch('/api/auth/grant-session-access', {
    method: 'POST',
    headers: { Authorization: `Bearer ${session.access_token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const json = (await res.json().catch(() => ({}))) as { error?: string; code?: string };
    throw new Error(
      json.code === 'mfa_required'
        ? json.error ?? 'Admin accounts must sign in with email and two-factor authentication.'
        : res.status === 403
          ? 'Sign-in could not be verified. Please check your details and try again.'
          : json.error || 'Failed to complete sign-in. Please try again.',
    );
  }
}

/**
 * Complete sign-in once a specific state_leaders record has been chosen.
 * Creates an anonymous Supabase session and writes user_profiles / user_roles.
 */
export async function completeSignIn(
  stateLeader: StateLeaderMatch,
  credentials: { mobile: string; firstName: string },
): Promise<{ user: User; stateLeader: StateLeaderMatch }> {
  // Sign out any existing stale session first. Without this, every login on the
  // same device creates a fresh anonymous auth user that is never cleaned up.
  const { data: { session: existingSession } } = await supabase.auth.getSession();
  if (existingSession) {
    await signOutClearingAccess();
  }

  const { data: authData, error: authError } = await supabase.auth.signInAnonymously();

  if (authError) {
    const msg = authError.message || authError.toString();
    throw new Error(
      msg.includes('Anonymous sign-ins are disabled')
        ? 'Anonymous sign-in is disabled in Supabase. Enable it in Dashboard → Authentication → Providers → Anonymous.'
        : `Authentication failed: ${msg}`
    );
  }

  if (!authData.user) {
    throw new Error('Failed to create user session');
  }

  // The server re-verifies the mobile+name pair before writing this session's
  // user_profiles / user_roles rows (see requestSessionAccess). If it refuses,
  // don't leave a half-signed-in anonymous session behind.
  try {
    await requestSessionAccess({
      method: 'mobile-name',
      leaderId: stateLeader.id,
      mobile: credentials.mobile,
      firstName: credentials.firstName,
    });
  } catch (err) {
    await supabase.auth.signOut();
    throw err;
  }

  // Record sign-in timestamp
  const { error: signInUpdateError } = await supabase
    .from('state_leaders')
    .update({ last_sign_in_at: new Date().toISOString() })
    .eq('id', stateLeader.id);
  if (signInUpdateError) console.warn('Failed to update last_sign_in_at:', signInUpdateError);

  setAppSessionCookie();

  return { user: { id: authData.user.id, email: authData.user.email }, stateLeader };
}

const LEADER_AUTH_SESSION_MAX_AGE_SECONDS = 30 * 24 * 60 * 60; // 30 days

/**
 * Complete sign-in for the real-auth + MFA login path
 * (app/login/mfa/callback/page.tsx), once the leader's chosen state_leaders
 * row is known and the session is already a real, AAL2-verified one (never
 * an anonymous sign-in — that already exists by the time this is called, so
 * unlike completeSignIn() there's no signInAnonymously() step here).
 *
 * Has the server write the exact same user_profiles/user_roles shape
 * completeSignIn() does (requestSessionAccess — the server checks the session
 * is this row's bound user_id and at aal2), so every existing "who is this / are they admin" consumer
 * (UserContext, campaignFilter.ts, the RLS is_admin() function, the admin
 * API routes) keeps working completely unmodified — none of them care
 * whether the underlying auth.users row is anonymous or real, only that
 * user_profiles/user_roles exist for the current session's auth.uid().
 *
 * One behaviour completeSignIn() never needed: since this real user_id
 * persists across logins (unlike a fresh anonymous user every time), a
 * leader who picks a *different* role on a later login (e.g. their SR row
 * instead of their AD row) must not keep a stale admin user_roles row from
 * a previous choice — so a non-admin pick explicitly deletes any existing
 * row rather than just never upserting one.
 */
export async function completeLeaderAuthSignIn(row: AuthedLeaderRow): Promise<void> {
  await requestSessionAccess({ method: 'real-auth', leaderId: row.id });

  const { error: signInUpdateError } = await supabase
    .from('state_leaders')
    .update({ last_sign_in_at: new Date().toISOString() })
    .eq('id', row.id);
  if (signInUpdateError) console.warn('Failed to update last_sign_in_at:', signInUpdateError);

  setAppSessionCookie(LEADER_AUTH_SESSION_MAX_AGE_SECONDS);
}

/**
 * Convenience wrapper: validate then sign in immediately.
 * Errors if credentials are invalid; picks the first record if multiple states
 * match (legacy behaviour — prefer validateStateLeader + completeSignIn for
 * full multi-state support).
 */
export async function signInWithMobileAndName(
  mobile: string,
  firstName: string,
): Promise<{ user: User; stateLeader: StateLeaderMatch }> {
  const matches = await validateStateLeader(mobile, firstName);
  if (matches.length === 0) {
    throw new Error('No matching record found. Please check your mobile number and first name.');
  }
  return completeSignIn(matches[0], { mobile, firstName });
}

export async function sendMagicLink(email: string) {
  // Get the current origin (localhost:3000 in development)
  const origin = typeof window !== 'undefined' ? window.location.origin : '';

  const { data, error } = await supabase.auth.signInWithOtp({
    email,
    options: {
      emailRedirectTo: `${origin}/auth/callback`,
    },
  });

  if (error) throw error;
  return data;
}

export async function signOut() {
  const { error } = await signOutClearingAccess();
  if (error) throw error;
  // Clear the session-indicator cookie set on login.
  clearAppSessionCookie();
}

export async function getCurrentUser(): Promise<User | null> {
  const { data: { user }, error } = await supabase.auth.getUser();
  if (error) throw error;
  return user ? { id: user.id, email: user.email } : null;
}

export async function getSession() {
  const { data: { session }, error } = await supabase.auth.getSession();
  if (error) throw error;
  return session;
}

/**
 * Like getSession(), but only returns the session if Supabase's server still
 * accepts it. getSession() just reads the copy saved on the device, so a
 * session the server has since rejected (banned — e.g. by
 * scripts/revoke_admin_app_sessions.ts — deleted, or otherwise invalid) still
 * looks signed in. /login used to send that to /app, whose own server check
 * (UserContext → getUser()) sent it straight back to /login, forever — the
 * phone just showed "Checking sign-in status…" (Peter_AD, 2026-10-14).
 *
 * A rejected session is cleared from this device (local sign-out only — the
 * server has already disowned it) along with the app_session cookie. A
 * network failure returns null without clearing anything, so a leader who is
 * briefly offline isn't signed out.
 */
export async function getVerifiedSession() {
  const session = await getSession();
  if (!session) return null;
  const { data: { user }, error } = await supabase.auth.getUser();
  if (user && !error) return session;
  if (!error || isAuthApiError(error)) {
    await supabase.auth.signOut({ scope: 'local' });
    clearAppSessionCookie();
  }
  return null;
}

