/** Free authenticator apps, linked from the setup screen and the step-by-step guide (app/help/2fa). */
export const AUTHENTICATOR_STORE_LINKS = [
  { label: 'iPhone — Google Authenticator', href: 'https://apps.apple.com/app/google-authenticator/id388497605' },
