/**
 * Campaign Date Management
 *
 * Calculates and manages global campaign dates based on the current day of the week.
 */
import { getOrdinalSuffix } from '@/lib/slideLayout';

export interface CampaignDates {
  pastCampaignStart: Date;
  upcomingCampaignStart: Date;
  secondWeekStart: Date;
}

/**
 * Get the Monday of a given week
 * @param date - Reference date
 * @param weeksOffset - Number of weeks to offset (negative for previous weeks, positive for future weeks)
 */
function getMondayOfWeek(date: Date, weeksOffset: number = 0): Date {
  const result = new Date(date);
  const dayOfWeek = result.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday

  // Calculate days to subtract to get to Monday
  // If Sunday (0), go back 6 days; if Monday (1), go back 0 days; if Tuesday (2), go back 1 day, etc.
  const daysToMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

  result.setDate(result.getDate() - daysToMonday + (weeksOffset * 7));
  result.setHours(0, 0, 0, 0);

  return result;
}

/**
 * Calculate campaign dates based on the current date
 * 
 * Logic:
 * 1. Past Campaign Start:
 *    - Thursday to Sunday (4-0): Monday of current week
 *    - Monday to Wednesday (1-3): Monday of previous week
 * 
 * 2. Upcoming Campaign Start:
 *    - Monday to Saturday (1-6): Monday of current week
 *    - Sunday (0): Monday of next week
 * 
 * 3. Second Week Start:
 *    - Monday after Upcoming Campaign Start
 */
export function calculateCampaignDates(referenceDate: Date = new Date()): CampaignDates {
  const dayOfWeek = referenceDate.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday

  let pastCampaignStart: Date;
  let upcomingCampaignStart: Date;

  // Determine Past Campaign Start
  if (dayOfWeek >= 4 || dayOfWeek === 0) {
    // Thursday to Sunday: Monday of current week
    pastCampaignStart = getMondayOfWeek(referenceDate, 0);
  } else {
    // Monday to Wednesday: Monday of previous week
    pastCampaignStart = getMondayOfWeek(referenceDate, -1);
  }

  // Determine Upcoming Campaign Start
  if (dayOfWeek >= 1 && dayOfWeek <= 6) {
    // Monday to Saturday: Monday of current week
    upcomingCampaignStart = getMondayOfWeek(referenceDate, 0);
  } else {
    // Sunday: Monday of next week
    upcomingCampaignStart = getMondayOfWeek(referenceDate, 1);
  }

  // Second Week Start: Monday after Upcoming Campaign Start
  const secondWeekStart = new Date(upcomingCampaignStart);
  secondWeekStart.setDate(secondWeekStart.getDate() + 7);

  return {
    pastCampaignStart,
    upcomingCampaignStart,
    secondWeekStart,
  };
}

/**
 * Format a date as YYYY-MM-DD
 */
export function formatDateForDb(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Get today's date as YYYY-MM-DD string
 */
export function getTodayDateString(): string {
  return formatDateForDb(new Date());
}

/** Number of days covered by "the fortnight": the upcoming week plus the one after it. */
export const FORTNIGHT_DAYS = 14;

/**
 * Builds the 14 consecutive date targets covering a fortnight starting at
 * `startDate`. Shared by the slide/ZIP generator (lib/slideGenerator.ts) and
 * any public route that needs the same "current fortnight" window, so both
 * stay in sync with a single definition.
 */
export function getFortnightDateRange(startDate: Date): Date[] {
  return Array.from({ length: FORTNIGHT_DAYS }, (_, i) => {
    const d = new Date(startDate);
    d.setDate(d.getDate() + i);
    return d;
  });
}

/**
 * Builds every date from `startDate` to `endDate`, inclusive. Used wherever
 * a screen lets the user pick an explicit Start Date + End Date instead of
 * relying on a fixed-length window (e.g. `getFortnightDateRange`,
 * `getAriseDateRange`). Returns an empty array if `endDate` precedes
 * `startDate`.
 */
export function getDateRangeInclusive(startDate: Date, endDate: Date): Date[] {
  const dates: Date[] = [];
  const cursor = new Date(startDate);
  cursor.setHours(0, 0, 0, 0);
  const last = new Date(endDate);
  last.setHours(0, 0, 0, 0);
  while (cursor <= last) {
    dates.push(new Date(cursor));
    cursor.setDate(cursor.getDate() + 1);
  }
  return dates;
}

/**
 * Format a date as a readable string (e.g., "Mon, Jan 15, 2026")
 */
export function formatDateReadable(date: Date): string {
  return date.toLocaleDateString('en-US', {
    weekday: 'short',
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

const SHORT_MONTH_NAMES = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];

/**
 * Format a Monday-start week as a compact range label, e.g. "3 Aug - 9 Aug".
 * The month is always shown on both ends (even within a single month) and the
 * year is omitted entirely — spans a month boundary the same way, e.g.
 * "29 Jun - 5 Jul" or "28 Dec - 3 Jan".
 *
 * Uses a fixed month-abbreviation table rather than toLocaleString(), whose
 * 'short' month format is inconsistent across locales/ICU builds (e.g. 'en-AU'
 * can render "June" instead of "Jun" depending on the runtime's ICU data).
 */
export function formatWeekRangeLabel(monday: Date): string {
  const sunday = new Date(monday);
  sunday.setDate(sunday.getDate() + 6);

  const startDay = monday.getDate();
  const endDay = sunday.getDate();
  const startMonth = SHORT_MONTH_NAMES[monday.getMonth()];
  const endMonth = SHORT_MONTH_NAMES[sunday.getMonth()];

  return `${startDay} ${startMonth} - ${endDay} ${endMonth}`;
}

/**
 * Format a Monday-start week as a full date range string, e.g.
 * "Mon 10th Aug 26 - Sun 16th Aug 26" — used where the week needs to be
 * spelled out in full rather than the compact formatWeekRangeLabel().
 */
export function formatWeekDateRangeString(monday: Date): string {
  const sunday = new Date(monday);
  sunday.setDate(sunday.getDate() + 6);

  const format = (date: Date, dayName: string) => {
    const day = date.getDate();
    const month = SHORT_MONTH_NAMES[date.getMonth()];
    const year = String(date.getFullYear()).slice(2);
    return `${dayName} ${day}${getOrdinalSuffix(day)} ${month} ${year}`;
  };

  return `${format(monday, 'Mon')} - ${format(sunday, 'Sun')}`;
}

/**
 * Compact Monday–Sunday range for buttons, e.g. "19–25 Oct", or
 * "28 Oct – 3 Nov" when the week spans two months.
 */
export function formatShortWeekRange(monday: Date): string {
  const sunday = new Date(monday);
  sunday.setDate(sunday.getDate() + 6);
  const startMonth = SHORT_MONTH_NAMES[monday.getMonth()];
  const endMonth = SHORT_MONTH_NAMES[sunday.getMonth()];
  if (monday.getMonth() === sunday.getMonth()) {
    return `${monday.getDate()}–${sunday.getDate()} ${endMonth}`;
  }
  return `${monday.getDate()} ${startMonth} – ${sunday.getDate()} ${endMonth}`;
}

/**
 * Format a Monday-start fortnight (14 days — the combined upcoming + second
 * week period) as a full date range string, e.g. "Mon 10th Aug 26 - Sun 23rd
 * Aug 26". Same format as formatWeekDateRangeString but spans two weeks.
 */
export function formatFortnightDateRangeString(monday: Date): string {
  const secondSunday = new Date(monday);
  secondSunday.setDate(secondSunday.getDate() + 13);

  const format = (date: Date, dayName: string) => {
    const day = date.getDate();
    const month = SHORT_MONTH_NAMES[date.getMonth()];
    const year = String(date.getFullYear()).slice(2);
    return `${dayName} ${day}${getOrdinalSuffix(day)} ${month} ${year}`;
  };

  return `${format(monday, 'Mon')} - ${format(secondSunday, 'Sun')}`;
}

const SHORT_DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/**
 * Format a single date as a compact "Wed 12th Aug" string — short day name,
 * ordinal day, short month, no year. Used for one-line campaign summaries
 * (e.g. the Register Interest confirmation popup) where a full date range
 * would be too long. Uses fixed day/month abbreviation tables rather than
 * toLocaleString(), for the same ICU-consistency reason as the range
 * formatters above.
 */
export function formatShortDateWithOrdinal(date: Date): string {
  const dayName = SHORT_DAY_NAMES[date.getDay()];
  const day = date.getDate();
  const month = SHORT_MONTH_NAMES[date.getMonth()];
  return `${dayName} ${day}${getOrdinalSuffix(day)} ${month}`;
}

const FULL_DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

/**
 * The Sunday named in the Campaign Results public link's notice ("will not be
 * stored by AFJ in any form beyond …"), given the Monday of the week being
 * displayed: the end of the week *after* the one in which that week is on
 * screen. A displayed week is actually deleted a week earlier than this, by
 * the Sunday refresh that ends its time on screen (e.g. the 28 Sep - 4 Oct
 * week is shown until, and deleted on, Sunday 11 Oct — the notice says
 * Sunday 18 Oct). The extra week is deliberate (Peter, 2026-10-09): it gives
 * people time to delete any copies they downloaded themselves.
 */
export function getCampaignResultsNoticeDate(displayedWeekStart: Date): Date {
  const noticeDate = new Date(displayedWeekStart);
  noticeDate.setDate(noticeDate.getDate() + 20);
  return noticeDate;
}

/**
 * Format a single date as "Sunday 11th Oct 2026" — full day name, ordinal
 * day, short month, full year. Used where a date is read as part of a
 * sentence (e.g. the Campaign Results public link's notice) rather than as a
 * compact label. Fixed name tables rather than toLocaleString(), same
 * ICU-consistency reason as the formatters above.
 */
export function formatLongDateWithOrdinal(date: Date): string {
  const dayName = FULL_DAY_NAMES[date.getDay()];
  const day = date.getDate();
  const month = SHORT_MONTH_NAMES[date.getMonth()];
  return `${dayName} ${day}${getOrdinalSuffix(day)} ${month} ${date.getFullYear()}`;
}

/**
 * Get the current campaign dates as formatted strings
 */
export function getCampaignDatesFormatted() {
  const dates = calculateCampaignDates();

  return {
    pastCampaignStart: formatDateForDb(dates.pastCampaignStart),
    upcomingCampaignStart: formatDateForDb(dates.upcomingCampaignStart),
    secondWeekStart: formatDateForDb(dates.secondWeekStart),
    pastCampaignStartReadable: formatDateReadable(dates.pastCampaignStart),
    upcomingCampaignStartReadable: formatDateReadable(dates.upcomingCampaignStart),
    secondWeekStartReadable: formatDateReadable(dates.secondWeekStart),
  };
}

/**
 * Check if a date is in the past campaigns period
 */
export function isInPastPeriod(campaignDate: Date | string): boolean {
  const dates = calculateCampaignDates();
  const dateObj = typeof campaignDate === 'string' ? new Date(campaignDate) : campaignDate;
  dateObj.setHours(0, 0, 0, 0);

  return dateObj < dates.upcomingCampaignStart;
}

/**
 * Check if a date is in the upcoming campaigns period (current 2-week period)
 */
export function isInUpcomingPeriod(campaignDate: Date | string): boolean {
  const dates = calculateCampaignDates();
  const dateObj = typeof campaignDate === 'string' ? new Date(campaignDate) : campaignDate;
  dateObj.setHours(0, 0, 0, 0);

  const endOfSecondWeek = new Date(dates.secondWeekStart);
  endOfSecondWeek.setDate(endOfSecondWeek.getDate() + 6); // End of second week (Sunday)

  return dateObj >= dates.upcomingCampaignStart && dateObj <= endOfSecondWeek;
}

