import { supabase } from './supabaseClient';
import { getCurrentUser } from './auth';
import { getUserProfile } from './userProfile';
import { isCampaignLoggingEnabled } from './appSettings';

/**
 * Get changed fields between old and new data
 */
function getChangedFields(oldData: Record<string, unknown>, newData: Record<string, unknown>): string[] {
  const changedFields: string[] = [];
  const allKeys = new Set([...Object.keys(oldData), ...Object.keys(newData)]);

  for (const key of allKeys) {
    // Skip internal fields that shouldn't be logged as changes
    if (key === 'id' || key === 'created_at' || key === 'updated_at') {
      continue;
    }

    const oldValue = oldData[key];
    const newValue = newData[key];

    // Compare values (handling null/undefined)
    if (oldValue !== newValue) {
      // Deep comparison for objects/arrays
      if (JSON.stringify(oldValue) !== JSON.stringify(newValue)) {
        changedFields.push(key);
      }
    }
  }

  return changedFields;
}

/**
 * Log a campaign change to the campaign_changes_log table.
 * Logs from every route, including admin screens — a past incident where campaigns went
 * missing was much harder to investigate than it needed to be because admin-route changes
 * were silently excluded (see #92 investigation).
 *
 * @param campaignId - The ID of the campaign being changed (null for INSERT before creation)
 * @param changeType - Type of change: 'INSERT', 'UPDATE', or 'DELETE'
 * @param oldData - Previous values (for UPDATE/DELETE)
 * @param newData - New values (for INSERT/UPDATE)
 */
export async function logCampaignChange(
  campaignId: string | null,
  changeType: 'INSERT' | 'UPDATE' | 'DELETE',
  oldData?: Record<string, unknown> | null,
  newData?: Record<string, unknown> | null
): Promise<void> {
  try {
    // Check if logging is enabled
    const loggingEnabled = await isCampaignLoggingEnabled();
    if (!loggingEnabled) {
      console.log('Skipping campaign change log - logging is disabled');
      return;
    }

    // Get current user
    const user = await getCurrentUser();
    if (!user) {
      console.warn('Cannot log campaign change - user not authenticated');
      return;
    }

    // Get user profile for name
    let userName: string | null = null;
    const userEmail: string | null = user.email || null;

    try {
      const profile = await getUserProfile();
      userName = profile?.name || null;
    } catch (error) {
      console.warn('Could not fetch user profile for logging:', error);
    }

    // Determine changed fields for UPDATE operations
    let changedFields: string[] | null = null;
    if (changeType === 'UPDATE' && oldData && newData) {
      changedFields = getChangedFields(oldData, newData);
      // If no fields actually changed, skip logging
      if (changedFields.length === 0) {
        return;
      }
    }

    // Prepare log entry
    const logEntry: {
      campaign_id?: string | null;
      user_id: string;
      change_type: string;
      old_data?: Record<string, unknown>;
      new_data?: Record<string, unknown>;
      changed_fields?: string[] | null;
      user_email?: string | null;
      user_name?: string | null;
    } = {
      user_id: user.id,
      change_type: changeType,
      user_email: userEmail,
      user_name: userName,
    };

    // Add campaign_id if available
    if (campaignId) {
      logEntry.campaign_id = campaignId;
    }

    // Add old_data for UPDATE/DELETE
    if ((changeType === 'UPDATE' || changeType === 'DELETE') && oldData) {
      // Remove internal fields from logged data
      const { id, created_at, updated_at, user_id, ...loggableOldData } = oldData;
      logEntry.old_data = loggableOldData;
    }

    // Add new_data for INSERT/UPDATE
    if ((changeType === 'INSERT' || changeType === 'UPDATE') && newData) {
      // Remove internal fields from logged data
      const { id, created_at, updated_at, user_id, ...loggableNewData } = newData;
      logEntry.new_data = loggableNewData;
    }

    // Add changed_fields for UPDATE
    if (changeType === 'UPDATE' && changedFields) {
      logEntry.changed_fields = changedFields;
    }

    // Insert log entry (async, don't wait for it to complete)
    Promise.resolve(
      supabase
        .from('campaign_changes_log')
        .insert([logEntry])
    )
      .then(({ error }) => {
        if (error) {
          console.error('Error logging campaign change:', error);
        }
      })
      .catch((error) => {
        console.error('Exception logging campaign change:', error);
      });
  } catch (error) {
    // Don't throw - logging failures shouldn't break the main operation
    console.error('Error in logCampaignChange:', error);
  }
}

/**
 * Helper function to fetch current campaign data before updating
 * This is useful when you need to log the old state before an update
 */
export async function fetchCampaignData(campaignId: string): Promise<import('./types').Campaign | null> {
  try {
    const { data, error } = await supabase
      .from('campaigns')
      .select('*')
      .eq('id', campaignId)
      .single();

    if (error) {
      console.error('Error fetching campaign data:', error);
      return null;
    }

    return data;
  } catch (error) {
    console.error('Exception fetching campaign data:', error);
    return null;
  }
}

lib/campaignReportLocationSort.ts:
/** Sorting for the Campaign Report Locations (bulk) list. */
import type { UnresolvedLocation } from '@/lib/services/campaignReportLocationsService';

export type LocationSortColumn = 'records' | 'location' | 'state';
export type SortDirection = 'asc' | 'desc';

/**
 * Sorted copy. Records sort by count; location by its text; state by the
 * state already worked out for it, with ties (and unknown states, which
 * always come last) broken by location so a state's locations stay in order.
 */
export function sortLocations(
  locations: UnresolvedLocation[],
  column: LocationSortColumn,
  direction: SortDirection,
): UnresolvedLocation[] {
  const sign = direction === 'asc' ? 1 : -1;
  const byLocation = (a: UnresolvedLocation, b: UnresolvedLocation) => a.example.toLowerCase().localeCompare(b.example.toLowerCase());
  return [...locations].sort((a, b) => {
    if (column === 'records') return (a.rows - b.rows) * sign || byLocation(a, b);
    if (column === 'location') return byLocation(a, b) * sign;
    if (!a.knownState && !b.knownState) return byLocation(a, b);
    if (!a.knownState) return 1;
    if (!b.knownState) return -1;
    return a.knownState.localeCompare(b.knownState) * sign || byLocation(a, b);
  });
}

lib/campaignReportManageFilters.ts:
/**
 * Pure search / filter / sort for the Campaign Reports management screen
 * (app/admin/campaign-reports/page.tsx). The whole list (~6.5k rows) is
 * fetched once and narrowed in the browser, like /registry/manage.
 */
import type { ManageReport } from '@/lib/campaignReportManageTypes';

export interface ReportFilters {
  search: string;
  /** 'all', 'none' (no state yet) or a state code. */
  state: string;
  locationStatus: 'all' | 'missing' | 'set';
  needsReviewOnly: boolean;
  /** 'all' or a submission year, e.g. '2026'. */
  year: string;
}

export const DEFAULT_REPORT_FILTERS: ReportFilters = {
  search: '', state: 'all', locationStatus: 'all', needsReviewOnly: false, year: 'all',
};

export type ReportSortColumn = 'submittedAt' | 'campaignDate' | 'locationTyped' | 'leader' | 'state' | 'location';
export type SortDirection = 'asc' | 'desc';

export function filterReports(reports: ManageReport[], f: ReportFilters): ManageReport[] {
  const needle = f.search.trim().toLowerCase();
  return reports.filter((r) => {
    if (f.state === 'none' && r.state) return false;
    if (f.state !== 'none' && f.state !== 'all' && r.state !== f.state) return false;
    if (f.locationStatus === 'missing' && r.location) return false;
    if (f.locationStatus === 'set' && !r.location) return false;
    if (f.needsReviewOnly && !r.needsReview) return false;
    if (f.year !== 'all' && !r.submittedAt.startsWith(f.year)) return false;
    if (needle) {
      const haystack = [r.locationTyped, r.leader, r.location, r.matchedLeader, r.state].filter(Boolean).join(' ').toLowerCase();
      if (!haystack.includes(needle)) return false;
    }
    return true;
  });
}

function sortValue(r: ManageReport, column: ReportSortColumn): string {
  switch (column) {
    case 'submittedAt': return r.submittedAt;
    case 'campaignDate': return r.campaignDate ?? '';
    case 'locationTyped': return (r.locationTyped ?? '').toLowerCase();
    case 'leader': return (r.leader ?? '').toLowerCase();
    case 'state': return r.state ?? '';
    case 'location': return (r.location ?? '').toLowerCase();
  }
}

/** Sorted copy; blank values always sort last whichever way you sort. */
export function sortReports(reports: ManageReport[], column: ReportSortColumn, direction: SortDirection): ManageReport[] {
  const sign = direction === 'asc' ? 1 : -1;
  return [...reports].sort((a, b) => {
    const av = sortValue(a, column);
    const bv = sortValue(b, column);
    if (av === bv) return 0;
    if (av === '') return 1;
    if (bv === '') return -1;
    return av < bv ? -sign : sign;
  });
}

/** Distinct submission years, newest first, for the year filter. */
export function reportYears(reports: ManageReport[]): string[] {
  return [...new Set(reports.map((r) => r.submittedAt.slice(0, 4)))].sort().reverse();
}

export interface ReportSummary {
  total: number;
  noState: number;
  noLocation: number;
  needsReview: number;
}

export function summarizeReports(reports: ManageReport[]): ReportSummary {
  return {
    total: reports.length,
    noState: reports.filter((r) => !r.state).length,
    noLocation: reports.filter((r) => !r.location).length,
    needsReview: reports.filter((r) => r.needsReview).length,
  };
}

lib/campaignReportManageTypes.ts:
/** Shapes shared by the Campaign Reports management screen and its API (see lib/services/campaignReportManageService.ts). */

export interface ManageReport {
  id: string;
  submittedAt: string;
  campaignDate: string | null;
  campaignDateRaw: string | null;
  /** The location and leader exactly as typed into the sheet. */
  locationTyped: string | null;
  leader: string | null;
  state: string | null;
  /** The mapped State Places location (`state_places.location`) — the physical location. */
  location: string | null;
  matchedLeader: string | null;
  partial: number | null;
  full: number | null;
  sinnersPrayer: number | null;
