lib/campaignReportMatcher.ts:
/**
 * Derives state/location/leader for `campaign_reports` rows by matching the
 * sheet's free-text `location_raw`/`leader_raw` against this app's own
 * `state_places`/`state_leaders` reference tables.
 *
 * "Location" here is `state_places.location` — the real physical location
 * (e.g. "Perth CBD", "Frankston", "Orange") — not `state_places.place`, which
 * is a campaign-form site label that can be numbered ("Perth CBD 3",
 * "Frankston 2") or a one-off name ("LifeSrce Food"); several places can share
 * one location, and a typed "Frankston" can't say which numbered site was
 * meant. A typed name is matched against both, and the result is the
 * place's location.
 *
 * Full sheet history (2020-2026) was ruled out for this kind of matching in
 * phase 1 — see docs/campaign-report/BRIEF.md — because the text is too
 * inconsistent (1,355 distinct locations, 1,693 distinct leaders). The more
 * recent slice is meaningfully cleaner (mostly bare suburb/venue names and
 * first names, occasionally with a team-size suffix), so a normalization +
 * small verified-alias pass recovers state for the large majority of rows.
 *
 * Philosophy, matching lib/campaignReportParser.ts: never guess. A row that
 * can't be confidently resolved gets `null` fields, not a best-effort pick —
 * see scripts/derive_campaign_reports_fields.ts for how those are surfaced.
 */

export interface PlaceRef {
  state: string;
  place: string;
  /** state_places.location — the physical location; falls back to `place` when empty. */
  location?: string | null;
}

export interface LeaderRef {
  state: string;
  leader: string;
}

/** A confirmed mapping from a normalized sheet location (see locationKey) to a state and, when known, a state_places location. */
export interface LocationAliasRef {
  location_key: string;
  state: string;
  location: string | null;
}

export interface DerivedFields {
  state: string | null;
  location: string | null;
  leader: string | null;
}

/** The physical location a state_places row stands for. */
export function locationOf(p: PlaceRef): string {
  return (p.location?.trim() || p.place.trim());
}

/** Distinct physical locations (case-insensitive) among the rows, keeping the first spelling seen. */
export function distinctLocations(rows: PlaceRef[]): string[] {
  const seen = new Map<string, string>();
  for (const r of rows) {
    const loc = locationOf(r);
    if (loc && !seen.has(loc.toLowerCase())) seen.set(loc.toLowerCase(), loc);
  }
  return [...seen.values()];
}

// Verified against the live state_places table (each key confirmed to
// resolve to a real row) — typos and abbreviation mismatches between how
// leaders typed the sheet's "Location" column and how the place is actually
// stored in state_places. Keys are already lowercased/trimmed.
const LOCATION_ALIASES: Record<string, string> = {
  'mount gambier': 'mt gambier',
  'my gambier': 'mt gambier', // typo
  'charters towers': 'charters twrs',
  'paramatta': 'parramatta', // typo
  'crinulla': 'cronulla', // typo
  'cronulla beach': 'cronulla',
  'narree warren': 'narre warren', // typo
  'strathfueld': 'strathfield', // typo
  'rouse hill town centre': 'rouse hill',
  'dandening': 'dandenong', // typo
};

const FULL_STATE_NAMES: Record<string, string> = {
  'new south wales': 'NSW',
  'victoria': 'VIC',
  'queensland': 'QLD',
  'south australia': 'SA',
  'western australia': 'WA',
  'tasmania': 'TAS',
  'northern territory': 'NT',
  'australian capital territory': 'ACT',
};
const STATE_ABBR = ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'];

/**
 * Normalizes a sheet "Location" entry for matching: strips bracketed asides,
 * trailing state names/abbreviations (bare or parenthetical), stray periods
 * between letters ("Mt.Gambier" -> "Mt Gambier"), trailing punctuation, and a
 * short list of qualifier words that don't change which place is meant.
 */
export function normalizeLocationForMatch(raw: string | null | undefined): string {
  if (!raw) return '';
  let s = raw.trim();
  s = s.replace(/\s*\[[^\]]*\]\s*$/i, ''); // trailing "[main street]"
  s = s.replace(/\.(?=[A-Za-z])/g, ' '); // "Mt.Gambier" -> "Mt Gambier"
  s = s.replace(/([A-Za-z])(\d)/g, '$1 $2'); // "CBD1" -> "CBD 1"

  // Trailing parenthetical or bare state name/abbreviation, e.g. "(Vic)", "- Vic", "Victoria".
  const fullNamesPattern = Object.keys(FULL_STATE_NAMES).join('|');
  const stateTail = new RegExp(
    `[\\s,.\\-]*\\(?\\b(${STATE_ABBR.join('|')}|${fullNamesPattern})\\b\\)?\\.?\\s*$`,
    'i',
  );
  s = s.replace(stateTail, '');

  s = s.replace(/[.,-]\s*$/, '');
  s = s.replace(/\s+(update|shops?|shopping centre|main street|station)$/i, '');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

/** The key a location is stored/looked up under in campaign_report_location_aliases. */
export function locationKey(raw: string | null | undefined): string {
  return normalizeLocationForMatch(raw).toLowerCase();
}

const STATE_HINT = new RegExp(
  `(?:^|[\\s,.(\\-])(${STATE_ABBR.join('|')}|${Object.keys(FULL_STATE_NAMES).join('|')})\\)?\\.?\\s*$`,
  'i',
);

/**
 * The state a leader explicitly typed at the end of a location ("Brighton SA",
 * "Ayr Nth Qld", "Queanbeyan, NSW"), or null. This is the strongest signal we
 * have — stronger than a place-name match (the same name exists in several
 * states) and than the leader's usual state (leaders travel).
 */
export function extractStateHint(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const m = raw.trim().match(STATE_HINT);
  if (!m) return null;
  const token = m[1].toLowerCase();
  return FULL_STATE_NAMES[token] ?? m[1].toUpperCase();
}

/**
 * Normalizes a sheet "Campaign Leader" entry for matching: strips trailing
 * team-size annotations ("+2", "(+ 3)", ", 5") and a trailing co-leader
 * mention ("& Lanre", "and Josh"), leaving just the primary leader's name.
 */
export function normalizeLeaderForMatch(raw: string | null | undefined): string {
  if (!raw) return '';
  let s = raw.trim();
  s = s.replace(/\(?\s*[+&,]\s*\d+\s*\)?\s*$/i, ''); // trailing "+2" / "(+3)" / ", 5"
  s = s.replace(/\s*(&|and)\s+\S.*$/i, ''); // trailing "& Lanre" / "and Josh"
  return s.trim();
}

/**
 * Matches a normalized sheet location against state_places — by either the
 * row's physical `location` or its `place` label — trying (in order): an exact
 * match (after alias substitution), a forward prefix match (the typed text is
 * the base of a longer name, e.g. "Perth" -> "Perth CBD"), and a reverse prefix
 * match (the typed text carries an extra trailing descriptor beyond a real name,
 * e.g. "Perth CBD1" -> "Perth CBD"). Returns every candidate row so the caller
 * can resolve state/location together with the leader match — never picks a
 * "best guess" itself.
 */
export function matchPlace(locationRaw: string | null | undefined, places: PlaceRef[]): PlaceRef[] {
  const normalized = normalizeLocationForMatch(locationRaw);
  if (!normalized) return [];
  const key = (LOCATION_ALIASES[normalized.toLowerCase()] ?? normalized).toLowerCase();

  const names = (p: PlaceRef) => [p.place, p.location ?? ''].map((n) => n.trim().toLowerCase()).filter(Boolean);

  const exact = places.filter((p) => names(p).includes(key));
  if (exact.length) return exact;

  const forwardPrefix = places.filter((p) => names(p).some((n) => n.startsWith(`${key} `)));
  if (forwardPrefix.length) return forwardPrefix;

  const reversePrefix = places.filter((p) => names(p).some((n) => key.startsWith(`${n} `)));
  if (reversePrefix.length) return reversePrefix;

  return [];
}

/**
 * Matches a normalized leader name against state_leaders: an exact match
 * first, falling back to a first-name-only match (handles the sheet using a
 * fuller/shorter form than how the leader is stored, e.g. "Linda H" vs
 * "Linda", "Maria McCully" vs "Maria").
 */
export function matchLeader(leaderRaw: string | null | undefined, leaders: LeaderRef[]): LeaderRef[] {
  const normalized = normalizeLeaderForMatch(leaderRaw);
  if (!normalized) return [];
  const key = normalized.toLowerCase();

  const exact = leaders.filter((l) => l.leader.trim().toLowerCase() === key);
  if (exact.length) return exact;

  const firstToken = key.split(/\s+/)[0];
  const firstTokenMatches = leaders.filter(
    (l) => l.leader.trim().toLowerCase().split(/\s+/)[0] === firstToken,
  );
  if (firstTokenMatches.length) return firstTokenMatches;

  return [];
}

/**
 * Combines a place match and a leader match into a single derived
 * state/location/leader, requiring the two to agree when both resolve to a
 * state. Each of the three output fields is independently nulled out if it
 * can't be pinned to exactly one value. Several places sharing one physical
 * location (e.g. "Orange 1"/"Orange 2") resolve to that one location; a
 * resolvable state whose candidates span different locations still yields a
 * confident state with location left null.
 */
export function deriveCampaignReportFields(
  row: { location_raw: string | null; leader_raw: string | null },
  places: PlaceRef[],
  leaders: LeaderRef[],
  aliases: ReadonlyMap<string, LocationAliasRef> = new Map(),
): DerivedFields {
  const leaderCandidates = matchLeader(row.leader_raw, leaders);
  const pickLeader = (state: string): string | null => {
    const inState = leaderCandidates.filter((l) => l.state === state);
    return inState.length === 1 ? inState[0].leader : null;
  };

  // A confirmed alias (an admin's decision) beats every heuristic below.
  const alias = aliases.get(locationKey(row.location_raw));
  if (alias) return { state: alias.state, location: alias.location, leader: pickLeader(alias.state) };

  const hint = extractStateHint(row.location_raw);
  const allPlaceCandidates = matchPlace(row.location_raw, places);
  // An explicit state discards place matches in other states ("Brighton SA" is not NSW's "Brighton Le S").
  const placeCandidates = hint ? allPlaceCandidates.filter((p) => p.state === hint) : allPlaceCandidates;

  const placeStates = [...new Set(placeCandidates.map((p) => p.state))];
  const leaderStates = [...new Set(leaderCandidates.map((l) => l.state))];

  // A typed state is trusted outright. Otherwise a unique place match is
  // trusted (it's the stronger signal — a leader mismatch just means that name
  // wasn't resolvable, not that the place is wrong). No place match at all
  // falls back to a unique leader match. An *ambiguous* place (matches >1
  // state) is only resolved if the leader's state(s) narrow it down to exactly
  // one — a leader match to a state the place doesn't even support is a real
  // disagreement, not a tiebreak, so that yields no resolution.
  let state: string | null = null;
  if (hint) {
    state = hint;
  } else if (placeStates.length === 1) {
    state = placeStates[0];
  } else if (placeStates.length === 0) {
    if (leaderStates.length === 1) state = leaderStates[0];
  } else if (leaderStates.length >= 1) {
    const common = placeStates.filter((s) => leaderStates.includes(s));
    if (common.length === 1) state = common[0];
  }

  if (!state) return { state: null, location: null, leader: null };

  const locationsInState = distinctLocations(placeCandidates.filter((p) => p.state === state));
  return {
    state,
    location: locationsInState.length === 1 ? locationsInState[0] : null,
    leader: pickLeader(state),
  };
}

lib/campaignReportParser.ts:
/**
 * Parsing/normalization for the "Campaign Report" project — turning a raw row
 * from Jordan's Google Sheet export (docs/campaign-report/BRIEF.md) into a
 * `campaign_reports` row. Framework-agnostic (no xlsx/Supabase imports) so it
 * can be unit tested directly and reused by both the one-off initial-load
 * script and the later incremental catch-up script.
 *
 * Two real data-quality problems drive the shape of this module (see
 * docs/campaign-report/BRIEF.md for the full investigation):
 *
 * 1. The four tally columns (Partial/Full/Sinners Prayer/Information
 *    Requests) sometimes hold a leader's free-text note instead of a number
 *    ("Nil", "10(1 with 5 persons...)", or a full narrative). `parseTallyValue`
 *    extracts a leading number where possible and always preserves the
 *    original text in a paired `*_raw` field so nothing is silently lost.
 * 2. ~25% of the "Dates" (campaign date) column isn't a native Excel date —
 *    it's a human-typed string in a wide variety of formats ("18th September
 *    2021", "6.4.24", "2024.04.06", "August 7th", "9/9/21 & 10/9/21"), or
 *    occasionally a plain digit string with no separators at all ("20240914",
 *    "50222" — Excel dropped a leading zero from "050222"). `parseCampaignDate`
 *    recovers the common patterns; anything it can't confidently parse is
 *    left null with the original text preserved and `needsReview` set, per
 *    Peter's "keep + flag" decision (2026-08-30) rather than guessing.
 */

const ZERO_TOKENS = /^(nil|none|no|n\/a|na|o)\.?$/i;
const DASH_ONLY = /^[-—–]+$/;

export interface ParsedTally {
  /** Best-effort parsed integer, or null if the cell held no recognizable number. */
  value: number | null;
  /** Original cell text, preserved whenever it wasn't already a clean number. Null otherwise. */
  raw: string | null;
}

/**
 * Parses one of the four tally cells (Partial/Full/Sinners Prayer/Information
 * Requests). A clean number passes straight through. A recognized "zero" word
 * ("Nil", "None", "—", the letter "O") becomes 0. Text starting with a number
 * ("10(1 with 5 persons...)") extracts that leading number. Anything else
 * (a narrative note with no leading digit) yields value: null — the raw text
 * is kept so a human can review it, never discarded.
 */
export function parseTallyValue(cell: unknown): ParsedTally {
  if (typeof cell === 'number' && Number.isFinite(cell)) {
    return { value: Math.round(cell), raw: null };
  }
  if (cell === null || cell === undefined) return { value: null, raw: null };

  const text = String(cell).trim();
  if (!text) return { value: null, raw: null };

  if (ZERO_TOKENS.test(text) || DASH_ONLY.test(text)) {
    return { value: 0, raw: text };
  }

  const leadingNumber = text.match(/^-?\d+/);
  if (leadingNumber) {
    return { value: parseInt(leadingNumber[0], 10), raw: text };
  }

  return { value: null, raw: text };
}

export interface ParsedCampaignDate {
  /** YYYY-MM-DD, or null if unparseable. */
  date: string | null;
  /** Original cell text, preserved whenever the cell wasn't already a clean native date. */
  raw: string | null;
  /** True when the cell held something but it couldn't be confidently parsed into a date. */
  needsReview: boolean;
}

const MIN_YEAR = 2015;
const MAX_YEAR = 2036;

const MONTHS: Record<string, number> = {
  jan: 1, january: 1,
  feb: 2, february: 2,
  mar: 3, march: 3,
  apr: 4, april: 4,
  may: 5,
  jun: 6, june: 6,
  jul: 7, july: 7,
  aug: 8, august: 8,
  sep: 9, sept: 9, september: 9,
  oct: 10, october: 10,
  nov: 11, november: 11,
  dec: 12, december: 12,
};

function daysInMonth(year: number, month: number): number {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

function toIsoDate(year: number, month: number, day: number): string | null {
  if (month < 1 || month > 12) return null;
  if (day < 1 || day > daysInMonth(year, month)) return null;
  if (year < MIN_YEAR || year > MAX_YEAR) return null;
  return `${year.toString().padStart(4, '0')}-${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
}

function expandYear(y: number): number {
  return y < 100 ? 2000 + y : y;
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

// A "Campaign Report" is filed after the campaign it describes, so a future
// campaign_date is never legitimate — 45 days of slack covers any reporting
// delay. Past dates, though, genuinely run much later in this data: several
// leaders batch-submitted a full year of backlogged reports at once (real
// examples cluster at ~365-368 days late, correct date, just very late).
// Real *errors* on the past side are multiple years off (see BRIEF.md's
// 2026-09-01 investigation) — 400 days comfortably separates the two.
const MAX_FUTURE_DAYS = 45;
const MAX_PAST_DAYS = 400;

/** True if `iso` sits within a plausible reporting window of the submission timestamp. */
function isPlausibleRelativeToSubmission(iso: string, submittedAt: Date): boolean {
  const diffDays = (new Date(`${iso}T00:00:00Z`).getTime() - submittedAt.getTime()) / MS_PER_DAY;
  return diffDays <= MAX_FUTURE_DAYS && diffDays >= -MAX_PAST_DAYS;
}

/** Resolves a missing year against the submission date, correcting for a Dec-campaign/Jan-report crossing. */
function resolveYearlessDate(month: number, day: number, submittedAt: Date): string | null {
  const submittedYear = submittedAt.getFullYear();
  let iso = toIsoDate(submittedYear, month, day);
  if (iso && new Date(iso).getTime() - submittedAt.getTime() > MAX_FUTURE_DAYS * MS_PER_DAY) {
    // Resulting date is more than 45 days after the submission — almost
    // certainly a report filed after the new year for a prior-year campaign.
    iso = toIsoDate(submittedYear - 1, month, day);
  }
  return iso;
}

/** Strips leader-typed noise (day-of-week names, ordinal suffixes, "of", AM/PM) before pattern matching. */
function preprocessDateText(text: string): string {
  let s = text.trim();
  s = s.replace(/^(monday|tuesday|wednesday|thursday|friday|saturday|sunday|mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)[.,\s]+/i, '');
  s = s.replace(/\bof\b/gi, ' ');
  s = s.replace(/\b(am|pm)\b\.?/gi, '');
  s = s.replace(/(\d+)\s*(st|nd|rd|th)\b/gi, '$1');
  // Multi-date entries ("9/9/21 & 10/9/21", "10th and 11th Dec 2021") — take the first date.
  s = s.split(/\s*(?:&|\band\b)\s*/i)[0];
  // A leading day-range ("24/25 June", "19-20 December 2022", "10-13 Nov") — drop the second day.
  s = s.replace(/^(\d{1,2})[-/]\d{1,2}(\s+\D)/, '$1$2');
  s = s.replace(/\s*([./])\s*/g, '$1');
  s = s.replace(/\s+/g, ' ').trim().replace(/[.\s]+$/, '');
  return s;
}

/**
 * Parses the "Dates" (campaign date) cell. `submittedAt` (the sheet's own
 * "Date" submission-timestamp column, always present and clean) is used
 * both to resolve dates with no year and — for every successful parse,
 * regardless of source — as a plausibility check: a Campaign Report always
 * describes a campaign that already happened, so a candidate date wildly
 * far from its own submission timestamp (in either direction) is far more
 * likely a mistyped year than a real date, and is flagged instead of
 * trusted. See the MAX_FUTURE_DAYS/MAX_PAST_DAYS comment above and
 * BRIEF.md's 2026-09-01 investigation for the real examples that drove this.
 */
export function parseCampaignDate(cell: unknown, submittedAt: Date): ParsedCampaignDate {
  const accept = (iso: string, raw: string | null): ParsedCampaignDate =>
    isPlausibleRelativeToSubmission(iso, submittedAt)
      ? { date: iso, raw, needsReview: false }
      : { date: null, raw: raw ?? iso, needsReview: true };

  if (cell instanceof Date && !isNaN(cell.getTime())) {
    const iso = toIsoDate(cell.getFullYear(), cell.getMonth() + 1, cell.getDate());
    if (iso) return accept(iso, null);
    return { date: null, raw: cell.toDateString(), needsReview: true };
  }

  if (cell === null || cell === undefined) return { date: null, raw: null, needsReview: false };

  if (typeof cell === 'number' && Number.isFinite(cell)) {
    // Only trust the unambiguous case: an 8-digit YYYYMMDD typed as a plain
    // number (e.g. "20240914"). Anything shorter is ambiguous (a dropped
    // leading zero could mean several things) and gets flagged instead of
    // guessed — see BRIEF.md.
    const digits = Math.trunc(cell).toString();
    if (digits.length === 8) {
      const year = parseInt(digits.slice(0, 4), 10);
      const month = parseInt(digits.slice(4, 6), 10);
      const day = parseInt(digits.slice(6, 8), 10);
      const iso = toIsoDate(year, month, day);
      if (iso) return accept(iso, digits);
    }
    return { date: null, raw: String(cell), needsReview: true };
  }

  if (typeof cell !== 'string') return { date: null, raw: String(cell), needsReview: true };

  const original = cell.trim();
  if (!original) return { date: null, raw: null, needsReview: false };

  const text = preprocessDateText(original);

  // D.M.Y or Y.M.D (dot-separated numeric)
  let m = text.match(/^(\d{1,4})\.(\d{1,2})\.(\d{2,4})$/);
  if (m) {
    const [, a, month, c] = m;
    const iso = a.length === 4
      ? toIsoDate(parseInt(a, 10), parseInt(month, 10), parseInt(c, 10)) // Y.M.D
      : toIsoDate(expandYear(parseInt(c, 10)), parseInt(month, 10), parseInt(a, 10)); // D.M.Y
    if (iso) return accept(iso, original);
  }

  // D/M/Y or Y/M/D (slash-separated numeric)
  m = text.match(/^(\d{1,4})\/(\d{1,2})\/(\d{2,4})$/);
  if (m) {
    const [, a, month, c] = m;
    const iso = a.length === 4
      ? toIsoDate(parseInt(a, 10), parseInt(month, 10), parseInt(c, 10))
      : toIsoDate(expandYear(parseInt(c, 10)), parseInt(month, 10), parseInt(a, 10));
    if (iso) return accept(iso, original);
  }

  // "D Month[, Y]"
  m = text.match(/^(\d{1,2})\s+([A-Za-z]+)\.?,?\s*(\d{2,4})?$/);
  if (m) {
    const month = MONTHS[m[2].toLowerCase()];
    if (month) {
      const day = parseInt(m[1], 10);
      const iso = m[3] ? toIsoDate(expandYear(parseInt(m[3], 10)), month, day) : resolveYearlessDate(month, day, submittedAt);
      if (iso) return accept(iso, original);
    }
  }

  // "Month D[, Y]"
  m = text.match(/^([A-Za-z]+)\.?\s+(\d{1,2})\.?,?\s*(\d{2,4})?$/);
  if (m) {
    const month = MONTHS[m[1].toLowerCase()];
    if (month) {
      const day = parseInt(m[2], 10);
      const iso = m[3] ? toIsoDate(expandYear(parseInt(m[3], 10)), month, day) : resolveYearlessDate(month, day, submittedAt);
      if (iso) return accept(iso, original);
    }
  }

  return { date: null, raw: original, needsReview: true };
}

/** A raw row exactly as read from the "campaign report" sheet (see BRIEF.md for the column layout). */
export interface RawCampaignReportSheetRow {
  /** The sheet's "Date" column — Google Form submission timestamp. Always a clean datetime in every row seen so far. */
  submittedAt: unknown;
  location: unknown;
  leader: unknown;
  /** The sheet's "Dates" column — the actual campaign date. */
  campaignDate: unknown;
  partialPresentations: unknown;
  fullPresentations: unknown;
  sinnersPrayer: unknown;
  informationRequests: unknown;
}

/** Target shape for an insert into the `campaign_reports` table (scripts/create_campaign_reports_table.sql). */
export interface CampaignReportInsert {
  submitted_at: string;
  campaign_date: string | null;
  campaign_date_raw: string | null;
  location_raw: string | null;
  leader_raw: string | null;
  partial_presentations: number | null;
  partial_presentations_raw: string | null;
  full_presentations: number | null;
  full_presentations_raw: string | null;
  sinners_prayer: number | null;
  sinners_prayer_raw: string | null;
  information_requests: number | null;
  information_requests_raw: string | null;
  needs_review: boolean;
  source: string;
}

function toTrimmedTextOrNull(cell: unknown): string | null {
  if (cell === null || cell === undefined) return null;
  const text = String(cell).trim();
  return text || null;
}

/**
 * Normalizes one raw sheet row into a `campaign_reports` insert. Returns null
 * if `submittedAt` isn't a usable timestamp — that column is the row's unique
 * de-dup key (see BRIEF.md), so a row without one can't be loaded at all;
 * the caller is expected to log and skip it.
 */
export function normalizeCampaignReportRow(row: RawCampaignReportSheetRow): CampaignReportInsert | null {
  const submittedAt = row.submittedAt instanceof Date && !isNaN(row.submittedAt.getTime()) ? row.submittedAt : null;
  if (!submittedAt) return null;

  const date = parseCampaignDate(row.campaignDate, submittedAt);
  const partial = parseTallyValue(row.partialPresentations);
  const full = parseTallyValue(row.fullPresentations);
  const sinnersPrayer = parseTallyValue(row.sinnersPrayer);
  const informationRequests = parseTallyValue(row.informationRequests);

  const needsReview =
    date.needsReview ||
    (partial.value === null && partial.raw !== null) ||
    (full.value === null && full.raw !== null) ||
    (sinnersPrayer.value === null && sinnersPrayer.raw !== null) ||
    (informationRequests.value === null && informationRequests.raw !== null);

  return {
    submitted_at: submittedAt.toISOString(),
    campaign_date: date.date,
    campaign_date_raw: date.raw,
    location_raw: toTrimmedTextOrNull(row.location),
    leader_raw: toTrimmedTextOrNull(row.leader),
    partial_presentations: partial.value,
    partial_presentations_raw: partial.raw,
    full_presentations: full.value,
    full_presentations_raw: full.raw,
    sinners_prayer: sinnersPrayer.value,
    sinners_prayer_raw: sinnersPrayer.raw,
    information_requests: informationRequests.value,
    information_requests_raw: informationRequests.raw,
    needs_review: needsReview,
    source: 'jordan_sheet_import',
  };
}

lib/campaignReportSheetReader.ts:
/**
 * Campaign Report project — see docs/campaign-report/BRIEF.md.
 *
 * Reads the live Google Sheet (link-shared, "anyone with the link can view")
 * into the same raw-row shape `normalizeCampaignReportRow` already consumes.
 * No API key and no xlsx-parsing library (see scripts/campaign_reports_xlsx_to_json.py
 * for why those are avoided): two plain public endpoints are merged instead.
 *
 *  - `/export?format=csv` carries every cell's text, including the free-text
 *    notes leaders typed into date and tally columns.
 *  - `/gviz/tq?tqx=out:json` carries real types (true dates/numbers), but
 *    returns null for any cell whose type differs from its column's majority
 *    — so on its own it silently loses ~2,400 text cells.
 *
 * CSV supplies the text; gviz supplies the typed dates (which CSV can only
 * show as ambiguous display strings like "4/9/21"). Rows are aligned by
 * position, and every row's timestamp is cross-checked between the two
 * responses so a row added between the two requests fails loudly instead of
 * shifting data.
 *
 * Temporary by design: removed when the app's own campaign-report numbers
 * replace this sheet.
 */
import { parseCsv, stripBom } from '@/lib/registryPipeline/csvParse';
import type { RawCampaignReportSheetRow } from '@/lib/campaignReportParser';

/** The sheet's timestamps are wall-clock times in this zone (matches the 2021-2026 historical load). */
export const SHEET_TIME_ZONE = 'Australia/Melbourne';

const CSV_TIMESTAMP = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/;
const GVIZ_DATE = /^Date\((\d+),(\d+),(\d+)(?:,(\d+),(\d+),(\d+))?(?:,\d+)?\)$/;
const PLAIN_NUMBER = /^-?\d+(\.\d+)?$/;

/** Offset (ms, east of UTC) of `zone` at the instant `utcMs`. */
function zoneOffsetMs(utcMs: number, zone: string): number {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone, hourCycle: 'h23',
    year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric',
  }).formatToParts(new Date(utcMs));
  const get = (type: string) => Number(parts.find((p) => p.type === type)!.value);
  const asUtc = Date.UTC(get('year'), get('month') - 1, get('day'), get('hour'), get('minute'), get('second'));
  return asUtc - Math.floor(utcMs / 1000) * 1000;
}

/** Converts a wall-clock time in `zone` to the real instant, whatever zone the server itself runs in. */
export function wallClockToDate(
  y: number, mo: number, d: number, h: number, mi: number, s: number,
  zone: string = SHEET_TIME_ZONE,
): Date {
  const naive = Date.UTC(y, mo - 1, d, h, mi, s);
  let result = naive - zoneOffsetMs(naive, zone);
  // Re-check at the candidate instant so a time just either side of a DST change resolves correctly.
  result = naive - zoneOffsetMs(result, zone);
  return new Date(result);
}

export interface GvizCell { v?: unknown; f?: string }
export type GvizRow = { c: (GvizCell | null)[] };

/** Strips Google's JSONP wrapper from a gviz response and returns its rows. */
export function parseGvizRows(body: string): GvizRow[] {
  const start = body.indexOf('(');
  const end = body.lastIndexOf(')');
  if (start < 0 || end < start) throw new Error('Unexpected Google Sheets response (not a gviz payload)');
  const json = JSON.parse(body.slice(start + 1, end));
  if (json.status !== 'ok') throw new Error(`Google Sheets returned status "${json.status}"`);
  return json.table.rows as GvizRow[];
}

function gvizValue(cell: GvizCell | null | undefined): unknown {
  return cell && cell.v !== undefined ? cell.v : null;
}

/** A gviz `Date(y,m,d[,h,mi,s])` string as its components (month is 1-based here), or null. */
function parseGvizDate(v: unknown): number[] | null {
  if (typeof v !== 'string') return null;
  const m = v.match(GVIZ_DATE);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]) + 1, Number(m[3]), Number(m[4] ?? 0), Number(m[5] ?? 0), Number(m[6] ?? 0)];
}

function csvText(cells: string[], index: number): string | null {
  const t = cells[index];
  return t === undefined || t.trim() === '' ? null : t;
}

/** A tally: gviz's exact number when it has one, otherwise the CSV text (a number written out, or a typed note). */
function tally(gviz: GvizCell | null | undefined, csv: string | null): unknown {
  const v = gvizValue(gviz);
  if (typeof v === 'number') return v;
  if (csv !== null && PLAIN_NUMBER.test(csv.trim())) return Number(csv.trim());
  return csv;
}

/**
 * Merges the CSV and gviz exports into raw sheet rows (header row excluded,
 * fully blank rows dropped). Throws if the two responses don't line up row
 * for row — a sheet edited mid-fetch — so the caller can simply retry.
 */
export function mergeSheetExports(csvBody: string, gvizBody: string): RawCampaignReportSheetRow[] {
  const csvRows = parseCsv(stripBom(csvBody)).slice(1);
  const gvizRows = parseGvizRows(gvizBody);
  if (csvRows.length !== gvizRows.length) {
    throw new Error(`Sheet changed while reading (${csvRows.length} CSV rows vs ${gvizRows.length} typed rows) — retry`);
  }

  const out: RawCampaignReportSheetRow[] = [];
  gvizRows.forEach((g, i) => {
    const cells = csvRows[i];
    if (cells.every((c) => c.trim() === '')) return;

    // Column A: the submission timestamp, the row's de-dup key.
    const csvStamp = csvText(cells, 0);
    const gvizStamp = g.c[0]?.f ?? null;
    if (csvStamp !== null && gvizStamp !== null && csvStamp.trim() !== gvizStamp) {
      throw new Error(`Sheet changed while reading (row ${i + 2} timestamp mismatch) — retry`);
    }
    const stamp = parseGvizDate(gvizValue(g.c[0])) ?? csvStamp?.trim().match(CSV_TIMESTAMP)?.slice(1).map(Number) ?? null;
    const submittedAt = stamp ? wallClockToDate(stamp[0], stamp[1], stamp[2], stamp[3], stamp[4], stamp[5]) : null;

    // Column D: the campaign date — a true date when the cell is one, else whatever was typed.
    const dateParts = parseGvizDate(gvizValue(g.c[3]));
    // Built from local parts on purpose: the parser reads getFullYear()/getMonth()/getDate().
    // A digit-only entry (e.g. 20240203) was a plain number in the sheet, which the parser treats differently from text.
    const dateText = csvText(cells, 3);
    const campaignDate = dateParts
      ? new Date(dateParts[0], dateParts[1] - 1, dateParts[2])
      : dateText !== null && /^\d+$/.test(dateText.trim()) ? Number(dateText.trim()) : dateText;

    out.push({
      submittedAt,
      location: csvText(cells, 1),
      leader: csvText(cells, 2),
      campaignDate,
      partialPresentations: tally(g.c[4], csvText(cells, 4)),
      fullPresentations: tally(g.c[5], csvText(cells, 5)),
      sinnersPrayer: tally(g.c[6], csvText(cells, 6)),
      informationRequests: tally(g.c[7], csvText(cells, 7)),
    });
  });
  return out;
}

/** Downloads both exports of a link-shared sheet and merges them. */
export async function fetchCampaignReportSheetRows(
  sheetId: string,
  fetchImpl: typeof fetch = fetch,
): Promise<RawCampaignReportSheetRow[]> {
  const base = `https://docs.google.com/spreadsheets/d/${encodeURIComponent(sheetId)}`;
  const [csvRes, gvizRes] = await Promise.all([
    fetchImpl(`${base}/export?format=csv`, { cache: 'no-store' }),
    fetchImpl(`${base}/gviz/tq?tqx=out:json`, { cache: 'no-store' }),
  ]);
  if (!csvRes.ok || !gvizRes.ok) {
    throw new Error(`Google Sheet fetch failed (CSV ${csvRes.status}, typed ${gvizRes.status}) — is it still shared with "anyone with the link"?`);
  }
  return mergeSheetExports(await csvRes.text(), await gvizRes.text());
}

lib/campaignRules.ts:
/**
 * Campaign Rules Engine
 *
 * Evaluates campaign rules and generates campaign records based on scheduling patterns.
 */

import type { CampaignRule, RuleConfig } from '@/lib/types';

export interface GeneratedCampaign {
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
  mobile: string | null;
  category: string;
  rule_id: string;
}

/**
 * Find the Nth occurrence of a given day-of-week within each month in the range,
 * or the last occurrence when weekNumber === -1.
 *
 * Fix vs. previous implementation: the old algorithm subtracted firstDayOfWeek from
 * the week offset, which could produce a date in the prior month that then failed the
 * month-boundary check — silently dropping valid first-week dates. This version uses
 * the correct "find first occurrence, add (N-1)*7" approach.
 */
function findMonthlyOccurrences(
  weekNumber: number,
  dayOfWeek: number | null,
  startDate: Date,
  endDate: Date
): Date[] {
  if (dayOfWeek === null) return []; // required field; guard defensively

  const matches: Date[] = [];
  // Start iterating from the first day of startDate's month.
  const cursor = new Date(startDate.getFullYear(), startDate.getMonth(), 1);

  while (cursor <= endDate) {
    const year = cursor.getFullYear();
    const month = cursor.getMonth();

    let targetDate: Date | null = null;

    if (weekNumber === -1) {
      // Last occurrence of dayOfWeek in the month.
      const lastDay = new Date(year, month + 1, 0);
      let daysBack = lastDay.getDay() - dayOfWeek;
      if (daysBack < 0) daysBack += 7;
      targetDate = new Date(year, month, lastDay.getDate() - daysBack);
    } else {
      // Nth occurrence (1–4): find first occurrence of dayOfWeek, then add (N-1) weeks.
      const firstDayOfMonth = new Date(year, month, 1).getDay();
      let daysToFirst = dayOfWeek - firstDayOfMonth;
      if (daysToFirst < 0) daysToFirst += 7;
      const nthDay = 1 + daysToFirst + (weekNumber - 1) * 7;
      const daysInMonth = new Date(year, month + 1, 0).getDate();
      if (nthDay <= daysInMonth) {
        targetDate = new Date(year, month, nthDay);
      }
    }

    if (targetDate && targetDate >= startDate && targetDate <= endDate) {
      matches.push(targetDate);
    }

    cursor.setMonth(cursor.getMonth() + 1);
  }

  return matches;
}

/**
 * Find all dates matching a weekly pattern within the given range.
 */
function findWeeklyOccurrences(
  dayOfWeek: number,
  startDate: Date,
  endDate: Date
): Date[] {
  const matches: Date[] = [];
  const current = new Date(startDate);

  // Advance to the first occurrence of dayOfWeek on or after startDate.
  const diff = (dayOfWeek - current.getDay() + 7) % 7;
  current.setDate(current.getDate() + diff);

  while (current <= endDate) {
    matches.push(new Date(current));
    current.setDate(current.getDate() + 7);
  }

  return matches;
}

/**
 * Whole calendar days between two local-midnight dates (b - a), DST-safe.
 *
 * Fix: raw millisecond subtraction between two local-midnight Dates is off by however many
 * DST transitions fall between them (a 1-hour spring-forward/fall-back shifts the real ms
 * gap away from an exact multiple of 86400000). Diffing at local noon instead of midnight
 * keeps a wide enough margin that a ±1h shift can never flip the rounded day count.
 */
function daysBetweenLocalDates(a: Date, b: Date): number {
  const noonA = new Date(a.getFullYear(), a.getMonth(), a.getDate(), 12);
  const noonB = new Date(b.getFullYear(), b.getMonth(), b.getDate(), 12);
  return Math.round((noonB.getTime() - noonA.getTime()) / (24 * 60 * 60 * 1000));
}

/**
 * Find ALL dates matching a biweekly pattern within the given range.
 *
 * Fix vs. previous implementation: the old function always returned at most one result,
 * which worked by accident for the 14-day cron window but would silently produce
 * incomplete results for any wider evaluation window (e.g. the live "first campaign"
 * preview or any future wider-range query).
 *
 * Uses referenceDate (a known past occurrence) to anchor the repeating pattern so the
 * cycle stays consistent across cron runs. Falls back to the first matching dayOfWeek
 * on or after startDate when no reference is available.
 *
 * Fix: occurrences are stepped with `setDate()` (calendar-day arithmetic), never with raw
 * millisecond offsets — a millisecond-based step drifts by an hour across any DST
 * transition inside the range, which showed up as a real one-day-early result for a rule
 * whose period crossed the early-April AEDT→AEST changeover.
 */
function findBiweeklyOccurrences(
  frequencyValue: number,
  dayOfWeek: number,
  startDate: Date,
  endDate: Date,
  referenceDate: string | null
): Date[] {
  const matches: Date[] = [];
  const periodDays = frequencyValue * 7;

  const normStart = new Date(startDate); normStart.setHours(0, 0, 0, 0);
  const normEnd   = new Date(endDate);   normEnd.setHours(23, 59, 59, 999);

  // Establish an anchor: any confirmed occurrence of this biweekly pattern.
  let anchor: Date;
  if (referenceDate) {
    const [y, m, d] = referenceDate.split('-').map(Number);
    anchor = new Date(y, m - 1, d);
    anchor.setHours(0, 0, 0, 0);
    // Correct day-of-week if the stored reference doesn't match (defensive).
    if (anchor.getDay() !== dayOfWeek) {
      anchor.setDate(anchor.getDate() + (dayOfWeek - anchor.getDay() + 7) % 7);
    }
  } else {
    // No reference: the first dayOfWeek on or after normStart becomes the anchor.
    anchor = new Date(normStart);
    anchor.setDate(anchor.getDate() + (dayOfWeek - anchor.getDay() + 7) % 7);
  }

  // Walk the anchor to the first occurrence at or after normStart in one jump, using a
  // DST-safe day count rather than a millisecond period. `daysToStart` may be negative
  // (anchor after normStart) — ceil still finds the smallest valid `periods` in both
  // directions, e.g. ceil(-40/28) = -1 steps anchor back exactly one period.
  const daysToStart = daysBetweenLocalDates(anchor, normStart);
  const periods = Math.ceil(daysToStart / periodDays);
  const firstInRange = new Date(anchor);
  firstInRange.setDate(firstInRange.getDate() + periods * periodDays);

  // Collect every occurrence from firstInRange to normEnd.
  let current = new Date(firstInRange);
  while (current <= normEnd) {
    matches.push(new Date(current));
    current = new Date(current);
    current.setDate(current.getDate() + periodDays);
  }

  return matches;
}

/**
 * Returns true if `date` falls within the rule's start_date / end_date window.
 *
 * Fix vs. previous implementation: date-only strings (YYYY-MM-DD) are parsed by
 * the JS Date constructor as UTC midnight, but campaign dates are local midnight.
 * In AEST (UTC+10) the 10-hour gap caused boundary-day campaigns to be incorrectly
 * excluded. Appending 'T00:00:00' forces local-time parsing.
 */
function isDateInRange(date: Date, startDate: string | null, endDate: string | null): boolean {
  if (startDate && date < new Date(startDate + 'T00:00:00')) return false;
  if (endDate   && date > new Date(endDate   + 'T00:00:00')) return false;
  return true;
}

/**
 * Returns true if `date` appears in the rule's exceptions list.
 */
function isDateExcepted(date: Date, ruleConfig: RuleConfig): boolean {
  if (!ruleConfig?.exceptions?.length) return false;
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return ruleConfig.exceptions.includes(`${y}-${m}-${d}`);
}

/**
 * Evaluate a single rule and return generated campaign records for the given period.
 */
export function evaluateRule(
  rule: CampaignRule,
  targetStartDate: Date,
  targetEndDate: Date
): GeneratedCampaign[] {
  if (!rule.is_active) return [];
  // Defence in depth against a blank-leader rule row (rulesService rejects these at
  // create/update time — see assertLeaderPresent — but this guard also stops any rule
  // already sitting in the DB with a blank leader from continuing to silently spawn
  // blank-leader campaigns on every future weekly refresh).
  if (!rule.leader?.trim()) return [];

  let matchingDates: Date[] = [];

  switch (rule.frequency_type) {
    case 'monthly':
      // Both fields are required; month_day_of_week was made required in the UI
      // (was previously optional and silently fell back to Monday).
      if (rule.month_week_number === null || rule.month_day_of_week === null) return [];
      matchingDates = findMonthlyOccurrences(
        rule.month_week_number,
        rule.month_day_of_week,
        targetStartDate,
        targetEndDate
      );
      break;

    case 'biweekly': {
      if (rule.day_of_week === null || rule.frequency_value === null) return [];
      const refDate = rule.rule_config?.reference_date ?? null;
      matchingDates = findBiweeklyOccurrences(
        rule.frequency_value,
        rule.day_of_week,
        targetStartDate,
        targetEndDate,
        refDate
      );
      break;
    }

    case 'weekly':
      if (rule.day_of_week === null) return [];
      matchingDates = findWeeklyOccurrences(
        rule.day_of_week,
        targetStartDate,
        targetEndDate
      );
      break;

    case 'custom':
      // 'custom' rules are no longer creatable via the UI and cannot generate campaigns.
      // Legacy rows of this type are preserved in the DB but silently skipped here.
      return [];

    default:
      return [];
  }

  // Filter by the rule's own active date window and exception list.
  const validDates = matchingDates.filter(
    date => isDateInRange(date, rule.start_date, rule.end_date) && !isDateExcepted(date, rule.rule_config)
  );

  // Build campaign records.
  return validDates.map(date => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const dateStr = `${y}-${m}-${d}`;

    const overrideFields = rule.rule_config?.override_fields?.[dateStr] ?? {};

    return {
      date:     dateStr,
      state:    rule.state,
      place:    rule.place,
      site:     rule.site,
      time:     typeof overrideFields.time === 'string' ? overrideFields.time : rule.time,
      leader:   rule.leader,
      mobile:   rule.mobile,
      category: 'TWOL',
      rule_id:  rule.id,
    };
  });
}

/**
 * Evaluate multiple rules for a period and return deduplicated campaigns.
 * Conflicts (same date/state/place/time) are resolved by priority — higher wins.
 */
export function evaluateRules(
  rules: CampaignRule[],
  targetStartDate: Date,
  targetEndDate: Date
): GeneratedCampaign[] {
  const sortedRules = [...rules].sort((a, b) => b.priority - a.priority);
  const seen = new Map<string, GeneratedCampaign>();
  const all: GeneratedCampaign[] = [];

  for (const rule of sortedRules) {
    for (const campaign of evaluateRule(rule, targetStartDate, targetEndDate)) {
      const key = `${campaign.date}_${campaign.state}_${campaign.place}_${campaign.site}_${campaign.time}`;
      if (!seen.has(key)) {
        seen.set(key, campaign);
        all.push(campaign);
      }
    }
  }

  return all;
}

/**
 * Preview rule evaluation for a date range.
 * Returns both the raw Date objects and the full GeneratedCampaign records.
 */
export function previewRuleEvaluation(
  rule: CampaignRule,
  previewStartDate: Date,
  previewEndDate: Date
): { dates: Date[]; campaigns: GeneratedCampaign[] } {
  const campaigns = evaluateRule(rule, previewStartDate, previewEndDate);
  const dates = campaigns.map(c => new Date(c.date + 'T00:00:00'));
  return { dates, campaigns };
}

lib/campaignUtils.ts:
/**
 * Shared utility functions for campaign data formatting and parsing
 */
import { formatSlideDateText } from '@/lib/slideLayout';

/**
 * Parse campaign time string (HH:MM or HH:MM:SS or ISO timestamp) and return as display string (e.g. "2:30 PM")
 */
export function formatCampaignTimeDisplay(timeStr: string): string {
  let clean = timeStr;
  if (timeStr.includes('T')) {
    clean = timeStr.split('T')[1]?.split('.')[0] ?? timeStr;
  }
  const [hours, minutes] = (clean || '0:0').split(':');
  const hour = parseInt(hours || '0', 10);
  const ampm = hour >= 12 ? 'PM' : 'AM';
  const displayHour = hour % 12 || 12;
  return `${displayHour}:${minutes ?? '00'} ${ampm}`;
}

/**
 * Check if a campaign's date+time is in the past
 */
export function isCampaignPast(date: string, time: string): boolean {
  const campaignDate = new Date(date);
  let timeStr = time;
  if (timeStr.includes('T')) {
    timeStr = timeStr.split('T')[1]?.split('.')[0] || timeStr;
  }
  const [hours, minutes] = (timeStr || '0:0').split(':').map(Number);
  campaignDate.setHours(hours || 0, minutes || 0, 0, 0);
  return campaignDate < new Date();
}

/**
 * Combines a campaign's date and time into a single readable line, e.g.
 * "Saturday 12th July 10:00 AM" — used in map marker popups to show a
 * campaign's date/time without a separate date/time split.
 */
export function formatCampaignDateTimeDisplay(date: string, time: string): string {
  const [y, m, d] = date.split('-').map(Number);
  const dateText = formatSlideDateText(new Date(y, m - 1, d));
  const timeText = formatCampaignTimeDisplay(time);
  return `${dateText} ${timeText}`;
}

/**
 * Returns a copy of the list sorted by date, then time — used by map popups
 * that list every campaign at a place, not just the first. Sorts explicitly
 * rather than trusting array order, since getCampaignsByDateRange only
 * guarantees ordering by date, not by time within a date.
 */
export function sortCampaignsChronologically<T extends { date: string; time: string }>(campaigns: T[]): T[] {
  return [...campaigns].sort((a, b) => (a.date === b.date ? a.time.localeCompare(b.time) : a.date.localeCompare(b.date)));
}

/**
 * Returns the chronologically earliest campaign in a list (by date, then
 * time), or undefined for an empty list.
 */
export function getEarliestCampaign<T extends { date: string; time: string }>(campaigns: T[]): T | undefined {
  return campaigns.reduce<T | undefined>((earliest, c) => {
    if (!earliest) return c;
    if (c.date !== earliest.date) return c.date < earliest.date ? c : earliest;
    return c.time < earliest.time ? c : earliest;
  }, undefined);
}

lib/clickSendClient.ts:
/**
 * ClickSend SMS adapter for the "text the leader" notification
 * (lib/services/campaignInterestSmsService.ts) — thin wiring only, same role
 * as supabase/functions/ac-sync/emailClient.ts for Resend.
 *
 * Requires CLICKSEND_USERNAME and CLICKSEND_API_KEY (see README.md).
 * Always throws on failure to send — including missing config — rather than
 * swallowing it, so the single try/catch in campaignInterestSmsService.ts is
 * the one place responsible for logging every outcome to
 * campaign_interest_sms_log. A silently-swallowed failure here is exactly
 * the mistake registry.whatsapp_invite_log's own EmailPort used to make
 * before being fixed to always throw — see that file's comment.
 */

const CLICKSEND_SEND_URL = 'https://rest.clicksend.com/v3/sms/send';

export async function sendSms(toE164: string, body: string): Promise<{ messageId: string | null }> {
  const username = process.env.CLICKSEND_USERNAME;
  const apiKey = process.env.CLICKSEND_API_KEY;
  if (!username || !apiKey) {
    throw new Error('CLICKSEND_USERNAME/CLICKSEND_API_KEY is not set');
  }

  const res = await fetch(CLICKSEND_SEND_URL, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${Buffer.from(`${username}:${apiKey}`).toString('base64')}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ messages: [{ source: 'campaign-app', to: toE164, body }] }),
  });

  const payload: unknown = await res.json().catch(() => null);

  if (!res.ok) {
    const message = payload && typeof payload === 'object' && 'response_msg' in payload
      ? String((payload as { response_msg: unknown }).response_msg)
      : `ClickSend request failed with status ${res.status}`;
    throw new Error(message);
  }

  const messageStatus = (payload as { data?: { messages?: { status?: string; message_id?: string }[] } } | null)
    ?.data?.messages?.[0];
  if (messageStatus?.status && messageStatus.status !== 'SUCCESS') {
    throw new Error(`ClickSend rejected the message: ${messageStatus.status}`);
  }

  return { messageId: messageStatus?.message_id ?? null };
}

