lib/corsUtils.ts:
/**
 * CORS origin enforcement for internal API routes.
 *
 * Browser same-origin requests send an Origin header matching the app's host.
 * Cross-origin requests (from other domains) send a mismatched Origin.
 * Server-to-server requests (cron, internal services) send no Origin at all.
 *
 * Call enforceOrigin() at the top of any route handler that should only be
 * reachable from the app itself. Returns a 403 NextResponse if the request is
 * cross-origin, or null if it should proceed.
 *
 * Note: CORS is a browser security feature. It does not prevent non-browser
 * clients (curl, scripts) from calling the endpoint — other auth mechanisms
 * (Bearer token, CRON_SECRET) cover that case.
 */
import { NextRequest, NextResponse } from 'next/server';

export function enforceOrigin(request: NextRequest): NextResponse | null {
  const origin = request.headers.get('origin');

  // No Origin header → same-origin browser request or server-to-server → allow.
  if (!origin) return null;

  const host = request.headers.get('host') ?? '';

  try {
    const originHost = new URL(origin).host;
    if (originHost === host) return null; // Origins match → allow.
  } catch {
    // Malformed Origin header — treat as cross-origin.
  }

  return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
}

lib/emailConfirmSupabaseClient.ts:
/**
 * Supabase browser client shared by /confirm-email and /setup-mfa — both
 * need the identical "isolated session to prove identity via magic link,
 * then sign out" shape, so this file is reused rather than adding a third
 * near-duplicate of lib/registrySupabaseClient.ts's own isolated-client
 * pattern.
 *
 * A SEPARATE client instance from lib/supabaseClient.ts, pointed at the same
 * Supabase project but with its own localStorage key — exactly mirroring
 * lib/registrySupabaseClient.ts, and for the same reason: without this,
 * detecting the magic-link session here would overwrite the leader's real
 * anonymous app session in the shared storage slot, and this page's own
 * signOut() (see app/confirm-email/page.tsx) would then destroy it —
 * logging them out of the app entirely.
 *
 * `detectSessionInUrl: true` lets the SDK's own client-side URL detection
 * pick up the session on this page — this project's magic-link flow is the
 * implicit (#access_token=... hash) shape, not PKCE (?code=...), confirmed
 * live for /registry (see registrySupabaseClient.ts's own header comment).
 * The page must never parse the URL or call exchangeCodeForSession() itself;
 * it just waits for the SDK to finish and fire SIGNED_IN.
 */
import { createClient } from '@supabase/supabase-js';
import { createNonBlockingAuthLock } from './supabaseLock';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

if (!supabaseUrl || !supabaseAnonKey) {
  console.warn('Supabase environment variables are not set (emailConfirmSupabaseClient)');
}

export const emailConfirmSupabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    storageKey: 'afj-email-confirm-auth',
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storage: typeof window !== 'undefined' ? window.localStorage : undefined,
    lock: createNonBlockingAuthLock(), // never wait forever on a stuck tab — see lib/supabaseLock.ts
  },
});

lib/emailLoginPreference.ts:
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';

/**
 * Remembers, per browser, that this device signs in via email + 2FA
 * (app/login/mfa), so /login can skip its mobile+name form instead of making
 * a returning visitor click through to it. Set by app/login/mfa/callback/page.tsx
 * after a successful sign-in; never cleared on sign-out (same precedent as /login's
 * remembered mobile/name).
 *
 * Two strengths, because the two kinds of leader differ:
 *  - 'always' — an admin (AD/SR). They cannot use mobile+name at all, so every
 *    signed-out visit to /login goes straight to email sign-in.
 *  - 'when-required' — any other leader. Mobile+name still works for them (it
 *    just can't show members' personal details), so /login keeps showing it by
 *    default; the email sign-in is only skipped to when they arrive from the
 *    "extra security needed" screen (/login?require2fa=1). Before this, a plain
 *    leader who had tried 2FA once was bounced to email sign-in on every
 *    sign-out (reported 2026-10-13, testing PVTester).
 * An older marker (the literal '1', written before there were two strengths) reads
 * as 'when-required' — the safe reading, since an admin simply sees the mobile+name
 * screen once, is pointed at email sign-in, and the next email sign-in upgrades it.
 */
export const PREFERS_EMAIL_MFA_LOGIN_KEY = 'afj_prefers_email_mfa_login';

const ALWAYS = 'always';
const WHEN_REQUIRED = 'when-required';

/** Records a completed email + 2FA sign-in as the given leader row. Never weakens an existing 'always'. */
export function rememberEmailLogin(admin: string | null): void {
  try {
    const current = localStorage.getItem(PREFERS_EMAIL_MFA_LOGIN_KEY);
    const strength = isRecognizedAdminStatus(admin) || current === ALWAYS ? ALWAYS : WHEN_REQUIRED;
    localStorage.setItem(PREFERS_EMAIL_MFA_LOGIN_KEY, strength);
  } catch { /* ignore (e.g. private browsing) */ }
}

/** Whether /login should send a signed-out visitor straight to email sign-in. */
export function shouldSkipToEmailLogin(options: { requireTwoFactor: boolean }): boolean {
  try {
    const stored = localStorage.getItem(PREFERS_EMAIL_MFA_LOGIN_KEY);
    if (!stored) return false;
    return stored === ALWAYS || options.requireTwoFactor;
  } catch {
    return false;
  }
}

lib/errorUtils.ts:
/**
 * Centralized error handling utilities
 */

/**
 * Safely extract a user-facing error message from an unknown error.
 *
 * Handles three shapes that all occur in practice:
 *   1. Native Error instances — return .message
 *   2. Plain strings — return as-is
 *   3. PostgrestError / Supabase-thrown errors — plain objects with .message,
 *      .code, .details, .hint. These do NOT pass `instanceof Error`, so
 *      without explicit handling the fallback ("An unexpected error occurred")
 *      was being returned for every Supabase error, hiding the real cause.
 */
export function getErrorMessage(err: unknown, fallback = 'An unexpected error occurred'): string {
  if (err instanceof Error) {
    return err.message;
  }
  if (typeof err === 'string') {
    return err;
  }
  if (err && typeof err === 'object') {
    const e = err as { message?: unknown; code?: unknown; details?: unknown; hint?: unknown };
    const parts: string[] = [];
    if (typeof e.message === 'string' && e.message) parts.push(e.message);
    if (typeof e.code    === 'string' && e.code)    parts.push(`code: ${e.code}`);
    if (typeof e.details === 'string' && e.details) parts.push(`details: ${e.details}`);
    if (typeof e.hint    === 'string' && e.hint)    parts.push(`hint: ${e.hint}`);
    if (parts.length) return parts.join(' | ');
  }
  return fallback;
}

lib/geocoding.ts:
/**
 * Thin wrapper around the free Nominatim (OpenStreetMap) geocoding API.
 * Nominatim's usage policy caps requests at 1/sec, so callers must serialize lookups.
 */

export interface GeocodeResult {
  latitude: number;
  longitude: number;
}

/** Geocode a "place, state" pair within Australia. Returns null if no match is found. */
export async function geocodePlace(place: string, state: string): Promise<GeocodeResult | null> {
  const query = `${place}, ${state}, Australia`;
  return queryNominatim(query);
}

export interface AddressGeocodeResult extends GeocodeResult {
  /** Human-readable address Nominatim resolved the query to — useful for confirming the match. */
  displayName: string;
}

/**
 * Geocode an arbitrary free-form address within Australia.
 * Used by the "Campaigns Near Me" map when the user types an address instead of
 * relying on browser geolocation.
 */
export async function geocodeAddress(address: string): Promise<AddressGeocodeResult | null> {
  const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=au&q=${encodeURIComponent(address)}`;

  const response = await fetch(url, {
    headers: {
      'Accept-Language': 'en',
      'User-Agent': 'campaign-app (campaigns near me feature)',
    },
    signal: AbortSignal.timeout(8000),
  }).catch(() => null);
  if (!response || !response.ok) return null;

  const results = (await response.json()) as Array<{ lat: string; lon: string; display_name: string }>;
  if (results.length === 0) return null;

  const { lat, lon, display_name } = results[0];
  return { latitude: parseFloat(lat), longitude: parseFloat(lon), displayName: display_name };
}

async function queryNominatim(query: string): Promise<GeocodeResult | null> {
  const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=au&q=${encodeURIComponent(query)}`;

  const response = await fetch(url, {
    headers: {
      'Accept-Language': 'en',
      // Nominatim's usage policy requires a descriptive User-Agent identifying the app.
      'User-Agent': 'campaign-app (admin campaign map feature)',
    },
    // Guards against a slow or unreachable Nominatim from hanging the map indefinitely.
    signal: AbortSignal.timeout(8000),
  }).catch(() => null);
  if (!response || !response.ok) return null;

  const results = (await response.json()) as Array<{ lat: string; lon: string }>;
  if (results.length === 0) return null;

  const { lat, lon } = results[0];
  return { latitude: parseFloat(lat), longitude: parseFloat(lon) };
}

lib/isIosDevice.ts:
/**
 * True on an iPhone, iPod or iPad. The authenticator setup screen uses it to
 * lead with the typed setup key: on iOS an `otpauth://` link is as likely to
 * open Apple's Passwords app (or nothing) as Google/Microsoft Authenticator,
 * and a QR code on the phone's own screen can't be scanned (Mark, an admin on
 * iPhone, couldn't complete setup this way, 2026-10-19). iPadOS 13+ reports
 * itself as a Mac, so a "Mac" with a touch screen counts too.
 */
export function isIosDevice(nav: Pick<Navigator, 'userAgent' | 'platform' | 'maxTouchPoints'> | undefined =
  typeof navigator === 'undefined' ? undefined : navigator): boolean {
  if (!nav) return false;
  if (/iPhone|iPad|iPod/i.test(nav.userAgent)) return true;
  return nav.platform === 'MacIntel' && nav.maxTouchPoints > 1;
}

