}

lib/leaderShares.ts:
import { supabase } from './supabaseClient';
import { normalizeName, normalizeMobile } from './auth';
import type { LeaderShareOwner } from '@/lib/types';

export type { LeaderShareOwner };

/**
 * Get the list of (owner_state, owner_leader) who have shared their campaigns with the given leader.
 * Use this to load "shared with me" campaigns: campaigns where (state, leader) is in this list.
 */
export async function getSharedWithMeOwners(
  myState: string,
  myLeader: string
): Promise<LeaderShareOwner[]> {
  if (!myState?.trim() || !myLeader?.trim()) return [];
  const normalizedState = myState.toUpperCase().trim();
  const myLeaderNorm = normalizeName(myLeader);
  const { data, error } = await supabase
    .from('leader_shares')
    .select('owner_state, owner_leader, shared_with_leader')
    .eq('shared_with_state', normalizedState);

  if (error) {
    console.error('getSharedWithMeOwners:', error);
    return [];
  }
  return (data || [])
    .filter((r) => normalizeName(r.shared_with_leader || '') === myLeaderNorm)
    .map((r) => ({
      owner_state: r.owner_state,
      owner_leader: r.owner_leader,
    }));
}

/**
 * Check if the current user (myState, myLeader, myMobile) can access a campaign
 * (campaignState, campaignLeader, campaignMobile). Returns true if:
 * - Own: campaign leader/state/mobile match mine, or
 * - Shared: the campaign's (state, leader) is an owner who shared with me.
 */
export async function canAccessCampaign(
  campaignState: string,
  campaignLeader: string,
  campaignMobile: string | null,
  myState: string | null,
  myLeader: string | null,
  myMobile: string | null
): Promise<boolean> {
  if (!myState?.trim() || !myLeader?.trim()) return false;

  const myStateNorm = myState.toUpperCase().trim();
  const campaignStateNorm = (campaignState || '').toUpperCase().trim();
  const myLeaderNorm = normalizeName(myLeader);
  const campaignLeaderNorm = normalizeName(campaignLeader || '');

  // Own: same state, same leader, same mobile
  if (campaignStateNorm === myStateNorm && campaignLeaderNorm === myLeaderNorm) {
    if (myMobile) {
      const campaignMobileNorm = normalizeMobile(campaignMobile || '');
      const myMobileNorm = normalizeMobile(myMobile);
      if (campaignMobileNorm && campaignMobileNorm === myMobileNorm) return true;
    }
    // If no mobile on campaign or we don't have mobile, still allow if state+leader match (owner)
    if (!campaignMobile?.trim() || !myMobile?.trim()) return true;
  }

  // Shared: campaign's (state, leader) has shared with me
  const owners = await getSharedWithMeOwners(myState, myLeader);
  const isShared =
    owners.some(
      (o) =>
        (o.owner_state || '').toUpperCase().trim() === campaignStateNorm &&
        normalizeName(o.owner_leader) === campaignLeaderNorm
    );
  return isShared;
}

/**
 * Sync check: is this campaign owned by the current user (leader + mobile match)?
 * Use for Delete button (only owner can delete). Shared users can view/edit/record results but not delete.
 */
export function isCampaignOwner(
  campaignLeader: string,
  campaignMobile: string | null,
  myLeader: string | null,
  myMobile: string | null
): boolean {
  if (!myLeader?.trim()) return false;
  const leaderMatch = normalizeName(campaignLeader || '') === normalizeName(myLeader);
  if (!leaderMatch) return false;
  if (!myMobile?.trim()) return true;
  return (
    normalizeMobile(campaignMobile || '') === normalizeMobile(myMobile) &&
    normalizeMobile(campaignMobile || '') !== ''
  );
}

lib/leafletMarkerIcon.ts:
/**
 * Leaflet marker icons tinted by state, using the same palette as the downloaded
 * campaign-list slides (`SLIDE_STATE_COLORS` in lib/slideLayout.ts — also the source
 * the pastel badge colors in lib/stateColors.ts are derived from). Used by every map
 * in the app (Campaign Map, Campaigns Near Me, State Places Map) so a pin's color
 * matches its state at a glance, consistently with slides and badges elsewhere.
 *
 * Rendered as a translucent halo ring around a tiny centre point — the point's
 * diameter matches the ring's own border thickness, so it reads as a precise mark
 * rather than a fat dot — with the place name overlaid in black directly on top of
 * the ring, centred on it (a white outline keeps it legible over darker ring colors
 * like NSW's black). The icon's own centre point *is* the location, so `iconAnchor`
 * is the ring's centre.
 *
 * Only imported by map components that are dynamically loaded with `ssr: false`
 * (CampaignMap, NearbyCampaignsMap) since `leaflet` touches `window` at import time.
 */
import L from 'leaflet';
import { getSlideStateColor } from '@/lib/slideLayout';

// Leaflet icons are immutable once built, so one instance per state+place+size+
// opacity combination can be shared across every marker on the map instead of
// rebuilding an <svg>/label string per marker. Keyed on those too (not just
// state+place) since a caller can now request a different size/opacity (see
// options below) — without that, two callers on the same page (or across
// client-side navigations, since this cache is module-level) requesting
// different sizes for the same state+place would silently collide and one
// would get the other's cached icon.
const iconCache = new Map<string, L.DivIcon>();

const DEFAULT_SIZE = 22;
const DEFAULT_FILL_OPACITY = 0.35;
// Border scales with size (see below) so the ring's proportions stay
// consistent — this is its value at DEFAULT_SIZE.
const DEFAULT_BORDER_WIDTH = 1.5;

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export interface StateMarkerIconOptions {
  /** Overall icon diameter in px. Defaults to 22 (CampaignMap's usual size) — NearbyCampaignsMap passes a larger value so markers are easier to spot and tap on a map meant to be used one-handed on a phone. */
  size?: number;
  /** Fill opacity of the translucent halo ring (0-1). Defaults to 0.35 — NearbyCampaignsMap passes a higher value to make markers read more clearly against the base map. */
  fillOpacity?: number;
}

export function getStateMarkerIcon(state: string, place: string, options: StateMarkerIconOptions = {}): L.DivIcon {
  const upperState = state.trim().toUpperCase();
  const size = options.size ?? DEFAULT_SIZE;
  const fillOpacity = options.fillOpacity ?? DEFAULT_FILL_OPACITY;
  const key = `${upperState}::${place}::${size}::${fillOpacity}`;
  const cached = iconCache.get(key);
  if (cached) return cached;

  const center = size / 2;
  // Scaled from DEFAULT_BORDER_WIDTH at DEFAULT_SIZE, so a larger marker's
  // ring stays proportionally as thick rather than looking relatively thinner.
  const borderWidth = DEFAULT_BORDER_WIDTH * (size / DEFAULT_SIZE);
  // The centre point is reduced to match the ring's own border thickness — a precise
  // mark rather than a filled-in dot.
  const pointRadius = borderWidth / 2;

  const color = getSlideStateColor(upperState);
  const label = escapeHtml(place);
  const icon = L.divIcon({
    className: 'state-color-marker',
    html: `<div style="position:relative;width:${size}px;height:${size}px;">
      <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" xmlns="http://www.w3.org/2000/svg">
        <circle cx="${center}" cy="${center}" r="${center - 1}" fill="${color}" fill-opacity="${fillOpacity}" stroke="${color}" stroke-width="${borderWidth}"/>
        <circle cx="${center}" cy="${center}" r="${pointRadius}" fill="${color}"/>
      </svg>
      <span style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);white-space:nowrap;font-size:11px;font-weight:600;line-height:1;color:#000;text-shadow:-1px -1px 0 #fff,1px -1px 0 #fff,-1px 1px 0 #fff,1px 1px 0 #fff;">${label}</span>
    </div>`,
    iconSize: [size, size],
    iconAnchor: [center, center],
    popupAnchor: [0, -center],
  });
  iconCache.set(key, icon);
  return icon;
}

lib/location.ts:
/**
 * Get user's location and convert to Australian state code
 * Returns state codes like: VIC, NSW, QLD, SA, WA, TAS, NT, ACT
 */

export type StateCode = 'VIC' | 'NSW' | 'QLD' | 'SA' | 'WA' | 'TAS' | 'NT' | 'ACT';

interface Coordinates {
  latitude: number;
  longitude: number;
}

export interface LocationResult {
  coords: Coordinates | null;
  /** True when the user explicitly denied the permission prompt. */
  deniedByUser: boolean;
}

/**
 * Get user's current location using browser geolocation API.
 * Returns deniedByUser=true so callers can surface a helpful message
 * rather than silently showing an empty state field.
 */
export async function getUserLocation(): Promise<LocationResult> {
  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve({ coords: null, deniedByUser: false });
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({
          coords: {
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          },
          deniedByUser: false,
        });
      },
      (error) => {
        const deniedByUser = error.code === error.PERMISSION_DENIED;
        if (!deniedByUser) {
          console.warn('Error getting location:', error.message);
        }
        resolve({ coords: null, deniedByUser });
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 300000,
      }
    );
  });
}

/**
 * Convert coordinates to Australian state code using reverse geocoding
 * Uses a free geocoding service (Nominatim) to get state information
 */
export async function getStateFromLocation(
  latitude: number,
  longitude: number
): Promise<StateCode | null> {
  try {
    // Use Nominatim (OpenStreetMap) reverse geocoding API
    const response = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&zoom=10`,
      {
        headers: {
          'User-Agent': 'CampaignApp/1.0', // Required by Nominatim
        },
      }
    );

    if (!response.ok) {
      throw new Error('Geocoding service unavailable');
    }

    const data = await response.json();
    const address = data.address;

    if (!address) {
      return null;
    }

    // Check various address fields for state information
    const state = address.state || address.region || address.state_district || '';
    const stateUpper = state.toUpperCase();

    // Map Australian state names to codes
    const stateMap: Record<string, StateCode> = {
      VICTORIA: 'VIC',
      'NEW SOUTH WALES': 'NSW',
      QUEENSLAND: 'QLD',
      'SOUTH AUSTRALIA': 'SA',
      'WESTERN AUSTRALIA': 'WA',
      TASMANIA: 'TAS',
      'NORTHERN TERRITORY': 'NT',
      'AUSTRALIAN CAPITAL TERRITORY': 'ACT',
      ACT: 'ACT',
    };

    // Check if we have a direct match
    if (stateMap[stateUpper]) {
      return stateMap[stateUpper];
    }

    // Check for partial matches
    for (const [key, code] of Object.entries(stateMap)) {
      if (stateUpper.includes(key) || key.includes(stateUpper)) {
        return code;
      }
    }

    return null;
  } catch (error) {
    console.error('Error getting state from location:', error);
    return null;
  }
}

export interface StateCodeResult {
  stateCode: StateCode | null;
  /** True when the user explicitly denied location permission. */
  deniedByUser: boolean;
}

/**
 * Get user's state code from their location.
 * Caches the result in localStorage to avoid repeated API calls.
 * Returns deniedByUser so callers can prompt the user to select state manually.
 */
export async function getUserStateCode(): Promise<StateCodeResult> {
  if (typeof window === 'undefined') return { stateCode: null, deniedByUser: false };

  // Check if we have a cached state code (valid for 24 hours)
  const cached = localStorage.getItem('user_state_code');
  const cachedTime = localStorage.getItem('user_state_code_time');

  if (cached && cachedTime) {
    const age = Date.now() - parseInt(cachedTime, 10);
    if (age < 24 * 60 * 60 * 1000) {
      return { stateCode: cached as StateCode, deniedByUser: false };
    }
  }

  const { coords, deniedByUser } = await getUserLocation();
  if (!coords) {
    return { stateCode: null, deniedByUser };
  }

  const stateCode = await getStateFromLocation(coords.latitude, coords.longitude);

  if (stateCode) {
    localStorage.setItem('user_state_code', stateCode);
    localStorage.setItem('user_state_code_time', Date.now().toString());
  }

  return { stateCode, deniedByUser: false };
}

/**
 * Get cached state code without making API calls
 */
export function getCachedStateCode(): StateCode | null {
  if (typeof window === 'undefined') return null;

  const cached = localStorage.getItem('user_state_code');
  return cached ? (cached as StateCode) : null;
}

lib/magicLinkToken.ts:
/**
 * Scanner-proof magic links. Supabase's own `{{ .ConfirmationURL }}` is a
 * `/verify` URL that is consumed by *any* GET — so a mail program that opens
 * links before the person does (Apple Mail Privacy Protection, Outlook /
 * Microsoft link checkers; confirmed repeatedly in this app) uses the link up,
 * and the person lands on an "expired" page. Instead the Magic Link email
 * template links straight to one of our landing pages with the token in the
 * query string (`{{ .RedirectTo }}&token_hash={{ .TokenHash }}&type=email`),
 * and the page only calls verifyOtp() when the person *taps a button* — a
 * scanner that merely fetches the page never does.
 *
 * `{{ .RedirectTo }}` is the `emailRedirectTo` each sender passes, so every
 * such URL must already contain a `?` for the `&token_hash=` to attach to
 * (propose-email has `?leaderId=`; the others carry `?via=email`).
 */
export const MAGIC_LINK_TOKEN_PARAM = 'token_hash';

// Supabase token hashes are short; bound the input before it goes anywhere.
const MAX_TOKEN_HASH_LENGTH = 200;

/** The one-time token hash from a magic-link landing URL's query string, if any. */
export function readTokenHashFromUrl(search: string = typeof window === 'undefined' ? '' : window.location.search): string | null {
  const value = new URLSearchParams(search).get(MAGIC_LINK_TOKEN_PARAM);
  if (!value || value.length > MAX_TOKEN_HASH_LENGTH) return null;
  return value;
}

/** Removes the token from the address bar so a refresh/bookmark/history entry can't replay it. */
export function stripTokenHashFromUrl(): void {
  if (typeof window === 'undefined') return;
  const url = new URL(window.location.href);
  if (!url.searchParams.has(MAGIC_LINK_TOKEN_PARAM)) return;
  url.searchParams.delete(MAGIC_LINK_TOKEN_PARAM);
  url.searchParams.delete('type');
  window.history.replaceState(window.history.state, '', `${url.pathname}${url.search}${url.hash}`);
}

lib/mfaErrors.ts:
/**
 * Plain-language text for a failed authenticator-code check. Supabase's own
 * messages ("Invalid TOTP code entered") tell a non-technical leader nothing
 * about what to try; the usual causes are all on the phone side — a stale
 * entry from an earlier setup attempt (each attempt makes a new secret but
 * the same-looking label), a phone clock that has drifted (codes are only
 * valid for ~30–60 seconds either side of the server's clock), or a code
 * that expired before it was typed.
 */
export function describeMfaVerifyError(error: { message: string; code?: string | null }): string {
  const code = error.code ?? '';
  const message = error.message.toLowerCase();

  if (code === 'mfa_verification_failed' || message.includes('invalid totp')) {
    return (
      "That code didn't work. Please check: (1) you are reading the newest \"AFJ Campaign App\" entry in your authenticator app — " +
      'delete any older AFJ entries, as only the one from this page works; (2) your phone\'s date and time are set to "automatic"; ' +
      '(3) type the code before it changes. Then try again.'
    );
  }
  if (code === 'mfa_challenge_expired' || message.includes('challenge has expired')) {
    return 'That took too long. Please try again with the code now showing in your app.';
  }
  if (code === 'over_request_rate_limit' || message.includes('rate limit') || message.includes('too many')) {
    return 'Too many attempts. Please wait a minute, then try again.';
  }
  if (code === 'mfa_factor_not_found' || message.includes('factor not found')) {
    return 'This setup has expired. Please go back to the sign-in page and start setup again.';
  }
  return error.message;
}

lib/otpInput.ts:
// Authenticator-app (TOTP) codes are always 6 digits.
export const OTP_CODE_LENGTH = 6;

// Emailed codes follow the Supabase project's "Email OTP Length" setting (6-10), so the
// email-code inputs must not assume 6.
export const EMAIL_OTP_MIN_LENGTH = 6;
export const EMAIL_OTP_MAX_LENGTH = 10;

// Pasted codes often carry stray whitespace, a newline, or a label; maxLength on the
// input would truncate those before they could be cleaned, so sanitize here instead.
export function normalizeOtpInput(raw: string, maxLength: number = OTP_CODE_LENGTH): string {
  return raw.replace(/\D/g, '').slice(0, maxLength);
}

lib/pdfRenderScale.ts:
/**
 * Sizing for rendering a PDF page onto a canvas (components/PdfGuideViewer.tsx).
 * The page is shown at the container's width; the canvas backing store is
 * rendered at up to 2× that so text stays sharp on high-density phone screens
 * and when pinch-zoomed — capped at 2× because a 3× canvas per page adds up
 * quickly in phone memory for a long guide.
 */
export const MAX_RENDER_PIXEL_RATIO = 2;

export function computePdfRenderScale(
  containerWidth: number,
  pageWidth: number,
  devicePixelRatio: number,
): { cssScale: number; renderScale: number } {
  if (!(containerWidth > 0) || !(pageWidth > 0)) return { cssScale: 1, renderScale: 1 };
  const cssScale = containerWidth / pageWidth;
  const ratio = Math.min(Math.max(devicePixelRatio || 1, 1), MAX_RENDER_PIXEL_RATIO);
  return { cssScale, renderScale: cssScale * ratio };
}

lib/pendingLoginStep.ts:
import type { StateLeaderMatch } from '@/lib/auth';

/**
 * Remembers the login page's "Check your inbox" screen (email confirmation or
 * 2FA setup) across a page reload. To read the emailed code a leader has to
 * leave the app for their mail program — and a phone browser (iPhone Safari
 * and installed web apps especially) often reloads the page when they come
 * back. /login then found them already signed in and sent them straight to
 * /app, so they never got to type the code (reported by a leader on an
 * iPhone, 2026-10-12). Stored in localStorage — it survives the page being
 * discarded — with a short expiry, and holds only the leader row the page
 * already had (no tokens or secrets).
 */
const STORAGE_KEY = 'afj_pending_login_step';
const MAX_AGE_MS = 30 * 60 * 1000;

export type PendingLoginStep =
  | { kind: 'email'; match: StateLeaderMatch; value: string }
  | { kind: 'mfa'; match: StateLeaderMatch };

function isMatch(value: unknown): value is StateLeaderMatch {
  if (!value || typeof value !== 'object') return false;
  const m = value as Record<string, unknown>;
  return typeof m.id === 'string' && typeof m.state === 'string' && typeof m.leader === 'string';
}

export function clearPendingLoginStep(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch { /* ignore (e.g. private browsing) */ }
}

export function savePendingLoginStep(step: PendingLoginStep, now: number = Date.now()): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...step, savedAt: now }));
  } catch { /* ignore (e.g. private browsing) */ }
}

/** The remembered step, or null if there is none, it has expired, or it is malformed (which is also cleared). */
export function readPendingLoginStep(now: number = Date.now()): PendingLoginStep | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { kind?: unknown; match?: unknown; value?: unknown; savedAt?: unknown };
    const fresh = typeof parsed.savedAt === 'number' && now - parsed.savedAt <= MAX_AGE_MS;
    if (fresh && isMatch(parsed.match)) {
      if (parsed.kind === 'email' && typeof parsed.value === 'string') {
        return { kind: 'email', match: parsed.match, value: parsed.value };
      }
      if (parsed.kind === 'mfa') return { kind: 'mfa', match: parsed.match };
    }
    localStorage.removeItem(STORAGE_KEY);
    return null;
  } catch {
    clearPendingLoginStep();
    return null;
  }
}

lib/pendingTotpEnrollment.ts:
/**
 * Remembers the authenticator (TOTP) setup key shown by MfaEnrollmentFlow
 * across a page reload. Setting up on a phone means leaving the page to add
 * the key to the authenticator app, and iPhone reloads the page on return.
 * Each page load used to unenroll the unfinished authenticator and create a
 * *new* one — so the key already sitting in the person's app no longer
 * matched, and every code they typed failed (an iPhone leader entered seven,
 * 2026-10-13). Supabase only returns the secret at enrollment time, so it has
 * to be kept here. It belongs to an *unverified* factor of the signed-in
 * session's own account (the flow checks it still exists there before reusing
 * it), is the same value already on screen, expires quickly, and is cleared
 * the moment setup finishes, is cancelled, or times out.
 */
const STORAGE_KEY = 'afj_pending_totp_enrollment';
const MAX_AGE_MS = 15 * 60 * 1000;

export interface PendingTotpEnrollment {
  factorId: string;
  uri: string;
  secret: string;
}

export function clearPendingTotpEnrollment(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch { /* ignore (e.g. private browsing) */ }
}

export function savePendingTotpEnrollment(value: PendingTotpEnrollment, now: number = Date.now()): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...value, savedAt: now }));
  } catch { /* ignore (e.g. private browsing) */ }
}

/** The remembered setup, or null if none / expired / malformed (the latter two are also cleared). */
export function readPendingTotpEnrollment(now: number = Date.now()): PendingTotpEnrollment | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const p = JSON.parse(raw) as { factorId?: unknown; uri?: unknown; secret?: unknown; savedAt?: unknown };
    const fresh = typeof p.savedAt === 'number' && now - p.savedAt <= MAX_AGE_MS;
    if (fresh && typeof p.factorId === 'string' && typeof p.uri === 'string' && typeof p.secret === 'string') {
      return { factorId: p.factorId, uri: p.uri, secret: p.secret };
    }
    localStorage.removeItem(STORAGE_KEY);
    return null;
  } catch {
    clearPendingTotpEnrollment();
    return null;
  }
}

lib/placeSite.ts:
/**
 * Splits/joins the numeric "site" suffix that distinguishes multiple locations
 * sharing the same place name (e.g. "Orange 1", "Orange 2", "Frankston 2").
 * Single source of truth so the parsing rule stays consistent between the
 * one-off data migration and every place selector/display in the app.
 */

/** Parses a raw place string like "Orange 1" into its base place and site. */
export function splitPlaceAndSite(raw: string): { place: string; site: string } {
  const collapsed = raw.trim().replace(/\s+/g, ' ');
  const match = collapsed.match(/^(.*\S)\s+(\d+)$/);
  if (match) return { place: match[1], site: match[2] };
  return { place: collapsed, site: '' };
}

/** Joins a base place and site back into the combined display label. */
export function combinePlaceAndSite(place: string, site: string): string {
  return site ? `${place} ${site}` : place;
}

