lib/rateLimit.ts:
/**
 * Shared in-memory, per-IP rate limiter for API routes.
 *
 * Resets across serverless cold starts, which is acceptable for this use
 * case — the goal is to blunt casual abuse, not provide hard guarantees.
 * Each call site keeps its own Map (via createRateLimiter) so limits for
 * different routes don't share a budget.
 */
import { NextRequest } from 'next/server';

export interface RateLimiterOptions {
  /** Rolling window length in milliseconds. */
  windowMs: number;
  /** Max requests allowed per IP within the window. */
  maxAttempts: number;
}

export interface RateLimiter {
  /** Returns true if this IP is currently over the limit (request should be rejected). */
  isLimited(ip: string): boolean;
}

/** Creates an independent rate limiter with its own request map. */
export function createRateLimiter({ windowMs, maxAttempts }: RateLimiterOptions): RateLimiter {
  const attempts = new Map<string, { count: number; resetAt: number }>();

  return {
    isLimited(ip: string): boolean {
      const now = Date.now();

      // Prevent unbounded growth: evict expired entries when the map gets large.
      if (attempts.size > 5000) {
        for (const [k, v] of attempts) {
          if (now > v.resetAt) attempts.delete(k);
        }
      }

      const entry = attempts.get(ip);
      if (!entry || now > entry.resetAt) {
        attempts.set(ip, { count: 1, resetAt: now + windowMs });
        return false;
      }
      entry.count++;
      return entry.count > maxAttempts;
    },
  };
}

/**
 * Best-effort client IP extraction from a Next.js request. Falls back to
 * 'unknown' (which shares a single rate-limit bucket) when no header is set —
 * acceptable since this is a UX-level throttle, not the security boundary.
 */
export function getClientIp(request: NextRequest): string {
  return (
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ??
    request.headers.get('x-real-ip') ??
    'unknown'
  );
}

lib/recordResultsDraft.ts:
/**
 * Local-only backup of in-progress Record Results edits.
 *
 * The page's autosave can lose work in several real-world ways: network
 * drops mid-save, browser tab closes before the 2-second debounce fires,
 * iOS Safari pagehide/visibilitychange quirks, transient RLS rejections.
 * This module mirrors the form state to localStorage on every change and
 * exposes it for restore on page load, so even if every server-side save
 * path fails, the user's typing is still on their device.
 *
 * The draft is keyed by campaign id, cleared only after a confirmed
 * successful name save, and intentionally narrow (just the fields the
 * Record Results page owns).
 */

// Must stay in sync with the `results_category_code_check` CHECK constraint
// in the database (see scripts/fix_results_category_code_check.sql) — a
// mismatch here silently drops entire save batches (#69: 'TM' was added
// here without updating the constraint, and Postgres INSERT is atomic).
export type ResultsCategory = 'TM' | 'P' | 'F' | 'SP' | 'IR';

/**
 * One name slot as it appears in the visible form. `dbId` is the
 * primary key of the corresponding row in the `results` table once it
 * has been saved at least once; null means this slot has never reached
 * the server. Empty `value` with a non-null `dbId` represents "user
 * cleared a previously-saved entry — delete it on next save".
 */
export interface NameSlotDraft {
  value: string;
  dbId: string | null;
}

export interface RecordResultsDraft {
  campaignId: string;
  names: Record<ResultsCategory, NameSlotDraft[]>;
  actualLeader: string;
  updatedAt: string; // ISO timestamp
}

const STORAGE_PREFIX = 'record-results-draft:';
const keyFor = (campaignId: string) => `${STORAGE_PREFIX}${campaignId}`;

function safeStorage(): Storage | null {
  if (typeof window === 'undefined') return null;
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function saveDraft(draft: RecordResultsDraft): void {
  const storage = safeStorage();
  if (!storage) return;
  try {
    storage.setItem(keyFor(draft.campaignId), JSON.stringify(draft));
  } catch (err) {
    // QuotaExceeded or a privacy-mode restriction — non-fatal.
    console.warn('Failed to write Record Results draft:', err);
  }
}

export function loadDraft(campaignId: string): RecordResultsDraft | null {
  const storage = safeStorage();
  if (!storage) return null;
  try {
    const raw = storage.getItem(keyFor(campaignId));
    if (!raw) return null;
    const parsed = JSON.parse(raw) as RecordResultsDraft;
    // Basic shape check — anything malformed is treated as no draft.
    if (!parsed || parsed.campaignId !== campaignId || !parsed.names) return null;
    return parsed;
  } catch (err) {
    console.warn('Failed to read Record Results draft:', err);
    return null;
  }
}

export function clearDraft(campaignId: string): void {
  const storage = safeStorage();
  if (!storage) return;
  try {
    storage.removeItem(keyFor(campaignId));
  } catch {
    // Non-fatal.
  }
}

/**
 * True if the draft has any meaningful content (a name or actual leader
 * entry). Used so a draft of pure empty strings doesn't trigger a "restored
 * unsaved names" banner. Team size and the Partial/Full/Full+Sinner's
 * Prayer/Information Request counts are derived from the name grids
 * themselves rather than drafted separately.
 */
export function draftHasContent(draft: RecordResultsDraft): boolean {
  const anyName = (Object.values(draft.names) as NameSlotDraft[][])
    .some((arr) => arr.some((s) => s.value.trim().length > 0));
  if (anyName) return true;
  if (draft.actualLeader.trim()) return true;
  return false;
}

lib/registryAuth.ts:
/**
 * Thin Supabase-SDK glue for the /registry portal. The actual gating
 * decision lives in lib/registryPipeline/mfaGate.ts (pure, unit tested);
 * this file only fetches the values that decision needs and wires up the
 * session-indicator cookie, same pattern as lib/auth.ts's app_session for
 * the main app. Not independently unit tested — same precedent as this
 * app's other thin SDK adapters (e.g. supabase/functions/ac-sync/db.ts) —
 * exercised instead via the page-level tests under app/registry/.
 */
import { registrySupabase } from './registrySupabaseClient';
import { evaluateMfaGate, type MfaGateResult, type LeaderRoleRow } from './registryPipeline/mfaGate';

const REGISTRY_AUTH_COOKIE = 'registry_auth';       // set once a session exists, MFA outcome pending — lets middleware admit /registry/mfa/*
const REGISTRY_SESSION_COOKIE = 'registry_session'; // set once the full MFA gate has passed — required for the rest of /registry

function setCookie(name: string): void {
  if (typeof document === 'undefined') return;
  const secure = location.protocol === 'https:' ? '; Secure' : '';
  document.cookie = `${name}=1; path=/registry; SameSite=Lax${secure}`;
}

function clearCookie(name: string): void {
  if (typeof document === 'undefined') return;
  document.cookie = `${name}=; path=/registry; expires=Thu, 01 Jan 1970 00:00:00 GMT; SameSite=Lax`;
}

/** Call right after a successful magic-link code exchange, before the MFA gate is evaluated. */
export function setRegistryAuthCookie(): void {
  setCookie(REGISTRY_AUTH_COOKIE);
}

export function setRegistrySessionCookie(): void {
  setCookie(REGISTRY_SESSION_COOKIE);
}

export function clearRegistrySessionCookie(): void {
  clearCookie(REGISTRY_AUTH_COOKIE);
  clearCookie(REGISTRY_SESSION_COOKIE);
}

async function getOwnLeaderRole(): Promise<LeaderRoleRow | null> {
  // RLS (leader_roles_select_own) already restricts this to the caller's
  // own row, so no explicit .eq('user_id', ...) is needed.
  const { data, error } = await registrySupabase
    .schema('registry')
    .from('leader_roles')
    .select('role, mfa_required')
    .maybeSingle();

  if (error) {
    console.error('getOwnLeaderRole: failed to read registry.leader_roles', error);
    return null;
  }
  return (data as LeaderRoleRow | null) ?? null;
}

/**
 * Gathers everything evaluateMfaGate() needs and returns its verdict, plus
 * the leader role row (pages need the role/state to render, not just the
 * routing decision).
 */
export async function getRegistryAccessState(): Promise<{ result: MfaGateResult; leaderRole: LeaderRoleRow | null }> {
  const { data: { session } } = await registrySupabase.auth.getSession();
  if (!session) {
    return { result: evaluateMfaGate({ hasSession: false, leaderRole: null, currentLevel: null, hasVerifiedTotpFactor: false }), leaderRole: null };
  }

  const [leaderRole, aalResult, factorsResult] = await Promise.all([
    getOwnLeaderRole(),
    registrySupabase.auth.mfa.getAuthenticatorAssuranceLevel(),
    registrySupabase.auth.mfa.listFactors(),
  ]);

  const currentLevel = (aalResult.data?.currentLevel ?? 'aal1') as 'aal1' | 'aal2';
  const hasVerifiedTotpFactor = (factorsResult.data?.totp ?? []).some((f) => f.status === 'verified');

  const result = evaluateMfaGate({ hasSession: true, leaderRole, currentLevel, hasVerifiedTotpFactor });
  return { result, leaderRole };
}

export async function signOutOfRegistry(): Promise<void> {
  await registrySupabase.auth.signOut();
  clearRegistrySessionCookie();
}

