import { describe, expect, it } from 'vitest';
import { computeBackoffMs, REQUEST_PACING_MS } from '../rateLimiter';

describe('computeBackoffMs', () => {
  it('honors a numeric Retry-After header, in seconds converted to ms', () => {
    expect(computeBackoffMs('2', 0)).toBe(2000);
  });

  it('honors a Retry-After of 0', () => {
    expect(computeBackoffMs('0', 3)).toBe(0);
  });

  it('falls back to exponential backoff when Retry-After is missing', () => {
    expect(computeBackoffMs(null, 0)).toBe(REQUEST_PACING_MS * 2 ** 0);
    expect(computeBackoffMs(null, 1)).toBe(REQUEST_PACING_MS * 2 ** 1);
    expect(computeBackoffMs(undefined, 2)).toBe(REQUEST_PACING_MS * 2 ** 2);
  });

  it('falls back to exponential backoff when Retry-After is unparseable', () => {
    expect(computeBackoffMs('not-a-number', 1)).toBe(REQUEST_PACING_MS * 2 ** 1);
  });

  it('caps exponential backoff at 30 seconds', () => {
    expect(computeBackoffMs(null, 20)).toBe(30_000);
  });

  it('never backs off below zero attempts', () => {
    expect(computeBackoffMs(null, -1)).toBe(REQUEST_PACING_MS);
  });
});

lib/registryPipeline/__tests__/registran:
import { describe, it, expect } from 'vitest';
import {
  resolvePeriodRange,
  countAllRegistrants,
  countRegistrantsForPeriod,
  countRegistrantsByCategory,
  filterRegistrantsForCell,
  filterRegistrantsByCategoryForCell,
  MANAGE_CONSOLE_STATES,
  type RegistrantForCount,
  type RegistrantForCategoryCount,
} from '../registrantCounts';

const NOW = new Date('2026-09-10T12:00:00Z');

function row(state: string | null, registeredAt: string | null): RegistrantForCount {
  return { state, registeredAt };
}

describe('resolvePeriodRange', () => {
  it('anchors a rolling period to now', () => {
    expect(resolvePeriodRange('last_24_hours', NOW)).toEqual({
      start: NOW.getTime() - 24 * 60 * 60 * 1000,
      end: NOW.getTime(),
    });
  });

  it('resolves year_to_date from Jan 1st of the current year to now', () => {
    expect(resolvePeriodRange('year_to_date', NOW)).toEqual({
      start: Date.UTC(2026, 0, 1),
      end: NOW.getTime(),
    });
  });

  it('resolves a fixed calendar year regardless of now, not clamped to it', () => {
    expect(resolvePeriodRange('2024', NOW)).toEqual({
      start: Date.UTC(2024, 0, 1),
      end: Date.UTC(2025, 0, 1),
    });
  });
});

describe('countAllRegistrants', () => {
  it('counts every row regardless of registeredAt, bucketing by state', () => {
    const rows = [
      row('VIC', null),
      row('vic', '2020-01-01T00:00:00Z'), // lowercase — must normalize
      row('NSW', '2026-09-01T00:00:00Z'),
      row(null, '2026-09-01T00:00:00Z'),
      row('OS', '2026-09-01T00:00:00Z'), // not a recognized code
    ];
    const result = countAllRegistrants(rows);
    expect(result.total).toBe(5);
    expect(result.byState.VIC).toBe(2);
    expect(result.byState.NSW).toBe(1);
    expect(result.unknown).toBe(2);
  });

  it('initializes every known state to zero even when absent from the data', () => {
    const result = countAllRegistrants([]);
    for (const s of MANAGE_CONSOLE_STATES) {
      expect(result.byState[s]).toBe(0);
    }
    expect(result.total).toBe(0);
    expect(result.unknown).toBe(0);
  });
});

describe('countRegistrantsForPeriod', () => {
  const rows = [
    row('VIC', '2026-09-10T06:00:00Z'), // within last 24h of NOW
    row('VIC', '2026-08-01T00:00:00Z'), // outside last 24h, within last month
    row('NSW', '2025-01-01T00:00:00Z'), // old
    row('QLD', null), // never matches a period
  ];

  it('only counts rows whose registeredAt falls within the resolved window', () => {
    const result = countRegistrantsForPeriod(rows, 'last_24_hours', NOW);
    expect(result.total).toBe(1);
    expect(result.byState.VIC).toBe(1);
  });

  it('excludes a row with no registeredAt from every period', () => {
    const result = countRegistrantsForPeriod(rows, 'last_12_months', NOW);
    expect(result.total).toBe(2); // the two VIC rows, not the null-date QLD row
    expect(result.byState.QLD).toBe(0);
  });

  it('is exclusive of the window end (a fixed calendar year does not leak into the next)', () => {
    const boundary = [row('VIC', '2025-01-01T00:00:00Z')]; // exactly midnight Jan 1 2025 = start of 2025, not part of 2024
    expect(countRegistrantsForPeriod(boundary, '2024', NOW).total).toBe(0);
    expect(countRegistrantsForPeriod(boundary, '2025', NOW).total).toBe(1);
  });

  it('ignores an unparseable registeredAt rather than throwing', () => {
    const bad = [row('VIC', 'not-a-date')];
    expect(countRegistrantsForPeriod(bad, 'last_12_months', NOW).total).toBe(0);
  });
});

describe('filterRegistrantsForCell', () => {
  // Richer than RegistrantForCount, same as ManageRegistrant — confirms the
  // function is generic and hands back the caller's own row shape rather
  // than narrowing it down to just state/registeredAt.
  function record(id: string, state: string | null, registeredAt: string | null) {
    return { id, state, registeredAt };
  }

  const rows = [
    record('vic-recent', 'VIC', '2026-09-10T06:00:00Z'), // within last 24h of NOW
    record('vic-old', 'vic', '2026-08-01T00:00:00Z'), // lowercase — within last month, outside last 24h
    record('nsw-old', 'NSW', '2025-01-01T00:00:00Z'),
    record('no-state', null, '2026-09-10T00:00:00Z'),
    record('no-date', 'QLD', null),
  ];

  it('"total" with no period matches every row, regardless of state or date', () => {
    expect(filterRegistrantsForCell(rows, 'total', null, NOW).map((r) => r.id)).toEqual(rows.map((r) => r.id));
  });

  it('a specific state column matches case-insensitively, independent of period', () => {
    const result = filterRegistrantsForCell(rows, 'VIC', null, NOW);
    expect(result.map((r) => r.id)).toEqual(['vic-recent', 'vic-old']);
  });

  it('"unknown" matches a missing or unrecognized state', () => {
    const result = filterRegistrantsForCell(rows, 'unknown', null, NOW);
    expect(result.map((r) => r.id)).toEqual(['no-state']);
  });

  it('combines the column with a period when one is given', () => {
    const result = filterRegistrantsForCell(rows, 'VIC', 'last_24_hours', NOW);
    expect(result.map((r) => r.id)).toEqual(['vic-recent']);
  });

  it('excludes a row with no registeredAt once a period is applied, even if its column matches', () => {
    const result = filterRegistrantsForCell(rows, 'QLD', 'last_12_months', NOW);
    expect(result).toEqual([]);
  });

  it('returns the caller\'s own richer row objects, not a stripped-down copy', () => {
    const result = filterRegistrantsForCell(rows, 'NSW', null, NOW);
    expect(result[0]).toBe(rows[2]); // same object reference, not a rebuilt one
  });
});

describe('countRegistrantsByCategory', () => {
  function categoryRow(state: string | null, unsubscribed: string | null, nfc: string | null): RegistrantForCategoryCount {
    return { state, registeredAt: null, unsubscribed, nfc };
  }

  const rows = [
    categoryRow('VIC', 'Yes', null),
    categoryRow('VIC', null, 'Yes'),
    categoryRow('NSW', 'Yes', 'Yes'), // flagged both — counts under either category
    categoryRow('QLD', null, null), // neither — never counted
  ];

  it('counts only rows flagged \'Yes\' for the selected category', () => {
    const unsubscribed = countRegistrantsByCategory(rows, 'unsubscribed');
    expect(unsubscribed.total).toBe(2);
    expect(unsubscribed.byState.VIC).toBe(1);
    expect(unsubscribed.byState.NSW).toBe(1);

    const nfc = countRegistrantsByCategory(rows, 'nfc');
    expect(nfc.total).toBe(2);
    expect(nfc.byState.VIC).toBe(1);
    expect(nfc.byState.NSW).toBe(1);
  });

  it('ignores registeredAt entirely — a null date still counts if the category flag is set', () => {
    const result = countRegistrantsByCategory([categoryRow('VIC', 'Yes', null)], 'unsubscribed');
    expect(result.total).toBe(1);
  });
});

describe('filterRegistrantsByCategoryForCell', () => {
  function record(id: string, state: string | null, unsubscribed: string | null, nfc: string | null) {
    return { id, state, registeredAt: null, unsubscribed, nfc };
  }

  const rows = [
    record('vic-unsub', 'VIC', 'Yes', null),
    record('vic-nfc', 'VIC', null, 'Yes'),
    record('nsw-unsub', 'NSW', 'Yes', null),
    record('vic-neither', 'VIC', null, null),
  ];

  it('"total" matches every row flagged for the category, regardless of state', () => {
    expect(filterRegistrantsByCategoryForCell(rows, 'total', 'unsubscribed').map((r) => r.id)).toEqual(['vic-unsub', 'nsw-unsub']);
  });

  it('combines the column with the category', () => {
    expect(filterRegistrantsByCategoryForCell(rows, 'VIC', 'unsubscribed').map((r) => r.id)).toEqual(['vic-unsub']);
    expect(filterRegistrantsByCategoryForCell(rows, 'VIC', 'nfc').map((r) => r.id)).toEqual(['vic-nfc']);
  });

  it('excludes a row that matches the column but not the category', () => {
    expect(filterRegistrantsByCategoryForCell(rows, 'VIC', 'unsubscribed').map((r) => r.id)).not.toContain('vic-neither');
  });
});

import { describe, it, expect } from 'vitest';
import {
  getLookupOptions,
  matchesLookupFilters,
  filterByLookups,
  LOOKUP_FIELDS,
  LOOKUP_FIELD_LABELS,
  BLANK_VALUE_OPTION,
  type LookupableRegistrant,
} from '../registrantLookupFilters';

function record(overrides: Partial<LookupableRegistrant> = {}): LookupableRegistrant {
  return { firstName: 'Vicky', lastName: 'Vale', email: 'vicky@example.com', phone: '+61400000001', postcode: '3000', churchName: 'Grace Church', webinarAttended: 'Yes', codeOfConductAgreed: null, ...overrides };
}

describe('LOOKUP_FIELDS / LOOKUP_FIELD_LABELS', () => {
  it('covers the pane\'s text columns other than State and the dates', () => {
    expect(LOOKUP_FIELDS).toEqual(['firstName', 'lastName', 'email', 'phone', 'postcode', 'churchName', 'webinarAttended', 'codeOfConductAgreed']);
  });

  it('labels phone as "Mobile", matching the pane\'s own column header', () => {
    expect(LOOKUP_FIELD_LABELS.phone).toBe('Mobile');
  });

  it('has a label for every field', () => {
    for (const field of LOOKUP_FIELDS) {
      expect(LOOKUP_FIELD_LABELS[field]).toBeTruthy();
    }
  });
});

describe('getLookupOptions', () => {
  const records = [
    record({ postcode: '3000' }),
    record({ email: 'nat@example.com', postcode: '2000' }),
    record({ email: 'nat@example.com', postcode: null }), // duplicate email, blank postcode
  ];

  it('returns every distinct non-blank value, sorted', () => {
    const values = getLookupOptions(records, 'postcode').map((o) => o.value).filter((v) => v !== BLANK_VALUE_OPTION);
    expect(values).toEqual(['2000', '3000']);
  });

  it('dedupes repeated values', () => {
    expect(getLookupOptions(records, 'email').map((o) => o.value)).toEqual(['nat@example.com', 'vicky@example.com']);
  });

  it('prepends a "(blank)" option only when at least one record actually has a blank value for that field', () => {
    const postcodeOptions = getLookupOptions(records, 'postcode');
    expect(postcodeOptions[0]).toEqual({ value: BLANK_VALUE_OPTION, label: '(blank)' });

    const emailOptions = getLookupOptions(records, 'email'); // no blank emails in the sample
    expect(emailOptions.some((o) => o.value === BLANK_VALUE_OPTION)).toBe(false);
  });

  it('treats an empty-string value the same as null for blank detection', () => {
    const options = getLookupOptions([record({ lastName: '' })], 'lastName');
    expect(options).toEqual([{ value: BLANK_VALUE_OPTION, label: '(blank)' }]);
  });

  it('returns no options for an empty record list', () => {
    expect(getLookupOptions([], 'firstName')).toEqual([]);
  });
});

describe('church / webinar / code lookups', () => {
  const records = [
    record({ churchName: 'Grace Church', webinarAttended: 'Yes', codeOfConductAgreed: 'Yes' }),
    record({ churchName: 'Hope Chapel', webinarAttended: null, codeOfConductAgreed: null }),
    record({ churchName: null, webinarAttended: 'Yes', codeOfConductAgreed: null }),
  ];

  it('lists the distinct church names, with (blank) when some are missing', () => {
    expect(getLookupOptions(records, 'churchName').map((o) => o.value)).toEqual([BLANK_VALUE_OPTION, 'Grace Church', 'Hope Chapel']);
  });

  it('finds everyone who agreed to the Code (or has not)', () => {
    expect(filterByLookups(records, { codeOfConductAgreed: 'Yes' })).toHaveLength(1);
    expect(filterByLookups(records, { codeOfConductAgreed: BLANK_VALUE_OPTION })).toHaveLength(2);
  });

  it('combines webinar attended with the Code', () => {
    expect(filterByLookups(records, { webinarAttended: 'Yes', codeOfConductAgreed: BLANK_VALUE_OPTION })).toHaveLength(1);
  });
});

describe('matchesLookupFilters', () => {
  const vicky = record();

  it('matches everything when no filters are set', () => {
    expect(matchesLookupFilters(vicky, {})).toBe(true);
  });

  it('matches on a single exact field value', () => {
    expect(matchesLookupFilters(vicky, { postcode: '3000' })).toBe(true);
    expect(matchesLookupFilters(vicky, { postcode: '2000' })).toBe(false);
  });

  it('combines multiple active filters with AND', () => {
    expect(matchesLookupFilters(vicky, { firstName: 'Vicky', postcode: '3000' })).toBe(true);
    expect(matchesLookupFilters(vicky, { firstName: 'Vicky', postcode: '2000' })).toBe(false);
  });

  it('the BLANK_VALUE_OPTION sentinel matches null or an empty string, nothing else', () => {
    expect(matchesLookupFilters(record({ lastName: null }), { lastName: BLANK_VALUE_OPTION })).toBe(true);
    expect(matchesLookupFilters(record({ lastName: '' }), { lastName: BLANK_VALUE_OPTION })).toBe(true);
    expect(matchesLookupFilters(record({ lastName: 'Vale' }), { lastName: BLANK_VALUE_OPTION })).toBe(false);
  });
});

describe('filterByLookups', () => {
  const records = [
    record({ firstName: 'Vicky', postcode: '3000' }),
    record({ firstName: 'Nat', postcode: '2000' }),
    record({ firstName: 'Vicky', postcode: '2000' }),
  ];

  it('returns only the records matching every active filter', () => {
    expect(filterByLookups(records, { firstName: 'Vicky' })).toHaveLength(2);
    expect(filterByLookups(records, { firstName: 'Vicky', postcode: '2000' })).toHaveLength(1);
  });

  it('returns every record when filters is empty', () => {
    expect(filterByLookups(records, {})).toHaveLength(3);
  });

  it('returns the caller\'s own row objects unmodified', () => {
    const result = filterByLookups(records, { firstName: 'Nat' });
    expect(result[0]).toBe(records[1]);
  });
});

import { describe, it, expect } from 'vitest';
import { protectExistingRegistrantName } from '../registrantNameGuard';

describe('protectExistingRegistrantName', () => {
  it('keeps the existing name instead of a later sync\'s placeholder test values (the Lorraine Walker incident)', () => {
    const candidate = { first_name: 'Test', last_name: 'Testing', state: 'WA' as string | null };
    const existing = { first_name: 'Lorraine', last_name: 'Walker' };

    const result = protectExistingRegistrantName(candidate, existing);

    expect(result.first_name).toBe('Lorraine');
    expect(result.last_name).toBe('Walker');
    expect(result.state).toBe('WA'); // untouched fields pass through unchanged
  });

  it('fills in a currently blank name from the new sync, rather than leaving it blank forever', () => {
    const candidate = { first_name: 'Jane', last_name: 'Doe' };
    const existing = { first_name: null, last_name: '' };

    const result = protectExistingRegistrantName(candidate, existing);

    expect(result.first_name).toBe('Jane');
    expect(result.last_name).toBe('Doe');
  });

  it('protects first and last name independently', () => {
    const candidate = { first_name: 'New', last_name: 'Value' };
    const existing = { first_name: 'Existing', last_name: null };

    const result = protectExistingRegistrantName(candidate, existing);

    expect(result.first_name).toBe('Existing'); // protected — already had a real value
    expect(result.last_name).toBe('Value'); // filled in — was blank
  });

  it('treats a whitespace-only existing value as blank, so it can still be filled in', () => {
    const candidate = { first_name: 'Jane', last_name: 'Doe' };
    const existing = { first_name: '   ', last_name: '' };

    const result = protectExistingRegistrantName(candidate, existing);

    expect(result.first_name).toBe('Jane');
    expect(result.last_name).toBe('Doe');
  });
});

import { describe, it, expect } from 'vitest';
import type { ManageRegistrant } from '../manageSummaryTypes';
import { sortRegistrants, getPageCount, getPageSlice } from '../registrantSort';

function reg(id: string, overrides: Partial<ManageRegistrant> = {}): ManageRegistrant {
  return {
    id, firstName: null, lastName: null, email: null, phone: null, state: null, postcode: null,
    registeredAt: null, isLeader: false, leaderName: null, webinarSessionAt: null, webinarAttended: null,
    codeOfConductAgreed: null, codeOfConductAgreedAt: null, unsubscribed: null, nfc: null, churchName: null,
    ...overrides,
  };
}

const ids = (rs: ManageRegistrant[]) => rs.map((r) => r.id);

describe('sortRegistrants', () => {
  const rows = [
    reg('blank'),
    reg('tas', { postcode: '7000' }),
    reg('vic', { postcode: '3000' }),
    reg('nsw', { postcode: '2000' }),
  ];

  it('puts blanks last when ascending', () => {
    expect(ids(sortRegistrants(rows, 'postcode', 'asc'))).toEqual(['nsw', 'vic', 'tas', 'blank']);
  });

  it('also puts blanks last when descending', () => {
    expect(ids(sortRegistrants(rows, 'postcode', 'desc'))).toEqual(['tas', 'vic', 'nsw', 'blank']);
  });

  it('treats whitespace-only values as blank', () => {
    const out = sortRegistrants([reg('ws', { email: '  ' }), reg('a', { email: 'a@x.com' })], 'email', 'asc');
    expect(ids(out)).toEqual(['a', 'ws']);
  });

  it('compares text case-insensitively', () => {
    const out = sortRegistrants([reg('b', { email: 'Bob@x.com' }), reg('a', { email: 'alice@x.com' })], 'email', 'asc');
    expect(ids(out)).toEqual(['a', 'b']);
  });

  it('compares date columns as instants', () => {
    const out = sortRegistrants(
      [
        reg('late', { registeredAt: '2026-01-02T00:00:00+11:00' }),
        reg('early', { registeredAt: '2026-01-01T12:00:00Z' }),
      ],
      'registeredAt',
      'asc',
    );
    // 2026-01-02 00:00 +11:00 is 2026-01-01 13:00Z, i.e. after 12:00Z.
    expect(ids(out)).toEqual(['early', 'late']);
  });

  it('groups "Yes" rows together on a flag column', () => {
    const out = sortRegistrants(
      [reg('n'), reg('y1', { codeOfConductAgreed: 'Yes' }), reg('y2', { codeOfConductAgreed: 'Yes' })],
      'codeOfConductAgreed',
      'asc',
    );
    expect(ids(out)).toEqual(['y1', 'y2', 'n']);
  });

  it('sorts by church name, blanks last', () => {
    const out = sortRegistrants(
      [reg('none'), reg('z', { churchName: 'Zion Baptist' }), reg('a', { churchName: 'abbotsford Church' })],
      'churchName',
      'asc',
    );
    expect(ids(out)).toEqual(['a', 'z', 'none']);
  });

  it('does not mutate its input', () => {
    const copy = [...rows];
    sortRegistrants(rows, 'postcode', 'asc');
    expect(rows).toEqual(copy);
  });
});

describe('paging', () => {
  const items = Array.from({ length: 1234 }, (_, i) => i);

  it('counts pages, minimum one', () => {
    expect(getPageCount(0, 100)).toBe(1);
    expect(getPageCount(1234, 100)).toBe(13);
    expect(getPageCount(1234, 'all')).toBe(1);
  });

  it('reaches rows beyond the old 500-row cap', () => {
    expect(getPageSlice(items, 13, 100)).toEqual(items.slice(1200));
    expect(getPageSlice(items, 6, 100)[0]).toBe(500);
  });

  it('clamps an out-of-range page', () => {
    expect(getPageSlice(items, 99, 100)).toEqual(items.slice(1200));
    expect(getPageSlice(items, 0, 100)[0]).toBe(0);
  });

  it('returns everything for "all"', () => {
    expect(getPageSlice(items, 1, 'all')).toHaveLength(1234);
  });
});

import { describe, it, expect } from 'vitest';
import {
  EDITABLE_REGISTRANT_FIELDS,
  EDITABLE_FIELD_COLUMNS,
  EDITABLE_FIELD_LABELS,
  isEditableRegistrantField,
  isValidAustralianPostcode,
  isValidRegistrantState,
  isValidNfcFlag,
  isValidRegistrantFieldValue,
} from '../registrantValidation';

describe('isEditableRegistrantField', () => {
  it('accepts each of the whitelisted fields', () => {
    for (const field of EDITABLE_REGISTRANT_FIELDS) {
      expect(isEditableRegistrantField(field)).toBe(true);
    }
  });

  it('rejects a field not on the whitelist, notably the identity keys', () => {
    expect(isEditableRegistrantField('email')).toBe(false);
    expect(isEditableRegistrantField('phone')).toBe(false);
    expect(isEditableRegistrantField('registeredAt')).toBe(false);
    expect(isEditableRegistrantField('id')).toBe(false);
  });
});

describe('EDITABLE_FIELD_COLUMNS', () => {
  it('maps every editable field to its real registry.registrants column', () => {
    expect(EDITABLE_FIELD_COLUMNS).toEqual({
      firstName: 'first_name',
      lastName: 'last_name',
      state: 'state',
      postcode: 'postcode',
      nfc: 'nfc',
    });
  });
});

describe('EDITABLE_FIELD_LABELS', () => {
  it('has exactly one label per DB column EDITABLE_FIELD_COLUMNS can write — the edit log must be able to label every row it might show', () => {
    const columns = Object.values(EDITABLE_FIELD_COLUMNS);
    expect(Object.keys(EDITABLE_FIELD_LABELS).sort()).toEqual([...columns].sort());
  });
});

describe('isValidAustralianPostcode', () => {
  it('accepts a plausible 4-digit postcode', () => {
    expect(isValidAustralianPostcode('3000')).toBe(true);
    expect(isValidAustralianPostcode('0800')).toBe(true);
  });

  it('rejects the wrong number of digits', () => {
    expect(isValidAustralianPostcode('300')).toBe(false);
    expect(isValidAustralianPostcode('30001')).toBe(false);
  });

  it('rejects non-numeric input', () => {
    expect(isValidAustralianPostcode('30AB')).toBe(false);
    expect(isValidAustralianPostcode('NFC')).toBe(false);
  });

  it('allows null or blank — clearing the field is valid, postcode is optional', () => {
    expect(isValidAustralianPostcode(null)).toBe(true);
    expect(isValidAustralianPostcode('')).toBe(true);
    expect(isValidAustralianPostcode('   ')).toBe(true);
  });

  it('tolerates surrounding whitespace on an otherwise-valid value', () => {
    expect(isValidAustralianPostcode(' 3000 ')).toBe(true);
  });
});

describe('isValidRegistrantState', () => {
  it('accepts every real state code', () => {
    for (const code of ['ACT', 'NSW', 'QLD', 'SA', 'TAS', 'VIC', 'WA', 'NT']) {
      expect(isValidRegistrantState(code)).toBe(true);
    }
  });

  it('rejects an unrecognized value — the dropdown should never send one, but the API must not trust that', () => {
    expect(isValidRegistrantState('XX')).toBe(false);
    expect(isValidRegistrantState('vic')).toBe(false); // lowercase — the dropdown sends canonical uppercase codes only
  });

  it('allows null or blank — clearing the state is valid', () => {
    expect(isValidRegistrantState(null)).toBe(true);
    expect(isValidRegistrantState('')).toBe(true);
  });
});

describe('isValidNfcFlag', () => {
  it('accepts exactly "Yes"', () => {
    expect(isValidNfcFlag('Yes')).toBe(true);
  });

  it('rejects any other non-blank value, notably "No" — this column is never a recorded No', () => {
    expect(isValidNfcFlag('No')).toBe(false);
    expect(isValidNfcFlag('yes')).toBe(false);
    expect(isValidNfcFlag('true')).toBe(false);
  });

  it('allows null or blank — clearing the flag is valid', () => {
    expect(isValidNfcFlag(null)).toBe(true);
    expect(isValidNfcFlag('')).toBe(true);
    expect(isValidNfcFlag('   ')).toBe(true);
  });
});

describe('isValidRegistrantFieldValue', () => {
  it('dispatches postcode values to isValidAustralianPostcode', () => {
    expect(isValidRegistrantFieldValue('postcode', '3000')).toBe(true);
    expect(isValidRegistrantFieldValue('postcode', 'bad')).toBe(false);
  });

  it('dispatches state values to isValidRegistrantState', () => {
    expect(isValidRegistrantFieldValue('state', 'NSW')).toBe(true);
    expect(isValidRegistrantFieldValue('state', 'bad')).toBe(false);
  });

  it('dispatches nfc values to isValidNfcFlag', () => {
    expect(isValidRegistrantFieldValue('nfc', 'Yes')).toBe(true);
    expect(isValidRegistrantFieldValue('nfc', 'No')).toBe(false);
  });

  it('imposes no format constraint on name fields', () => {
    expect(isValidRegistrantFieldValue('firstName', "O'Malley-Smith")).toBe(true);
    expect(isValidRegistrantFieldValue('lastName', '')).toBe(true);
  });
});

