import { describe, expect, it, vi } from 'vitest';
import { TRANSFORM_BATCH_LIMIT, transformPendingStagingEvents } from '../transform';
import type { DbPort, EmailPort, StagingEventRow } from '../ports';
import type { KnownSourceTag, RawAcContactPayload } from '../types';
import { NATIONAL_GROUP_KEY } from '../whatsappInvite';

const KNOWN_TAGS: KnownSourceTag[] = [
  { ac_tag_id: '48', tag_name: 'CAMPAIGN: TWOL Sept 2019 Register', source_label: 'wayoflife_interest' },
];

function makeEvent(id: number, overrides: Partial<RawAcContactPayload> = {}): StagingEventRow {
  return {
    id,
    raw_payload: {
      contact: { id: `ac-${id}`, email: 'jane@example.com', firstName: 'Jane', lastName: 'Doe', phone: '0438438438', cdate: '2026-01-15T10:00:00Z' },
      fieldValues: [{ field: '6', value: 'NSW' }],
      tags: [{ id: '48' }],
      listMembership: { contact: `ac-${id}`, list: '1', status: '1' },
      ...overrides,
    },
  };
}

function makeDb(events: StagingEventRow[], overrides: Partial<DbPort> = {}): DbPort {
  return {
    startSyncLog: vi.fn(),
    getLastCompletedSyncTimestamp: vi.fn(),
    insertStagingEvent: vi.fn(),
    completeSyncLog: vi.fn(),
    failSyncLog: vi.fn(),
    getPendingStagingEvents: vi.fn().mockResolvedValue(events),
    getKnownSourceTags: vi.fn().mockResolvedValue(KNOWN_TAGS),
    upsertRegistrant: vi.fn().mockResolvedValue({ id: 'registrant-1', isNew: true, unsubscribed: null }),
    insertRegistrationEvent: vi.fn().mockResolvedValue(undefined),
    insertTwolRespondent: vi.fn().mockResolvedValue(undefined),
    markStagingProcessed: vi.fn().mockResolvedValue(undefined),
    markStagingError: vi.fn().mockResolvedValue(undefined),
    markRegistrantUnsubscribedByEmail: vi.fn().mockResolvedValue(undefined),
    getSyncProgress: vi.fn().mockResolvedValue(null),
    saveSyncProgress: vi.fn().mockResolvedValue(undefined),
    clearSyncProgress: vi.fn().mockResolvedValue(undefined),
    recordPartialSync: vi.fn().mockResolvedValue(undefined),
    // No national link configured by default — most tests here don't care
    // about WhatsApp invites at all; override per-test where they do.
    getWhatsAppGroupLink: vi.fn().mockResolvedValue(null),
    logWhatsAppInviteAttempt: vi.fn().mockResolvedValue(undefined),
    ...overrides,
  };
}

describe('transformPendingStagingEvents', () => {
  it('upserts a registrant and records a registration event for an active submission', async () => {
    const db = makeDb([makeEvent(1)]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 1, errors: 0, partial: false });
    expect(db.upsertRegistrant).toHaveBeenCalledWith({
      acContactId: 'ac-1',
      firstName: 'Jane',
      lastName: 'Doe',
      email: 'jane@example.com',
      phone: '+61438438438',
      phoneRaw: '0438438438',
      state: 'NSW',
      postcode: null,
      registeredAt: '2026-01-15T10:00:00Z',
      interestedInTraining: null,
      churchLeader: null,
      // churchName is omitted (not null) when the contact has no church.
      // Tag [48] is present on this event's default payload (it's also the
      // known source tag), so codeOfConductAgreed derives to 'Yes' — the
      // other three tag/field-derived keys stay omitted (no webinar tags,
      // no cdate on tag 48, no field [24] in fieldValues).
      codeOfConductAgreed: 'Yes',
    });
    expect(db.insertRegistrationEvent).toHaveBeenCalledWith({
      registrantId: 'registrant-1',
      sourceListId: '1',
      sourceTag: 'CAMPAIGN: TWOL Sept 2019 Register',
      eventType: 'new_registration',
      rawStagingId: 1,
    });
    expect(db.markStagingProcessed).toHaveBeenCalledWith(1, null);
  });

  it('omits all four tag/field-derived keys entirely when no relevant tag or field is present — never writes null over an existing value', async () => {
    const db = makeDb([makeEvent(1, { tags: [{ id: '21' }] })]);
    await transformPendingStagingEvents(db);

    const call = (db.upsertRegistrant as ReturnType<typeof vi.fn>).mock.calls[0][0];
    expect(call).not.toHaveProperty('webinarSessionAt');
    expect(call).not.toHaveProperty('webinarAttended');
    expect(call).not.toHaveProperty('codeOfConductAgreed');
    expect(call).not.toHaveProperty('codeOfConductAgreedAt');
  });

  it('passes through webinarSessionAt, webinarAttended, and codeOfConductAgreed/At when all four signals are present', async () => {
    const db = makeDb([
      makeEvent(1, {
        fieldValues: [{ field: '6', value: 'NSW' }, { field: '24', value: '2022-07-05T08:30:00+10:00' }],
        tags: [{ id: '60' }, { id: '48', cdate: '2021-11-05T18:31:54-05:00' }],
      }),
    ]);
    await transformPendingStagingEvents(db);

    expect(db.upsertRegistrant).toHaveBeenCalledWith(
      expect.objectContaining({
        webinarSessionAt: '2022-07-05T08:30:00+10:00',
        webinarAttended: 'Yes',
        codeOfConductAgreed: 'Yes',
        codeOfConductAgreedAt: '2021-11-05T18:31:54-05:00',
      })
    );
  });

  it('skips a submission whose list status is not active, without touching registrants', async () => {
    const db = makeDb([makeEvent(2, { listMembership: { contact: 'ac-2', list: '1', status: '3' } })]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 0, errors: 0, partial: false });
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(2, 'skipped: list status not active');
  });

  it('marks an existing registrant unsubscribed when a later sync sees their list status go non-active', async () => {
    const db = makeDb([
      makeEvent(20, { listMembership: { contact: 'ac-20', list: '1', status: '2' } }),
    ]);
    await transformPendingStagingEvents(db);

    expect(db.markRegistrantUnsubscribedByEmail).toHaveBeenCalledWith('jane@example.com');
  });

  it('does not attempt to mark unsubscribed when the inactive-status contact has no email', async () => {
    const db = makeDb([
      makeEvent(21, {
        contact: { id: 'ac-21', email: null, firstName: 'Jane', lastName: 'Doe', phone: '0438438438', cdate: '2026-01-15T10:00:00Z' },
        listMembership: { contact: 'ac-21', list: '1', status: '2' },
      }),
    ]);
    await transformPendingStagingEvents(db);

    expect(db.markRegistrantUnsubscribedByEmail).not.toHaveBeenCalled();
  });

  it('skips a contact whose only signal is the excluded MailChimp-import tag, without creating a registrant', async () => {
    const db = makeDb([makeEvent(9, { tags: [{ id: '11' }] })]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 0, errors: 0, partial: false });
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(9, 'skipped: excluded source tag only (no recognized registration funnel)');
  });

  it('still creates a registrant when the excluded tag is present alongside a genuine recognized tag', async () => {
    const db = makeDb([makeEvent(10, { tags: [{ id: '11' }, { id: '48' }] })]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 1, errors: 0, partial: false });
    expect(db.upsertRegistrant).toHaveBeenCalled();
  });

  it('skips a contact whose only signal is the donation-form-only tag [40], without creating a registrant', async () => {
    const db = makeDb([makeEvent(13, { tags: [{ id: '40' }] })]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 0, errors: 0, partial: false });
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(13, 'skipped: excluded source tag only (no recognized registration funnel)');
  });

  it('skips a contact whose only signal is the blank "TWOL Explore More" tag [8]/[9], without creating a registrant', async () => {
    const db = makeDb([makeEvent(14, { tags: [{ id: '8' }, { id: '9' }] })]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 0, errors: 0, partial: false });
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(14, 'skipped: excluded source tag only (no recognized registration funnel)');
  });

  it('excludes a would-be-excluded contact even when their event is on AC List [2] — never reaches twol_respondents either', async () => {
    const db = makeDb([
      makeEvent(15, { tags: [{ id: '8' }], listMembership: { contact: 'ac-15', list: '2', status: '1' } }),
    ]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 0, errors: 0, partial: false });
    expect(db.insertTwolRespondent).not.toHaveBeenCalled();
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(15, 'skipped: excluded source tag only (no recognized registration funnel)');
  });

  it('excludes a "TWOL Video: Requested" (tag [6]) submission entirely, rather than routing it to twol_respondents', async () => {
    const db = makeDb([
      makeEvent(16, { tags: [{ id: '6' }], listMembership: { contact: 'ac-16', list: '2', status: '1' } }),
    ]);
    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 0, errors: 0, partial: false });
    expect(db.insertTwolRespondent).not.toHaveBeenCalled();
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(16, 'skipped: excluded source tag only (no recognized registration funnel)');
  });

  it('records a null source_tag when no known tag matches', async () => {
    const db = makeDb([makeEvent(3, { tags: [{ id: '999' }] })]);
    await transformPendingStagingEvents(db);

    expect(db.insertRegistrationEvent).toHaveBeenCalledWith(
      expect.objectContaining({ sourceTag: null })
    );
  });

  it('marks a staging row errored and continues processing subsequent events', async () => {
    const db = makeDb([makeEvent(4), makeEvent(5)]);
    (db.upsertRegistrant as ReturnType<typeof vi.fn>).mockRejectedValueOnce(new Error('db unavailable'));

    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 1, errors: 1, partial: false });
    expect(db.markStagingError).toHaveBeenCalledWith(4, 'db unavailable');
    expect(db.markStagingProcessed).toHaveBeenCalledWith(5, null);
  });

  it('passes through a populated postcode', async () => {
    const db = makeDb([
      makeEvent(6, { fieldValues: [{ field: '6', value: 'NSW' }, { field: '30', value: '3080' }] }),
    ]);
    await transformPendingStagingEvents(db);

    expect(db.upsertRegistrant).toHaveBeenCalledWith(expect.objectContaining({ postcode: '3080' }));
  });

  it('passes through a populated interestedInTraining', async () => {
    const db = makeDb([
      makeEvent(7, { fieldValues: [{ field: '6', value: 'NSW' }, { field: '9', value: 'Yes' }] }),
    ]);
    await transformPendingStagingEvents(db);

    expect(db.upsertRegistrant).toHaveBeenCalledWith(expect.objectContaining({ interestedInTraining: 'Yes' }));
  });

  it('passes through populated churchLeader and churchName', async () => {
    const db = makeDb([
      makeEvent(8, {
        fieldValues: [
          { field: '6', value: 'NSW' },
          { field: '28', value: 'Yes' },
          { field: '26', value: 'Eaton Baptist Church' },
        ],
      }),
    ]);
    await transformPendingStagingEvents(db);

    expect(db.upsertRegistrant).toHaveBeenCalledWith(
      expect.objectContaining({ churchLeader: 'Yes', churchName: 'Eaton Baptist Church' })
    );
  });

  it('reads the church from AC field [8], which the current Register Commitment form writes', async () => {
    const db = makeDb([makeEvent(9, { fieldValues: [{ field: '6', value: 'WA' }, { field: '8', value: 'St Mary' }] })]);
    await transformPendingStagingEvents(db);

    expect(db.upsertRegistrant).toHaveBeenCalledWith(expect.objectContaining({ churchName: 'St Mary' }));
  });

  it('omits churchName entirely when the contact has no church, so a re-sync cannot blank a stored one', async () => {
    const db = makeDb([makeEvent(10, { fieldValues: [{ field: '6', value: 'WA' }] })]);
    await transformPendingStagingEvents(db);

    const input = (db.upsertRegistrant as ReturnType<typeof vi.fn>).mock.calls[0][0];
    expect('churchName' in input).toBe(false);
  });

  it('routes an AC List [2] (/wayoflife-responder/) submission to twol_respondents, never registrants', async () => {
    const db = makeDb([
      makeEvent(11, {
        tags: [{ id: '1' }],
        listMembership: { contact: 'ac-11', list: '2', status: '1' },
      }),
    ], {
      getKnownSourceTags: vi.fn().mockResolvedValue([
        { ac_tag_id: '1', tag_name: 'FORM: Way of life responder: Completed', source_label: 'wayoflife_responder' },
      ]),
    });

    const result = await transformPendingStagingEvents(db);

    expect(result).toEqual({ recordsUpserted: 1, errors: 0, partial: false });
    expect(db.insertTwolRespondent).toHaveBeenCalledWith({
      acContactId: 'ac-11',
      firstName: 'Jane',
      lastName: 'Doe',
      email: 'jane@example.com',
      phone: '+61438438438',
      phoneRaw: '0438438438',
      state: 'NSW',
      registeredAt: '2026-01-15T10:00:00Z',
      sourceTag: 'FORM: Way of life responder: Completed',
      rawStagingId: 11,
    });
    expect(db.upsertRegistrant).not.toHaveBeenCalled();
    expect(db.insertRegistrationEvent).not.toHaveBeenCalled();
    expect(db.markStagingProcessed).toHaveBeenCalledWith(11, null);
  });

  it('never sends a WhatsApp invite for an AC List [2] submission, even when a national link is configured', async () => {
    const db = makeDb([
      makeEvent(12, { listMembership: { contact: 'ac-12', list: '2', status: '1' } }),
    ], { getWhatsAppGroupLink: vi.fn().mockResolvedValue('https://chat.whatsapp.com/abc123') });
    const email: EmailPort = { sendWhatsAppInviteEmail: vi.fn().mockResolvedValue({ resendMessageId: 'msg-1', includedCampaignsNearMeLink: false }) };

    await transformPendingStagingEvents(db, { email });

    expect(email.sendWhatsAppInviteEmail).not.toHaveBeenCalled();
    expect(db.insertTwolRespondent).toHaveBeenCalled();
  });

  it('passes the batch limit through to getPendingStagingEvents', async () => {
    const db = makeDb([]);
    await transformPendingStagingEvents(db);

    expect(db.getPendingStagingEvents).toHaveBeenCalledWith(TRANSFORM_BATCH_LIMIT);
  });

  it('reports partial and leaves later rows untouched once the deadline passes', async () => {
    const db = makeDb([makeEvent(1), makeEvent(2), makeEvent(3)]);
    let calls = 0;
    const now = () => {
      calls++;
      // First two checks (before events 1 and 2) pass; the third (before event 3) trips.
      return calls < 3 ? 0 : 1000;
    };

    const result = await transformPendingStagingEvents(db, { deadline: 1000, now });

    expect(result).toEqual({ recordsUpserted: 2, errors: 0, partial: true });
    expect(db.markStagingProcessed).toHaveBeenCalledWith(1, null);
    expect(db.markStagingProcessed).toHaveBeenCalledWith(2, null);
    expect(db.markStagingProcessed).not.toHaveBeenCalledWith(3, null);
  });

  it('reports partial when a full batch is returned, even without hitting the time budget', async () => {
    const fullBatch = Array.from({ length: TRANSFORM_BATCH_LIMIT }, (_, i) => makeEvent(i + 1));
    const db = makeDb(fullBatch);

    const result = await transformPendingStagingEvents(db);

    expect(result.partial).toBe(true);
    expect(result.recordsUpserted).toBe(TRANSFORM_BATCH_LIMIT);
  });

  it('does not report partial when fewer than a full batch is returned and nothing timed out', async () => {
    const db = makeDb([makeEvent(1)]);
    const result = await transformPendingStagingEvents(db);

    expect(result.partial).toBe(false);
  });
});

describe('WhatsApp invite email', () => {
  function makeEmail(): EmailPort {
    return { sendWhatsAppInviteEmail: vi.fn().mockResolvedValue({ resendMessageId: 'msg-1', includedCampaignsNearMeLink: true }) };
  }

  it('sends the invite for a genuinely new registrant with an email, when a national link is configured, and logs the send', async () => {
