import { shouldSendWhatsAppInvite, buildWhatsAppInviteEmail, NATIONAL_GROUP_KEY } from '../whatsappInvite';

describe('NATIONAL_GROUP_KEY', () => {
  it('is a stable, non-empty key', () => {
    expect(NATIONAL_GROUP_KEY).toBe('national');
  });
});

describe('shouldSendWhatsAppInvite', () => {
  it('sends for a genuinely new registrant with an email', () => {
    expect(shouldSendWhatsAppInvite({ isNew: true, email: 'jane@example.com', unsubscribed: null })).toBe(true);
  });

  it('does not send for an existing registrant being re-synced, even with an email', () => {
    expect(shouldSendWhatsAppInvite({ isNew: false, email: 'jane@example.com', unsubscribed: null })).toBe(false);
  });

  it('does not send for a new registrant with no email on file', () => {
    expect(shouldSendWhatsAppInvite({ isNew: true, email: null, unsubscribed: null })).toBe(false);
  });

  it('does not send for a new registrant with an empty-string email', () => {
    expect(shouldSendWhatsAppInvite({ isNew: true, email: '', unsubscribed: null })).toBe(false);
  });

  it('does not send for a new registrant already flagged unsubscribed, even with an email', () => {
    expect(shouldSendWhatsAppInvite({ isNew: true, email: 'jane@example.com', unsubscribed: 'Yes' })).toBe(false);
  });
});

describe('buildWhatsAppInviteEmail', () => {
  it('greets the registrant by first name and includes the invite link in both html and text', () => {
    const { subject, html, text } = buildWhatsAppInviteEmail('Jane', 'https://chat.whatsapp.com/abc123', null);
    expect(subject).toMatch(/WhatsApp/);
    expect(text).toContain('Hi Jane,');
    expect(text).toContain('https://chat.whatsapp.com/abc123');
    expect(html).toContain('Hi Jane,');
    expect(html).toContain('href="https://chat.whatsapp.com/abc123"');
  });

  it('falls back to a generic greeting when there is no first name on file', () => {
    const { text, html } = buildWhatsAppInviteEmail(null, 'https://chat.whatsapp.com/abc123', null);
    expect(text).toContain('Hi there,');
    expect(html).toContain('Hi there,');
  });

  it('escapes a first name containing HTML-significant characters', () => {
    const { html } = buildWhatsAppInviteEmail('<script>alert(1)</script>', 'https://chat.whatsapp.com/abc123', null);
    expect(html).not.toContain('<script>');
    expect(html).toContain('&lt;script&gt;');
  });

  it('trims a first name that is present but blank/whitespace-only, falling back to the generic greeting', () => {
    const { text } = buildWhatsAppInviteEmail('   ', 'https://chat.whatsapp.com/abc123', null);
    expect(text).toContain('Hi there,');
  });

  it('omits the campaigns-near-me section entirely when no URL is given', () => {
    const { text, html } = buildWhatsAppInviteEmail('Jane', 'https://chat.whatsapp.com/abc123', null);
    expect(text).not.toContain('campaigns happening near you');
    expect(html).not.toContain('campaigns happening near you');
    expect(text).not.toContain('Keep this link safe');
    expect(html).not.toContain('Keep this link safe');
  });

  it('includes a campaigns-near-me section, with the link, when a URL is given', () => {
    const mapUrl = 'https://campaign.afj.org.au/public/campaigns-near-me?r=abc-123';
    const { text, html } = buildWhatsAppInviteEmail('Jane', 'https://chat.whatsapp.com/abc123', mapUrl);
    expect(text).toContain('campaigns happening near you');
    expect(text).toContain(mapUrl);
    expect(html).toContain('campaigns happening near you');
    expect(html).toContain(`href="${mapUrl}"`);
  });

  it('reminds the reader to keep the campaigns-near-me link, right after the link itself', () => {
    const mapUrl = 'https://campaign.afj.org.au/public/campaigns-near-me?r=abc-123';
    const { text, html } = buildWhatsAppInviteEmail('Jane', 'https://chat.whatsapp.com/abc123', mapUrl);
    const reminder = 'Keep this link safe and click on it anytime to get an up-to-date view of campaigns near you, and register your interest in joining one.';
    expect(text.indexOf(mapUrl)).toBeLessThan(text.indexOf(reminder));
    expect(html).toContain(`<p>${reminder}</p>`);
  });

  it('still includes the WhatsApp invite link and sign-off when the campaigns-near-me section is present', () => {
    const { text } = buildWhatsAppInviteEmail('Jane', 'https://chat.whatsapp.com/abc123', 'https://campaign.afj.org.au/public/campaigns-near-me?r=abc-123');
    expect(text).toContain('https://chat.whatsapp.com/abc123');
    expect(text).toContain('The AFJ Team');
  });
});

// Planning logic for scripts/backfill_church_from_staging.ts — the registrants
// whose church_name is blank only because ac-sync never read AC field [8]
// (every registrant synced since the "AFJ Register Commitment" form started
// writing the church there), recovered from the raw payloads already saved in
// staging.ac_events. Pure and IO-free so the rules are unit tested.
import { mapAcFields } from './fieldMap';
import type { RawAcContactPayload } from './types';

export interface BlankChurchRegistrant {
  id: string;
  acContactId: string;
  email: string | null;
}

export interface ChurchBackfillUpdate {
  registrantId: string;
  acContactId: string;
  email: string | null;
  churchName: string;
}

/**
 * For each registrant with a blank church, the church found in that AC
 * contact's most recent staging payload (the caller passes the latest event
 * per contact). A registrant with no payload, or whose latest payload still
 * has no church, is left out — this only ever fills, never clears.
 */
export function planChurchBackfill(
  registrants: BlankChurchRegistrant[],
  latestPayloadByContact: Map<string, RawAcContactPayload>,
): ChurchBackfillUpdate[] {
  const updates: ChurchBackfillUpdate[] = [];
  for (const r of registrants) {
    const payload = latestPayloadByContact.get(r.acContactId);
    if (!payload) continue;
    const churchName = mapAcFields(payload).churchName;
    if (!churchName) continue;
    updates.push({ registrantId: r.id, acContactId: r.acContactId, email: r.email, churchName });
  }
  return updates;
}

lib/registryPipeline/csvParse.ts:
// Minimal RFC 4180-ish CSV parser — no dependency added for a one-time
// reload script. Handles quoted fields (including embedded commas,
// embedded newlines, and "" as an escaped quote), which a naive
// String.split(',') cannot: at least one real value in
// AFJ Registrations.csv contains a comma inside a quoted field
// ("Huon Valley Christian Life Centre, Cygnet").

/** Parses a full CSV document (already stripped of any leading BOM) into rows of raw string cells. */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];

    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
      continue;
    }

    if (c === '"') {
      inQuotes = true;
    } else if (c === ',') {
      row.push(field);
      field = '';
    } else if (c === '\r') {
      // ignore — paired \n (or a lone \r) handles the line break
    } else if (c === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
    } else {
      field += c;
    }
  }

  // Final field/row if the file doesn't end with a newline.
  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

/** Strips a UTF-8 BOM if present — AFJ Registrations.csv (and most Excel CSV exports) start with one. */
export function stripBom(text: string): string {
  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
}

lib/registryPipeline/csvRegistrantTransf:
// Transform rules for the registrations CSV reload. See
// docs/registry-pipeline/OPERATIONS.md's two 2026-09-07 entries for the
// full decision history — this module is the implementation of those
// decisions, kept framework/IO-free so every rule is independently
// testable (scripts/reload_registrants_from_csv.ts is the thin script
// that reads the actual file and calls into this).

export interface RawCsvRow {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  state: string;
  postcode: string;
  church: string;
  regd: string; // D/M/YYYY text, as found in the source
  webinar: string; // D/M/YYYY HH:MM text — the webinar SESSION date/time (confirmed live against AC field [24]), not a rego date
  webinarDone: string; // "Yes"/"No" text, as found in the source
  code: string; // "YES"/blank text — never "No" in the source data
  dateAgreed: string; // D/M/YYYY text, as found in the source
  lineNumber: number; // 1-indexed CSV line, for traceability in logs/errors
}

export interface TransformedRegistrant {
  firstName: string | null;
  lastName: string | null;
  email: string | null;
  phoneRaw: string | null;
  state: string | null;
  postcode: string | null;
  churchName: string | null;
  registeredAt: string | null; // ISO date (midnight UTC — the source has no time component)
  unsubscribed: 'Yes' | null;
  nfc: 'Yes' | null;
  webinarSessionAt: string | null; // ISO date/time (midnight UTC when the source has no time component)
  webinarAttended: 'Yes' | 'No' | null;
  codeOfConductAgreed: 'Yes' | null; // never 'No' — see parseYesNo's caller-side narrowing below
  codeOfConductAgreedAt: string | null; // ISO date (midnight UTC — the source has no time component)
  sourceLines: number[]; // CSV line(s) this row was built from — 1 normally, >1 after a dedup merge
}

/** Rows with these states are excluded from the reload entirely (decision 3) — not loaded with a null/placeholder state, skipped. */
export const EXCLUDED_NON_AU_STATES = ['OS', 'NZ', 'UK'];

/**
 * Case-insensitive "does this value contain the marker, and what's left
 * after removing it" — shared by both the NFC-in-postcode check (decision
 * 7) and the UNSUBSCRIBED-in-Church check (decision 4). Removes the
 * marker as actually cased in the source, wherever it's found, and
 * collapses the whitespace left behind.
 */
export function extractMarker(raw: string, marker: string): { found: boolean; cleaned: string } {
  const re = new RegExp(marker, 'i');
  const match = raw.match(re);
  if (!match) return { found: false, cleaned: raw.trim() };
  const cleaned = (raw.slice(0, match.index) + raw.slice((match.index ?? 0) + match[0].length))
    .replace(/\s+/g, ' ')
    .trim();
  return { found: true, cleaned };
}

const VALID_AU_POSTCODE = /^\d{4}$/;

/** Decision 7 then decision 2, in that order: NFC marker is checked before the postcode is validated/nulled. */
export function extractPostcode(raw: string): { postcode: string | null; nfc: 'Yes' | null } {
  const { found, cleaned } = extractMarker(raw, 'NFC');
  const postcode = VALID_AU_POSTCODE.test(cleaned) ? cleaned : null;
  return { postcode, nfc: found ? 'Yes' : null };
}

/** Decision 4: UNSUBSCRIBED marker in the Church field. */
export function extractChurch(raw: string): { churchName: string | null; unsubscribed: 'Yes' | null } {
  const { found, cleaned } = extractMarker(raw, 'UNSUBSCRIBED');
  return { churchName: cleaned || null, unsubscribed: found ? 'Yes' : null };
}

/** "D/M/YYYY" (as found in the CSV's Regd column) -> ISO date at midnight UTC. Null if unparseable. */
export function parseAuDate(raw: string): string | null {
  const match = raw.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!match) return null;
  const [, d, m, y] = match;
  const day = Number(d);
  const month = Number(m);
  const year = Number(y);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  const iso = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  // Validate it round-trips (catches e.g. 31/02/2020) rather than trusting the regex alone.
  const d2 = new Date(`${iso}T00:00:00Z`);
  if (d2.getUTCFullYear() !== year || d2.getUTCMonth() + 1 !== month || d2.getUTCDate() !== day) return null;
  return `${iso}T00:00:00Z`;
}

/** "D/M/YYYY HH:MM" (the CSV's Webinar column — a session date/time, confirmed live against AC field [24]) -> ISO datetime. Null if unparseable. */
export function parseAuDateTime(raw: string): string | null {
  const match = raw.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4}) (\d{1,2}):(\d{2})$/);
  if (!match) return null;
  const [, d, m, y, h, min] = match;
  const day = Number(d);
  const month = Number(m);
  const year = Number(y);
  const hour = Number(h);
  const minute = Number(min);
  if (month < 1 || month > 12 || day < 1 || day > 31 || hour > 23 || minute > 59) return null;
  const iso = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}T${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:00Z`;
  const d2 = new Date(iso);
  if (d2.getUTCFullYear() !== year || d2.getUTCMonth() + 1 !== month || d2.getUTCDate() !== day || d2.getUTCHours() !== hour || d2.getUTCMinutes() !== minute) {
    return null;
  }
  return iso;
}

/** Trims and case-normalizes a Yes/No-ish CSV cell. Anything other than an unambiguous yes/no (blank, "?", a note) is null — never guessed. */
export function parseYesNo(raw: string): 'Yes' | 'No' | null {
  const value = raw.trim().toLowerCase();
  if (value === 'yes' || value === 'y') return 'Yes';
  if (value === 'no' || value === 'n') return 'No';
  return null;
}

export type RowTransformResult =
  | { status: 'included'; registrant: TransformedRegistrant }
  | { status: 'excluded_non_au_state'; state: string };

/** Per-row transform — everything decidable without looking at any other row. Cross-row de-duplication (dedupeByEmail) runs after this. */
export function transformRow(raw: RawCsvRow): RowTransformResult {
  const state = raw.state.trim().toUpperCase() || null;
  if (state && EXCLUDED_NON_AU_STATES.includes(state)) {
    return { status: 'excluded_non_au_state', state };
  }

  const { postcode, nfc } = extractPostcode(raw.postcode);
  const { churchName, unsubscribed } = extractChurch(raw.church);

  return {
    status: 'included',
    registrant: {
      firstName: raw.firstName.trim() || null,
      lastName: raw.lastName.trim() || null,
      email: raw.email.trim() || null,
      phoneRaw: raw.phone.trim() || null,
      state,
      postcode,
      churchName,
      registeredAt: parseAuDate(raw.regd),
      unsubscribed,
      nfc,
      webinarSessionAt: parseAuDateTime(raw.webinar),
      webinarAttended: parseYesNo(raw.webinarDone),
      // "Code" is never anything but blank/"YES" in the source (confirmed
      // live) — narrowed to Yes-or-null here rather than storing a literal
      // 'No' that the column never actually contains.
      codeOfConductAgreed: parseYesNo(raw.code) === 'Yes' ? 'Yes' : null,
      codeOfConductAgreedAt: parseAuDate(raw.dateAgreed),
      sourceLines: [raw.lineNumber],
    },
  };
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

function groupBy<T>(items: T[], keyOf: (item: T) => string): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const item of items) {
    const key = keyOf(item);
    const existing = map.get(key);
    if (existing) {
      existing.push(item);
    } else {
      map.set(key, [item]);
    }
  }
  return map;
}

function normalizeName(r: TransformedRegistrant): string {
  return `${r.firstName ?? ''} ${r.lastName ?? ''}`.trim().toLowerCase().replace(/\s+/g, ' ');
}

/** Non-null values win; when both sides have a (different) non-null value, the chronologically later row wins — see OPERATIONS.md decision 6's Pattern C. */
function mergeField<K extends keyof TransformedRegistrant>(
  rows: TransformedRegistrant[],
  key: K,
): TransformedRegistrant[K] {
  const sorted = [...rows].sort((a, b) => (a.registeredAt ?? '').localeCompare(b.registeredAt ?? ''));
  let result: TransformedRegistrant[K] | null = null;
  for (const r of sorted) {
    const v = r[key];
    if (v !== null && v !== undefined && v !== '') result = v;
  }
  return (result ?? sorted[sorted.length - 1][key]) as TransformedRegistrant[K];
}

function mergeSameEmailCluster(rows: TransformedRegistrant[]): TransformedRegistrant {
  if (rows.length === 1) return rows[0];
  return {
    firstName: mergeField(rows, 'firstName'),
    lastName: mergeField(rows, 'lastName'),
    email: rows[0].email,
    phoneRaw: mergeField(rows, 'phoneRaw'),
    state: mergeField(rows, 'state'),
    postcode: mergeField(rows, 'postcode'),
    churchName: mergeField(rows, 'churchName'),
    registeredAt: mergeField(rows, 'registeredAt'),
    unsubscribed: rows.some((r) => r.unsubscribed === 'Yes') ? 'Yes' : null,
    nfc: rows.some((r) => r.nfc === 'Yes') ? 'Yes' : null,
    webinarSessionAt: mergeField(rows, 'webinarSessionAt'),
    // Attendance is the stronger signal: if any row says Yes, Yes wins over
    // any row saying No (same idiom as unsubscribed/nfc, but with an
    // explicit precedence since this field has a genuine third value).
    webinarAttended: rows.some((r) => r.webinarAttended === 'Yes')
      ? 'Yes'
      : rows.some((r) => r.webinarAttended === 'No')
        ? 'No'
        : null,
    codeOfConductAgreed: rows.some((r) => r.codeOfConductAgreed === 'Yes') ? 'Yes' : null,
    codeOfConductAgreedAt: mergeField(rows, 'codeOfConductAgreedAt'),
    sourceLines: rows.flatMap((r) => r.sourceLines),
  };
}

/**
 * De-duplicates by normalized email (OPERATIONS.md decision "identity
 * redesigned" + decision 6). Within a group sharing one email, rows are
 * further split by normalized name: this is what generalizes the
 * steve.i.walker@icloud.com / "Cilla Geldenhuys" anomaly into an
 * algorithmic rule rather than a hardcoded special case — a differently-
 * named row sharing someone else's email is treated as a *different*
 * person who doesn't legitimately own that email (resolved as option
 * (b): she keeps her own row, with the email removed, matchable only by
 * phone going forward). The name sub-group with the most rows keeps the
 * email; every other sub-group's rows have their email cleared. Ties
 * broken by whichever sub-group's earliest row is chronologically first.
 */
export function dedupeByEmail(registrants: TransformedRegistrant[]): TransformedRegistrant[] {
  const noEmail = registrants.filter((r) => !r.email);
  const withEmail = registrants.filter((r): r is TransformedRegistrant & { email: string } => !!r.email);
  const byEmail = groupBy(withEmail, (r) => normalizeEmail(r.email));

  const result: TransformedRegistrant[] = [...noEmail];

  for (const group of byEmail.values()) {
    if (group.length === 1) {
      result.push(group[0]);
      continue;
    }

    const byName = groupBy(group, normalizeName);

    if (byName.size === 1) {
      result.push(mergeSameEmailCluster(group));
      continue;
    }

    // Genuinely different names sharing one email — pick the owner
    // sub-group (most rows, then earliest first row) and strip the email
    // from everyone else.
    const subgroups = [...byName.values()].sort((a, b) => {
      if (b.length !== a.length) return b.length - a.length;
      const aFirst = [...a].sort((x, y) => (x.registeredAt ?? '').localeCompare(y.registeredAt ?? ''))[0];
      const bFirst = [...b].sort((x, y) => (x.registeredAt ?? '').localeCompare(y.registeredAt ?? ''))[0];
      return (aFirst.registeredAt ?? '').localeCompare(bFirst.registeredAt ?? '');
    });

    const [owner, ...others] = subgroups;
    result.push(mergeSameEmailCluster(owner));
    for (const other of others) {
      for (const r of other) {
        result.push({ ...r, email: null });
      }
    }
  }

  return result;
}

lib/registryPipeline/fieldMap.ts:
// Field-inclusion enforcement for the registry pipeline.
// See docs/registry-pipeline/AFJ_PII_Technical_Implementation_Plan.md
// Section 3.4 — field inclusion/exclusion is final, confirmed by AFJ
// leadership. This module is a whitelist, not a blacklist: mapAcFields()
// only ever reads AC custom-field IDs listed in ALLOWED_CUSTOM_FIELD_IDS,
// so a field id that's missing from this list is unreadable by
// construction, not just "not currently read" — a future accidental
// change to AC's forms (e.g. a new field reusing an old excluded ID,
// or someone extending this file carelessly) can't silently reintroduce
// a sensitive field into the registry without a deliberate edit here.

import type { AcFieldValue, MappedRegistrantFields, RawAcContactPayload } from './types.ts';
import { normalizeAcDate } from './tagDerivedFields.ts';

/**
 * AC custom-field IDs this pipeline is allowed to read (plan Section 3.4).
 * Standard contact fields (name, email, phone) aren't custom fields and
 * are read directly off `contact` — see mapAcFields below.
 *
 * NOT included, deliberately, per plan 3.4 (never add these back without
 * a new AFJ leadership decision): [15] Denomination, [4] Did they say the
 * response prayer?, [12] How much would you like to give?, [13] How can
 * you support AFJ?, [20] Music Leader, [21] Website (an AC *field* ID —
 * unrelated to AC *tag* [21] used for source attribution, see
 * sourceAttribution.ts), [29] Webinar Replay Link, [11]
 * Country, and the wayoflife-responder response-outcome fields.
 *
 * [10]/[28] Church Leader? and [14]/[26] Church Name / What Church do you
 * attend? were ALSO originally excluded here on the same basis — reversed
 * 2026-09-01, Peter confirmed both are now needed. [8] Church was excluded
 * with them, but it is the field the current "AFJ Register Commitment" form
 * actually writes the church to — reversed 2026-11-03 (every registrant
 * synced since 10 Sept had a blank church because only [26]/[14] were read).
 */
export const ALLOWED_CUSTOM_FIELD_IDS = {
  /** [6] State (free text) — confirmed canonical, populated on all tested List-1 pages. */
  STATE: '6',
  /** [25] AU State (dropdown) — fallback only; never populated on any tested submission. */
  AU_STATE_FALLBACK: '25',
  /**
   * [30] Post Code. Reverses the original plan Section 3.4/3.5 exclusion
   * ("not currently capturable — data loss identified") — that was a
   * landing-page bug (postcode never reached AC at all, for any
   * submission), not a pipeline decision. Confirmed fixed upstream and
   * live-tested by Peter (two real test registrations, real postcode
   * values landed on field [30], created 2026-08-26 per ac_discovery.js —
   * i.e. the field itself is brand new). Historical registrants will NOT
   * be retroactively backfilled with postcode by AC — this only appears
   * on registrations from ~2026-08-26 onward, so `postcode` being null is
   * expected and normal for anyone registered before then.
   */
  POSTCODE: '30',
  /** [9] Interested in training? — confirmed live/populated per plan 3.4. Promoted to registry.registrants.interested_in_training (2026-09-01, per Peter). */
  INTERESTED_IN_TRAINING: '9',
  /**
   * [28] Are you a church leader? (dropdown, newer form) / [10] Church
   * Leader? (hidden, older form) — same old/new pairing already seen for
   * State [6]/[25] and training [9]/[27]. Reverses the original plan 3.4
   * exclusion ("Sensitive-adjacent; leadership decision") — confirmed by
   * Peter 2026-09-01 that this is now needed.
   */
  CHURCH_LEADER: '28',
  CHURCH_LEADER_FALLBACK: '10',
  /**
   * [26] What Church do you attend? (newer) / [14] Church Name (older) —
   * same pairing pattern. Reverses the original plan 3.4 exclusion
   * ("Confirmed by AFJ leadership") — confirmed by Peter 2026-09-01 that
   * this is now needed.
   */
  CHURCH_NAME: '26',
  CHURCH_NAME_FALLBACK: '14',
  /** [8] Church — what the current Register Commitment form writes (see the note above). Last in the fallback order. */
  CHURCH_NAME_FALLBACK_2: '8',
  /**
   * [23] BOTJ Webinar Rego Date (date-only). Confirmed live/populated and
   * included per plan 3.4, but registry.registrants has no column for it —
   * preserved untouched in staging.ac_events.raw_payload, not promoted.
   * Distinct from [24] below: confirmed live (2026-09-15) that Lorraine's
   * CSV "Webinar" column matches [24]'s value, not this one — no CSV
   * column maps to Rego Date, so there is no operational need to promote
   * it. Do not read it further without adding a registrants column first.
   */
  BOTJ_WEBINAR_REGO_DATE: '23',
  /**
   * [24] BOTJ Webinar Session (datetime). Promoted to
   * registry.registrants.webinar_session_at (2026-09-15, per Peter) —
   * confirmed live against 8 shared records between Lorraine's CSV
   * "Webinar" column and Jordan's tracking spreadsheet's own "Session
   * Date" column, always an exact match including time-of-day.
   */
  BOTJ_WEBINAR_SESSION: '24',
} as const;

function findFieldValue(fieldValues: readonly AcFieldValue[], fieldId: string): string | null {
  const match = fieldValues.find((fv) => fv.field === fieldId);
  const value = match?.value?.trim();
  return value ? value : null;
}

/**
 * Maps a raw AC contact payload to the fields the registry actually stores.
 * This is the sole place allowed to read AC custom fields — see
 * ALLOWED_CUSTOM_FIELD_IDS above. Never index `fieldValues` by an ID that
 * isn't in that whitelist.
 */
export function mapAcFields(payload: RawAcContactPayload): MappedRegistrantFields {
  const { contact, fieldValues } = payload;

  const state =
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.STATE) ??
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.AU_STATE_FALLBACK);

  const churchLeader =
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.CHURCH_LEADER) ??
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.CHURCH_LEADER_FALLBACK);

  const churchName =
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.CHURCH_NAME) ??
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.CHURCH_NAME_FALLBACK) ??
    findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.CHURCH_NAME_FALLBACK_2);

  return {
    firstName: contact.firstName?.trim() || null,
    lastName: contact.lastName?.trim() || null,
    email: contact.email?.trim() || null,
    phoneRaw: contact.phone?.trim() || null,
    state,
    postcode: findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.POSTCODE),
    registeredAt: contact.cdate?.trim() || null,
    interestedInTraining: findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.INTERESTED_IN_TRAINING),
    churchLeader,
    churchName,
    webinarSessionAt: normalizeAcDate(findFieldValue(fieldValues, ALLOWED_CUSTOM_FIELD_IDS.BOTJ_WEBINAR_SESSION)),
  };
}

lib/registryPipeline/leaderMatch.ts:
// Cross-references registry.registrants against public.state_leaders by
// normalized phone number — the only field both systems reliably collect.
// state_leaders does now carry an email column (added for the leader
// email-capture rollout — see CLAUDE.md's "Leader email capture" section),
// but it's still unpopulated for most rows and login there remains
// mobile+name (see lib/auth.ts), so phone stays the reliable join key here.
// Name matching isn't used: state_leaders.leader is one
// combined free-text field while registry.registrants splits first/last,
// so it's exactly the kind of fuzzy comparison that produces false
// positives/negatives. Kept pure/framework-free, same precedent as the
// rest of lib/registryPipeline/ — see app/api/registry/manage-summary/route.ts
// for where this actually runs (a live join on every request, not a
// stored/synced column — see that file's header comment for why).
//
// Deliberately just a yes/no + the matched leader's name for a hover
// confirmation — not which state they lead (Peter only needs to know a
// registrant is a leader at all, not where).
import { normalizePhone } from './phone';

/** Just enough of a state_leaders row to match against — state_leaders.mobile is in the main app's local '0XXXXXXXXX' format, normalized here the same way registry.registrants.phone already is. */
export interface LeaderForMatch {
  leader: string;
  mobile: string | null;
}

export interface LeaderMatch {
  leaderName: string;
}

/**
 * One normalized phone -> leader. If two leader rows somehow share a phone
 * (state_leaders has no uniqueness constraint on mobile alone), the later
 * one in the input array wins — an edge case not worth failing over, since
 * this is an informational cross-reference, not an identity system.
 */
export function buildLeaderPhoneIndex(leaders: LeaderForMatch[]): Map<string, LeaderForMatch> {
  const index = new Map<string, LeaderForMatch>();
  for (const leader of leaders) {
    const phone = normalizePhone(leader.mobile);
    if (phone) index.set(phone, leader);
  }
  return index;
}

export function findMatchingLeader(registrantPhone: string | null, index: Map<string, LeaderForMatch>): LeaderMatch | null {
  const phone = normalizePhone(registrantPhone);
  if (!phone) return null;
  const leader = index.get(phone);
  return leader ? { leaderName: leader.leader } : null;
}

/** Convenience entry point: tags every registrant with whether (and who) a state_leaders row matches its phone. Generic over T so callers get back their own richer row type, same pattern as registrantCounts.ts's filterRegistrantsForCell. */
export function matchRegistrantsToLeaders<T extends { phone: string | null }>(
  registrants: T[],
  leaders: LeaderForMatch[],
): (T & { isLeader: boolean; leaderName: string | null })[] {
  const index = buildLeaderPhoneIndex(leaders);
  return registrants.map((registrant) => {
    const match = findMatchingLeader(registrant.phone, index);
    return { ...registrant, isLeader: !!match, leaderName: match?.leaderName ?? null };
  });
}

lib/registryPipeline/listFilter.ts:
// List-scoping predicates for the registry pipeline.
// See docs/registry-pipeline/AFJ_PII_Technical_Implementation_Plan.md
// Sections 3.6 and 6.1/6.2.

/**
 * AC lists that are permanently excluded from the registry: List 3
 * ("Business Life") and List 5 ("Tony Mclennan") — see plan Section 3.6.
 * Enforced at the sync step (before a contact ever reaches staging), not
 * just in the transform, as defense-in-depth: List 5 contacts include
 * sensitive financial-intent field data, so it should never be one
 * accidental query away from entering the registry (plan Section 6.1).
 */
export const EXCLUDED_LIST_IDS: readonly string[] = ['3', '5'];

/** True if this AC list ID must never be synced into the registry. */
export function isExcludedList(listId: string): boolean {
  return EXCLUDED_LIST_IDS.includes(listId);
}

/**
 * AC's `contactLists` status for "actively subscribed". Confirmed via real
 * test data that status can be a value other than '1' (e.g. '3', seen on a
 * bounced test email) — anything else must be skipped rather than assumed
 * to be an active registrant (plan Section 6.2 / Section 10 open question).
 */
const ACTIVE_LIST_STATUS = '1';

/** True if this AC contactLists membership status counts as an active registrant. */
export function isActiveListStatus(status: string | null | undefined): boolean {
  return status === ACTIVE_LIST_STATUS;
}

// Shared shapes between the /registry/manage API routes
// (app/api/registry/manage-summary/route.ts, manage-record/route.ts,
// manage-edit-log/route.ts, manage-whatsapp-invite-log/route.ts) and their
// pages (app/registry/manage/page.tsx, app/registry/manage/edit-log/page.tsx,
// app/registry/manage/whatsapp-invite-log/page.tsx) — kept out of route.ts
// itself, same reason as recentRegistrationTypes.ts: Next.js's App Router
// restricts a route.ts's exports to recognized HTTP methods and route
// config.
import type { EditableRegistrantField } from './registrantValidation';

/** One row of registry.sync_log, whichever ran most recently regardless of outcome — see supabase/functions/ac-sync/db.ts and scripts/add_status_to_sync_log.sql for what writes these. */
export interface SyncLogSummary {
  startedAt: string;
  completedAt: string | null;
  status: 'success' | 'failed' | 'partial' | 'crashed' | null;
  recordsIn: number | null;
  recordsUpserted: number | null;
  errors: number | null;
  notes: string | null;
}

/**
 * One registry.registrants row, as shown on the Manage console: enough to
 * both tally the grid (state/registeredAt — see
 * lib/registryPipeline/registrantCounts.ts) and, when a national admin
 * clicks a non-zero cell, list the actual matching records underneath it,
 * plus the row id for a stable React key.
 */
export interface ManageRegistrant {
  id: string;
  firstName: string | null;
  lastName: string | null;
  email: string | null;
  phone: string | null;
  state: string | null;
  postcode: string | null;
  registeredAt: string | null;
  /**
   * Whether this registrant's phone matches a public.state_leaders row, by
   * normalized phone (lib/registryPipeline/leaderMatch.ts) — computed live
   * on every request, not stored. leaderName is that matched row's own
   * leader name (for a hover confirmation), non-null only when isLeader is
   * true — deliberately no leaderState, Peter only needs to know a
   * registrant is a leader at all, not where.
   */
  isLeader: boolean;
  leaderName: string | null;
  /**
   * Four fields synced/derived from ActiveCampaign (or backfilled from
   * Lorraine's CSV for pre-2026-09 registrants) — see
   * lib/registryPipeline/tagDerivedFields.ts and
   * scripts/add_webinar_and_code_fields_to_registrants.sql. Display-only:
   * deliberately NOT in EDITABLE_REGISTRANT_FIELDS (registrantValidation.ts) —
   * an admin never hand-corrects these here, same as email/phone/registeredAt.
   */
  webinarSessionAt: string | null;
  webinarAttended: string | null;
  codeOfConductAgreed: string | null;
  codeOfConductAgreedAt: string | null;
  /** 'Yes' if this person has unsubscribed (Lorraine's CSV, Jordan's tracking sheet, or a later ac-sync list-status change — see the registry schema notes in CLAUDE.md); null otherwise. Powers the "Exclude unsubscribed" toggle on the console — display-only, never hand-corrected here. */
  unsubscribed: string | null;
  /** 'Yes' if the CSV reload's source postcode field carried a literal "NFC" (No Further Contact) marker (scripts/prepare_registrants_for_csv_reload.sql); null otherwise. Set only at reload time — never written by ac-sync's live upsert, same as unsubscribed. Powers the "Exclude NFC" toggle. */
  nfc: string | null;
  /** The church the registrant said they attend (AC field [26], fallback [14]; the CSV's Church column, minus any UNSUBSCRIBED marker). Display-only here — synced/loaded, never hand-corrected. Free text. */
  churchName: string | null;
}

export interface ManageSummaryResponse {
  /** null only if registry.sync_log has no rows at all yet. */
  lastSync: SyncLogSummary | null;
  registrants: ManageRegistrant[];
}

/** PATCH /api/registry/manage-record body — one hand-edit to one field of one registrant. `value: null` clears the field. */
export interface ManageRecordEditRequest {
  id: string;
  field: EditableRegistrantField;
  value: string | null;
}

/** Echoes back the field/value as actually stored (post-normalization — e.g. a blank string comes back as null) so the page can update its in-memory copy without re-fetching. */
