import { describe, it, expect, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { makeQueryBuilder, type MockQueryBuilder } from './supabaseMock';

vi.mock('@/lib/supabaseClient', () => ({ supabase: { auth: {}, from: vi.fn() } }));

import { verifyAdminCaller } from '../adminCallerService';

const jwt = (aal: string) => `h.${Buffer.from(JSON.stringify({ aal })).toString('base64url')}.s`;

function setup(opts: { user?: { id: string } | null; profile?: { name: string; state: string } | null; leaders?: { leader: string; admin: string | null }[] } = {}) {
  const builders: Record<string, MockQueryBuilder> = {
    user_profiles: makeQueryBuilder({ data: opts.profile === undefined ? { name: 'Peter_AD', state: 'vic' } : opts.profile, error: null }),
    state_leaders: makeQueryBuilder({ data: opts.leaders ?? [{ leader: 'Peter_AD', admin: 'AD' }, { leader: 'Peter', admin: null }], error: null }),
  };
  const client = {
    auth: { getUser: vi.fn().mockResolvedValue({ data: { user: opts.user === undefined ? { id: 'u1' } : opts.user }, error: null }) },
    from: vi.fn((t: string) => builders[t]),
  } as unknown as SupabaseClient;
  return client;
}

describe('verifyAdminCaller', () => {
  it('accepts a full admin at aal2', async () => {
    expect(await verifyAdminCaller(setup(), jwt('aal2'))).toEqual({ ok: true, userId: 'u1', label: 'Peter_AD (VIC)' });
  });

  it('rejects an invalid token', async () => {
    expect(await verifyAdminCaller(setup({ user: null }), jwt('aal2'))).toMatchObject({ ok: false, status: 401 });
  });

  it('rejects an admin whose session is not at aal2', async () => {
    expect(await verifyAdminCaller(setup(), jwt('aal1'))).toMatchObject({ ok: false, status: 403 });
  });

  it('rejects a state reporter (SR is not a full admin)', async () => {
    const client = setup({ profile: { name: 'Peter_SR', state: 'VIC' }, leaders: [{ leader: 'Peter_SR', admin: 'SR' }] });
    expect(await verifyAdminCaller(client, jwt('aal2'))).toMatchObject({ ok: false, status: 403 });
  });

  it('rejects a plain leader and a session with no profile', async () => {
    expect(await verifyAdminCaller(setup({ profile: { name: 'Peter', state: 'VIC' } }), jwt('aal2'))).toMatchObject({ ok: false, status: 403 });
    expect(await verifyAdminCaller(setup({ profile: null }), jwt('aal2'))).toMatchObject({ ok: false, status: 403 });
  });

  it('matches the name exactly, not as a LIKE pattern (an underscore must not act as a wildcard)', async () => {
    // "PeterXAD" would match "Peter_AD" under ILIKE; it must not here.
    const client = setup({ profile: { name: 'PeterXAD', state: 'VIC' } });
    expect(await verifyAdminCaller(client, jwt('aal2'))).toMatchObject({ ok: false, status: 403 });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

vi.mock('@/lib/supabaseClient', () => ({
  supabase: { from: vi.fn(), auth: { getUser: vi.fn() } },
}));

import { supabase } from '@/lib/supabaseClient';
import { makeQueryBuilder } from './supabaseMock';
import { getAuthenticatedUser } from '../authService';

const mockFrom = vi.mocked(supabase.from) as unknown as ReturnType<typeof vi.fn>;
const mockGetUser = vi.mocked(supabase.auth.getUser);

beforeEach(() => {
  vi.clearAllMocks();
});

describe('getAuthenticatedUser', () => {
  it('returns null when there is no signed-in user', async () => {
    mockGetUser.mockResolvedValue({ data: { user: null }, error: null } as never);
    expect(await getAuthenticatedUser()).toBeNull();
    expect(mockFrom).not.toHaveBeenCalled();
  });

  it('throws when the auth check itself errors', async () => {
    const error = { message: 'network error' };
    mockGetUser.mockResolvedValue({ data: { user: null }, error } as never);
    await expect(getAuthenticatedUser()).rejects.toEqual(error);
  });

  it('returns a null-role shape when the profile has no name/state yet', async () => {
    mockGetUser.mockResolvedValue({ data: { user: { id: 'u1', email: 'a@b.com' } }, error: null } as never);
    mockFrom.mockReturnValue(makeQueryBuilder({ data: { name: null, state: null }, error: null }));

    const result = await getAuthenticatedUser();

    expect(result).toEqual({
      user: { id: 'u1', email: 'a@b.com' },
      profile: { name: null, state: null },
      adminStatus: null,
      isAdmin: false,
      userState: null,
      userLeader: null,
      userMobile: null,
    });
  });

  it('tolerates a missing profile row (PGRST116) rather than throwing', async () => {
    mockGetUser.mockResolvedValue({ data: { user: { id: 'u1' } }, error: null } as never);
    mockFrom.mockReturnValue(makeQueryBuilder({ data: null, error: { code: 'PGRST116' } }));

    const result = await getAuthenticatedUser();
    expect(result?.profile).toBeNull();
    expect(result?.adminStatus).toBeNull();
  });

  it('throws on a real profile-query error', async () => {
    const error = { code: '500', message: 'boom' };
    mockGetUser.mockResolvedValue({ data: { user: { id: 'u1' } }, error: null } as never);
    mockFrom.mockReturnValue(makeQueryBuilder({ data: null, error }));
    await expect(getAuthenticatedUser()).rejects.toEqual(error);
  });

  it('resolves full admin status from the matching state_leaders row', async () => {
    mockGetUser.mockResolvedValue({ data: { user: { id: 'u1', email: 'a@b.com' } }, error: null } as never);
    mockFrom
      .mockReturnValueOnce(makeQueryBuilder({ data: { name: '  Alice  ', state: 'vic' }, error: null }))
      .mockReturnValueOnce(
        makeQueryBuilder({ data: [{ admin: 'AD', leader: 'Alice', state: 'VIC', mobile: '0412345678' }], error: null }),
      );

    const result = await getAuthenticatedUser();

    expect(result).toEqual({
      user: { id: 'u1', email: 'a@b.com' },
      profile: { name: '  Alice  ', state: 'vic' },
      adminStatus: 'AD',
      isAdmin: true,
      userState: 'VIC',
      userLeader: 'Alice',
      userMobile: '0412345678',
    });
  });

  it('is not admin for a state reporter (isAdmin only true for AD)', async () => {
    mockGetUser.mockResolvedValue({ data: { user: { id: 'u1' } }, error: null } as never);
    mockFrom
      .mockReturnValueOnce(makeQueryBuilder({ data: { name: 'Bob', state: 'NSW' }, error: null }))
      .mockReturnValueOnce(
        makeQueryBuilder({ data: [{ admin: 'SR', leader: 'Bob', state: 'NSW', mobile: null }], error: null }),
      );

    const result = await getAuthenticatedUser();
    expect(result?.adminStatus).toBe('SR');
    expect(result?.isAdmin).toBe(false);
  });

  it('falls back to the normalized profile state when no state_leaders row matches', async () => {
    mockGetUser.mockResolvedValue({ data: { user: { id: 'u1' } }, error: null } as never);
    mockFrom
      .mockReturnValueOnce(makeQueryBuilder({ data: { name: 'Nobody', state: 'qld' }, error: null }))
      .mockReturnValueOnce(makeQueryBuilder({ data: [], error: null }));

    const result = await getAuthenticatedUser();
    expect(result?.adminStatus).toBeNull();
    expect(result?.userState).toBe('QLD');
    expect(result?.userLeader).toBeNull();
  });
});

