    expect(await getPlacesForState('')).toEqual([]);
    expect(mockFrom).not.toHaveBeenCalled();
  });

  it('normalizes state, dedupes, and sorts place options', async () => {
    const builder = makeQueryBuilder({
      data: [
        { place: 'Geelong' },
        { place: 'Melbourne' },
        { place: 'Melbourne' },
