import type { SupabaseClient } from '@supabase/supabase-js';
import { normalizeName } from '@/lib/auth';
import { getAalFromJwt } from '@/lib/services/sessionAccessService';

export type AdminCallerResult =
  | { ok: true; userId: string; label: string }
  | { ok: false; status: number; error: string };

/**
 * Verifies that a Bearer token belongs to a full admin (state_leaders 'AD')
 * who signed in with two-factor authentication (aal2). For high-value admin
 * actions (e.g. resetting another leader's 2FA). Identity is whatever
 * supabaseAdmin.auth.getUser(token) says; the admin row is found by the
 * session's user_profiles name+state, which — since 2026-10-11 — only the
 * server writes (sessionAccessService.ts), and for an AD only after MFA.
 * The aal2 check here is belt-and-braces on top of that.
 *
 * Matches the leader name exactly after normalizing (not ILIKE — `_` in
 * names like "Lorraine_AD" is a LIKE wildcard). The four older inline
 * admin-check routes (app/api/admin/*) predate this and still duplicate the
 * check; migrating them is a follow-up.
 */
export async function verifyAdminCaller(client: SupabaseClient, token: string): Promise<AdminCallerResult> {
  const { data: { user }, error: userError } = await client.auth.getUser(token);
  if (userError || !user) return { ok: false, status: 401, error: 'Unauthorized' };

  if (getAalFromJwt(token) !== 'aal2') {
    return { ok: false, status: 403, error: 'Two-factor sign-in is required for this action' };
  }

  const { data: profile } = await client
    .from('user_profiles')
    .select('name, state')
    .eq('user_id', user.id)
    .maybeSingle();
  if (!profile?.name || !profile?.state) return { ok: false, status: 403, error: 'Forbidden' };

  const { data: rows } = await client
    .from('state_leaders')
    .select('leader, admin')
    .eq('state', String(profile.state).toUpperCase().trim());
  const wanted = normalizeName(profile.name);
  const row = (rows ?? []).find((r: { leader: string | null }) => normalizeName(r.leader ?? '') === wanted);
  if (!row || row.admin !== 'AD') return { ok: false, status: 403, error: 'Forbidden' };

  return { ok: true, userId: user.id, label: `${row.leader} (${String(profile.state).toUpperCase().trim()})` };
}

lib/services/authService.ts:
import { supabase } from '@/lib/supabaseClient';
import { normalizeName } from '@/lib/auth';
import type { UserProfile } from '@/lib/types';

export interface AuthenticatedUser {
  user: { id: string; email?: string };
  profile: UserProfile | null;
  adminStatus: string | null;
  isAdmin: boolean;
  userState: string | null;
  userLeader: string | null;
  userMobile: string | null;
}

/**
 * Single-round-trip auth resolution: one auth check + one user_profiles query +
 * one state_leaders query, replacing the prior 4×getCurrentUser + 2×user_profiles +
 * 2×state_leaders pattern that ran on every page load.
 */
export async function getAuthenticatedUser(): Promise<AuthenticatedUser | null> {
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError) throw authError;
  if (!user) return null;

  const { data: profileData, error: profileError } = await supabase
    .from('user_profiles')
    .select('*')
    .eq('user_id', user.id)
    .single();

  if (profileError && profileError.code !== 'PGRST116') throw profileError;

  const profile: UserProfile | null = profileData ?? null;

  if (!profile?.name || !profile?.state) {
    return {
      user: { id: user.id, email: user.email },
      profile,
      adminStatus: null,
      isAdmin: false,
      userState: profile?.state ? profile.state.toUpperCase().trim() : null,
      userLeader: null,
      userMobile: null,
    };
  }

  const normalizedState = profile.state.toUpperCase().trim();
  const normalizedName = normalizeName(profile.name);

  const { data: leaderRows } = await supabase
    .from('state_leaders')
    .select('admin, leader, state, mobile')
    .eq('state', normalizedState)
    .ilike('leader', normalizedName);

  const match = leaderRows && leaderRows.length > 0 ? leaderRows[0] : null;
  const adminStatus = match?.admin ?? null;

  return {
    user: { id: user.id, email: user.email },
    profile,
    adminStatus,
    isAdmin: adminStatus === 'AD',
    userState: match ? (match.state as string).toUpperCase().trim() : normalizedState,
    userLeader: match?.leader ?? null,
    userMobile: match?.mobile ?? null,
  };
}

lib/services/backupService.ts:
/**
 * Backup & Restore (app/admin/backup/page.tsx) — export/import a JSON snapshot
 * of every admin-curated table in the app. Deliberately excludes tables that
 * are either pure operational history (campaign_changes_log, results_changes_log,
 * weekly_refresh_log, app_events — high-volume, already rolling-pruned, and
 * reconstructable from nothing but their own accumulation) or tied to Supabase
 * Auth identities (user_profiles, user_roles — keyed by auth.users.id, which
 * this JSON format has no way to restore, and which self-heal from
 * state_leaders + normal login rather than being admin-authored content).
 */

import type { SupabaseClient } from '@supabase/supabase-js';

export type BackupTableKey =
  | 'state_leaders'
  | 'state_places'
  | 'campaign_categories'
  | 'campaigns'
  | 'results'
  | 'campaign_reports'
  | 'campaign_report_location_aliases'
  | 'campaign_interest'
  | 'training_interest'
  | 'campaign_rules'
  | 'campaign_messages'
  | 'leader_shares'
  | 'state_refresh_settings'
  | 'app_settings';

interface BackupTableConfig {
  key: BackupTableKey;
  table: string;
  label: string;
  /** Column that uniquely identifies a row — used to fetch/delete-by-key in "replace" restore mode. */
  keyField: string;
  orderBy: [column: string, ascending: boolean][];
}

/**
 * One entry per backed-up table, in FK-safe order: a table only ever appears
 * *after* every table it references. `restoreBackup` inserts top-to-bottom and
 * (in "replace" mode) deletes bottom-to-top, so e.g. `results` — which has a
 * foreign key to `campaigns.id` — is always inserted after campaigns exist and
 * cleared before campaigns are deleted.
 */
export const BACKUP_TABLE_CONFIG: BackupTableConfig[] = [
  { key: 'state_leaders',          table: 'state_leaders',          label: 'State Leaders',          keyField: 'id',          orderBy: [['state', true], ['leader', true]] },
  { key: 'state_places',           table: 'state_places',           label: 'State Places',           keyField: 'id',          orderBy: [['state', true], ['place', true]] },
  { key: 'campaign_categories',    table: 'campaign_categories',    label: 'Campaign Categories',    keyField: 'id',          orderBy: [['code', true]] },
  { key: 'campaigns',              table: 'campaigns',              label: 'Campaigns',              keyField: 'id',          orderBy: [['date', true]] },
  { key: 'results',                table: 'results',                label: 'Results',                keyField: 'id',          orderBy: [['created_at', true]] },
  { key: 'campaign_reports',       table: 'campaign_reports',       label: 'Campaign Reports',       keyField: 'id',          orderBy: [['submitted_at', true]] },
  { key: 'campaign_report_location_aliases', table: 'campaign_report_location_aliases', label: 'Campaign Report Location Aliases', keyField: 'id', orderBy: [['location_key', true]] },
  { key: 'campaign_interest',      table: 'campaign_interest',      label: 'Campaign Interest',      keyField: 'id',          orderBy: [['created_at', true]] },
  { key: 'training_interest',      table: 'training_interest',      label: 'Training Interest',      keyField: 'id',          orderBy: [['created_at', true]] },
  { key: 'campaign_rules',         table: 'campaign_rules',         label: 'Campaign Rules',         keyField: 'id',          orderBy: [['state', true], ['name', true]] },
  { key: 'campaign_messages',      table: 'campaign_messages',      label: 'Campaign Messages',      keyField: 'date',        orderBy: [['date', true]] },
  { key: 'leader_shares',          table: 'leader_shares',          label: 'Leader Shares',          keyField: 'id',          orderBy: [['owner_state', true], ['owner_leader', true]] },
  { key: 'state_refresh_settings', table: 'state_refresh_settings', label: 'State Refresh Settings', keyField: 'state',       orderBy: [['state', true]] },
  { key: 'app_settings',           table: 'app_settings',           label: 'App Settings',           keyField: 'setting_key', orderBy: [['setting_key', true]] },
];

export type BackupTableData = Record<string, unknown>[];

export type BackupData = {
  exported_at: string;
  version: string;
} & Partial<Record<BackupTableKey, BackupTableData>>;

/** Current export format version. Bump when the set of backed-up tables changes. */
export const BACKUP_FORMAT_VERSION = '9';

export function isValidBackupFile(parsed: unknown): parsed is BackupData {
  return (
    !!parsed &&
    typeof parsed === 'object' &&
    typeof (parsed as BackupData).exported_at === 'string' &&
    typeof (parsed as BackupData).version === 'string'
  );
}

// ---------------------------------------------------------------------------
// Export
// ---------------------------------------------------------------------------

export async function exportBackup(
  client: SupabaseClient,
  selectedKeys: BackupTableKey[],
  onProgress?: (message: string) => void,
): Promise<BackupData> {
  const backup: BackupData = { exported_at: new Date().toISOString(), version: BACKUP_FORMAT_VERSION };

  for (const cfg of BACKUP_TABLE_CONFIG) {
    if (!selectedKeys.includes(cfg.key)) continue;

    onProgress?.(`Exporting ${cfg.label}…`);
    let query = client.from(cfg.table).select('*');
    for (const [column, ascending] of cfg.orderBy) {
      query = query.order(column, { ascending });
    }
    const { data, error } = await query;
    if (error) throw error;

    const rows = (data ?? []) as BackupTableData;
    backup[cfg.key] = rows;
    onProgress?.(`  ✓ ${rows.length} ${cfg.label.toLowerCase()}`);
  }

  return backup;
}

// ---------------------------------------------------------------------------
// Restore
// ---------------------------------------------------------------------------

const BATCH_SIZE = 500;

async function insertRecords(client: SupabaseClient, table: string, records: BackupTableData): Promise<void> {
  for (let i = 0; i < records.length; i += BATCH_SIZE) {
    const { error } = await client.from(table).insert(records.slice(i, i + BATCH_SIZE));
    if (error) throw error;
  }
}

async function upsertRecords(client: SupabaseClient, table: string, records: BackupTableData): Promise<void> {
  for (let i = 0; i < records.length; i += BATCH_SIZE) {
    const { error } = await client.from(table).upsert(records.slice(i, i + BATCH_SIZE));
    if (error) throw error;
  }
}

/** Deletes every current row in `table`, in batches, keyed on `keyField`. */
async function deleteAllRecords(client: SupabaseClient, table: string, keyField: string): Promise<void> {
  const { data: current, error: fetchError } = await client.from(table).select(keyField);
  if (fetchError) throw fetchError;

  const currentKeys = ((current ?? []) as unknown as Record<string, unknown>[]).map((row) => row[keyField]);
  for (let i = 0; i < currentKeys.length; i += BATCH_SIZE) {
    const { error } = await client.from(table).delete().in(keyField, currentKeys.slice(i, i + BATCH_SIZE));
    if (error) throw error;
  }
}

export type RestoreMode = 'merge' | 'replace';

/**
 * Restores the selected tables from `backup`.
 *
 * "merge" upserts records (adds/updates; nothing is deleted).
 * "replace" deletes every current row in each selected table and reinserts
 * exactly what's in the backup. To stay FK-safe regardless of which tables
 * are selected, "replace" runs as two passes over the *selected* tables —
 * a delete pass in reverse config order (children before parents), then an
 * insert pass in forward config order (parents before children) — rather
 * than delete-then-insert one table at a time.
 */
export async function restoreBackup(
  client: SupabaseClient,
  backup: BackupData,
  selectedKeys: BackupTableKey[],
  mode: RestoreMode,
  onProgress?: (message: string) => void,
): Promise<void> {
  const selected = BACKUP_TABLE_CONFIG.filter(
    (cfg) => selectedKeys.includes(cfg.key) && backup[cfg.key] !== undefined,
  );

  if (mode === 'replace') {
    for (const cfg of [...selected].reverse()) {
      onProgress?.(`Clearing existing ${cfg.label.toLowerCase()}…`);
      await deleteAllRecords(client, cfg.table, cfg.keyField);
    }
  }

  for (const cfg of selected) {
    const records = backup[cfg.key] as BackupTableData;
    onProgress?.(`Restoring ${cfg.label} (${mode})…`);
    if (mode === 'replace') {
      await insertRecords(client, cfg.table, records);
    } else {
      await upsertRecords(client, cfg.table, records);
    }
    onProgress?.(`  ✓ ${records.length} ${cfg.label.toLowerCase()} restored`);
  }
}

lib/services/campaignInterestService.ts:
/**
 * campaign_interest — members registering interest in joining a campaign via
 * the public Register Interest screen (app/public/register-interest). One
 * row per (campaign, person) pair, with mobile and/or email (at least one
 * required — DB CHECK constraint, see scripts/create_campaign_interest_table.sql
 * and scripts/add_email_to_campaign_interest.sql).
 *
 * Note: this module's functions use the browser client, which is RLS-gated
 * to an admin or the campaign's owning/shared leader for this table (see
 * supabase/rls-policies.sql) — so it's used by both /admin/registered-interest
 * (getCampaignInterestList, admin-wide) and the leader-facing /campaign-interest
 * (getCampaignInterestForLeader). The public submission flow can't use it
 * (anonymous visitors have no RLS access) — it inserts via the service role
 * directly in app/api/public/register-interest/route.ts instead.
 */
import { supabase } from '@/lib/supabaseClient';
import type { Campaign } from '@/lib/types';
import { getCampaignsForUser, type CampaignsForUserParams } from './campaignService';
import { fetchInterestCounts } from './interestCountsClient';

export type CampaignInterestType = 'in' | 'more';

export interface CampaignInterest {
  id: string;
  campaign_id: string;
  first_name: string;
  /** At least one of mobile/email is present — enforced by a DB CHECK constraint, see scripts/add_email_to_campaign_interest.sql. */
  mobile: string | null;
  email: string | null;
  interest_type: CampaignInterestType;
  contacted: boolean;
  contacted_at: string | null;
  created_at: string;
}

/** The subset of campaign fields needed to identify/display which campaign an interest row is for. */
export type CampaignInterestCampaignInfo = Pick<Campaign, 'id' | 'date' | 'state' | 'place' | 'site' | 'time' | 'leader'>;

export interface CampaignInterestWithCampaign extends CampaignInterest {
  /** Null if the referenced campaign has since been deleted independently of this row (shouldn't normally happen — FK is ON DELETE CASCADE). */
  campaign: CampaignInterestCampaignInfo | null;
}

/**
 * All campaign interest registrations, newest first, each paired with its
 * campaign's key details. Fetched as two queries (rather than a PostgREST
 * embed) to keep the relationship explicit and easy to mock in tests.
 */
export async function getCampaignInterestList(): Promise<CampaignInterestWithCampaign[]> {
  const { data, error } = await supabase
    .from('campaign_interest')
    .select('*')
    .order('created_at', { ascending: false });
  if (error) throw error;
  const entries = (data || []) as CampaignInterest[];
  if (entries.length === 0) return [];

  const campaignIds = [...new Set(entries.map(e => e.campaign_id))];
  const { data: campaignRows, error: campaignError } = await supabase
    .from('campaigns')
    .select('id, date, state, place, site, time, leader')
    .in('id', campaignIds);
  if (campaignError) throw campaignError;

  const campaignsById = new Map(
    (campaignRows || []).map(c => [c.id as string, c as CampaignInterestCampaignInfo]),
  );

  return entries.map(e => ({ ...e, campaign: campaignsById.get(e.campaign_id) ?? null }));
}

/**
 * Interest registrations for campaigns the given user leads (own, shared, or
 * — for admins — every campaign) — reuses getCampaignsForUser's role-aware
 * fetch rather than re-implementing that filtering here, same pattern as
 * trainingInterestService's getTrainingCampaigns. Unlike getCampaignInterestList
 * (admin-wide, needs a second campaigns query), the campaign details are
 * already in hand from getCampaignsForUser's own result.
 */
export async function getCampaignInterestForLeader(params: CampaignsForUserParams): Promise<CampaignInterestWithCampaign[]> {
  const { campaigns } = await getCampaignsForUser(params);
  if (campaigns.length === 0) return [];

  const campaignIds = campaigns.map(c => c.id);
  const { data, error } = await supabase
    .from('campaign_interest')
    .select('*')
    .in('campaign_id', campaignIds)
    .order('created_at', { ascending: false });
  if (error) throw error;

  const campaignsById = new Map(campaigns.map(c => [c.id, c as CampaignInterestCampaignInfo]));

  return ((data || []) as CampaignInterest[]).map(e => ({ ...e, campaign: campaignsById.get(e.campaign_id) ?? null }));
}

/**
 * Count of campaign_interest rows per campaign id, for the given campaign ids.
 * Goes through the server (numbers only, for campaigns the caller can see)
 * rather than reading the table, because members' details need a 2FA-level
 * session but a leader must still be able to see *that* people registered —
 * see lib/services/interestCountsService.ts.
 */
export async function getCampaignInterestCounts(campaignIds: string[]): Promise<Map<string, number>> {
  if (campaignIds.length === 0) return new Map();
  const { campaignInterest } = await fetchInterestCounts(campaignIds);
  return new Map(Object.entries(campaignInterest));
}

/**
 * Whether the given user leads any campaign that has registrations — without
 * reading the registrations themselves, so it works for a session that hasn't
 * passed 2FA. Drives the "Manage my Campaign Interest" button.
 */
export async function hasCampaignInterestForLeader(params: CampaignsForUserParams): Promise<boolean> {
  const { campaigns } = await getCampaignsForUser(params);
  if (campaigns.length === 0) return false;
  const counts = await getCampaignInterestCounts(campaigns.map((c) => c.id));
  return [...counts.values()].some((n) => n > 0);
}

/**
 * Mark a registration as contacted (or un-contacted). `contacted_at` is set
 * to now when marking contacted, and cleared back to null when un-marking.
 * Returns the updated row's contacted_at so callers can update local state
 * from the authoritative persisted value rather than re-deriving their own
 * timestamp with a second `new Date().toISOString()` call.
 */
export async function setCampaignInterestContacted(id: string, contacted: boolean): Promise<{ contacted_at: string | null }> {
  const { data, error } = await supabase
    .from('campaign_interest')
    .update({ contacted, contacted_at: contacted ? new Date().toISOString() : null })
    .eq('id', id)
    .select('contacted_at')
    .single();
  if (error) throw error;
  return data as { contacted_at: string | null };
}

/**
 * Texts a campaign's owning leader (state_leaders.mobile, via ClickSend)
 * whenever someone registers interest via the public Register Interest
 * screen or the personalized Campaigns Near Me map — both write into
 * campaign_interest and call notifyLeadersOfCampaignInterest() right after
 * their insert succeeds. Only the owning leader (campaign.leader) is
 * texted, never a campaign's shared leaders.
 *
 * A single submission can tick several campaigns; if more than one
 * resolves to the same (state, leader), they're combined into one text
 * rather than sending one per campaign.
 *
 * Split into pure logic (fully unit tested, no mocks) and one orchestration
 * function taking an injected SupabaseClient — same shape as
 * backupService.ts's exportBackup(client, ...), so it can be exercised with
 * lib/services/__tests__/supabaseMock.ts and never accidentally imports the
 * browser client (this only ever runs from a public API route under the
 * service role — a leader's mobile isn't readable by an anonymous visitor
 * through RLS).
 *
 * Best-effort by design: notifyLeadersOfCampaignInterest() never throws.
 * Every attempt — sent, failed, or skipped for no mobile on file — is
 * logged to campaign_interest_sms_log so a misconfiguration doesn't go
 * unnoticed the way registry.whatsapp_invite_log's own gap did before it
 * had a dedicated log table.
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { isValidMobile } from '@/lib/validation';
import { normalizeMobile } from '@/lib/auth';
import { combinePlaceAndSite } from '@/lib/placeSite';
import { getSiteUrl } from '@/lib/siteUrl';
import { sendSms } from '@/lib/clickSendClient';
import { getErrorMessage } from '@/lib/errorUtils';

export type CampaignInterestType = 'in' | 'more';

export interface CampaignLeaderInfo {
  id: string;
  state: string;
  leader: string;
  date: string; // 'YYYY-MM-DD'
  place: string;
  site: string;
  time: string;
}

export interface LeaderCampaignGroup {
  state: string;
  leader: string;
  campaigns: CampaignLeaderInfo[];
}

/** '04XXXXXXXX' -> '+614XXXXXXXX'; null if not a plausible AU mobile. */
export function toE164AuMobile(localMobile: string): string | null {
  if (!isValidMobile(localMobile)) return null;
  const normalized = normalizeMobile(localMobile);
  return `+61${normalized.slice(1)}`;
}

/** Groups campaigns by their owning (state, leader) pair, keyed as 'STATE::leader'. */
export function groupCampaignsByLeader(campaigns: CampaignLeaderInfo[]): Map<string, LeaderCampaignGroup> {
  const groups = new Map<string, LeaderCampaignGroup>();
  for (const campaign of campaigns) {
    const key = `${campaign.state}::${campaign.leader}`;
    const existing = groups.get(key);
    if (existing) {
      existing.campaigns.push(campaign);
    } else {
      groups.set(key, { state: campaign.state, leader: campaign.leader, campaigns: [campaign] });
    }
  }
  return groups;
}

const MONTH_ABBR = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** Compact date for SMS, parsed directly from 'YYYY-MM-DD' (no Date object, no timezone risk). */
function formatShortDate(dateStr: string): string {
  const [, month, day] = dateStr.split('-').map(Number);
  return `${day} ${MONTH_ABBR[(month ?? 1) - 1] ?? ''}`.trim();
}

const INTEREST_TYPE_LABEL: Record<CampaignInterestType, string> = {
  in: "Yes I'm In",
  more: 'Tell Me More',
};

/** Builds the SMS body for one leader's group of ticked campaigns. */
export function buildLeaderSmsMessage(
  registrantFirstName: string,
  interestType: CampaignInterestType,
  campaigns: CampaignLeaderInfo[]
): string {
  const typeLabel = INTEREST_TYPE_LABEL[interestType];
  const link = `${getSiteUrl()}/campaign-interest`;

  if (campaigns.length === 1) {
    const c = campaigns[0];
    const placeLabel = combinePlaceAndSite(c.place, c.site);
    return `<Important AFJ Notification> ${registrantFirstName} has registered interest ("${typeLabel}") in your campaign at ${placeLabel}, ${formatShortDate(c.date)} ${c.time}. View details here: ${link}`;
  }

  const list = campaigns
    .map((c) => `${combinePlaceAndSite(c.place, c.site)} (${formatShortDate(c.date)})`)
    .join(', ');
  return `<Important AFJ Notification> ${registrantFirstName} has registered interest ("${typeLabel}") in ${campaigns.length} of your campaigns: ${list}. View details here: ${link}`;
}

interface NotifyLeadersParams {
  campaignIds: string[];
  registrantFirstName: string;
  interestType: CampaignInterestType;
}

/**
 * Fetches the given campaigns, groups them by owning leader, and best-effort
 * texts each leader with a mobile on file — logging every outcome. Never
 * throws; a lookup/send/logging failure for one leader never affects
 * another, and never propagates to the caller.
 */
export async function notifyLeadersOfCampaignInterest(client: SupabaseClient, params: NotifyLeadersParams): Promise<void> {
  const { campaignIds, registrantFirstName, interestType } = params;
  if (campaignIds.length === 0) return;

  try {
    const { data, error } = await client
      .from('campaigns')
      .select('id, state, leader, date, place, site, time')
      .in('id', campaignIds);
    if (error) throw error;

    const campaigns = ((data ?? []) as CampaignLeaderInfo[]).filter((c) => c.state && c.leader);
    if (campaigns.length === 0) return;

    const groups = groupCampaignsByLeader(campaigns);

    await Promise.all(
      Array.from(groups.values()).map((group) =>
        notifyOneLeader(client, group, registrantFirstName, interestType)
      )
    );
  } catch (err) {
    console.error('[campaignInterestSmsService] notifyLeadersOfCampaignInterest error:', getErrorMessage(err));
  }
}

async function notifyOneLeader(
  client: SupabaseClient,
  group: LeaderCampaignGroup,
  registrantFirstName: string,
  interestType: CampaignInterestType
): Promise<void> {
  const campaignIds = group.campaigns.map((c) => c.id);
  let status: 'sent' | 'failed' | 'skipped_no_mobile';
  let mobile: string | null = null;
  let messageBody: string | null = null;
  let error: string | null = null;
  let clicksendMessageId: string | null = null;

  try {
    const { data: leaderRow, error: leaderError } = await client
      .from('state_leaders')
      .select('mobile')
      .eq('state', group.state)
      .eq('leader', group.leader)
      .maybeSingle();
    if (leaderError) throw leaderError;

    mobile = (leaderRow as { mobile: string | null } | null)?.mobile ?? null;
    const e164 = mobile ? toE164AuMobile(mobile) : null;

    if (!e164) {
      status = 'skipped_no_mobile';
    } else {
      messageBody = buildLeaderSmsMessage(registrantFirstName, interestType, group.campaigns);
      const result = await sendSms(e164, messageBody);
      clicksendMessageId = result.messageId;
      status = 'sent';
    }
  } catch (err) {
    status = 'failed';
    error = getErrorMessage(err);
  }

  try {
    // insert() resolves to { data, error } rather than rejecting on a
    // PostgREST-level failure (missing table, RLS denial, constraint
    // violation) — checked explicitly so a logging failure can't go
    // silent the way it would if only a thrown exception were caught here.
    const { error: logError } = await client.from('campaign_interest_sms_log').insert({
      state: group.state,
      leader: group.leader,
      mobile,
      campaign_ids: campaignIds,
      interest_type: interestType,
      message_body: messageBody,
      status,
      error,
      clicksend_message_id: clicksendMessageId,
    });
    if (logError) throw logError;
  } catch (logErr) {
    console.error('[campaignInterestSmsService] failed to write campaign_interest_sms_log:', getErrorMessage(logErr));
  }
}

lib/services/campaignMapService.ts:
/**
 * Builds map-ready data for the admin campaign map: campaigns within a date range
 * (optionally filtered by state), grouped by place, with coordinates resolved via
 * cached state_places columns or on-demand geocoding through the admin API route.
 */
import { supabase } from '@/lib/supabaseClient';
import { getCampaignsByDateRange } from '@/lib/services/campaignService';
import { getStatePlaces } from '@/lib/services/statePlacesService';
import { isCampaignPast } from '@/lib/campaignUtils';
import type { Campaign } from '@/lib/types';

export interface MapMarker {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
  // Omitted for the state-places map (getStatePlacesMapData), which has no campaigns
  // to attach — CampaignMap's popup falls back to a bare place/state label in that case.
  campaigns?: Campaign[];
}

export interface MapDataResult {
  markers: MapMarker[];
  /** Places that could not be geocoded — surfaced so the admin knows coverage is incomplete. */
  unresolvedPlaces: { state: string; place: string }[];
}

// campaigns.place and state_places.place are independently free-typed and can differ by
// incidental whitespace/case (e.g. "Preston" vs "Preston "), so cache keys are normalized
// to avoid silently missing an already-geocoded place. Exported so any other code
// matching campaigns against state_places by place (e.g. publicCampaignsNearMeService.ts)
// uses this exact same normalization rather than a second, possibly-inconsistent one.
export function placeKey(state: string, place: string): string {
  return `${state.trim().toUpperCase()}::${place.trim().replace(/\s+/g, ' ').toLowerCase()}`;
}

/**
 * Calls the admin geocode-place API for a single place. Also used by the admin
 * Manage State Places page to geocode a place immediately on create/edit, rather than
 * waiting for it to first appear on the campaign map.
 *
 * `force` skips the API's coordinate cache and re-geocodes even if coordinates already
 * exist — pass it when a place's `location` was just edited, since the old coordinates
 * were computed from the previous location text and are now stale.
 */
export async function fetchPlaceCoordinates(state: string, place: string, force = false): Promise<{ latitude: number; longitude: number } | null> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) return null;

  const response = await fetch('/api/admin/geocode-place', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${session.access_token}`,
    },
    body: JSON.stringify({ state, place, ...(force ? { force: true } : {}) }),
    // Guards against a slow geocode (e.g. an unreachable Nominatim) hanging the map indefinitely.
    signal: AbortSignal.timeout(10000),
  }).catch(() => null);
  if (!response || !response.ok) return null;

  const data = await response.json() as { latitude: number; longitude: number };
  return data;
}

export async function getMapData(options: {
  startDate: string;
  endDate: string;
  state?: string;
}): Promise<MapDataResult> {
  // Campaigns that have already started or finished are excluded — the map is
  // for finding upcoming campaigns, not a record of ones already underway/done.
  const campaigns = (await getCampaignsByDateRange(options))
    .filter(campaign => !isCampaignPast(campaign.date, campaign.time));

  const grouped = new Map<string, { state: string; place: string; campaigns: Campaign[] }>();
  for (const campaign of campaigns) {
    const key = placeKey(campaign.state, campaign.place);
    const group = grouped.get(key);
    if (group) {
      group.campaigns.push(campaign);
    } else {
      grouped.set(key, { state: campaign.state, place: campaign.place, campaigns: [campaign] });
    }
  }

  const knownPlaces = await getStatePlaces(options.state);
  const coordsByKey = new Map(
    knownPlaces
      .filter(p => p.latitude != null && p.longitude != null)
      .map(p => [placeKey(p.state, p.place), { latitude: p.latitude as number, longitude: p.longitude as number }]),
  );

  const markers: MapMarker[] = [];
  const unresolvedPlaces: { state: string; place: string }[] = [];

  let isFirstUncachedLookup = true;
  for (const [key, group] of grouped) {
    let coords = coordsByKey.get(key);
    if (!coords) {
      // Nominatim's usage policy caps requests at 1/sec — space out uncached lookups
      // so a burst of new places doesn't get throttled into spurious "not found" results.
      if (!isFirstUncachedLookup) await new Promise(resolve => setTimeout(resolve, 1100));
      isFirstUncachedLookup = false;
      coords = await fetchPlaceCoordinates(group.state, group.place) ?? undefined;
    }
    if (coords) {
      markers.push({ state: group.state, place: group.place, latitude: coords.latitude, longitude: coords.longitude, campaigns: group.campaigns });
    } else {
      unresolvedPlaces.push({ state: group.state, place: group.place });
    }
  }

  return { markers, unresolvedPlaces };
}

/**
 * Builds map-ready data for every row in state_places (optionally filtered by state),
 * for the admin "Show me where they are" map. Unlike getMapData, markers carry no
 * campaigns — just the bare place/state pair for the popup.
 *
 * Two different state_places rows can still resolve to the same physical spot (e.g. a
 * duplicate entered under a slightly different name), which would otherwise stack
 * identical pins on top of each other — so markers are deduped by rounded coordinates
 * (~1m precision) rather than by place name, keeping exactly one pin per location.
 */
export async function getStatePlacesMapData(options: { state?: string } = {}): Promise<MapDataResult> {
  const places = await getStatePlaces(options.state);

  const markers: MapMarker[] = [];
  const unresolvedPlaces: { state: string; place: string }[] = [];
  const seenCoordKeys = new Set<string>();

  let isFirstUncachedLookup = true;
  for (const place of places) {
    let latitude = place.latitude ?? null;
    let longitude = place.longitude ?? null;

    if (latitude == null || longitude == null) {
      // Nominatim's usage policy caps requests at 1/sec — space out uncached lookups
      // so a burst of new places doesn't get throttled into spurious "not found" results.
      if (!isFirstUncachedLookup) await new Promise(resolve => setTimeout(resolve, 1100));
      isFirstUncachedLookup = false;
      const coords = await fetchPlaceCoordinates(place.state, place.place);
      latitude = coords?.latitude ?? null;
      longitude = coords?.longitude ?? null;
    }

    if (latitude == null || longitude == null) {
      unresolvedPlaces.push({ state: place.state, place: place.place });
      continue;
    }

    const coordKey = `${latitude.toFixed(5)},${longitude.toFixed(5)}`;
    if (seenCoordKeys.has(coordKey)) continue;
    seenCoordKeys.add(coordKey);

    markers.push({ state: place.state, place: place.place, latitude, longitude });
  }

  return { markers, unresolvedPlaces };
}

