lib/services/campaignReportManageService:
/**
 * Campaign Report project — see docs/campaign-report/BRIEF.md.
 *
 * Backs the Campaign Reports management screen (/admin/campaign-reports):
 * loads every report in a compact shape, applies one hand edit to a report's
 * derived state / location / leader (audited to campaign_report_edits), and
 * pages that audit log. Server-side only — injected client, always
 * `supabaseAdmin` (campaign_reports has no authenticated write policy).
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { AUSTRALIAN_STATES } from '@/lib/constants';
import { ensureStateLocation, getStateLocations } from '@/lib/services/stateLocations';
import {
  REPORT_FIELD_COLUMNS,
  type EditableReportField,
  type ManageDataResponse,
  type ManageReport,
  type ReportEditLogResponse,
  type ReportEditResponse,
} from '@/lib/campaignReportManageTypes';

const PAGE = 1000;
export const EDIT_LOG_PAGE_SIZE = 50;

interface ReportRow {
  id: string;
  submitted_at: string;
  campaign_date: string | null;
  campaign_date_raw: string | null;
  location_raw: string | null;
  leader_raw: string | null;
  derived_state: string | null;
  derived_location: string | null;
  derived_leader: string | null;
  partial_presentations: number | null;
  full_presentations: number | null;
  sinners_prayer: number | null;
  information_requests: number | null;
  needs_review: boolean;
}

const REPORT_COLUMNS =
  'id, submitted_at, campaign_date, campaign_date_raw, location_raw, leader_raw, derived_state, derived_location, derived_leader, partial_presentations, full_presentations, sinners_prayer, information_requests, needs_review';

export function toManageReport(r: ReportRow): ManageReport {
  return {
    id: r.id,
    submittedAt: r.submitted_at,
    campaignDate: r.campaign_date,
    campaignDateRaw: r.campaign_date_raw,
    locationTyped: r.location_raw,
    leader: r.leader_raw,
    state: r.derived_state,
    location: r.derived_location,
    matchedLeader: r.derived_leader,
    partial: r.partial_presentations,
    full: r.full_presentations,
    sinnersPrayer: r.sinners_prayer,
    infoRequests: r.information_requests,
    needsReview: r.needs_review,
  };
}

export async function getManageData(client: SupabaseClient): Promise<ManageDataResponse> {
  const rows: ReportRow[] = [];
  for (let from = 0; ; from += PAGE) {
    const { data, error } = await client
      .from('campaign_reports').select(REPORT_COLUMNS).order('submitted_at', { ascending: false }).range(from, from + PAGE - 1);
    if (error) throw error;
    rows.push(...((data ?? []) as ReportRow[]));
    if ((data?.length ?? 0) < PAGE) break;
  }
  const locations = await getStateLocations(client);
  const { data: leaders, error: lErr } = await client.from('state_leaders').select('state, leader').order('state').order('leader');
  if (lErr) throw lErr;
  return { reports: rows.map(toManageReport), locations, leaders: leaders ?? [] };
}

export type ApplyEditResult =
  | { ok: true; report: ReportEditResponse }
  | { ok: false; status: number; error: string; code?: 'unknown_location' };

export interface ApplyEditInput {
  id: string;
  field: EditableReportField;
  value: string | null;
  /** Confirms a location not yet in State Places should be added to it. */
  addLocation?: boolean;
  actor: { userId: string; label: string };
}

/**
 * Applies one edit. Changing the state also clears a location or leader that
 * doesn't exist in the new state (each clear is audited too), so a report
 * can never carry e.g. a VIC location under NSW.
 */
export async function applyReportEdit(client: SupabaseClient, input: ApplyEditInput): Promise<ApplyEditResult> {
  const value = input.value?.trim() || null;

  const { data: existing, error: fetchError } = await client
    .from('campaign_reports').select('id, derived_state, derived_location, derived_leader').eq('id', input.id).maybeSingle();
  if (fetchError) throw fetchError;
  if (!existing) return { ok: false, status: 404, error: 'Report not found' };

  const next = { state: existing.derived_state as string | null, location: existing.derived_location as string | null, leader: existing.derived_leader as string | null };
  const before = { ...next };

  if (input.field === 'state') {
    if (value !== null && !AUSTRALIAN_STATES.includes(value as never)) return { ok: false, status: 400, error: `Invalid state: ${value}` };
    next.state = value;
  } else if (!next.state) {
    return { ok: false, status: 400, error: 'Choose a state first' };
  } else if (input.field === 'location') {
    next.location = value;
  } else {
    next.leader = value;
  }

  const leaderInState = async (state: string, name: string) => {
    const { data, error } = await client.from('state_leaders').select('leader').eq('state', state).eq('leader', name).limit(1);
    if (error) throw error;
    return (data?.length ?? 0) > 0;
  };

  if (input.field === 'location' && value && next.state) {
    const found = await ensureStateLocation(client, next.state, value, Boolean(input.addLocation));
    if (!found.ok) return { ok: false, status: 409, code: found.code, error: found.error };
    next.location = found.location; // the stored spelling
  }
  if (input.field === 'leader' && value && next.state && !(await leaderInState(next.state, value))) {
    return { ok: false, status: 400, error: `"${value}" is not a ${next.state} leader` };
  }

  if (input.field === 'state') {
    if (next.state && next.location && !(await ensureStateLocation(client, next.state, next.location, false)).ok) next.location = null;
    if (next.state && next.leader && !(await leaderInState(next.state, next.leader))) next.leader = null;
    if (!next.state) { next.location = null; next.leader = null; }
  }

  const updates = { derived_state: next.state, derived_location: next.location, derived_leader: next.leader };
  const { error: updateError } = await client.from('campaign_reports').update(updates).eq('id', input.id);
  if (updateError) throw updateError;

  const audit = (['state', 'location', 'leader'] as const)
    .filter((f) => before[f] !== next[f])
    .map((f) => ({
      report_id: input.id, field: REPORT_FIELD_COLUMNS[f], old_value: before[f], new_value: next[f],
      edited_by: input.actor.userId, edited_by_label: input.actor.label,
    }));
  if (audit.length) {
    // The edit already succeeded; a failed audit write must not undo it, but must not be silent either.
    const { error } = await client.from('campaign_report_edits').insert(audit);
    if (error) console.error('[campaignReportManageService] audit insert failed:', error);
  }

  return { ok: true, report: { id: input.id, state: next.state, location: next.location, matchedLeader: next.leader } };
}

export async function getEditLog(client: SupabaseClient, page: number): Promise<ReportEditLogResponse> {
  const safePage = Math.max(1, Math.floor(page) || 1);
  const from = (safePage - 1) * EDIT_LOG_PAGE_SIZE;
  const { data, error, count } = await client
    .from('campaign_report_edits')
    .select('id, report_id, field, old_value, new_value, edited_by_label, edited_at', { count: 'exact' })
    .order('edited_at', { ascending: false })
    .range(from, from + EDIT_LOG_PAGE_SIZE - 1);
  if (error) throw error;

  const ids = [...new Set((data ?? []).map((e) => e.report_id as string))];
  const context = new Map<string, { locationTyped: string | null; leader: string | null }>();
  if (ids.length) {
    const { data: reports, error: rErr } = await client.from('campaign_reports').select('id, location_raw, leader_raw').in('id', ids);
    if (rErr) throw rErr;
    for (const r of reports ?? []) context.set(r.id as string, { locationTyped: r.location_raw as string | null, leader: r.leader_raw as string | null });
  }

  return {
    entries: (data ?? []).map((e) => ({
      id: e.id as string,
      editedAt: e.edited_at as string,
      editedBy: e.edited_by_label as string | null,
      field: e.field as string,
      oldValue: e.old_value as string | null,
      newValue: e.new_value as string | null,
      locationTyped: context.get(e.report_id as string)?.locationTyped ?? null,
      leader: context.get(e.report_id as string)?.leader ?? null,
    })),
    page: safePage,
    pageSize: EDIT_LOG_PAGE_SIZE,
    total: count ?? 0,
  };
}

lib/services/campaignReportSyncService.t:
/**
 * Campaign Report project — see docs/campaign-report/BRIEF.md.
 *
 * Temporary bridge: keeps `campaign_reports` current from the live Google
 * Sheet until the app's own campaign-report numbers replace it. Takes an
 * injected client (always `supabaseAdmin` in practice — the table has no
 * authenticated write policy) so it can be unit tested with supabaseMock.ts.
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { normalizeCampaignReportRow, type CampaignReportInsert, type RawCampaignReportSheetRow } from '@/lib/campaignReportParser';
import {
  deriveCampaignReportFields, locationKey, type PlaceRef, type LeaderRef, type LocationAliasRef,
} from '@/lib/campaignReportMatcher';
import { fetchCampaignReportSheetRows } from '@/lib/campaignReportSheetReader';

/** Derive state/location/leader for the whole history (the original 2026-05-06 cutoff was lifted 2026-10-24). */
export const DERIVE_SINCE = '2000-01-01';

/** Marks rows written by the live sync so they're easy to find (and remove) when the sheet is retired. */
export const SHEET_SYNC_SOURCE = 'google_sheet_sync';

const BATCH_SIZE = 500;

export interface SheetSyncResult {
  sheetRows: number;
  skippedNoTimestamp: number;
  duplicateTimestampsInSheet: number;
  inserted: number;
  alreadyPresent: number;
  needsReview: number;
  derived: DeriveResult;
}

export interface DeriveResult {
  inScope: number;
  updated: number;
  /** Rows still without a state. */
  unresolved: number;
  /** Rows still without a mapped location, and how many distinct typed spellings that is. */
  noLocationRows: number;
  noLocationSpellings: number;
}

/** The one-line daily summary the cron job logs. */
export function summarizeUnresolvedLocations(d: DeriveResult): string {
  return d.noLocationRows === 0
    ? 'All campaign report locations are mapped.'
    : `${d.noLocationSpellings} typed location(s) (${d.noLocationRows} report row(s)) don't map to a location yet — review at /admin/campaign-report-locations.`;
}

/** Normalizes raw sheet rows, dropping rows with no usable timestamp and repeated timestamps (first wins, like the original load). */
export function prepareInserts(rows: RawCampaignReportSheetRow[]): {
  inserts: CampaignReportInsert[]; skippedNoTimestamp: number; duplicateTimestamps: number;
} {
  const seen = new Set<string>();
  const inserts: CampaignReportInsert[] = [];
  let skippedNoTimestamp = 0;
  let duplicateTimestamps = 0;
  for (const raw of rows) {
    const normalized = normalizeCampaignReportRow(raw);
    if (!normalized) { skippedNoTimestamp++; continue; }
    if (seen.has(normalized.submitted_at)) { duplicateTimestamps++; continue; }
    seen.add(normalized.submitted_at);
    inserts.push({ ...normalized, source: SHEET_SYNC_SOURCE });
  }
  return { inserts, skippedNoTimestamp, duplicateTimestamps };
}

const PAGE = 1000;
const UPDATE_CHUNK = 100; // ids per UPDATE ... IN (...) — keeps the request URL short

async function fetchAll<T>(build: (from: number, to: number) => PromiseLike<{ data: T[] | null; error: unknown }>): Promise<T[]> {
  const out: T[] = [];
  for (let from = 0; ; from += PAGE) {
    const { data, error } = await build(from, from + PAGE - 1);
    if (error) throw error;
    out.push(...(data ?? []));
    if ((data?.length ?? 0) < PAGE) return out;
  }
}

/** Confirmed location aliases keyed by location_key. A missing table (SQL not yet run) counts as none. */
export async function loadLocationAliases(client: SupabaseClient): Promise<Map<string, LocationAliasRef>> {
  const { data, error } = await client.from('campaign_report_location_aliases').select('location_key, state, location');
  if (error) {
    const code = (error as { code?: string }).code;
    if (code === '42P01' || code === '42703' || code === 'PGRST205') return new Map();
    throw error;
  }
  return new Map((data ?? []).map((a) => [a.location_key as string, a as LocationAliasRef]));
}

interface ReportForDerive {
  id: string;
  location_raw: string | null;
  leader_raw: string | null;
  derived_state: string | null;
  derived_location: string | null;
  derived_leader: string | null;
}

/**
 * Fills derived_state/derived_location/derived_leader for every row from
 * `since` on. By default only EMPTY fields are filled, so a value an admin
 * set by hand (Campaign Reports screen) or a location alias already applied is never
 * overwritten by a later run; `overwrite: true` recomputes everything (used
 * once after the matcher itself changes). Rows needing the same values are
 * written together. Also reports how many rows still have no location.
 */
export async function deriveCampaignReportFieldsSince(
  client: SupabaseClient,
  since: string = DERIVE_SINCE,
  apply = true,
  overwrite = false,
): Promise<DeriveResult> {
  const reports = await fetchAll<ReportForDerive>((from, to) =>
    client.from('campaign_reports')
      .select('id, location_raw, leader_raw, derived_state, derived_location, derived_leader')
      .gte('submitted_at', since).order('submitted_at').range(from, to));
  const { data: places, error: pErr } = await client.from('state_places').select('state, place, location');
  if (pErr) throw pErr;
  const { data: leaders, error: lErr } = await client.from('state_leaders').select('state, leader');
  if (lErr) throw lErr;
  const aliases = await loadLocationAliases(client);

  const groups = new Map<string, { values: Record<string, string | null>; ids: string[] }>();
  let updated = 0;
  let unresolved = 0;
  let noLocationRows = 0;
  const noLocationKeys = new Set<string>();

  for (const row of reports) {
    const d = deriveCampaignReportFields(row, (places ?? []) as PlaceRef[], (leaders ?? []) as LeaderRef[], aliases);
    const next = {
      derived_state: overwrite ? d.state : row.derived_state ?? d.state,
      derived_location: overwrite ? d.location : row.derived_location ?? d.location,
      derived_leader: overwrite ? d.leader : row.derived_leader ?? d.leader,
    };
    if (!next.derived_state) unresolved++;
    if (!next.derived_location) {
      noLocationRows++;
      noLocationKeys.add(locationKey(row.location_raw));
    }
    if (next.derived_state === row.derived_state && next.derived_location === row.derived_location && next.derived_leader === row.derived_leader) continue;
    updated++;
    const groupKey = JSON.stringify(next);
    const g: { values: Record<string, string | null>; ids: string[] } = groups.get(groupKey) ?? { values: next, ids: [] };
    g.ids.push(row.id);
    groups.set(groupKey, g);
  }

  if (apply) {
    for (const { values, ids } of groups.values()) {
      for (let i = 0; i < ids.length; i += UPDATE_CHUNK) {
        const { error } = await client.from('campaign_reports').update(values).in('id', ids.slice(i, i + UPDATE_CHUNK));
        if (error) throw error;
      }
    }
  }
  return { inScope: reports.length, updated, unresolved, noLocationRows, noLocationSpellings: noLocationKeys.size };
}

/** Every `submitted_at` already stored, as epoch ms (dry runs use this to count what would be new). */
async function loadExistingTimestamps(client: SupabaseClient): Promise<Set<number>> {
  const PAGE = 1000;
  const keys = new Set<number>();
  for (let from = 0; ; from += PAGE) {
    const { data, error } = await client
      .from('campaign_reports').select('submitted_at').order('submitted_at').range(from, from + PAGE - 1);
    if (error) throw error;
    for (const r of data ?? []) keys.add(new Date(r.submitted_at as string).getTime());
    if ((data?.length ?? 0) < PAGE) return keys;
  }
}

/**
 * Pulls the sheet and inserts rows not yet in `campaign_reports` (matched on
 * the unique `submitted_at`; existing rows are never modified, so any manual
 * cleanup of them survives), then derives state/location/leader.
 * With `apply: false` nothing is written.
 */
export async function syncCampaignReportsFromSheet(
  client: SupabaseClient,
  sheetId: string,
  options: { apply?: boolean; fetchImpl?: typeof fetch } = {},
): Promise<SheetSyncResult> {
  const apply = options.apply ?? true;
  const rawRows = await fetchCampaignReportSheetRows(sheetId, options.fetchImpl);
  const { inserts, skippedNoTimestamp, duplicateTimestamps } = prepareInserts(rawRows);

  let inserted = 0;
  if (!apply) {
    const existing = await loadExistingTimestamps(client);
    inserted = inserts.filter((r) => !existing.has(new Date(r.submitted_at).getTime())).length;
  } else {
    for (let i = 0; i < inserts.length; i += BATCH_SIZE) {
      const { data, error } = await client
        .from('campaign_reports')
        .upsert(inserts.slice(i, i + BATCH_SIZE), { onConflict: 'submitted_at', ignoreDuplicates: true })
        .select('id');
      if (error) throw error;
      inserted += data?.length ?? 0;
    }
  }

  const derived = await deriveCampaignReportFieldsSince(client, DERIVE_SINCE, apply);

  return {
    sheetRows: rawRows.length,
    skippedNoTimestamp,
    duplicateTimestampsInSheet: duplicateTimestamps,
    inserted,
    alreadyPresent: inserts.length - inserted,
    needsReview: inserts.filter((r) => r.needs_review).length,
    derived,
  };
}

