import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * How many members registered interest per campaign — numbers only, no names
 * or contact details. Members' details (campaign_interest / training_interest
 * rows) can only be read by a session that passed 2FA, but leaders still need
 * the *count* without 2FA: for the "N people interested" note on a campaign
 * and to know whether the "Manage my Campaign Interest" button should show
 * (which is what leads them to set 2FA up).
 *
 * Visibility is decided by the caller's OWN session, not by us: `userClient`
 * is a Supabase client carrying the caller's JWT, so reading `campaigns`
 * through it returns only campaigns that person may see (own, shared, or all
 * for an admin) — the same RLS the rest of the app relies on. Only for those
 * campaigns does `adminClient` (service role, which bypasses the 2FA-gated
 * policy) count rows. Injected clients, like backupService.ts.
 */
export const MAX_CAMPAIGN_IDS = 500;

export interface InterestCounts {
  campaignInterest: Record<string, number>;
  trainingInterest: Record<string, number>;
}

async function countByCampaign(
  adminClient: SupabaseClient,
  table: 'campaign_interest' | 'training_interest',
  campaignIds: string[],
): Promise<Record<string, number>> {
  if (campaignIds.length === 0) return {};
  const { data, error } = await adminClient.from(table).select('campaign_id').in('campaign_id', campaignIds);
  if (error) throw error;
  const counts: Record<string, number> = {};
  for (const row of (data ?? []) as { campaign_id: string }[]) {
    counts[row.campaign_id] = (counts[row.campaign_id] ?? 0) + 1;
  }
  return counts;
}

export async function getVisibleInterestCounts(
  userClient: SupabaseClient,
  adminClient: SupabaseClient,
  requestedIds: string[],
): Promise<InterestCounts> {
  const ids = [...new Set(requestedIds)].slice(0, MAX_CAMPAIGN_IDS);
  if (ids.length === 0) return { campaignInterest: {}, trainingInterest: {} };

  const { data, error } = await userClient.from('campaigns').select('id').in('id', ids);
  if (error) throw error;
  const visibleIds = ((data ?? []) as { id: string }[]).map((c) => c.id);

  const [campaignInterest, trainingInterest] = await Promise.all([
    countByCampaign(adminClient, 'campaign_interest', visibleIds),
    countByCampaign(adminClient, 'training_interest', visibleIds),
  ]);
  return { campaignInterest, trainingInterest };
}

lib/services/leaderSharesService.ts:
import { supabase } from '@/lib/supabaseClient';

export interface LeaderShare {
  id: string;
  owner_state: string;
  owner_leader: string;
  shared_with_state: string;
  shared_with_leader: string;
  created_at: string;
}

export interface NewLeaderShare {
  owner_state: string;
  owner_leader: string;
  shared_with_state: string;
  shared_with_leader: string;
}

/** Fetch every leader-sharing row, ordered by owner state then leader. */
export async function getLeaderShares(): Promise<LeaderShare[]> {
  const { data, error } = await supabase
    .from('leader_shares')
    .select('*')
    .order('owner_state', { ascending: true })
    .order('owner_leader', { ascending: true });
  if (error) throw error;
  return (data || []) as LeaderShare[];
}

/** Create a leader-sharing row. Throws a friendly error on the (owner, shared-with) duplicate conflict. */
export async function createLeaderShare(input: NewLeaderShare): Promise<void> {
  const { error } = await supabase.from('leader_shares').insert([input]);
  if (error) {
    if (error.code === '23505') throw new Error('This sharing relationship already exists');
    throw error;
  }
}

export async function deleteLeaderShare(id: string): Promise<void> {
  const { error } = await supabase.from('leader_shares').delete().eq('id', id);
  if (error) throw error;
}

lib/services/leaderVerificationService.t:
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { normalizeMobile, normalizeName } from '@/lib/auth';

export interface VerifiedStateLeaderRow {
  id: string;
  state: string;
  leader: string;
  mobile: string | null;
  admin: string | null;
  email: string | null;
  pending_email: string | null;
  mfa_enrolled_at: string | null;
}

/**
 * Server-side mobile+name verification against state_leaders, shared by
 * app/api/auth/validate-leader/route.ts (the original login check) and
 * app/api/auth/propose-email/route.ts (which must re-verify the same pair
 * rather than trust a bare leaderId — see that route's own comment).
 * Extracted so the two routes can't drift apart on this security-sensitive
 * matching logic, per this project's standing rule against duplicating
 * that kind of check (see stateLeadersService.ts's assertValidAdminValue).
 *
 * Uses supabaseAdmin (service role) — callers run unauthenticated, before
 * any session exists.
 */
export async function findVerifiedStateLeaders(
  mobile: string,
  firstName: string,
): Promise<VerifiedStateLeaderRow[]> {
  const mobileNormalized = normalizeMobile(mobile);
  const firstNameNormalized = normalizeName(firstName);

  if (!mobileNormalized || !firstNameNormalized) return [];

  // Prefix-match on leader name to limit the result set while still tolerating
  // trailing whitespace in stored values (e.g. "Rosheen "). The JS filter below
  // enforces an exact normalised-name match, so "Rosh" will never match "Rosheen".
  const { data, error } = await supabaseAdmin
    .from('state_leaders')
    .select('id, state, leader, mobile, admin, email, pending_email, mfa_enrolled_at')
    .ilike('leader', `${firstNameNormalized}%`);

  if (error) throw error;
  if (!data || data.length === 0) return [];

  return (data as VerifiedStateLeaderRow[]).filter((rec) => {
    const storedNameNormalized = normalizeName(rec.leader ?? '');
    if (storedNameNormalized !== firstNameNormalized) return false;
    if (!rec.mobile) return false;
    return normalizeMobile(rec.mobile) === mobileNormalized;
  });
}

lib/services/mfaEnrollmentService.ts:
import type { SupabaseClient } from '@supabase/supabase-js';

export type CompleteEnrollmentResult =
  | { ok: true; enrolledRows: number }
  | { ok: false; status: number; error: string };

/** Escapes LIKE/ILIKE wildcards so an address is matched literally — `_` is
 * common in email local-parts and would otherwise match any character. */
export function escapeLikePattern(value: string): string {
  return value.replace(/[\\%_]/g, '\\$&');
}

/**
 * Finishes MFA enrollment for a verified session (caller has already checked
 * the session has a verified factor).
 *
 * Step 1 binds `user_id` on every still-unbound state_leaders row whose
 * `email` is the address this session just proved inbox control of. A row's
 * `email` is trusted by construction — it is only ever set by a completed
 * self-serve confirmation (which binds user_id itself) or typed in by an
 * admin, which counts as confirmed — so the person who has just proved they
 * control that inbox *and* holds a verified authenticator is entitled to be
 * tied to those rows. Without this, an admin-entered email never got a
 * user_id: setup finished, but only the one row the account happened to be
 * bound to was marked enrolled, and the rest (e.g. a leader's AD row) could
 * never appear under email sign-in (found 2026-10-12). Rows already bound to
 * a different account are never touched.
 *
 * Step 2 stamps mfa_enrolled_at on every row now bound to this account.
 * Injected client (always supabaseAdmin) like backupService.ts's exportBackup.
 */
export async function completeMfaEnrollment(
  client: SupabaseClient,
  params: { userId: string; email: string | null | undefined },
): Promise<CompleteEnrollmentResult> {
  const { userId, email } = params;
  const now = new Date().toISOString();

  if (email) {
    const { error: bindError } = await client
      .from('state_leaders')
      .update({ user_id: userId, email_confirmed_at: now })
      .is('user_id', null)
      .ilike('email', escapeLikePattern(email.trim()));
    if (bindError) {
      console.error('complete-mfa-setup: failed to bind user_id:', bindError);
      return { ok: false, status: 500, error: 'Internal server error' };
    }
  }

  const { error: updateError, count } = await client
    .from('state_leaders')
    .update({ mfa_enrolled_at: now }, { count: 'exact' })
    .eq('user_id', userId);
  if (updateError) {
    console.error('complete-mfa-setup: failed to write mfa_enrolled_at:', updateError);
    return { ok: false, status: 500, error: 'Internal server error' };
  }
  if (!count) {
    return { ok: false, status: 404, error: 'No matching leader record found for this account' };
  }
  return { ok: true, enrolledRows: count };
}

