import { supabase } from '@/lib/supabaseClient';

/** Browser-side call to POST /api/admin/reset-mfa. Throws with the server's
 * message on failure. (Separate file from mfaResetService.ts so the server
 * code doesn't import the browser Supabase client.) */
export async function requestMfaReset(leaderId: string): Promise<{ factorsRemoved: number; rowsReset: number }> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error('Not signed in');

  const res = await fetch('/api/admin/reset-mfa', {
    method: 'POST',
    headers: { Authorization: `Bearer ${session.access_token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ leaderId }),
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error((json as { error?: string }).error || 'Failed to reset two-factor authentication');
  return json as { factorsRemoved: number; rowsReset: number };
}

lib/services/mfaResetService.ts:
import type { SupabaseClient } from '@supabase/supabase-js';

export type ResetMfaResult =
  | { ok: true; factorsRemoved: number; rowsReset: number }
  | { ok: false; status: number; error: string };

/**
 * Resets a leader's two-factor authentication (an admin's "lost phone"
 * recovery): deletes every MFA factor on the leader's auth account, clears
 * mfa_enrolled_at on every state_leaders row bound to that account, and
 * deletes the account's user_profiles/user_roles rows so any session it
 * still holds loses its app identity immediately. The leader must then sign
 * in again — for an admin that means going through the normal email + 2FA
 * setup before they can get back in. Never lets an admin reset their own
 * (a lost phone is the case where they can't be signed in to ask anyway, and
 * resetting yourself mid-session is just a way to lock yourself out).
 *
 * The audit row is best-effort — it never blocks the reset itself (the table
 * comes from scripts/create_state_leader_mfa_resets_table.sql).
 * Injected client, always supabaseAdmin.
 */
export async function resetLeaderMfa(
  client: SupabaseClient,
  params: { leaderId: string; actorUserId: string; actorLabel: string },
): Promise<ResetMfaResult> {
  const { leaderId, actorUserId, actorLabel } = params;

  const { data: target, error: targetError } = await client
    .from('state_leaders')
    .select('id, user_id')
    .eq('id', leaderId)
    .maybeSingle();
  if (targetError) {
    console.error('reset-mfa: leader lookup failed:', targetError);
    return { ok: false, status: 500, error: 'Internal server error' };
  }
  if (!target) return { ok: false, status: 404, error: 'Leader not found' };

  const targetUserId = (target as { user_id: string | null }).user_id;
  if (!targetUserId) {
    return { ok: false, status: 409, error: 'This leader has no email sign-in account yet, so there is no 2FA to reset.' };
  }
  if (targetUserId === actorUserId) {
    return { ok: false, status: 400, error: "You can't reset your own 2FA — ask another admin to do it." };
  }

  const { data: factorData, error: listError } = await client.auth.admin.mfa.listFactors({ userId: targetUserId });
  if (listError) {
    console.error('reset-mfa: listFactors failed:', listError);
    return { ok: false, status: 500, error: 'Internal server error' };
  }
  const factors = factorData?.factors ?? [];
  for (const factor of factors) {
    const { error: deleteError } = await client.auth.admin.mfa.deleteFactor({ id: factor.id, userId: targetUserId });
    if (deleteError) {
      console.error('reset-mfa: deleteFactor failed:', deleteError);
      return { ok: false, status: 500, error: 'Internal server error' };
    }
  }

  const { error: clearError, count } = await client
    .from('state_leaders')
    .update({ mfa_enrolled_at: null }, { count: 'exact' })
    .eq('user_id', targetUserId);
  if (clearError) {
    console.error('reset-mfa: clearing mfa_enrolled_at failed:', clearError);
    return { ok: false, status: 500, error: 'Internal server error' };
  }

  // End any live session's app identity right away (RLS is_admin() reads user_profiles).
  for (const table of ['user_profiles', 'user_roles'] as const) {
    const { error } = await client.from(table).delete().eq('user_id', targetUserId);
    if (error) console.warn(`reset-mfa: failed to clear ${table}:`, error);
  }

  const { error: auditError } = await client.from('state_leader_mfa_resets').insert([
    { state_leader_id: leaderId, target_user_id: targetUserId, reset_by: actorLabel, reset_by_user_id: actorUserId },
  ]);
  if (auditError) console.warn('reset-mfa: failed to record audit row:', auditError);

  return { ok: true, factorsRemoved: factors.length, rowsReset: count ?? 0 };
}

lib/services/nearbyCampaignsService.ts:
/**
 * Builds map-ready data for the "Campaigns Near Me" screen: campaigns within
 * a date range, filtered to those whose place is within a radius (km) of a
 * given centre point. Reuses the existing getMapData() pipeline so geocoding
 * lookups and the state_places cache are shared with the admin campaign map.
 */
import { getMapData, type MapMarker, type MapDataResult } from '@/lib/services/campaignMapService';

export interface NearbyCampaignsOptions {
  startDate: string;
  endDate: string;
  centerLat: number;
  centerLng: number;
  radiusKm: number;
}

export interface NearbyMapMarker extends MapMarker {
  // Narrowed back to required: these markers are always built from getMapData's
  // campaign-grouped markers below, which populate campaigns unconditionally.
  campaigns: NonNullable<MapMarker['campaigns']>;
  /** Straight-line distance from the centre, in km, rounded to one decimal. */
  distanceKm: number;
}

export interface NearbyCampaignsResult {
  markers: NearbyMapMarker[];
  unresolvedPlaces: MapDataResult['unresolvedPlaces'];
}

const EARTH_RADIUS_KM = 6371;

/**
 * Great-circle distance between two lat/lng points using the haversine formula.
 * Accurate to better than 0.5% for distances under a few hundred km, which is well
 * within the precision needed for "campaigns within 60 km".
 */
export function haversineKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);

  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(h));
}

export async function getNearbyCampaigns(
  options: NearbyCampaignsOptions,
): Promise<NearbyCampaignsResult> {
  const { centerLat, centerLng, radiusKm, startDate, endDate } = options;

  // No state filter — campaigns within 60 km of a border may straddle two states.
  const { markers, unresolvedPlaces } = await getMapData({ startDate, endDate });

  const center = { lat: centerLat, lng: centerLng };
  const nearby: NearbyMapMarker[] = [];
  for (const marker of markers) {
    const distanceKm = haversineKm(center, { lat: marker.latitude, lng: marker.longitude });
    if (distanceKm <= radiusKm) {
      // getMapData always populates campaigns; the fallback only satisfies the type
      // checker for MapMarker's now-optional field, never actually engages.
      nearby.push({ ...marker, campaigns: marker.campaigns ?? [], distanceKm: Math.round(distanceKm * 10) / 10 });
    }
  }

  nearby.sort((a, b) => a.distanceKm - b.distanceKm);

  return { markers: nearby, unresolvedPlaces };
}

lib/services/newStatePlace.ts:
/**
 * The one place that decides what a freshly created `state_places` row looks
 * like, whichever screen creates it (a leader typing a new place in a
 * campaign form, or an admin adding a historical place from the Campaign
 * Reports screens). Every new place gets its `location` text (the query an
 * admin can re-run from /admin/state-places) and, when Nominatim finds it
 * *inside the right state*, coordinates — without these a place is invisible
 * on the public maps, which never geocode on demand.
 */
import { geocodePlace, type GeocodeResult } from '@/lib/geocoding';
import { isWithinState } from '@/lib/stateBounds';

export interface NewStatePlaceRow {
  state: string;
  place: string;
  location: string;
  latitude?: number;
  longitude?: number;
}

export async function buildNewStatePlaceRow(
  state: string,
  place: string,
  geocode: (place: string, state: string) => Promise<GeocodeResult | null> = geocodePlace,
): Promise<NewStatePlaceRow> {
  const normalizedState = state.toUpperCase().trim();
  const normalizedPlace = place.trim();
  const row: NewStatePlaceRow = { state: normalizedState, place: normalizedPlace, location: normalizedPlace };

  const found = await geocode(normalizedPlace, normalizedState).catch(() => null);
  if (found && isWithinState(found.latitude, found.longitude, normalizedState)) {
    row.latitude = found.latitude;
    row.longitude = found.longitude;
  }
  return row;
}

lib/services/placeService.ts:
import { supabase } from '@/lib/supabaseClient';
import { buildNewStatePlaceRow } from '@/lib/services/newStatePlace';

/**
 * Insert a new place for the given state. Silently ignores duplicate (23505).
 *
 * Best-effort geocodes the place immediately (see newStatePlace.ts), using the place name itself
 * as the location text — this call site (a leader typing a brand-new place
 * inline while creating a campaign, via useCampaignForm.ts) has no separate
 * "location" field the way the admin Manage State Places page does, so
 * without this a new place silently lands with no coordinates at all. The
 * public Campaigns Near Me map never geocodes on demand (only cached
 * state_places coordinates — see publicCampaignsNearMeService.ts), so an
 * ungeocoded place is invisible there with no warning until someone
 * notices a campaign missing from their map (see CLAUDE.md's 2026-09-17
 * "state_places geocoding gap" entry for the incident this prevents).
 * Most everyday place names (a suburb/town) geocode fine as-is; a venue or
 * event name that doesn't is left ungeocoded exactly as before — an admin
 * can fix it via Manage State Places, which now flags any place missing
 * coordinates regardless of cause.
 */
export async function addNewPlaceForState(state: string, place: string): Promise<void> {
  const row = await buildNewStatePlaceRow(state, place);

  const { error } = await supabase.from('state_places').insert([row]);
  if (error && error.code !== '23505')
    throw new Error(`Failed to add new place: ${error.message}`);
}

lib/services/publicCampaignListService.t:
/**
 * Shared data fetch for the public, unauthenticated "current fortnight, all
 * states" campaign list — the same underlying dataset behind both
 * `/api/public/temporary-upcoming-campaigns` and `/api/public/final-campaign-lists`.
 * Those two pages differ only in copy and available actions (Edit+Download vs
 * Download-only); the query, date range, and response shape are identical, so
 * it lives here once rather than being duplicated per route.
 */
import { supabaseAdmin } from '@/lib/supabaseAdmin';
import { calculateCampaignDates, formatDateForDb, getFortnightDateRange } from '@/lib/campaignDates';
import type { SlideCampaign, PublicSlideDay } from '@/lib/slideGenerator';

/**
 * The upcoming fortnight's dates, formatted for the DB. Cheap (no DB call) —
 * callers use `dateStrings[0]` as a short-lived cache key so they can skip
 * the actual query (fetchFortnightCampaignDays) on a cache hit.
 */
export function getUpcomingFortnightDateStrings(): string[] {
  const { upcomingCampaignStart } = calculateCampaignDates();
  return getFortnightDateRange(upcomingCampaignStart).map(formatDateForDb);
}

/**
 * Fetches the given dates' campaigns (all states) plus each day's
 * campaign_messages banner text, shaped for generateAndDownloadSlidesFromData
 * (lib/slideGenerator.ts) — one fetch powers both an on-screen list and its
 * ZIP download. Pass `getUpcomingFortnightDateStrings()`.
 *
 * mobile is hard-coded null on every campaign — this data is served to
 * anonymous callers and must never carry a phone number.
 */
export async function fetchFortnightCampaignDays(dateStrings: string[]): Promise<PublicSlideDay[]> {
  const [campaignsResult, messagesResult] = await Promise.all([
    supabaseAdmin
      .from('campaigns')
      .select('id, date, state, place, site, time, leader, category')
      .gte('date', dateStrings[0])
      .lte('date', dateStrings[dateStrings.length - 1])
      .order('date', { ascending: true })
      .order('state', { ascending: true })
      .order('place', { ascending: true })
      .order('time', { ascending: true }),
    supabaseAdmin
      .from('campaign_messages')
      .select('date, message')
      .gte('date', dateStrings[0])
      .lte('date', dateStrings[dateStrings.length - 1]),
  ]);

  if (campaignsResult.error) {
    throw new Error(`campaigns query failed: ${campaignsResult.error.message}`);
  }
  if (messagesResult.error) {
    throw new Error(`campaign_messages query failed: ${messagesResult.error.message}`);
  }

  const campaigns = campaignsResult.data ?? [];
  const messageByDate = new Map<string, string>(
    (messagesResult.data ?? []).map((m: { date: string; message: string }) => [m.date, m.message]),
  );

  return dateStrings.map((date) => ({
    date,
    campaigns: campaigns
      .filter((c) => c.date === date)
      .map((c): SlideCampaign => ({ ...c, mobile: null })),
    message: messageByDate.get(date) ?? null,
  }));
}

lib/services/publicCampaignResultsServic:
/**
 * Which campaign week the public Campaign Results link
 * (/public/campaign-results) shows.
 *
 * The page shows the oldest week the last Weekly Refresh left in the
 * database, and keeps showing it until the next refresh runs — not until a
 * fixed weekday. Each refresh deletes every campaign (and its results) dated
 * before `calculateCampaignDates().pastCampaignStart` as of the moment it ran,
 * so re-deriving that same date from the last successful run's timestamp
 * names exactly the week that refresh kept, and the week the *next* refresh
 * will delete. With the Sunday cron that means: the Mon-Sun week just ended
 * is shown from that Sunday's refresh until the following Sunday's.
 *
 * Deliberately not `calculateCampaignDates()` as of "now" (what the admin
 * "Campaign Results" quick action still uses): that flips to the in-progress
 * week every Thursday, three days before the previous week is removed.
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { calculateCampaignDates } from '@/lib/campaignDates';

/**
 * `completed_at` of the most recent Weekly Refresh that succeeded (failed
 * runs are logged with an `error_message` and may not have deleted
 * anything). Null if none has been logged. Takes an injected client — the
 * service role in practice, since an anonymous visitor can't read this log.
 */
export async function getLastSuccessfulWeeklyRefreshAt(client: SupabaseClient): Promise<Date | null> {
  const { data, error } = await client
    .from('weekly_refresh_log')
    .select('completed_at')
    .is('error_message', null)
    .order('completed_at', { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) throw error;
  return data?.completed_at ? new Date(data.completed_at) : null;
}

/**
 * Monday of the week the public page shows. Falls back to the current
 * date-based past week when no successful refresh has ever been logged.
 */
export function getDisplayedResultsWeekStart(lastRefreshAt: Date | null, now: Date = new Date()): Date {
  return calculateCampaignDates(lastRefreshAt ?? now).pastCampaignStart;
}

lib/services/publicCampaignsNearMeServic:
/**
 * Pure map-assembly logic for the public "Campaigns Near Me" screen a
 * registrant reaches from their WhatsApp-invite email
 * (app/public/campaigns-near-me, app/api/public/campaigns-near-me/route.ts).
 *
 * Deliberately narrower than lib/services/nearbyCampaignsService.ts's
 * admin equivalent: this only ever uses cached state_places coordinates
 * (no on-demand Nominatim geocoding of a place — that goes through the
 * admin-only /api/admin/geocode-place route, which an anonymous public
 * visitor can't call), and takes already-fetched rows rather than calling
 * Supabase itself, so the actual grouping/distance/sort logic is testable
 * with no mocks at all. The route handler does the (untested, matching
 * this codebase's convention for /api/public/* handlers) fetching.
 */
import { haversineKm } from './nearbyCampaignsService';
import { placeKey } from './campaignMapService';

export interface PublicNearbyCampaignRow {
  id: string;
  date: string;
  state: string;
  place: string;
  time: string;
  leader: string;
  category: string | null;
}

export interface PublicPlaceCoords {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
}

export interface PublicNearbyCampaign {
  id: string;
  date: string;
  time: string;
  leader: string;
  category: string | null;
}

export interface PublicNearbyMarker {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
  /** Straight-line distance from the centre, in km, rounded to one decimal. */
  distanceKm: number;
  campaigns: PublicNearbyCampaign[];
}

/** GET /api/public/campaigns-near-me's full response shape — shared with the page (app/public/campaigns-near-me/page.tsx) since route.ts files can't export anything but HTTP methods/route config. */
export interface CampaignsNearMeResponse {
  firstName: string | null;
  startDate: string;
  endDate: string;
  radiusKm: number;
  /** null when there's no postcode/state to centre a map on, or geocoding that failed — the page shows a fallback message rather than an empty map in that case. */
  center: { latitude: number; longitude: number; label: string } | null;
  markers: PublicNearbyMarker[];
  unresolvedCount: number;
}

export interface BuildNearbyMarkersResult {
  markers: PublicNearbyMarker[];
  /** Distinct places with at least one campaign in range but no cached coordinates. */
  unresolvedCount: number;
}

/**
 * Groups already-upcoming, in-window campaigns by place, resolves each
 * place's coordinates from `placeCoords` (cached state_places rows only),
 * and keeps only those within `radiusKm` of `center` — sorted nearest
 * first. Callers are responsible for having already filtered `campaigns`
 * to the desired date range and excluded past ones (isCampaignPast).
 */
export function buildNearbyMarkers(
  campaigns: PublicNearbyCampaignRow[],
  placeCoords: PublicPlaceCoords[],
  center: { latitude: number; longitude: number },
  radiusKm: number,
): BuildNearbyMarkersResult {
  const coordsByKey = new Map(placeCoords.map((p) => [placeKey(p.state, p.place), p]));

  const grouped = new Map<string, { state: string; place: string; campaigns: PublicNearbyCampaign[] }>();
  for (const c of campaigns) {
    const key = placeKey(c.state, c.place);
    const entry: PublicNearbyCampaign = { id: c.id, date: c.date, time: c.time, leader: c.leader, category: c.category };
    const group = grouped.get(key);
    if (group) {
      group.campaigns.push(entry);
    } else {
      grouped.set(key, { state: c.state, place: c.place, campaigns: [entry] });
    }
  }

  const markers: PublicNearbyMarker[] = [];
  let unresolvedCount = 0;
  for (const [key, group] of grouped) {
    const coords = coordsByKey.get(key);
    if (!coords) {
      unresolvedCount++;
      continue;
    }
    // haversineKm takes {lat, lng} — everything else here uses
    // {latitude, longitude} (matching the campaigns-near-me API response
    // shape), so this is the one spot they're translated.
    const distanceKm = haversineKm(
      { lat: center.latitude, lng: center.longitude },
      { lat: coords.latitude, lng: coords.longitude },
    );
    if (distanceKm <= radiusKm) {
      markers.push({ ...group, latitude: coords.latitude, longitude: coords.longitude, distanceKm: Math.round(distanceKm * 10) / 10 });
    }
  }

  markers.sort((a, b) => a.distanceKm - b.distanceKm);

  return { markers, unresolvedCount };
}

lib/services/publicUpcomingCampaignsServ:
/**
 * Pure map-assembly logic for the public "Upcoming Campaigns" map
 * (app/public/upcoming-campaigns, app/api/public/upcoming-campaigns/route.ts)
 * — the general-public counterpart to lib/services/campaignMapService.ts's
 * admin `getMapData`. Deliberately narrower, same reasoning as
 * publicCampaignsNearMeService.ts: this only ever uses cached state_places
 * coordinates (no on-demand Nominatim geocoding, which needs the
 * admin-only /api/admin/geocode-place route an anonymous visitor can't
 * call), and takes already-fetched rows rather than calling Supabase
 * itself, so the grouping logic is testable with no mocks. Unlike
 * publicCampaignsNearMeService's buildNearbyMarkers, there is no
 * centre/radius — every upcoming campaign in the given rows is grouped
 * into a marker, since this map shows all states at once rather than a
 * distance-filtered view.
 */
import { placeKey } from './campaignMapService';

export interface PublicUpcomingCampaignRow {
  id: string;
  date: string;
  state: string;
  place: string;
  time: string;
  leader: string;
  category: string | null;
}

export interface PublicUpcomingPlaceCoords {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
}

export interface PublicUpcomingCampaign {
  id: string;
  date: string;
  time: string;
  leader: string;
  category: string | null;
}

export interface PublicUpcomingMarker {
  state: string;
  place: string;
  latitude: number;
  longitude: number;
  campaigns: PublicUpcomingCampaign[];
}

export interface BuildUpcomingMarkersResult {
  markers: PublicUpcomingMarker[];
  /** Distinct places with at least one campaign in range but no cached coordinates. */
  unresolvedCount: number;
}

/**
 * Groups in-window campaigns by place and resolves each
 * place's coordinates from `placeCoords` (cached state_places rows only).
 * Callers are responsible for having already filtered `campaigns` to the
 * desired date range. Past campaigns within the range are kept — the page
 * shows the whole selected week.
 */
export function buildUpcomingCampaignMarkers(
  campaigns: PublicUpcomingCampaignRow[],
  placeCoords: PublicUpcomingPlaceCoords[],
): BuildUpcomingMarkersResult {
  const coordsByKey = new Map(placeCoords.map((p) => [placeKey(p.state, p.place), p]));

  const grouped = new Map<string, { state: string; place: string; campaigns: PublicUpcomingCampaign[] }>();
  for (const c of campaigns) {
    const key = placeKey(c.state, c.place);
    const entry: PublicUpcomingCampaign = { id: c.id, date: c.date, time: c.time, leader: c.leader, category: c.category };
    const group = grouped.get(key);
    if (group) {
      group.campaigns.push(entry);
    } else {
      grouped.set(key, { state: c.state, place: c.place, campaigns: [entry] });
    }
  }

  const markers: PublicUpcomingMarker[] = [];
  let unresolvedCount = 0;
  for (const [key, group] of grouped) {
    const coords = coordsByKey.get(key);
    if (!coords) {
      unresolvedCount++;
      continue;
    }
    markers.push({ ...group, latitude: coords.latitude, longitude: coords.longitude });
  }

  return { markers, unresolvedCount };
}

