import { supabase } from '@/lib/supabaseClient';
import type { CampaignRule, CampaignRuleInput } from '@/lib/types';

interface DeletedRuleCampaign {
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
}

interface GetRulesOptions {
  adminStatus: string | null;
  userState: string | null;
  userLeader: string | null;
}

export async function getRules({
  adminStatus,
  userState,
  userLeader,
}: GetRulesOptions): Promise<CampaignRule[]> {
  const isTeamLeader = adminStatus !== 'AD' && adminStatus !== 'SR' && !!userState;
  const isStateReporter = adminStatus === 'SR';

  if (isTeamLeader && !userLeader) return [];

  let query = supabase.from('campaign_rules').select('*');

  if (isStateReporter && userState) {
    query = query.eq('state', userState.toUpperCase().trim());
  }
  if (isTeamLeader && userState && userLeader) {
    query = query.eq('state', userState.toUpperCase().trim()).eq('leader', userLeader);
  }

  const { data, error } = await query
    .order('priority', { ascending: false })
    .order('created_at', { ascending: false });

  if (error) throw error;
  return (data || []) as CampaignRule[];
}

/**
 * A rule with a blank leader generates blank-leader campaigns every single
 * week via the automated refresh (weeklyRefreshService inserts rule-generated
 * rows directly, bypassing campaignService's own leader-required guard — see
 * #84, which closed this gap for manual campaign create/update but not for
 * rules). Rejecting it here is the service-layer choke point for every
 * caller (the admin rules form today, any future one).
 */
function assertLeaderPresent(leader: string | undefined): void {
  if (!leader?.trim()) throw new Error('Leader is required');
}

export async function createRule(
  ruleData: CampaignRuleInput,
  createdBy: string,
): Promise<void> {
  assertLeaderPresent(ruleData.leader);

  const { error } = await supabase
    .from('campaign_rules')
    .insert([{ ...ruleData, created_by: createdBy }]);
  if (error) throw error;
}

export async function updateRule(
  id: string,
  ruleData: Partial<CampaignRuleInput>,
): Promise<void> {
  // Only enforced when this update actually touches `leader` — partial updates
  // to unrelated fields (rule_config exceptions, is_active, etc.) don't include it.
  if ('leader' in ruleData) assertLeaderPresent(ruleData.leader);

  const { error } = await supabase.from('campaign_rules').update(ruleData).eq('id', id);
  if (error) throw error;
}

export async function deleteRule(id: string): Promise<void> {
  const { error } = await supabase.from('campaign_rules').delete().eq('id', id);
  if (error) throw error;
}

export async function setRuleActive(id: string, isActive: boolean): Promise<void> {
  const { error } = await supabase
    .from('campaign_rules')
    .update({ is_active: isActive })
    .eq('id', id);
  if (error) throw error;
}

/**
 * Record a rule exception so a manually-deleted, rule-generated campaign is never
 * silently regenerated by a later weekly refresh (see #93 investigation — the refresh's
 * dedup only checks whether a matching row currently exists, so a deletion was
 * indistinguishable from "never generated" and got recreated).
 *
 * Matches the deleted campaign back to its originating rule(s) by state/place/site/leader
 * plus effective time (accounting for a per-date `override_fields` time override, since the
 * stored campaign keeps the override value while `rule.time` stays the rule's default), then
 * appends the campaign's date to that rule's `rule_config.exceptions` — the same list
 * `isDateExcepted` in campaignRules.ts already filters out during evaluation.
 *
 * Best-effort: errors are logged, never thrown, so a lookup/update failure here must not
 * block the campaign deletion itself.
 */
export async function excludeDateForDeletedCampaign(campaign: DeletedRuleCampaign): Promise<void> {
  try {
    const { data: candidateRules, error } = await supabase
      .from('campaign_rules')
      .select('id, time, rule_config')
      .eq('state', campaign.state)
      .eq('place', campaign.place)
      .eq('site', campaign.site)
      .eq('leader', campaign.leader);
    if (error) throw error;

    const matches = ((candidateRules || []) as Pick<CampaignRule, 'id' | 'time' | 'rule_config'>[]).filter(
      (rule) => {
        const overrideTime = rule.rule_config?.override_fields?.[campaign.date]?.time;
        const effectiveTime = typeof overrideTime === 'string' ? overrideTime : rule.time;
        return effectiveTime === campaign.time;
      },
    );

    for (const rule of matches) {
      const exceptions = rule.rule_config?.exceptions ?? [];
      if (exceptions.includes(campaign.date)) continue;

      const { error: updateError } = await supabase
        .from('campaign_rules')
        .update({ rule_config: { ...rule.rule_config, exceptions: [...exceptions, campaign.date] } })
        .eq('id', rule.id);
      if (updateError) throw updateError;
    }
  } catch (err) {
    console.error('[rulesService] Failed to record deletion exception:', err);
  }
}

lib/services/sessionAccessService.ts:
import type { SupabaseClient } from '@supabase/supabase-js';
import { findVerifiedStateLeaders } from '@/lib/services/leaderVerificationService';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';

export type GrantRequest =
  | { method: 'mobile-name'; leaderId: string; mobile: string; firstName: string }
  | { method: 'real-auth'; leaderId: string };

export type GrantResult = { ok: true } | { ok: false; status: number; error: string; code?: 'mfa_required' };

interface GrantedLeader {
  leader: string;
  state: string;
  admin: string | null;
}

/** Reads the `aal` claim from a JWT payload. Only call this on a token that
 * supabaseAdmin.auth.getUser() has already validated — it does not verify the
 * signature itself. */
export function getAalFromJwt(token: string): string | null {
  try {
    const payload = token.split('.')[1];
    if (!payload) return null;
    const json = Buffer.from(payload.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
    const aal = (JSON.parse(json) as { aal?: unknown }).aal;
    return typeof aal === 'string' ? aal : null;
  } catch {
    return null;
  }
}

/**
 * Writes the user_profiles / user_roles rows that every "who is this / are
 * they admin" consumer (UserContext, campaignFilter.ts, RLS is_admin(), the
 * admin API routes) reads for a session — but only after verifying, on the
 * server, that the caller is entitled to the leader row they're asking for.
 * Before this existed the browser wrote those rows itself, and user_roles'
 * RLS let any signed-in session (including a bare anonymous one) write its
 * own `admin` row — so the login screen was the only thing standing between
 * anyone and admin access (found 2026-10-11). Takes an injected client
 * (always supabaseAdmin in practice) like backupService.ts's exportBackup.
 *
 * Two ways to prove entitlement:
 * - 'mobile-name': the legacy login. Re-verifies the typed mobile+first name
 *   against state_leaders on the server (a bare leaderId is never trusted)
 *   and that the chosen leaderId is one of the verified matches. Refused
 *   outright (code 'mfa_required') for an AD or SR row.
 * - 'real-auth': the email + MFA login. The session's user must be the
 *   state_leaders row's bound user_id AND the token must be at aal2.
 *
 * A non-AD leader explicitly has any existing admin role deleted, since a
 * real-auth user_id persists across logins and a different role may be
 * picked each time.
 */
export async function grantSessionAccess(
  client: SupabaseClient,
  params: {
    userId: string;
    aal: string | null;
    request: GrantRequest;
    verifyLeaders?: typeof findVerifiedStateLeaders;
  },
): Promise<GrantResult> {
  const { userId, aal, request, verifyLeaders = findVerifiedStateLeaders } = params;

  let leader: GrantedLeader | null = null;

  if (request.method === 'mobile-name') {
    const matches = await verifyLeaders(request.mobile, request.firstName);
    leader = matches.find((m) => m.id === request.leaderId) ?? null;
    if (!leader) return { ok: false, status: 403, error: 'No matching leader found' };
    // Admins (AD and SR) must use email + an authenticator code — mobile+name
    // alone, which anyone who knows an admin's number and first name could
    // supply, never yields an admin identity (mandatory 2FA, 2026-10-12).
    if (isRecognizedAdminStatus(leader.admin)) {
      return {
        ok: false,
        status: 403,
        code: 'mfa_required',
        error: 'Admin accounts must sign in with email and two-factor authentication.',
      };
    }
  } else {
    const { data, error } = await client
      .from('state_leaders')
      .select('leader, state, admin, user_id')
      .eq('id', request.leaderId)
      .maybeSingle();
    if (error) {
      console.error('grant-session-access: leader lookup failed:', error);
      return { ok: false, status: 500, error: 'Internal server error' };
    }
    if (!data || data.user_id !== userId || aal !== 'aal2') {
      return { ok: false, status: 403, error: 'Not authorised for this leader' };
    }
    leader = data as GrantedLeader;
  }

  const { error: profileError } = await client
    .from('user_profiles')
    .upsert({ user_id: userId, name: leader.leader.trim(), state: leader.state }, { onConflict: 'user_id' });
  if (profileError) {
    console.error('grant-session-access: profile write failed:', profileError);
    return { ok: false, status: 500, error: 'Internal server error' };
  }

  const { error: roleError } =
    leader.admin === 'AD'
      ? await client.from('user_roles').upsert({ user_id: userId, role: 'admin' }, { onConflict: 'user_id' })
      : await client.from('user_roles').delete().eq('user_id', userId);
  if (roleError) {
    console.error('grant-session-access: role write failed:', roleError);
    return { ok: false, status: 500, error: 'Internal server error' };
  }

  return { ok: true };
}

/**
 * Removes a session's user_profiles / user_roles rows — the counterpart to
 * grantSessionAccess, called on sign-out. Those rows *are* the session's app
 * identity (RLS is_admin() and the app read them), so leaving them behind
 * after sign-out meant every mobile+name login — each a brand-new anonymous
 * account — left a permanent admin-looking identity (1,458 had piled up by
 * 2026-10-12). A real-auth account's rows are simply rewritten at its next
 * sign-in. Injected client, always supabaseAdmin.
 */
export async function revokeSessionAccess(
  client: SupabaseClient,
  userId: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  for (const table of ['user_profiles', 'user_roles'] as const) {
    const { error } = await client.from(table).delete().eq('user_id', userId);
    if (error) {
      console.error(`revoke-session-access: failed to clear ${table}:`, error);
      return { ok: false, error: 'Internal server error' };
    }
  }
  return { ok: true };
}

lib/services/stateLeadersService.ts:
import { supabase } from '@/lib/supabaseClient';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';
import { isValidEmail } from '@/lib/validation';

export interface StateLeader {
  id: string;
  state: string;
  leader: string;
  mobile: string | null;
  admin: string | null;
  email: string | null;
  pending_email: string | null;
  email_confirmed_at: string | null;
  mfa_enrolled_at: string | null;
  created_at: string;
}

/**
 * The admin column is meant to hold exactly 'AD', 'SR', or null — never free
 * text. This is the app-level backstop for that (see also the DB-level CHECK
 * constraint in scripts/add_state_leaders_admin_check_constraint.sql).
 *
 * Without this, the admin panel's own free-text field could recreate the #78
 * bug: a recruiter's name typed into this column instead of a real role code,
 * which isRecognizedAdminStatus() treats as "not an admin" but which still
 * doesn't mean what the column is supposed to mean. Reuses
 * isRecognizedAdminStatus() rather than re-checking `=== 'AD' || === 'SR'`
 * inline, per the project's rule against duplicating that logic.
 */
function assertValidAdminValue(admin: string | null): void {
  if (admin !== null && !isRecognizedAdminStatus(admin)) {
    throw new Error(`"${admin}" is not a valid admin role — must be AD, SR, or left blank`);
  }
}

function assertValidEmailValue(email: string | null): void {
  if (email !== null && !isValidEmail(email)) {
    throw new Error(`"${email}" is not a valid email address`);
  }
}

/**
 * Best-effort audit write to state_leader_email_changes — never allowed to
 * fail the admin's actual save (create/update already succeeded by the time
 * this runs). See scripts/create_state_leader_email_changes_table.sql.
 */
async function recordEmailChange(
  stateLeaderId: string,
  oldEmail: string | null,
  newEmail: string | null,
  source: 'self-serve' | 'admin',
): Promise<void> {
  const { error } = await supabase
    .from('state_leader_email_changes')
    .insert([{ state_leader_id: stateLeaderId, old_email: oldEmail, new_email: newEmail, source }]);
  if (error) console.warn('Failed to record email change:', error);
}

export async function getStateLeaders(filterState?: string): Promise<StateLeader[]> {
  let query = supabase
    .from('state_leaders')
    .select('*')
    .order('state', { ascending: true })
    .order('leader', { ascending: true });
  if (filterState) query = query.eq('state', filterState);
  const { data, error } = await query;
  if (error) throw error;
  return (data || []) as StateLeader[];
}

export async function createStateLeader(input: {
  state: string;
  leader: string;
  mobile: string | null;
  admin: string | null;
  email: string | null;
}): Promise<void> {
  assertValidAdminValue(input.admin);
  assertValidEmailValue(input.email);

  const { error } = await supabase.from('state_leaders').insert([input]);
  if (error) {
    if (error.code === '23505') throw new Error('This state-leader combination already exists');
    throw error;
  }

  // The id needed for the audit row is only knowable after the insert, so it's
  // looked up separately (by the state+leader uniqueness key that error.code
  // 23505 above already relies on) rather than chaining .select().single() onto
  // the insert itself — that would make an unrelated read-back failure (e.g. a
  // transient RLS/replica hiccup) surface as a false "creation failed" error
  // even though the leader row was already committed. This whole lookup is
  // best-effort: it must never affect whether createStateLeader itself succeeds.
  if (input.email) {
    try {
      const { data, error: lookupError } = await supabase
        .from('state_leaders')
        .select('id')
        .eq('state', input.state)
        .eq('leader', input.leader)
        .single();
      if (lookupError || !data) throw lookupError ?? new Error('Newly created leader row not found');
      await recordEmailChange((data as { id: string }).id, null, input.email, 'admin');
    } catch (lookupErr) {
      console.warn('Failed to record email change for new leader:', lookupErr);
    }
  }
}

/** Same address, ignoring case and surrounding spaces; two empties are the same. */
function isSameEmail(a: string | null, b: string | null): boolean {
  return (a ?? '').trim().toLowerCase() === (b ?? '').trim().toLowerCase();
}

export async function updateStateLeader(
  id: string,
  input: { state: string; leader: string; mobile: string | null; admin: string | null; email: string | null },
): Promise<void> {
  assertValidAdminValue(input.admin);
  assertValidEmailValue(input.email);

  const { data: existing, error: fetchError } = await supabase.from('state_leaders').select('email').eq('id', id).single();
  if (fetchError) console.warn('Failed to fetch existing email before update:', fetchError);

  const previousEmail = (existing as { email: string | null } | null)?.email ?? null;
  // When an admin changes or removes a leader's email, everything that
  // vouched for the *old* address must go with it: the confirmation, the tie
  // to that address's sign-in account (user_id — otherwise the previous
  // address's owner could still sign in as this leader by email), and the 2FA
  // enrolment that belongs to that account. The leader then confirms again
  // (or the new address is bound when they finish 2FA setup). Skipped when the
  // pre-fetch failed — we can't tell whether the email really changed, and
  // wiping a working sign-in on a guess would be worse.
  const emailChanged = !fetchError && !isSameEmail(previousEmail, input.email);
  const payload = emailChanged
    ? { ...input, email_confirmed_at: null, user_id: null, mfa_enrolled_at: null }
    : input;

  const { error } = await supabase.from('state_leaders').update(payload).eq('id', id);
  if (error) throw error;

  // Skip the audit comparison entirely when the pre-fetch itself failed —
  // defaulting to "no previous email" in that case would risk logging a false
  // change (e.g. reporting old_email: null when it was never actually null).
  if (!fetchError && previousEmail !== input.email) {
    await recordEmailChange(id, previousEmail, input.email, 'admin');
  }
}

export async function deleteStateLeader(id: string): Promise<void> {
  const { error } = await supabase.from('state_leaders').delete().eq('id', id);
  if (error) throw error;
}

lib/services/stateLocations.ts:
/**
 * The physical locations (`state_places.location`) available in each state —
 * what a Campaign Report's "Location" is chosen from. Several State Places
 * rows can share one location ("Perth CBD 1…4" are all "Perth CBD"), so this
 * is the distinct set, not the rows. Server-side: injected client, always
 * `supabaseAdmin`.
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { distinctLocations, locationOf, type PlaceRef } from '@/lib/campaignReportMatcher';
import { buildNewStatePlaceRow } from '@/lib/services/newStatePlace';

export interface StateLocation {
  state: string;
  location: string;
}

/** Distinct locations per state, sorted by state then name. */
export function toStateLocations(rows: PlaceRef[]): StateLocation[] {
  const byState = new Map<string, PlaceRef[]>();
  for (const r of rows) byState.set(r.state, [...(byState.get(r.state) ?? []), r]);
  return [...byState.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .flatMap(([state, list]) =>
      distinctLocations(list).sort((a, b) => a.localeCompare(b)).map((location) => ({ state, location })));
}

export async function getStateLocations(client: SupabaseClient): Promise<StateLocation[]> {
  const { data, error } = await client.from('state_places').select('state, place, location');
  if (error) throw error;
  return toStateLocations((data ?? []) as PlaceRef[]);
}

export type EnsureLocationResult =
  | { ok: true; location: string }
  | { ok: false; code: 'unknown_location'; error: string };

/**
 * Confirms `wanted` is a location in `state` (case-insensitively, returning
 * the stored spelling). When it isn't: with `addIfMissing` a new State Places
 * row is created for it (place and location both the new name, geocoded — see
 * newStatePlace.ts); without, it reports `unknown_location` so the caller can
 * ask first.
 */
export async function ensureStateLocation(
  client: SupabaseClient,
  state: string,
  wanted: string,
  addIfMissing: boolean,
): Promise<EnsureLocationResult> {
  const { data, error } = await client.from('state_places').select('state, place, location').eq('state', state);
  if (error) throw error;
  const rows = (data ?? []) as PlaceRef[];
  const existing = distinctLocations(rows).find((l) => l.toLowerCase() === wanted.trim().toLowerCase());
  if (existing) return { ok: true, location: existing };

  if (!addIfMissing) {
    return { ok: false, code: 'unknown_location', error: `"${wanted}" is not a location in State Places for ${state}` };
  }
  const name = wanted.trim();
  // A State Places row already *named* this but located elsewhere (place "Campbelltown", location "Sydney"):
  // adding another row would collide on state+place, and silently reusing it would pick the wrong location.
  const clash = rows.find((r) => r.place.trim().toLowerCase() === name.toLowerCase());
  if (clash) {
    return {
      ok: false, code: 'unknown_location',
      error: `"${name}" is already a place in ${state} whose location is "${locationOf(clash)}" — choose that location, or change it in State Places`,
    };
  }
  const { error: insertError } = await client.from('state_places').insert([await buildNewStatePlaceRow(state, name)]);
  if (insertError && insertError.code !== '23505') throw insertError;
  return { ok: true, location: name };
}

