import { supabase } from '@/lib/supabaseClient';
import type { StuckLeader } from '@/lib/services/stuckLeadersService';

/** Browser-side call to GET /api/admin/stuck-leaders. Throws with the server's message on failure. */
export async function fetchStuckLeaders(): Promise<StuckLeader[]> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error('Not signed in');

  const res = await fetch('/api/admin/stuck-leaders', { headers: { Authorization: `Bearer ${session.access_token}` } });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error((json as { error?: string }).error || 'Failed to load the list');
  return (json as { leaders: StuckLeader[] }).leaders;
}

lib/services/stuckLeadersService.ts:
import type { SupabaseClient } from '@supabase/supabase-js';
import { isRecognizedAdminStatus } from '@/lib/campaignFilter';

/**
 * "Who is stuck setting up email sign-in / 2FA, and where?" — for the admin
 * who has to phone them. Works purely from data we already hold: each
 * leader's rows in state_leaders plus the email-sign-in account Supabase made
 * for their address (when an email was last sent, and when a link was last
 * used). Per PERSON, not per row (one real person can have nine rows).
 *
 * Admins (AD/SR) are listed at every stage until they've enrolled, because
 * they cannot sign in as an admin without 2FA. Plain leaders are only listed
 * if they actually started and didn't finish — never for not having started,
 * since 2FA is optional for them.
 */

export interface LeaderRow {
  id: string;
  leader: string;
  state: string;
  admin: string | null;
  mobile: string | null;
  email: string | null;
  pending_email: string | null;
  email_confirmed_at: string | null;
  mfa_enrolled_at: string | null;
  user_id: string | null;
  last_sign_in_at: string | null;
}

export interface AuthEmailInfo {
  /** Latest time Supabase sent this address a sign-in/confirmation email. */
  emailSentAt: string | null;
  /** Latest time a link/code for this address was used. */
  lastUsedAt: string | null;
}

export type StuckStage =
  | 'not-started'
  | 'email-not-sent'
  | 'email-link-unused'
  | 'email-link-used'
  | '2fa-not-started'
  | '2fa-link-unused'
  | '2fa-started';

export interface StuckLeader {
  key: string;
  name: string;
  role: 'Admin' | 'State Reporter' | 'Leader';
  isAdmin: boolean;
  states: string[];
  mobile: string | null;
  email: string | null;
  stage: StuckStage;
  label: string;
  action: string;
  lastActivityAt: string | null;
}

const STAGES: Record<StuckStage, { label: string; action: string; adminOnly?: boolean }> = {
  'not-started': {
    label: 'Has not started — no email on file',
    action: 'Ask them to sign in. They will be guided through confirming an email address.',
    adminOnly: true,
  },
  'email-not-sent': {
    label: 'Entered an email but no message was sent',
    action: 'Ask them to try again from the sign-in page.',
  },
  'email-link-unused': {
    label: 'Confirmation email sent — link not used',
    action: 'Ask them to check their Junk/Spam folder, then tap CONFIRM NOW (or type the code from the email).',
  },
  'email-link-used': {
    label: 'Opened the confirmation link but did not finish',
    action: 'Ask them to try again and tap the blue button on the page that opens.',
  },
  '2fa-not-started': {
    label: 'Email confirmed — 2FA not started',
    action: 'Ask them to sign in and choose "Set up now". The guide is at /help/2fa.',
    adminOnly: true,
  },
  '2fa-link-unused': {
    label: '2FA setup email sent — link not used',
    action: 'Ask them to check Junk/Spam, then tap CONFIRM NOW in that email.',
  },
  '2fa-started': {
    label: 'Opened 2FA setup but did not finish',
    action: 'Usually the 6-digit code. Check: newest AFJ entry in their app, phone clock on automatic, old AFJ entries deleted.',
  },
};

const digits = (mobile: string | null) => (mobile ?? '').replace(/\D/g, '').replace(/^61/, '0');
const ms = (iso: string | null | undefined) => (iso ? new Date(iso).getTime() : null);
const latest = (...values: (string | null | undefined)[]): string | null => {
  const withValue = values.filter((v): v is string => !!v);
  if (withValue.length === 0) return null;
  return withValue.reduce((a, b) => (new Date(a) >= new Date(b) ? a : b));
};

/** Pure: which people are stuck, and at what stage. */
export function classifyStuckLeaders(
  rows: LeaderRow[],
  authByEmail: Map<string, AuthEmailInfo>,
): StuckLeader[] {
  const people = new Map<string, LeaderRow[]>();
  for (const row of rows) {
    const key = digits(row.mobile) || row.id;
    people.set(key, [...(people.get(key) ?? []), row]);
  }

  const out: StuckLeader[] = [];
  for (const [key, personRows] of people) {
    if (personRows.some((r) => r.mfa_enrolled_at)) continue; // done

    const adminRow = personRows.find((r) => r.admin === 'AD') ?? personRows.find((r) => r.admin === 'SR');
    const isAdmin = personRows.some((r) => isRecognizedAdminStatus(r.admin));
    const display = adminRow ?? [...personRows].sort((a, b) => (b.last_sign_in_at ?? '').localeCompare(a.last_sign_in_at ?? ''))[0];

    const confirmedAt = latest(...personRows.map((r) => r.email_confirmed_at));
    const email = personRows.find((r) => r.email)?.email ?? null;
    const pending = personRows.find((r) => r.pending_email)?.pending_email ?? null;
    const hasEmailOnFile = !!email; // confirmed by them, or entered by an admin (which counts as confirmed)
    // The address a still-unfinished email is going to / came from.
    const relevantAddress = (hasEmailOnFile ? email : pending)?.trim().toLowerCase() ?? null;
    const auth = relevantAddress ? authByEmail.get(relevantAddress) : undefined;
    const sentAt = auth?.emailSentAt ?? null;
    const usedAt = auth?.lastUsedAt ?? null;
    const used = !!sentAt && !!usedAt && (ms(usedAt) as number) >= (ms(sentAt) as number);

    let stage: StuckStage;
    if (!hasEmailOnFile && !pending) {
      stage = 'not-started';
    } else if (!hasEmailOnFile) {
      // proposed an address, never confirmed
      stage = !sentAt ? 'email-not-sent' : used ? 'email-link-used' : 'email-link-unused';
    } else {
      // email is in place; anything sent since confirmation is the 2FA setup email
      const setupEmailSent = !!sentAt && (!confirmedAt || (ms(sentAt) as number) > (ms(confirmedAt) as number));
      stage = !setupEmailSent ? '2fa-not-started' : used ? '2fa-started' : '2fa-link-unused';
    }

    if (STAGES[stage].adminOnly && !isAdmin) continue; // plain leaders: only if they actually tried

    out.push({
      key,
      name: display.leader.trim(),
      role: adminRow?.admin === 'AD' ? 'Admin' : adminRow?.admin === 'SR' ? 'State Reporter' : 'Leader',
      isAdmin,
      states: [...new Set(personRows.map((r) => r.state))].sort(),
      mobile: personRows.find((r) => r.mobile)?.mobile ?? null,
      email: email ?? pending,
      stage,
      label: STAGES[stage].label,
      action: STAGES[stage].action,
      lastActivityAt: latest(sentAt, usedAt, ...personRows.map((r) => r.last_sign_in_at)),
    });
  }

  // Admins first (they cannot sign in as admin until done), then the most recently active (warmest) first.
  return out.sort((a, b) => {
    if (a.isAdmin !== b.isAdmin) return a.isAdmin ? -1 : 1;
    return (b.lastActivityAt ?? '').localeCompare(a.lastActivityAt ?? '');
  });
}

/** Loads state_leaders and the email accounts, then classifies. Injected client (always supabaseAdmin). */
export async function getStuckLeaders(client: SupabaseClient): Promise<StuckLeader[]> {
  const { data: rows, error } = await client
    .from('state_leaders')
    .select('id, leader, state, admin, mobile, email, pending_email, email_confirmed_at, mfa_enrolled_at, user_id, last_sign_in_at');
  if (error) throw error;

  const authByEmail = new Map<string, AuthEmailInfo>();
  for (let page = 1; ; page++) {
    const { data, error: listError } = await client.auth.admin.listUsers({ page, perPage: 1000 });
    if (listError) throw listError;
    for (const user of data.users) {
      if (user.is_anonymous || !user.email) continue;
      authByEmail.set(user.email.toLowerCase(), {
        emailSentAt: latest(user.recovery_sent_at, user.confirmation_sent_at),
        lastUsedAt: user.last_sign_in_at ?? null,
      });
    }
    if (data.users.length < 1000) break;
  }

  return classifyStuckLeaders((rows ?? []) as LeaderRow[], authByEmail);
}

lib/services/trainingInterestService.ts:
/**
 * training_interest — members expressing interest in joining a training
 * session (a campaign with category BOTJ or TLT) via its per-campaign public
 * link (/public/training/[campaignId]). One row per (campaign, person). See
 * scripts/create_training_interest_table.sql.
 *
 * Note: these functions use the browser client, which is RLS-gated to the
 * campaign's owning/shared leader or an admin (see supabase/rls-policies.sql)
 * — so only the leader-facing /training-interest screens use it. The public
 * submission flow can't (anonymous visitors have no RLS access) — it inserts
 * via the service role directly in
 * app/api/public/training-interest/[campaignId]/route.ts instead.
 */
import { supabase } from '@/lib/supabaseClient';
import { fetchInterestCounts } from './interestCountsClient';
import type { Campaign } from '@/lib/types';
import { getCampaignsForUser, type CampaignsForUserParams } from './campaignService';

/**
 * Campaign category codes that represent a training session. Deliberately a
 * hardcoded allowlist rather than reading from the DB-driven
 * `campaign_categories` table (see /admin/campaign-categories): "is this
 * category a training" is a property of the code itself, not something an
 * admin currently has a way to flag per-category in that table. If a new
 * training-style category is introduced later, it needs adding here too —
 * consider adding an `is_training` boolean column to `campaign_categories`
 * instead if this list grows past BOTJ/TLT.
 */
export const TRAINING_CATEGORIES = ['BOTJ', 'TLT'] as const;
export type TrainingCategory = (typeof TRAINING_CATEGORIES)[number];

export function isTrainingCategory(category: string | null | undefined): boolean {
  return !!category && (TRAINING_CATEGORIES as readonly string[]).includes(category);
}

export interface TrainingInterest {
  id: string;
  campaign_id: string;
  name: string;
  mobile: string | null;
  email: string | null;
  contacted: boolean;
  contacted_at: string | null;
  created_at: string;
}

/**
 * Training campaigns (category BOTJ/TLT) visible to the current user —
 * reuses getCampaignsForUser's role-aware fetch (own + shared + admin) rather
 * than re-implementing that filtering here, then narrows to training
 * categories client-side.
 */
export async function getTrainingCampaigns(params: CampaignsForUserParams): Promise<Campaign[]> {
  const { campaigns } = await getCampaignsForUser(params);
  return campaigns.filter((c) => isTrainingCategory(c.category));
}

/** Count of training_interest rows per campaign id, for the given campaign ids. */
export async function getTrainingInterestCounts(campaignIds: string[]): Promise<Map<string, number>> {
  if (campaignIds.length === 0) return new Map();
  // Numbers only, via the server — the registrations themselves need a 2FA-level session
  // (lib/services/interestCountsService.ts).
  const { trainingInterest } = await fetchInterestCounts(campaignIds);
  return new Map(Object.entries(trainingInterest));
}

/** All interest registrations for one training campaign, newest first. */
export async function getTrainingInterestForCampaign(campaignId: string): Promise<TrainingInterest[]> {
  const { data, error } = await supabase
    .from('training_interest')
    .select('*')
    .eq('campaign_id', campaignId)
    .order('created_at', { ascending: false });
  if (error) throw error;
  return (data || []) as TrainingInterest[];
}

/**
 * Mark a registration as contacted (or un-contacted). `contacted_at` is set
 * to now when marking contacted, and cleared back to null when un-marking.
 * Returns the updated row's contacted_at so callers can update local state
 * from the authoritative persisted value rather than re-deriving their own
 * timestamp with a second `new Date().toISOString()` call.
 */
export async function setTrainingInterestContacted(id: string, contacted: boolean): Promise<{ contacted_at: string | null }> {
  const { data, error } = await supabase
    .from('training_interest')
    .update({ contacted, contacted_at: contacted ? new Date().toISOString() : null })
    .eq('id', id)
    .select('contacted_at')
    .single();
  if (error) throw error;
  return data as { contacted_at: string | null };
}

lib/services/userGuideClient.ts:
import { supabase } from '@/lib/supabaseClient';
import { USER_GUIDE_BUCKET, type UserGuideView } from '@/lib/services/userGuideService';

async function authHeader(): Promise<Record<string, string>> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error('Not signed in');
  return { Authorization: `Bearer ${session.access_token}` };
}

/** Browser-side call to GET /api/public/user-guide (no sign-in needed). Null when no guide has been uploaded yet. */
export async function fetchUserGuide(): Promise<UserGuideView | null> {
  const res = await fetch('/api/public/user-guide');
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error((json as { error?: string }).error || 'The guide could not be loaded');
  const { url, uploadedAt } = json as { url: string | null; uploadedAt?: string };
  return url && uploadedAt ? { url, uploadedAt } : null;
}

/**
 * Admin upload of a new guide: gets a one-time signed upload target from
 * POST /api/admin/user-guide/upload-url, then sends the file straight to
 * Storage. Throws with a readable message on failure.
 */
export async function uploadUserGuide(file: File): Promise<void> {
  const res = await fetch('/api/admin/user-guide/upload-url', { method: 'POST', headers: await authHeader() });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error((json as { error?: string }).error || 'Could not prepare the upload');
  const { path, token } = json as { path: string; token: string };

  const { error } = await supabase.storage
    .from(USER_GUIDE_BUCKET)
    .uploadToSignedUrl(path, token, file, { contentType: 'application/pdf' });
  if (error) throw new Error(`Upload failed: ${error.message}`);
}

lib/services/userGuideService.ts:
import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * The CAS User Guide PDF that leaders open from the "OPEN GUIDE" button.
 *
 * Kept in a **private** Supabase Storage bucket, so the PDF never sits at a
 * fixed public address; it's reached only through short-lived signed URLs
 * from GET /api/public/user-guide. That route needs no sign-in — the guide is
 * offered on the sign-in screen for new leaders, and Peter decided
 * (2026-10-15) that anyone may read it. An admin uploads through a one-time
 * signed upload URL from POST /api/admin/user-guide/upload-url — direct to
 * Storage, so a large PDF never hits Vercel's request-body limit.
 *
 * Each upload gets a new timestamped name and the newest file is the current
 * guide, so a replaced guide is never served from a stale CDN cache. Before
 * each new upload everything but the current guide is deleted, so at most
 * the current and previous versions exist at any time.
 *
 * Every function takes an injected client — always `supabaseAdmin` in
 * practice (the bucket has no RLS policies, so only the service role can
 * reach it).
 */

export const USER_GUIDE_BUCKET = 'user-guide';
export const USER_GUIDE_MAX_BYTES = 20 * 1024 * 1024;
/** Long enough that a guide page left open for an afternoon still opens. */
export const USER_GUIDE_URL_TTL_SECONDS = 4 * 60 * 60;

const GUIDE_NAME_PATTERN = /^guide-(\d+)\.pdf$/;

export interface UserGuideFile {
  path: string;
  uploadedAt: string;
}

export interface UserGuideView {
  url: string;
  uploadedAt: string;
}

/** Name for a newly uploaded guide; the timestamp both orders versions and busts caches. */
export function makeUserGuidePath(now: Date = new Date()): string {
  return `guide-${now.getTime()}.pdf`;
}

/** Newest first. Ignores anything in the bucket that isn't one of our guide files. */
async function listGuides(client: SupabaseClient): Promise<UserGuideFile[]> {
  const { data, error } = await client.storage.from(USER_GUIDE_BUCKET).list('', {
    limit: 100,
    sortBy: { column: 'name', order: 'desc' },
  });
  if (error) {
    // A bucket that hasn't been created yet just means no guide has been uploaded.
    if (/not found/i.test(error.message ?? '')) return [];
    throw new Error(`Could not list user guides: ${error.message ?? 'unknown error'}`);
  }
  return (data ?? [])
    .map((f) => GUIDE_NAME_PATTERN.exec(f.name))
    .filter((m): m is RegExpExecArray => m !== null)
    .map((m) => ({ path: m[0], uploadedMs: Number(m[1]) }))
    .sort((a, b) => b.uploadedMs - a.uploadedMs)
    .map(({ path, uploadedMs }) => ({ path, uploadedAt: new Date(uploadedMs).toISOString() }));
}

export async function getCurrentUserGuide(client: SupabaseClient): Promise<UserGuideFile | null> {
  return (await listGuides(client))[0] ?? null;
}

/** A signed URL for the current guide, or null when none has been uploaded yet. */
export async function getUserGuideView(client: SupabaseClient): Promise<UserGuideView | null> {
  const current = await getCurrentUserGuide(client);
  if (!current) return null;

  const { data, error } = await client.storage
    .from(USER_GUIDE_BUCKET)
    .createSignedUrl(current.path, USER_GUIDE_URL_TTL_SECONDS);
  if (error || !data?.signedUrl) {
    throw new Error(`Could not create a link to the user guide: ${error?.message ?? 'unknown error'}`);
  }
  return { url: data.signedUrl, uploadedAt: current.uploadedAt };
}

async function ensureBucket(client: SupabaseClient): Promise<void> {
  const { data } = await client.storage.getBucket(USER_GUIDE_BUCKET);
  if (data) return;
  const { error } = await client.storage.createBucket(USER_GUIDE_BUCKET, {
    public: false,
    fileSizeLimit: USER_GUIDE_MAX_BYTES,
    allowedMimeTypes: ['application/pdf'],
  });
  if (error && !/already exists/i.test(error.message ?? '')) {
    throw new Error(`Could not create the user guide bucket: ${error.message ?? 'unknown error'}`);
  }
}

/**
 * Prepares an admin upload: creates the bucket on first use, deletes every
 * guide except the current one, and returns a one-time signed upload target
 * for the new file. The new file becomes the current guide as soon as its
 * upload finishes.
 */
export async function createUserGuideUploadTarget(
  client: SupabaseClient,
  now: Date = new Date(),
): Promise<{ path: string; token: string }> {
  await ensureBucket(client);

  const stale = (await listGuides(client)).slice(1).map((g) => g.path);
  if (stale.length > 0) {
    const { error } = await client.storage.from(USER_GUIDE_BUCKET).remove(stale);
    // Leftovers only cost storage; never block the new upload over them.
    if (error) console.error('[userGuide] could not remove old guides:', error.message);
  }

  const path = makeUserGuidePath(now);
  const { data, error } = await client.storage.from(USER_GUIDE_BUCKET).createSignedUploadUrl(path);
  if (error || !data?.token) {
    throw new Error(`Could not prepare the upload: ${error?.message ?? 'unknown error'}`);
  }
  return { path, token: data.token };
}

/** "15 October 2026" — how the guide's upload date is shown to people. */
export function formatGuideDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-AU', { day: 'numeric', month: 'long', year: 'numeric' });
}

/**
 * Browser-side check before uploading — the bucket also refuses non-PDFs
 * and oversized files, but this gives a plain-English message first.
 * `header` is the file's first bytes (a real PDF starts with "%PDF-").
 */
export function validateUserGuideFile(
  file: { name: string; size: number; type: string },
  header: Uint8Array,
): string | null {
  const looksLikePdf = new TextDecoder().decode(header.slice(0, 5)) === '%PDF-';
  if (!looksLikePdf || (file.type && file.type !== 'application/pdf')) {
    return 'Please choose a PDF file.';
  }
  if (file.size > USER_GUIDE_MAX_BYTES) {
    return `That file is too large (${(file.size / 1024 / 1024).toFixed(1)} MB). The limit is ${USER_GUIDE_MAX_BYTES / 1024 / 1024} MB.`;
  }
  if (file.size === 0) return 'That file is empty.';
  return null;
}

lib/services/weeklyRefreshService.ts:
/**
 * Weekly Refresh Service
 *
 * Contains the core logic for generating the next week's campaigns from rules,
 * deduplicating against existing rows, and pruning old campaigns.
 *
 * Designed to be called from both:
 *   - The admin UI  (passes the anon Supabase client + the user's ID)
 *   - The Vercel Cron API route  (passes the service-role client + null userId)
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import { calculateCampaignDates, formatDateForDb } from '@/lib/campaignDates';
import type { CampaignRule } from '@/lib/types';
import { evaluateRules } from '@/lib/campaignRules';
import { getErrorMessage } from '@/lib/errorUtils';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface NewCampaignRow {
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
  mobile: string | null;
  category: string | null;
  user_id: string | null;
  team_size: null;
  tl_ok: boolean;
  source: string;
}

export interface WeeklyRefreshResult {
  /** Campaigns actually inserted this run. */
  created: number;
  /** Campaigns skipped because they already existed in the target week. */
  skipped: number;
  /** Old campaigns deleted (older than pastCampaignStart). */
  deleted: number;
  /** Audit log rows pruned (older than LOG_RETENTION_DAYS). */
  logsPruned: number;
  /** Start of the week that was targeted. */
  secondWeekStart: Date;
}

// ---------------------------------------------------------------------------
// Main function
// ---------------------------------------------------------------------------

/**
 * Runs the weekly campaign refresh.
 *
 * Steps:
 *  1. Evaluate active campaign rules for the second upcoming week, plus a one-off
 *     "catch-up" pass into the current week for any rule with no campaign already
 *     on the books (see below).
 *  2. Deduplicate against existing campaigns in that week.
 *  3. Insert new campaigns.
 *  4. Update biweekly rule reference_dates.
 *  5. Delete campaigns older than pastCampaignStart (always — even if nothing was inserted).
 *  6. Write an enriched row to weekly_refresh_log.
 *
 * @param client     Supabase client. Use service-role for cron, anon for manual.
 * @param userId     Authenticated user ID (manual runs) or null (automated cron).
 */
export async function runWeeklyRefresh(
  client: SupabaseClient,
  userId: string | null
): Promise<WeeklyRefreshResult> {
  const triggeredBy = userId ? 'manual' : 'auto';

  // -------------------------------------------------------------------------
  // Compute target date windows
  // -------------------------------------------------------------------------
  const { upcomingCampaignStart, secondWeekStart, pastCampaignStart } = calculateCampaignDates();

  const secondWeekEnd = new Date(secondWeekStart);
  secondWeekEnd.setDate(secondWeekEnd.getDate() + 6); // Mon – Sun

  // Catch-up window: the current week, up to (but not overlapping) secondWeekStart.
  // A rule normally gets exactly one shot at each week — evaluated once, when that
  // week is the "second week" (1-2 weeks out). A rule created *after* that shot for
  // the current week has already passed can never be revisited by the normal pass,
  // since secondWeekStart only advances forward. This window gives such rules one
  // catch-up evaluation into the current week.
  const catchUpEnd = new Date(secondWeekStart);
  catchUpEnd.setDate(catchUpEnd.getDate() - 1); // Sunday before secondWeekStart

  const secondWeekEndStr   = formatDateForDb(secondWeekEnd);
  const pastCampaignStartStr = formatDateForDb(pastCampaignStart);

  try {
    // -----------------------------------------------------------------------
    // Fetch states, active rules, and existing campaigns in target week
    // -----------------------------------------------------------------------
    const { data: stateRows, error: statesError } = await client
      .from('state_leaders')
      .select('state');
    if (statesError) throw statesError;
    const states = Array.from(
      new Set((stateRows || []).map((r: { state: string }) => r.state))
    );

    const { data: fetchedRules, error: rulesError } = await client
      .from('campaign_rules')
      .select('*')
      .eq('is_active', true)
      .order('priority', { ascending: false });
    if (rulesError) throw rulesError;
    const allRules = (fetchedRules || []) as CampaignRule[];

    const { data: existingRows, error: existingError } = await client
      .from('campaigns')
      .select('date, state, place, site, time, leader')
      .gte('date', pastCampaignStartStr)
      .lte('date', secondWeekEndStr);
    if (existingError) throw existingError;

    const existingSlotKeys = new Set(
      (existingRows || []).map(
        (c: { date: string; state: string; place: string; site: string; time: string; leader: string }) =>
          `${c.date}_${c.state}_${c.place}_${c.site}_${c.time}_${c.leader}`
      )
    );

    // -----------------------------------------------------------------------
    // Biweekly rules: backfill reference_date from the most recent campaign
    // -----------------------------------------------------------------------
    for (const rule of allRules) {
      if (rule.frequency_type === 'biweekly' && !rule.rule_config?.reference_date) {
        const { data: recent, error: recentError } = await client
          .from('campaigns')
          .select('date')
          .eq('state', rule.state)
          .eq('place', rule.place)
          .eq('site', rule.site)
          .eq('time', rule.time)
          .eq('leader', rule.leader)
          .order('date', { ascending: false })
          .limit(1);
        if (!recentError && recent?.length > 0) {
          rule.rule_config = rule.rule_config || {};
          rule.rule_config.reference_date = recent[0].date;
        }
      }
    }

    // -----------------------------------------------------------------------
    // Evaluate rules for all states
    // -----------------------------------------------------------------------
    const allNewCampaigns: NewCampaignRow[] = [];
    const rulesUsedInRefresh: CampaignRule[] = [];

    const toNewCampaignRow = (campaign: ReturnType<typeof evaluateRules>[number]): NewCampaignRow => ({
      date:      campaign.date,
      state:     campaign.state,
      place:     campaign.place,
      site:      campaign.site,
      time:      campaign.time,
      leader:    campaign.leader,
      mobile:    campaign.mobile,
      category:  campaign.category ?? 'TWOL',
      user_id:   userId,
      team_size: null as null,
      tl_ok:     false,
      source:    'RUL',
    });

    // Rules that get a catch-up evaluation this run — collected so they can be marked
    // as caught-up (see below) once the run's insert has actually succeeded.
    const rulesToMarkCaughtUp: CampaignRule[] = [];

    for (const state of states) {
      const stateRules = allRules.filter((r) => r.state === state);
      const ruleCampaigns = evaluateRules(stateRules, secondWeekStart, secondWeekEnd);
      allNewCampaigns.push(...ruleCampaigns.map(toNewCampaignRow));
      rulesUsedInRefresh.push(...stateRules);

      // Catch-up: a rule gets exactly one extra evaluation pass into the current week (a
      // range the normal pass above never covers), so a rule created after its first
      // occurrence's normal window has already gone by still gets that occurrence
      // generated. Eligibility is tracked with `catchup_evaluated_at` on the rule itself
      // (null = not yet evaluated) rather than by looking for a matching campaign row —
      // matching on campaign fields like `time` breaks the moment a rule's schedule is
      // edited after its first occurrence was generated (see #91), since already-generated
      // occurrences correctly keep their original values.
      const catchUpRules = stateRules.filter((r) => !r.catchup_evaluated_at);
      if (catchUpRules.length > 0) {
        const catchUpCampaigns = evaluateRules(catchUpRules, upcomingCampaignStart, catchUpEnd);
        allNewCampaigns.push(...catchUpCampaigns.map(toNewCampaignRow));
        rulesToMarkCaughtUp.push(...catchUpRules);
      }
    }

    // -----------------------------------------------------------------------
    // Deduplicate and insert
    // -----------------------------------------------------------------------
    const slotKey = (c: { date: string; state: string; place: string; site: string; time: string; leader: string }) =>
      `${c.date}_${c.state}_${c.place}_${c.site}_${c.time}_${c.leader}`;

    const toInsert    = allNewCampaigns.filter((c) => !existingSlotKeys.has(slotKey(c)));
    const skippedCount = allNewCampaigns.length - toInsert.length;

    let createdCount = 0;
    if (toInsert.length > 0) {
      const { error: insertError } = await client.from('campaigns').insert(toInsert);
      if (insertError) throw insertError;
      createdCount = toInsert.length;

      // Update biweekly reference_dates for rules that generated new campaigns
      for (const rule of rulesUsedInRefresh) {
        if (rule.frequency_type === 'biweekly') {
          const inserted = toInsert.filter(
            (c) =>
              c.state  === rule.state  &&
              c.place  === rule.place  &&
              c.site   === rule.site   &&
              c.time   === rule.time   &&
              c.leader === rule.leader
          );
          if (inserted.length > 0) {
            const newReferenceDate = inserted.map((c) => c.date).sort()[0];
            await client
              .from('campaign_rules')
              .update({ rule_config: { ...(rule.rule_config || {}), reference_date: newReferenceDate } })
              .eq('id', rule.id);
          }
        }
      }
    }

    // -----------------------------------------------------------------------
    // Mark catch-up-eligible rules as evaluated — placed after the insert above has
    // succeeded (or been skipped because there was nothing to insert) so a rule is never
    // marked "caught up" without its campaign actually landing. This is a one-off flip:
    // once set, the rule never gets a catch-up pass again, regardless of what happens to
    // the resulting campaign afterward (edited, deleted, etc.) — its future occurrences
    // are reliably covered by the normal secondWeek pass from here on.
    // -----------------------------------------------------------------------
    if (rulesToMarkCaughtUp.length > 0) {
      const { error: catchupMarkError } = await client
        .from('campaign_rules')
        .update({ catchup_evaluated_at: new Date().toISOString() })
        .in('id', rulesToMarkCaughtUp.map((r) => r.id));
      if (catchupMarkError) throw catchupMarkError;
    }

    // -----------------------------------------------------------------------
    // Always delete old campaigns (independent of whether anything was inserted)
    // -----------------------------------------------------------------------
    const { data: deletedRows, error: deleteError } = await client
      .from('campaigns')
      .delete()
      .lt('date', pastCampaignStartStr)
      .select();
    if (deleteError) throw deleteError;
    const deletedCount = deletedRows?.length ?? 0;

    // -----------------------------------------------------------------------
    // Prune audit log — rolling 90-day retention
    // -----------------------------------------------------------------------
    const LOG_RETENTION_DAYS = 90;
    const logCutoff = new Date();
    logCutoff.setDate(logCutoff.getDate() - LOG_RETENTION_DAYS);
    const { data: deletedLogs, error: logsDeleteError } = await client
      .from('campaign_changes_log')
      .delete()
      .lt('created_at', logCutoff.toISOString())
      .select('id');
    if (logsDeleteError) {
      // Non-fatal: log the error but don't fail the whole refresh
      console.error('[weeklyRefresh] log pruning error:', logsDeleteError);
    }
    const logsPrunedCount = deletedLogs?.length ?? 0;

    // -----------------------------------------------------------------------
    // Log success
    // -----------------------------------------------------------------------
    await client
      .from('weekly_refresh_log')
      .insert({
        completed_at:      new Date().toISOString(),
        created_by:        userId,
        triggered_by:      triggeredBy,
        campaigns_created: createdCount,
        campaigns_skipped: skippedCount,
        campaigns_deleted: deletedCount,
      })
      .then(({ error }) => {
        if (error) console.error('[weeklyRefresh] log insert error:', error);
      });

    return { created: createdCount, skipped: skippedCount, deleted: deletedCount, logsPruned: logsPrunedCount, secondWeekStart };

  } catch (err) {
    // Log the failure (best-effort — don't let a log failure mask the original error).
    // Supabase errors are plain objects, not Error instances (see #69) — getErrorMessage
    // extracts message/code/details/hint instead of falling back to a useless string.
    const message = getErrorMessage(err);
    await client
      .from('weekly_refresh_log')
      .insert({
        completed_at:  new Date().toISOString(),
        created_by:    userId,
        triggered_by:  triggeredBy,
        error_message: message,
      })
      .then(({ error }) => {
        if (error) console.error('[weeklyRefresh] error-log insert failed:', error);
      });
    throw err;
  }
}

lib/slideGenerator.ts:
/**
 * Slide Generator
 *
 * All JPEG slide canvas logic extracted from app/admin/generate-slides/page.tsx
 * into a parameter-driven function. Used by:
 *   - app/admin/generate-slides/page.tsx  (with optional custom start date)
 *   - app/app/page.tsx admin quick-action  (always uses upcomingCampaignStart)
 *
 * The optional `hideMobile` flag produces the "Leader Campaign Lists" variant:
 * identical output except the mobile number column is omitted and the freed
 * width is given to the place column so long place names (e.g. "Macquarie
 * University") are no longer truncated.
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import JSZip from 'jszip';
import {
  getSlideStateColor,
  formatSlideDateText,
  formatDownloadDate,
  STATE_CODES,
} from '@/lib/slideLayout';
import { formatCampaignTimeDisplay } from '@/lib/campaignUtils';
import { combinePlaceAndSite } from '@/lib/placeSite';
import { formatDateForDb, getFortnightDateRange, getDateRangeInclusive } from '@/lib/campaignDates';

// ---------------------------------------------------------------------------
// Canvas constants  (match generate-slides/page.tsx exactly)
// ---------------------------------------------------------------------------

const DPI                 = 300;
const SLIDE_WIDTH         = Math.floor(7.5 * DPI);  // 2250 px
const SLIDE_HEIGHT        = Math.floor(10  * DPI);  // 3000 px

const FONT_SIZES = { title: 72, colorKey: 54, date: 78, campaign: 84 } as const;

const PLACE_COLS         = 18;
const PLACE_COLS_LEADER  = 29; // wider place column when the mobile column is omitted
const TIME_COLS          = 9;
const LEADER_COLS        = 12;
const MOBILE_MAX_COLS    = 10;
const TIME_LEADER_GAP_LEADER = 4; // extra breathing room between the time and leader fields when the mobile column is omitted

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Exported so callers building a prefetched data source (e.g. a public API route) share the exact shape renderSlide expects. */
export interface SlideCampaign {
  id: string;
  date: string;
  state: string;
  place: string;
  site: string;
  time: string;
  leader: string;
  mobile: string | null;
  category: string | null;
}

export interface GenerateSlidesOptions {
  supabase: SupabaseClient;
  /** First date of the window to render. */
  startDate: Date;
  /**
   * Last date of the window to render, inclusive. When omitted, falls back
   * to the fixed two-week fortnight starting at `startDate`.
   */
  endDate?: Date;
  adminStatus?: string | null;
  userState?: string | null;
  /** Explicit state to filter to, chosen by a full admin. Overrides the SR role-based filter. */
  stateFilter?: string | null;
  /** Optional callback invoked with status messages as generation proceeds. */
  onProgress?: (msg: string) => void;
  /** When true, omits the mobile number column and widens the place column ("Leader Campaign Lists"). */
  hideMobile?: boolean;
}

/**
 * Where renderSlide gets its per-date data from. The authenticated flow
 * (generateAndDownloadSlides) backs this with live Supabase queries; the
 * public flow (generateAndDownloadSlidesFromData) backs it with a dataset
 * fetched up-front from a service-role API route, since anonymous visitors
 * have no RLS access to `campaigns` or `campaign_messages`. renderSlide
 * itself is identical either way — only the data source changes.
 */
interface SlideDataSource {
  getCampaigns(date: Date): Promise<SlideCampaign[]>;
  getMessage(date: Date): Promise<string | null>;
}

// ---------------------------------------------------------------------------
// Private helpers
// ---------------------------------------------------------------------------

function px(inches: number): number {
  return Math.floor(inches * DPI);
}

async function fetchCampaigns(
  client: SupabaseClient,
  date: Date,
  filterState: string | null,
): Promise<SlideCampaign[]> {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const dateStr = `${y}-${m}-${d}`;

  let q = client
    .from('campaigns')
    .select('*')
    .eq('date', dateStr)
    .order('state', { ascending: true })
    .order('place', { ascending: true })
    .order('time', { ascending: true });

  if (filterState) {
    q = q.eq('state', filterState);
  }
  const { data } = await q;
  return (data ?? []) as SlideCampaign[];
}

async function fetchMessage(
  client: SupabaseClient,
  date: Date,
): Promise<string | null> {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const { data } = await client
    .from('campaign_messages')
    .select('message')
    .eq('date', `${y}-${m}-${d}`)
    .single();
  return data?.message ?? null;
}

/** SlideDataSource backed by live, per-date Supabase queries — the existing authenticated behavior, unchanged. */
function supabaseSlideDataSource(client: SupabaseClient, filterState: string | null): SlideDataSource {
  return {
    getCampaigns: (date) => fetchCampaigns(client, date, filterState),
    getMessage: (date) => fetchMessage(client, date),
  };
}

function drawFestiveBanner(
  ctx: CanvasRenderingContext2D,
  date: Date,
  spaceEnd: number,
  width: number,
): number {
  if (!(date.getMonth() === 11 && date.getDate() === 31)) return 0;
  const text = 'Happy New Year!';
  const padding = px(0.08);
  ctx.font = `bold italic ${FONT_SIZES.date}px Arial`;
  const tw = ctx.measureText(text).width;
  const bw = tw + 2 * padding;
  const bh = FONT_SIZES.date + 2 * padding;
  const bx = (width - bw) / 2;
  const by = spaceEnd - bh;
  ctx.fillStyle = 'rgb(255, 165, 0)';
  ctx.fillRect(bx, by, bw, bh);
  ctx.fillStyle = 'rgb(0, 0, 0)';
  ctx.fillText(text, bx + padding, by + padding + FONT_SIZES.date * 0.8);
  return bh;
}

function drawMessageBanner(
  ctx: CanvasRenderingContext2D,
  message: string,
  spaceStart: number,
  width: number,
): number {
  const padding = px(0.1);
  const maxW = width - padding * 4;
  ctx.font = `bold italic ${FONT_SIZES.date}px Arial`;

  const words = message.split(' ');
  const lines: string[] = [];
  let line = '';
  for (const word of words) {
    const test = line ? `${line} ${word}` : word;
    if (ctx.measureText(test).width > maxW) {
      if (line) lines.push(line);
      line = word;
    } else {
      line = test;
    }
  }
  if (line) lines.push(line);

  const th = FONT_SIZES.date;
  const ls = th * 0.3;
  const totalH = lines.length * th + (lines.length - 1) * ls;
  const vp = padding * 1.5;
  const bh = totalH + 2 * vp;
  const bw = Math.max(...lines.map(l => ctx.measureText(l).width)) + 2 * padding;
  const bx = (width - bw) / 2;

  ctx.fillStyle = 'rgb(255, 165, 0)';
  ctx.fillRect(bx, spaceStart, bw, bh);
  ctx.fillStyle = 'rgb(0, 0, 0)';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  lines.forEach((l, i) => {
    ctx.fillText(l, width / 2, spaceStart + vp + i * (th + ls));
  });
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  return bh;
}

async function renderSlide(
  dataSource: SlideDataSource,
  startDateIndex: number,
  startCampaignIndex: number,
  dateHeadings: Date[],
  hideMobile: boolean,
): Promise<{ canvas: HTMLCanvasElement; nextDateIndex: number | null; nextCampaignIndex: number }> {
  const canvas = document.createElement('canvas');
  canvas.width  = SLIDE_WIDTH;
  canvas.height = SLIDE_HEIGHT;
  const ctx = canvas.getContext('2d')!;
  if (!ctx) throw new Error('Failed to get canvas context');

  // White background
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, SLIDE_WIDTH, SLIDE_HEIGHT);

  // Red title banner
  const bannerH = px(0.5);
  ctx.fillStyle = 'rgb(255, 0, 0)';
  ctx.fillRect(0, 0, SLIDE_WIDTH, bannerH);
  ctx.fillStyle = 'white';
  ctx.font = `bold ${FONT_SIZES.title}px Arial`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('A.F.J UPCOMING CAMPAIGNS', SLIDE_WIDTH / 2, bannerH / 2);

  // Colour key row
  ctx.font = `bold ${FONT_SIZES.colorKey}px Arial`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  const keyLabel = 'Colour Key:    ';
  let totalW = ctx.measureText(keyLabel).width;
  STATE_CODES.forEach((s, i) => {
    totalW += ctx.measureText(s).width;
    if (i < STATE_CODES.length - 1) totalW += ctx.measureText('   ').width;
  });
  let xPos = (SLIDE_WIDTH - totalW) / 2;
  const yKey = px(0.6) + px(0.1);
  ctx.fillStyle = 'rgb(130, 0, 0)';
  ctx.fillText(keyLabel, xPos, yKey);
  xPos += ctx.measureText(keyLabel).width;
  STATE_CODES.forEach((s, i) => {
    ctx.fillStyle = getSlideStateColor(s);
    ctx.fillText(s, xPos, yKey);
    xPos += ctx.measureText(s).width;
    if (i < STATE_CODES.length - 1) {
      ctx.fillStyle = 'rgb(0, 0, 0)';
      ctx.fillText('   ', xPos, yKey);
      xPos += ctx.measureText('   ').width;
    }
  });

  // Campaign entries
  const dateStartTop  = px(1.0);
  const dateLeft      = px(0.5);
  const dateHeight    = px(0.35);
  const lineSpacing   = px(0.3);
  const bottomMargin  = px(0.5);
  let currentY = dateStartTop;
  let previousWeek: number | null = startDateIndex > 0 ? (startDateIndex >= 7 ? 2 : 1) : null;
  let currentCampaignIndex = startCampaignIndex;

  for (let i = startDateIndex; i < dateHeadings.length; i++) {
    const date = dateHeadings[i];
    const week = i < 7 ? 1 : 2;
    const campaigns = await dataSource.getCampaigns(date);

    if (campaigns.length === 0) { previousWeek = week; currentCampaignIndex = 0; continue; }

    const toRender = campaigns.slice(currentCampaignIndex);
    if (toRender.length === 0)  { previousWeek = week; currentCampaignIndex = 0; continue; }

    const topMargin       = (previousWeek !== null || currentY > dateStartTop) ? px(0.1) : 0;
    const dateHeaderSpace = px(0.05);

    ctx.font = `bold ${FONT_SIZES.campaign}px "Courier New", monospace`;
    const campaignLineH = FONT_SIZES.campaign;
    const avail = SLIDE_HEIGHT - bottomMargin - currentY - topMargin - dateHeight - dateHeaderSpace;
    const maxFit = Math.max(0, Math.floor((avail + campaignLineH) / lineSpacing));
    const nFit   = Math.min(toRender.length, maxFit);

    if (nFit === 0) return { canvas, nextDateIndex: i, nextCampaignIndex: currentCampaignIndex };

    const finalCampaigns = toRender.slice(0, nFit);
    const willContinue   = nFit < toRender.length;

    // Date header (yellow background)
    currentY += topMargin;
    ctx.font = `italic ${FONT_SIZES.date}px Arial`;
    const dateText   = formatSlideDateText(date);
    const dtMetrics  = ctx.measureText(dateText);
    const dtH        = FONT_SIZES.date;
    const pad        = px(0.08);
    const ybW        = dtMetrics.width + 2 * pad;
    const ybH        = dtH + 2 * pad;
    const ybX        = dateLeft;
    const ybY        = currentY + (dateHeight - ybH) / 2;
    ctx.fillStyle = 'rgb(255, 255, 0)';
    ctx.fillRect(ybX, ybY, ybW, ybH);
    ctx.fillStyle = 'rgb(130, 0, 0)';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText(dateText, ybX + pad, ybY + pad);

    // Campaign lines (scaled to fill width edge-to-edge)
    const campaignY = currentY + dateHeight + dateHeaderSpace;
    ctx.font = `bold ${FONT_SIZES.campaign}px "Courier New", monospace`;
    const placeCols        = hideMobile ? PLACE_COLS_LEADER : PLACE_COLS;
    const oneCharW        = Math.round(ctx.measureText('M').width);
    const availW          = SLIDE_WIDTH - 2 * oneCharW;
    const totalCols       = hideMobile
      ? placeCols + 1 + TIME_COLS + TIME_LEADER_GAP_LEADER + LEADER_COLS
      : placeCols + 1 + TIME_COLS + 1 + LEADER_COLS + 1 + MOBILE_MAX_COLS;
    const naturalW        = ctx.measureText('M'.repeat(totalCols)).width;
    const scaleX          = availW / naturalW;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';

    finalCampaigns.forEach((c, j) => {
      let place = combinePlaceAndSite(c.place, c.site);
      const cat = c.category ?? 'TWOL';
      if (cat !== 'TWOL') place = `${place} ${cat}`;
      if (place.length > placeCols) place = place.substring(0, placeCols);

      const time   = formatCampaignTimeDisplay(c.time);
      const leader = c.leader.length > LEADER_COLS ? c.leader.substring(0, LEADER_COLS) : c.leader;

      const text = hideMobile
        ? `${place.padEnd(placeCols)} ${time.padStart(TIME_COLS)}${' '.repeat(TIME_LEADER_GAP_LEADER)}${leader.padEnd(LEADER_COLS)}`
        : `${place.padEnd(placeCols)} ${time.padStart(TIME_COLS)} ${leader.padEnd(LEADER_COLS)} ${(c.mobile ?? '').replace(/\s/g, '')}`;
      const color = getSlideStateColor(c.state);
      ctx.save();
      ctx.translate(oneCharW, campaignY + j * lineSpacing);
      ctx.scale(scaleX, 1);
      ctx.strokeStyle = color;
      ctx.lineWidth = 3;
      ctx.lineJoin = 'round';
      ctx.strokeText(text, 0, 0);
      ctx.fillStyle = color;
      ctx.fillText(text, 0, 0);
      ctx.restore();
    });

    const campaignsH = finalCampaigns.length * campaignLineH
      + (finalCampaigns.length - 1) * (lineSpacing - campaignLineH);
    currentY += dateHeight + dateHeaderSpace + campaignsH + px(0.05);

    const finishingDate = currentCampaignIndex + nFit >= campaigns.length;
    if (finishingDate) {
      currentY += drawFestiveBanner(ctx, date, currentY + px(0.2), SLIDE_WIDTH);

      const msg = await dataSource.getMessage(date);
      if (msg) {
        currentY += px(0.05) + drawMessageBanner(ctx, msg, currentY + px(0.05), SLIDE_WIDTH);
      }

      if (i === 6 && week === 1) {
        ctx.font = `bold ${FONT_SIZES.colorKey}px Arial`;
        ctx.fillStyle = 'rgb(255, 0, 0)';
        ctx.textAlign = 'center';
        ctx.fillText('*'.repeat(50), SLIDE_WIDTH / 2, currentY + px(0.05));
        currentY += px(0.4);
      }
    }

    if (willContinue) {
      return { canvas, nextDateIndex: i, nextCampaignIndex: currentCampaignIndex + nFit };
    }
    previousWeek = week;
    currentCampaignIndex = 0;
  }

  return { canvas, nextDateIndex: null, nextCampaignIndex: 0 };
}

// ---------------------------------------------------------------------------
// Shared orchestration — rendering a full slide deck and zipping it up.
// Used by both the authenticated and public entry points below.
// ---------------------------------------------------------------------------

/** Renders slides until the data source is exhausted (or the 20-slide safety cap is hit). */
async function buildSlideBlobs(
  dataSource: SlideDataSource,
  dateHeadings: Date[],
  hideMobile: boolean,
  onProgress?: (msg: string) => void,
): Promise<Blob[]> {
  const slides: Blob[] = [];
  let slideNum = 1;
  let dateIdx  = 0;
  let campIdx  = 0;

  while (slideNum <= 20) {
    onProgress?.(`Generating slide ${slideNum}…`);
    const result = await renderSlide(dataSource, dateIdx, campIdx, dateHeadings, hideMobile);

    const blob = await new Promise<Blob>((resolve, reject) => {
      result.canvas.toBlob(
        b => (b ? resolve(b) : reject(new Error('Failed to create blob'))),
        'image/jpeg',
        0.95,
      );
    });
    slides.push(blob);

    if (result.nextDateIndex === null) break;
    dateIdx = result.nextDateIndex;
    campIdx = result.nextCampaignIndex;
    slideNum++;
  }

  return slides;
}

/** Packages rendered slides into a ZIP and triggers a browser download. */
async function zipAndDownloadSlides(
  slides: Blob[],
  filename: string,
  onProgress?: (msg: string) => void,
): Promise<void> {
  onProgress?.(`Creating ZIP with ${slides.length} slide(s)…`);

  const zip = new JSZip();
  for (let i = 0; i < slides.length; i++) {
    zip.file(`slide_${i + 1}.jpg`, await slides[i].arrayBuffer());
  }

  const zipBlob = await zip.generateAsync({ type: 'blob' });
  const url  = URL.createObjectURL(zipBlob);
  const link = document.createElement('a');
  link.href     = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);

  onProgress?.(`Done — ${slides.length} slide(s) downloaded.`);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Generates JPEG slides for the two-week window starting at `startDate`,
 * packages them into a ZIP, and triggers a browser download. Fetches its
 * own data live via the (authenticated, RLS-scoped) Supabase client.
 */
export async function generateAndDownloadSlides(options: GenerateSlidesOptions): Promise<void> {
  const { supabase: client, startDate, endDate, adminStatus, userState, stateFilter, onProgress, hideMobile = false } = options;

  const explicitState = stateFilter && stateFilter.trim() ? stateFilter.toUpperCase().trim() : null;
  const roleState = adminStatus === 'SR' && userState ? userState.toUpperCase().trim() : null;
  const filterState = explicitState || roleState;

  const dateHeadings = endDate ? getDateRangeInclusive(startDate, endDate) : getFortnightDateRange(startDate);
  const dataSource = supabaseSlideDataSource(client, filterState);
  const slides = await buildSlideBlobs(dataSource, dateHeadings, hideMobile, onProgress);

  if (slides.length === 0) {
    throw new Error('No slides generated. Check that campaigns exist in the database.');
  }

  const listLabel = hideMobile ? 'Leader_Campaigns' : 'All_Campaigns';
  const filename = `${formatDownloadDate(new Date())}_${listLabel}${explicitState ? `_${explicitState}` : ''}.zip`;
  await zipAndDownloadSlides(slides, filename, onProgress);
}

/** One day's worth of prefetched data for generateAndDownloadSlidesFromData. */
export interface PublicSlideDay {
  /** YYYY-MM-DD */
  date: string;
  campaigns: SlideCampaign[];
  message: string | null;
}

/**
 * Same output as generateAndDownloadSlides(hideMobile: true, all states),
 * but from a dataset fetched up-front (e.g. by a public API route) instead
 * of live Supabase queries — for use on public, unauthenticated pages where
 * there is no RLS-scoped client available. Always hides mobile numbers,
 * matching the "Leader Campaign Lists" output this mirrors.
 */
export async function generateAndDownloadSlidesFromData(
  days: PublicSlideDay[],
  onProgress?: (msg: string) => void,
): Promise<void> {
  const dateHeadings = days.map((d) => {
    const [y, m, dd] = d.date.split('-').map(Number);
    return new Date(y, m - 1, dd);
  });
  const campaignsByDate = new Map(days.map((d) => [d.date, d.campaigns]));
  const messageByDate = new Map(days.map((d) => [d.date, d.message]));

  const dataSource: SlideDataSource = {
    getCampaigns: async (date) => campaignsByDate.get(formatDateForDb(date)) ?? [],
    getMessage: async (date) => messageByDate.get(formatDateForDb(date)) ?? null,
  };

  const slides = await buildSlideBlobs(dataSource, dateHeadings, /* hideMobile */ true, onProgress);

  if (slides.length === 0) {
    throw new Error('No slides generated. Check that campaigns exist in the database.');
  }

  const filename = `${formatDownloadDate(new Date())}_Leader_Campaigns.zip`;
  await zipAndDownloadSlides(slides, filename, onProgress);
}

lib/slideLayout.ts:
/**
 * Shared constants and helpers for campaign slide layout (JPEG slides and HTML list).
 * Keeps slide-style state colors (RGB) and formatting in one place.
 */

export const SLIDE_STATE_COLORS: Record<string, string> = {
  ACT: 'rgb(0, 176, 240)',
  NSW: 'rgb(0, 0, 0)',
  NT: 'rgb(0, 46, 138)',
  QLD: 'rgb(255, 0, 0)',
  SA: 'rgb(0, 176, 80)',
  TAS: 'rgb(0, 0, 255)',
  VIC: 'rgb(234, 107, 20)',
  WA: 'rgb(204, 0, 255)',
};

export const STATE_CODES = ['ACT', 'NSW', 'NT', 'QLD', 'SA', 'TAS', 'VIC', 'WA'];

export const DAY_NAMES = [
  'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday',
];
export const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

export function getSlideStateColor(state: string): string {
  const upper = state.toUpperCase();
  return SLIDE_STATE_COLORS[upper] ?? 'rgb(0, 0, 0)';
}

/**
 * Same per-state colors as the campaign results slides, lightened into a
 * tint suitable as a background (the colors above are text-color-
 * saturated, not meant to be used at full strength behind content).
 * Shared by any screen that shades a row/column by state — originally
 * written for the registry portal's (now-retired) Recent Registrations
 * table, kept in use by its Manage console (app/registry/manage/page.tsx),
 * which also passes a higher `alpha` to highlight whichever grid cell's
 * records are currently shown below it.
 */
export function getSlideStateShade(state: string | null, alpha = 0.14): string {
  if (!state) return 'transparent';
  const rgb = getSlideStateColor(state).match(/\d+/g);
  if (!rgb) return 'transparent';
  const [r, g, b] = rgb;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

export function getOrdinalSuffix(day: number): string {
  if (day >= 11 && day <= 13) return 'th';
  const last = day % 10;
  switch (last) {
    case 1: return 'st';
    case 2: return 'nd';
    case 3: return 'rd';
    default: return 'th';
  }
}

export function formatSlideDateText(date: Date): string {
  const jsDay = date.getDay();
  const dayIndex = jsDay === 0 ? 6 : jsDay - 1;
  const dayName = DAY_NAMES[dayIndex];
  const dayNum = date.getDate();
  const ordinal = getOrdinalSuffix(dayNum);
  const monthName = MONTH_NAMES[date.getMonth()];
  return `${dayName} ${dayNum}${ordinal} ${monthName}`;
}

/**
 * Format a date as the standard download-filename prefix: e.g. "Wed27May26".
 * Used by all three generators so filenames are consistent.
 */
export function formatDownloadDate(date: Date): string {
  const dayName = date.toLocaleDateString('en-AU', { weekday: 'short' }); // "Wed"
  const day     = date.getDate();                                          // 27
  const month   = date.toLocaleString('en-AU', { month: 'short' });       // "May"
  const year    = String(date.getFullYear()).slice(2);                     // "26"
  return `${dayName}${day}${month}${year}`;
}

export function getSlideDateHeadings(customStartDate?: string): Date[] {
  const today = new Date();
  const currentWeekday = today.getDay();
  const pythonWeekday = currentWeekday === 0 ? 6 : currentWeekday - 1;

  let startDate: Date;
  if (customStartDate) {
    const [y, m, d] = customStartDate.split('-').map(Number);
    startDate = new Date(y, m - 1, d);
    startDate.setHours(0, 0, 0, 0);
  } else {
    if (pythonWeekday <= 2) {
      startDate = new Date(today);
      startDate.setDate(startDate.getDate() - pythonWeekday);
    } else {
      startDate = new Date(today);
      startDate.setDate(startDate.getDate() + (7 - pythonWeekday));
    }
  }

  const dates: Date[] = [];
  for (let i = 0; i < 14; i++) {
    const d = new Date(startDate);
    d.setDate(d.getDate() + i);
    dates.push(d);
  }
  return dates;
}

lib/stateBounds.ts:
/**
 * Rough bounding boxes for each Australian state/territory, used to reject a
 * geocoding result that landed in the wrong state (Nominatim happily returns
 * a same-named suburb elsewhere, e.g. Brisbane's "Brighton" for a Victorian
 * place). Each box is a simple rectangle, so it catches a result hundreds of
 * kilometres away in another state but NOT one just across a shared border
 * (the boxes overlap there — Canberra falls inside Victoria's); it is a
 * sanity check, not a boundary test.
 */
const BOUNDS: Record<string, { south: number; north: number; west: number; east: number }> = {
  NSW: { south: -37.6, north: -28.1, west: 140.9, east: 153.8 },
  VIC: { south: -39.3, north: -33.9, west: 140.9, east: 150.1 },
  QLD: { south: -29.2, north: -9.0, west: 137.9, east: 153.8 },
  SA: { south: -38.2, north: -25.9, west: 129.0, east: 141.1 },
  WA: { south: -35.2, north: -13.6, west: 112.8, east: 129.1 },
  TAS: { south: -43.8, north: -39.4, west: 143.7, east: 148.7 },
  NT: { south: -26.1, north: -10.9, west: 128.9, east: 138.1 },
  ACT: { south: -36.0, north: -35.1, west: 148.7, east: 149.5 },
};

/** True when the point lies inside the state's box; true for a state we have no box for, so unknown codes never reject. */
export function isWithinState(latitude: number, longitude: number, state: string): boolean {
  const b = BOUNDS[state.toUpperCase()];
  if (!b) return true;
  return latitude >= b.south && latitude <= b.north && longitude >= b.west && longitude <= b.east;
}

