import { describe, it, expect } from 'vitest';
import { matchRoute, routeFromFilePath } from '../routeMatch';
import type { RouteEntry } from '../types';

const page = (pattern: string): RouteEntry => ({ pattern, kind: 'page', file: `app${pattern}/page.tsx`, layouts: [], methods: [] });

describe('routeFromFilePath', () => {
  it.each([
    ['app/page.tsx', '/'],
    ['app/admin/state-leaders/page.tsx', '/admin/state-leaders'],
    ['app/(marketing)/about/page.tsx', '/about'],
    ['app/training-interest/[campaignId]/page.tsx', '/training-interest/[campaignId]'],
    ['app/api/admin/x/route.ts', '/api/admin/x'],
  ])('%s → %s', (file, route) => expect(routeFromFilePath(file)).toBe(route));

  it('returns null for non-route files', () => {
    expect(routeFromFilePath('app/admin/components/Card.tsx')).toBeNull();
    expect(routeFromFilePath('lib/a.ts')).toBeNull();
  });
});

describe('matchRoute', () => {
  const routes = [page('/'), page('/admin'), page('/admin/new'), page('/admin/[id]'), page('/docs/[...slug]'), page('/training-interest/[campaignId]')];

  it('matches the root and static pages', () => {
    expect(matchRoute('/', routes)?.pattern).toBe('/');
    expect(matchRoute('/admin', routes)?.pattern).toBe('/admin');
    expect(matchRoute('/admin/', routes)?.pattern).toBe('/admin');
  });

  it('prefers a static segment over a dynamic one', () => {
    expect(matchRoute('/admin/new', routes)?.pattern).toBe('/admin/new');
    expect(matchRoute('/admin/42', routes)?.pattern).toBe('/admin/[id]');
  });

  it('matches dynamic and catch-all segments, ignoring query and hash', () => {
    expect(matchRoute('/training-interest/abc?x=1#y', routes)?.pattern).toBe('/training-interest/[campaignId]');
    expect(matchRoute('/docs/a/b/c', routes)?.pattern).toBe('/docs/[...slug]');
    expect(matchRoute('/docs', routes)).toBeNull();
  });

  it('returns null for an unknown path or one with extra segments', () => {
    expect(matchRoute('/nowhere', routes)).toBeNull();
    expect(matchRoute('/admin/1/2', routes)).toBeNull();
  });

  it('only matches the requested kind', () => {
    const api: RouteEntry = { pattern: '/api/x', kind: 'api', file: 'app/api/x/route.ts', layouts: [], methods: ['GET'] };
    expect(matchRoute('/api/x', [api])).toBeNull();
    expect(matchRoute('/api/x', [api], 'api')).toBe(api);
  });
});

lib/techInsights/__tests__/tagsMatchSour:
/**
 * A `data-ti="<path>"` tag is the link between a component on screen and the
 * Tech Insights manifest, so it must name the very file it is written in —
 * a copy-pasted or stale value would send a developer to the wrong code.
 */
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(__dirname, '../../..');
const DIRS = ['app', 'components', 'contexts', 'lib'];
const TAG = /data-ti="([^"<>{}]+\.tsx?)"/g;

function walk(dir: string): string[] {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) return e.name === 'node_modules' || e.name === '__tests__' ? [] : walk(full);
    return /\.tsx?$/.test(e.name) ? [full] : [];
  });
}

const tagged = DIRS.flatMap((d) => walk(path.join(ROOT, d))).flatMap((full) => {
  const rel = path.relative(ROOT, full).split(path.sep).join('/');
  const values = [...fs.readFileSync(full, 'utf8').matchAll(TAG)].map((m) => m[1]);
  return values.length > 0 ? [{ rel, values }] : [];
});

describe('data-ti tags', () => {
  it('exist (the scan found tagged components)', () => {
    expect(tagged.length).toBeGreaterThan(30);
  });

  it.each(tagged.map((t) => [t.rel, t.values] as const))('%s tags only itself', (rel, values) => {
    expect(new Set(values)).toEqual(new Set([rel]));
  });

  it('every tag points at a real file', () => {
    for (const { values } of tagged) for (const v of values) expect(fs.existsSync(path.join(ROOT, v))).toBe(true);
  });
});

lib/techInsights/buildManifest.ts:
/**
 * Tech Insights — pure manifest builder (no filesystem access, so it is fully
 * unit-testable). scripts/build-tech-insights.ts reads the repo, feeds the
 * text in here and writes the result out. Uses the TypeScript parser only
 * (no type-checking program), so it takes a couple of seconds for the whole app.
 *
 * Static analysis has limits: dynamically computed imports, `.from(variable)`
 * and non-literal '/api/…' strings are invisible to it. Those are simply
 * absent from the result rather than guessed.
 */
import ts from 'typescript';
import { matchRoute, routeFromFilePath } from './routeMatch';
import type { ExportInfo, FileEntry, FileKind, RouteEntry, TechInsightsManifest } from './types';

export interface SourceInput { path: string; text: string }

export interface BuildInput {
  /** Every .ts/.tsx/.css file to analyse, repo-relative with forward slashes. */
  files: SourceInput[];
  /** Files under public/, repo-relative (e.g. 'public/icons/a.png'). */
  publicAssets: string[];
  generatedAt: string;
  commit: string | null;
}

const HTTP_METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']);
const RESOLVE_EXTENSIONS = ['', '.ts', '.tsx', '.js', '.jsx', '.json', '/index.ts', '/index.tsx'];
const ASSET_LITERAL = /^\/[\w\-./]+\.(png|jpe?g|svg|ico|webp|gif|woff2?|pdf|json|webmanifest)$/i;
const MAX_DESCRIPTION_LENGTH = 800;

export function classifyFile(path: string): FileKind {
  if (/(^|\/)__tests__\//.test(path) || /\.test\.tsx?$/.test(path)) return 'test';
  if (path.endsWith('.css')) return 'style';
  if (path === 'middleware.ts' || path === 'proxy.ts') return 'middleware';
  if (path.startsWith('app/')) {
    const base = path.slice(path.lastIndexOf('/') + 1);
    if (/^page\.tsx?$/.test(base)) return 'page';
    if (/^layout\.tsx?$/.test(base)) return 'layout';
    if (/^route\.ts$/.test(base)) return 'api-route';
    return 'component';
  }
  if (path.startsWith('components/')) return 'component';
  if (path.startsWith('lib/services/')) return 'service';
  if (path.startsWith('contexts/')) return 'context';
  if (path.startsWith('lib/')) return 'lib';
  return 'other';
}

function dirname(path: string): string {
  const i = path.lastIndexOf('/');
  return i === -1 ? '' : path.slice(0, i);
}

/** Resolves './x', '../x' and '@/x' to a known repo path, or null (a package or unknown). */
export function resolveImport(from: string, specifier: string, known: ReadonlySet<string>): string | null {
  let base: string;
  if (specifier.startsWith('@/')) base = specifier.slice(2);
  else if (specifier.startsWith('.')) {
    const parts = dirname(from).split('/').filter(Boolean);
    for (const seg of specifier.split('/')) {
      if (seg === '.' || seg === '') continue;
      if (seg === '..') parts.pop();
      else parts.push(seg);
    }
    base = parts.join('/');
  } else return null;
  for (const ext of RESOLVE_EXTENSIONS) {
    if (known.has(base + ext)) return base + ext;
  }
  return null;
}

function packageName(specifier: string): string {
  const parts = specifier.split('/');
  return specifier.startsWith('@') ? parts.slice(0, 2).join('/') : parts[0];
}

function cleanComment(raw: string): string {
  const text = raw
    .replace(/^\/\*+/, '').replace(/\*+\/$/, '')
    .split('\n')
    .map((l) => l.trim().replace(/^\/\/+\s?/, '').replace(/^\*\s?/, ''))
    .join('\n')
    .trim();
  return text.length > MAX_DESCRIPTION_LENGTH ? `${text.slice(0, MAX_DESCRIPTION_LENGTH)}…` : text;
}

function lineOf(sf: ts.SourceFile, pos: number): number {
  return sf.getLineAndCharacterOfPosition(pos).line + 1;
}

function exportKind(node: ts.Node): ExportInfo['kind'] {
  if (ts.isFunctionDeclaration(node)) return 'function';
  if (ts.isClassDeclaration(node)) return 'class';
  if (ts.isInterfaceDeclaration(node)) return 'interface';
  if (ts.isTypeAliasDeclaration(node)) return 'type';
  if (ts.isEnumDeclaration(node)) return 'enum';
  return 'other';
}

function hasModifier(node: ts.Node, kind: ts.SyntaxKind): boolean {
  return ts.canHaveModifiers(node) && (ts.getModifiers(node) ?? []).some((m) => m.kind === kind);
}

function stringArg(call: ts.CallExpression): string | null {
  const arg = call.arguments[0];
  return arg && (ts.isStringLiteral(arg) || ts.isNoSubstitutionTemplateLiteral(arg)) ? arg.text : null;
}

/** Text of a string/template literal with each `${…}` replaced by 'x', or null for any other node. */
function literalText(node: ts.Node): string | null {
  if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return node.text;
  if (ts.isTemplateExpression(node)) {
    return node.head.text + node.templateSpans.map((s) => `x${s.literal.text}`).join('');
  }
  return null;
}

interface RawAnalysis {
  entry: FileEntry;
  apiPaths: string[];
}

function analyse(file: SourceInput, known: ReadonlySet<string>, publicAssets: ReadonlySet<string>): RawAnalysis {
  const kind = classifyFile(file.path);
  const entry: FileEntry = {
    path: file.path, kind, lines: file.text.split('\n').length, client: false, description: null,
    exports: [], imports: [], importedBy: [], tests: [], packages: [], tables: [], rpcs: [],
    apiRoutes: [], apiUnresolved: [], assets: [],
  };
  const apiPaths: string[] = [];
  if (kind === 'style') return { entry, apiPaths };

  const sf = ts.createSourceFile(file.path, file.text, ts.ScriptTarget.Latest, true,
    file.path.endsWith('x') ? ts.ScriptKind.TSX : ts.ScriptKind.TS);

  const imports = new Set<string>();
  const packages = new Set<string>();
  const assets = new Set<string>();
  const tables = new Set<string>();
  const rpcs = new Set<string>();

  const addSpecifier = (spec: string) => {
    const resolved = resolveImport(file.path, spec, known);
    if (!resolved) {
      if (!spec.startsWith('.') && !spec.startsWith('@/')) packages.add(packageName(spec));
      return;
    }
    if (classifyFile(resolved) === 'style') assets.add(resolved);
    else imports.add(resolved);
  };

  // Top-level pass: directives, description, imports/exports with line ranges.
  let firstReal: ts.Statement | null = null;
  for (const stmt of sf.statements) {
    if (ts.isExpressionStatement(stmt) && ts.isStringLiteral(stmt.expression)) {
      if (stmt.expression.text === 'use client') entry.client = true;
      continue;
    }
    if (!firstReal) firstReal = stmt;

    if (ts.isImportDeclaration(stmt) && ts.isStringLiteral(stmt.moduleSpecifier)) {
      addSpecifier(stmt.moduleSpecifier.text);
      continue;
    }
    if (ts.isExportDeclaration(stmt)) {
      if (stmt.moduleSpecifier && ts.isStringLiteral(stmt.moduleSpecifier)) addSpecifier(stmt.moduleSpecifier.text);
      continue;
    }
    if (ts.isExportAssignment(stmt)) {
      entry.exports.push({ name: 'default', kind: 'default', startLine: lineOf(sf, stmt.getStart(sf)), endLine: lineOf(sf, stmt.getEnd()) });
      continue;
    }
    if (!hasModifier(stmt, ts.SyntaxKind.ExportKeyword)) continue;
    const isDefault = hasModifier(stmt, ts.SyntaxKind.DefaultKeyword);
    const startLine = lineOf(sf, stmt.getStart(sf));
    const endLine = lineOf(sf, stmt.getEnd());
    if (ts.isVariableStatement(stmt)) {
      for (const decl of stmt.declarationList.declarations) {
        if (ts.isIdentifier(decl.name)) entry.exports.push({ name: decl.name.text, kind: 'const', startLine, endLine });
      }
    } else {
      const named = (stmt as ts.Node & { name?: ts.Identifier }).name?.text;
      entry.exports.push({ name: isDefault ? (named ? `default (${named})` : 'default') : (named ?? 'unnamed'), kind: isDefault ? 'default' : exportKind(stmt), startLine, endLine });
    }
  }
  if (firstReal) {
    const ranges = ts.getLeadingCommentRanges(file.text, firstReal.getFullStart());
    if (ranges && ranges.length > 0) {
      // The comment nearest the first statement is the file's own description.
      const nearest = ranges[ranges.length - 1];
      const text = cleanComment(file.text.slice(nearest.pos, nearest.end));
      entry.description = text || null;
    }
  }

  // Whole-tree pass: dynamic imports, Supabase calls, '/api/…' and asset literals.
  const visit = (node: ts.Node) => {
    if (ts.isCallExpression(node)) {
      if (node.expression.kind === ts.SyntaxKind.ImportKeyword) {
        const spec = stringArg(node);
        if (spec) addSpecifier(spec);
      } else if (ts.isPropertyAccessExpression(node.expression)) {
        const method = node.expression.name.text;
        const target = stringArg(node);
        if (target && (method === 'from' || method === 'rpc')) {
          const receiver = node.expression.expression;
          const receiverText = receiver.getText(sf);
          if (!/storage\s*$/.test(receiverText) && !/^Array$/.test(receiverText)) {
            let schema: string | null = null;
            if (ts.isCallExpression(receiver) && ts.isPropertyAccessExpression(receiver.expression) && receiver.expression.name.text === 'schema') {
              schema = stringArg(receiver);
            }
            (method === 'from' ? tables : rpcs).add(schema ? `${schema}.${target}` : target);
          }
        }
      }
    }
    const text = literalText(node);
    if (text !== null) {
      if (text.startsWith('/api/')) apiPaths.push(text.split('?')[0].replace(/\/+$/, ''));
      else if (ASSET_LITERAL.test(text) && publicAssets.has(`public${text}`)) assets.add(`public${text}`);
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);

  entry.imports = [...imports].sort();
  entry.packages = [...packages].sort();
  entry.assets = [...assets].sort();
  entry.tables = [...tables].sort();
  entry.rpcs = [...rpcs].sort();
  return { entry, apiPaths };
}

export function buildManifest(input: BuildInput): TechInsightsManifest {
  const known = new Set(input.files.map((f) => f.path));
  const publicAssets = new Set(input.publicAssets);
  const analysed = input.files
    .slice()
    .sort((a, b) => a.path.localeCompare(b.path))
    .map((f) => analyse(f, known, publicAssets));
  const files: Record<string, FileEntry> = Object.fromEntries(analysed.map((a) => [a.entry.path, a.entry]));

  // Routes, from the app/ directory conventions.
  const routes: RouteEntry[] = [];
  for (const { entry } of analysed) {
    if (entry.kind !== 'page' && entry.kind !== 'api-route') continue;
    const pattern = routeFromFilePath(entry.path);
    if (pattern === null) continue;
    const layouts: string[] = [];
    if (entry.kind === 'page') {
      const segments = dirname(entry.path).split('/');
      for (let i = 1; i <= segments.length; i++) {
        const layout = ['tsx', 'ts'].map((ext) => `${segments.slice(0, i).join('/')}/layout.${ext}`).find((p) => known.has(p));
        if (layout) layouts.push(layout);
      }
    }
    routes.push({
      pattern, kind: entry.kind === 'page' ? 'page' : 'api', file: entry.path, layouts,
      methods: entry.kind === 'api-route' ? entry.exports.map((e) => e.name).filter((n) => HTTP_METHODS.has(n)) : [],
    });
  }
  routes.sort((a, b) => a.pattern.localeCompare(b.pattern));

  // Resolve literal '/api/…' strings to the route files that serve them.
  const apiRoutes = routes.filter((r) => r.kind === 'api');
  for (const { entry, apiPaths } of analysed) {
    const resolved = new Set<string>();
    const unresolved = new Set<string>();
    for (const p of apiPaths) {
      const hit = matchRoute(p, apiRoutes, 'api');
      if (hit) resolved.add(hit.file);
      else unresolved.add(p);
    }
    entry.apiRoutes = [...resolved].sort();
    entry.apiUnresolved = [...unresolved].sort();
  }

  // Reverse edges.
  for (const entry of Object.values(files)) {
    for (const target of entry.imports) {
      const t = files[target];
      if (!t) continue;
      t.importedBy.push(entry.path);
      if (entry.kind === 'test') t.tests.push(entry.path);
    }
  }
  for (const entry of Object.values(files)) {
    entry.importedBy.sort();
    entry.tests.sort();
  }

  return { version: 1, generatedAt: input.generatedAt, commit: input.commit, routes, files };
}

lib/techInsights/client.ts:
import { supabase } from '@/lib/supabaseClient';
import type { TechInsightsManifest } from './types';

async function authedGet(url: string): Promise<Record<string, unknown>> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error('Not signed in');
  const res = await fetch(url, { headers: { Authorization: `Bearer ${session.access_token}` } });
  const json = await res.json().catch(() => ({})) as Record<string, unknown>;
  if (!res.ok) throw new Error((json.error as string | undefined) || `Request failed (${res.status})`);
  return json;
}

/** Browser-side call to GET /api/admin/tech-insights. Throws with the server's message on failure. */
export async function fetchTechInsightsManifest(): Promise<TechInsightsManifest> {
  return (await authedGet('/api/admin/tech-insights')).manifest as TechInsightsManifest;
}

export async function fetchTechInsightsSource(path: string): Promise<string> {
  return (await authedGet(`/api/admin/tech-insights?file=${encodeURIComponent(path)}`)).source as string;
}

lib/techInsights/domScan.ts:
/**
 * Tech Insights — finding the components currently on screen. Components opt in
 * by carrying `data-ti="<repo-relative file path>"` on their root element
 * (attribute only: no wrapper, no extra render). The value is a path into the
 * manifest, so it survives minification; a test (tagsMatchSourceFiles) keeps
 * every tag pointing at its own file.
 */

export const TAG_ATTRIBUTE = 'data-ti';

export interface VisibleTag {
  /** Manifest path the tag names. */
  path: string;
  /** Every element currently carrying it, in document order. */
  elements: Element[];
}

/** Tagged elements under `root`, grouped by path in order of first appearance; paths the manifest does not know are dropped. */
export function scanVisibleTags(root: ParentNode, isKnown: (path: string) => boolean): VisibleTag[] {
  const byPath = new Map<string, Element[]>();
  for (const el of root.querySelectorAll(`[${TAG_ATTRIBUTE}]`)) {
    const path = el.getAttribute(TAG_ATTRIBUTE);
    if (!path || !isKnown(path)) continue;
    const list = byPath.get(path);
    if (list) list.push(el); else byPath.set(path, [el]);
  }
  return [...byPath].map(([path, elements]) => ({ path, elements }));
}

/** Tags of `el` and its ancestors, outermost first — "this screen's <MobileLayout> > <CampaignCard> > …". Consecutive repeats collapse. */
export function tagChain(el: Element): string[] {
  const chain: string[] = [];
  for (let cur: Element | null = el; cur; cur = cur.parentElement) {
    const path = cur.getAttribute(TAG_ATTRIBUTE);
    if (path && chain[0] !== path) chain.unshift(path);
  }
  return chain;
}

/** The nearest tagged element at or above `target`, or null. */
export function closestTagged(target: EventTarget | null): Element | null {
  return target instanceof Element ? target.closest(`[${TAG_ATTRIBUTE}]`) : null;
}

lib/techInsights/graph.ts:
/**
 * Tech Insights — walking the manifest's dependency graph from a page.
 * Edges are imports plus literal API calls (page → fetch('/api/x') → route file),
 * so "what does this screen ultimately touch" follows data through the server.
 * Test files are never followed.
 */
import type { FileEntry, FileKind, TechInsightsManifest } from './types';

export interface Reach {
  /** file → the file it was first reached from (null for a starting point). */
  parent: Map<string, string | null>;
  /** BFS order, starting points first. */
  order: string[];
}

export function computeReach(roots: readonly string[], manifest: TechInsightsManifest): Reach {
  const parent = new Map<string, string | null>();
  const order: string[] = [];
  const queue: string[] = [];
  for (const r of roots) {
    if (manifest.files[r] && !parent.has(r)) { parent.set(r, null); order.push(r); queue.push(r); }
  }
  while (queue.length > 0) {
    const current = queue.shift() as string;
    const entry = manifest.files[current];
    for (const next of [...entry.imports, ...entry.apiRoutes]) {
      const target = manifest.files[next];
      if (!target || target.kind === 'test' || parent.has(next)) continue;
      parent.set(next, current);
      order.push(next);
      queue.push(next);
    }
  }
  return { parent, order };
}

/** Shortest chain of files from a starting point to `target`, or [] if unreachable. */
export function pathTo(reach: Reach, target: string): string[] {
  if (!reach.parent.has(target)) return [];
  const chain: string[] = [];
  for (let cur: string | null = target; cur !== null; cur = reach.parent.get(cur) ?? null) chain.unshift(cur);
  return chain;
}

export interface DataSummary {
  tables: string[];
  rpcs: string[];
  apiRoutes: string[];
  assets: string[];
  packages: string[];
}

export function summariseReach(reach: Reach, manifest: TechInsightsManifest): DataSummary {
  const sets = { tables: new Set<string>(), rpcs: new Set<string>(), apiRoutes: new Set<string>(), assets: new Set<string>(), packages: new Set<string>() };
  for (const path of reach.order) {
    const f = manifest.files[path];
    f.tables.forEach((t) => sets.tables.add(t));
    f.rpcs.forEach((t) => sets.rpcs.add(t));
    f.apiRoutes.forEach((t) => sets.apiRoutes.add(t));
    f.assets.forEach((t) => sets.assets.add(t));
    f.packages.forEach((t) => sets.packages.add(t));
  }
  const sorted = (s: Set<string>) => [...s].sort();
  return { tables: sorted(sets.tables), rpcs: sorted(sets.rpcs), apiRoutes: sorted(sets.apiRoutes), assets: sorted(sets.assets), packages: sorted(sets.packages) };
}

export const KIND_LABELS: Record<FileKind, string> = {
  page: 'Pages', layout: 'Layouts', 'api-route': 'API routes', component: 'Components', service: 'Services',
  lib: 'Libraries', context: 'Contexts', middleware: 'Middleware', test: 'Tests', style: 'Styles', other: 'Other',
};

export const KIND_SINGULAR: Record<FileKind, string> = {
  page: 'Page', layout: 'Layout', 'api-route': 'API route', component: 'Component', service: 'Service',
  lib: 'Library', context: 'Context', middleware: 'Middleware', test: 'Test', style: 'Style', other: 'Other',
};

const KIND_ORDER: FileKind[] = ['page', 'layout', 'component', 'context', 'service', 'lib', 'api-route', 'middleware', 'style', 'other', 'test'];

/** Reached files grouped by kind, in a stable display order. */
export function groupByKind(paths: readonly string[], files: Record<string, FileEntry>): Array<{ kind: FileKind; label: string; paths: string[] }> {
  return KIND_ORDER
    .map((kind) => ({ kind, label: KIND_LABELS[kind], paths: paths.filter((p) => files[p]?.kind === kind).sort() }))
    .filter((g) => g.paths.length > 0);
}

lib/techInsights/hotkey.ts:
/**
 * Tech Insights — the configurable keyboard shortcut. Stored as a canonical
 * string such as 'Ctrl+Alt+I' (modifier order: Ctrl, Alt, Shift, Meta).
 */
export const DEFAULT_TECH_INSIGHTS_HOTKEY = 'Ctrl+Alt+I';

export interface ParsedHotkey { ctrl: boolean; alt: boolean; shift: boolean; meta: boolean; key: string }

/** The slice of KeyboardEvent we read — lets tests pass plain objects. */
export interface HotkeyEventLike { code: string; key: string; ctrlKey: boolean; altKey: boolean; shiftKey: boolean; metaKey: boolean }

const KEY_PATTERN = /^([A-Z]|[0-9]|F([1-9]|1[0-2]))$/;

/** Parses 'Ctrl+Alt+I'. Needs at least one of Ctrl/Alt/Meta (Shift alone would clash with typing) and exactly one key (A–Z, 0–9, F1–F12). */
export function parseHotkey(value: string): ParsedHotkey | null {
  const parts = value.split('+').map((p) => p.trim());
  if (parts.length < 2 || parts.some((p) => !p)) return null;
  const key = parts[parts.length - 1].toUpperCase();
  if (!KEY_PATTERN.test(key)) return null;
  const mods = new Set(parts.slice(0, -1).map((p) => p.toLowerCase()));
  const known = new Set(['ctrl', 'alt', 'shift', 'meta']);
  if (mods.size !== parts.length - 1 || [...mods].some((m) => !known.has(m))) return null;
  if (!mods.has('ctrl') && !mods.has('alt') && !mods.has('meta')) return null;
  return { ctrl: mods.has('ctrl'), alt: mods.has('alt'), shift: mods.has('shift'), meta: mods.has('meta'), key };
}

export function formatHotkey(h: ParsedHotkey): string {
  return [h.ctrl && 'Ctrl', h.alt && 'Alt', h.shift && 'Shift', h.meta && 'Meta', h.key].filter(Boolean).join('+');
}

/** Canonical form of a valid hotkey string, or null. */
export function normalizeHotkey(value: string): string | null {
  const parsed = parseHotkey(value);
  return parsed ? formatHotkey(parsed) : null;
}

function eventKey(e: HotkeyEventLike): string | null {
  if (/^Key[A-Z]$/.test(e.code)) return e.code.slice(3);
  if (/^Digit[0-9]$/.test(e.code)) return e.code.slice(5);
  if (/^F([1-9]|1[0-2])$/.test(e.key)) return e.key;
  return null;
}

/** Uses e.code (physical key) for letters/digits so Alt/Option combos and non-QWERTY layouts still match. */
export function matchesHotkey(e: HotkeyEventLike, hotkey: ParsedHotkey): boolean {
  return e.ctrlKey === hotkey.ctrl && e.altKey === hotkey.alt && e.shiftKey === hotkey.shift
    && e.metaKey === hotkey.meta && eventKey(e) === hotkey.key;
}

/** For the admin "press the keys" box: the hotkey string a key press represents, or null if it isn't a valid combination. */
export function hotkeyFromEvent(e: HotkeyEventLike): string | null {
  const key = eventKey(e);
  if (!key) return null;
  return normalizeHotkey([e.ctrlKey && 'Ctrl', e.altKey && 'Alt', e.shiftKey && 'Shift', e.metaKey && 'Meta', key].filter(Boolean).join('+'));
}

lib/techInsights/manifestStore.ts:
/**
 * Tech Insights — server-side access to the generated manifest and sources
 * (scripts/build-tech-insights.ts). Read from disk lazily and cached for the
 * life of the server instance. The route that serves these is next.config.ts's
 * outputFileTracingIncludes entry's counterpart: without it Vercel would not
 * ship the generated files with the function.
 */
import fs from 'fs';
import path from 'path';
import type { TechInsightsManifest, TechInsightsSources } from './types';

const DIR = path.join(process.cwd(), 'generated', 'tech-insights');

let manifestCache: TechInsightsManifest | null = null;
let sourcesCache: TechInsightsSources | null = null;

function readJson<T>(name: string): T | null {
  try {
    return JSON.parse(fs.readFileSync(path.join(DIR, name), 'utf8')) as T;
  } catch {
    return null;
  }
}

/** null when the generator hasn't been run (run `npm run tech-insights`). */
export function loadManifest(): TechInsightsManifest | null {
  manifestCache ??= readJson<TechInsightsManifest>('manifest.json');
  return manifestCache;
}

/** Source text for a path the manifest knows about; arbitrary paths are never read from disk. */
export function loadSource(filePath: string): string | null {
  sourcesCache ??= readJson<TechInsightsSources>('sources.json');
  if (!sourcesCache || !Object.prototype.hasOwnProperty.call(sourcesCache, filePath)) return null;
  return sourcesCache[filePath];
}

lib/techInsights/routeMatch.ts:
/**
 * Tech Insights — mapping between URLs and Next.js App Router files, and back.
 */
import type { RouteEntry } from './types';

/** 'app/admin/state-leaders/page.tsx' → '/admin/state-leaders'; null if not a route file. */
export function routeFromFilePath(path: string): string | null {
  const m = /^app\/(.*?)\/?(page\.tsx?|route\.ts)$/.exec(path);
  if (!m) return null;
  const segments = m[1].split('/').filter((s) => s && !/^\(.*\)$/.test(s) && !s.startsWith('@'));
  return `/${segments.join('/')}`;
}

function scoreSegment(pattern: string, actual: string): number | null {
  if (/^\[\[?\.\.\./.test(pattern)) return 1;
  if (/^\[.+\]$/.test(pattern)) return 2;
  return pattern === actual ? 3 : null;
}

/**
 * Finds the page route serving a URL pathname: static segments beat dynamic
 * ones, which beat catch-alls. Returns null when nothing matches.
 */
export function matchRoute(pathname: string, routes: readonly RouteEntry[], kind: RouteEntry['kind'] = 'page'): RouteEntry | null {
  const actual = pathname.split('?')[0].split('#')[0].split('/').filter(Boolean);
  let best: { route: RouteEntry; score: number[] } | null = null;
  for (const route of routes) {
    if (route.kind !== kind) continue;
    const pattern = route.pattern.split('/').filter(Boolean);
    const score: number[] = [];
    let ok = true;
    let catchAll = false;
    for (let i = 0; i < pattern.length; i++) {
      if (/^\[\[?\.\.\./.test(pattern[i])) {
        // '[...x]' needs at least one segment here; '[[...x]]' may match none.
        if (actual.length <= i && !pattern[i].startsWith('[[')) ok = false;
        score.push(1);
        catchAll = true;
        break;
      }
      const s = i < actual.length ? scoreSegment(pattern[i], actual[i]) : null;
      if (s === null) { ok = false; break; }
      score.push(s);
    }
    if (ok && !catchAll && actual.length !== pattern.length) ok = false;
    if (!ok) continue;
    if (!best || compareScores(score, best.score) > 0) best = { route, score };
  }
  return best?.route ?? null;
}

function compareScores(a: number[], b: number[]): number {
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const d = (a[i] ?? 0) - (b[i] ?? 0);
    if (d !== 0) return d;
  }
  return 0;
}

