/**
 * Format validators for public-facing contact-detail forms (currently just
 * /public/register-interest, which requires a *valid* mobile number or
 * email rather than merely a non-empty one — see the PR that added this
 * file). Deliberately loose, not exhaustive RFC validators: just enough to
 * catch obviously-wrong input, since real deliverability is confirmed by
 * the leader following up, not by this check.
 */
import { normalizeMobile } from './auth';

/** True if the value, once normalized, is a plausible Australian mobile number (04XX XXX XXX). */
export function isValidMobile(value: string): boolean {
  return /^04\d{8}$/.test(normalizeMobile(value));
}

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** True if the value is a plausible email address (basic shape check). */
export function isValidEmail(value: string): boolean {
  return EMAIL_PATTERN.test(value.trim());
}

lib/weeklyRefresh.ts:
import { supabase } from './supabaseClient';

export interface LeaderNotSignedIn {
  id: string;
  state: string;
  leader: string;
  mobile: string | null;
  admin: string | null;
  last_sign_in_at: string | null;
}

/**
 * Get the completed_at timestamp of the most recent Weekly Refresh run.
 * Returns null if no refresh has been logged yet.
 */
export async function getLastWeeklyRefreshAt(): Promise<Date | null> {
  const { data, error } = await supabase
    .from('weekly_refresh_log')
    .select('completed_at')
    .order('completed_at', { ascending: false })
    .limit(1)
    .maybeSingle();

  if (error) {
    console.error('Error fetching last weekly refresh:', error);
    throw error;
  }

  return data?.completed_at ? new Date(data.completed_at) : null;
}

/**
 * Shared implementation for the two exports below. `state`, when given, is
 * pushed down to the query (`.eq('state', ...)`) rather than fetched for
 * every state and filtered in JS — the by-state variant only ever needs one
 * state's rows.
 */
async function fetchLeadersNotSignedInSinceRefresh(state?: string): Promise<{
  leaders: LeaderNotSignedIn[];
  lastRefreshAt: Date | null;
}> {
  const lastRefreshAt = await getLastWeeklyRefreshAt();

  let query = supabase
    .from('state_leaders')
    .select('id, state, leader, mobile, admin, last_sign_in_at')
    .order('state', { ascending: true })
    .order('leader', { ascending: true });
  if (state) query = query.eq('state', state);

  const { data, error } = await query;

  if (error) {
    console.error('Error fetching state leaders:', error);
    throw error;
  }

  const all = (data || []) as LeaderNotSignedIn[];

  const leaders = lastRefreshAt
    ? all.filter(
        (row) =>
          row.last_sign_in_at == null || new Date(row.last_sign_in_at) < lastRefreshAt
      )
    : all.filter((row) => row.last_sign_in_at == null);

  return { leaders, lastRefreshAt };
}

/**
 * Get leaders who have not signed in since the last Weekly Refresh.
 * If no refresh has been logged, returns all leaders who have never signed in (last_sign_in_at IS NULL).
 */
export async function getLeadersNotSignedInSinceRefresh(): Promise<{
  leaders: LeaderNotSignedIn[];
  lastRefreshAt: Date | null;
}> {
  return fetchLeadersNotSignedInSinceRefresh();
}

/**
 * Get leaders in a given state who have not signed in since the last Weekly Refresh.
 * For State Reporters to see their state only.
 */
export async function getLeadersNotSignedInSinceRefreshByState(state: string): Promise<{
  leaders: LeaderNotSignedIn[];
  lastRefreshAt: Date | null;
}> {
  const normalizedState = state?.toUpperCase().trim();
  if (!normalizedState) {
    return { leaders: [], lastRefreshAt: null };
  }
  return fetchLeadersNotSignedInSinceRefresh(normalizedState);
}

middleware.ts:
/**
 * Next.js Edge Middleware — route protection
 *
 * Redirects unauthenticated requests away from protected routes before they
 * reach any page component. The main app's check uses a session-indicator
 * cookie (app_session) that is set by lib/auth.ts after a successful
 * Supabase sign-in and cleared on sign-out. The independent /registry
 * portal (real Supabase Auth + MFA, see lib/registryAuth.ts) has its own
 * pair of cookies, deliberately separate from app_session so the two auth
 * systems can't interfere with each other.
 *
 * Important: none of these cookies are cryptographically signed — they are
 * UX-level redirect guards. Supabase Row-Level Security (and, for
 * /registry, registry.has_required_mfa()) is the enforced security
 * boundary for all data access. This middleware prevents casual
 * unauthenticated browsing and satisfies the audit requirement for
 * server-side route protection.
 *
 * A future migration to @supabase/ssr (cookie-based JWT sessions) would allow
 * this middleware to verify the JWT itself, replacing the indicator cookies.
 */
import { NextRequest, NextResponse } from 'next/server';

const PROTECTED_PREFIXES = ['/app', '/admin', '/capture', '/record-results', '/results', '/view-slides', '/training-interest', '/campaign-interest'];
const LOGIN_PATH = '/login';

// Note: `/public/*` (and its `/api/public/*` data routes) is intentionally
// NOT in PROTECTED_PREFIXES — those routes are meant to be reachable via a
// static link with no login. Each one is responsible for exposing only
// public-safe data server-side (see app/api/public/week1-campaigns/route.ts).

// Reachable with no session at all — the sign-in form, the magic-link
// exchange, and the terminal "you don't have access" page.
const REGISTRY_PUBLIC_PATHS = ['/registry/login', '/registry/auth/callback', '/registry/no-access'];
// Reachable with a session that exists but hasn't cleared the MFA gate yet
// (registry_auth, set right after the code exchange) — anyone further
// along also has registry_session, so this check alone is sufficient here.
const REGISTRY_PARTIAL_AUTH_PATHS = ['/registry/mfa/enroll', '/registry/mfa/challenge'];
const REGISTRY_LOGIN_PATH = '/registry/login';

function redirectTo(request: NextRequest, pathname: string) {
  const url = request.nextUrl.clone();
  url.pathname = pathname;
  url.search = '';
  return NextResponse.redirect(url);
}

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  if (pathname.startsWith('/registry')) {
    if (REGISTRY_PUBLIC_PATHS.some((p) => pathname === p || pathname.startsWith(`${p}/`))) {
      return NextResponse.next();
    }
    if (REGISTRY_PARTIAL_AUTH_PATHS.some((p) => pathname === p)) {
      return request.cookies.has('registry_auth') ? NextResponse.next() : redirectTo(request, REGISTRY_LOGIN_PATH);
    }
    // Every other /registry/* path needs the full, MFA-cleared session.
    return request.cookies.has('registry_session') ? NextResponse.next() : redirectTo(request, REGISTRY_LOGIN_PATH);
  }

  const isProtected = PROTECTED_PREFIXES.some((prefix) => pathname.startsWith(prefix));
  if (!isProtected) return NextResponse.next();

  const hasSession = request.cookies.has('app_session');
  if (hasSession) return NextResponse.next();

  // No session cookie — redirect to login, preserving intended destination
  return redirectTo(request, LOGIN_PATH);
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static  (static files)
     * - _next/image   (image optimisation)
     * - favicon.ico, public assets
     * - /login        (the login page itself)
     * - /api/auth/*   (auth API routes — must remain open)
     */
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:png|jpg|jpeg|gif|svg|ico)|login|api/auth).*)',
  ],
};
